import Foundation
let main: () = {
    let T = nextInt()
    var (n, a, b, c, d) = (0, 0, 0, 0, 0)
    var memo = [Int: Int]()
    func f(_ x: Int) -> Int {
        if x == 0 { return 0 }
        if memo[x] != nil { return memo[x]! }

        var res = Int.max
        let f2 = { (y: Int) -> Int in (y >= x) ? y * d : f(y) }
        block {
            let l = x / 2 * 2, r = l + 2
            res = min(res, f2(l / 2) + a + (x - l) * d)
            res = min(res, f2(r / 2) + a + (r - x) * d)
        }
        block {
            let l = x / 3 * 3, r = l + 3
            res = min(res, f2(l / 3) + b + (x - l) * d)
            res = min(res, f2(r / 3) + b + (r - x) * d)
        }
        block {
            let l = x / 5 * 5, r = l + 5
            res = min(res, f2(l / 5) + c + (x - l) * d)
            res = min(res, f2(r / 5) + c + (r - x) * d)
        }

        memo[x] = res
//print("\(x):\(res)")
        return res
    }

    repeate(T) { t in
        memo.removeAll()
        (n, a, b, c, d) = *listOfInt()
        print(f(n))
    }
}()


























