import Foundation
let main: () = {
    let T = nextInt()
    var (N, A, B, C, D) = (0, 0, 0, 0, 0)
    var memo = [Int: Int]()

    func solve(_ N: Int) -> Int {
        if N == 0 { return 0 }
        if N == 1 { return D }
        if memo[N] != nil { return memo[N]! }
        let l2 = (N / 2) * 2
        let r2 = ((N + 1) / 2) * 2
        let l3 = (N / 3) * 3
        let r3 = ((N + 2) / 3) * 3
        let l5 = (N / 5) * 5
        let r5 = ((N + 4) / 5) * 5

        var res = Int(1e18)
        if N < res / D { res = N * D }
        res = min(res, abs(l2 - N) * D + A + solve(l2 / 2))
        res = min(res, abs(r2 - N) * D + A + solve(r2 / 2))

        res = min(res, abs(l3 - N) * D + B + solve(l3 / 3))
        res = min(res, abs(r3 - N) * D + B + solve(r3 / 3))

        res = min(res, abs(l5 - N) * D + C + solve(l5 / 5))
        res = min(res, abs(r5 - N) * D + C + solve(r5 / 5))

        memo[N] = res

        return res
    }

    repeate(T) { t in
        memo.removeAll()
        (N, A, B, C, D) = *listOfInt()
        print(solve(N))
    }
}()





















