let main: () = {
    let T = nextInt()
    repeate(T) { t in
        let (N, a, b, c, d) = *listOfInt()
        var dfs = [Int: Int]()
        var Q = PriorityQueue<Int> { a, b in a < b }
        Q.push(N)
        while Q.count > 0 {
            let n = Q.pop()!
            Q.removeAll(n)
            let coin = dfs.getOrElse(n, {0})
            func push(_ d:Int, _ C: Int, _ s:String, _ f:Int = 0) {
                let m: Int, c:Int
                if (f == 0) {
                    var p = n
                    var q = 0
                    while p.isMultiple(of: d) {
                        q += 1
                        p /= d
                    }
                    m = n / (q * d)
                    c = C * q
                } else {
                    m = n + f
                    c = C
                }
                if let cn = dfs[m] {
                    if cn > coin + c {
                        dfs[m] = coin + c
                        if m != 0 { Q.push(m) }
                    }
                } else {
                    dfs[m] = coin + c
                    if m != 0 { Q.push(m) }
                }
//print("\(n):\(s) \(m):\(dfs.getOrElse(m, {0}))")
            }
            if n.isMultiple(of: 2) {
                push(2, a, "/2")
            }
            if n.isMultiple(of: 3) {
                push(3, b, "/3")
            }
            if n.isMultiple(of: 5) {
                push(5, c, "/5")
            }
            if n.isMultiple(of: 6) {
                push(6, a + b, "/2/3")
            }
            if n.isMultiple(of: 10) {
                push(10, a + c, "/2/5")
            }
            if n.isMultiple(of: 15) {
                push(15, b + c, "/3/5")
            }
            if n.isMultiple(of: 30) {
                push(30, a + b + c, "/2/3/5")
            }
            if n < N + 1 {
                push(1, d, "+1", +1)
            }
            if n > 0 {
                push(-1, d, "-1", -1)
            }
        }
        print(dfs[0]!)
    }
}()
