from heapq import heapify, heappop, heappush

def solve():
      input = sys.stdin.readline
      T = int(input())
      Ans = [0] * T
      for i in range(T):
            N, A, B, C, D = map(int, input().split())
            minPay = dict()
            minPay[0] = N * D
            q = []
            heapify(q)
            heappush(q, (0, N))
            while q:
                  cost, n = heappop(q)
                  if n not in minPay and n >= 0:
                        minPay[n] = cost
                        minPay[0] = min(minPay[0], cost + D * n)
                        if n % 2 == 0: heappush(q, (cost + A, n // 2))
                        else:
                              heappush(q, (cost + D, n + 1))
                              heappush(q, (cost + D, n - 1))
                        if n % 3 == 0: heappush(q, (cost + B, n // 3))
                        else:
                              m = n % 3
                              heappush(q, (cost + D * (3 - m), n + (3 - m)))
                              heappush(q, (cost + D * m, n - m))
                        if n % 5 == 0: heappush(q, (cost + C, n // 5))
                        else:
                              m = n % 5
                              heappush(q, (cost + D * (5 - m), n + (5 - m)))
                              heappush(q, (cost + D * m, n - m))
                  elif n == 0:
                        minPay[n] = min(minPay[n], cost)
                        break

            Ans[i] = minPay[0]

      print(*Ans, sep="\n")


      return 0

