int64_t GetAns(int64_t x, int state, int64_t limit = -1) {
    if (x <= 0) {
        return 0;
    }

    /*if (x < low_limit) {
        return x * d;
    }*/

    auto it = dp[state].find(x);
    if (it != dp[state].end()) {
        return it->second;
    }

    int64_t result = numeric_limits<int64_t>::max() / 2;
    if (result / x > d) {
        result = x * d;
    }

    if (state == 0) {
        for (int i = -4; i < 4; ++i) {
            if (x + i < limit) {
                result = min(result, d * abs(i) + GetAns(x + i, 1 - state));
            }
        }
    } else {
        if (x % 2 == 0) {
            result = min(result, a + GetAns(x / 2, 1 - state, x));
        }
        if (x % 3 == 0) {
            result = min(result, b + GetAns(x / 3, 1 - state, x));
        }
        if (x % 5 == 0) {
            result = min(result, c + GetAns(x / 5, 1 - state, x));
        }
    }

    dp[state][x] = result;
    return result;
}

