ll n;
int d,p[6];
unordered_map<ll,ll> M;

ll mul(ll a,ll b) {
	if((long double)a*b>Inf) return Inf;
	return a*b;
}

ll cal(ll n) {
	if(M.count(n)) return M[n];
	ll ret=mul(n,d);
	for(auto k:{2,3,5}) {
		ll t=(n+k-1)/k;if(t==n) continue;
		ret=min(ret,mul(k*t-n,d)+p[k]+cal(t));
		t=n/k;ret=min(ret,mul(n-k*t,d)+p[k]+cal(t));
	}
