LL a, b, c, d;

LL dp(LL n)
{
	if(n == 0)
		return 0;
	if(n == 1)
		return d;
	if(mp.count(n))
		return mp[n];
	int r2 = n % 2, r3 = n % 3, r5 = n % 5;
	LL& ans = mp[n];
	ans = dp((n - r2) / 2) + r2 * d + a;
	ans = min(ans, dp((n + (2 - r2) % 2) / 2) + ((2 - r2) % 2) * d + a);
	ans = min(ans, dp((n - r3) / 3) + r3 * d + b);
	ans = min(ans, dp((n + (3 - r3) % 3) / 3) + ((3 - r3) % 3) * d + b);
	ans = min(ans, dp((n - r5) / 5) + r5 * d + c);
	ans = min(ans, dp((n + (5 - r5) % 5) / 5) + ((5 - r5) % 5) * d + c);
	if(n <= ans / d)
		ans = min(ans, n * d);
	return ans;
}

