const long long INF = (1ll << 61);

long long f(long long n, long long A, long long B, long long C, long long D, map<long long, long long>& dp){
  if(n == 0ll) return 0;
  if(n == 1ll) return D;
  if(dp.count(n)) return dp[n];
  //cout<<n<<endl;
  long long ret = INF;
  if(n <= max({A, B, C})) ret = D * n;
  long long t;

  if(n > 2){
    ret = min(f(n / 3, A, B, C, D, dp) + B + D * (n % 3), ret);
  }
  ret = min(f(n / 3 + 1, A, B, C, D, dp) + B + D * (3ll - n % 3), ret);

  if(n > 4){
    ret = min(f(n / 5, A, B, C, D, dp) + C + D * (n % 5), ret);
  }
  ret = min(f(n / 5 + 1, A, B, C, D, dp) + C + D * (5ll - n % 5), ret);

  if(n > 1){
    t = f(n / 2, A, B, C, D, dp) + A;
    ret = min({t + D * (n % 2), t + D * (2ll - n % 2) + A, ret});
  }

  if(n > 2){
    t = f(n / 3, A, B, C, D, dp) + B;
    ret = min({t + D * (n % 3), t + D * (3ll - n % 3) + B, ret});
  }
  if(n > 4){
    t = f(n / 5, A, B, C, D, dp) + C;
    ret = min({t + D * (n % 5), t + D * (5ll - n % 5) + C, ret});
  }

  if(n > 3){
    t = f(n / 2 - 2, A, B, C, D, dp) + A;
    ret = min({t + D * (n % 2 + 2), ret});
  }
  if(n > 5){
    t = f(n / 3 - 3, A, B, C, D, dp) + B;
    ret = min({t + D * (n % 3 + 3), ret});
  }
  if(n > 9){
    t = f(n / 5 - 5, A, B, C, D, dp) + C;
    ret = min({t + D * (n % 5 + 5), ret});
  }

  return dp[n] = ret;
}

