using namespace std;

void solve() {
  int64_t n, a, b, c, d;
  cin >> n >> a >> b >> c >> d;
  int64_t ans = (a + d) * 60;
  using Entry = tuple<int64_t, int64_t>;
  priority_queue<Entry, vector<Entry>, greater<Entry>> q;
  unordered_map<int64_t, int64_t> vis;

  auto Add = [&](int64_t dis, int64_t val) {
    if (dis >= ans) return;
    if (vis.count(val) && vis[val] <= dis) return;
    vis[val] = dis;
    q.emplace(dis, val);
    auto tmp = (LLONG_MAX - dis) / d;
    if (val <= tmp)
      ans = min(ans, dis + val * d);
  };

  Add(0, n);
  while (q.size()) {
    auto entry = q.top(); q.pop();
    auto [dis, v] = entry;
    if (dis >= ans) {
      break;
    }
    for (auto x = v - 4; x <= v + 4; ++x) {
      if (x % 2 == 0 && abs(v - x) < 2) {
        Add(dis + abs(v - x) * d + a, x / 2);
      }
      if (x % 3 == 0 && abs(v - x) < 3) {
        Add(dis + abs(v - x) * d + b, x / 3);
      }
      if (x % 5 == 0 && abs(v - x) < 5) {
        Add(dis + abs(v - x) * d + c, x / 5);
      }
    }
  }
  cout << ans << endl;
}

