typedef ll mi;
typedef pair<mi, mi> mpi;

void solve(int ti) {
    mi n, a, b, c, d;
    re(n, a, b, c, d);
    map<mi, mi> modes = {{2, a},
                         {3, b},
                         {5, c}};//step, cost
    double maxeffi = 0;
    trav(x, modes) {
        ckmax(maxeffi, log2(x.first) / x.second);
    }
    //start from n
    //for increasing cost, explore reachable numbers
    //stop when reach 0
    priority_queue<mpi> pq;//format -cost,-position
    pq.emplace(0, -n);
    map<mi, mi> costdefined;
    set<mi> popped;
    auto pqem = [&, ti](mi cost, mi posi) {
        if (costdefined.count(cost) == 0) {
            costdefined[posi] = cost;
            pq.emplace(-cost, -posi);
//            cerr << posi << '@' << cost << endl;
        } else {
            if (ckmin(costdefined[posi], cost)) {
                pq.emplace(-cost, -posi);
//                cerr << posi << '@' << cost << endl;
            }
        }

    };
    while (not pq.empty()) {
        auto top = pq.top();
        pq.pop();
        mi cost = -top.first;//indicative
        mi position = -top.second;
        if(popped.count(position))
            continue;
        else
            popped.emplace(position);
//        cerr << position << '@' << cost << endl;
        if (position == 0) {
            cout << cost << endl;
            break;
        } else {
            double rough1 = ((double) position) * ((double) d);
//                double rough2 = log2(position) / maxeffi;
            if (rough1 <= (double) LLONG_MAX) {
                mi naivecost = cost + d * position;
                pqem(naivecost, 0);
            }
            trav(kv, modes) {
                mi mode = kv.first;
                mi margin = kv.second;
                mi modulo = position % mode;

                mi downcost = cost + margin + d * modulo;
                pqem(downcost, position / mode);

                mi upcost = cost + margin + d * (mode - modulo);
                pqem(upcost, (position + mode - modulo) / mode);
            }
        }
    }
}

