long long a, b, c, d;

unordered_map<long long, long long> mm;

long long rec(long long n)
{
	if (n == 1)
		return d;
	if (mm.find(n) != mm.end())
	{
		return mm[n];
	}
	long long ans = 3LL * 1e18;
	if (n < ans / d) ans = n * d;

	if (n >= 3)
	{
		long long rem3 = n % 3;
		if (rem3 < (3 - rem3))
			ans = min(ans, d * rem3 + b + rec(n / 3LL));
		else
			ans = min(ans, (3 - rem3) * d + b + rec(n / 3LL + 1LL));
	}

	if (n>=5)
	{
		long long rem5 = n % 5;
		if (rem5 < (5 - rem5))
			ans = min(ans, d * rem5 + c + rec(n / 5LL));
		else
			ans = min(ans, d * (5 - rem5) + c + rec(n / 5LL + 1LL));
	}

	if (1)
	{
		if (n % 2 == 0)
			ans = min(ans, a + rec(n / 2LL));
		else
		{
				ans = min(ans, d + a + rec((n + 1) / 2LL));
				ans = min(ans, d + a + rec((n) / 2LL));

		}
	}
	mm[n] = ans;
	return ans;
}

