    if (now % 5 == 0){
      ans = min(ans, Solve(now / 5) + C + abs(i) * D);
      ll deg = abs(now / 5 - num);
      if (deg <= Limit){
        ans = min(ans, Solve(now / 5) + deg * D);
      }
    }
    if (MP[now] > 0) ans = min(ans, MP[now] + abs(i) * D);
  }

  return MP[num] = ans;
}

