ll a,b,c,d;
ll rec(ll n){
  if(n == 0) return 0;
  if(n == 1) return d;
  if(mcount.count(n)) return mcount[n];

  ll u2 = (n+1)/2*2;
  ll l2 = n/2*2;
  ll u3 = (n+2)/3*3;
  ll l3 = n/3*3;
  ll u5 = (n+4)/5*5;
  ll l5 = n/5*5;

  ll ret;
  if(n < 1e18/d) ret = n*d;
  ret = min(ret,(u2-n)*d + a + rec((n+1)/2));
  ret = min(ret,(n-l2)*d + a + rec(l2/2));
  ret = min(ret,(u3-n)*d + b + rec(u3/3));
  ret = min(ret,(n-l3)*d + b + rec(l3/3));
  ret = min(ret,(u5-n)*d + c + rec(u5/5));
  ret = min(ret,(n-l5)*d + c + rec(l5/3));

  return mcount[n] = ret;

}

