int N, A, B, C, D;
map<int, int> memo;
void solve(int num, int cost)
{
    if (memo.count(num))
    {
        if (memo[num] <= cost)
            return;
        else
            memo[num] = cost;
    }
    else
        memo[num] = cost;

    if (num == 1)
    {
        if (memo.count(0))
            memo[0] = min(memo[0], cost + D);
        else
            memo[0] = cost + D;
        return;
    }

    int add;
    if (num % 2 == 0)
    {
        add = min(num / 2 * D, A);
        if (add <= 0)
            add = A;
        solve(num / 2, cost + add);
    }
    else
    {
        int tmp = num;
        while (true)
        {
            tmp++;
            if (tmp % 2 == 0)
            {
                add = min(abs(num - tmp / 2) * D, A + D * abs(num - tmp));
                if (add <= 0)
                    add = A + D * abs(num - tmp);
                solve(tmp / 2, cost + add);
                break;
            }
        }
        tmp = num;
        while (true)
        {
            tmp--;
            if (tmp % 2 == 0)
            {
                add = min(abs(num - tmp / 2) * D, A + D * abs(num - tmp));
                if (add <= 0)
                    add = A + D * abs(num - tmp);
                solve(tmp / 2, cost + add);
                break;
            }
        }
    }

    if (num % 3 == 0)
    {
        add = min(num / 3 * 2 * D, B);
        if (add <= 0)
            add = B;
        solve(num / 3, cost + add);
    }
    else
    {
        int tmp = num;
        while (true)
        {
            tmp++;
            if (tmp % 3 == 0)
            {
                add = min(abs(num - tmp / 3) * D, B + D * abs(num - tmp));
                if (add <= 0)
                    add = B + D * abs(num - tmp);
                solve(tmp / 3, cost + add);
                break;
            }
        }
        tmp = num;
        while (true)
        {
            tmp--;
            if (tmp % 3 == 0)
            {
                add = min(abs(num - tmp / 3) * D, B + D * abs(num - tmp));
                if (add <= 0)
                    add = B + D * abs(num - tmp);
                solve(tmp / 3, cost + add);
                break;
            }
        }
    }

    if (num % 5 == 0)
    {
        add = min(num / 5 * 4 * D, C);
        if (add <= 0)
            add = C;
        solve(num / 5, cost + add);
    }
    else
    {
        int tmp = num;
        while (true)
        {
            tmp++;
            if (tmp % 5 == 0)
            {
                add = min(abs(num - tmp / 5) * D, C + D * abs(num - tmp));
                if (add <= 0)
                    add = C + D * abs(num - tmp);
                solve(tmp / 5, cost + add);
                break;
            }
        }
        tmp = num;
        while (true)
        {
            tmp--;
            if (tmp % 5 == 0)
            {
                add = min(abs(num - tmp / 5) * D, C + D * abs(num - tmp));
                if (add <= 0)
                    add = C + D * abs(num - tmp);
                solve(tmp / 5, cost + add);
                break;
            }
        }
    }
}

