map<ll, ll> memo;
ll dfs(ll nowVal)
{
	ll amari1;
	ll amari2;

	if (memo.count(nowVal)) {
		return memo[nowVal];
	}

	ll ansCoin;
	if (D * nowVal < 0) {
		ansCoin = INF_LL;
	} else {
		ansCoin = D * nowVal;
	}
	for (auto one : vCoin) {
		ll div = one.first;
		ll add = one.second;
		amari1 = nowVal % div;
		amari2 = div - nowVal % div;

		ll nextVal = (nowVal - amari1) / div;
		ll nextCoin = amari1 * D;
		if (nextVal != 0) {
			nextCoin += add;
		}
		chmin(ansCoin, dfs(nextVal) + nextCoin);
		if (amari1 != 0) {
			nextVal = (nowVal + amari2) / div;
			nextCoin = amari2 * D + add;
			chmin(ansCoin, dfs(nextVal) + nextCoin);
		}
	}

	memo[nowVal] = ansCoin;
	return ansCoin;
}

