    cin >> N >> A >> B >> C >> D;
    save.clear();
    divisions.clear();

    for (int a = 0; a <= 60; a++)
        for (int b = 0; b <= 40; b++)
            for (int c = 0; c <= 30; c++)
                divisions.insert(evaluate(a, b, c));

    cout << solve(N) << '\n';
}

