        map<ll,ll> dp;
        dp[N]=0;

        // que.front() := 次の処理する整数
        queue<ll> que;
        que.push(N);

        // cout<<N<<endl;

        while(!que.empty()){
            ll v=que.front();que.pop();

            // 終了条件
            if(v==0)continue;

            bool ok=true;

            // 継続
            if(v%2==0){
                ll nv=v/2;

                if(dp.find(nv)==dp.end())dp[nv]=INF;
                if(dp[nv]>dp[v]+A){
                    que.push(nv);
                    dp[nv]=dp[v]+A;

                    // cout<<nv<<endl;
                }
            }//else ok=false;

            if(v%3==0){
                ll nv=v/3;

                if(dp.find(nv)==dp.end())dp[nv]=INF;
                if(dp[nv]>dp[v]+B){
                    que.push(nv);
                    dp[nv]=dp[v]+B;

                    // cout<<nv<<endl;
                }
            }else ok=false;

            if(v%5==0){
                ll nv=v/5;

                if(dp.find(nv)==dp.end())dp[nv]=INF;
