#define min min<ll>
ll N, A, B, C, D;
unordered_map<ll, ll>memo;


ll solve(ll n) { //nを0にするための最小コスト
    if(n == 0) return 0;
    if(n == 1) return D;
    if(memo[n] != 0) return memo[n];
    ll ret = 1e18;
    if(n < ret / D) ret = D * n;
    if(n % 2 == 0) {
        ret = min(ret, A + solve(n / 2));
    } else {
        ret = min(ret, A + D + solve(n / 2));
        ret = min(ret, A + D + solve((n + 1) / 2));
    }
    if(n % 3 == 0) {
        ret = min(ret, B + solve(n / 3));
    } else {
        ret = min(ret, B + (n % 3) * D + solve(n / 3));
        ret = min(ret, B + (3 - (n % 3)) * D + solve((n + 2) / 3));
    }
    if(n % 5 == 0) {
        ret = min(ret, C + solve(n / 5));
    }else {
        ret = min(ret, C + (n % 5) * D + solve(n / 5));
        ret = min(ret, C + (5 - (n % 5)) * D + solve((n + 4) / 5));
    }
    return memo[n] = ret;
}

