int A, B;
int C, D;

map<ll,ll>  memo;
vector<int> base = {2,3,5};

ll  calc(ll  n) {
    if (n == 0)         return  0;
    if (memo.count(n))  return  memo[n];

    ll &res = memo[n];  res = 1e18;

    for(int x : base)   {
        ll  v = n / x;
        int c;

        if (x == 2) c = A;
        if (x == 3) c = B;
        if (x == 5) c = C;
        if (v == 0) c = 0;

        res = min(res,calc(v) + c + (n - v * x) * D);   if (n % x)  v++;
        res = min(res,calc(v) + c + (v * x - n) * D);
    }
    return  res;
}

int main()  {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    int itest;
    cin >> itest;

    while (itest--) {
        ll  n;  cin >> n;   
        cin >> A >> B;
        cin >> C >> D;

        ll  ans = 0;

        for(ll  x = n ; x ;)    {
            if (x & 1)  ans += D;
            x >>= 1;    ans += A;
        }
        if (ans / n >= D)
            ans = n * D;

        cout << min(ans,calc(n)) << "\n";
        memo.clear();
    }
}

