    tmp = min(abs(n - l) * d, (n - 2LL * l) * d + a);
  }
  res = min(res, tmp + dfs(id, l));
  if (n % 2LL != 0) {
    r = l + 1LL;
    if (n > 1e9) {
      tmp = abs(n - 2LL * r) * d + a;
    } else {
      tmp = min((n - r) * d, abs(n - 2LL * r) * d + a);
    }
    res = min(res, tmp + dfs(id, r));
  }
  ///////////////3
  if (n >= 3LL) {
    l = n / 3LL;
    if (n > 1e9) {
      tmp = abs(n - 3LL * l) * d + b;
    } else {
      tmp = min((n - l) * d, (n - 3LL * l) * d + b);
    }
    res = min(res, tmp + dfs(id, l));
    if (n % 3LL != 0) {
      r = l + 1LL;
      if (n > 1e9) {
        tmp = abs(n - 3LL * r) * d + b;
      } else {
        tmp = min((n - r) * d, abs(n - 3LL * r) * d + b);
      }
      res = min(res, tmp + dfs(id, r));
    }
  }
  ///////////////5
  if (n >= 5LL) {
    l = n / 5LL;
    if (n > 1e9) {
      tmp = abs(n - 5LL * l) * d + c;
    } else {
      tmp = min((n - l) * d, (n - 5LL * l) * d + c);
    }
    res = min(res, tmp + dfs(id, l));
    if (n % 5LL != 0) {
      r = l + 1LL;
      if (n > 1e9) {
        tmp = abs(n - 5LL * r) * d + c;
      } else {
        tmp = min((n - r) * d, abs(n - 5LL * r) * d + c);
      }

      res = min(res, tmp + dfs(id, r));
    }
  }
  mp[n] = res;
  // cout << n << " " << res << endl;
  return mp[n] = res;
}
