ll N, A, B, C, D;
map<ll, ll> mp;

ll dfs(ll n, ll high, int operation) {
    if (mp.find(n) != mp.end()) return mp[n];

    ll res = n < 4e9 ? n * D : INT64_MAX;

    if (operation >> 0 & 1) {
        int op = operation;
        for (ll k = n, sum = 0; k > max(n - 15, 0LL); --k, sum += D) {
            if (k % 2 == 0 && op >> 2 & 1) {
                res = min(res, sum + A + dfs(k / 2, k / 2 + (n - k / 2 + 1) / 2, op));
                op &= ~(1 << 2);
            }
            if (k % 3 == 0 && op >> 3 & 1) {
                res = min(res, sum + B + dfs(k / 3, k / 3 + (n - k / 3 + 1) / 2, op));
                op &= ~(1 << 3);
            }
            if (k % 5 == 0 && op >> 4 & 1) {
                res = min(res, sum + C + dfs(k / 5, k / 5 + (n - k / 5 + 1) / 2, op));
                op &= ~(1 << 4);
            }
        }
    }
    if (operation >> 1 & 1) {
        int op = operation;
        for (ll k = n + 1, sum = D; k < min(n + 15, high); ++k, sum += D) {
            if (k % 2 == 0 && k / 2 < n && op >> 2 & 1) {
                res = min(res, sum + A + dfs(k / 2, k / 2 + (n - k / 2 + 1) / 2, op));
                op &= ~(1 << 2);
            }
            if (k % 3 == 0 && k / 3 < n && op >> 3 & 1) {
                res = min(res, sum + B + dfs(k / 3, k / 3 + (n - k / 3 + 1) / 2, op));
                op &= ~(1 << 3);
            }
            if (k % 5 == 0 && k / 5 < n && op >> 4 & 1) {
                res = min(res, sum + C + dfs(k / 5, k / 5 + (n - k / 5 + 1) / 2, op));
                op &= ~(1 << 4);
            }
        }
    }

    mp[n] = res;
    return res;
}

