ll work(ll x){
	if(!x) return 0;
	if(x == 1) return D;
	if(dp.count(x)) return dp[x];
	ll res = INF;
	if(res / D > x) res = x * D;
	if(x & 1){
		res = min(res, work((x-1)>>1) + A + D),
		res = min(res, work((x+1)>>1) + A + D);
	} else res = min(res, work(x>>1) + A);
	ll l = x - x % 3, r = x - x % 3 + 3;
	if(l != x){
		res = min(res, work(l/3) + B + (x - l) * D);
		res = min(res, work(r/3) + B + (r - x) * D);
	} else res = min(res, work(x/3) + B);
	l = x - x % 5; r = x - x % 5 + 5;
	if(l != x){
		res = min(res, work(l/5) + C + (x - l) * D);
		res = min(res, work(r/5) + C + (r - x) * D);
	} else res = min(res, work(x/5) + C);
	return dp[x] = res;
}
