map<long long, long long> m;
array<int,3> w = {2,3,5};
array<int,6> cost;

long long dfs(long long n) {
  assert(n>=0);
  if(m.count(n)) return m[n];
  long long r = 1LL << 60;
  for(auto i : w) {
    if(n%i) {
      long long minus = n % i;
      long long plus = i - (n % i);
      assert((n-minus) % i == 0);
      assert((n+plus) % i == 0);
      r = min(r, minus * D + cost[i] + dfs((n-minus)/i));
      r = min(r, plus  * D + cost[i] + dfs((n+plus)/i));
    }
    else {
      r = min(r, cost[i] + dfs(n/i));
    }
  }
  if((long double) D * (long double) n < r) r =n*D;
  return m[n] = r;
}

