ll A, B, C, D;

ll solve(ll N, unordered_map<ll, ll>& cache) {
    if (cache.count(N) > 0) {
        return cache[N];
    }
    if (N == 0) {
        cache[N] = 0;
        return cache[N];
    }
    if (N == 1) {
        cache[N] = D;
        return cache[N];
    }
    ll ans = min((__int128_t)N * (__int128_t)D, (__int128_t)LL_MAX);
    using P = pair<ll, ll>;
    for (P type : {P{2,A}, P{3,B}, P{5,C}}) {
        ll m = type.first;
        ll X = type.second;
        {
            ll cnt = N%m;
            ll M = (N - cnt) / m;
            ll ans_loc = X + cnt * D + solve(M, cache);
            chmin(ans, ans_loc);
        }
        {
            if (N % m != 0) {
                ll cnt = m - N%m;
                ll M = (N + cnt) / m;
                ll ans_loc = X + cnt * D + solve(M, cache);
                chmin(ans, ans_loc);
            }
        }
    }
    cache[N] = ans;
    return ans;
}

