map<lint, lint> mp;
lint N, A, B, C, D;
std::string ll2bitstr(long long x)
{
    std::string ret;
    while (x)
    {
        ret += x % 2 + '0', x /= 2;
    }
    std::reverse(ret.begin(), ret.end());
    return ret;
}
__int128 solve2(lint x)
{
    string s = ll2bitstr(x);
    int N = s.length() + 1;

    vector<lint> dp0(N, 4e18);
    vector<lint> dpk(N, 4e18);
    vector<lint> dpyo(N, 4e18);
    dp0[0] = 0;
    dp0[1] = D + A * (s.length() - 1);
    dpyo[0] = D + A * s.length();
    REP(i, s.length())
    {
        if (s[i] == '0')
        {
            dp0[i + 1] = min(dp0[i], dpk[i]);
            dpyo[i + 1] = dp0[i + 1] + D;
        }
        else
        {
            if (i != 0) chmin(dp0[i + 1], min({dp0[i] + D, dpk[i] + D}));
            dpk[i + 1] = min(dpk[i], dpyo[i] + D);
        }
    }
    // dbg(x);
    // dbg(s);
    // dbg(dp0);
    // dbg(dpk);
    // dbg(dpyo);
    lint ret = min(dp0.back(), dpk.back());
    if (__int128(x) * D < ret) ret = x * D;
    // dbg(ret);
    return ret;
}

lint rec(lint x)
{
    if (x == 0) return 0;
    if (x == 1) return D;
    if (mp.count(x)) return mp[x];
    __int128 ret = __int128(D) * x;
    {
        // use 2 only
        chmin(ret, solve2(x));
    }
    int mod3 = x % 3;
    chmin<__int128>(ret, rec(x / 3 + (mod3 >= 2)) + B + (mod3 > 0) * D);
    int mod5 = x % 5;
    chmin<__int128>(ret, rec(x / 5 + (mod5 >= 3)) + C + min(mod5, (5 - mod5) % 5) * D);
    mp[x] = ret;
    return ret;
}

void Sol()
{
    mp.clear();
    mp[0] = 0;
    cin >> N >> A >> B >> C >> D;
    lint ret = rec(N);
    cout << ret << '\n';
}

int main()
{
    int T;
    cin >> T;
    while (T--) Sol();
}

#include <bits/stdc++.h>
#define LL long long
using namespace std;

LL n,a,b,c,d,ans;

inline void upda(LL v){ if (v<0) return; if (ans == -1) ans = v; else ans = min(ans,v);  }
inline void upd(LL &ans,LL v){ if (v<0) return; if (ans == -1) ans = v; else ans = min(ans,v);  }
inline int Log(LL n,LL k){
	LL ret = 0,r = 1;
	while (n / r >= k) r *= k,++ret; ++ret;
	return ret;
}
inline LL solve(LL v){
	LL ans = 0;
	while (v%2==0) v/=2,ans+=a;
	while (v%3==0) v/=3,ans+=b;
	while (v%5==0) v/=5,ans+=c;
	if (v>1) return -1;
	return ans;
}
inline LL power(LL a,LL b){ static LL r; r=1; while (b){ if (b&1) r*=a; a*=a,b>>=1; } return r; }
int tmp[100];
inline LL DP(int n,int *a,int k){
	static LL v0,v1,t0,t1; static int i;
	v0 = 0,v1 = 1;
	for (int i = n; i >= 0; --i){
		t0 = t1 = -1;
		if (v0 > -1) upd(t0,v0 + a[i]),upd(t1,v0 + abs(a[i]+1));
		if (v1 > -1) upd(t0,v1 + abs(a[i]-k)),upd(t1,v1 + abs(a[i]+1-k));
		v0 = t0,v1 = t1;
	}
	if (t0 == -1) return ans;
	return t0;
}
map<LL,LL>mp;
inline void solve1(LL n,LL now){
	upda(n*d+now); if (n <= 1) return;
	if (ans != -1 && now >= ans) return;
	if (mp.count(n) && now >= mp[n]) return; mp[n] = now;
	if (n % 2 == 0) solve1(n/2,now+a); else solve1(n/2+1,now+d+a),solve1(n/2,now+d+a);
	if (n % 3 == 0) solve1(n/3,now+b); else solve1(n/3,now+d*(n%3)+b),solve1(n/3+1,now+d*(3-n%3)+b);
	if (n % 5 == 0) solve1(n/5,now+c); else solve1(n/5,now+d*(n%5)+c),solve1(n/5+1,now+d*(5-n%5)+c);
//	solve1(n+1,now+d),solve1(n-1,now+d);
	for (int i = -10; i <= 10; ++i){
		LL v = n + i; if (v < 0) continue;
		if (v % 2 == 0) solve1(v/2,now+a+d*abs(i));
		if (v % 3 == 0) solve1(v/3,now+b+d*abs(i));
		if (v % 5 == 0) solve1(v/5,now+c+d*abs(i));
	}
	if (n <= 1000){
		solve1(n-1,now+d);
	//	solve1(n+1,now-d);
	}
}
inline void solve(){
	int i,j;
	int l2,l3,l5;
	int v2,v3,v5;
	LL v,s,t;
	cin >> n >> a >> b >> c >> d; ans = -1; upda(n*d);
	for (i = 1; i <= 1000 && i <= n; ++i)
	for (s = i,j = -1000; j <= 1000; ++j){
		t = n + j; if (t <= 0 || t % s != 0) continue;
		v = solve(t/s); if (v == -1) continue; upda(d * (abs(j)+i) + v);
	}
	l2 = Log(n,2); upda(l2 * a + abs((1ll<<l2)-n) * d + d);
	l3 = Log(n,3); upda(l3 * b + abs(power(3,l3)-n) * d + d);
	l5 = Log(n,5); upda(l5 * c + abs(power(5,l5)-n) * d + d);
	for (v = 0,t = n,i = l2-1; i >= 0; --i) s = power(2,i),v += t / s,t %= s; if (!t) upda((l2-1) * a + d * v);
	for (v = 0,t = n,i = l3-1; i >= 0; --i) s = power(3,i),v += t / s,t %= s; if (!t) upda((l3-1) * b + d * v);
	for (v = 0,t = n,i = l5-1; i >= 0; --i) s = power(5,i),v += t / s,t %= s; if (!t) upda((l5-1) * c + d * v);

	for (v = 0,t = n,i = l2-1; i >= 0; --i) s = power(2,i),tmp[i] = t / s,t %= s; upda((l2-1)*a + DP(l2-1,tmp,2) * d);
	for (v = 0,t = n,i = l3-1; i >= 0; --i) s = power(3,i),tmp[i] = t / s,t %= s; upda((l3-1)*b + DP(l3-1,tmp,3) * d);
	for (v = 0,t = n,i = l5-1; i >= 0; --i) s = power(5,i),tmp[i] = t / s,t %= s; upda((l5-1)*c + DP(l5-1,tmp,5) * d);

	mp.clear();
	solve1(n,0);

	cout << ans << '\n';
}

int main(){
	int T; cin >> T;
	while (T--) solve();
	return 0;
}

#include <cstdio>
#include <algorithm>
#include <unordered_map>

typedef long long LL;
const LL Infll = 0x3f3f3f3f3f3f3f3f;

LL A, B, C, D;
std::unordered_map<LL, LL> mp;
LL f(LL x) {
	if (x == 0) return 0;
	if (x == 1) return D;
	if (mp.count(x)) return mp[x];
	LL ret = x <= Infll / D ? x * D : Infll;
	ret = std::min(ret, x % 2 * D + A + f(x / 2));
	ret = std::min(ret, x % 3 * D + B + f(x / 3));
	ret = std::min(ret, x % 5 * D + C + f(x / 5));
	if (x % 2) ret = std::min(ret, (2 - x % 2) * D + A + f(x / 2 + 1));
	if (x % 3) ret = std::min(ret, (3 - x % 3) * D + B + f(x / 3 + 1));
	if (x % 5) ret = std::min(ret, (5 - x % 5) * D + C + f(x / 5 + 1));
	return mp[x] = ret;
}

int main() {
	int Tests;
	scanf("%d", &Tests);
	while (Tests--) {
		LL N;
		scanf("%lld%lld%lld%lld%lld", &N, &A, &B, &C, &D);
		mp.clear();
		printf("%lld\n", f(N));
	}
	return 0;
}

