using namespace std;

ll a, b, c, d;
map <ll, ll> dp;

// nにたどり着くために必要なコスト
ll cost(ll n) {
    if (n == 0) {
        // if 0
        return 0;
    } else if (n == 1) {
        // if remaining step is to minus 1
        return d;
    } else if (n == 2) {
        // if remaining step is to minus 2 or divide 2 and minus 1
        return min(d * 2, a + d);
    } else if (dp.find(n) != dp.end()) {
        // if already calculated cost(n)
        return dp[n];
    }

    // 商を１増やすためには次の倍数にたどり着かせる
    // => (k - n % k) * d
    dp[n] = min({
            d * n,
            (n % 2) * d + a + cost(n / 2),
            (n % 3) * d + b + cost(n / 3),
            (n % 5) * d + c + cost(n / 5),
            (n % 2) ? (2 - n % 2) * d + a + cost(n / 2 + 1) : INF,
            (n % 3) ? (3 - n % 3) * d + b + cost(n / 3 + 1) : INF,
            (n % 5) ? (5 - n % 5) * d + c + cost(n / 5 + 1) : INF
    });
    return dp[n];
}

