        if (A / (double) diff > D) {
          pque.push(Node(node.n / 2, node.cost + diff * D));
        } else {
          pque.push(Node(node.n / 2, node.cost + A));
        }
      } else {
        ll d1 = node.n - (node.n - 1) / 2;

        if (A / (double) d1 > D) {
          pque.push(Node((node.n - 1) / 2, node.cost + d1 * D));
        } else {
          pque.push(Node((node.n - 1) / 2, node.cost + A + D));
