map<ll, ll> memo;

ll solve(ll n, ll a, ll b, ll c, ll d) {
  if(n == 0) return 0;
  if(n == 1) return d;
  if(memo.find(n) != memo.end()) {
    return memo[n];
  }

  ll res = LLONG_MAX;

  if(n % 2) {
    ll cost = a;
    if((n+1) / 2 < LLONG_MAX / d) chmin(cost, d * ((n+1)/2));
    chmin(res, solve((n+1)/2, a, b, c, d) + cost + d);
    cost = a;
    if((n-1)/2 < LLONG_MAX / d) chmin(cost, d * ((n-1)/2));
    chmin(res, solve((n-1)/2, a, b, c, d) + cost + d);
  } else {
    ll cost = a;
    if(n/2 < LLONG_MAX / d) chmin(cost, d * (n/2));
    res = solve(n/2, a, b, c, d) + cost;
  }

  if(n % 3) {
    ll tmpn = n;
    ll now = 0;
    while (tmpn % 3) {
      now += d;
      tmpn++;
    }
    ll cost = b;
    if((tmpn / 3) * 2 < LLONG_MAX / d) chmin(cost, d * (tmpn/3) * 2);
    chmin(res, solve(tmpn/3, a, b, c, d) + cost + now);
    tmpn = n;
    now = 0;
    while(tmpn % 3) {
      now += d;
      tmpn--;
    }
    cost = b;
    if((tmpn / 3) * 2 < LLONG_MAX / d) chmin(cost, d * (tmpn/3) * 2);
    chmin(res, solve(tmpn/3, a, b, c, d) + cost + now);
  } else {
    ll cost = b;
    if((n/3) * 2 < LLONG_MAX / d) chmin(cost, d * (n/3) * 2);
    chmin(res, solve(n/3, a, b, c, d) + b);
  }

  if(n % 5) {
    ll tmpn = n;
    ll now = 0;
    while (tmpn % 5) {
      now += d;
      tmpn++;
    }
    ll cost = c;
    if(tmpn / 5 * 4 < LLONG_MAX / d) chmin(cost, d * (tmpn / 5 * 4));
    chmin(res, solve(tmpn/5, a, b, c, d) + cost + now);
    tmpn = n;
    now = 0;
    while(tmpn % 5) {
      now += d;
      tmpn--;
    }
    cost = c;
    if(tmpn / 5 * 4 < LLONG_MAX / d) chmin(cost, d * (tmpn / 5 * 4));
    chmin(res, solve(tmpn/5, a, b, c, d) + c + now);
  } else {
    ll cost = c;
    if(n / 5 * 4 < LLONG_MAX / d) chmin(cost, d * (n / 5 * 4));
    chmin(res, solve(n/5, a, b, c, d) + c);
  }

  return memo[n] = res;
}

