ll a, b, c, d, n;

P f(mp::cpp_int prev_cost, ll prev_n,  ll base, bool increase) {
    ll next_n; mp::cpp_int cost;
    if(increase) {
        next_n = (prev_n + base - 1) / base;
        cost = prev_cost + mp::cpp_int(next_n * base - prev_n) * d;
    } else {
        next_n = prev_n / base;
        cost = prev_cost + mp::cpp_int(prev_n - next_n * base) * d;
    }
    if(next_n) cost += ((base==2)?a:((base==3)?b:c));
    return { cost, next_n };
}

void solve() {
