#include "bits/stdc++.h"

using namespace std;

void update(map<long long, long long>& minCoins, long long updated_n, long long coin) {
    if (minCoins.count(updated_n) == 0) {
        minCoins.insert(make_pair(updated_n, coin));
    }
    else {
        minCoins[updated_n] = min(minCoins[updated_n], coin);
    }
}

void solve(long long N, long long A, long long B, long long C, long long D) {
    map<long long, long long> minCoins;
    minCoins.insert(make_pair(1LL, D));
    if (A < D) {
        minCoins.insert(make_pair(2LL, A + D));
    }
    else {
        minCoins.insert(make_pair(2LL, 2 * D));
    }
    if (B < 2 * D) {
        minCoins.insert(make_pair(3LL, B + D));
    }
    else {
        minCoins.insert(make_pair(3LL, 3 * D));
    }
    if (C < 4 * D) {
        minCoins.insert(make_pair(5LL, C + D));
    }
    else {
        minCoins.insert(make_pair(5LL, 5 * D));
    }

    for (long long i = 0; i < 20; ++i) {
        for (auto e : minCoins) {
            long long na = e.first * 2;
            long long nb = e.first * 3;
            long long nc = e.first * 5;
            long long ndp = e.first + 1;
            long long ndm = e.first - 1;
            update(minCoins, na, e.second + A);
            update(minCoins, nb, e.second + B);
            update(minCoins, nc, e.second + C);
            update(minCoins, ndp, e.second + D);
            update(minCoins, ndm, e.second + D);
        }
    }

    long long ans = 0;
    if (minCoins.count(N) == 0) {
        ans = 0LL;
    }
    else {
        ans = minCoins[N];
    }
    cout << ans << endl;
}

void Main() {
    long long T;
    cin >> T;
    vector<long long> N(T, 0), A(T, 0), B(T, 0), C(T, 0), D(T, 0);
    for (long long i = 0; i < T; ++i) {
        cin >> N[i] >> A[i] >> B[i] >> C[i] >> D[i];
    }

    for (long long i = 0; i < T; ++i) {
        solve(N[i], A[i], B[i], C[i], D[i]);
    }
}

int main() {
    std::cout << std::fixed << std::setprecision(15);
    Main();
    return 0;
}

