const ll MOD = 1'000'000'007; // 998'244'353;

ll A, B, C, D;
map<ll, ll> memo;

ll rec(ll X) {
	if (memo.count(X)) return memo[X];
	ll res = INF;
	if (X % 2 == 0) chmin(res, A + rec(X / 2));
	else chmin(res, A + min(D + rec(X - 1), D + rec(X + 1)));
	if (X % 3 == 0) chmin(res, B + rec(X / 3));
	else {
		ll r = X % 3, s = 3 - r;
		chmin(res, B + min(D * r + rec((X - r) / 3), D * s + rec((X + s) / 3)));
	}
	if (X % 5 == 0) chmin(res, C + rec(X / 5));
	else {
		int r = X % 5, s = 5 - r;
		chmin(res, C + min(D * r + rec((X - r) / 5), D * s + rec((X + s) / 5)));
	}
	return memo[X] = res;
}

