LL N, A, B, C, D;

unordered_map<LL, LL> mem;
const LL INF = 1LL<<62;
LL LIMIT;

LL F(const LL n) {
    if (n == 0) return 0;
    if (n == 1) return D;

    auto it = mem.find(n);
    if (it != mem.end() && it->first == n) return it->second;

    LL tmp = INF;
    if (LIMIT > n) amin(tmp, n*D);

    LL x = (n+4) / 5;
    assert(x < n);

    if (LIMIT > abs(x*5-n)) {
	amin(tmp, F(x) + C + abs(x*5-n) * D);
    }
    x = n / 5;
    if (LIMIT > abs(x*5-n)) {
	amin(tmp, F(x) + C + abs(x*5-n) * D);
    }

    x = (n+2) / 3;
    assert(x < n);
    if (LIMIT > abs(x*3-n)) {
	amin(tmp, F(x) + B + abs(x*3-n) * D);
    }
    x = n / 3;
    if (LIMIT > abs(x*3-n)) {
	amin(tmp, F(x) + B + abs(x*3-n) * D);
    }

    x = (n+1) / 2;
    assert(x < n);
    if (LIMIT > abs(x*2-n)) {
	amin(tmp, F(x) + A + abs(x*2-n) * D);
    }
    x = n / 2;
    if (LIMIT > abs(x*2-n)) {
	amin(tmp, F(x) + A + abs(x*2-n) * D);
    }

    mem.insert(make_pair(n, tmp));
    return tmp;
}

void MAIN() {
    scanf("%lld%lld%lld%lld%lld", &N, &A, &B, &C, &D);

    mem.clear();

    LIMIT = INF / D;
    LL ans = F(N);

    printf("%lld\n", ans);
}

