namespace n91 {

u64 iabs(const i64 x) { return x < 0 ? -x : x; }

void solve() {
  const i64 n = scan<i64>();
  const u64 a = scan<u64>();
  const u64 b = scan<u64>();
  const u64 c = scan<u64>();
  const u64 d = scan<u64>();

  std::map<i64, u64> memo;
  memo[0] = 0;

  u64 ans = make_rec([a, b, c, d, &memo](const auto &f, const i64 n) -> i64 {
    {
      const auto itr = memo.find(n);
      if (itr != memo.end()) {
        return itr->second;
      }
    }

    u64 ret = std::numeric_limits<u64>::max();

    if (ret / d > iabs(n)) {
      ret = d * iabs(n);
    }

    // case 2
    {
      i64 rem = n % 2;
      if (rem < 0) {
        rem += 2;
      }
      chmin(ret, f((n - rem) / 2) + a + d * iabs(rem));
    }

    // case 3
    {
      i64 rem = n % 3;
      if (rem < 0) {
        rem += 3;
      }
      if (rem >= 2) {
        rem -= 3;
      }
      chmin(ret, f((n - rem) / 3) + b + d * iabs(rem));
    }

    // case 5
    {
      i64 rem = n % 5;
      if (rem < 0) {
        rem += 5;
      }
      if (rem >= 3) {
        rem -= 5;
      }
      chmin(ret, f((n - rem) / 5) + c + d * iabs(rem));
    }

    memo[n] = ret;

    return ret;
  })(n);

  std::cout << ans << eoln;
}

