ll use_coin[3];
ll mod[3] = {2,3,5};
const ll INF = INT64_MAX>>2;

ll dfs(ll k) {
    if(k == 0) return 0;
    if(k == 1) return d;
    if(memo.count(k) > 0) return memo[k];
    ll res = INF;
    if(k < INF/d) res = k*d;
    rep(i,3) {
        ll nk=  k/mod[i];
        ll nc = use_coin[i] + d*(k-nk*mod[i]);
        chmin(res, dfs(nk)+nc);
        nk =  (k+mod[i]-1)/mod[i];
        nc = use_coin[i] + d*(nk*mod[i]-k);
        chmin(res, dfs(nk)+nc);
    }
    return memo[k] = res;
}

