map<ll,ll> memo;

ll solve (ll N) {
  if (N == 0) return 0;
  else if (N == 1) return D;
  else if (memo[N] != 0) return memo[N];
  else {
    ll l2 = (N/2) * 2;
    ll r2 = ((N+1)/2) * 2;
    ll l3 = (N/3) * 3;
    ll r3 = ((N+2)/3) * 3;
    ll l5 = (N/5) * 5;
    ll r5 = ((N+4)/5) * 5;
    ll res = pow(10LL,18LL);
    if (N < res/D) res = N*D;
    res = min(res,solve(l2 / 2) + A + (abs(N-l2) * D));
    res = min(res,solve(l3 / 3) + B + (abs(N-l3) * D));
    res = min(res,solve(l5 / 5) + C + (abs(N-l5) * D));
    res = min(res,solve(r2 / 2) + A + (abs(N-r2) * D));
    res = min(res,solve(r3 / 3) + B + (abs(N-r3) * D));
    res = min(res,solve(r5 / 5) + C + (abs(N-r5) * D));
    memo[N] = res;
    return res;
   }
}


