        if ((x-a)/d < x) {
            f((x-a)/d, a * D + y + X);
            S.emplace((x-a)/d);
        }
        if ((x+b)/d < x) {
            f((x+b)/d, b * D + y + X);
            S.emplace((x+b)/d);
        }
    };
    constexpr long long inf = 2e18;
    long long ans = inf;
    while (!S.empty()) {
        long long x = *S.rbegin();
        S.erase(x);
        long long y = M[x];
        if (inf / D >= x) ans = min(ans, y + D * x);
        M.erase(x);
        g(x, y, 2, A);
