bool update(map<ll, ll>& mp, ll score, ll number) {
    if (mp.find(number) == mp.end()) {
        mp[number] = score;
        return true;
    }
    else {
        ll baseScore = mp[number];
        if (baseScore <= score) {
            return false;
        }
        else {
            mp[number] = score;
            return true;
        }
    }
}

int main()
{
    int T;
    cin >> T;
    rep(t, T) {
        ll N, A, B, C, D;
        cin >> N >> A >> B >> C >> D;
        priority_queue<pll, vector<pll>, greater<pll>> pq; // <score, number>
        map<ll, ll> mp; // number -> score
        pq.push({ 0,N });
        mp[N] = 0;
        while (true) {
            ll nowScore, nowNumber;
            tie(nowScore, nowNumber) = pq.top(); pq.pop();
            if (nowNumber == 0)break;
            if (mp.find(0) != mp.end()) {
                ll bestScore = mp[0];
                if (nowScore > bestScore)break;
            }

            // special case: use all D
            {
                if (log10(nowNumber) + log10(D) < 18.8) {
                    update(mp, nowScore + nowNumber * D, 0);
                }
            }

            // updater2
            if (nowNumber % 2 == 0) {
                ll nextNumber = nowNumber / 2;
                ll nextScore = nowScore + A;
                if (update(mp, nextScore, nextNumber)) {
                    pq.push({ nextScore,nextNumber });
                }
            }
            else {
                REP(nextNumber, nowNumber / 2, nowNumber / 2 + 2) {
                    ll timeD = abs(nextNumber * 2 - nowNumber);
                    ll nextScore = nowScore + D * timeD + (nextNumber == 0 ? 0 : A);
                    if (update(mp, nextScore, nextNumber)) {
                        pq.push({ nextScore,nextNumber });
                    }
                }
            }

            // updater3
            if (nowNumber % 3 == 0) {
                ll nextNumber = nowNumber / 3;
                ll nextScore = nowScore + B;
                if (update(mp, nextScore, nextNumber)) {
                    pq.push({ nextScore,nextNumber });
                }
            }
            else {
                REP(nextNumber, nowNumber / 3, nowNumber / 3 + 2) {
                    ll timeD = abs(nextNumber * 3 - nowNumber);
                    ll nextScore = nowScore + D * timeD + (nextNumber == 0 ? 0 : B);
                    if (update(mp, nextScore, nextNumber)) {
                        pq.push({ nextScore,nextNumber });
                    }
                }
            }

            // updater5
            if (nowNumber % 5 == 0) {
                ll nextNumber = nowNumber / 5;
                ll nextScore = nowScore + C;
                if (update(mp, nextScore, nextNumber)) {
                    pq.push({ nextScore,nextNumber });
                }
            }
            else {
                REP(nextNumber, nowNumber / 5, nowNumber / 5 + 2) {
                    ll timeD = abs(nextNumber * 5 - nowNumber);
                    ll nextScore = nowScore + D * timeD + (nextNumber == 0 ? 0 : C);
                    if (update(mp, nextScore, nextNumber)) {
                        pq.push({ nextScore,nextNumber });
                    }
                }
            }
        }
        cout << mp[0] << endl;
    }

    return 0;
}

