ll dv[3] = { 2, 3, 5 }, py[3], a, b, c, d;

ll solve(ll now)
{
	if (dp.count(now))
		return dp[now];

	ll ans = 1e18, i;

	if (ans / d >= now)
		ans = min(ans, now * d);

	for (i = 0; i < 3; i++)
	{
		ans = min(ans, now % dv[i] * d + solve(now / dv[i]) + py[i]);
		if (now / dv[i] + 1 < now)
			ans = min(ans, (dv[i] - now % dv[i]) * d + solve(now / dv[i] + 1) + py[i]);
	}

	return dp[now] = ans;
}

