void solve() {
  ll N, A, B, C, D; cin >> N >> A >> B >> C >> D;
  DLOG("N=", N, "A=", A);

  map<ll, ll> mp;
  using Pair = pair<ll, ll>;
  priority_queue<Pair, vector<Pair>, greater<Pair>> pq;
  pq.emplace(0, N);
  while (!pq.empty()) {
    DLOG("pq", pq);
    auto [d, v] = pq.top(); pq.pop();
    DLOG("popped d=", d, "v=", v);
    if (mp.find(v) != mp.end()) continue;
    DLOG("first");
    mp[v] = d;
    if (v == 0) {
      cout << d << "\n";
      return;
    }
    if (v == 1) {
      pq.emplace(d + D, 0);
    }
    if (v % 2 == 0) {
      ll vv = v / 2;
      ll dd = d + A;
      if (mp.find(vv) == mp.end() || mp[vv] > dd) pq.emplace(dd, vv);
    }else {
      ll vv = (v - 1) / 2;
      ll dd = d + D + A;
      if (mp.find(vv) == mp.end() || mp[vv] > dd) pq.emplace(dd, vv);
      vv = (v + 1) / 2;
      if (mp.find(vv) == mp.end() || mp[vv] > dd) pq.emplace(dd, vv);
    }
    {
      ll vd = 0;
      if (v % 3 == 0) vd = 0;
      else if (v % 3 == 1) vd = -1;
      else if (v % 3 == 2) vd = 1;
      ll vv = (v + vd) / 3;
      ll dd = d + abs(vd) * D + B;
      if (mp.find(vv) == mp.end() || mp[vv] > dd) pq.emplace(dd, vv);
    }
    {
      ll vd = 0;
      if (v % 5 == 0) vd = 0;
      else if (v % 5 == 1) vd = -1;
      else if (v % 5 == 2) vd = -2;
      else if (v % 5 == 3) vd = 2;
      else if (v % 5 == 4) vd = 1;
      ll vv = (v + vd) / 5;
      ll dd = d + abs(vd) * D + C;
      if (mp.find(vv) == mp.end() || mp[vv] > dd) pq.emplace(dd, vv);
    }
    {
      if (v < (LLONG_MAX - d) / D) {
	ll vv = 0;
	ll dd = d + v * D;
	if (mp.find(vv) == mp.end() || mp[vv] > dd) pq.emplace(dd, vv);
      }
    }
  }
  assert(0);
}

