using namespace std;

/*
N -> N-1 ~ N+1 で /2
    -> N-2 ~ N+2 で /3
	-> N-4 ~ N+4 で /5
	-> 0まで-1
*/

void challenge(long long n, long long new_cost, queue<long long> *pq, map<long long, long long> *pcost)
{
	if ((*pcost)[n] != 0 && (*pcost)[n] <= new_cost)
	{
		return;
	}
	(*pcost)[n] = new_cost;
	if (n > 1)
	{
		(*pq).push(n);
		// cout << "cost[" << n << "]=" << new_cost << ", "
		// 	 << "push " << n << "\n";
	}
	return;
}

int main()
{
	//cin.tie(0);
	//ios::sync_with_stdio(false);
	int T;
	scanf("%d", &T);

	for (int i = 0; i < T; i++)
	{
		long long N, A, B, C, D;
		scanf("%lld %lld %lld %lld %lld", &N, &A, &B, &C, &D);
		map<long long, long long> cost;
		cost[N] = 1; //1多い.
		queue<long long> q;
		q.push(N);
		long long N_tmp;
		while (!q.empty())
		{
			N_tmp = q.front();
			// cout << "N_tmp=" << N_tmp << "\n";
			q.pop();
			if (N_tmp == 1)
			{
				cost[0] = cost[N_tmp] + D;
				continue;
			}
			challenge((N_tmp - N_tmp % 2) / 2, cost[N_tmp] + (N_tmp % 2) * D + A, &q, &cost);
			if (N_tmp % 2 != 0)
			{
				challenge((N_tmp - N_tmp % 2) / 2 + 1, cost[N_tmp] + (2 - (N_tmp % 2)) * D + A, &q, &cost);
			}
			challenge((N_tmp - N_tmp % 3) / 3, cost[N_tmp] + (N_tmp % 3) * D + B, &q, &cost);
			if (N_tmp % 3 != 0)
			{
				challenge((N_tmp - N_tmp % 3) / 3 + 1, cost[N_tmp] + (3 - (N_tmp % 3)) * D + B, &q, &cost);
			}
			challenge((N_tmp - N_tmp % 5) / 5, cost[N_tmp] + (N_tmp % 5) * D + C, &q, &cost);
			if (N_tmp % 5 != 0)
			{
				challenge((N_tmp - N_tmp % 5) / 5 + 1, cost[N_tmp] + (5 - (N_tmp % 5)) * D + C, &q, &cost);
			}
			// challenge(1, cost[N_tmp] + D * (N_tmp - 1), &q, &cost);
		}

		cost[0] = cost[1] + D;

		for (auto j : cost)
		{
			// cout << j.first << " " << j.second << "\n";
			if (j.first == 0)
			{
				continue;
			}
			if (cost[0] / D > j.first)
			{
				cost[0] = min(cost[0], j.second + j.first * D);
			}
		}

		cout << cost[0] - 1 << "\n"; //最後に1を引く.
	}

	return 0;
}

