#include <iostream>
#include <algorithm>
#include <set>
using namespace std;

typedef pair<long long, long long> pairll;

set<pairll> determined; 

long long coins(long long N, int A, int B, int C, int D){
    if(N == 0) return 0;
    if(N == 1) return D;

    auto itr = determined.lower_bound(pairll(N, 0));
    if((*itr).first == N)return (*itr).second;

    long long res;
    res = A + D * abs(N-N/2*2) + coins(N/2, A, B, C, D);
    res = min(res, A + D * abs((N+1)/2*2-N) + coins((N+1)/2, A, B, C, D));
    res = min(res, B + D * abs(N-N/3*3) + coins(N/3, A, B, C, D));
    res = min(res, B + D * abs((N+2)/3*3-N) + coins((N+2)/3, A, B, C, D));
    res = min(res, C + D * abs(N-N/5*5) + coins(N/5, A, B, C, D));
    res = min(res, C + D * abs((N+4)/5*5-N) + coins((N+4)/5, A, B, C, D));
    if(res/D >= N){
        res = N*D;
    }
    determined.insert(pairll(N, res));
    return res;
}

int main(void){
    int T, A, B, C, D;
    long long N;
    cin >> T;
    vector<long long> ans;
    for(int i=0; i<T; i++){
        cin >> N >> A >> B >> C >> D;
        determined.clear();
        ans.push_back(coins(N, A, B, C, D));
    }

    for(int i=0; i<T; i++){
        cout << ans[i] << endl;
    }

    return 0;
}

