void dpn(){
	for(register int i = 0;i <= n + 1;i++){
		if(i << 1 <= n + 1)dp[i<<1] = min(dp[i]+a,dp[i<<1]);
		if((i<<1) + i <= n+1)dp[(i<<1) + i] = min(dp[i]+b,dp[(i<<1) + i]);
		if((i<<2) + i <= n+1)dp[(i<<2) + i] = min(dp[i]+c,dp[(i<<2) + i]);
		dp[i + 1] = min(dp[i]+d,dp[i + 1]);
