long long MOD = 1000000007;

ll N, A, B, C, D;
ll calc(ll N){
    priority_queue<pair<ll,ll>, vector<pair<ll,ll>>, greater<pair<ll,ll>>> pque;
    pque.push(make_pair(0,N));
    map<ll,bool> m;
    while((int)pque.size()>0){
        ll cost, num;
        cost=pque.top().first;
        num=pque.top().second;
        pque.pop();
        if(m.count(num)){
            continue;
        }else{
            m[num]=true;
        }

        //cout << cost << ' ' << num << endl;
        if(num==0){
            return cost;
        }

        if(num%2+A/D+(A%D>0)<=(num-num/2)){
            pque.push(make_pair(cost+(num%2)*D+A,num/2));
        }else{
            pque.push(make_pair(cost+(num-num/2)*D,num/2));
        }

        if((2LL-(num%2))+A/D+(A%D>0)<=(num-num/2-1)){
            pque.push(make_pair(cost+(2LL-(num%2))*D+A,num/2+1));
        }else{
            pque.push(make_pair(cost+(num-num/2-1)*D,num/2+1));
        }

        if((num%3)+B/D+(B%D>0)<=(num-num/3)){
            pque.push(make_pair(cost+(num%3)*D+B,num/3));
        }else{
            pque.push(make_pair(cost+(num-num/3)*D,num/3));
        }

        if((3LL-(num%3))+B/D+(B%D>0)<=(num-num/3-1)){
            pque.push(make_pair(cost+(3LL-(num%3))*D+B,num/3+1));
        }else{
            pque.push(make_pair(cost+(num-num/3-1)*D,num/3+1));
        }

        if((num%5)+C/D+(C%D>0)<=(num-num/5)){
            pque.push(make_pair(cost+(num%5)*D+C,num/5));
        }else{
            pque.push(make_pair(cost+(num-num/5)*D,num/5));
        }

        if((5LL-(num%5))+C/D+(C%D>0)<=(num-num/5-1)){
            pque.push(make_pair(cost+(5LL-(num%5))*D+C,num/5+1));
        }else{
            pque.push(make_pair(cost+(num-num/5-1)*D,num/5+1));
        }

        if(num==1){
            pque.push(make_pair(cost+D,0));
        }
    }
}

int main(){
    int T;
    cin >> T;
    for(int i=0; i<T; i++){
        cin >> N >> A >> B >> C >> D;
        cout << calc(N) << endl;
    }
}

