        res = min(res, f2(l/2LL) + a + (x - l) * d);
        res = min(res, f2(r/2LL) + a + (r - x) * d);
    }
    {
        ll l = x / 3LL * 3LL, r = l + 3LL;
        res = min(res, f2(l/3LL) + b + (x - l) * d);
        res = min(res, f2(r/3LL) + b + (r - x) * d);
    }
    {
        ll l = x / 5LL * 5LL, r = l + 5LL;
        res = min(res, f2(l/5LL) + c + (x - l) * d);
        res = min(res, f2(r/5LL) + c + (r - x) * d);
    }
    return mem[x] = res;
}

