    rep(i, T)
    {
        rep(j, 5)
        {
            cin >> cases[i][j];
        }
    }
    Datas start = {1, 0, 0,0};
    q.push(start);
    q.emplace(start);

    rep(k,T){
        ans[k] = bfs(k);
    }
    rep(k,T){
        cout << ans[k] << endl;
    }
}

