long long dfs(long long x) {
    if (x == 0) return 0;
    if (x == 1) return d;
    if (mp.count(x))    return mp[x];
    long long res = INF;
    if (res / d > x)    res = d * x;
    long long L2 = x / 2 * 2, R2 = (x + 1) / 2 * 2;
    res = min(res, dfs(L2 / 2) + a + abs(x - L2) * d);
    res = min(res, dfs(R2 / 2) + a + abs(R2 - x) * d);

