    res = min(res, dfs(L3 / 3) + b + abs(x - L3) * d);
    res = min(res, dfs(R3 / 3) + b + abs(R3 - x) * d);

    long long L5 = x / 5 * 5, R5 = (x + 4) / 5 * 5;
    res = min(res, dfs(L5 / 5) + c + abs(x - L5) * d);
    res = min(res, dfs(R5 / 5) + c + abs(R5 - x) * d);

