struct node
{
	s64 val; 
	int x, y, z; 

	node(){}
	node(s64 v, int a, int b, int c):
		val(v), x(a), y(b), z(c) {}

	inline bool operator < (const node &rhs) const
	{
		return val > rhs.val; 
	}
	inline s64 calc() const
	{
		return x * a + y * b + z * c; 
	}
}p[MaxM]; 

// std::vector<int> d[MaxM]; 

template <class T>
inline T abs(T x)
{
	return x < 0 ? -x : x; 
}

inline s64 solve(int i, s64 n, const node &frm)
{
	if (i > m)
		return 0; 
	if (p[i].x > frm.x || p[i].y > frm.y || p[i].z > frm.z)
		return solve(i + 1, n, frm); 

	s64 cnt = n / p[i].val; 
	if (n - cnt * p[i].val <= (cnt + 1) * p[i].val - n)
		return solve(i + 1, n - cnt * p[i].val, p[i]) + cnt; 
	else
		return solve(i + 1, (cnt + 1) * p[i].val - n, p[i]) + cnt + 1; 
}

inline void work()
{
	ans = (s128)1e27; 
	read(n), read(a), read(b), read(c), read(d); 

	for (int i = 1; i <= m; ++i)
		if (p[i].val <= 2 * n && p[i].calc() < ans)
		{
			tense(ans, p[i].calc() + (s128)solve(i, n, p[i]) * d); 
		}

	putint(ans); 
	putchar('\n'); 
}

