struct my_hash {
    template<typename ...> using to_void = void;
    template<typename T, typename = void> struct is_container : false_type {};
    template<typename T> struct is_container<T, to_void<decltype(declval<T>().begin()), decltype(declval<T>().end())>> : true_type {};
    static const uint64_t FIXED_RANDOM;
    static uint64_t splitmix64(uint64_t x) { // http://xorshift.di.unimi.it/splitmix64.c
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }
    size_t operator()(uint64_t x) const { return splitmix64(x + FIXED_RANDOM); }
    template<typename T, typename U> size_t operator()(const pair<T, U>& x) const {
      size_t ret = operator()(x.first); return ((ret << 6) ^ (ret >> 15)) + operator()(x.second); }
    template<typename T, typename = typename enable_if<is_container<T>::value>::type > size_t operator()(const T& x) const {
      size_t ret = FIXED_RANDOM; for (auto c : x) { ret = ((ret << 6) ^ (ret >> 15)) + operator()(c); } return ret; }
    template<size_t i = 0, typename... Ts> size_t operator()(const tuple<Ts...>& x, size_t ret = FIXED_RANDOM) const {
      if constexpr(i < sizeof...(Ts)) return operator()<i + 1>(x, ((ret << 6) ^ (ret >> 15)) + operator()(get<i>(x))); else return ret; }
};
const uint64_t my_hash::FIXED_RANDOM = chrono::steady_clock::now().time_since_epoch().count() ^ (uint64_t) (make_unique<char>().get());
