    res = min(res, (3 - num % 3) * d + b + rec(div3_1 / 3));
    res = min(res, (5 - num % 5) * d + c + rec(div5_1 / 5));

    if (div2_2 >= 0) res = min(res, (num % 2) * d + a + rec(div2_2 / 2));
    if (div3_2 >= 0) res = min(res, (num % 3) * d + b + rec(div3_2 / 3));
    if (div5_2 >= 0) res = min(res, (num % 5) * d + c + rec(div5_2 / 5));

    return cache[num] = res;
}
