map<ll,ll> dp;
ll n,a,b,c,d;
ll run(ll n)
{
    if(n==1)
    {
        return 0;
    }
    if(n==0)
    {
        return (ll)(4e18);
    }
    if(dp.find(n)!=dp.end())
    {
        return dp[n];
    }
    ll ans=(ll)4e18;
    if(d<(ll)1e6 && n<(ll)1e12)
    {
        ans=min(ans,(n-1)*d);
    }
    if(n%2==0)
    {
        ans=min(ans,run(n/2)+a);
    }
    else
    {
        ans=min({ans,run((n-1)/2)+a+d,run((n+1)/2)+a+d});
    }
    if(n%3==0)
    {
        ans=min(ans,run(n/3)+b);
    }
    else if(n%3==1)
    {
        ans=min(ans,run((n-1)/3)+b+d);
    }
    else
    {
        ans=min(ans,run((n+1)/3)+b+d);
    }
    if(n%5==0)
    {
        ans=min(ans,run(n/5)+c);
    }
    else if(n%5==1)
    {
        ans=min(ans,run((n-1)/5)+c+d);
    }
    else if(n%5==2)
    {
        ans=min(ans,run((n-2)/5)+c+d+d);
    }
    else if(n%5==3)
    {
        ans=min(ans,run((n+2)/5)+c+d+d);
    }
    else
    {
        ans=min(ans,run((n+1)/5)+c+d);
    }
    dp[n]=ans;
    return ans;
}
