typedef pair<li, li> PI;

inline void solve() {
    li n, a, b, c, d;
    cin >> n >> a >> b >> c >> d;

    map<li, li> memo;

    // cost, pos
    priority_queue<PI> pq;

    auto try_push = [&](li cost, li prev, li prev_cost, li num) {
        if ((abs(prev - num)*d) / d == abs(prev - num) && prev_cost + abs(prev - num)*d >= 0) {
            cost = min(cost, prev_cost + abs(prev - num) * d);
        }
        if (memo.count(num) == 0 || memo[num] > cost) {
            pq.push({ -cost, num});
        }
    };
    pq.push({0, n});
    while (!pq.empty()) {
        li now = pq.top().S;
        li now_cost = -pq.top().F;
        pq.pop();
        if (memo.count(now) > 0 && memo[now] <= now_cost) {
            continue;
        }
        memo[now] = now_cost;
        {
            auto it = memo.find(now);
            if (it != memo.begin()) {
                auto prev = it;
                prev--;
                if (memo[now] > prev->S + d + abs(now - prev->F)) {
                    memo[now] = prev->S + d + abs(now - prev->F);
                }
            }
            auto next = it;
            next++;
            if (next != memo.end()) {
                if (memo[now] > next->S + d + abs(now - next->F)) {
                    memo[now] = next->S + d + abs(now - next->F);
                }
            }
        }
        //p2(now, now_cost);
        if (now == 0) {
            cout << now_cost << endl;
            return;
        }
        if (now == 1) {
            cout << now_cost + d << endl;
            return;
        }
        if (now % 2 == 0) {
            try_push(now_cost + a, now, now_cost, now / 2);
        } else {
            try_push(now_cost + a + d, now, now_cost,  now / 2);
            try_push(now_cost + a + d, now, now_cost,  now / 2 + 1);
        }
        if (now % 3 == 0) {
            try_push(now_cost + b, now, now_cost,  now / 3);
        } else {
            li amari = now % 3;
            try_push(now_cost + b + d * amari, now, now_cost,  now / 3);
            try_push(now_cost + b + d * (3 - amari), now, now_cost,  now / 3 + 1);
        }
        if (now % 5 == 0) {
            try_push(now_cost + c, now, now_cost,  now / 5);
        } else {
            li amari = now % 5;
            try_push(now_cost + c + d * amari, now, now_cost,  now / 5);
            try_push(now_cost + c + d * (5 - amari), now, now_cost,  now / 5 + 1);
        }
    }
}

int main() {
    li t;
    cin >> t;
    rep(i, t) {
        solve();
    }

    return 0;
}

