const ll INF = 1ll<<60;

#define FOR(i,a,b) for (ll i=(a);i<(ll)(b);++i)
#define REP(i,n) FOR(i,0,n)
#define ALL(v) (v).begin(),(v).end()

ll A, B, C, D;
map<ll, ll> ma;

ll solve_sub(ll N)
{
	if (N == 0) return 0;
	if (ma.count(N)) return ma[N];
	ll res;
	if (N <= 3e9) res = N*D;
	else res = INF;

	for (ll i = -1; i <= 1; ++i)
	{
		ll x = N + i;
		if (x < 0 || x % 2 != 0) continue;
		ll y = x/2;
		if (y < N)
			res = min(res, abs(i)*D + A + solve_sub(y));
	}
	for (ll i = -2; i <= 2; ++i)
	{
		ll x = N + i;
		if (x < 0 || x % 3 != 0) continue;
		ll y = x/3;
		if (y < N)
			res = min(res, abs(i)*D + B + solve_sub(y));
	}
	for (ll i = -4; i <= 4; ++i)
	{
		ll x = N + i;
		if (x < 0 || x % 5 != 0) continue;
		ll y = x/5;
		if (y < N)
			res = min(res, abs(i)*D + C + solve_sub(y));
	}

	return ma[N] = res;
}


ll solve()
{
	ll N; cin >> N;
	cin >> A >> B >> C >> D;
	ma.clear();
	return solve_sub(N);
}

