long long rec(long long n, long long x) {
    if (n == 0) return 0;
    if (memo.count(n)) return memo[n];
    long long res = n;
    for (int i = 0; i < 4; i++) {
        if (n < 0) {
            res = min(res, rec(n + 1, --x));
        } else if (i == 0) {
            res = min(res, rec(n - (x * 5), x * 5));
        } else if (i == 1) {
            res = min(res, rec(n - (x * 3), x * 3));
        } else if (i == 2) {
            res = min(res, rec(n - (x * 2), x * 2));
        } else if (i == 3) {
            res = min(res, rec(n - 1, ++x));
        }
    }
    memo[n] = res;
    return memo[n];
}

