const LLONG DFS(const LLONG n)
{
    auto itr = num2MinCostMap.find(n);
    if (itr != num2MinCostMap.end())
    {
        return itr->second;
    }
    LLONG minCost = log10(n) * log10(D) < 18.0 ? n * D : 9e18;
    for (int i = 0; i < 3; ++i)
    {
        LLONG k = ks[i];
        LLONG lower = n / k;
        LLONG upper = (n + k - 1) / k;
        minCost = min(minCost,
            min(DFS(lower) + costs[i] + llabs(n - lower * k) * D,
                DFS(upper) + costs[i] + llabs(n - upper * k) * D));
    }
    num2MinCostMap[n] = minCost;
    return minCost;
}

