    if(x%2==0)return min(d*x, a+res(x/2));
    else{
        if(x%4==1)return min(d*x, d+a+res((x-1)/2));
        else return min(d*x, d+a+res((x+1)/2));
        // return min(d*x, d+a+res((x-1)/2));
    }
}

void ask(int B, int C){
