unsigned long long cost(unsigned long long n) {
    if (n == 0) return 0;
    if (n == 1) return d;
    if (memo.find(n) != memo.end()) return memo[n];
    unsigned long long score = cost(n / 5) + c * (n >= 5) + d * (n % 5);
    if (n % 5 != 0) score = min(score, cost((n + 5) / 5) + c + d * (5 - n % 5));
    score = min(score, cost(n / 3) + b * (n >= 3) + d * (n % 3));
    if (n % 3 != 0) score = min(score, cost((n + 3) / 3) + b + d * (3 - n % 3));
    score = min(score, cost(n / 2) + a * (n >= 2) + d * (n % 2));
    if (n % 2 != 0) score = min(score, cost((n + 2) / 2) + a + d * (2 - n % 2));
    if (score / d > n) score = d * n;
    memo[n] = score;
    return score; 
}

