ld dijkstra(){
    dp.clear();
    while( !q.empty() ) q.pop();
    q.push({-1,n});
    dp[n] = 1;
    while( !q.empty() ){
        int u = q.top().s;
        ld w = -q.top().f;//db(u)
        q.pop();//db(w)
        if( u == 0 ) return w - 1;
        if( u % 2 == 0 ){
            if( dp[u/2] > dp[u] + min(a,u/2*d) || !dp[u/2] ){
                dp[u/2] = dp[u] + min(a,u/2*d);
                q.push({-dp[u/2],u/2});
            }
        }
        if( u % 3 == 0 ){
            if( dp[u/3] > dp[u] + min(b,u*2/3*d) || !dp[u/3] ){
                dp[u/3] = dp[u] + min(b,u*2/3*d);
                q.push({-dp[u/3],u/3});
            }
        }
        if( u % 5 == 0 ){
            if( dp[u/5] > dp[u] + min(c,u*4/5*d) || !dp[u/5] ){
                dp[u/5] = dp[u] + min(c,u*4/5*d);
                q.push({-dp[u/5],u/5});
            }
        }
        if( ( u % 2 || u % 3 ) || u % 5 ){
            if( dp[u-1] > dp[u] + d || !dp[u-1] ){
                dp[u-1] = dp[u] + d;
                q.push({-dp[u-1],u-1});
            }
            if( dp[u+1] > dp[u] + d || !dp[u+1] ){
                dp[u+1] = dp[u] + d;
                q.push({-dp[u+1],u+1});
            }
        }
    }
