    ll l = (n/2) * 2;
    ll r = ((n+1)/2) * 2;
    mn = min(mn, (n-l)*d + a + dfs(l/2));
    mn = min(mn, (r-n)*d + a + dfs(r/2));
    l = (n/3) * 3;
    r = ((n+2)/3) * 3;
