    for(int p = -4; p<= 4 ; p++){
        ll x = n + p;
        if(x%5 !=0 || x < 0) continue;
        ll y = x/5;
        if(y < n)
        ans = min(ans,abs(p)*d + c+ solve(y));
    }

    return mp[n] = ans ;
}

