#define chmin(x, a) do { x = min(x, a); } while(0)

using namespace std;

ll T, A, B, C, D;
map<ll, ll> memo;

ll f(ll N) {
  // cout << "N = " << N << endl;
  if (N == 0) {
    return 0;
  }

  auto it = memo.find(N);
  if (it != memo.end())
    return it->second;

  ll res = 1e18;
  if (N * D < res && N * D >= 0) // overflow 対策
    res = N * D;

  ll a = N % 2, b = N % 3, c = N % 5;

  if ((N - a)/2 < N) chmin(res,      a * D + A + f((N - a)/ 2));
  if ((N + a)/2 < N) chmin(res, (2 - a)* D + A + f((N + a)/ 2));

  if ((N - b)/3 < N) chmin(res,      b * D + B + f((N - b)/ 3));
  if ((N + b)/3 < N) chmin(res, (3 - b)* D + B + f((N + b)/ 3));

  if ((N - c)/5 < N) chmin(res,      c * D + C + f((N - c)/ 5));
  if ((N + c)/5 < N) chmin(res, (5 - c)* D + C + f((N + c)/ 5));

  return memo[N] = res;
}

