ll fast_exp(ll base, ll exp)
{
  ll res=1;
  while(exp>0)
    {
      if(exp%2==1) res=(res*base);
      base=(base*base);
      exp/=2;
    }
  return res;
}
ll compute( ll A)
{
    if(dp.find(A) == dp.end()) dp[A] = -1;
    if(dp[A]!= -1) return dp[A];
    ll ans = 1e18;
    ll cur ;
    // do 2
    if( A >= 2)
    {
        cur = llabs((A/2)*2 - A)*d + a + compute(A/2);
        ans = MIN2(ans, cur);
        if(A%2)
        {
            cur = llabs((A/2 + 1)*2 - A)*d + a + compute(A/2 + 1);
            ans = MIN2(ans, cur);
        }
    }
    if( A >= 3)
    {
        // do 3
        cur = llabs((A/3)*3 - A)*d + b + compute(A/3);
        ans = MIN2(ans, cur);
        if(A%3)
        {
            cur = llabs((A/3 + 1)*3 - A)*d + b + compute(A/3 + 1);
            ans = MIN2(ans, cur);
        }
    }
    // do 5
    if( A >= 5)
    {
        cur = llabs((A/5)*5 - A)*d + c+ compute(A/5);
        ans = MIN2(ans, cur);

        if(A%5)
        {
            cur = llabs((A/5 + 1)*5 - A)*d + c+ compute(A/5 + 1);
            ans = MIN2(ans, cur);
        }
    }
    // run down to 0 with just operation 'D'
    if(log2(A) + log2(d) < 61 )
            ans = MIN2(ans, A*d);
    return dp[A] = ans;
}
