map<ll,ll> dp;
ll dfs(ll x){ //x→0にかかる最小のコストを計算
    if(x==0) return 0;
    if(x==1) return d; //1以外のxは1で止まるので、1のときは別で用意しておかないと無限ループに。
    if(dp.count(x)==1) return dp[x]; //一度計算したことあったら、再度計算しない。

    ll cur=pow(10,18); //+-1のみをつかってx→0にするときのコスト
    if(x<=cur/d) cur=x*d; 

    ll r2=(x+1)/2*2;
    ll l2=x/2*2;
    ll r3=(x+2)/3*3;
    ll l3=x/3*3;
    ll r5=(x+4)/5*5;
    ll l5=x/5*5;
    cur=min(cur,(r2-x)*d+a+dfs(r2/2));
    cur=min(cur,(x-l2)*d+a+dfs(l2/2));
    cur=min(cur,(r3-x)*d+b+dfs(r3/3));
    cur=min(cur,(x-l3)*d+b+dfs(l3/3));
    cur=min(cur,(r5-x)*d+c+dfs(r5/5));
    cur=min(cur,(x-l5)*d+c+dfs(l5/5));
    dp[x]=cur;
    return cur;
}
