#include <bits/stdc++.h>
using namespace std;
#define rep(i, n) for (int i = 0; i < (int)(n); i++)
#define rep1(i, n) for (int i = 1; i <= (int)(n); i++)
typedef int64_t Int;

Int A, B, C, D;
map<Int,Int> m;

Int solve(Int N) {
    if (N == 0) return 0;
    if (N == 1) return D;
    if (m.count(N)) return m[N];

    Int l2 = (N/2)*2;
    Int r2 = ((N+1)/2)*2;

    Int l3 = (N/3)*3;
    Int r3 = ((N+1)/3)*3;

    Int l5 = (N/5)*5;
    Int r5 = ((N+1)/5)*5;

    Int res = 1e18;
    if (N < res/D) res = N * D;

    res = min(res, llabs(N-l2)*D + A + solve(l2/2));
    res = min(res, llabs(r2-N)*D + A + solve(r2/2));

    res = min(res, llabs(N-l3)*D + B + solve(l3/2));
    res = min(res, llabs(r3-N)*D + B + solve(r3/2));

    res = min(res, llabs(N-l5)*D + C + solve(l5/2));
    res = min(res, llabs(r5-N)*D + C + solve(r5/2));

    m[N] = res;

    return res;
}

int main() {
    int T; cin >> T;

    for (int t = 0; t < T; t++) {
        m.clear();
        Int N; cin >> N;
        cin >> A >> B >> C >> D;

        cout << solve(N) << endl;
    }

}

#include <bits/stdc++.h>

using namespace std;

#define INF 1e14
#define ll long long
ll n, a, b, c, d;
vector<ll> x;
vector<ll> co;
map<ll, ll> mp;
ll dp[7];

ll nows(ll x, ll inc)
{
    if(x == 1) return d;
    ll mins = INF;
    if(x%2 == 0) mins = min(mins, nows(x/2, inc)+a);
    if(x%3 == 0) mins = min(mins, nows(x/3, inc)+b);
    if(x%5 == 0) mins = min(mins, nows(x/5, inc)+c);
    mins = min(mins, nows(x-1, inc)+d);
    if(inc > 0) mins = min(mins, nows(x+1, inc-1)+d);
    return mins;
}

ll mul(ll a, ll b)
{
    if(a >= INF/b) return INF;
    return (a*b);
}

ll calc(ll n)
{
    if(n == 0) return INF;
    if(n == 1) return d;
    if(mp.find(n) != mp.end()) return mp[n];
    ll mins = mul(n, d);
    for(int i=0; i<x.size(); i++){
        ll p = x[i], cost = co[i];
        if(n%p == 0){
            ll newN = n/p;
            mins = min(mins, min(mul(n-newN, d), cost)+calc(newN));
        }
        else if(n < p){
            ll hi = p - n%p;
            ll newN = (n+hi)/p;
            mins = min(mins, min(mul(n-newN, d), cost)+calc(newN)+dp[hi]);
        }
        else {
            ll lo = n%p;
            ll hi = p - lo;
            ll newN1 = (n-lo)/p;
            mins = min(mins, min(mul(n-newN1, d), cost)+calc(newN1)+dp[lo]);
            ll newN2 = (n+hi)/p;
            mins = min(mins, min(mul(n-newN2, d), cost)+calc(newN2)+dp[hi]);
        }
    }
    //cout << n << " " << mins << endl;
    return mp[n] = mins;
}

int main()
{
    //freopen("in.txt", "r", stdin);
    int cases;
    scanf("%d", &cases);
    while(cases--){
        scanf("%lld %lld %lld %lld %lld", &n, &a, &b, &c, &d);
        for(int i=1; i<=6; i++){
            dp[i] = nows(i, 4);
        }
        x = {2, 3, 5};
        co = {a, b, c};
        ll ans = calc(n);
        cout << ans << endl;
        mp.clear();
    }
}

