int rec(int n){
	if(n == 0){
		return 0;
	}
	if(n == 1)
		return d;

	if(dp.find(n)!=dp.end())
		return dp[n];

	int l2 = (n/2)*2;
	int r2 = ((n+1)/2)*2;

	int l3 = (n/3)*3;
	int r3 = ((n+2)/3)*3;

	int l5 = (n/5)*5;
	int r5 = ((n+4)/5)*5;

	int ans = 1e18;
	if(n < ans/d) ans = n*d;

	ans = min(ans, llabs(l2-n)*d + a + rec(l2/2));
	ans = min(ans, llabs(r2-n)*d + a + rec(r2/2));

	ans = min(ans, llabs(l3-n)*d + b + rec(l3/3));
	ans = min(ans, llabs(r3-n)*d + b + rec(r3/3));

	ans = min(ans, llabs(l5-n)*d + c + rec(l5/5));
	ans = min(ans, llabs(r5-n)*d + c + rec(r5/5));

	dp[n] = ans;
	return ans;

}
