        return dp[N];
    }

    ll res = INF;

    if (D <= (INF + N - 1)/N){
        chmin(res, N * D);
    }
    if (N % 2 == 1){
        chmin(res, f(N/2) + A + D);
        chmin(res, f(N/2 + 1) + A + D);
    } else {
        chmin(res, f(N/2) + A);
    }
    if (1 || N%3 <= 1){
        chmin(res, f(N/3) + B + N%3 * D);
    //} else {
        chmin(res, f(N/3 + 1) + B + (3 - N%3) * D);
    }


    if (1 || N%5 <= 2){
        chmin(res, f(N/5) + C + N%5 * D);
    //} else {
        chmin(res, f(N/5 + 1) + C + (5 - N%5) * D);
    }
    //fprintf(stderr, "N = %d, res = %d\n", N, res);    
    return dp[N] = res;
}
int main() {
    int T;
    cin >> T;

    rep(i, T){
        dp.clear();
        cin >> N >> A >> B >> C >> D;
        cout << f(N) << endl;
        //exit(1);
    }    
    return 0;
}

