#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll zero = 0;
const ll INF = 3000000000000000000; //10^18
const ll MOD = 1000000007; //10^9+7
const ll MOD2 = 998244353;

ll N,A,B,C,D;
map<ll, ll> memo;

ll solve(ll now){
    if     (now == 0) return zero;
    else if(now == 1) return D;
    else if(now == 2) return min(2*D,A+D);
    if(memo.count(now)){
        return memo[now];
    }    

    memo[now/5] = solve(now/5);
    memo[now/5 + 1] = solve(now/5 + 1);
    memo[now/3] = solve(now/3);
    memo[now/3 + 1] = solve(now/3 + 1);
    memo[now/2] = solve(now/2);
    memo[now/2 + 1] = solve(now/2 + 1);

    ll ret = INF;
    ll mod5,mod3,mod2;
    mod5 = now % 5;
    mod3 = now % 3;
    mod2 = now % 2;

    ret = INF;
    if(INF / now <= D){
        ret = D*now;
    }    
    ret = min(ret, memo[now/5]     + C + mod5*D);
    ret = min(ret, memo[now/5 + 1] + C + (5-mod5)*D);
    ret = min(ret, memo[now/3]     + B + mod3*D);
    ret = min(ret, memo[now/3 + 1] + B + (3-mod3)*D);
    ret = min(ret, memo[now/2]     + A + mod2*D);
    ret = min(ret, memo[now/2 + 1] + A + (2-mod2)*D);

    return ret;
}

