ll rec(ll n, ll c2, ll c3, ll c5, ll c1, map<ll, ll> &memo) {
    if (memo.find(n) != memo.end()) return memo[n];

    if (n == 0) return 0;
    if (n == 1) return c1;

    auto t1 = [&](ll x, ll c) -> ll {
        ll target = n / x * x;
        ll one = (n - target) * c1;
        return rec(target / x, c2, c3, c5, c1, memo) + one + c;
    };


    auto t2 = [&](ll x, ll y) -> ll {
        if (n % x == 0) return INF;
        ll target = (n + x - 1) / x * x;
        assert(target > n);
        ll one = (target - n) * c1;
        return rec(target / x, c2, c3, c5, c1, memo) + one + y;
    };

    ll ans = n * c1;
    cmin(ans, t1(2, c2));
    cmin(ans, t1(3, c3));
    cmin(ans, t1(5, c5));
    cmin(ans, t2(2, c2));
    cmin(ans, t2(3, c3));
    cmin(ans, t2(5, c5));

    memo[n] = ans;
    return ans;

}

