	for( int i = 1; i < N; ++i ) {
		table[i] = table[i-1] + d;
		if( i % 2 == 0 )
			table[i] = min(table[i], table[i/2] + a);
		if( i % 3 == 0 )
			table[i] = min(table[i], table[i/3] + b);
		if( i % 5 == 0 )
			table[i] = min(table[i], table[i/5] + c);
	}
}

ll dp( ll n ) {
	// if( n < N ) return table[n];
	if( f.count(n) ) return f[n];
	ll &now = f[n];
	if( n == 0 ) return now = 0;
	now = INFLL;

	if( n % 2 ) {
		now = min(now, dp(n-n%2) + n%2*d);
		if( n/2+1 != n )
			now = min(now, dp(n/2+1) + (2-n%2)*d + a);
	} else {
		now = min(now, dp(n/2) + a);
		if( n/2 <= INF )
			now = min(now, dp(n/2) + n/2*d);
	}
	if( n % 3 ) {
		now = min(now, dp(n-n%3) + n%3*d);
		if( n/3+1 != n )
			now = min(now, dp(n/3+1) + (3-n%3)*d + b);
	} else {
		now = min(now, dp(n/3) + b);
		if( n/3*2 <= INF )
			now = min(now, dp(n/3) + n/3*2*d);
	}
	if( n % 5 ) {
		now = min(now, dp(n-n%5) + n%5*d);
		if( n/5+1 != n )
			now = min(now, dp(n/5+1) + (5-n%5)*d + c);
	} else {
		now = min(now, dp(n/5) + c);
		if( n/5*4 <= INF )
			now = min(now, dp(n/5) + n/5*4*d);
	}
	if( n <= INF )
		now = min(now, n*d);
	return now;
}

int main() {
	int T;
	cin >> T;
	while( T-- ) {
		cin >> n >> a >> b >> c >> d;
		calc_table();
		f.clear();
		cout << dp(n) << endl;
	}
	return 0;
}

