using namespace templates;

__int128_t func(){
  __int128_t n = in();
  __int128_t a = in();
  __int128_t b = in();
  __int128_t c = in();
  __int128_t d = in();
  map<__int128_t,__int128_t> m;
  m[n] = 0;

  auto func =
    [&](__int128_t x,__int128_t y){
      if(m.count(x)){
        chmin(m[x],y);
      }else{
        m[x] = y;
      }
    };

  while(m.size()){
    pair<__int128_t,__int128_t> current = *m.rbegin();
    m.erase(current.first);
    __int128_t x = current.first;
    __int128_t y = current.second;
    if(x==0)return y;
    func(0,y+d*x);
    if(x&1){
      func(x/2,y+a+d);
      if(x/2+1!=x){
        func(x/2+1,y+a+d);
      }
    }else{
      func(x/2,y+a);
    }
    if(x%3==0){
      func(x/3,y+b);
    }else{
      func(x/3,y+b+d*(x%3));
      if(x/3+1!=x){
        func(x/3+1,y+b+d*(3-x%3));
      }
    }
    if(x%5==0){
      func(x/5,y+c);
    }else{
      func(x/5,y+c+d*(x%5));
      if(x/5+1!=x){
        func(x/5+1,y+c+d*(5-x%5));
      }
    }
  }
  return INF;
}
int print_uint128(__int128_t n) {
  if (n == 0)  return printf("0\n");

  char str[40] = {0}; // log10(1 << 128) + '\0'
  char *s = str + sizeof(str) - 1; // start at the end
  while (n != 0) {
    if (s == str) return -1; // never happens

    *--s = "0123456789"[n % 10]; // save last digit
    n /= 10;                     // drop it
  }
  return printf("%s\n", s);
}
int main(){
  int t = in();
  rep(i,t){
    __int128_t ans = func();
    print_uint128(ans);

  }
  return 0;
}

