#include <bits/stdc++.h>
using namespace std;

vector<int> PowerVec = {2, 3, 5};
vector<int> ExponentMaxCountVec = {60, 37, 25};
vector<vector<long long>> PowerResultVec(3, vector<long long>(1, (long long)1));

void calcPowerResultVec()
{
    for (int powerIndex = 0; powerIndex < 3; ++powerIndex)
    {
        for (int exp = 1; exp <= ExponentMaxCountVec.at(powerIndex); ++exp)
        {
            PowerResultVec.at(powerIndex).push_back(PowerResultVec.at(powerIndex).at(exp - 1) * PowerVec.at(powerIndex));
        }
    }
}

long long solve()
{
    long long n;
    int a, b, c, d;
    cin >> n >> a >> b >> c >> d;

    vector<int> costVec = {a, b, c, d};

    long long minPoint = n * costVec.at(3);

    // 現在の進行状況
    vector<int> exponentCountVec = {0, 0, 0};
    bool isFinished = false;

    // 指数の組み合わせを全探索
    while (!isFinished)
    {
        long long singlePoint = 1;

        // かけた結果
        long long powerResult = 1;
        for (int i = 0; i < 3; ++i)
        {
            powerResult *= PowerResultVec.at(i).at(exponentCountVec.at(i));

            singlePoint += costVec.at(i) * exponentCountVec.at(i);
        }

        // かけた結果が小さければ残りの埋め方を考える
        // 大きければ-1で埋めたときのポイント考える
        if (powerResult <= n)
        {
            long long plusOneMinPoint = n * costVec.at(3);

            long long rem = n - powerResult;

            vector<int> plusOneExponentCountVec = {0, 0, 0};

            bool isPlusOneFinished = false;

            while (isPlusOneFinished)
            {
                long long plusOneSinglePoint = singlePoint;

                long long remPower = 1;
                for (int i = 0; i < 3; ++i)
                {
                    remPower *= PowerResultVec.at(i).at(plusOneExponentCountVec.at(i));

                    plusOneSinglePoint += plusOneExponentCountVec.at(i) * costVec.at(3);
                }

                if (remPower <= rem)
                {
                    long long remRem = rem - remPower;

                    plusOneSinglePoint += costVec.at(3) * remRem;

                    plusOneMinPoint = min(plusOneMinPoint, plusOneSinglePoint);
                }

                // 指数更新
                for (int i = 0; i < 3; ++i)
                {
                    if (plusOneExponentCountVec.at(i) < exponentCountVec.at(i))
                    {
                        ++plusOneExponentCountVec.at(i);

                        break;
                    }
                    else if (i < 2 && plusOneExponentCountVec.at(i + 1) < exponentCountVec.at(i + 1))
                    {
                        for (int left = 0; left <= i; ++left)
                        {
                            plusOneExponentCountVec.at(left) = 0;
                        }

                        ++plusOneExponentCountVec.at(i + 1);

                        break;
                    }

                    if (i == 2)
                    {
                        isPlusOneFinished = true;
                    }
                }
            }

            minPoint = min(minPoint, plusOneMinPoint);
        }
        else if (powerResult < n * 2)
        {
            long long rem = powerResult - n;

            singlePoint += costVec.at(3) * rem;

            minPoint = min(minPoint, singlePoint);
        }

        // 指数更新
        for (int i = 0; i < 3; ++i)
        {
            if (exponentCountVec.at(i) < ExponentMaxCountVec.at(i))
            {
                ++exponentCountVec.at(i);

                break;
            }
            else if (i < 2 && exponentCountVec.at(i + 1) < ExponentMaxCountVec.at(i + 1))
            {
                // 自分と左を全て0にする
                for (int left = 0; left <= i; ++left)
                {
                    exponentCountVec.at(left) = 0;
                }

                ++exponentCountVec.at(i + 1);

                break;
            }

            if (i == 2)
            {
                isFinished = true;
            }
        }
    }

    return minPoint;
}

int main()
{
    int t;
    cin >> t;

    calcPowerResultVec();

    vector<long long> ansVec;

    for (int i = 0; i < t; ++i)
    {
        ansVec.push_back(solve());
    }

    for (const long long &singleAns : ansVec)
    {
        cout << singleAns << endl;
    }
}

