unordered_map<uint64_t, uint64_t> cache;
uint64_t n, a, b, c, d;

uint64_t dfs(uint64_t k) {
    if (k == 0) return 0;
    if (k == 1) return d;
    if (cache.count(k) > 0) return cache[k];
    uint64_t ans = d * k;
    ans = min(ans, dfs(k / 5) + c + d * (k % 5));
    if (k % 5 != 0) ans = min(ans, dfs(k / 5 + 1) + c + d * (5 - k % 5));
    ans = min(ans, dfs(k / 3) + b + d * (k % 3));
    if (k % 3 != 0) ans = min(ans, dfs(k / 3 + 1) + b + d * (3 - k % 3));
    ans = min(ans, dfs(k / 2) + a + d * (k % 2));
    if (k % 2 != 0) ans = min(ans, dfs(k / 2 + 1) + a + d * (2 - k % 2));
    cache[k] = ans;
    return ans;
}

