ll dfs(ll n) {
    if (n == 0) return 0;
    if (m[n] > 0) return m[n];

    ll ans = 1e18;
    if (n < ans / D) ans = n * D;
    if (n % 5 == 0) ans = min(ans, C + dfs(n / 5));
    else {
        ll lower = n / 5 * 5, upper = lower + 5;
        ans = min(ans, dfs(lower / 5) + C + (n - lower) * D);
        ans = min(ans, dfs(upper / 5) + C + (upper - n) * D);
    }

    if (n % 3 == 0) ans = min(ans, B + dfs(n / 3));
    else {
        ll lower = n / 3 * 3, upper = lower + 3;
        ans = min(ans, dfs(lower / 3) + B + (n - lower) * D);
        ans = min(ans, dfs(upper / 3) + B + (upper - n) * D);
    }

    if (n % 2 == 0) ans = min(ans, A + dfs(n / 2));
    else {
        ll lower = n / 2 * 2, upper = lower + 2;
        ans = min(ans, dfs(lower / 2) + A + (n - lower) * D);
        ans = min(ans, dfs(upper / 2) + A + (upper - n) * D);
    }

    return m[n] = ans;
}

