			auto [s, v] = q.top(); q.pop();
			auto f = [&](LL m, LL k) {
				add(s + prod(v - v / m, d) , v / m    );
				add(s + (    v % m) * d + k, v / m    );
				add(s + (m - v % m) * d + k, v / m + 1);
			};
