int main() {
    int t;
    cin >> t;
    while (t--) {
        ll n;
        vector<ll> coin(4);
        cin >> n >> coin[0] >> coin[1] >> coin[2] >> coin[3];

        map<ll, ll> cost;
        cost[n] = 0;
        priority_queue<p, vector<p>, greater<>> que;
        que.push({0, n});
        while (true) {
            auto x = que.top();
            que.pop();
            ll nowNum = x.second;
            if (x.first > cost[nowNum])continue;
            if (nowNum == 0) break;

            for (int i = 0; i < 3; i++) {
                ll nextNum = nowNum / times[i];
                ll nextCost = x.first + coin[i] + coin[3] * (nowNum % times[i]);
                if (cost.find(nextNum) == cost.end() || cost[nextNum] > nextCost) {
                    cost[nextNum] = nextCost, que.push({nextCost, nextNum});
                }

                nextNum = (nowNum + times[i] - 1) / times[i];
                nextCost = x.first + coin[i] + coin[3] * (times[i] - (nowNum % times[i]));
                if (cost.find(nextNum) == cost.end() || cost[nextNum] > nextCost) {
                    cost[nextNum] = nextCost, que.push({nextCost, nextNum});
                }
            }
        }

        ll ret = INF;
        for (auto x:cost) {
            if (x.first > INF / coin[3] + 1)continue;
            ret = min(ret, x.first * coin[3] + x.second);
        }
        cout << ret << endl;
    }
    return 0;
}

