    if (k >= 3)
    {
        ll temp = (k % 3) * d + b;
        ll temp1 = (3 - (k % 3)) * d + b;
        temp += dfs(k / 3);
        temp1 += dfs((k + 3) / 3);
        chmin(res, temp);
        chmin(res, temp1);
    }
    if (k >= 5)
    {
        ll temp = (k % 5) * d + c;
        ll temp1 = (5 - (k % 5)) * d + c;
        temp1 += dfs((k + 5) / 5);
        temp += dfs(k / 5);
        chmin(res, temp);
        chmin(res, temp1);
    }
    dp[k] = res;
