// O(N)

// Avoid this
// for(int i = 1;i <= 1000000;i++) if(memo[pos] == 0) cout << "YES"; // O(log(N)) -> memorinya sejuta
// Use this instead
// for(int i = 1;i <= 1000000;i++) if(memo.count(pos)) cout << "YES"; // O(log(n)) -> memorinya 0
// O(log N)
// (memo[pos] != 0)
// C++ bakal giniin : memo[pos] = int(0);, return memo[pos]; // O 
// memo.count(pos);

const LL LINF = 4557430888798830399LL;

LL n, d;
map <LL, LL> memo;
LL cost[3];
LL fact[3] = {2,3,5};

LL dp(LL pos){

    if(pos == 0) return 0;
    if(pos == 1) return d;

    if(memo.count(pos)) return memo[pos];

    LL ret = pos*d;
    if(pos > (1'000'000'000'000'000'000LL)/d) ret = LINF;

    // Coba dibagi X
    // Ada 2 cara, jadiin lowerbound X dimana, 2|X
    for(int i = 0;i < 3;i++){
        int x = fact[i];

        // misal x = 5
        // 12 -> 10/2
        LL rem = pos%x; // rem -> 2

        LL nx = pos-rem; // nx = 10
        LL nxcost = (pos-nx)*d; // pos dikurang kurangin sampe nx, terus bagi 5

        if(nx/x != 0) nxcost += cost[i];
        ret = min(dp(nx/x)+nxcost, ret);

        if(rem == 0) continue;

        // 12 -> 15/2
        nx = pos-rem+x; // nx = 15
        nxcost = (nx-pos)*d; // pos ditambah tambahin sampe nx, terus bagi 5

        if(nx/x != 0) nxcost += cost[i];
        ret = min(dp(nx/x)+nxcost, ret);
    }

    return memo[pos] = ret;
}

