#define ff first
#define ss second
typedef long long LL;
typedef unsigned long long uLL;
typedef std::pair<int,int> pii;
const int inf = 0x3f3f3f3f;
const LL Linf = 1ll<<61;

const int maxn = 1000111;
LL n, a, b, c, d, dist[maxn], val[maxn];

std::map<LL, int> all;
int tot;

void dfs(LL n)
{
	if(all.find(n) != all.end()) return;
	all[n] = ++tot;
	val[tot] = n;
	dfs(n / 2);
	dfs(n / 3);
	dfs(n / 5);
}

std::priority_queue<std::pair<LL, LL>> pq;
void update(LL val, LL d)
{
	if(all.find(val) == all.end()) return;
	int id = all[val];
	if(dist[id] > d)
	{
		dist[id] = d;
		pq.emplace(-dist[id], id);
	}
}
void dijkstra()
{
	for(int i=1; i<=tot; i++)
	{
		if(val[i] == 0) dist[i] = 0;
		else if(Linf / val[i] >= d) dist[i] = val[i] * d;
		else dist[i] = Linf;
		pq.emplace(-dist[i], i);
	}
	while(!pq.empty())
	{
		int id = pq.top().ss; LL D = -pq.top().ff; pq.pop();
		if(dist[id] != D) continue;
		// printf("v= %lld d= %lld\n", val[id], D);
		update(val[id] * 2, D + a);
		update(val[id] * 3, D + b);
		update(val[id] * 5, D + c);
		update(val[id] + 1, D + d);
		update(val[id] - 1, D + d);
	}
}

void solve()
{
	get1(n);
	get4(a, b, c, d);
	all.clear();
	dfs(n);
	std::vector<LL> candidate;
	for(auto v : all) candidate.pb(v.ff);
	for(auto v : candidate) for(int i=-2; i<=2; i++)
	{
		if(all.find(v + i) == all.end())
		{
			all[v + i] = ++tot;
			val[tot] = v + i;
		}
	}
	dijkstra();
	printendl(dist[all[n]]);
}

int main()
{
	int tc;
	get1(tc);
	while(tc--) solve();
	return 0;
}

