ll count(ll num, ll coins, ll d) {
  ll a1, a2;
  decltype(t)::iterator itt;

//printf("%*scount(%lld, %lld, %lld)\n", (int)d, "", num, coins, d);

  if (num == 1) {
    if (coins+D<minc) minc = coins+D;
//printf("%*scount(%lld, %lld, %lld)=%lld\n", (int)d, "", num, coins, d, D);
    return D;
  }
  if (num == 0) {
    if (coins<minc) minc = coins;
//printf("%*scount(%lld, %lld, %lld)=0\n", (int)d, "", num, coins, d);
    return 0;
  }

  a1 = LLONG_MIN;
  itt = t.find(num);  //num から0までの最小値（確定値）
  if (itt != t.end()) {
//printf("%*scount(%lld, %lld, %lld)=%lld m\n", (int)d, "", num, coins, d, itt->second);
    return itt->second;
  }

// 2で割る
  if (num%2 == 0) {
    a2 = count(num/2, coins+A, d+1)+A;
    if (a1 < 0 || a2 < a1) a1 = a2;
  } else {
    a2 = count((num+1)/2, coins+D+A, d+1)+D+A;
    if (a1 < 0 || a2<a1) a1 = a2;
    a2 = count((num-1)/2, coins+D+A, d+1)+D+A;
    if (a1 < 0 || a2<a1) a1 = a2;
  }

//3で割る
  switch (num%3) {
  case 0:
    a2 = count(num/3, coins+B, d+1)+B;
    if (a1 < 0 || a2 < a1) a1 = a2;
    break;
  case 1:
    a2 = count((num-1)/3, coins+D+B, d+1)+D+B;
    if (a1 < 0 || a2 < a1) a1 = a2;
    break;
  case 2:
    a2 = count((num+1)/3, coins+D+B, d+1)+D+B;
    if (a1 < 0 || a2 < a1) a1 = a2;
    break;
  }

//5で割る
  switch (num%5) {
  case 0:
    a2 = count(num / 5, coins+C, d+1)+C;
    if (a1 < 0 || a2 < a1) a1 = a2;
    break;
  case 1:
    a2 = count((num-1) / 5, coins+D+C, d+1)+D+C;
    if (a1 < 0 || a2 < a1) a1 = a2;
    break;
  case 2:
    a2 = count((num-2) / 5, coins+D*2+C, d+1)+D*2+C;
    if (a1 < 0 || a2 < a1) a1 = a2;
    break;
  case 3:
    a2 = count((num+2) / 5, coins+D*2+C, d+1)+D*2+C;
    if (a1 < 0 || a2 < a1) a1 = a2;
    break;
  case 4:
    a2 = count((num+1) / 5, coins+D+C, d+1)+D+C;
    if (a1 < 0 || a2 < a1) a1 = a2;
    break;
  }

  if (a1 < 0) {
//printf("%*scount(%lld, %lld, %lld)=%lld\n", (int)d, "", num, coins, d, a1);
    return LLONG_MIN;
  }

  itt = t.find(num);
  if (itt != t.end()) {
    if (itt->second > a1) {
      t.erase(num);
      t.emplace(num, a1);
//printf("x memo(%lld, %lld)\n", num, a1);
    }
  } else {
    t.emplace(num, a1);
//printf("memo(%lld, %lld) %lu\n", num, a1, t.size());
  }

//printf("%*scount(%lld, %lld, %lld)=%lld\n", (int)d, "", num, coins, d, a1);
  return a1;
}

