         ans  = min(ans , b + solve(x/3));
    }
    else
    {
        ans = min(ans , d*(3 - x%3) + b + solve((x +3 - x%3)/3));
        ans = min(ans  ,d*(x%3) + b + solve( (x - x%3)/3 ) );
    }
    if(x %5 == 0)
    {
        ans  = min(ans , c + solve(x/5));
    }
    else
    {
        ans = min(ans , d*(5- x%5) + c + solve((x +5 - x%5)/5));
        ans = min(ans  ,d*(x%5) + c + solve( (x - x%5)/5 ) );
    }
    if(x %2 == 0)
    {
        ans  = min(ans , a + solve(x/2));
    }
    else
    {
        ans = min(ans , d*(2- x%2) + a + solve((x +2- x%2)/2));
        ans = min(ans  ,d*(x%2) + a + solve( (x - x%2)/2 ));
    }
    mp[x] = ans;
    return ans;
}

