typedef pair<long long,long long> P;
__int128 INF=1e15;
bool visited[1001];

__int128 ans(long long x) {
    if (x<=1000) {
        return dist[x];
    }
    if (dp.find(x)!=dp.end()) {
        return dp[x];
    }
    __int128 ret=INF;
    if (x%2==0) {
        ret=min({ret,ans(x/2)+a,ans(x/2)+d*(x/2)});
    }
    else {
        ret=min({ret,ans(x/2)+a+d,ans(x/2+1)+a+d,ans(x/2)+d*(x-x/2),ans(x/2+1)+d*(x-x/2-1)});
    }
    if (x%3==0) {
        ret=min({ret,ans(x/3)+b,ans(x/3)+d*(x-x/3)});
    }
    else {
        ret=min({ret,ans(x/3)+b+(x%3)*d,ans(x/3+1)+b+(3-x%3)*d,ans(x/3)+d*(x-x/3),ans(x/3+1)+d*(x-x/3-1)});
    }
    if (x%5==0) {
        ret=min({ret,ans(x/5)+c,ans(x/5)+d*(x-x/5)});
    }
    else {
        ret=min({ret,ans(x/5)+c+(x%5)*d,ans(x/5+1)+c+(5-x%5)*d,ans(x/5)+d*(x-x/5),ans(x/5+1)+d*(x-x/5-1)});
    }
    dp[x]=ret;
    return ret;
}

