        d=dd;
        vector<P> adj[1001];
        for(int i=0;i<=1000;i++) {
            if (i+1<=1000) {
                adj[i].push_back(P(i+1,d));
            }
            if (i-1>=0) {
                adj[i].push_back(P(i-1,d));
            }
            if (i*2<=1000) {
                adj[i].push_back(P(i*2,a));
            }
            if (i*3<=1000) {
                adj[i].push_back(P(i*3,b));
            }
            if (i*5<=1000) {
                adj[i].push_back(P(i*5,c));
            }
            dist[i]=INF;
            visited[i]=false;
        }
        dist[0]=0;
        priority_queue<P,vector<P>,greater<P>> pq;
        pq.push(P(0,0));
        dist[0]=0;
        while (!pq.empty()) {
            int now;
            do {
                now=pq.top().second;
                pq.pop();
