typedef uint64_t ll;

map<ll, ll> mem;

ll go(ll n, ll a, ll b, ll c, ll d) {
	if (n == 0)
		return 0;
	if (n == 1)
		return d;
	if (mem[n] != 0)
		return mem[n];

	vector<ll> res;

	if (n / 5 > 0)
		res.push_back((n % 5) * d + c + go((n - n % 5) / 5, a, b, c, d));
	if (n % 5 != 0)
		res.push_back((5 - n % 5) * d + c + go((n + (5 - n % 5)) / 5, a, b, c, d));

	if (n / 3 > 0)
		res.push_back((n % 3) * d + b + go((n - n % 3) / 3, a, b, c, d));
	if (n % 3 != 0)
		res.push_back((3 - n % 3) * d + b + go((n + (3 - n % 3)) / 3, a, b, c, d));

	if (n / 2 > 0)
		res.push_back((n % 2) * d + a + go((n - n % 2) / 2, a, b, c, d));
	if (n % 2 != 0)
		res.push_back((2 - n % 2) * d + a + go((n + (2 - n % 2)) / 2, a, b, c, d));

	res.push_back(n * d);

	sort(res.begin(), res.end());

	mem[n] = res[0];

	return res[0];
}

