long long DP(long long n){
    if(!n)return 0ll;
    if(n==1)return D;
    if(Map.count(n))return Map[n];
    int i;
    long long r=1e18;
    for(i=2;i<=5;i++){
        if(i==4)continue;
        long long x = n/i;
        long long u = DP(x);
        long long t1 = (n-x*i)*D +P[i];
        if(t1/D >= (n-x))t1 = (n-x)*D;
        r=min(r,t1+u);
        if(x+1!=n){
            long long t2 = ((x+1)*i-n)*D +P[i];
            if(t2/D >= (n-x-1))t2 = (n-x-1)*D;
            long long v = DP(x+1);
            r=min(r,t2+v);
        }
    }
    Map[n]=r;
    return r;
}
