    for (int i = 0; i < N; ++i) {
      for (int j = 0; j < N; ++j) {
        for (int k = 0; k < N; ++k) {
          if (i + 1 < N) pr[i + 1][j][k] = mul(pr[i][j][k], 2);
          if (j + 1 < N) pr[i][j + 1][k] = mul(pr[i][j][k], 3);
          if (k + 1 < N) pr[i][j][k + 1] = mul(pr[i][j][k], 5);
          dp[i][j][k] = Inf;
        }
      }
    }
    auto gettk = [&] (ll x, ll y) {
      ll tk = x / y;
      ll go = tk * y;
      if (abs(x - go) > abs(x - (go + y))) ++tk;
      return tk;
    };
    auto getx = [&] (ll x, ll y) {
      ll tk = x / y;
      ll go = tk * y;
      if (abs(x - go) > abs(x - (go + y))) ++tk;
      return abs(x - tk * y);
    };
    dp[0][0][0] = 0;
    for (int i = 0; i < N; ++i) {
      for (int j = 0; j < N; ++j) {
        for (int k = 0; k < N; ++k) {
