          }
          ll tk = gettk(n, pr[i][j][k]);
          ll need = sum(dp[i][j][k], tk);
          ll all = mul(need, d);
          add(all, mul(i, a));
          add(all, mul(j, b));
          add(all, mul(k, c));
          ans = min(ans, all);
        }
      }
    }
    cout << ans << '\n'; 
  }
}

