ll calc(ll x) {
    if (cache.find(x) != cache.end()) return cache[x];
    ll ans = INF;
    if ((ld) x * (ld) d < INF) ans = x * d;

    if (x % 2 == 0) {
        ll ca = calc(x / 2) + a;
        ans = min(ans, ca);
    }
    else {
