        ans = min(ans, ca);
    }
    else {
        ll D = x % 3;
        ll U = 3 - D;
        ll ca = min(
                calc(x / 3) + b + D*d,
                calc(x / 3 + 1) + b + U*d
                );
        ans = min(ans, ca);
    }

    if (x % 5 == 0) {
        ll ca = calc(x / 5) + c;
        ans = min(ans, ca);
    }
    else {
        ll D = x % 5;
        ll U = 5 - D;
        ll ca = min(
                calc(x / 5) + c + D*d,
                calc(x / 5 + 1) + c + U*d
                );
        ans = min(ans, ca);
    }

