bool update(map<ll, ll>& mp, ll score, ll number) {
    if (mp.find(number) == mp.end()) {
        mp[number] = score;
        return true;
    }
    else {
        ll baseScore = mp[number];
        if (baseScore <= score) {
            return false;
        }
        else {
            mp[number] = score;
            return true;
        }
    }
