map<ll, ll> mp;

ll dfs(ll x) {
	if (mp.count(x)) return mp[x];
	if (x == 0) return mp[0] = 0;
	if (x == 1) return mp[1] = d;

	ll res = INF;
     res = min(res, x*d);
	res = min(res, dfs(x / 2) + a + x % 2 * d);
	res = min(res, dfs((x + 1) / 2) + a + (2 - x % 2)*d);
	res = min(res, dfs(x / 3) + b + x % 3 * d);
	res = min(res, dfs((x + 2) / 3) + b + (3 - x % 3)*d);
	res = min(res, dfs(x / 5) + c + x % 5 * d);
	res = min(res, dfs((x + 4) / 5) + c + (5 - x % 5)*d);
	return mp[x] = res;
}

