ll N, A, B, C, D;
map<ll, ll> memo;
ll dfs(ll n, bool two, bool three, bool add)
{
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return D;
    }
    if (memo[n] != 0) {
        return memo[n];
    }
    // dump(n);
    ll lo = max(1LL, n - 4);
    ll hi = n + 4;
    ll ans = INF;
    if (INF / D > n) {
        ans = n * D;
    }
    if (true && n % 5 == 0) chmin(ans, dfs(n / 5, true, true, true) + C);
    if (three && n % 3 == 0) chmin(ans, dfs(n / 3, true, true, true) + B);
    if (two && n % 2 == 0) chmin(ans, dfs(n / 2, true, true, true) + A);

    if (add) {
        chmin(ans, dfs(n + 4, false, false, false) + 4 * D);
        chmin(ans, dfs(n + 3, false, false, false) + 3 * D);
        chmin(ans, dfs(n + 2, false, true, false) + 2 * D);
        chmin(ans, dfs(n + 1, true, true, false) + 1 * D);
        if (n >= 1) chmin(ans, dfs(n - 1, true, true, false) + 1 * D);
        if (n >= 2) chmin(ans, dfs(n - 2, true, true, false) + 2 * D);
        if (n >= 3) chmin(ans, dfs(n - 3, true, true, false) + 3 * D);
        if (n >= 4) chmin(ans, dfs(n - 4, true, true, false) + 4 * D);
    }
    if (two && three && add) {
        memo[n] = ans;
    }
    return ans;
}
