ll solve(ll n)
{
    ll r1,r2,r3;
	if(n==1)
		return d;
	if(n==0)
	return 0;
	if(mp.find(n)!=mp.end())
	    return mp[n];
	r1=n%2;
	r2=n%3;
	r3=n%5;
	ll k1=r1*d+a+solve((n-r1)/2);
	ll k2=r2*d+b+solve((n-r2)/3);
	ll k3=r3*d+c+solve((n-r3)/5);
	ll k4=1e18+1;
	ll k5=1e18+1;
	ll k6=1e18+1;
	if(n>2)
	k4=(2-r1)*d+a+solve((n+2-r1)/2);
	if(n>1)
	k5=(3-r2)*d+b+solve((n+3-r2)/3);
	if(n>1)
	k6=(5-r3)*d+c+solve((n+5-r3)/5);
	mp[n]=min(k1,min(k2,min(k3,min(k4,min(k5,k6)))));
	ll u=n*d;
	if(u>0)
	mp[n]=min(mp[n],n*d);
	return mp[n];
