		for(nx2 = x, res2 = 0; nx2 % m[i]; --nx2, res2 += d);
		if(res1 <= res2){
			for(; nx1 && !(nx1 % m[i]) && myMin(d, nx1, c[i]) == c[i]; nx1 /= m[i], res1 += c[i]);
			ret = min(ret, solve(nx1) + res1);
		}
		if(res1 >= res2){
			for(; nx2 && !(nx2 % m[i]) && myMin(d, nx2, c[i]) == c[i]; nx2 /= m[i], res2 += c[i]);
			ret = min(ret, solve(nx2) + res2);
		}
	}
	return ret;
}

