typedef long long int ll;
ll isSubsetSum(vector<ll> set, ll n, ll sum,ll x) 
{ 
    // Base Cases 
    if (x == sum ) 
        return x; 


    // If last element is greater than sum, 
    // then ignore it 
    if (set[n - 1] > sum) 
        return isSubsetSum(set, n - 1, sum,x); 

    /* else, check if sum can be obtained by any  
of the following: 
      (a) including the last element 
      (b) excluding the last element   */
    return isSubsetSum(set, n - 1, sum,x) 
           || isSubsetSum(set, n - 1, sum,sum - set[n - 1]); 
} 
