ll Task::calc(ll x) {
	ll rez = LL_INF;
	if(x <= LL_INF / D) {
		rez = min(rez, x * D);
	}
	ll r2 = x & 1LL;
	if((x - r2) / 2 < x) {
		rez = min(rez, r2 * D + A + get((x - r2) / 2));
	}
	if((x + 2 - r2) / 2 < x) {
		rez = min(rez, (2 - r2) * D + A + get((x + 2 - r2) / 2));
	}
	ll r3 = x % 3;
	if((x - r3) / 3 < x) {
		rez = min(rez, r3 * D + B + get((x - r3) / 3));
	}
	if((x + 3 - r3) / 3 < x) {
		rez = min(rez, (3 - r3) * D + B + get((x + 3 - r3) / 3));
	}
	ll r5 = x % 5;
	if((x - r5) / 5 < x) {
		rez = min(rez, r5 * D + C + get((x - r5) / 5));
	}
	if((x + 5 - r5) / 5 < x) {
		rez = min(rez, (5 - r5) * D + C + get((x + 5 - r5) / 5));
	}
	return rez;
}

ll Task::get(ll x) {
	if(MEM.count(x)) {
		return MEM[x];
	} else {
		return (MEM[x] = calc(x));
	}
}

