bool anspro(){
    ll n,a,b,c,d;cin>>n>>a>>b>>c>>d;
    ll N=500;
    ll dp[N];
    rep(i,0,N-1)dp[i]=inf;
    dp[0]=0;
    priority_queue<l_l,vector<l_l>,greater<l_l>>p;//cost,数

    p.push({0,0});
    while(!p.empty()){

        l_l top=p.top();p.pop();
        ll now=top.se;
        ll co=top.fi;
        if(now*2<=N-1){
            if(chmin(dp[now*2],co+a)){
                p.push({dp[now*2],now*2});
            }
        }
        if(now*3<=N-1){
            if(chmin(dp[now*3],co+b)){
                p.push({dp[now*3],now*3});
            }
        }
        if(now*5<=N-1){
            if(chmin(dp[now*5],co+c)){
                p.push({dp[now*5],now*5});
            }
        }
        if(now+1<=N-1){
            if(chmin(dp[now+1],co+d)){
                p.push({dp[now+1],now+1});
            }
        }
        if(now-1>=1){
            if(chmin(dp[now-1],co+d)){
                p.push({dp[now-1],now-1});
            }
        }
    }
    //rep(i,0,N-1)cout<<dp[i]<<" ";cout<<endl;

    priority_queue<l_l,vector<l_l>,greater<l_l>>q;//cost,数
    ll ans=inf;
    q.push({0,n});
    map<ll,ll>mp;
    while(!q.empty()){

        l_l top=q.top();q.pop();
        ll now=top.se;
        ll co=top.fi;
        if(mp[now]==0){
            mp[now]=co;
        }else{
            if(co>=mp[now])continue;
            else mp[now]=co;
        }

        ll nxt=now,cost=co;
        if(now<=N-1){
            chmin(ans,cost+dp[now]);
            continue;
        }

        while(1){
            if(nxt%2==0){
                q.push({cost+a,nxt/2});
                break;
            }else{
                cost+=d;
                nxt++;
            }
        }
        nxt=now;cost=co;
        while(1){
            if(nxt%2==0){
                q.push({cost+a,nxt/2});
                break;
            }else{
                cost+=d;
                nxt--;
            }
        }

        nxt=now;cost=co;
        while(1){
            if(nxt%3==0){
                q.push({cost+b,nxt/3});
                break;
            }else{
                cost+=d;
                nxt++;
            }
        }

        nxt=now;cost=co;
        while(1){
            if(nxt%3==0){
                q.push({cost+b,nxt/3});
                break;
            }else{
                cost+=d;
                nxt--;
            }
        }

        nxt=now;cost=co;
        while(1){
            if(nxt%5==0){
                q.push({cost+c,nxt/5});
                break;
            }else{
                cost+=d;
                nxt++;
            }
        }

        nxt=now;cost=co;
        while(1){
            if(nxt%5==0){
                q.push({cost+c,nxt/5});
                break;
            }else{
                cost+=d;
                nxt--;
            }
        }
        nxt=now;cost=co;
        ll t=nxt/4;
        LL T=t;
        LL D=d;
        if(T*D+cost<ans){
            q.push({cost+d*t,nxt-t});
        }

    }
    cout<<ans<<endl;

    return 0;
}

