    boost::multiprecision::cpp_int a = 1, b = 1;
    a *= k; a*= cost[1]; a += cost[p];
    b *= abs(s - g); b *= cost[1];
    return (ll)min(a, b);
}

ll f(ll n) {
    if (mp.find(n) != mp.end())
        return mp[n];
    if (n == 1)
        return cost[1];

    vector<int> v = {2, 3, 5};
    ll ret = LINF;
    for (auto p : v) {
        ll l = n / p, r = rup(n, p);
        if (l == 0)
            ret = min(ret, calc(n, r, p) + f(r));
        else
            ret = min(ret, min(calc(n, l, p) + f(l), calc(n, r, p) + f(r)));
    }
    mp[n] = ret;
    return ret;
}

