std::string ll2bitstr(long long x)
{
    std::string ret;
    while (x)
    {
        ret += x % 2 + '0', x /= 2;
    }
    std::reverse(ret.begin(), ret.end());
    return ret;
}
__int128 solve2(lint x)
{
    string s = ll2bitstr(x);
    int N = s.length() + 1;

    vector<lint> dp0(N, 1e18);
    vector<lint> dpk(N, 1e18);
    vector<lint> dpyo(N, 1e18);
    dp0[0] = 0;
    dp0[1] = D + A * (s.length() - 1);
    dpyo[0] = D + A * s.length();
    REP(i, s.length())
    {
        if (s[i] == '0')
        {
            dp0[i + 1] = min(dp0[i], dpk[i]);
            dpyo[i + 1] = min(dp0[i + 1] + D, dpyo[i] + D);
        }
        else
        {
            if (i != 0) chmin(dp0[i + 1], min({dp0[i] + D, dpk[i] + D}));
            dpk[i + 1] = min(dpk[i], dpyo[i] + D);
        }
    }
    lint ret = min(dp0.back(), dpk.back());
    if (__int128(x) * D < ret) ret = x * D;
    // dbg(x);
