const int mx = 2e5+5;
void amin(ll &u, ll v){u=min(u,v);}
void amax(ll &u, ll v){u=max(u,v);}

ll n, a, b, c, d;
unordered_map<ll,ll> m;

ll fun(ll x){
    if(x == 0) return 0;
    if(x == 1) return d;

    if(m.find(x) != m.end()) return m[x];

    ll res = LLONG_MAX, y;
    if(x < res/d) res = x*d;
    y = (x/2)*2; amin(res, (x-y)*d + a + fun(y/2));
    y = (x/3)*3; amin(res, (x-y)*d + b + fun(y/3));
    y = (x/5)*5; amin(res, (x-y)*d + c + fun(y/5));

    y = ((x+1)/2)*2; amin(res, (y-x)*d + a + fun(y/2));
    y = ((x+2)/3)*3; amin(res, (y-x)*d + b + fun(y/3));
    y = ((x+4)/5)*5; amin(res, (y-x)*d + c + fun(y/5));
    return m[x] = res;
}

void solve(){
    cin >> n >> a >> b >> c >> d;
    m.clear();
    m.reserve(mx<<2);
    cout << fun(n) << "\n";
}

int main(){
    cin.tie(nullptr);
    ios_base::sync_with_stdio(0);

    int tc; cin >> tc;
    while(tc--) solve();
    return 0;
}

