map<int, int> mp;
int n, a[4], k[3] = {2, 3, 5};

int func(int x)
{
	int n, tmp;

	if(x == 0)return 0;

	if(mp[x] != 0) return mp[x];
	if(x == 1) return mp[x] = a[3];

	if(x > 1e18 / a[3]) n = LLONG_MAX;
	else n = x * a[3];

	for (int i = 0; i < 3; i++)
	{
		tmp = x % k[i];
		n = min(n, func((x - tmp) / k[i]) + a[i] + tmp * a[3]);
		tmp = (k[i] - tmp) % k[i];
		n = min(n, func((x + tmp) / k[i]) + a[i] + tmp * a[3]);
	}

	return mp[x] = n;
}

