map<LL,LL> dp;
LL A,B,C,D,N;
const LL INF=9e18;
LL Go(LL x){
	if (x==0){
		return 0;
	}
	if (dp.count(x)) return dp[x];
	LL ans=INF;
	if (x<=INF/D){
		ans=x*D;
	}
	for (int dlt=-4;dlt<=4;dlt++){
		LL v=x+dlt;
		if (v%2==0){
			if (v/2<x){
				ans=min(ans,Go(v/2)+A+D*abs(dlt));
			}
		}
		if (v%3==0){
			if (v/3<x){
				ans=min(ans,Go(v/3)+B+D*abs(dlt));
			}
		}
		if (v%5==0){
			if (v/5<x){
				ans=min(ans,Go(v/5)+C+D*abs(dlt));
			}
		}
	}
	return dp[x]=ans;
}
