void upd(ll a, ll b) {
	if(mp.find(a) == mp.end())
		mp[a] = b;
	else
		mp[a] = min(mp[a], b);
}

int main() {
	int T; cin >> T;
	while(T --) {
		ll n, a, b, c, d;
		cin >> n >> a >> b >> c >> d;
		mp = {{n, 0}};

		ll ans = 1e18L;
		while(!mp.empty()) {
			auto p = *(-- mp.end());
			mp.erase(-- mp.end());

			// cout << p.fi << ' ' << p.se << '\n';

			if(p.fi < 1e18L / d)
				ans = min(ans, p.second + p.fi * d);

			auto f = [&](ll div, ll cost) {
				ll down = p.fi / div;
				ll up = (p.fi + div - 1) / div;
				for(ll to : {up, down}) if(to > 0) {
					upd(to, abs(to * div - p.fi) * d + cost + p.se);
				}
			};

			f(2, a); f(3, b); f(5, c);

			if(p.fi == 1) break;
		}

		cout << ans << '\n';
	}
}

