using namespace std;
typedef long long ll;
constexpr char sp = ' ';

int T;
ll N, A, B, C, D;

ll tourist() {
	set<ll>st;
	priority_queue < pair<ll, pair<ll, bool>>, vector<pair<ll, pair<ll, bool>>>, greater<pair<ll, pair<ll, bool>>>>pq;
	pq.push({ 0,{N,true} });
	while (true) {
		ll d = pq.top().first;
		ll v = pq.top().second.first;
		bool b = pq.top().second.second;
		pq.pop();
		if (st.insert(v).second) {
			if (v == 0)return d;
			if (b) {
				for (ll i = max(0ll, v - 4); i <= v + 4; i++) {
					pq.push({ d + abs(i - v)*D,{i,false} });
				}
				if (D <= (5e18) / v) {
					pq.push({ d + v*D,{0,false} });
				}
			}
			if (v % 2 == 0) {
				pq.push({ d + A,{v / 2,true} });
			}
			if (v % 3 == 0) {
				pq.push({ d + B,{v / 3,true} });
			}
			if (v % 5 == 0) {
				pq.push({ d + C,{v / 5,true} });
			}
		}
	}
}

int main() {
	cin >> T;
	while (T--) {
		cin >> N >> A >> B >> C >> D;
		cout << tourist() << endl;
	}
}

