ll INF = (1LL<<62)-1;

ll a, b, c, d;
M m;

ll f(ll n) {
  if(n < 0) {
    return INF;
  }
  if(n == 0) {
    return 0;
  }
  if(n == 1) {
    return d;
  }
  if(m[n]) {
    return m[n];
  }

  ll next_val = INF;
  ll delta = 0;
  while(delta < 5) {
    if ((n + delta) % 2 == 0 && delta >= 1 && delta < 2) {
      ll k = (n+delta)/2;
      next_val = min(next_val, f(k) + delta*d+a);
      // オーバフローする場合があるのでその場合は無視
      if((n-k)*d > 0) next_val = min(next_val, f(k) + (n-k)*d);
    }
    if ((n - delta) % 2 == 0 && delta < 2) {
      ll k = (n-delta)/2;
      next_val = min(next_val, f(k) + delta*d+a);
      if((n-k)*d > 0) next_val = min(next_val, f(k) + (n-k)*d);
    }
    if ((n + delta) % 3 == 0 && delta >= 1 && delta < 3) {
      ll k = (n+delta)/3;
      next_val = min(next_val, f(k) + delta*d+b);
      if((n-k)*d > 0) next_val = min(next_val, f(k) + (n-k)*d);
    }
    if ((n - delta) % 3 == 0 && delta < 3) {
      ll k = (n-delta)/3;
      next_val = min(next_val, f(k) + delta*d+b);
      if((n-k)*d > 0) next_val = min(next_val, f(k) + (n-k)*d);
    }
    if ((n + delta) % 5 == 0 && delta >= 1 && delta < 5) {
      ll k = (n+delta)/5;
      next_val = min(next_val, f(k) + delta*d+c);
      if((n-k)*d > 0) next_val = min(next_val, f(k) + (n-k)*d);
    }
    if ((n - delta) % 5 == 0 && delta < 5) {
      ll k = (n-delta)/5;
      next_val = min(next_val, f(k) + delta*d+c);
      if((n-k)*d > 0) next_val = min(next_val, f(k) + (n-k)*d);
    }
    delta++;
  }
  // printf("%lld, %lld\n", n, next_val);
  return m[n] = next_val;
}

