		chmin(ans, Search(n / k[i], mp) + a[i] + (n % k[i]) * d);
		if (n % k[i])
			chmin(ans, Search(n / k[i] + 1, mp) + a[i] + (k[i] - (n % k[i])) * d);
	}
	if (d * n / n == d)
		chmin(ans, d * n);
	return mp[n] = ans;
}

int main(void) {
	int i, k, q;
	ll num, ans;
	cin >> q;
	rep(k, q) {
		cin >> num >> a[0] >> a[1] >> a[2] >> d;
		map<ll, ll> mp;
		mp[0] = 0;
		mp[1] = d;
		ans = Search(num, mp);
		cout << ans << "\n";
	}
	return 0;
}

