ll solve (ll n) {
	if (n == 0) return 0;
	if (n == 1) return d;
	if (n == 2) return d + min(d, a);
	if (dp.count(n)) return dp[n];

	ll ret = inff;
	if (inff / d >= n) ret = n * d;
	ret = min(ret, a + n % 2 * d + solve(n / 2));
	ret = min(ret, a + (2 - n % 2) * d + solve(n / 2 + 1));
	ret = min(ret, b + n % 3 * d + solve(n / 3));
	ret = min(ret, b + (3 - n % 3) * d + solve(n / 3 + 1));
	ret = min(ret, c + n % 5 * d + solve(n / 5));
	ret = min(ret, c + (5 - n % 5) * d + solve(n / 5 + 1));
	return dp[n] = ret;
}

