        } else if (n % 3 == 2) {
            v.push_back({(n - (n - 2) / 3) * 1.0 / (b + 2 * d), {(n - 2) / 3, b + 2 * d}});
            v.push_back({(n - (n + 1) / 3) * 1.0 / (b + d), {(n + 1) / 3, b + d}});
        }
        if (n % 5 == 0) {
            v.push_back({(n - n / 5) * 1.0 / c, {n / 5, c}});
        } else if (n % 5 == 1) {
            v.push_back({(n - (n - 1) / 5) * 1.0 / (c + d), {(n - 1) / 5, c + d}});
            v.push_back({(n - (n + 4) / 5) * 1.0 / (c + 4 * d), {(n + 4) / 5, c + 4 * d}});
        } else if (n % 5 == 2) {
            v.push_back({(n - (n - 2) / 5) * 1.0 / (c + 2 * d), {(n - 2) / 5, c + 2 * d}});
            v.push_back({(n - (n + 3) / 5) * 1.0 / (c + 3 * d), {(n + 3) / 5, c + 3 * d}});
        } else if (n % 5 == 3) {
            v.push_back({(n - (n - 3) / 5) * 1.0 / (c + 3 * d), {(n - 3) / 5, c + 3 * d}});
            v.push_back({(n - (n + 2) / 5) * 1.0 / (c + 2 * d), {(n + 2) / 5, c + 2 * d}});
        } else if (n % 5 == 4) {
            v.push_back({(n - (n - 4) / 5) * 1.0 / (c + 4 * d), {(n - 4) / 5, c + 4 * d}});
            v.push_back({(n - (n + 1) / 5) * 1.0 / (c + 1 * d), {(n + 1) / 5, c + d}});
        }
        v.push_back({1.0 / d, {n - 1, d}});
        int id = 0;
        double minn = v[0].first;
        for (int i = 1; i < v.size(); ++i) {
            if (minn < v[i].first) {
                id = i;
                minn = v[i].first;
            }
        }
        if (id == v.size() - 1) {
            ans += n * d;
