ll dp(ll x) {
    if (x <= n) return f[x];
    if (mp.count(x)) return mp[x];
    ll res = INF;
    if (res / D > x) res = x * D;

    ll l2 = (x/2)*2;
    ll r2 = ((x+1)/2)*2;
    ll l3 = (x/3)*3;
    ll r3 = ((x+2)/3)*3;
    ll l5 = (x/5)*5;
    ll r5 = ((x+4)/5)*5;

    res = min(res, llabs(l2-x)*D + A + dp(l2/2));
    res = min(res, llabs(r2-x)*D + A + dp(r2/2));

    res = min(res, llabs(l3-x)*D + B + dp(l3/3));
    res = min(res, llabs(r3-x)*D + B + dp(r3/3));

    res = min(res, llabs(l5-x)*D + C + dp(l5/5));
    res = min(res, llabs(r5-x)*D + C + dp(r5/5));


    return mp[x] = res;
}

