void dfs(llong x)
{
	if(mp.count(x)) {return;}
	llong ret = x*D,t;
	t = x/2ll; dfs(t); updmin(ret,mp[x/2ll]+min((x-x/2ll)*D,A+(x%2ll)*D));
	t = (x+1)/2ll; dfs(t); updmin(ret,mp[(x+1)/2ll]+min((x-(x+1ll)/2ll)*D,A+(2ll-x%2ll)%2ll*D));
	t = x/3ll; dfs(t); updmin(ret,mp[x/3ll]+min((x-x/3ll)*D,B+(x%3ll)*D));
	t = (x+2)/3ll; dfs(t); updmin(ret,mp[(x+2)/3ll]+min((x-(x+2ll)/3ll)*D,B+(3ll-x%3ll)%3ll*D));
	t = x/5ll; dfs(t); updmin(ret,mp[x/5ll]+min((x-x/5ll)*D,C+(x%5ll)*D));
	t = (x+4)/5ll; dfs(t); updmin(ret,mp[(x+4)/5ll]+min((x-(x+4ll)/5ll)*D,C+(5ll-x%5ll)%5ll*D));
	mp[x] = ret;
	return;
}

