ll LIM = 1e12;

ll ans;

set<pair<ll, ll> > pp;
map<ll, ll> dis;

ll a, b, c, d;

void add(ll n, ll v) {
	if (v >= ans) {
		return;
	}
	if (dis.count(n)) {
		if (dis[n] > v) {
			pp.erase(mp(dis[n], n));
			dis[n] = v;
			pp.insert(mp(v, n));
		}
	} else {
		dis[n] = v;
		pp.insert(mp(v, n));
	}
}

void process() {
	ll v = pp.begin()->_1, n = pp.begin()->_2;
	//cout << n << " " << v << endl;
	pp.erase(pp.begin());
	if (n <= LIM && LIM / d >= n) {
		ans = min(ans, v + d * n);
	}
	if (n <= 1) {
		return;
	}
	if (v >= ans) {
		return;
	}

	if (n % 2 == 0) {
		add(n / 2, v + a);
	} else {
		add(n / 2, v + a + d);
		add(n / 2 + 1, v + a + d);
	}

	if (n % 3 == 0) {
		add(n / 3, v + b);
	} else if (n % 3 == 1) {
		add(n / 3, v + b + d);
	} else {
		add(n / 3 + 1, v + b + d);
	}

	if (n % 5 == 0) {
		add(n / 5, v + c);
	} else if (n % 5 == 1) {
		add(n / 5, v + c + d);
	} else if (n % 5 == 2) {
		add(n / 5, v + c + d + d);
	}  else if (n % 5 == 3) {
		add(n / 5 + 1, v + c + d + d);
	} else {
		add(n / 5 + 1, v + c + d);
	}
}

