ll m[3]{2,3,5};
ll p[3];

ll dp(ll x){
    if(x <= 1)
        return x * D;
    if(mp[x])
        return mp[x];

    ll ans = INF;
    if(x<=INF/D) ans = D*x;
    for(ll i = 0; i < 3; i ++){
        ll tms = x / m[i];
        ll fst = tms * m[i];
        ll snd = fst + m[i];
        ans = min(ans, dp(fst / m[i]) + p[i] + abs(fst - x) * D);
        if(x % m[i])
            ans = min(ans, dp(snd / m[i]) + p[i] + abs(snd - x) * D);
    } 
    return mp[x] = ans;
}

