i64 compute(i64 N, i64 A, i64 B, i64 C, i64 D, unordered_map<i64, i64> &sol) {  
  if(sol.find(N) == sol.end()) {
    //cout << N << endl;
    i64 ans;
    if(N % 2 == 0) {
      ans = A + compute(N / 2, A, B, C, D, sol);
    }
    else {
      ans = D + A + min(compute(N / 2, A, B, C, D, sol),
			compute(N / 2 + 1, A, B, C, D, sol));
    }

    i64 res = N % 3;
    ans = min(ans, B + min(res       * D + compute(N/3,   A, B, C, D, sol),
			   (3 - res) * D + compute(N/3+1, A, B, C, D, sol)));

    res = N % 5;
    ans = min(ans, C + min(res       * D + compute(N/5, A, B, C, D, sol),
			   (5 - res) * D + compute(N/5+1, A, B, C, D, sol)));

    if(ans / D >= N) {
      ans = D * N;
    }

    sol[N] = ans;
    //cout << N << " " << sol[N] << endl;
  }

  return sol[N];
}

