ll divide(ll x,ll y,ll w,ll D){
  if(x%y!=0){
    abort();
  }
  if(x/y*(y-1)>=w/D)return w;
  return min(x/y*(y-1)*D,w);
}
ll dd(ll x,ll y){
  return x/y+(x%y>0?1:0);
}
ll A,B,C,D;
ll solve(ll N){
  if(N==0)return 0;
  if(N==1)return D;
  priority_queue<pll,vector<pll>,greater<pll>> q;
  set<ll> visited;
  q.push(pll(0,N));
  while(!q.empty()){
    auto cur=q.top();q.pop();
    ll cost=cur.first,num=cur.second;
    if(visited.count(num))continue;
    visited.insert(num);
    if(num==0)return cost;
    if(num==1)return cost+D;
    auto push=[&](pll x){
      if(visited.count(x.second)==0){
        q.push(x);
      }
    };
    push(pll(cost+divide(num/2*2,2,A,D)+num%2*D,num/2));
    if(num%2)push(pll(cost+divide(num/2*2+2,2,A,D)+D,num/2+1));
    push(pll(cost+divide(num/3*3,3,B,D)+num%3*D,num/3));
    if(num%3)push(pll(cost+divide(num/3*3+3,3,B,D)+D,num/3+1));
    push(pll(cost+divide(num/5*5,5,C,D)+num%5*D,num/5));
    if(num%5)push(pll(cost+divide(num/5*5+5,5,C,D)+D,num/5+1));
  }
}
