int64_t ans=INT64_MAX;

void wfs(queue<pair<int64_t,int64_t>> &q,map<int64_t,int64_t> &m,int64_t n,int64_t c){
    if(m.count(n)) m[n]=min(m[n],c);
    else  m[n]=c;
    //cout<<n<<" "<<c<<endl;

    if(n==1){
        ans=min(ans, c+D);
        return;
    }

    if(n%2==0 && (!m.count(n/2) || c+A<m[n/2])) q.push(make_pair(n/2,c+A));
    if(n%3==0 && (!m.count(n/3) || c+B<m[n/3])) q.push(make_pair(n/3,c+B));
    if(n%5==0 && (!m.count(n/5) || c+C<m[n/5])) q.push(make_pair(n/5,c+C));

    if(!m.count(n-1) || c+D<m[n-1]) q.push(make_pair(n-1,c+D));
    if((n+1)<=N+30-N%30 && (!m.count(n+1) || c+D<m[n+1])) q.push(make_pair(n+1,c+D));
}

int main(){
    int T; cin>>T;
    rep(t,0,T){
        cin>>N>>A>>B>>C>>D;

        mp.clear();
        ans=INT64_MAX;
        queue<pair<int64_t,int64_t>> q;
        q.push(make_pair(N,0));

        while(!q.empty()){
            int64_t n,c;
            tie(n,c)=q.front();
            q.pop();

            wfs(q,mp,n,c);
        }
        cout<<ans<<endl;
    }
}

