int T;
ll N, A, B, C, D;
unordered_map<ll, ll> m;
ll dfs(ll pos) {
    // 停止条件
    // 深さに限らず，任意の停止条件を書く
    if(pos == 0) return 0;
    if(pos == 1) return D;
    if(m.count(pos)) return m[pos];
    ll l2 = (pos/2)*2;
    ll r2 = ((pos+1)/2)*2;
    ll l3 = (pos/3)*3;
    ll r3 = ((pos+2)/3)*3;
    ll l5 = (pos/5)*5;
    ll r5 = ((pos+4)/5)*5;

    // pos を進めながら（末端に進みながら）分岐処理
    // 末端まで到達した時それぞれの分岐から値が返される
    // for 文で書ける場合は for 文で実装
    ll res = 1e18;
    if(pos < res/D) res = pos*D;
    res = min(res, abs(l2-pos)*D + A + dfs(l2/2));
    res = min(res, abs(r2-pos)*D + A + dfs(r2/2));

    res = min(res, abs(l3-pos)*D + B + dfs(l3/3));
    res = min(res, abs(r3-pos)*D + B + dfs(r3/3));

    res = min(res, abs(l5-pos)*D + C + dfs(l5/5));
    res = min(res, abs(r5-pos)*D + C + dfs(r5/5));

    // それぞれの分岐からの戻り値の処理を行う関数
    return m[pos] = res;
}

