      int val1 = ost % kek[i], val2 = kek[i] - val1;
      go((ost - val1) / kek[i]);
      go((ost + val2) / kek[i]);
      if (ost - val1 == 0) {
        rez = min(rez, D * val1);
      }
      else {
        rez = min(rez, opt[(ost - val1) / kek[i]] + c[i] + D * val1);  
      }
      rez = min(rez, opt[(ost + val2) / kek[i]] + c[i] + D * val2);
    }
  }
  if (log2(D) + log2(ost) < 63) {
    rez = min(rez, D * ost);  
  }
  opt[ost] = rez;
  return;
}

