long long one(long long x,long long res,long long answer,long long d){
  long long i=0;
  long long z=min(res,x);
  while(1){
    if(x%z==0){
      long long p=res/z;
      answer+=p*d;
      res%=z;
      break;
    }
    z--;
  }
  if(res==0) return answer;
  else return one(x,res,answer,d);
}      
