ll a, b, c, d;

ll solve(ll n){
    if (n==0) return 1;
    if (n==1) return d;
    if (memo[n]) return memo[n];

    ll res = 10e18;
    if (n < res/d) res = n*d;
    for (auto x : p){
        ll l = n/x.fi;
        ll r = (n+x.fi-1)/x.fi;
        res = min(res, llabs(x.fi*r-n)*d+x.se+solve(r));
        res = min(res, llabs(x.fi*l-n)*d+x.se+solve(l));
    }
    memo[n] = res;
    return res;
}

