	if(now > N){
		ans = min(ans, mon + D*(now-N));
//		MN = N;
		return;
	}
	if(now >= N - N/3){
		ans = min(ans, mon + D*(N-now));
		return;
	}	

//	if(!(now*5 >= MN))
		dfs(now*5, mon+C);
//	if(!(now*3 >= MN))
