void dfs2(unsigned long long now, unsigned long long mon){
	if(mon >= ans){
		return;
	}

	if(now == 1){
		ans = min(ans, mon+D);
		return;
	}

	if(now == 0){
		ans = min(ans, mon);
		return;
	}

	ans = min(ans, D*now+mon);

	switch(now%5){
		case 0:{
			dfs2(now/5, mon+C);
			break;
		}
		default:{
			dfs2((now-now%5)/5, mon+C+(now%5)*D);
			dfs2((now+5-now%5)/5, mon+C+(5-now%5)*D);
			break;
		}		
	}


	switch(now%3){
		case 0:{
			dfs2(now/3, mon+B);
			break;
		}
		case 1:{
			dfs2((now+2)/3, mon+B+2*D);
			dfs2((now-1)/3, mon+B+D);
			break;
		}
		case 2:{
			dfs2((now-2)/3, mon+B+2*D);
			dfs2((now+1)/3, mon+B+D);
			break;
		}
		default:
			break;
	}

	if((now%2)){
		dfs2((now+1)/2, mon+D+A);
		dfs2(now/2, mon+D+A);
	}
	else dfs2(now/2, mon+A);

}
