    if(n==1ll)return d;
    if(mem.find(n)!=mem.end())return mem[n];

    ll ret= inf, x;
    if(n<(inf/d))ret= n*d;

    x= (n/2ll)*2ll;
    ret= min(ret, (n-x)*d+a+dp(x/2));
    if(n%2ll)
    {
        x= ((n/2ll)+1)*2ll;
        ret= min(ret, (x-n)*d+a+dp(x/2));
    }

    x= (n/3ll)*3ll;
    ret= min(ret, (n-x)*d+b+dp(x/3ll));
    if(n%3ll)
    {
        x= ((n/3ll)+1)*3ll;
        ret= min(ret, (x-n)*d+b+dp(x/3ll));
    }

    x= (n/5ll)*5ll;
    ret= min(ret, (n-x)*d+c+dp(x/5ll));
    if(n%5ll)
    {
        x= ((n/5ll)+1)*5ll;
        ret= min(ret, (x-n)*d+c+dp(x/5ll));
    }
    return mem[n]= ret;
}
