using LL = long long;
const LL INF = 1e15;
unordered_map<LL, LL> dp;
LL n, a, b ,c, d;
int cost[10];
LL ceil(LL a, LL b) {
    if (a % b == 0) return a / b;
    else return a / b + 1;
}

LL dfs(LL x) {
    if (dp.find(x) != dp.end()) return dp[x];

    if ((__int128_t)d * x < INF) dp[x] = d * x;
    else dp[x] = INF;

    for (auto m : {2, 3, 5}) {
        LL t1 = x / m;
        LL t2 = ceil(x, m);
        dp[x] = min(dp[x], min(dfs(t1) + (x - t1 * m) * d + cost[m], dfs(t2) + (t2 * m - x) * d + cost[m]));
    }
    return dp[x];
}

void solve() {
    cin >> n >> a >> b >> c >> d;
    cost[2] = a, cost[3] = b, cost[5] = c;
    dp.clear();
    cout << dfs(n) << endl;
}

