ll a,b,c,d;
vector<ll> v={2,3,5};
map<ll,ll> m;

ll solve(ll n){
    if(n==0)
        return 0;
    if(n==1)
        return d;
    ll mn=INF;
    if(n<INF/d)
        mn=n*d;
    if(m.find(n)!=m.end())
        return m[n];
    ll cost;
    for(ll i=0;i<3;i++){
        if(i==0) cost=a;
        if(i==1) cost=b;
        if(i==2) cost=c;
        if(n%v[i]==0)
            mn=min(mn,cost+solve(n/v[i]));
        else{
            ll down=n/v[i]*v[i];
            mn=min(mn,d*(n-down)+cost+solve(n/v[i]));
            ll up=down+v[i];
            mn=min(mn,d*(up-n)+cost+solve(n/v[i]+1));
        }
    }
    return m[n]=mn;
}

