template <typename T>
class RecursiveFunction {
    T t;

public:
    RecursiveFunction(T&& t) : t(forward<T>(t)) {}

    template <typename... Args>
    auto operator()(Args&& ... args) const {
        return t(*this, forward<Args>(args)...);
    }
};


class APayToWin {
public:
    void solve() {
        ll n = in.readLong();
        ll a = in.readInt();
        ll b = in.readInt();
        ll c = in.readInt();
        ll d = in.readInt();

        map<ll, ll> res;
        res[0] = 0;
        RecursiveFunction rec = [&](const auto& self, ll n) -> ll {
            if (res.count(n)) {
                return res[n];
            }
            ll& ans = res[n];
            ans = numeric_limits<ll>::max() / 2;
            if (ans / d >= n) {
                ans = n * d;
            }
            if (n % 2 == 0) {
                minim(ans, self(n / 2) + a);
            } else {
                minim(ans, self(n / 2) + a + d * (n % 2));
                minim(ans, self(n / 2 + 1) + a + d * (2 - n % 2));
            }
            if (n % 3 == 0) {
                minim(ans, self(n / 3) + b);
            } else {
                minim(ans, self(n / 3) + b + d * (n % 3));
                minim(ans, self(n / 3 + 1) + b + d * (3 - n % 3));
            }
            if (n % 5 == 0) {
                minim(ans, self(n / 5) + c);
            } else {
                minim(ans, self(n / 5) + c + d * (n % 5));
                minim(ans, self(n / 5 + 1) + c + d * (5 - n % 5));
            }
            return ans;
        };
        out.printLine(rec(n));
    }
};


