inline void gao(ll x,ll y)
{
	if (!mp.count(x)) mp[x]=y;
	else mp[x]=min(mp[x],y);
}

inline void work()
{
	n=rd();a=rd();b=rd();c=rd();d=rd();
	mp.clear();mp[n]=0;
	ll ans=inf;
	while (233)
