            std::vector<std::vector<T>> a(szi, std::vector<T>(szj));
            for (std::size_t i = 0; i < szi; ++i) for (std::size_t j = 0; j < szj; ++j) cin >> a[i][j]; return a;
        }
    };
    inp inp1;

    ll dfs(ll n, map<ll, ll>& mp, ll a, ll b, ll c, ll d) {
        if (n == 0) return 0LL;
        if (mp.find(n) != mp.end()) return mp[n];
        if (mp.find(n) != mp.end()) return mp[n];
        ll ret = infll;

        // Dだけで済ます
        if (n <= infll / d) ret = n * d;

        for (int i = -3; i <= 3; ++i) {
            ll x = n + i;
            if (x <= 0) continue;
            if (x % 5 == 0) chmin(ret, dfs(x / 5, mp, a, b, c, d) + c + d * abs(i));
            if (abs(i) >= 2) continue;
            if (x % 3 == 0) chmin(ret, dfs(x / 3, mp, a, b, c, d) + b + d * abs(i));
            if (abs(i) >= 1) continue;
            if (x % 2 == 0) chmin(ret, dfs(x / 2, mp, a, b, c, d) + a + d * abs(i));
        }

        return mp[n] = ret;
    }
}

