        res = min(res, 1ll * x * d);

    // x * d <= res
    // x <= res / d

    // cerr << x << " D " << res << endl;

    long long two = 2ll * (x / 2);
    res = min(res, a + go(two / 2) + d * (x - two));
    if (x != 2)
