long long int f(long long int N) {
  if (N == 0) return 0;

  long long int res = INF;
  if (N < INF / D) res = min(res, N * D);

  if (N % 2 == 0) {
    res = min(res, f(N/2) + A);
  } else {
    res = min(res, f((N-1)/2) + D + A);
    res = min(res, f((N+1)/2) + D + A);
  }

  if (N % 3 == 0) {
    res = min(res, f(N/3) + B);
  } else {
    int m = N % 3;
    res = min(res, f((N-m)/3) + m*D + B);
    res = min(res, f((N-m+3)/3) + (3-m)*D + B);
  }

  if (N % 5 == 0) {
    res = min(res, f(N/5) + C);
  } else {
    int m = N % 5;
    res = min(res, f((N-m)/5) + m*D + C);
    res = min(res, f((N-m+5)/5) + (5-m)*D + C);
  }

  return res;
}

