            //cout << "***********************" << endl;
            tup el = q.top();q.pop();
            ll num = get<0>(el);
            ll coin = get<1>(el);
            vector<ll> plus_minus = get<2>(el);

            //cout << num << ":" << coin << ":" << endl;

            if(coin >= min_coin_theory + 1) continue;
            if(num == 0) {
                if(coin < 0) continue;
                if(min_coin < 0) min_coin = coin;
                else min_coin = min(coin, min_coin);
                continue;
            }

            if(num > 0 && (min_coin_theory - coin) / D > num )  push_el(q, 0, coin + num* D, plus_minus);
            if(num % 2 == 0) push_el(q, num / 2, min({coin + A}), plus_minus);
            if(num % 2 == 1 && num != 1) {
                push_el(q, (num - 1) / 2, min({coin + A + D}), plus_minus);
                push_el(q, (num + 1) / 2, min({coin + A + D}), plus_minus);
            }
            if(num % 3 == 0) push_el(q, num / 3, min({coin + B}), plus_minus);
            if(num % 3 == 1 && num != 1) {
                push_el(q, (num - 1) / 3, min({coin + B + D}), plus_minus);
                push_el(q, (num + 2) / 3, min({coin + B + (2 * D)}), plus_minus);
            }
            if(num % 3 == 2 && num != 2) {
                push_el(q, (num - 2) / 3, min({coin + B + (2* D)}), plus_minus);
                push_el(q, (num + 1) / 3, min({coin + B +  D}), plus_minus);
            }
            if(num % 5 == 0) push_el(q, num / 5, min({coin + C}), plus_minus);
            if(num % 5 == 1 && num != 1) {
                push_el(q, (num - 1) / 5, min({coin + C + D}), plus_minus);
                push_el(q, (num + 4) / 5, min({coin + C + (4 * D)}), plus_minus);
            }
            if(num % 5 == 2 && num != 2) {
                push_el(q, (num - 2) / 5, min({coin + C + (2 * D)}), plus_minus);
                push_el(q, (num + 3) / 5, min({coin + C + (3 * D) }), plus_minus);
            }
            if(num % 5 == 3 && num != 3) {
                push_el(q, (num - 3) / 5, min({coin + C + (3 * D)}), plus_minus);
                push_el(q, (num + 2) / 5, min({coin + C + (2 * D) }), plus_minus);
            }
            if(num % 5 == 4 && num != 4) {
                push_el(q, (num - 4) / 5, min({coin + C + (4 * D) }), plus_minus);
                push_el(q, (num + 1) / 5, min({coin + C +  D}), plus_minus);
            }
        }
        cout << min_coin << endl;
    }


    return 0;
}

#include <bits/stdc++.h>
