using namespace std;

typedef long long ll;

typedef pair<ll, ll> P;
struct edge { ll to, cost; };

const int MAX_V =1000000;
const ll INF = 1LL<<60;

int V;
vector<edge> G[MAX_V];
ll d[MAX_V];

void dijkstra(ll s) {
    // greater<P>を指定することでfirstが小さい順に取り出せるようにする
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d + V, INF);
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top(); que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;
        rep(i,G[v].size()) {
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}

int main() {
    int T;
    cin >> T;
    vector<ll> N(T), A(T), B(T), C(T), D(T);
    queue<ll> q;
    rep(i, T) {
        cin >> N[i] >> A[i] >> B[i] >> C[i] >> D[i];
        q.push(N[i]);
    }
    set<ll> done;
    while (!q.empty()) {
        ll p = q.front();
        q.pop();
        if (done.find(p) != done.end()) continue;
        if (p % 2 == 0) {
            q.push(p / 2);
        }
        if (p % 3 == 0) {
            q.push(p / 3);
        }
        if (p % 5 == 0) {
            q.push(p / 5);
        }
        ll s1 = p / 2 * 2, s2 = p / 3 * 3, s3 = p / 5 * 5;
        ll s = s1;
        if (s2 < s) s = s2;
        if (s3 < s) s = s3;
        ll g1 = (p + 1) / 2 * 2, g2 = (p + 2) / 3 * 3, g3 = (p + 4) / 5 * 5;
        ll g = g1;
        if (g2 > g) g = g2;
        if (g3 > g) g = g3;
        //cout << "s=" << s << " g=" << g << "\n";
        for (ll j = s; j <= g; j++) {
            if (done.find(j) == done.end()) q.push(j);
        }
        done.insert(p);
    }
    int n = done.size();
    map<ll, int> m;
    vector<ll> v(n);
    int c = 0;
    for (auto i : done) {
        m[i] = c;
        v[c] = i;
        c++;
        //cout << i << "\n";
    }
    //cout << "n=" << n << "\n";
    /*
    rep(i, 10) {
        cout << v[i] << "\n";
    }
    */
    V = n;
    rep(i, T) {
        rep(j, n) {
            G[j] = {};
            if (done.find(v[j] * 2) != done.end()) G[j].push_back({m[v[j] * 2], A[i]});
            if (done.find(v[j] * 3) != done.end()) G[j].push_back({m[v[j] * 3], B[i]});
            if (done.find(v[j] * 5) != done.end()) G[j].push_back({m[v[j] * 5], C[i]});
            if (done.find(v[j] + 1) != done.end()) G[j].push_back({m[v[j] + 1], D[i]});
            if (done.find(v[j] - 1) != done.end()) G[j].push_back({m[v[j] - 1], D[i]});
        }
        rep(j, n) {
            if (v[j] <= 1e9) G[0].push_back({j, D[i] * v[j]});
        }
        /*
        rep(j, n) {
            cout << "j=" << j << "\n";
            rep(k, G[j].size()) {
                cout << G[j][k].to << " " << G[j][k].cost << "\n";
            }
        }
        */
        dijkstra(m[0]);
        //cout << "m[0]=" << m[0] << " m[N[i]]=" << m[N[i]] << "\n";
        cout << d[m[N[i]]] << "\n";
        //rep(j, n) cout << "d[" << j << "]=" << d[j] << "\n";
    }
}

