long long int napzak(int ns, long long int coin, int num){
  if(coin < 0 || coin >= d[num] * n[num]) return LLONG_MAX;
  if(ns == n[num])return coin;

  long long int ret1 = min( napzak(ns * 2, coin + a[num], num), napzak(ns * 3, coin + b[num], num));
  long long int ret2 = min( napzak(ns * 5, coin + c[num], num), napzak(ns + 1, coin + d[num], num));
  long long int ret3 = napzak(ns - 1, coin + d[num], num);

  long long int ret4 = min(min(ret1, ret2), ret3);

  return ret4;

}

