void solve(){
	int N,A,B,C,D;
	cin>>N>>A>>B>>C>>D;
	unordered_map<int,int>mp;
	auto dfs = [&](auto&&f,int n) -> unsigned long long{
		if(n == 1)return D;
		if(n == 0)return 0;
		if(mp.count(n))return mp[n];
		unsigned long long ret = D * n;
		FOR(i,-1,1 + 1){
			int cost = abs(i) * D + A;
			int nn = n + i;
			if(nn % 2 == 0){
				if(nn <= 0 || nn / 2 >= n)continue;
				CHMIN(ret,f(f,nn / 2) + cost);
			}
		}
		FOR(i,-2,2 + 1){
			int cost = abs(i) * D + B;
			int nn = n + i;
			if(nn % 3 == 0){
				if(nn <= 0 || nn / 3 >= n)continue;
				CHMIN(ret,f(f,nn / 3) + cost);
			}
		}
		FOR(i,-4,4 + 1){
			int cost = abs(i) * D + C;
			int nn = n + i;
			if(nn % 5 == 0){
				if(nn <= 0 || nn / 5 >= n)continue;
				CHMIN(ret,f(f,nn / 5) + cost);
			}
		}
		return mp[n] = ret;
	};
	out(dfs(dfs,N));
}

