ll solve(ll now){
    if(ma.find(now)!=ma.end()){
        return ma[now];
    }
    ll res;
    ll k;
    if(now>inf){
        k=2;
        if(now%k==0){
            res=solve(now/k)+a;
        }else{
            res=solve(now/k)+a+now%k*d;
            res=min(solve(now/k+1)+a+(k-now%k)*d,res);
        }
    }else{
        res=now*d;
    }
    if(now/2>0){
        k=2;
        if(now%k==0){
            res=min(solve(now/k)+a,res);
        }else{
            res=min(solve(now/k)+a+now%k*d,res);
            res=min(solve(now/k+1)+a+(k-now%k)*d,res);
        }
    }
    if(now/3>0){
        k=3;
        if(now%k==0){
            res=min(solve(now/k)+b,res);
        }else{
            res=min(solve(now/k)+b+now%k*d,res);
            res=min(solve(now/k+1)+b+(k-now%k)*d,res);
        }
    }else{
        k=3;
        res=min(solve(now/k+1)+b+(k-now%k)*d,res);
    }
    if(now/5>0){
        k=5;
        if(now%k==0){
            res=min(solve(now/k)+c,res);
        }else{
            res=min(solve(now/k)+c+now%k*d,res);
            res=min(solve(now/k+1)+c+(k-now%k)*d,res);
        }
    }else{
        k=5;
        res=min(solve(now/k+1)+c+(k-now%k)*d,res);
    }
    ma[now]=res;
    return res;
}
