ll P1;
map<int,ll> divmaps;
using memo_map = map<ll,ll>;

ll ff(ll n, memo_map &memo)
{
    if (auto it = memo.find(n); it != memo.end()) return memo[n];

    ll ans = (n >= (ll)1e9) ? LLONG_MAX : n * P1;


    for (auto [div, T] : divmaps)
    {
        if (n >= div)
        {
            ll fp = ff(n/div, memo);
            if (int m = n % div; m == 0)
                ans = min(ans, fp + T);
            else
            {
                ll fn = ff(n/div+1, memo);
                ans = min({ans, fp + T + P1 * m, fn + T + P1 * (div-m)});
            }
        }
    }

    // cout << "(" << n << "," << ans << ")" << endl;
    return memo[n] = ans;
}

ll f()
{
    ll N;
    cin >> N >> divmaps[2] >> divmaps[3] >> divmaps[5] >> P1;

    memo_map memo;
    return ff(N, memo);
}

