ll f(ll N){
    if(memo.count(N)){
        return memo[N];
    }

    ll ret = INF;
    ret = min(ret, f(N/2) + A + (N%2)*D);
    ret = min(ret, f(N/2+1) + A + (2-N%2)*D);
    ret = min(ret, f(N/3) + B + (N%3)*D);
    ret = min(ret, f(N/3+1) + min(B + (3-N%3)*D, B+(N%3)*D+D));
    ret = min(ret, f(N/5) + min(C + (N%5)*D, C + (5-N%5)*D+D));
    ret = min(ret, f(N/5+1) + min(C + (5-N%5)*D, C + (N%5)*D+D));
    if(INF / D > N-N/2  ) ret = min(ret, f(N/2  ) + D*(N-N/2));
    if(INF / D > N-N/2-1) ret = min(ret, f(N/2+1) + D*(N-N/2-1));
    if(INF / D > N-N/3  ) ret = min(ret, f(N/3  ) + D*(N-N/3));
