long long f(long long x) {
	if (x == 0) {
		return 0;
	}
	if (x == 1) return d;
	if (mp.count(x)) return mp[x];
	long long aa = 1ll * (x % 2) * d + a + f(x / 2);
	if (x % 2) {
		aa = min(aa, 1ll * (2 - x % 2) * d + a + f(x / 2 + 1));
	}
	long long bb = 1ll * (x % 3) * d + b + f(x / 3);
	if (x % 3) {
		bb = min(bb, 1ll * (3 - x % 3) * d + b + f(x / 3 + 1));
	}
	long long cc = 1ll * (x % 5) * d + c + f(x / 5);
	if (x % 5) {
		cc = min(cc, 1ll * (5 - x % 5) * d + c + f(x / 5 + 1));
	}
	mp[x] = min(aa, min(bb, cc));
	if (LLONG_MAX / x >= d) {
		mp[x] = min(mp[x], x * d);
	}
	return mp[x];
}

