int64_t dfs(int64_t n){
  if(memo.count(n))return memo[n];
  int64_t tmp = (1LL<<58);
  if(n%2==0)tmp = std::min(tmp,dfs(n/2)+a);
  else{
    tmp = std::min(tmp,dfs((n+1)/2)+a+d);
    tmp = std::min(tmp,dfs((n-1)/2)+a+d);
  }
  if(n%3==0)tmp = std::min(tmp,dfs(n/3)+b);
  else{
    int64_t low3 = n/3*3;
    int64_t high3 = (n/3+1)*3;
    tmp = std::min(tmp,dfs(low3)+b+d*(n-low3));
    tmp = std::min(tmp,dfs(high3)+b+d*(high3-n));
