LLONG Digit(LLONG n)
{
    LLONG ret = 0;
    while (n)
    {
        n /= 10;
        ++ret;
    }
    return ret;
}

LLONG DFS(const LLONG n)
{
    if (num2MinCostMap.count(n)) return num2MinCostMap[n];
    set<LLONG> vs;
    if (Digit(n) * Digit(D) > 18) vs.insert(1145141919810364364LL);
    else vs.insert(n * D);
    for (int i = 0; i < 3; ++i)
    {
        const LLONG k = ks[i];
        const LLONG lower = n / k;
        const LLONG upper = lower + 1;
        vs.insert(DFS(lower) + (n - lower * k) * D + costs[i]);
        vs.insert(DFS(upper) + (upper * k - n) * D + costs[i]);
    }
    return num2MinCostMap[n] = *vs.begin();
}

