int a[N], n = 0;

int & operator [] (int x) { return a[x]; }

void clear (void) { n = 0; }
int size (void) { return n; }
void push (int x) { a[++ n] = x; }
void pop (void) { n --; }
int & top (void) { return a[n]; }

} s;

ll h[N];

ll calc (ll now) {
	int m = s.size();
	h[m + 1] = 1;
	for (int i = m; i >= 1; i --) {
		h[i] = h[i + 1] * s[i];
	}
	ll ret = 0;
	for (int i = 1; i <= m + 1; i ++) {
		ll t = now / h[i];
		now %= h[i];
		if (now > h[i] - now) {
			ll diff = now * 2 - h[i];
			if (i != m + 1 && diff > h[i + 1]) {
				ret += t + 1;
				now = h[i] - now;
			} else {
				ret += t;
			}
		} else {
			ret += t;
		}
	}
	if (ret > 1e9) return LIM;
	return ret * d;
}


ll dfs (ll now) {
	if (dp.count(now)) 
