        return D;
    else if (memo.find(N) != memo.end())
        return memo[N];

    // cout << "solve " << N << endl;
    ll best = INFL;
    if (N <= INFL/D)
        best = N*D;

    if (N%2 == 0) {
        ll res = solve(N/2, A, B, C, D) + A;
        best = min(best, res);
    }
    else {
        ll res = solve((N+1)/2, A, B, C, D) + A + D;
        best = min(best, res);
        res = solve((N-1)/2, A, B, C, D) + A + D;
        best = min(best, res);
    }
    if (N >= 3) {
        if (N%3 == 0) {
            ll res = solve(N/3, A, B, C, D) + B;
            best = min(best, res);
        }
        else if ((N-1)%3 == 0) {
            ll res = solve((N-1)/3, A, B, C, D) + B + D;
            best = min(best, res);        
        }
        else if ((N+1)%3 == 0) {
            ll res = solve((N+1)/3, A, B, C, D) + B + D;
            best = min(best, res);        
        }
    }
    if (N >= 4) {
        if (N%5 == 0) {
            ll res = solve(N/5, A, B, C, D) + C;
            best = min(best, res);
        }
        else if ((N-1)%5 == 0) {
            ll res = solve((N-1)/5, A, B, C, D) + C + D;
            best = min(best, res);        
        }
        else if ((N+1)%5 == 0) {
            ll res = solve((N+1)/5, A, B, C, D) + C + D;
            best = min(best, res);        
        }
        else if ((N-2)%5 == 0) {
            ll res = solve((N-2)/5, A, B, C, D) + C + D + D;
            best = min(best, res);        
        }
        else if ((N+2)%5 == 0) {
            ll res = solve((N+2)/5, A, B, C, D) + C + D + D;
            best = min(best, res);        
        }
    }

    memo[N] = best;
    return best;
}

