void relax(long long &a, long long b, long long c) {
  if (b != -1 && (a == -1 || a > b + c)) {
    a = b + c;
  }
}

long long search(long long N, long long A, long long B, long long C, long long D, std::map <long long, long long> &m) {
  //std::cerr << "\t" << N << std::endl;
  if (N == 0) {
    return 0;
  }
  if (N == 1) {
    return D;
  }
  if (m.count(N) > 0) {
    //std::cerr << "\tm[N]=" << m[N] << std::endl;
    return m[N];
  }
  long long best = -1;

  if ((__int128)D * (N - N / 2) < A) {
    relax(best, search(N / 2, A, B, C, D, m), D * (N - N / 2));
  }
  if (N % 2 == 0) {
    //std::cerr << "\tN=" << N << "\tA=" << A << std::endl;
    relax(best, search(N / 2, A, B, C, D, m), A);
  } else if (N % 2 != 0 && N > 2) {
    relax(best, search(N / 2, A, B, C, D, m), A + D * (N % 2));
    relax(best, search((N + 1) / 2, A, B, C, D, m), A + D * (2 - N % 2));
  }

  if ((__int128)D * (N - N / 3) < B) {
    relax(best, search(N / 3, A, B, C, D, m), D * (N - N / 3));
  }
  if (N % 3 == 0) {
    relax(best, search(N / 3, A, B, C, D, m), B);
  } else if (N % 3 != 0 && N > 3) {
    relax(best, search(N / 3, A, B, C, D, m), B + D * (N % 3));
    //std::cerr << "\tN=" << N << "\tB+D(3-N%3)=" << (B + D * (3 - N % 3)) << std::endl;
    relax(best, search((N + 2) / 3, A, B, C, D, m), B + D * (3 - N % 3));
  }

  if ((__int128)D * (N - N / 5) < C) {
    relax(best, search(N / 5, A, B, C, D, m), D * (N - N / 5));
  }
  if (N % 5 == 0) {
    relax(best, search(N / 5, A, B, C, D, m), C);
  } else if (N % 5 != 0 && N > 5) {
    relax(best, search(N / 5, A, B, C, D, m), C + D * (N % 5));
    relax(best, search((N + 4) / 5, A, B, C, D, m), C + D * (5 - N % 5));
  }

  m[N] = best;
  return best;
}

void solve() {
  long long N, A, B, C, D;
  std::cin >> N >> A >> B >> C >> D;
  std::map <long long, long long> m;
  long long res = search(N, A, B, C, D, m);
  std::cout << res << std::endl;
}

int main() {
  int T;
  std::cin >> T;
  while (T--) {
    solve();
  }
  return 0;
}

