	LL re=(n&1) ?min(dfs(n>>1)+A+D,dfs(n/2+1)+A+D) :dfs(n>>1)+A ;
	switch (n%3) {
		case 0: re=min(re,dfs(n/3)+B); break;
		case 1: re=min(re,min(dfs(n/3)+B+D,dfs(n/3+1)+B+D+D)); break;
		case 2: re=min(re,min(dfs(n/3)+B+D+D,dfs(n/3+1))+B+D);
	}
	switch (n%5) {
		case 0: re=min(re,dfs(n/5)+C); break;
		case 1: re=min(re,dfs(n/5)+C+D); break;
		case 2: re=min(re,min(dfs(n/5)+C+D+D,dfs(n/5+1)+C+D+D+D)); break;
		case 3: re=min(re,min(dfs(n/5)+C+D+D+D,dfs(n/5+1))+C+D+D); break;
		case 4: re=min(re,dfs(n/5+1)+C+D+D);
	}
	return M[n]=re;
}

