int dfs(int n, int a, int b, int c, int d, map<int, int> &dp)
{
    if (dp.find(n) != dp.end()) {
        return dp[n];
    }
    if (n) {
        // cout << n << endl;
        int ret = INF;
        if (n < 1010001000LL)  {
            ret = min(ret, n * d);
        }
        if (n/2 != n && n/2 != 0) ret = min(ret, dfs(n/2, a, b, c, d, dp) + a + (n % 2) * d);
        if (n/2+1 != n) ret = min(ret, dfs(n/2+1, a, b, c, d, dp) + a + (2 - n % 2) * d);
        if (n/3 != n && n/3 != 0) ret = min(ret, dfs(n/3, a, b, c, d, dp) + b + (n % 3) * d);
        if (n/3+1 != n) ret = min(ret, dfs(n/3+1, a, b, c, d, dp) + b + (3 - n % 3) * d);
        if (n/5 != n && n/5 != 0) ret = min(ret, dfs(n/5, a, b, c, d, dp) + c + (n % 5) * d);
        if (n/5+1 != n) ret = min(ret, dfs(n/5+1, a, b, c, d, dp) + c + (5 - n % 5) * d);
        dp[n] = ret;
        return ret;
    } else {
        return 0;
    }
}

