constexpr lli N_MAX = 1e18;
// メモ
std::map<lli, lli> solved;

lli N, A, B, C, D;
lli solve(lli n) {
    using std::min;
    if (n == 0) return 0;
    if (n == 1) return 1;
    if (solved.count(n)) return solved.at(n);

    lli res = N_MAX;
    // 1でわる
    if (n < res / D) {  // overflow対策
        res = n * D;
    }

    // 2でわる
    res = min(res, (n % 2) * D + solve(n / 2LL) + A);
    res = min(res, (n % 2) * D + solve((n + 1LL) / 2LL) + A);

    // 3でわる
    res = min(res, (n % 3) * D + solve(n / 3LL) + B);
    res = min(res, (3 - n % 3) * D + solve((n + 2LL) / 3LL) + B);

    // 5でわる
    res = min(res, (n % 5) * D + solve(n / 5LL) + C);
    res = min(res, (5 - n % 5) * D + solve((n + 4LL) / 5LL) + C);

    // solved
    solved.insert(std::make_pair(n, res));
    return res;
}

