    else {pq.emplace(-v - A - D, i / 2); pq.emplace(-v - A - D, i / 2 + 1);}
    if (i % 3 == 0) pq.emplace(-v - B, i / 3);
    else if (i % 3 == 1) pq.emplace(-v - B - D, i / 3);
    else pq.emplace(-v - B - D, i / 3 + 1);
    if (i % 5 == 0) pq.emplace(-v - C, i / 5);
    else if (i % 5 == 1) pq.emplace(-v - C - D, i / 5);
    else if (i % 5 == 2) pq.emplace(-v - C - D * 2, i / 5);
    else if (i % 5 == 3) pq.emplace(-v - C - D * 2, i / 5 + 1);
    else pq.emplace(-v - C - D, i / 5 + 1);
    if (i < (1000000000000000000 - v) / D) pq.emplace(-v - D * i, 0);
}

