int n, a, b, c, d;
map<int, int> dp;

bool check(int x){
    return inf/d > x;
}

int fun(int x){

    if(x == 0)return 0;
    if(x == 1)return d;
    if(dp.count(x) != 0)return dp[x];

    dp[x] = inf;
    if(check(x))dp[x] = x*d;

    int tmp = inf;
    if(check(x-x/2))tmp = d*(x-x/2);
    dp[x] = min(dp[x], fun(x/2)+min(a+(x-x/2*2)*d, tmp));
    if(x != 2)
    dp[x] = min(dp[x], fun(x/2+1)+min(a+abs(x-(x/2+1))*d, tmp));

    tmp = inf;
    if(check(x-x/3))tmp = d*(x-x/3);
    dp[x] = min(dp[x], fun(x/3)+min(b+(x-x/3*3)*d, tmp));
    dp[x] = min(dp[x], fun(x/3+1)+min(b+((x/3+1)*3-x)*d, tmp));

    if(check(x-x/5))tmp = d*(x-x/5);
    dp[x] = min(dp[x], fun(x/5)+min(b+(x-x/5*5)*d, tmp));
    dp[x] = min(dp[x], fun(x/5+1)+min(b+((x/5+1)*5-x)*d, tmp));

    return dp[x];
}

void solve() {
    cin >> n >> a >> b >> c >> d;
    int ans = inf;
    if(check(n))ans = n*d;
    for(int i = -10; i < 10; i++){
        if(n+i >= 0)
        ans = min(ans, fun(n+i)+d*abs(i));
    }
    cout << ans << endl;
    dp.clear();
}

