ll N, A, B, C, D;
const ll inf = 1LL << 62;

int two[2] = {0, -1};
int two2[2] = {0, 1};
int three[3] = {0, -1, -2};
int three2[3] = {0, 2, 1};
int five[5] = {0, -1, -2, -3, -4};
int five2[5] = {0, 4, 3, 2, 1};


ll dfs(ll K, map<ll, ll> &M) {
//    output(K);
    if(K == 0) return 0;
    if(K == 1) return D;
    if(M[K] > 0) return M[K];
    ll ret;
    if(inf / D <= K) ret = inf;
    else ret = K * D;
    if(K + two[K % 2] > 0) ret = min(ret, D * abs(two[K % 2]) + A + dfs((K + two[K % 2]) / 2, M));
    if(K + two2[K % 2] > 0) ret = min(ret, D * abs(two2[K % 2]) + A + dfs((K + two2[K % 2]) / 2, M));
    if(K + three[K % 3] > 0) ret = min(ret, D * abs(three[K % 3]) + B + dfs((K + three[K % 3]) / 3, M));
    if(K + three2[K % 3] > 0) ret = min(ret, D * abs(three2[K % 3]) + B + dfs((K + three2[K % 3]) / 3, M));
    if(K + five[K % 5] > 0) ret = min(ret, D * abs(five[K % 5]) + C + dfs((K + five[K % 5]) / 5, M));
    if(K + five2[K % 5] > 0) ret = min(ret, D * abs(five[K % 5]) + C + dfs((K + five2[K % 5]) / 5, M));
    return M[K] = ret;
}


