・B枚のコインを支払い、持っている数を3倍する。
・C枚のコインを支払い、持っている数を5倍する。
・D枚のコインを支払い、持っている数を1増やす、または1減らす。
*/
#include<bits/stdc++.h>
using namespace std;
using ll=long long;
ll min4(ll a,ll b,ll c,ll d){
  return min(a,min(b,min(c,d)));
}
void cal(ll a,ll b,ll c,ll d,ll x,ll ans,int num){
  switch(num){
    case 1:
      x+=1; ans+=d;
      break;
    case 2:
      x-=1; ans+=d;
      break;
    case 3:
      x*=2; ans+=a;
      break;
    case 4:
      x*=3; ans+=b;
      break;
    case 5:
      x*=5; ans+=c;
      break;
    default:
      break;
  }
}
int main(void){
  ll t;
  ll n,a,b,c,d;
  ll x,ans;
  vector<ll> vec(4);
  cin>>t;
  for(int i=0;i<t;i++){
    x=0; ans=0;
    cin>>n>>a>>b>>c>>d;
    vec.push_back(a);
    vec.push_back(b);
    vec.push_back(c);
    vec.push_back(d);
    sort(vec.begin(),vec.end());
    while(1){
      for(int j=0;j<4;j++){
        cal(a,b,c,d,x,ans,vec[j]);
        if(x==n){
          cout<<ans<<endl;
          break;
        }
      }
      break;
    }
  }
  return 0;
}

