map<ll, ll> mem;

ll rec(ll x) {
	if (x == 0) return 0;
	if (mem.count(x)) return mem[x];
	ll ret = LLONG_MAX;
	if (d < LLONG_MAX / x) ret = d * x;
	REP(i, 3) {
		ll y = (x + MLT[i] - 1) / MLT[i] * MLT[i];
		if (y / MLT[i] < x) {
			ll cur = abs(y - x) * d + cost[i] + rec(y / MLT[i]);
			ret = min(ret, cur);
		}
		ll z = x / MLT[i] * MLT[i];
		if (z / MLT[i] < x) {
			ll cur = abs(z - x) * d + cost[i] + rec(z / MLT[i]);
			ret = min(ret, cur);
		}
	}
	return mem[x] = ret;
}

