using namespace std;

ll dp[65][65][65][2];
ll val[65][65][65][2];

void solve()
{
    ll n, a, b, c, d;
    scanf("%lld%lld%lld%lld%lld", &n, &a, &b, &c, &d);

    int i, j, k, m;
    for (i = 0; i <= 60; i++) {
        for (j = 0; j <= 60; j++) {
            for (k = 0; k <= 60; k++) {
                dp[i][j][k][0] = LINF3;
                dp[i][j][k][1] = LINF3;
            }
        }
    }

    ll ans = LINF;
    dp[0][0][0][0] = 0;
    val[0][0][0][0] = n;
    for (i = 0; i < 61; i++) {
        for (j = 0; j < 61; j++) {
            for (k = 0; k < 61; k++) {
                for (m = 0; m < 2; m++) {
                    if (dp[i][j][k][m] < LINF3) {
                        ll tmp=val[i][j][k][m];
                        if ((double)dp[i][j][k][m] + (double)tmp * d < LINF2) {
                            ans = MIN(ans, dp[i][j][k][m] + tmp * d);
                        }
                        if (tmp <= 1) {
                            continue;
                        }

                        int prime[3] = { 2,3,5 };
                        ll  cost[3] = { a,b,c };
                        int p;
                        for(p=0; p<3; p++) {
                            int i2 = i + (p == 0 ? 1 : 0);
                            int j2 = j + (p == 1 ? 1 : 0);
                            int k2 = k + (p == 2 ? 1 : 0);
                            ll tmp2 = tmp / prime[p];
                            if((double)dp[i][j][k][m] + (double)(tmp % prime[p])*d + cost[p] < LINF2){
                                dp[i2][j2][k2][0]=MIN(dp[i2][j2][k2][0], dp[i][j][k][m] + (tmp % prime[p])*d + cost[p]);
                                val[i2][j2][k2][0] = tmp2;
                            }
                            if (tmp % 2 && (double)dp[i][j][k][m] + (double)(prime[p]-tmp % prime[p])*d + cost[p] <LINF2) {
                                dp[i2][j2][k2][1]=MIN(dp[i2][j2][k2][1], dp[i][j][k][m] + (prime[p]-tmp % prime[p])*d + cost[p]);
                                val[i2][j2][k2][1] = tmp2+1;
                            }
                        }
                    }
                }
            }
        }
    }

    printf("%lld\n", ans);

    return;
}


