ll a, b, c, d;

map < ll, ll > mymp;

ll go(ll n){
  if(n == 0) return 0;
  if(n == 1) return d;
  if(mymp.find(n) != mymp.end()){
    return mymp[n];
  }
  ll ret = 2ll * 1e18, nn, rem;
  rem = n % 2;
  nn = n - rem;
  ret = min(ret, go(nn / 2ll) + a + rem * d);
  if(n >= 3){
    rem = n % 3;
    nn = n - rem;
    ret = min(ret, go(nn / 3ll) + b + rem * d);
  }
  if(n >= 5){
    rem = n % 5;
    nn = n - rem;
    ret = min(ret, go(nn / 5ll) + c + rem * d);
  }
  mymp[n] = ret;
  return ret;
}

