// @title メンバ変数を2つ持つ比較可能なクラス (VSCode スニペット)
struct node
{
	int dist;
	int v;
	node(int v1, int v2) : dist(v1), v(v2) {}
	node() {}
	bool operator<(const node r) const {
		return dist == r.dist ? v < r.v : dist < r.dist;
	}
	bool operator>(const node r) const {
		return r < *this;
	}
	bool operator>=(const node r) const {
		return !(*this < r);
	}
	bool operator<=(const node r) const {
		return !(r < *this);
	}
	bool operator==(const node r) const {
		return !(r < *this) && !(*this < r);
	}
	bool operator!=(const node r) const {
		return (r < *this) || (*this < r);
	}
};

int solve() {
	int N, A, B, C, D; cin >> N >> A >> B >> C >> D;
	ll res = LLONG_MAX;
	auto g = [&](int d, int n) {
		if (d <= int(1e18) / n) {
			return n * d;
		}
		return int(1e18);
	};
	chmin(res, g(D, N));

	priority_queue<node, vector<node>, greater<>> q;
	q.push({0, N});
	map<int, int> m;
	auto f = [&](int dist, int v) {
		if (m.count(v)) {
			return;
		}
		q.push({dist, v});
	};
	while (true) {
		auto [dist, v] = q.top(); q.pop();
		if (m.count(v)) continue;
		m[v] = dist;
		// dump(dist, v);
		if (dist >= res) return res;
		if (v == 1) return min(res, dist + D);
		if (v >= 2) {
			int r = v % 2;
			f(dist + A + D * r, v / 2);
			if (r) f(dist + A + D * (2 - r), v / 2 + 1);
		}
		if (v >= 3) {
			int r = v % 3;
			f(dist + B + r * D, v / 3);
			if (r) f(dist + B + (3 - r) * D, v / 3 + 1);
		}
		if (v >= 5) {
			int r = v % 5;
			f(dist + C + r * D, v / 5);
			if (r) f(dist + C + (5 - r) * D, v / 5 + 1);
		}
		chmin(res, dist + g(D, (v - 1)) + D);
	}
}


signed main(){
	int T; cin >> T;
	rep(i, T) {
		cout << solve() << endl;
	}
	return 0;
}

