ll calc(ll n) {
    if (cache.find(n) != cache.end()) return cache[n];
    ll ans = INF;
    if ((ld) n * (ld) d < INF) ans = n * d;

    if (n % 2 == 0) {
        ll ca = calc(n / 2) + a;
        ans = min(ans, ca);
    }
    else {
        ll ca = min(calc(n / 2) + a + d, calc(n / 2) + a + d);
        ans = min(ans, ca);
    }

    if (n % 3 == 0) {
        ll ca = calc(n / 3) + b;
        ans = min(ans, ca);
    }
    else {
        ll D = n % 3;
        ll U = 3 - D;
        ll ca = min(
                calc(n / 3) + b + D*d,
                calc(n / 3) + b + U*d
                );
        ans = min(ans, ca);
    }

    if (n % 5 == 0) {
        ll ca = calc(n / 5) + c;
        ans = min(ans, ca);
    }
    else {
        ll D = n % 5;
        ll U = 5 - D;
        ll ca = min(
                calc(n / 5) + c + D*d,
                calc(n / 5) + c + U*d
                );
        ans = min(ans, ca);
    }

    //out(n << ' ' << ans);
    return cache[n] = ans;
}

