			if (x%3<=1)get(x/3,y+min(B+D*(x-(x/3)*3),tr(x,x/3)));
			else get(x/3+1,y+min(B+D*((x/3+1)*3-x),tr(x,x/3+1)));
			if (x%5<3)get(x/5,y+min(C+D*(x-(x/5)*5),tr(x,x/5)));
			else get(x/5+1,y+min(C+D*((x/5+1)*5-x),tr(x,x/5+1)));
		}
		cout<<s[0]<<endl;
	}
	return 0;
}

