int main() {
  int t;
  cin >> t;
  for (int64_t n, a, b, c, d; cin >> n >> a >> b >> c >> d; ) {
    map<int64_t, int64_t> dp;
    array<int64_t, 3> multiple {2, 3, 5}, cost {a, b, c};
    function<int64_t(int64_t)> solve = [&] (int64_t n)->int64_t {
      if (n == 0) {
        return 0;
      }
      if (n == 1) {
        return d;
      }
      if (dp.count(n) != 0) {
        return dp[n];
      }
      int64_t result = numeric_limits<int64_t>::max();
      for (auto i = 0; i < 3; ++i) {
        if (n % multiple[i] == 0) {
          result = min(result, solve(n / multiple[i]) + cost[i]);
        } else {
          auto down = n / multiple[i] * multiple[i], up = down + multiple[i];
          result = min(result, solve(down / multiple[i]) + (n - down) * d + cost[i]);
          result = min(result, solve(up / multiple[i]) + (up - n) * d + cost[i]);
        }
      }
      return dp[n] = result;
    };
    auto result = solve(n);
    if (n <= numeric_limits<int64_t>::max() / d) {
      result = min(result, n * d);
    }
    cout << result << '\n';
  }
  return 0;
}

