  }
};

ll N, A, B, C, D;

ll abso(ll x) { return x < 0 ? -x : x; }

void solve() {
  DBG(N);

  map<ll, ll> prev;
  map<ll, ll> seen;
  seen[N] = 0;

  priority_queue<S> que;
  que.push({0, N});

  while (!que.empty()) {
    S here = que.top();
    que.pop();
    DBG(here.cost, here.value, que.size(), seen.size());
    if (here.value == 0) {
      ll x = here.value;
      while (x != N) {
        DBG(x);
        x = prev[x];
      }
      cout << here.cost << endl;
      break;
    }
    auto push = [&prev, &seen, &que, &here](ll cost, ll value) {
                  if (value < 0) return;
                  S there = {here.cost + cost, value};
                  auto it = seen.find(there.value);
                  if (it != seen.end() && it->second <= there.cost) {
                    return;
                  }
                  seen[there.value] = there.cost;
                  prev[there.value] = here.value;
                  que.push(there);
                };
    if (here.value % 2 == 0) {
      push(A, here.value / 2);
    }
    if (here.value % 3 == 0) {
      push(B, here.value / 3);
    }
    if (here.value % 5 == 0) {
      push(C, here.value / 5);
    }

    for (ll d = -4; d <= 4; ++d) {
      ll value = here.value + d;
      ll mods[] = {2, 3, 5};
      REP(i, 3) {
        ll m = mods[i];
        if (here.value % m != 0 && value % m == 0 && abso(d) < m) {
          push(D * abso(d), value);
        }
      }
    }

    /*
    if (here.value % 2 != 0) {
      push(D, here.value - 1);
      push(D, here.value + 1);
    }
    if (ll d = here.value % 3; d != 0) {
      push(D * d, here.value - d);
      push(D * (3 - d), here.value + (3 - d));
    }
    if (ll d = here.value % 5; d != 0) {
      push(D * d, here.value - d);
      push(D * (5 - d), here.value + (5 - d));
    }
    */

    if (D * here.value > 0) {
      push(D * here.value, 0);
    }
  }
}

