ll N, A, B, C, D, Limit;
map <ll, ll> MP;

ll Solve(ll num){
  if (num <= 0) return 0;
  if (num == 1) return MP[num] = D;
  if (MP[num] > 0) return MP[num];

  ll ans = 5e18;

  for (ll i = -1; i <= 10; i++){
    ll now = num - i;
    if (now % 2 == 0){
      ans = min(ans, Solve(now / 2) + A + abs(i) * D);
      ll deg = abs(now / 2 - num);
      if (deg <= Limit){
        ans = min(ans, Solve(now / 2) + deg * D);
      }
    }
    if (now % 3 == 0){
      ans = min(ans, Solve(now / 3) + B + abs(i) * D);
      ll deg = abs(now / 3 - num);
      if (deg <= Limit){
        ans = min(ans, Solve(now / 3) + deg * D);
      }
    }
    if (now % 5 == 0){
      ans = min(ans, Solve(now / 5) + C + abs(i) * D);
      ll deg = abs(now / 5 - num);
      if (deg <= Limit){
        ans = min(ans, Solve(now / 5) + deg * D);
      }
    }
    if (MP[now] > 0) ans = min(ans, MP[now] + abs(i) * D);
  }

  return MP[num] = ans;
}

