using namespace std;
#define MAXN (4e18+1)
class X
{
public:
    ll A,B,C,D;
    map<ll,ll> L;
    //set<ll> done;
    ll solve(ll N, ll maxa=MAXN)
    {
        if(L.find(N) != L.end())
            return L[N];
        //cerr<<N<<endl;
        ll ans = MAXN;
        if(N==0)
            return 0;
        if(N==1)
            return D;

        if(N<1e9)
            ans = D*N;
        if(maxa<0)
            return ans;
        {
            const int a=2;
            ll c1 = A;
            ll cost = (N%a)*D + c1;
            ans = min(ans, cost + solve(N/a,maxa-cost));//min(ans,maxa)-cost));
            if(N%a > a/2)
            {
                cost = (a-(N%a))*D + c1;
                ans = min(ans, cost + solve(1+N/a,maxa-cost));//min(ans,maxa)-cost));
            }
        }
        {
            const int a=3;
            ll c1 = B;
            ll cost = (N%a)*D + c1;
            ans = min(ans, cost + solve(N/a,maxa-cost));//min(ans,maxa)-cost));
            if(N%a > a/2)
            {
                cost = (a-(N%a))*D + c1;
                ans = min(ans, cost + solve(1+N/a,maxa-cost));//min(ans,maxa)-cost));
            }
        }
        {
            const int a=5;
            ll c1 = C;
            ll cost = (N%a)*D + c1;
            ans = min(ans, cost + solve(N/a,maxa-cost));//min(ans,maxa)-cost));
            if(N%a > a/2)
            {
                cost = (a-(N%a))*D + c1;
                ans = min(ans, cost + solve(1+N/a,maxa-cost));//min(ans,maxa)-cost));
            }
        }
        if(ans<=maxa)
            L[N]=ans;
        return ans;
    }
};

void solve()
{
	ll N;
    X x;
    cin>>N>>x.A>>x.B>>x.C>>x.D;
    cout<<x.solve(N)<<endl;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
    int T;
    cin>>T;
    while(T--)
	    solve();
