ll n, a, b, c, d;

// { res, cost }
vector<pair<ll, ll>> step(ll x) {
	vector<pair<ll, ll>> res;

	res.push_back({ x/2, a+d*(x%2) }); // down+2
	if (x%2) res.push_back({ (x+1)/2, a+d*(2-x%2) }); //up+2
	res.push_back({ x/3, b+d*(x%3) }); // down+3
	if (x%3) res.push_back({ (x+2)/3, b+d*(3-x%3) }); //up+3
	res.push_back({ x/5, c+d*(x%5) }); // down+5
	if (x%5) res.push_back({ (x+4)/5, c+d*(5-x%3) }); //up+5
	if (x<=1'000'000'000ll) res.push_back({ 0, d*x }); // jt 0

	return res;
}

void solve() {
	map<ll, ll> mindist;
	priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>> pq;

	read(n, a, b, c, d);

	mindist[n] = 0;
	pq.push({ 0, n });

	while (!pq.empty()) {
		ll st,cost;
		tie(cost,st) = pq.top(); pq.pop();

		if (cost > mindist[st]) {
			continue;
		}

		//printf("%lld = %lld\n", st,cost);

		for (auto [to,del] : step(st)) {
			if (mindist.find(to) == mindist.end() || cost+del < mindist[to]) {
				mindist[to] = cost+del;
				pq.push({ mindist[to], to });
			}
		}
	}

	write(mindist[0]);
}

int main() {
	cin.tie(0)->sync_with_stdio(0);
	cin.exceptions(cin.failbit);

	int n; read(n);
	rep(i, 0, n) solve();
}

