using namespace std;
long long a, b, c, d;
map<long long, long long> dp;
long long rec (long long cur) {
  if (cur == 0) return 0;
  if (cur == 1) return d;
  if (dp.count(cur)) return dp[cur];
  long long res = (1. * cur * d > 1e18 ? (long long) 1e18 : cur * d);
  long long to = (cur + 1) / 2 * 2;
  res = min(res, abs(to - cur) * d + a + rec(to / 2));
  to = cur / 2 * 2;
  res = min(res, abs(to - cur) * d + a + rec(to / 2));
  to = (cur + 2) / 3 * 3;
  res = min(res, abs(to - cur) * d + b + rec(to / 3));
  to = cur / 3 * 3;
  res = min(res, abs(to - cur) * d + b + rec(to / 3));
  to = (cur + 4) / 5 * 5;
  res = min(res, abs(to - cur) * d + c + rec(to / 5));
  to = cur / 5 * 5;
  res = min(res, abs(to - cur) * d + c + rec(to / 5));
  return dp[cur] = res;
}
signed main() { 
  ios::sync_with_stdio(false); cin.tie(0);
  auto solve = [] () {
    long long n;
    cin >> n >> a >> b >> c >> d;
    dp.clear();
    return rec(n);
  };
  int t;
  cin >> t;
  while (t--) cout << solve() << endl;
  return 0;
}

