void Main()
{
	int T;
	cin >> T;
	vector<uint64_t> ans(T);
	rep(i, T)
	{
		uint64_t N, A, B, C, D;
		cin >> N >> A >> B >> C >> D;

		priority_queue<uint64_t> q;
		unordered_map<uint64_t, uint64_t> cost;
		q.push(N);
		cost[N] = 0;
		while (q.top() != 0)
		{
			auto p = q.top();
			q.pop();

			auto Push = [&](uint64_t j, uint64_t cc)
			{
				if (cost.find(j) == cost.end())
				{
					cost[j] = cc;
					q.push(j);
				}
				else
				{
					cost[j] = min(cost[j], cc);
				}
			};

			auto L = [&](uint64_t k, uint64_t F) {
				auto r = p / k;

				if (r == 0)
				{
					auto cc = cost[p] + p * D;
					Push(0, cc);

					if (p % k != 1)
					{
						cc = cost[p] + F + (k - p) * D;
						Push(1, cc);
					}
				}
				else
				{
					if (p % k == 0)
					{
						auto cc = cost[p] + F;
						Push(r, cc);
					}
					else
					{
						{
							auto cc = cost[p] + F + (p - r * k) * D;
							Push(r, cc);
						}

						{
							auto cc = cost[p] + F + ((r+1) * k - p) * D;
							Push(r+1, cc);
						}
					}
				}
			};

			L(5, C);
			L(3, B);
			L(2, A);

			Push(0, cost[p] + p * D);
		}

		ans[i] = cost[0];
	}

	rep(i, T)
	{
		cout << ans[i] << endl;
	}
}

int main()
{
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);
	std::cout << std::fixed << std::setprecision(15);

	Main();
	return 0;
}

