const int inf = 2e18;
struct Sol{
  int a,b,c,d;
  map<int,int> res;

  int licz(int n){
    auto xxx = res.find(n);
    if(xxx != res.end())return xxx->SE;
    int &ak = res[n];
    if(__int128(n) * d < __int128(inf)){
      ak = n * d;
    }else{
      ak = inf;
    }
    mini(ak, licz(n/2) + a + (n % 2) * d);
    mini(ak, licz(n/2+1) + a + (2 - n % 2) * d);
    mini(ak, licz(n/3) + b + (n % 3) * d);
    mini(ak, licz(n/3+1) + b + (3 - n % 3) * d);
    mini(ak, licz(n/5) + c + (n % 5) * d);
    mini(ak, licz(n/5+1) + c + (5 - n % 5) * d);
    return ak;
  }

  void run(){
    res[0] = 0;
    int n;
    cin >> n >> a >> b >> c >> d;
    cout << licz(n) << "\n";
  }
};

