ll dfs(ll N);

In void check(ll &ans,ll N,ll M,ll fac){
	ll cur = abs(N - fac * M) * D + dfs(M) + w[fac];
	if(cur < ans)ans = cur;
}

ll dfs(ll N){
//cout<<"dfs:N="<<N<<" f="<<f.count(N)<<endl;
	if(N <= 1)return sp[N];
	if(f.count(N))return f[N];
	ll ans = inf;
	if(inf / N >= D)ans = N * D;
	if(N % 2 == 0)checkmin(ans,dfs(N/2) + A);
	else{
		check(ans,N,N / 2,2);
		check(ans,N,(N+1) / 2,2);
	}
	if(N % 3 == 0)checkmin(ans,dfs(N/3) + B);
	else{
		check(ans,N,N / 3,3);
		check(ans,N,(N+2) / 3,3);	
	}
	if(N % 5 == 0)checkmin(ans,dfs(N/5) + C);
	else{
		check(ans,N,N / 5,5);
		check(ans,N,(N+4) / 5,5);
	}
//cout<<"N="<<N<<" ans="<<ans<<endl;
	return f[N] = ans;
}

