ll solve(ll n) {
    if (ans.find(n) != ans.end())
        return ans[n];
    if (!n)
        return 0;
    if (n == 1)
        return d;
    ll mn=1e18;
    if (n <= mn/d)
        mn=d*n;
    if (n%2 == 0)
        mn=min(mn,solve(n/2)+a);
    else {
        mn=min(mn,d*(n%2)+a+solve(n/2));
        mn=min(mn,d*(2-n%2)+a+solve(1+n/2));
    }
    if (n%3 == 0)
        mn=min(mn,solve(n/3)+b);
    else {
        mn=min(mn,d*(n%3)+b+solve(n/3));
        mn=min(mn,d*(3-n%3)+b+solve(1+n/3));
    }
    if (n%5 == 0)
        mn=min(mn,solve(n/5)+c);
    else {
        mn=min(mn,d*(n%5)+c+solve(n/5));
        mn=min(mn,d*(5-n%5)+c+solve(1+n/5));
    }
    ans[n]=mn;
    return mn;
}



