          } // elseなし：更新しないときはQにも追加しない
        }
        else{ // 初めてその値になった場合
          yen[5*tmp] = C + yen[tmp];
          if(yen[N] > yen[5*tmp]) Q.push(5*tmp); // 安ければQに追加
        }

        if(yen.count(tmp+1)){
          if(yen[tmp+1] > D + yen[tmp] ){ // 最安値更新
            yen[tmp+1] = D + yen[tmp];
            if(yen[N] > yen[tmp+1]) Q.push(tmp+1); // 安ければQに追加
          } // elseなし：更新しないときはQにも追加しない
        }
        else{ // 初めてその値になった場合
          yen[tmp+1] = D + yen[tmp];
          if(yen[N] > yen[tmp+1]) Q.push(tmp+1); // 安ければQに追加
        }

        if(yen.count(tmp-1)){
          if(yen[tmp-1] > D + yen[tmp] ){ // 最安値更新
            yen[tmp-1] = D + yen[tmp];
            if(yen[N] > yen[tmp-1]) Q.push(tmp-1); // 安ければQに追加
          } // elseなし：更新しないときはQにも追加しない
        }
        else{ // 初めてその値になった場合
          yen[tmp-1] = D + yen[tmp];
          if(yen[N] > yen[tmp-1]) Q.push(tmp-1); // 安ければQに追加
        }

      }
    }

    cout << yen[N] << endl;
  } // ここまででテストケース1つ分

}

