        long long n, a, b, c, d; std::cin >> n >> a >> b >> c >> d;
        std::map<long long, long long> mp;
        std::vector<long long> t = { 2,3,5 }, co = { a,b,c };
        mp[0] = 0; mp[1] = d;
        auto func = [&](auto &self, long long m) {
            if (mp.count(m)) return mp[m];
            long long ret = 2e18;
            if (m <= 1e9) ret = m*d;
            for (int i = 0; i < 3; i++) {
                ret = std::min(ret,
                    self(self, m / t[i]) + co[i] + (m%t[i])*d);
                ret = std::min(ret,
                    self(self, (m + t[i] - 1) / t[i])
                    + co[i] + (t[i] - m%t[i])*d);
            }
            return mp[m] = ret;
        };
        std::cout << func(func, n) << std::endl;
    }
    return 0;
}

