int inf = 1e18;

int get_ans(int n);

int chk(int ans, int x1, int n, int add, int x) {
	if(abs(n - x1 * x) >= ans / d + x)
		return ans;
	int y = get_ans(x1);
	if(y > ans)
		return ans;
	return min(ans, y + add + abs(n - x1 * x) * d);
}

int get_ans(int n) {
	if(was.count(n))
		return was[n];
	if(n == 0) 
		return 0;
	int ans = inf;
	if(n <= inf / d)
		ans = d * n;
	int x1 = n / 2;
	ans = chk(ans, x1, n, a, 2);
	// ans = min(ans, get_ans(x1) + a + abs(n - x1 * 2) * d);
	if(x1 + 1 != n)
		ans = chk(ans, x1 + 1, n, a, 2);
		// ans = min(ans, get_ans(x1 + 1) + a + abs(n - (x1 + 1) * 2) * d);

	x1 = n / 3;
	// ans = min(ans, get_ans(x1) + b + abs(n - x1 * 3) * d);
	ans = chk(ans, x1, n, b, 3);
	if(x1 + 1 != n)
		ans = chk(ans, x1 + 1, n, b, 3);
		// ans = min(ans, get_ans(x1 + 1) + b + abs(n - (x1 + 1) * 3) * d);

	x1 = n / 5;
	ans = chk(ans, x1, n, c, 5);
	// ans = min(ans, get_ans(x1) + c + abs(n - x1 * 5) * d);
	if(x1 + 1 != n)
		ans = chk(ans, x1 + 1, n, c, 5);
		// ans = min(ans, get_ans(x1 + 1) + c + abs(n - (x1 + 1) * 5) * d);
	was[n] = ans;
	return ans;
}

