  if(dp.count(n)) return dp[n];

  ll ret = 1e18;
  if(n <= ret / d) ret = n * d;

  ll f2 = (n / 2) * 2;
  ll c2 = ((n - 1) / 2 + 1) * 2;
  ll f3 = (n / 3) * 3;
  ll c3 = ((n - 1) / 3 + 1) * 3;
  ll f5 = (n / 5) * 5;
  ll c5 = ((n - 1) / 5 + 1) * 5;

  ret = min(ret, llabs(n - f2) * d + a + f(f2 / 2));
  ret = min(ret, llabs(n - c2) * d + a + f(c2 / 2));
  ret = min(ret, llabs(n - f3) * d + b + f(f3 / 3));
  ret = min(ret, llabs(n - c3) * d + b + f(c3 / 3));
  ret = min(ret, llabs(n - f5) * d + c + f(f5 / 5));
  ret = min(ret, llabs(n - c5) * d + c + f(c5 / 5));
  return dp[n] = ret;
}
