int bit_count(ll v)
{
	int ret=0;

	for(;v>0;)
	{
		ret++;
		v&=v-1;
	}

	return ret;
}


int msb(ll v)
{
	int ret=0;
	if(v & 0xFFFFFFFF00000000LL) v>>=32,ret+=32;
	if(v & 0xFFFF0000LL) v>>=16,ret+=16;
	if(v & 0xFF00) v>>=8,ret+=8;
	if(v & 0xF0) v>>=4,ret+=4;
	if(v & 0xC) v>>=2,ret+=2;
	if(v & 0x2) v>>=1,ret+=1;
	return ret;
}


template<typename X>
bool max_u(X&m, X v)
{
	if(m<v)
	{
		m=v;
		return true;
	}
	return false;
}


template<typename X>
bool min_u(X&m, X v)
{
	if(m>v)
	{
		m=v;
		return true;
	}
	return false;
}


ll solve_i(map<ll,ll>&dp, ll n, ll a, ll b, ll c, ll d)
{
	if(n==0) return 0;
	if(n==1) return d;
	if(n==2) return min(d*2, d+a);

	if(dp[n]>0) return dp[n];

	ll ans=d*bit_count(n)+a*msb(n);
	if(ans/n > d) min_u(ans, n*d);

	for(auto x : vector<pii> {{2,a},{3,b},{5,c}})
	{
		int r, cost;
		tie(r, cost)=x;
		if(n%r==0)
		{
			min_u(ans, cost+solve_i(dp, n/r, a, b, c, d));
		}
		else
		{
			ll updown=n-n/r*r;
			min_u(ans, cost+d*(updown)+solve_i(dp, n/r, a, b, c, d));
			min_u(ans, cost+d*(r-updown)+solve_i(dp, n/r+1, a, b, c, d));
		}
	}
	dp[n]=ans;

//printf("dp[%lld]=%lld\n", n, ans);

	return ans;
}

ll solve(ll n, ll a, ll b, ll c, ll d)
{
	map<ll,ll> dp;
	return solve_i(dp, n, a, b, c, d);
}


