                continue;
            for (const auto &c: Z[2]){
                if (a * b * c % c != 0 or a * b * c / c != a * b)
                    continue;
                A.push_back(a * b * c);
            }
        }
    }

    sort(A.begin(), A.end());
    map<int64_t, array<int, 3>> B;

    for (auto a: A){
        auto b = a;
        array<int, 3> C = {0, 0, 0};
        for (int i = 0; i < 3; i++){
            while (a % ppp[i] == 0){
                a /= ppp[i];
                C[i]++;
            }
