ll dfs(ll value, ll a, ll b, ll c, ll d, ll plus, ll minus){
  if(m[value]!=0)
    return m[value];
  if(value==0)
    return 0;

  ll res=LLINF;
  if(value%5==0){
    ll x=dfs(value/5,a,b,c,d,0,0);
    if(value/5*4<=LLMAX/d){
      if(x<=LLMAX-value/5*4*d)
        res=min(res,x+value/5*4*d);
    }
    if(x<=LLMAX-c)
      res=min(res,x+c);
  }
  if(value%3==0){
    ll x=dfs(value/3,a,b,c,d,0,0);
    if(value/3*2<=LLMAX/d){
      if(x<=LLMAX-value/3*2*d)
        res=min(res,x+value/3*2*d);
    }
    if(x<=LLMAX-b)
      res=min(res,x+b);
  }
  if(value%2==0){
    ll x=dfs(value/2,a,b,c,d,0,0);
    if(value/2<=LLMAX/d){
      if(x<=LLMAX-value/2*d)
        res=min(res,x+value/2*d);
    }
    if(x<=LLMAX-a)
      res=min(res,x+a);
  }
  if(minus<5){
    ll x=dfs(value-1,a,b,c,d,plus, minus+1);
    if(x<=LLMAX-d)
      res=min(res,x+d);
  }
  if(plus<5 && value>1){
    ll x=dfs(value+1,a,b,c,d,plus+1,minus);
    if(x<=LLMAX-d)
      res=min(res,x+d);
  }

  if(value<=LLMAX/d)
    res=min(res,value*d);

  m[value]=res;
  return res;
}

