ll ans = 1e18;
void dfs(ll now,ll cnt,ll a,ll b,ll c,ll d,ll n) {
	if (now == n) {
		ans = min(ans, cnt);
		return;
	}
	if (now > n) {
		ans = min(ans,cnt + d*(now - n));
		return;
	}
	if (now < n / 2) {
		dfs(now * 2, cnt + a, a, b, c, d, n);
		dfs(now * 3, cnt + b, a, b, c, d, n);
		dfs(now * 5, cnt + c, a, b, c, d, n);
	}
	else {
		dfs(now * 2, cnt + a, a, b, c, d, n);
		ans = min(ans, cnt + d * (n - now));
		return;
	}
	return;
}
int main() {
	ll t;
	cin >> t;
	REP(i, t) {
		ll n, a, b, c, d;
		ans = 1e18;
		cin >> n >> a >> b >> c >> d;
		dfs(1, d, a, b, c, d, n);
		cout << ans << endl;
	}
	return 0;
}

