#define INCANT cin.tie(0), cout.tie(0), ios::sync_with_stdio(0), cout << fixed << setprecision(20);
#define int long long
#define double long double
const int INF = 1e18, MOD = 1e9 + 7;
int n, a, b, c, d;
map<int, int> memo;

int dp(int n) {
    if (n == 0) return 0;
    if (n == 1) return d;
    if (memo.count(n)) return memo[n];

    int ret = INF;
    if (n < INF / d) ret = n * d;

    int up, down;
    down = n / 2 * 2;
    up = (n + 1) / 2 * 2;
    ret = min(ret, abs(down - n) * d + a + dp(down / 2));
    ret = min(ret, abs(up - n)   * d + a + dp(up / 2));

    down = n / 3 * 3;
    up = (n + 2) / 3 * 3;
    ret = min(ret, abs(down - n) * d + b + dp(down / 3));
    ret = min(ret, abs(up - n)   * d + b + dp(up / 3));

    down = n / 5 * 5;
    up = (n + 4) / 5 * 5;
    ret = min(ret, abs(down - n) * d + c + dp(down / 5));
    ret = min(ret, abs(up - n)   * d + c + dp(up / 5));

    memo[n] = ret;

    return ret;
}

signed main() {
    int t;
    cin>>t;
    for (int i = 0; i < t; i++) {
        memo.clear();
        cin>>n>>a>>b>>c>>d;
        cout<<dp(n)<<endl;
    }
}

