const vector<int64_t> divisor = {2, 3, 5};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int T;
  cin >> T;
  for (int i = 0; i < T; i++) {
    int64_t N;
    vector<int64_t> X(4);
    cin >> N;
    for (int i = 0; i < 4; i++) {
      cin >> X[i];
    }
    int64_t res = INT64_C(1) << 58;
    priority_queue<pair<int64_t, int64_t>, vector<pair<int64_t, int64_t>>,
                   greater<pair<int64_t, int64_t>>>
        que;
    que.push(make_pair(0, N));
    set<int64_t> st;
    while (!que.empty()) {
      auto q = que.top();
      que.pop();
      int64_t c = q.first, n = q.second;
      if (n == 0) res = min(res, c);
      if (st.find(n) != st.end()) continue;
      st.insert(n);
      for (int i = 0; i < 3; i++) {
        int64_t d = divisor[i];
        if (n % d == 0) {
          int64_t m = n / d, nc = c + X[i];
          if (n - m < (INT64_C(1) << 32)) nc = min(nc, c + (n - m) * X[3]);
          que.push(make_pair(nc, m));
        } else {
          int64_t m = (n / d) * d;
          que.push(make_pair(c + (n - m) * X[3], m));
          if (m + d < N + 100)
            que.push(make_pair(c + (m + d - n) * X[3], m + d));
        }
      }
    }
    cout << res << '\n';
  }
  return 0;
}

