std::map<long long, long long> mp;
long long A, B, C, D, N;

long long solve(long long n){
  if (mp[n]!=0) return mp[n];
  if (n==0){
    return mp[0];
  } else if (n==1){
    mp[1]=D;
    return mp[1];
  } else if (n==2){
    mp[2]=std::min(2*D, D+A);
    return mp[2];
  } else {
    long long ret=1e18;
    if (1e18/D>=n) ret=n*D;
    ret = std::min(ret, A+D*(n-2*(n/2))+solve(n/2) );
    ret = std::min(ret, A+D*(2*(1+n/2)-n)+solve(n/2+1) );
    ret = std::min(ret, B+D*(n-3*(n/3))+solve(n/3) );
    ret = std::min(ret, B+D*(3*(1+n/3)-n)+solve(n/3+1) );
    ret = std::min(ret, C+D*(n-5*(n/5))+solve(n/5) );
    ret = std::min(ret, C+D*(5*(1+n/5)-n)+solve(n/5+1) );
    mp[n] = ret;
    return mp[n];
  }
}

int main(){
  int T;
  scanf("%d", &T);
  std::vector<long long > out;
  for (int i=0; i<T; i++){
    mp.clear();
    scanf("%lld", &N);
    scanf("%lld", &A);
    scanf("%lld", &B);
    scanf("%lld", &C);
    scanf("%lld", &D);
    long long ans = solve(N);
    out.push_back(ans);
  }
  for (int i=0; i<T; i++){
    std::cout << out[i] << std::endl;
  }
  return 0;
}

