map<int,int> memo;
int DFS(int N,int A,int B, int C,int D)
{
  if(N == 0)return 0 ;
  if(N == 1) return D;
  if(memo.count(N))return memo[N];

  int l2 = (N/2)*2;
  int r2 = ((N+1)/2)*2;
  int l3 = (N/3)*3;
  int r3 = ((N+2)/3)*3;
  int l5 = (N/5)*5;
  int r5 = ((N+4)/5)*5;

  int res = 1e18;
  if(N < res/D) res = N*D;//全部Dのパターンはここで考慮される。
  res = min(res,abs(l2 - N)*D + A + DFS(l2/2,A,B,C,D));
  res = min(res,abs(r2 - N)*D + A + DFS(r2/2,A,B,C,D));

  res = min(res,abs(l3 - N)*D + B + DFS(l3/3,A,B,C,D));
  res = min(res,abs(r3 - N)*D + B + DFS(r3/3,A,B,C,D));

  res = min(res,abs(l5 - N)*D + C + DFS(l5/5,A,B,C,D));
  res = min(res,abs(r5 - N)*D + C + DFS(r5/5,A,B,C,D));

  memo[N] = res;

  return res;

}


