template<class T>
void update(T &x, const T &y) {
	if (x > y) x = y;
}

LL dfs(LL n) {
	// std::cout<<n<<std::endl;
	if (n == 0)
		return 0;
	if (map.count(n))
		return map[n];
	if (n == 1)
		return d;
	LL ans = 6e18;
	if (ans / n >= d)
		update(ans, n * d);
	LL k = n / 2 * 2;
	update(ans, dfs(n / 2) + a + d * (n - k));
	if (n > 2)
		update(ans, dfs(n / 2 + 1) + a + d * (k + 2 - n));
	k = n / 3 * 3;
	update(ans, dfs(n / 3) + b + d * (n - k));
	update(ans, dfs(n / 3 + 1) + b + d * (k + 3 - n));
	k = n / 5 * 5;
	update(ans, dfs(n / 5) + c + d * (n - k));
	update(ans, dfs(n / 5 + 1) + c + d * (k + 5 - n));
	return map[n] = ans;
}

