map<long long, long long> dp;
long long N, A, B, C, D;

long long solve(long long N) {
    if (dp.count(N))    return dp[N];

    long long ans = 1e18;
    if (N <= ans/D)     ans = min(ans, N*D);

    if (N%2==0)         ans = min(ans, solve(N/2)+A);
    else                ans = min(ans, solve(N/2)+A+D);

    if (N%3==0)         ans = min(ans, solve(N/3)+B);
    else if (N%3==1)    ans = min(ans, solve(N/3)+B+D);
    else                ans = min(ans, solve(N/3+1)+B+D);

    if (N%5==0)         ans = min(ans, solve(N/5)+C);
    else if (N%5==1)    ans = min(ans, solve(N/5)+C+D);
    else if (N%5==2)    ans = min(ans, solve(N/5)+C+D+D);
    else if (N%5==3)    ans = min(ans, solve(N/5+1)+C+D+D);
    else                ans = min(ans, solve(N/5+1)+C+D);

    return dp[N] = ans;
}

