const LLONG Digit(LLONG n)
{
    LLONG ret = 0;
    while (n)
    {
        n /= 10;
        ++ret;
    }
    return ret;
}

const LLONG DFS(const LLONG n)
{
    if (num2MinCostMap.count(n)) return num2MinCostMap[n];
    LLONG minCost = Digit(n) * Digit(D) <= 18 ? n * D : 9e18;
    for (int i = 0; i < 3; ++i)
    {
        const LLONG k = ks[i];
        const LLONG lower = n / k;
        const LLONG upper = lower + 1;
        minCost = min(minCost,
            min(DFS(lower) + costs[i] + (n - lower * k) * D,
                DFS(upper) + costs[i] + (upper * k - n) * D));
    }
    return num2MinCostMap[n] = minCost;
}

