const long long INF = LLONG_MAX / 2;

int main()
{
    int t;
    cin >> t;

    while(--t >= 0){
        long long n;
        int a, b, c, d;
        cin >> n >> a >> b >> c >> d;

        const int mag[] = {2, 3, 5};
        const int cost[] = {a, b, c};

        map<long long, long long> dp;
        priority_queue<
            pair<long long, long long>,
            vector<pair<long long, long long> >,
            greater<pair<long long, long long> > > pq;
        dp[n] = 0;
        pq.push(make_pair(0, n));

        long long ans = INF;
        if(d < INF / n)
            ans = n * d;

        while(!pq.empty()){
            auto [tmp, x] = pq.top();
            pq.pop();
            if(dp[x] < tmp || ans < tmp)
                continue;

            if(x < INF / d)
                ans = min(ans, d * x + tmp);

            for(int i=0; i<3; ++i){
                long long tmp1 = tmp + cost[i] + (x % mag[i]) * d;
                long long x1 = x / mag[i];
                if(dp.find(x1) == dp.end() || tmp1 < dp[x1]){
                    dp[x1] = tmp1;
                    pq.push(make_pair(tmp1, x1));
                }

                if(x % mag[i] != 0){
                    long long tmp2 = tmp + cost[i] + (mag[i] - x % mag[i]) * d;
                    long long x2 = x / mag[i] + 1;
                    if(dp.find(x2) == dp.end() || tmp2 < dp[x2]){
                        dp[x2] = tmp2;
                        pq.push(make_pair(tmp2, x2));
                    }
                }
            }
        }
        cout << ans << endl;
    }

    return 0;
}

