long long dp[69][69][69][49];
long long power2[69];
long long power3[69];
long long power5[69];

void init() {
	power2[0] = 1; for (int i = 1; i <= 62; i++) power2[i] = (2LL * power2[i - 1]);
	power3[0] = 1; for (int i = 1; i <= 62; i++) power3[i] = (3LL * power3[i - 1]);
	power5[0] = 1; for (int i = 1; i <= 62; i++) power5[i] = (5LL * power5[i - 1]);
}

long long solve(long long N, long long A, long long B, long long C, long long D) {
	for (int i = 0; i <= 62; i++) {
		for (int j = 0; j <= 62; j++) {
			for (int k = 0; k <= 62; k++) {
				for (int l = 0; l <= 40; l++) dp[i][j][k][l] = (1LL << 60);
			}
		}
	}

	dp[0][0][0][20] = 0;
	for (int i = 0; i <= 61; i++) {
		for (int j = 0; j <= 61; j++) {
			for (int k = 0; k <= 61; k++) {
				double I = 0.3010 * i + 0.4771 * j + 0.6990 * k;
				if (I >= 18.7) break;
				long long val = power2[i] * power3[j] * power5[k];

				for (int l = 0; l <= 39; l++) dp[i][j][k][l + 1] = min(dp[i][j][k][l + 1], dp[i][j][k][l] + D);
				for (int l = 39; l >= 0; l--) dp[i][j][k][l] = min(dp[i][j][k][l], dp[i][j][k][l + 1] + D);

				// 2 倍にする
				long long A1 = (N / val) % 2LL;
				for (int l = -20; l <= 20; l++) {
					int p = 20 + 2 * l - A1;
					if (0 <= p && p <= 40) dp[i + 1][j][k][20 + l] = min(dp[i + 1][j][k][20 + l], dp[i][j][k][p] + A);
				}

				// 3 倍にする
				long long B1 = (N / val) % 3LL;
				for (int l = -20; l <= 20; l++) {
					int p = 20 + 3 * l - B1;
					if (0 <= p && p <= 40) dp[i][j + 1][k][20 + l] = min(dp[i][j + 1][k][20 + l], dp[i][j][k][p] + B);
				}

				// 5 倍にする
				long long C1 = (N / val) % 5LL;
				for (int l = -20; l <= 20; l++) {
					int p = 20 + 5 * l - C1;
					if (0 <= p && p <= 40) dp[i][j][k + 1][20 + l] = min(dp[i][j][k + 1][20 + l], dp[i][j][k][p] + C);
				}
			}
		}
	}

	long long Answer = (1LL << 60);
	for (int i = 0; i <= 62; i++) {
		for (int j = 0; j <= 62; j++) {
			for (int k = 0; k <= 62; k++) {
				double I = 0.3010 * i + 0.4771 * j + 0.6990 * k;
				if (I >= 18.7) break;
				long long val = power2[i] * power3[j] * power5[k];

				for (int l = 0; l <= 40; l++) {
					long long base = abs((N / val) + (l - 20));
					if (base >= 1 && (1LL << 61) / base < D) continue;
					Answer = min(Answer, dp[i][j][k][l] + base * D);
				}
			}
		}
	}
	return Answer;
}

int main() {
	long long T, N, A, B, C, D; init();
	cin >> T;
	for (int i = 1; i <= T; i++) {
		cin >> N >> A >> B >> C >> D;
		cout << solve(N, A, B, C, D) << endl;
	}
	return 0;
}

