map<long long, long long> mp;

long long calc(long long n) {
    int i;
    long long ans = 1e18;

    if (n < 0) return 1e18;
    if (mp.count(n)) return mp[n];
    if (n == 0) return mp[n] = 0;

    mp[n] = 1e18;

    for (int i = -1; i <= 1; i++) {
        if ((n + i) % 2 == 0) ans = min(ans, calc((n + i) / 2) + a + abs(i) * d);
    }

    for (int i = -2; i <= 2; i++) {
        if ((n + i) % 3 == 0) ans = min(ans, calc((n + i) / 3) + b + abs(i) * d);
    }

    for (int i = -4; i <= 4; i++) {
        if ((n + i) % 5 == 0) ans = min(ans, calc((n + i) / 5) + c + abs(i) * d);
    }

    if (n <= 1e9) ans = min(ans, n * d);

    return mp[n] = ans;
}

