int main() {
    int Case;
    cin >> Case;
    while(Case--) {
        long long N, A, B, C, D, ans = 0;
        long long t, tA, tB, tC;
        double c, ca, cb, cc;
        cin >> N >> A >> B >> C >> D;
        priority_queue<pair<long long, int>, vector<pair<long long, int> >, greater<pair<long long , int> > > que;
        int upp;
        if(N <= 100030) upp = 100050;
        else upp = 100000;
        dist[0] = 0;
        que.emplace(0, 0);
        for(int i = 1; i <= upp; ++i)
            dist[i] = inf;
        while(!que.empty()) {
            pair<long long, int> pr = que.top(); que.pop();
            if(pr.first > dist[pr.second]) continue;
            int u = pr.second, v;
            v = u * 2;
            if(v <= upp && dist[u] + A < dist[v]) {
                dist[v] = dist[u] + A;
                que.emplace(dist[v], v);
            }
            v = u * 3;
            if(v <= upp && dist[u] + B < dist[v]) {
                dist[v] = dist[u] + B;
                que.emplace(dist[v], v);
            }
            v = u * 5;
            if(v <= upp && dist[u] + C < dist[v]) {
                dist[v] = dist[u] + C;
                que.emplace(dist[v], v);
            }
            v = u + 1;
            if(v <= upp && dist[u] + D < dist[v]) {
                dist[v] = dist[u] + D;
                que.emplace(dist[v], v);
            }
            v = u - 1;
            if(v >= 0 && v <= upp && dist[u] + D < dist[v]) {
                dist[v] = dist[u] + D;
                que.emplace(dist[v], v);
            }
        }
        for(int i = -10; i <= 10; ++i)
            f[i] = D * abs(i);
        while(N > upp) {
            ca = inf;
            cb = inf;
            cc = inf;
            for(int i = -10; i <= 10; ++i) {
                if(N + i < 0) continue;
                if((N + i) % 2 == 0) {
                    t = (N + i) / 2;
                    if(t >= N) continue;
                    c = 1.0 * (A + f[i]) / (N - t);
                    if(c < ca) {
                        ca = c;
                        tA = t;
                    }
                }
                if((N + i) % 3 == 0) {
                    t = (N + i) / 3;
                    if(t >= N) continue;
                    c = 1.0 * (B + f[i]) / (N - t);
                    if(c < cb) {
                        cb = c;
                        tB = t;
                    }
                }
                if((N + i) % 5 == 0) {
                    t = (N + i) / 5;
                    if(t >= N) continue;
                    c = 1.0 * (C + f[i]) / (N - t);
                    if(c < cc) {
                        cc = c;
                        tC = t;
                    }
                }
            }
            if(ca <= cb && ca <= cc && ca <= D) {
                ans += A + f[tA * 2 - N];
                N = tA;
            } else if(cb <= ca && cb <= cc && cb <= D) {
                ans += B + f[tB * 3 - N];
                N = tB;
            } else if(cc <= ca && cc <= cb && cc <= D) {
                ans += C + f[tC * 5 - N];
                N = tC;
            } else {
                ans += D * N;
                N = 0;
            }
        }
        printf("%lld\n", ans + dist[N]);
    }
    return 0;
}

