LL solve() {
	LL n, a, b, c, d;
	cin >> n;
	cin >> a >> b >> c >> d;
	LL ans = (a + d) * 100;

	map<LL, LL> f;
	f[n] = 0;
	auto push = [&](LL v, LL c) {
		if(f.count(v)) chmin(f[v], c);
		else f[v] = c;
	};
	while(f.size()) {
		LL v = f.rbegin()->first, cost = f.rbegin()->second;
//		eprintf("%lld: %lld\n", v, cost);
		f.erase(v);
		if(v == 0) break;
		if((LL)1e15 / d >= v) chmin(ans, v * d + cost);
		push(v / 2, v % 2 * d + a + cost);
		if(v % 2 > 0 && v > 1)
			push(v / 2 + 1, (2 - v % 2) * d + a + cost);
		push(v / 3, v % 3 * d + b + cost);
		if(v % 3 > 0 && v > 1)
			push(v / 3 + 1, (3 - v % 3) * d + b + cost);
		push(v / 5, v % 5 * d + c + cost);
		if(v % 5 > 0 && v > 1)
			push(v / 5 + 1, (5 - v % 5) * d + c + cost);
	}
	return ans;
}

