            if (v % op.first) {
                nc = c + (op.first - v % op.first) * D + op.second;
                pq.emplace(nc, v / op.first + 1);
            }
        }
        if (double(v) * D + c <= INF) {
            pq.emplace(c + v * D, 0);
        }
    }
