const int  INF = 1 << 30;
const ll INFL = 1LL << 60;
const ll mod = 998244353;



ll dfs(ll a, ll b, ll c, ll d, ll n) {
	map<ll, ll> m;

	min_priority_queue<pair<ll, ll>> q;

	q.push({ 0,n });
	if (n == 1)return d;


	ll ans = INFL;

	if (n < 5e9)ans = d * n;
	while (!q.empty()) {
		auto k = q.top();
		q.pop();
		if (k.first >= ans)break;
		//cerr << k.first << ' ' << k.second << endl;
		//cerr << q.size() << endl;
		if (m[k.second] != k.first)continue;
		if (k.second == 1) {
			ans = min(ans, k.first + d);
			continue;
		}
		if (k.second < 5e9)ans = min(ans, d*k.second + k.first);

		for (ll i = -4; i <= 4; i++) {
			ll cost = abs(i*d);

			if (k.second + i <= 0)continue;

			if ((k.second + i) % 2 == 0 && abs(i) < 2) {
				if (m[(k.second + i) / 2] > k.first + cost + a || m[(k.second + i) / 2] == 0) {
					q.push({ k.first + cost + a,(k.second + i) / 2 });
					m[(k.second + i) / 2] = k.first + cost + a;
				}
			}
			if ((k.second + i) % 3 == 0 && abs(i) < 3) {
				if (m[(k.second + i) / 3] > k.first + cost + b || m[(k.second + i) / 3] == 0){
					q.push({ k.first + cost + b,(k.second + i) / 3 });
					m[(k.second + i) / 3] = k.first + cost + b;
				}
			}
			if ((k.second + i) % 5 == 0) {
				if (m[(k.second + i) / 5] > k.first + cost + c || m[(k.second + i) / 5] == 0) {
					q.push({ k.first + cost + c,(k.second + i) / 5 });
					m[(k.second + i) / 5] = k.first + cost + c;
				}
			}
		}

	}
	return ans;


}




