using namespace std;

static unordered_map<int64_t, int64_t> memo;
int64_t solve(int64_t n, int64_t a, int64_t b, int64_t c, int64_t d)
{
	if (n == 0) return 0;
	if (n == 1) return d;

	auto it = memo.find(n);
	if (it != memo.end()) {
		return it->second;
	}

	int64_t ans = INT64_MAX;
	if (n <= INT64_MAX / d) {
		ans = n * d;
	}

	if (n % 2 == 0) {
		ans = min(ans, solve(n/2, a, b, c, d) + a);
	}
	else {
		ans = min(ans, solve((n + 1) / 2, a, b, c, d) + a + d);
		ans = min(ans, solve((n - 1) / 2, a, b, c, d) + a + d);
	}
	if (n % 3 == 0) {
		ans = min(ans, solve(n / 3, a, b, c, d) + b);
	}
	else {
		int64_t r = n % 3;
		ans = min(ans, solve((n - r) / 3, a, b, c, d) + b + r * d);
		ans = min(ans, solve((n + 3 - r) / 3, a, b, c, d) + b + (3 - r) * d);
	}
	if (n % 5 == 0) {
		ans = min(ans, solve(n / 5, a, b, c, d) + c);
	}
	else {
		int64_t r = n % 5;
		ans = min(ans, solve((n - r) / 5, a, b, c, d) + c + r * d);
		ans = min(ans, solve((n + 5 - r) / 5, a, b, c, d) + c + (5 - r) * d);
	}

	memo.insert({ n, ans });

	return ans;
}

