ll intceil(ll a, ll b){
    if(a < 0){
      a *= -1;
      b *= -1;
    }
    if(b >= 0) return (a + b - 1 ) / b;
    return a / b;
}

ll intfloor(ll a, ll b){
    if(a < 0){
      a *= -1;
      b *= -1;
    }
    if(b >= 0) return a / b;
    return (a - b + 1) / b;
}

void addM(ll &a, ll b) {
    a += b;
    if (a >= MOD) a -= MOD;
}

void mulM(ll &a, ll b) {
    a = ((a%MOD)*(b%MOD))%MOD ;
}

ll powM(ll a,ll b) {
    ll ret = 1;
    ll tmp = a;
    while(b>0) {
        if((b&1)==1) ret = (ret * tmp) % MOD;
        tmp = (tmp * tmp) % MOD;
        b = b >> 1;
    }
    return ret;
}

// mod. m での a の逆元 a^{-1} を計算する
ll modinv(ll a, ll m) {
    ll b = m, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

// ラングレンス圧縮
vector<pair<char, int>> rang_com(string s){
  vector<pair<char, int>> ret;
  string t = s;
  t.erase(unique(all(t)), t.end());
  int now = 0;
  int pre = 0;
  for(auto ct : t){
    while(now < s.size() && s[now] == ct) now++;
    if(ret.size() == 0){
      ret.push_back({ct, now});
    } else {
      ret.push_back({ct, now - pre});
    }
    pre = now;
  }
  return ret;
}

ll mypow(ll a, ll t) {
  if (!t) return 1;
  ll ret = mypow(a, t>>1);
  ret *= ret;
  if (t&1) ret *= a;
  return ret;
}

ll N, A, B, C, D;
map<ll,ll> dp;

ll solve(ll N){
  if(N == 0){
    return 0;
  }
  if(dp.find(N) != dp.end()){
    return dp[N];
  }
  if(N == 1){
    return D;
  }
  ll ret = longinf;
  if(N%2 == 0){
    chmin(ret, solve(N/2) + A);
  } else {
    chmin(ret, min(solve(N/2) + A + D, solve(N/2+1) + A + D));
  }

  if(N%3 == 0){
    chmin(ret, solve(N/3) + B);
  } else if(N%3 == 1){
    chmin(ret, solve(N/3) + B + D);
  } else {
    chmin(ret, solve(N/3+1) + B + D);
  }

  if(N%5 == 0){
    chmin(ret, solve(N/5) + C);
  } else if(N%5 == 1){
    chmin(ret, solve(N/5) + C + D);
  } else if(N%5 == 2){
    chmin(ret, solve(N/5) + C + D + D);
  } else if(N%5 == 3){
    chmin(ret, solve(N/5+1) + C + D + D);
  } else {
    chmin(ret, solve(N/5+1) + C + D);
  }
  return dp[N] = ret;
}

