lint n; 
lint A,B,C,D;
map<lint, lint> mem;

lint brut(lint n) {
	lint ans = 0;
	if (n == 0) return 0;
	if (n%2==1) return A + D + brut(n/2);
	return A + brut(n/2);
}

void solve() {
	scanf("%lld", &n);
	scanf("%lld %lld %lld %lld", &A, &B,&C,&D);
	mem.clear();
	set<lint> que;
	que.insert(n);
	mem[n] = 0;
	FOR(i,0,100) {
		if (n >= i) {
			que.insert(n-i);
			mem[n-i] = i*1LL*D;
		}
		que.insert(n+i);
		mem[n+i] = i*1LL*D;
	}
	int pos = 0;
	lint ans = brut(n); 
	mem[n] = 0;
	while (!que.empty() && pos < 1e6) {
		lint kto = *que.begin(); 
		lint ile = mem[kto];
		que.erase(que.begin());
		lint nkto, nile;
		{
			nkto = kto/5;
			nile = ile + C + (kto%5)*1LL*D;
			if (nile < ans) {
				if (mem.find(nkto)==mem.end() || mem[nkto] > nile) {
					mem[nkto] = nile;
					que.insert(nkto);
				}
			}
			if (nkto <= (ans-nile)/D + 1) {
				ans = min(ans, nile + nkto*1LL*D);
			}
		} 
		{
			nkto = kto/3;
			nile = ile + B + (kto % 3)*1LL*D;
			if (nile < ans) {
				if (mem.find(nkto)==mem.end() || mem[nkto] > nile) {
					mem[nkto] = nile;
					que.insert(nkto);
				}
			}
			if (nkto <= (ans-nile)/D + 1) {
				ans = min(ans, nile + nkto*1LL*D);
			}
		} 
		{
			nkto = kto/2;
			nile = ile + A + (kto% 2)*1LL*D;
			if (nile < ans) {
				if (mem.find(nkto)==mem.end() || mem[nkto] > nile) {
					mem[nkto] = nile;
					que.insert(nkto);
				}
			}
			if (nkto <= (ans-nile)/D + 1) {
				ans = min(ans, nile + nkto*1LL*D);
			}
		}
		{
			nkto = kto/5 + 1;
			nile = ile + C + (5-(kto%5))*D;
			if (nile < ans) {
				if (mem.find(nkto)==mem.end() || mem[nkto] > nile) {
					mem[nkto] = nile;
					que.insert(nkto);
				}
			}
		} 
		{
			nkto = kto/3 + 1;
			nile = ile + B + (3-(kto % 3))*1LL*D;
			if (nile < ans) {
				if (mem.find(nkto)==mem.end() || mem[nkto] > nile) {
					mem[nkto] = nile;
					que.insert(nkto);
				}
			}
			if (nkto <= (ans-nile)/D + 1) {
				ans = min(ans, nile + nkto*1LL*D);
			}
		} 
		{
			nkto = kto/2 + 1;
			nile = ile + A + (2-(kto% 2))*1LL*D;
			if (nile < ans) {
				if (mem.find(nkto)==mem.end() || mem[nkto] > nile) {
					mem[nkto] = nile;
					que.insert(nkto);
				}
			}
			if (nkto <= (ans-nile)/D + 1) {
				ans = min(ans, nile + nkto*1LL*D);
			}
		}
	}
	printf("%lld\n", ans);
}

