    Int l3 = (N/3)*3;
    Int r3 = ((N+1)/3)*3;

    Int l5 = (N/5)*5;
    Int r5 = ((N+1)/5)*5;

    Int res = 1e18;
    if (N < res/D) res = N * D;

    res = llmin(res, llabs(N-l2)*D + A + solve(l2/2));
    res = llmin(res, llabs(r2-N)*D + A + solve(r2/2));

    res = llmin(res, llabs(N-l3)*D + B + solve(l3/2));
    res = llmin(res, llabs(r3-N)*D + B + solve(r3/2));

    res = llmin(res, llabs(N-l5)*D + C + solve(l5/2));
    res = llmin(res, llabs(r5-N)*D + C + solve(r5/2));

    m[N] = res;

    return res;
}

int main() {
    int T; cin >> T;

    while(T --> 0) {
        m.clear();
        Int N; cin >> N;
        cin >> A >> B >> C >> D;

        cout << solve(N) << endl;
    }

}

