class SearchNode{public:
  long long currC;
  long long currV;
};

class Coins{
public:


  long long getMinCoins(long long n, long long a, long long b, long long c, long long d){

    long long currC = d;
    long long retV = minPathLoop(currC,1,n,a,b,c,d);
    return retV;
  }

  long long minPathLoop(long long currC, long long currV,long long n, long long a, long long b, long long c, long long d){
    long long minCoins = -1LL;
    vector<SearchNode>currLayer;
    vector<SearchNode>nxtLayer;    
    SearchNode sn;
    sn.currC = currC;
    sn.currV = currV;
    currLayer.push_back(sn);
    while(currLayer.size()>0){
      for(int i=0;i<currLayer.size();i++){
	SearchNode sn = currLayer[i];
	//	cout<<"minPathLoop i "<<i<<", currC "<<sn.currC<<", currV "<<sn.currV<<endl;
	if((minCoins<0LL)||(sn.currC<minCoins)){
	  if(sn.currV==n){
	    if((sn.currC<minCoins)||(minCoins<0LL)){
	      minCoins = sn.currC;
	    }
	  }else if(sn.currV>n){
	    long long nCoins = sn.currC+abs(sn.currV-n)*d;
	    if((nCoins<minCoins)||(minCoins<0LL)){
	      minCoins = nCoins;
	    }
	  }else{
	    //currV<n
	    SearchNode sna,snb,snc,snd;
	    sna.currC = sn.currC+a;
	    snb.currC = sn.currC+b;
	    snc.currC = sn.currC+c;
	    snd.currC = sn.currC+d;
	    sna.currV = sn.currV*2LL;
	    snb.currV = sn.currV*3LL;
	    snc.currV = sn.currV*5LL;
	    snd.currV = sn.currV+1LL;
	    nxtLayer.push_back(sna);
	    nxtLayer.push_back(snb);
	    nxtLayer.push_back(snc);
	    nxtLayer.push_back(snd);	    
	  }
	}
      }
      currLayer = nxtLayer;
      nxtLayer.clear();
    }
    return minCoins;
  }
};

