ll solve(ll N) {
    if (N == 0) return 0;
    if (N == 1) return D;
    if (mp.find(N) != mp.end()) return mp[N];
    ll tmp1 = N % 2 == 0 ? solve(N / 2) + A :
                           min(solve(N / 2), solve(N / 2 + 1)) + A + D;
    ll tmp2 = N % 3 == 0 ? solve(N / 3) + B :
                           min(solve(N / 3) + (N % 3) * D,
                               solve(N / 3 + 1) + (3 - N % 3) * D) +
                               B;
    ll tmp3 = N % 5 == 0 ? solve(N / 5) + C :
                           min(solve(N / 5) + (N % 5) * D,
                               solve(N / 5 + 1) + (5 - N % 5) * D) +
                               C;
    ll tmp = min(min(tmp1, tmp2), tmp3);
    if (1. * D * N - 100000 < tmp) tmp = min(tmp, D * N);
    return mp[N] = tmp;
}

