using P = pair<int, int>;

ll N, A, B, C, D;
map<ll, ll> memo;

ll dfs(ll X) {
    // Xをすでに計算した場合はメモした値を返す
    if (memo.count(X)) {
        // cout << "X already" << X << endl;
        return memo[X];
    }

    // メモがない場合は、6通りのパターンを探索する
    ll min_costs = 1e18;
    ll d2f = (X/2)*2, d2c = ((X+1)/2)*2, 
        d3f = (X/3)*3, d3c = ((X+2)/3)*3, 
        d5f = (X/5)*5, d5c = ((X+4)/5)*5;
    min_costs = min(min_costs, dfs(d2f/2) + abs(X - d2f) * D + A);
    min_costs = min(min_costs, dfs(d3f/3) + abs(X - d3f) * D + B);
    min_costs = min(min_costs, dfs(d5f/5) + abs(X - d5f) * D + C);
    min_costs = min(min_costs, dfs(d2c/2) + abs(X - d2c) * D + A);
    min_costs = min(min_costs, dfs(d3c/3) + abs(X - d3c) * D + B);
    min_costs = min(min_costs, dfs(d5c/5) + abs(X - d5c) * D + C);

    // min_costs > X*Dの場合、Dを使って移動した方が安い
    if (X < min_costs / D) min_costs = X * D;
    memo[X] = min_costs;
    return memo[X];
}

