	if (n == 1) return d;
	if (dp.count(n)) return dp[n];
	ll res = mult(n, d);
	{
		int pr = n % 2, ne = 2 - pr;
		res = min(res, go((n - pr) / 2) + a + d * pr);
		if ((n + ne) / 2 < n)
			res = min(res, go((n + ne) / 2) + a + d * ne);
	}
	{
		int pr = n % 3, ne = 3 - pr;
		res = min(res, go((n - pr) / 3) + b + d * pr);
		if ((n + ne) / 3 < n)
			res = min(res, go((n + ne) / 3) + b + d * ne);
	}
	{
		int pr = n % 5, ne = 5 - pr;
		res = min(res, go((n - pr) / 5) + c + d * pr);
		if ((n + ne) / 5 < n)
			res = min(res, go((n + ne) / 5) + c + d * ne);
	}
//	cout << n << ' ' << res << endl;
	return dp[n] = res;
}

vector <ll> w;

inline ll get(ll n, ll base, ll cost) {
	if (base == 1) return mult(n, d);
	w.clear();
	while(n) {
		w.pb(n % base);
		n /= base;
	}
	ll res = 0;
	for (int i = sz(w) - 1; i >= 0; --i) {
		ll t1 = mult(w[i], d);
		ll t2 = add(mult(base - w[i], d), d);
		if (i == sz(w) - 1) t2 = add(t2, cost);
		res = add(res, min(t1, t2));
		if (i) res = add(res, cost);
	}
	return res;
}

inline void solve() {
	scanf(I64 "" I64 "" I64 "" I64 "" I64, &n, &a, &b, &c, &d);
	dp.clear();
	ll ans = go(n);
	for (ull cur = 1, i = 0; cur <= INF; cur *= 2, ++i)
		for (ull cur2 = cur, j = 0; cur2 <= INF; cur2 *= 3, ++j)
			for (ull cur3 = cur2, k = 0; cur3 <= INF; cur3 *= 5, ++k) {
				ans = min(ans, get(n, cur3, a * i + b * j + c * k));
//				cout << cur3 << ' ' << ans << endl;
			}
	printf(I64"\n", ans);
}

