long long f(long long N) {
  if (N == 0) return 0;

  long long res = 1e18;

  int num[] = {2, 3, 5};
  for (int i = 0; i < 3; ++i) {
    if (N % num[i] == 0) {
      res = min(res, f(N/num[i]));
      continue;
    }

    int d = N % num[i];
    res = min(res, f((N-d) / num[i]));
    d = num[i] - d;
    res = min(res, f((N+d) / num[i]));
  }

  return res;
}

