llint solve(llint n, llint doubleC, llint tripleC, llint fifthC, llint plusC){
	llint currNum = 1;
	llint coin = plusC;
	llint quote5 = -1;
	llint quote3 = -1;
	llint quote2 = -1;
	llint quote1 = -1;
	bool end5 = false;
	bool end3 = false;
	bool end2 = false;

	while(currNum != n){

		if(!end5 && currNum * 5 >= n){
			llint dif5 = abs(n - (currNum * 5));
			quote5 = fifthC + dif5 * plusC + coin;
			end5 = true;
		}

		if(!end3 && currNum * 3 >= n){
			llint dif3 = abs(n - (currNum * 3));
			quote3 = tripleC + dif3 * plusC + coin;
			end3 = true;
		}

		if(!end2 && currNum * 2 >= n){
			llint dif2 = abs(n - (currNum * 2));
			quote2 = doubleC + dif2 * plusC + coin;
			end2 = true;
		}

		if(end2 && end3 && end5){
			quote1 = abs((n - currNum)) * plusC + coin;
			break;
		}

		cout << currNum << endl;

		double one2 = doubleC / (double)(currNum * 2 - currNum);
		double one3 = (!end3) ? (tripleC / (double)(currNum * 3 - currNum)) : 10e18;
		double one5 = (!end5) ? (fifthC / (double)(currNum * 5 - currNum)) : 10e18;

		if(one3 < one5){
			if(one3 <= one2){
				if(one3 <= plusC){
					currNum *= 3;
					coin += tripleC;
				}else{
					currNum++;
					coin += plusC;
				}
			}else if(one2 <= plusC){
				currNum *= 2;
				coin += doubleC;
			}else{
				currNum++;
				coin += plusC;
			}
		}else{
			if(one5 <= one2){
				if(one5 <= plusC){
					currNum *= 5;
					coin += fifthC;
				}else{
					currNum++;
					coin += plusC;
				}
			}else if(one2 <= plusC){
				currNum *= 2;
				coin += doubleC;
			}else{
				currNum++;
				coin += plusC;
			}
		}
	}
	return min({quote1, quote2, quote3, quote5});
}

