void solve(ll *min,ll cost,ll n,ll a,ll b,ll c,ll d)
{
    if(n<=0) return;
    if(n==1){
        if(*min>cost+d) *min=cost+d;
        return;
    }
    ll r3 = n%3;
    if(r3==0){
        solve(min,cost+b,n/3,a,b,c,d);
    }else{
        if(r3==1){
            solve(min,cost+d+b,(n-1)/3,a,b,c,d);
        }else{
            solve(min,cost+d+b,(n+1)/3,a,b,c,d);
        }
    }

    ll r5 = n%5;
    if(r5==0){
        solve(min,cost+c,n/5,a,b,c,d);
    }else{
        if(r5==1){
            solve(min,cost+d+c,(n-1)/5,a,b,c,d);
        }else if(r5==2){
            solve(min,cost+2*d+c,(n-2)/5,a,b,c,d);
        }else if(r5==3){
            solve(min,cost+2*d+c,(n+2)/5,a,b,c,d);
        }else{
            solve(min,cost+d+c,(n+1)/5,a,b,c,d);
        }
    }

    ll r2 = n%2;
    if(r2==0){
        solve(min,cost+a,n/2,a,b,c,d);
    }else{
        solve(min,cost+a+d,(n-1)/2,a,b,c,d);
        solve(min,cost+a+d,(n+1)/2,a,b,c,d);
    }

}

