                    x =  min(c, diff/5);
                    cost += x*D;
                    diff -= x;
                    y = min(b, diff/3);
                    cost += y*D;
                    diff -= y;
                    cost += diff*D;
                    ans = min(D+cost, ans);
                    break;
                }
                for (ll a = 0; a <= l-b-c+1; a++) {
                    val = pow(5, c);
                    val *= pow(3, b);
                    val *= pow(2, a);
                    cost = a*A+b*B+c*C;
                    if (N >= val) {
                        diff = N - val;
                    } else {
                        diff = val - N;
                    }
                    x = min(c, diff/5);
                    diff -= 5*x;
                    y = min(b, diff/3);
                    diff -= 3*y;
                    z = min(a, diff/2);
                    diff -= 2*z;
                    cost += (x+y+z+diff)*D;
                    ans = min(D+cost, ans);
                    if (val > N) {
                        break;
                    }
                }
            }
        }
        answer[i] = ans;
    }
    for (int i = 0; i < T; i++) {
        cout << answer[i] << endl;
    }
}

