ll ans(ll n, ll a, ll b, ll c, ll d, map<ll,ll> memo){
  if(n==1) return d;

  ll ko1,ko2,ko3,ko4,ko5,ko6,ko7;
  if(memo.count(n/2)) ko1 = memo.at(n/2) + (n%2)*d + a;
  else ko1 = ans(n/2,a,b,c,d,memo) + (n%2)*d + a;
  if(memo.count((n+1)/2)) ko2 = memo.at((n+1)/2) + (n%2)*d + a;
  else ko2 = ans((n+1)/2,a,b,c,d,memo) + (n%2)*d + a; 

  if(memo.count(n/3)) ko3 = memo.at(n/3) + (n%3)*d + b;
  else ko3 = ans(n/3,a,b,c,d,memo) + (n%3)*d + b;
  if(memo.count((n+2)/3)) ko4 = memo.at((n+2)/3) + (2-((n-1)%3))*d + b;
  else ko4 = ans((n+2)/3,a,b,c,d,memo) + (2-((n-1)%3))*d + b;

  if(memo.count(n/5)) ko5 = memo.at(n/5) + (n%5)*d + c;
  else ko5 = ans(n/5,a,b,c,d,memo) + (n%5)*d + c;
  if(memo.count((n+4)/5)) ko6 = memo.at((n+4)/5) + (4-((n-1)%5))*d + c;
  else ko6 = ans((n+4)/5,a,b,c,d,memo) + (4-((n-1)%5))*d + c; 

  ko7=n*d;

  vector<ll> p={ko1,ko2,ko3,ko4,ko5,ko6,ko7};
  sort(all(p));
  memo[n]=p[0];

  return p[0];
}


