    auto [coin, val] = que.top(); que.pop();
    if (dp[val] > coin) continue;
    if (val == 0) {
      cout << dp[val] << '\n';
      return;
    }
    if (log10(d) + log10(val) < 18 + EPS && (dp.count(0) == 0 || dp[0] > coin + val * d)) {
      dp[0] = coin + val * d;
      que.emplace(dp[0], 0);
    }
    if (val % 2 == 0 && (dp.count(val / 2) == 0 || dp[val / 2] > coin + a)) {
      dp[val / 2] = coin + a;
      que.emplace(dp[val / 2], val / 2);
    }
    if (val % 3 == 0 && (dp.count(val / 3) == 0 || dp[val / 3] > coin + b)) {
      dp[val / 3] = coin + b;
      que.emplace(dp[val / 3], val / 3);
    }
    if (val % 5 == 0 && (dp.count(val / 5) == 0 || dp[val / 5] > coin + c)) {
      dp[val / 5] = coin + c;
      que.emplace(dp[val / 5], val / 5);
    }
    {
      ll nx = val / 2 * 2;
      if (nx < val && (dp.count(nx / 2) == 0 || dp[nx / 2] > coin + (val - nx) * d + a)) {
        dp[nx / 2] = coin + (val - nx) * d + a;
        que.emplace(dp[nx / 2], nx / 2);
      }
    }
    {
      ll nx = (val + 1) / 2 * 2;
      if (val < nx && (dp.count(nx / 2) == 0 || dp[nx / 2] > coin + (nx - val) * d + a)) {
        dp[nx / 2] = coin + (nx - val) * d + a;
        que.emplace(dp[nx / 2], nx / 2);
      }
    }
    {
      ll nx = val / 3 * 3;
      if (nx < val && (dp.count(nx / 3) == 0 || dp[nx / 3] > coin + (val - nx) * d + b)) {
        dp[nx / 3] = coin + (val - nx) * d + b;
        que.emplace(dp[nx / 3], nx / 3);
      }
    }
    {
      ll nx = (val + 2) / 3 * 3;
      if (val < nx && (dp.count(nx / 3) == 0 || dp[nx / 3] > coin + (nx - val) * d + b)) {
        dp[nx / 3] = coin + (nx - val) * d + b;
        que.emplace(dp[nx / 3], nx / 3);
      }
    }
    {
      ll nx = val / 5 * 5;
      if (nx < val && (dp.count(nx / 5) == 0 || dp[nx / 5] > coin + (val - nx) * d + c)) {
        dp[nx / 5] = coin + (val - nx) * d + c;
        que.emplace(dp[nx / 5], nx / 5);
      }
    }
    {
      ll nx = (val + 4) / 5 * 5;
      if (val < nx && (dp.count(nx / 5) == 0 || dp[nx / 5] > coin + (nx - val) * d + c)) {
        dp[nx / 5] = coin + (nx - val) * d + c;
        que.emplace(dp[nx / 5], nx / 5);
      }
    }
  }
}

