ll dfs(ll x) {
    if (x == 1)return d;
    if (x == 0)return 0;
    if (m.count(x))return m[x];
    ll res = LLINF;
    if (x <= LLINF / d)chmin(res, x * d);
    chmin(res, abs(x / 2 * 2 - x) * d + a + dfs(x / 2));
    chmin(res, abs((x + 1) / 2 * 2 - x) * d + a + dfs((x + 1) / 2));
    chmin(res, abs(x / 3 * 3 - x) * d + b + dfs(x / 3));
    chmin(res, abs((x + 2) / 3 * 3 - x) * d + b + dfs((x + 2) / 3));
    chmin(res, abs(x / 5 * 5 - x) * d + c + dfs(x / 5));
    chmin(res, abs((x + 4) / 5 * 5 - x) * d + c + dfs((x + 4) / 5));
    return m[x] = res;
}
