using i64t=int64_t;
using i64pt=std::pair<i64t,i64t>;

i64t solve(i64t n,i64t a,i64t b,i64t c,i64t d) {
  std::priority_queue<i64pt> q;
  q.push(std::make_pair(n,0));
  i64t prev=n+1,ans=std::numeric_limits<i64t>::max();
  const std::array<i64t,3> costs = { a,b,c };
  const std::array<i64t,3> divs = { 2,3,5 };
  const std::array<i64t,3> thrs = { (a-1)/d+1, (b-1)/d+1, (c-1)/d+1 };

  while ( !q.empty() ) {
    auto p=q.top();
    // std::cerr << "** " << p.first << ", " << p.second << ", " << ans << std::endl;
    q.pop();
    auto val=p.first;
    if ( val==prev )
      continue;
    prev=val;
    auto cost=p.second;
    for ( int i=0; i<3; i++ ) {
      auto div=divs[i];
      auto thr=thrs[i];
      if ( val<div ) {
        ans = std::min(ans,d*val-cost);
        continue;
      }
      auto costadd=costs[i];
      i64t x,y;
      x=val/div;
      y=val%div;
      if ( y==0 ) {
        if ( val-x < thr ) {
          ans = std::min(ans,d*val-cost);
        }
        else {
          auto costnew = cost-costadd;
          if ( -costnew < ans ) {
            q.push(std::make_pair(x,costnew));
          }
        }
      }
      else {
        if ( val-x+y < thr ) {
          ans = std::min(ans,d*val-cost);
        }
        else {
          auto costnew = cost-d*y-costadd;
          if ( -costnew < ans ) {
            q.push(std::make_pair(x,costnew));
          }
        }
        if ( val-(x+1)+(div-y) < thr ) {
          ans = std::min(ans,d*val-cost);
        }
        else {
          auto costnew = cost-d*(div-y)-costadd;
          if ( -costnew < ans ) {
            q.push(std::make_pair(x+1,costnew));
          }
        }
      }
    }
  }
  return ans;
}

