			solve((x - i) / 3);
			cost -= i * d + b;
			break;
		}
	}
	for (ll i = 0; ; i++) {
		if (x - i == 1) {
			mp[1] = min(mp[1], cost + i * d);
			break;
		}
		if ((x - i) % 5 == 0) {
			cost += i * d + c;
			solve((x - i) / 5);
