void dfs(vector<ll> &v){
    ll cost=D,n=v.back();
    for (int i=1;i<v.size();++i){
        ll x=v[i]/v[i-1];
        if (x==2) cost+=A;
        if (x==3) cost+=B;
        if (x==5) cost+=C;
    }
    if (n>=N){
        if (n-N<IINF/D) chmin(ans,cost+D*(n-N));
        return;
    }
    ll pre=10,now=N-n; int sz=v.size(),ok=1;
    for (int i=sz-1;i>=0;--i){
        ll use=now/v[i];
        if (use>IINF/D){ok=0; break;}
        cost+=D*use; now-=v[i]*use;
        ll rest=v[i]-now,ccost=cost+D; int ok2=1;
        for (int j=i-1;j>=0;--j){
            ll uuse=rest/v[j];
            if (uuse>IINF/D){ok2=0; break;}
            ccost+=D*uuse; rest-=v[j]*uuse;
        }
        chmin(ans,ccost);
    }
    if (ok) chmin(ans,cost);
    if (sz>=2) pre=v[sz-1]/v[sz-2];
    for (int i=0;i<3;++i){
        if (pre>=a[i]){
            v.emplace_back(n*a[i]);
            dfs(v);
            v.pop_back();
        }
    }
}

