LL go(LL N, int A, int B, int C, int D)
{
	if (!N)
		return 0;
	auto it = dp.find(N);
	if (it != dp.end())
		return it->second;
	__int128 tmp = N * (__int128)D;

	LL res = min((__int128)1e18, tmp);
	res = min(res, go(N / 2, A, B, C, D) + A + D * (LL)(N % 2));
	res = min(res, go(N / 3, A, B, C, D) + B + D * (LL)(N % 3));
	res = min(res, go(N / 5, A, B, C, D) + C + D * (LL)(N % 5));

	return dp[N] = res;
}

