ll solve(ll n){
	if(n == 0)return 0;
	if(n == 1)return d;
	if(dp[n])return dp[n];
	ll res = 1e18;
	if(n < res/d){
		res = d*n;
	}
	ll a1 = (n)/2 * 2;
	ll a2 = (n+1)/2 * 2;
	ll b1 = (n)/3 * 3;
	ll b2 = (n+2)/3 * 3;
	ll c1 = (n)/5 * 5;
	ll c2 = (n+4)/5 * 5;
	res = min(res,a+solve(a1/2)+abs(a1-n)*d);
