using LL = long long;

const int MOD = 1e9 + 7;
const int INF = 0x3f3f3f3f;
const LL LLINF = 0x3f3f3f3f3f3f3f3f;
const int MAX_N = 200005;

struct defaultdict {
    unordered_map<LL, LL> dict;
    LL& operator[](LL key) {
        if(dict.find(key) == dict.end()) {
            dict[key] = LLINF;
        }
        return dict[key];
    }
};

void solve(int) {
    using P = pair<LL, LL>;
    LL N, A, B, C, D;
    cin >> N >> A >> B >> C >> D;
    priority_queue<P, vector<P>, greater<P>> pq;
    defaultdict dist;
    dist[N] = 0;
    pq.push({0, N});

    auto calc_cost = [](auto X, auto D, auto diff) {
        auto res = X;
        if(diff <= LLONG_MAX / D) {
            res = min(res, D * diff);
        }
        return res;
    };

    LL ans = -1;
    while(pq.size()) {
        LL cost, n;
        tie(cost, n) = pq.top();
        pq.pop();

        if(n == 0) {
            if(ans == -1 or ans > cost) {
                ans = cost;
            }
            break;
        }

        if(cost > dist[n]) {
            continue;
        }

        for(int i = -4; i <= 4 and n >= i; ++i) {
            auto m = n - i;
            if(abs(i) < 2 and m % 2 == 0) {
                auto cost1 = calc_cost(A, D, m - m / 2) + abs(i) * D;

                if(dist[m / 2] > cost + cost1) {
                    dist[m / 2] = cost + cost1;
                    pq.push({cost + cost1, m / 2});
                }
            }

            if(abs(i) < 3 and m % 3 == 0) {
                auto cost1 = calc_cost(B, D, m - m / 3) + abs(i) * D;

                if(dist[m / 3] > cost + cost1) {
                    dist[m / 3] = cost + cost1;
                    pq.push({cost + cost1, m / 3});
                }
            }

            if(m % 5 == 0) {
                auto cost1 = calc_cost(C, D, m - m / 5) + abs(i) * D;

                if(dist[m / 5] > cost + cost1) {
                    dist[m / 5] = cost + cost1;
                    pq.push({cost + cost1, m / 5});
                }
            }
        }

        if(n <= LLONG_MAX / D and dist[0] > cost + n * D) {
            dist[0] = cost + n * D;
            pq.push({cost + n * D, 0});
        }

    }
    assert(ans != -1);
    cout << ans << endl;
}

int main() {
    int T = 1;
    cin >> T;
    for(int i = 1; i <= T; ++i) {
        solve(i);
    }
    return 0;
}

