#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int N = 1e3 + 10;
const ll LIM = 1e18;

ll n, a, b, c, d;
map<ll, ll> dp;

struct myStack {

int a[N], n = 0;

int & operator [] (int x) { return a[x]; }

void clear (void) { n = 0; }
int size (void) { return n; }
void push (int x) { a[++ n] = x; }
void pop (void) { n --; }
int & top (void) { return a[n]; }

} s;

ll h[N];

ll calc (ll now) {
	int m = s.size();
	h[m + 1] = 1;
	for (int i = m; i >= 1; i --) {
		h[i] = h[i + 1] * s[i];
	}
	ll ret = 0;
	for (int i = 1; i <= m + 1; i ++) {
		ll t = now / h[i];
		now %= h[i];
		if (now <= h[i] - now) {
			ret += t;
		} else {
			ret += t + 1;
			now = h[i] - now;
		}
	}
	if (ret > 1e9) return LIM;
	return ret * d;
}


ll dfs (ll now) {
	if (dp.count(now)) 
		return dp[now];
	if (now >= n && now - n < 1e9)
		return (now - n) * d;
	if (now <= 0 || now > n)
		return LIM;

	dp[now] = calc(n - now);
	s.push(2);
	dp[now] = min(dp[now], a + dfs(now * 2));
	s.pop();
	s.push(3); 
	dp[now] = min(dp[now], b + dfs(now * 3));
	s.pop();
	s.push(5);
	dp[now] = min(dp[now], c + dfs(now * 5));
	s.pop();
	return dp[now];
}

int main (void) {
	int kase;
	scanf("%d", &kase);
	while (kase --) {
		scanf("%lld%lld%lld%lld%lld", &n, &a, &b, &c, &d);
		dp.clear(); 
		s.clear();
		dfs(1);
		printf("%lld\n", d + dp[1]);
	}
}

