long long f(long long n, map<long long, long long> &m) {
  if (m.find(n) != m.end()) {
    return m[n];
  }
  if (n == 0) {
    m[0] = 0;
    return 0;
  }
  if (n == 1) {
    m[1] = d;
    return d;
  }
  if (n == 2) {
    m[2] = min(a, d) + d;
    return m[2];
  }
  pair<long long, long long> ks[3] = {{2, a}, {3, b}, {5, c}};
  long long ret = LLONG_MAX;
  for (auto p: ks) {
    long long k = p.first;
    long long n1 = (n - 1) / k + 1;
    long long n2 = n / k;
    long long cost1 = f(n1, m) + (n1 * k - n) * d;
    if (d < p.second && n1 * k - n1 < p.second) {
      cost1 += min(p.second, d * (n1 * k - n1));
    } else {
      cost1 += p.second;
    }
    long long cost2 = f(n2, m) + (n - n2 * k) * d;
    if (d < p.second && n2 * k - n2 < p.second) {
      cost2 += min(p.second, d * (n2 * k -  n2));
    } else {
      cost2 += p.second;
    }
    if (n2 == 0) {
      ret = min(cost1, ret);
    } else {
      ret = min(cost1, min(cost2, ret));
    }
  }
  m[n] = ret;
  return ret;
}
long long solve() {
  long long n;
  cin>>n>>a>>b>>c>>d;
  map<long long, long long> m;
  return f(n, m);
}
