ll rec(ll n,ll a,ll b,ll c,ll d) {

	if (mp.count(n)) {
		return mp[n];
	}
	if (n == 1)
		return d;
	if (n == 0)
		return 0;
	ll res = n * d;
	if (res < 0) {
		res = big;
	}

	if (n % 2 == 0) {
		res = min(res, rec(n / 2, a, b, c, d) + a);
	}
	else {
		res = min(res, rec(n / 2, a, b, c, d) + a + d);
		res = min(res, rec((n + 1) / 2, a, b, c, d) + a + d);
	}
	// n + n - n % 3
	// 3倍して足したか、3倍したものから引いたかの2ルートになるはず
	if (n % 3 == 0) {
		res = min(res, rec(n / 3, a, b, c, d) + b);
	}
	else {
		ll np3 = (n + (3 - n % 3));
		ll nm3 = (n - n % 3);
		res = min(res, rec(np3 / 3, a, b, c, d) + b + (np3 - n) * d);
		res = min(res, rec(nm3 / 3, a, b, c, d) + b + (n - nm3) * d);
	}
	if (n % 5 == 0) {
		res = min(res, rec(n / 5, a, b, c, d) + c);
	}
	else {
		ll np5 = (n + (5 - n % 5));
		ll nm5 = (n - n % 5);
		res = min(res, rec(np5 / 5, a, b, c, d) + c + (np5 - n) * d);
		res = min(res, rec(nm5 / 5, a, b, c, d) + c + (n - nm5) * d);
	}
	return mp[n] = res;
}

