LL go(LL N, int A, int B, int C, int D)
{
	LL res = inf;
	// Below works on G++, not in VS
	/*if (N*(__int128)D < res)
		res = N * D;*/
	if (N < res / D)
		res = N * D;
	if (!N)
		return 0;
	auto it = d.find(N);
	if (it != d.end())
		return it->second;

	auto K = { MP(2,A),MP(3,B),MP(5,C) };
	for (const auto &p : K)
	{
		{
			LL v = N / p.first;
			auto tmp = go(v, A, B, C, D);
			res = min(res, D*(N%p.first) + p.second + tmp);
		}
		{
			LL v = N / p.first + (N % p.first ? 1 : 0);
			if (v == N || v == N / p.first)
				continue;
			auto tmp = go(v, A, B, C, D);
			res = min(res, D*(p.first - N % p.first) + p.second + tmp);
		}
	}

	return d[N] = res;
}

