struct solve
{
	ll a, b, c, d;
	map<ll,ll> dp;
	vpii act;

	solve(ll a, ll b, ll c, ll d) : a(a),b(b),c(c),d(d)
	{
		act={{2,a},{3,b},{5,c}};
	}
	ll operator()(ll n)
	{
		if(n==0) return 0;
		if(n==1) return d;
		if(dp[n]>0) return dp[n];

		ll ans=a*msb(n)+d*bit_count(n);
		if(ans/n>d) min_u(ans, d*n);

		for(auto [r, cost]:act)
		{
			int updown=n-n/r*r;
			if(updown==0)
			{
				min_u(ans, cost+(*this)(n/r));
				continue;
			}
			min_u(ans, cost+d*updown+(*this)(n/r));
			min_u(ans, cost+d*(r-updown)+(*this)(n/r+1));
		}
		dp[n]=ans;
		return ans;
	}
};


