map<ll, ll> memo;

ll func(ll x, ll a, ll b, ll c, ll d){
    if(x == 0)
        return 0;
    if(x == 1)
        return d;

    if(memo.count(x))
        return memo[x];

    ll ans = 1000000000000000000LL;
    if(x%2==0) ans = min(ans, func(x/2,a,b,c,d)+a);
    else ans = min(ans, min(func((x-1)/2, a, b, c, d)+a+d, func((x+1)/2, a, b, c,d)+a+d));

    if(x%3==0) ans = min(ans, func(x/3,a,b,c,d)+b);
    else if(x%3==1) ans = min(ans, func((x-1)/3, a,b,c,d)+b+d);
    else ans = min(ans, func((x+1)/3,a,b,c,d)+b+d);

    if(x%5==0) ans = min(ans, func(x/5,a,b,c,d)+c);
    else if(x%5==1) ans = min(ans, func((x-1)/5,a,b,c,d)+c+d);
    else if(x%5==2) ans = min(ans, func((x-2)/5,a,b,c,d)+c+2*d);
    else if(x%5==3) ans = min(ans, func((x+2)/5,a,b,c,d)+c+2*d);
    else ans = min(ans, func((x+1)/5,a,b,c,d)+c+d);

    double tmp = d;
    tmp = tmp * (double)x;
    if(tmp < 1e18){
        ans = min(ans, d*x);
    }

    return memo[x] = ans;

}
