ll N, A, B, C, D;
ll width = 6;
unordered_map<ll, ll> dp;

ll rec(ll now){
    if (dp.count(now)) return dp[now];
    if (now == 0) return 0;
    ll ret = INF;
    if (INF / D > now) ret = D * now;
    for (ll i = now - width; i < now + width - 3; i++){
        if (i < 0) continue;
        ll d = abs(now - i);
        if ((i % 2) == 0 && i / 2 != now) chmin(ret, rec(i / 2) + A + d * D);
        if ((i % 3) == 0 && i / 3 != now) chmin(ret, rec(i / 3) + B + d * D);
        if ((i % 5) == 0 && i / 5 != now) chmin(ret, rec(i / 5) + C + d * D);
    }
    // pt(now);
    dp[now] = ret;
    return ret;
}

