    cin >> n >> a >> b >> c >> d;
    map<ll, ll> cost;
    cost[0] = 0;
    cost[1] = d;
    function<ll(ll)> calc = [&](ll n) {
        auto it = cost.find(n);
        if (it != cost.end()) return it->second;
        ll res = inf;
        if (n < inf / d)
            res = min(res, n * d);
        for (int x = -2; x <= 2; ++x) {
            if ((n + x) >= 0 && (n + x) % 5 == 0)
                res = min(res, calc((n + x) / 5) + c + d * abs(x));
        }
        for (int x = -1; x <= 1; ++x) {
            if ((n + x) >= 0 && (n + x) % 3 == 0)
                res = min(res, calc((n + x) / 3) + b + d * abs(x));
        }
        for (int x = -1; x <= 1; ++x) {
            if ((n + x) >= 0 && (n + x) % 2 == 0)
                res = min(res, calc((n + x) / 2) + a + d * abs(x));
        }
        cost[n] = res;
        return res;
    };
    cout << calc(n) << '\n';
}

