long long cost_calc(long long N) {

    if (N == 0) { return 0; }
    if (N == 1) { return D; }
    if (mp.find(N) != mp.end()) { return mp[N]; }

    long long A1 = (N / 2) * 2;
    long long A2 = ((N + 1) / 2) * 2;
    long long B1 = (N / 3) * 3;
    long long B2 = ((N + 2) / 3) * 3;
    long long C1 = (N / 5) * 5;
    long long C2 = ((N + 4) / 5) * 5;

    //select A
    long long costA1 = llabs(A1 - N) * D + A + cost_calc(A1 / 2);
    long long costA2 = llabs(A2 - N) * D + A + cost_calc(A2 / 2);

    //select B
    long long costB1 = llabs(B1 - N) * D + B + cost_calc(B1 / 3);
    long long costB2 = llabs(B2 - N) * D + B + cost_calc(B2 / 3);


    //select C
    long long costC1 = llabs(C1 - N) * D + C + cost_calc(C1 / 5);
    long long costC2 = llabs(C2 - N) * D + C + cost_calc(C2 / 5);

    //select D + 1
    //long long costD1 = cost_calc(N + 1, cost + D);

    //select D - 1
    //long long costD2 = cost_calc(N - 1, cost + D);

    vector<long long> costs;
    costs.push_back(costA1);
    costs.push_back(costA2);
    costs.push_back(costB1);
    costs.push_back(costB2);
    costs.push_back(costC1);
    costs.push_back(costC2);

    if (N < 1e18 / D) costs.push_back(N * D);
    //costs.push_back(costD1);
    //costs.push_back(costD2);

    sort(costs.begin(), costs.end());
    //cout << "N : " << N << " return : " << costs[0] << endl;
    mp[N] = costs[0];

    return costs[0];
}

