void slv(){
	int128 n=read();
	vc<int128> a(3);
	rep(i,3)a[i]=read();
	vc<int128> b{2,3,5};
	int128 d=read();
	int128 ans=inf;

	auto waf=[&](vc<int128> z,int128 s){
		int128 len=si(z);
		vi m(len);
		{
			int128 tmp=n;
			per(i,len){
				m[i]=tmp/z[i];
				tmp%=z[i];
			}
		}
		int128 dp[2]{0,inf};
		//dmp(z);
		rep(i,len){
			int128 nx[2]{inf,inf};
			rep(j,2){
				int128 v=m[i]+j;
				chmin(nx[0],dp[j]+d*v);
				if(i+1<len){
					int128 w=z[i+1]/z[i];
					//dmp2(v,w);
					assert(v<=w);
					chmin(nx[1],dp[j]+d*(w-v));
				}
			}
			swap(dp,nx);
		}
		chmin(ans,dp[0]+s);
	};

	auto rec=[&](auto self,vc<int128>&cur,int128 i,int128 s)->void{
		waf(cur,s);
		int128 last=cur.back();
