map<LLONG, LLONG> num2MinCostMap;
LLONG costs[3];
LLONG ks[3];
LLONG N, D;

const LLONG DFS(const LLONG n)
{
    if (num2MinCostMap.count(n)) return num2MinCostMap[n];
    LLONG minCost = log10(n) * log10(D) < 18.0 ? n * D : 9e18;
    for (int i = 0; i < 3; ++i)
    {
        LLONG k = ks[i];
        LLONG lower = n / k;
        LLONG upper = (n + k - 1) / k;
        minCost = min(minCost,
            min(DFS(lower) + costs[i] + llabs(n - lower * k) * D,
                DFS(upper) + costs[i] + llabs(n - upper * k) * D));
    }
    num2MinCostMap[n] = minCost;
    return minCost;
}

void Solve()
{
    cin >> N >> costs[0] >> costs[1] >> costs[2] >> D;
    num2MinCostMap.clear();
    num2MinCostMap[0] = 0;
    num2MinCostMap[1] = D;
    ks[0] = 2, ks[1] = 3, ks[2] = 5;
    cout << DFS(N) << endl;
}

int main()
{
