ll N, A, B, C, D;
map<ll, ll> cst;

ll calc(ll cur)
{
	if (!cur) return 0;
	if (cst.count(cur))
		return cst[cur];
	ll ret = 4e18;
	if (cur <= ret/D)
		ret = min(ret, cur * D);
	if (cur%2==0)
		ret = min(ret, calc(cur/2) + A);
	else
	{
		ret = min(ret, calc(cur/2) + A + D);
		if (1 + cur/2 < cur)
			ret = min(ret, calc(cur/2 + 1) + D + A);	
	}

	if (cur%3==0)
		ret = min(ret, calc(cur/3) + B);
	else
	{
		ret = min(ret, calc(cur/3) + B + D * (cur%3));
		if (cur > cur/3 + 1)
			ret = min(ret, calc(cur/3 + 1) + B + D * (3-cur%3));
	}

	if (cur%5==0)
		ret = min(ret, calc(cur/5) + C);
	else
	{
		ret = min(ret, calc(cur/5) + C + D * (cur%5));
		if (cur > cur/5 + 1)
