ld kkk(ll n,ll a,ll b,ll c,ll d){
	ld y = 1000000000000;
	for (ll i = 0; i < 100; i++) {
		for (ll j = 0; j < 100; j++) {
			for (ll k = 0; k < 100; k++) {
				ld count = 1;
				ld score = d;
				count *= pow(2, i) * pow(3, j) * pow(5, k);
				score += a * i + b * j + c * k;
				ld kk = score;
				kk += d * (abs(n - count));
				ll p = n / count;
				if (p == 0) {
					score += d * (abs(n - count));
				}
				else {
					score += kkk(p,a,b,c,d);
				}
				score = min(score, kk);
				 y=min(y, score);
			}
		}
	}
	return(y);
}
