int dfs(int x)
{
	if(x==0) return 0;
	if(f[x]) return f[x];
	int res=INF;
	if((__int128)d*x<res) res=d*x;
	int l=x/2;
	if(l!=x) res=min(res,(x-l*2)*d+a+dfs(l));
	l=x/2+1;
	if(l!=x) res=min(res,(l*2-x)*d+a+dfs(l));
	l=x/3;
	if(l!=x) res=min(res,(x-l*3)*d+b+dfs(l));
	l=x/3+1;
	if(l!=x) res=min(res,(l*3-x)*d+b+dfs(l));
	l=x/5;
	if(l!=x) res=min(res,(x-l*5)*d+c+dfs(l));
	l=x/5+1;
	if(l!=x) res=min(res,(l*5-x)*d+c+dfs(l));
	return f[x]=res;
}
