		// else
		// {
			res=min(res,d+a+min(solve((x+1)/2,1),solve((x-1)/2,1)));
		// }
	}
	if(z==2)
	{
		res=min(res,solve(x,1));
		ll r=x%3;
		if(1)
		{
			res=min(res,b+r*d+solve(x/3,2));
		}
		if(1)
		{
			res=min(res,b+(3-r)*d+solve(x/3+1,2));
		}
	}
	if(z==3)
	{
		res=min(res,solve(x,2));
		ll r=x%5;
		if(1)
