ll a, b, c, d;

ll lastt(ll v, ll d) {
  return (v / d) * d;
}

ll nextt(ll v, ll d) {
  return (v / d + 1) * d;
}

bool check(ll k, ll v) {
  return memo.find(k) == memo.end() || v < memo[k];
}

void solve(int tc) {
  cin >> n >> a >> b >> c >> d;

  memo.clear();
  set<pll> q;
  q.insert(mp(0, n));
  ans = 4 * mod * mod;
  while (!q.empty()) {
    pll x = *q.begin();
    q.erase(q.begin());

    if (!check(x.s, x.f)) continue;
    if (x.s < 0) continue;
    if (x.s == 0) {
      ans = min(ans, x.f);
      break;
    }
    // cout << x << endl;
    memo[x.s] = x.f;
    ll v = 0;
    if (x.s % 2 == 0) {
      if (check(x.s / 2, x.f + a))
        q.insert(mp(x.f + a, x.s / 2));
    } else {
      ll l = lastt(x.s, 2), r = nextt(x.s, 2);
      ll cl = x.f + a + d * abs(x.s - l);
      ll cr = x.f + a + d * abs(x.s - r);
      if (check(l, cl)) q.insert(mp(cl, l / 2));
      if (check(r, cr)) q.insert(mp(cr, r / 2));
    }
    if (x.s % 3 == 0) {
      if (check(x.s / 3, x.f + b))
        q.insert(mp(x.f + b, x.s / 3));
    } else {
      ll l = lastt(x.s, 3), r = nextt(x.s, 3);
      ll cl = x.f + b + d * abs(x.s - l);
      ll cr = x.f + b + d * abs(x.s - r);
      if (check(l, cl)) q.insert(mp(cl, l / 3));
      if (check(r, cr)) q.insert(mp(cr, r / 3));
    }
    if (x.s % 5 == 0) {
      if (check(x.s / 5, x.f + c))
        q.insert(mp(x.f + c, x.s / 5));
    } else {
      ll l = lastt(x.s, 5), r = nextt(x.s, 5);
      ll cl = x.f + c + d * abs(x.s - l);
      ll cr = x.f + c + d * abs(x.s - r);
      if (check(l, cl)) q.insert(mp(cl, l / 5));
      if (check(r, cr)) q.insert(mp(cr, r / 5));
    }
    if (d < 3e18 / x.s) ans = min(ans, x.f + d * x.s);
  }

  cout << ans << '\n';
}

