#define INF2 2000000000000000000
#define int long long
typedef pair<int, int> P;
int A[3], D;
int choice[3] = {2, 3, 5};
map<int, int> d;
void dijkstra(int N) {
    priority_queue<P, vector<P>, greater<P>> que;
    d[N] = 0;
    que.push(P(0, N));
    while (!que.empty()) {
        P p = que.top(); que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;
        if(v <= 1) continue; 
        //cout << v << " " << d[v] << endl;
        vector<P> v2;
        rep(i, 3) {
            int moveL = v % choice[i];
            int moveR = (choice[i] - v % choice[i]) % choice[i];
            int cost1 = A[i] + moveL * D;
            int cost2 = (v - ((v - moveL) / choice[i])) * D;
            int cost3 = A[i] + moveR * D;
            int cost4 = (v - ((v + moveR) / choice[i])) * D;
            double a = (v - ((v - moveL) / choice[i])), b = D;
            if(a * b >= INF2) cost2 = cost4 = INF2;
            v2.push_back({(v - moveL) / choice[i], min(cost1, cost2)});
            v2.push_back({(v + moveR) / choice[i], min(cost3, cost4)});
        }
        for(auto& e: v2) {
            if(d.find(e.first) == d.end()) d[e.first] = INF2;
            //cout << "*" << e.first << " " << d[e.first] << " " << d[v] << " " << e.second << endl;
            if (d[e.first] > d[v] + e.second) {
                d[e.first] = d[v] + e.second;
                que.push(P(d[e.first], e.first));
            }
        }
    }
}

