i64 solve(i64 x, i64 k, i64 m) {
    i64 x1 = (x / k) * k;
    i64 t1 = (x - x1) * d + m + solve(x1 / k);

    i64 R = t1;

    i64 x2 = (x / k + (x % k ? 1 : 0)) * k;
    if (x2 / k < x) {
        i64 t2 = (x2 - x) * d + m + solve(x2 / k);
        R = min(R, t2);
    }

    return R;
}

i64 solve(i64 x) {
    if (!x) {
        return 0;
    }

    if (q.count(x)) {
        return q[x];
    }

    i64 t2 = solve(x, 2, a);
    i64 t3 = solve(x, 3, b);
    i64 t5 = solve(x, 5, c);

    i64 R = min(t2, min(t3, t5));

    if (R / d >= x && R > x * d) {
        R = x * d;
    }

    q[x] = R;
    return q[x];
}


