int32_t main(){
	int t; cin >> t;
	while(t--){
		int n, a, b, c, d; cin >> n >> a >> b >> c >> d;
		map<int, int> m;
		m[n]=-inf;
		priority_queue<int> q;
		q.push(n);
		while(!q.empty()){
			int i=q.top();
			while(!q.empty() && q.top() == i) q.pop();
			if(i < inf/d && m[0] > m[i]+i*d) m[0] = m[i] + i*d; // -1 all the way to zero
			if(m[i/2] > m[i] + a + d*(i % 2)){ // round down divide by two
				m[i/2] = m[i] + a + d*(i % 2);
				q.push(i/2);
			}
			if(m[i/3] > m[i] + b + d*(i % 3)){ // round down divide by three
				m[i/3] = m[i] + b + d*(i % 3);
				q.push(i/3);
			}
			if(m[i/5] > m[i] + c + d*(i % 5)){ // round down divide by five
				m[i/5] = m[i] + c + d*(i % 5);
				q.push(i/5);
			}
			if(m[i/2+1] > m[i] + a + d*(2 - (i % 2))){ // round up divide by two
				m[i/2+1] = m[i] + a + d*(2 - (i % 2));
				q.push(i/2+1);
			}
			if(m[i/3+1] > m[i] + b + d*(3 - (i % 3))){ // round up divide by three
				m[i/3+1] = m[i] + b + d*(3 - (i % 3));
				q.push(i/3+1);
			}
			if(m[i/5+1] > m[i] + c + d*(5 - (i % 5))){ // round up divide by five
				m[i/5+1] = m[i] + c + d*(5 - (i % 5));
				q.push(i/5+1);
			}
		}
		cout << m[0]+inf << endl;
	}
}

