void solve(ll N, ll tmp) {
    if (tmp < 0) {
        return;
    }
    if (mp.count(N) > 0) {
        if (mp[N] <= tmp) {
            return;
        } else {
            mp[N] = tmp;
        }
    } else {
        mp[N] = tmp;
    }
    // cout << N << " " << tmp << endl;
    if (tmp >= ans) {
        return;
    }
    if (N == 1) {
        // cout << tmp << endl;
        if (D + tmp > 0) {
            ans = min(ans, D + tmp);
        }
        return;
    }
    if (N <= llmax / D && N * D <= llmax - tmp) {
        ans = min(ans, N * D + tmp);
    }
    if (N % 2 == 0) {
        solve(N / 2, tmp + A);
    } else {
        solve((N - 1) / 2, tmp + A + D);
        // solve((N + 1) / 2, tmp + A + D);
    }
    if (N % 3 == 0) {
        solve(N / 3, tmp + B);
    } else if (N % 3 == 1) {
        solve((N - 1) / 3, tmp + B + D);
        // solve((N + 2) / 3, tmp + B + 2 * D);
