ll N, A, B, C, D;
map<ll, ll> memo;

ll dfs(ll n) {
    if(n == 0) {
        return 0;
    }
    if(n == 1) {
        return D;
    }
    if(memo.count(n)) {
        return memo[n];
    }
    ll res = LLINF;
    if(n < res / D) {
        res = n * D;
    }

    ll l, r;
    l = (n / 2) * 2;
    r = ((n + 2 - 1) / 2) * 2;
    chmin(res, llabs(l - n) * D + A + dfs(l / 2));
    chmin(res, llabs(r - n) * D + A + dfs(r / 2));
    l = (n / 3) * 3;
    r = ((n + 3 - 1) / 3) * 3;
    chmin(res, llabs(l - n) * D + B + dfs(l / 3));
    chmin(res, llabs(r - n) * D + B + dfs(r / 3));
    l = (n / 5) * 5;
    r = ((n + 5 - 1) / 5) * 5;
    chmin(res, llabs(l - n) * D + C + dfs(l / 5));
    chmin(res, llabs(r - n) * D + C + dfs(r / 5));

    return (memo[n] = res);
}

