	ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	ll tc; cin>>tc;
	while(tc--) {
		cin >> N >> A >> B >> C >> D;
		cout << calc(N) << '\n';
		Map.clear();
	}
	return 0;
}

