using namespace std;

unordered_map<uint64_t, uint64_t> memo;
uint64_t walk(uint64_t n, uint64_t A, uint64_t B, uint64_t C, uint64_t D) {
  if (n == 0) return 0;
  if (n == 1) return D;

  uint64_t result = min({
    D * ((uint64_t)ceil(1.0 * n / 5) * 5 - n) + C + walk((uint64_t)ceil(1.0 * n / 5), A, B, C, D),
    D * ((uint64_t)ceil(1.0 * n / 3) * 3 - n) + B + walk((uint64_t)ceil(1.0 * n / 3), A, B, C, D),
    D * ((uint64_t)ceil(1.0 * n / 2) * 2 - n) + A + walk((uint64_t)ceil(1.0 * n / 2), A, B, C, D),
    D * (n - (uint64_t)floor(1.0 * n / 5) * 5) + C + walk((uint64_t)floor(1.0 * n / 5), A, B, C, D),
    D * (n - (uint64_t)floor(1.0 * n / 3) * 3) + B + walk((uint64_t)floor(1.0 * n / 3), A, B, C, D),
    D * (n - (uint64_t)floor(1.0 * n / 2) * 2) + A + walk((uint64_t)floor(1.0 * n / 2), A, B, C, D),
    D * n
    });

  return result;
}

