tint solve(tint n, tint a, tint b, tint c, tint d, map<tint, tint>& memo) {
	if(n==0) return 0;
	if(memo.find(n) != memo.end()) {
		return memo[n];
	}
	tint r2 = n%2, r3 = n%3, r5 = n%5;
	tint ans = 1000000000000000000LL;
	if(log(n)+log(d) < 60*log(2)) ans = n*d; 
	ans = min(ans, solve(n/2, a,b,c,d, memo) + a + d*r2);
