map<ll, ll> memo;

ll solve(ll n, ll a, ll b, ll c, ll d) {
  if(n == 0) return 0;
  if(n == 1) return d;
  if(memo.find(n) != memo.end()) {
    return memo[n];
  }

  ll res = LLONG_MAX;

  if(n % 2) {
    res = min(solve((n+1)/2, a, b, c, d), solve((n-1)/2, a, b, c, d)) + a + d;
  } else {
    res = solve(n/2, a, b, c, d) + a;
  }

  if(n % 3) {
    ll tmpn = n;
    ll now = 0;
    while (tmpn % 3) {
      now += d;
      tmpn++;
    }
    chmin(res, solve(tmpn/3, a, b, c, d) + b + now);
    tmpn = n;
    now = 0;
    while(tmpn % 3) {
      now += d;
      tmpn--;
