					f[c2][c3][c5][1] = min(f[c2][c3][c5][1],f[c2][c3][c5][0] + 1);
				//	cout << c2 << ' '<< c3 << ' ' << c5 << ' ' << f[c2][c3][c5][0] << ' '<< f[c2][c3][c5][1] << endl;
					if (n / v5 + f[c2][c3][c5][0] <= 2e18 / D)
						ans = min(ans,(n / v5 + f[c2][c3][c5][0]) * D + c2 * A + c3 * B + c5 * C);
				}
		printf("%lld\n",ans);
	}
