ll calc(ll x)
{
    if (x == 0) return 0;
    if (dp.find(x) != dp.end()) return dp[x];
    if ((double) x * d >= (double) 2e18) dp[x] = 2e18;
    else dp[x] = x * d;
    if (x % 2 == 0) dp[x] = min(dp[x], calc(x / 2) + a);
    else dp[x] = min(dp[x], min(calc(x / 2) + d, calc(x / 2 + 1) + d) + a);
    if (x % 3 == 0) dp[x] = min(dp[x], calc(x / 3) + b);
    else dp[x] = min(dp[x], 
    min(calc(x / 3) + d * (x - x / 3 * 3), calc(x / 3 + 1) + d * (x / 3 * 3 + 3 - x)) + b);
    if (x % 5 == 0) dp[x] = min(dp[x], calc(x / 5) + c);
    else dp[x] = min(dp[x], 
    min(calc(x / 5) + d * (x - x / 5 * 5), calc(x / 5 + 1) + d * (x / 5 * 5 + 5 - x)) + c);
    return dp[x];
}

