void dfs(unordered_map<ll, ll>& dp, ll cur = n) {
    // cout << cur << endl;
    if (cur == 0) {
        ans = min(ans, dp[cur]);
        return;
    }
    if (cur == 1) {
        ans = min(ans, dp[cur] + d);
        return;
    }

    ll red = cur % 2;
    if (!done.count((cur + 2 - red) / 2)) {
        dp[(cur + 2 - red) / 2] = dp[cur] + d * (2 - red) + a;
        done.insert((cur + 2 - red) / 2);
        dfs(dp, (cur + 2 - red) / 2);
    } else if (dp[(cur + 2 - red) / 2] > dp[cur] + d * (2 - red) + a) {
        dp[(cur + 2 - red) / 2] = dp[cur] + d * (2 - red) + a;
        dfs(dp, (cur + 2 - red) / 2);
    }

    if (!done.count((cur - red) / 2)) {
        dp[(cur - red) / 2] = dp[cur] + d * red + a;
        done.insert((cur - red) / 2);
        dfs(dp, (cur - red) / 2);
    } else if (dp[(cur - red) / 2] > dp[cur] + d * red + a) {
        dp[(cur - red) / 2] = dp[cur] + d * red + a;
