map<ll, ll> memo;
map<ll, bool> done;

ll n, a, b, c, d;

ll dp(ll x) {
  if (done[x]) return memo[x];
  if (x == 0) return 0;
  if (x == 1) return d;

  ll res = d * x;
  chmin(res, dp(x/2) + (x%2)*d + a);
  chmin(res, dp(x/3) + (x%3)*d + b);
  chmin(res, dp(x/5) + (x%5)*d + c);
  chmin(res, dp((x+1)/2) + (2-x%2)*d + a);
  chmin(res, dp((x+2)/3) + (3-x%3)*d + b);
  chmin(res, dp((x+4)/5) + (5-x%5)*d + c);

  done[x] = true;
  memo[x] = res;
  return res;
}


