      long long c = M[x];

      vector<pair<long long,long long>> V(0);
      V.push_back(make_pair(x/2,A+(x%2)*D));
      if(x%2!=0) V.push_back(make_pair(x/2+1,A+(x%2)*D));
      V.push_back(make_pair(x/3,B+(x%3)*D));
      if(x%3!=0) V.push_back(make_pair(x/3+1,B+(3-(x%3))*D));
      V.push_back(make_pair(x/5,C+(x%5)*D));
      if(x%5!=0) V.push_back(make_pair(x/5+1,C+(5-(x%5))*D));
      if(x<inf/D) V.push_back(make_pair(0,x*D));

      for(int i=0;i<V.size();i++){
        long long newx = V[i].first, coin = V[i].second;
        if(M.count(newx)){
          if(coin+c<M[newx]){
            M[newx] = coin+c;
            Q.push(newx);
          }
        }
        else{
          M[newx] = coin+c;
          Q.push(newx);
        }
      }
    }

