int main(){
    int T;
    cin >> T;

    vector<vector<int64_t>> Z(3, vector<int64_t>(1, 1));
    vector<int64_t> ppp = {2, 3, 5};

    for (int i = 0; i < 3; i++){
        auto &A = Z[i];
        const auto &p = ppp[i];
        while (true) {
            const auto &a = A[A.size() - 1];
            if (a * p / p != a)
                break;
            A.push_back(a * p); 
        }
    }

    vector<int64_t> A;

    for (const auto &a: Z[0]){
        for (const auto &b: Z[1]){
            if (a * b % b != 0 or a * b / b != a)
                continue;
            for (const auto &c: Z[2]){
                if (a * b * c % c != 0 or a * b * c / c != a * b)
                    continue;
                A.push_back(a * b * c);
            }
        }
    }

    sort(A.begin(), A.end());
    map<int64_t, array<int, 3>> B;

    for (auto a: A){
        array<int, 3> C = {0, 0, 0};
        for (int i = 0; i < 3; i++){
            while (a % ppp[i] == 0){
                a /= ppp[i];
                C[i]++;
            }
        }

        B[a] = C;
    }


    for (int t = 0; t < T; t++){
        int64_t n, a, b, c, d;
        cin >> n >> a >> b >> c >> d;
        auto m = n;
        vector<int> cnt(3);
        for (int i = 0; i < 3; i++){
            while (m % ppp[i] == 0){
                m /= ppp[i];
                cnt[i]++;
            }
        }

        int64_t ans = 1e18;
        ans++;

        for (const auto &k: A){
            if (k * m % m != 0 or k * m / m != k)
                break;
            for (const auto &l: A){
                int64_t cost = d;
                if (k * m < l and l - k * m * d > ans)
                    break;
                cost += a * B[l][0];
                cost += b * B[l][1];
                cost += c * B[l][2];
                cost += abs(l - k * m) * d;
                auto x = n / (k * m);
                cost += a * B[x][0];
                cost += b * B[x][1];
                cost += c * B[x][2];
                ans = min(ans, cost);
            }
        }

        cout << ans << endl;
    }
}

