priority_queue<pair<long long, long long>> pq;
map<long long, long long> m;
set<long long> s;

void push(long long x, long long y, bool flag = false) {
  if (m.find(y) == m.end() || x < m[y]) {
    if (flag) {
      s.insert(y);
    }
    m[y] = x;
    pq.push({-x, y});
  }
}

void solve() {
  scanf("%lld %d %d %d %d", &n, &a, &b, &c, &d);
  pq = priority_queue<pair<long long, long long>>();
  m.clear();
  push(0, n);
  while (!pq.empty()) {
    long long x = -pq.top().first;
    long long y = pq.top().second;
    if (y % 2 == 0) {
      push(x + a, y / 2);
      s.erase(y/2);
    }
    if (y % 3 == 0) {
      push(x + b, y / 3);
      s.erase(y/3);
    }
    if (y % 5 == 0) {
      push(x + c, y / 5);
      s.erase(y/5);
    }
    if (s.find(y) == s.end()) {
      push(x + d, y + 1, true);
      push(x + 2*d, y + 2, true);
      push(x + d, y - 1, true);
      push(x + 2*d, y - 2, true);
      if (y < 1e18/d) {
        push(x + y*d, 0, true);
      }
    }
    do {
      pq.pop();
    } while(!pq.empty() && pq.top().first != -m[pq.top().second]);
  }
  printf("%lld\n", m[0]);
}

