Cint gosa(Cint G) {
    if (g.count(G)) {
        return g[G];
    }
    if (G == 1)
        return D;
    if (G == 0) {
        return N * D;
    }

    Cint tmp = G * D;
    chmin(tmp, gosa(G / 2) + A + (G % 2) * D);
    chmin(tmp, gosa(G / 3) + B + (G % 3) * D);
    chmin(tmp, gosa(G / 5) + C + (G % 5) * D);

    if (G > G / 2 + 1)
        chmin(tmp, gosa(G / 2 + 1) + A + D * (2 - G % 2));
    if (G > G / 3 + 1)
        chmin(tmp, gosa(G / 3 + 1) + B + D * (3 - G % 3));
    if (G > G / 5 + 1)
        chmin(tmp, gosa(G / 5 + 1) + C + D * (5 - G % 5));

    return g[G] = tmp;
}


