ll f(ll x, ll a, ll b, ll c, ll d, map<ll, ll>& memo) {
    if (x == 0) return 0;
    if (x == 1) return d;
    if (memo[x] != 0) return memo[x];
    ll ans = LLONG_MAX;
    if ((double)x * d <= 1e18) ans = x * d;
    ans = min(ans, f(x / 2, a, b, c, d, memo) + a + (x - x / 2 * 2) * d);
    ans = min(ans, f((x + 1) / 2, a, b, c, d, memo) + a + ((x + 1) / 2 * 2 - x) * d);
    ans = min(ans, f(x / 3, a, b, c, d, memo) + b + (x - x / 3 * 3) * d);
    ans = min(ans, f((x + 2) / 3, a, b, c, d, memo) + b + ((x + 2) / 3 * 3 - x) * d);
    ans = min(ans, f(x / 5, a, b, c, d, memo) + c + (x - x / 5 * 5) * d);
    ans = min(ans, f((x + 4) / 5, a, b, c, d, memo) + c + ((x + 4) / 5 * 5 - x) * d);
    return memo[x] = ans;
}

