ll rec(ll cur, map<ll, ll> &mp) {
  auto itr = mp.find(cur);
  if (itr != mp.end()) {
    return itr->second;
  }
  ll ans = numeric_limits<ll>::max();

  REP(i, 3) {
    ll next, diff, cost;
    if (cur % ary[i] == 0) {
      next = cur / ary[i];
      diff = cur - next;
      cost = diff < (ll)2e9 / d ? min(c[i], d * diff) : c[i];
      chmin(ans, rec(next, mp) + cost);
      continue;
    }
    next = (cur - cur % ary[i]) / ary[i];
    diff = (cur - cur % ary[i]) - next;
    cost = (diff < (ll)2e9 / d ? min(c[i], d * diff) : c[i]) + (cur % ary[i]) * d;
    chmin(ans, rec(next, mp) + cost);

    next = (cur + ary[i] - cur % ary[i]) / ary[i];
    diff = (cur + ary[i] - cur % ary[i]) - next;
    cost = (diff < (ll)2e9 / d ? min(c[i], d * diff) : c[i]) + (ary[i] - (cur % ary[i])) * d;
    chmin(ans, rec(next, mp) + cost);
  }
  mp.insert({cur, ans});
  return mp[cur];
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int t;
  cin >> t;
  REP(num, t) {
    ll n;
    cin >> n >> c[0] >> c[1] >> c[2] >> d;
    map<ll, ll> mp;
    mp.insert({0LL, 0LL});
    mp.insert({1LL, d});
    rec(n, mp);
    cout << mp[n] << endl;
  }

  return 0;
}

