long long m[] = {2, 3, 5};
long long cst[3], d;
map<long long, long long> dp;

long long go(long long n) {
	if (n == 0) return 0;
	if (n == 1) return d;
	if (dp.find(n) != dp.end()) return dp[n];

	long long ans = 1e18;
	long long nxt, tmp;

	for (int i = 0; i < 3; i++) {
		nxt = n, tmp = 0;
		while (nxt % m[i]) {nxt--; tmp += d;}	
		ans = min(ans, tmp + min(cst[i], d*min(1000000000LL, nxt - (nxt/m[i]))) + go(nxt/m[i]));

		nxt = n, tmp = 0;
		while (nxt % m[i]) {nxt++; tmp += d;}	
		ans = min(ans, tmp + min(cst[i], d*min(1000000000LL, nxt - (nxt/m[i]))) + go(nxt/m[i]));
	}

	return dp[n] = ans;
}

void solve() {
	long long n;
	cin >> n >> cst[0] >> cst[1] >> cst[2] >> d;

	dp.clear();
	cout << go(n) << '\n';
}

