void solve(ll now,ll cost){
    if(now<0){
    return;
  }
  if(now==0){
    ans = min(ans,cost);
    return;
  }

  if(past.find(now)==past.end()){
    past.insert({now,cost});
  }else{
    if(past[now]<=cost){
      return;
    }else if(past[now]>cost){
      past[now]=cost;
    }
  }

  if(ans<=cost)return;

  solve((now - now%5)/5,cost+c + d*(now%5));

  if(ans<=cost)return

  solve((now - now%3)/3,cost+b+d*(now%3));

  if(ans<=cost)return;
  solve((now - now%2)/2,cost+a+d*(now%2));
  if(ans<=cost)return;
  solve(now-1,cost+d);
  if(ans<=cost)return;
  solve(now+1,cost+d);
  if(ans<=cost)return;
  return;
}
