typedef long long ll;

map<ll, ll> memo;
ll N, A, B, C, D;

ll Recursive(ll n){
	if(n == 1){
		return D;
	}
	if(n == 0){
		return LLONG_MAX / 2;
	}
	else if(memo.find(n) != memo.end()){
		return memo[n];
	}

	ll value = LLONG_MAX;
	// 2の倍数
	if(n % 2 == 1){
		ll nextN = (n+1)/2;
		value = min(value, Recursive(nextN) + min(A+D, n < 1000000000 ? D*(n-nextN) : LLONG_MAX));
		nextN = (n-1)/2;
		value = min(value, Recursive(nextN) + min(A+D, n < 1000000000 ? D*(n-nextN) : LLONG_MAX));
	}else{
		ll nextN = n/2;
		value = min(value, Recursive(nextN) + min(A, n < 1000000000 ? D*(n-nextN) : LLONG_MAX));
	}
	// 3の倍数
	if(n % 3 == 0){
		ll nextN = n/3;
		value = min(value, Recursive(nextN) + min(B, n < 1000000000 ? D*(n-nextN) : LLONG_MAX));
	}
	else if(n % 3 == 1){
		ll nextN = (n-1)/3;
		value = min(value, Recursive(nextN) + min(B+D, n < 1000000000 ? D*(n-nextN) : LLONG_MAX));
	}
	else{
		ll nextN = (n+1)/3;
		value = min(value, Recursive(nextN) + min(B+D, n < 1000000000 ? D*(n-nextN) : LLONG_MAX));
	}

	// 5の倍数
	if(n % 5 == 0){
		ll nextN = n/5;
		value = min(value, Recursive(nextN) + min(C, n < 1000000000 ? D*(n-nextN) : LLONG_MAX));
	}
	else if(n % 5 == 1 || n % 5 == 4){
		ll nextN = n % 5 == 1 ? (n-1)/5 : (n+1)/5;
		value = min(value, Recursive(nextN) + min(C+D, n < 1000000000 ? D*(n-nextN) : LLONG_MAX));
	}else{
		ll nextN = n % 5 == 2 ? (n-2)/5 : (n+2)/5;
		value = min(value, Recursive(nextN) + min(C+2*D, n < 1000000000 ? D*(n-nextN) : LLONG_MAX));
	}

	// 1減らすだけで0にする場合
	if(n < 1000000000){
		ll nextN = 1;
		value = min(value, Recursive(nextN) + D*(n-nextN));
	}

	memo[n] = value;
	return value;
}

