struct myStack {

ll a[N], n = 0;

ll & operator [] (ll x) { return a[x]; }

void clear (void) { n = 0; }
ll size (void) { return n; }
void push (ll x) { a[++ n] = x; }
void pop (void) { n --; }
ll & top (void) { return a[n]; }

} s;

ll h[N];

ll calc (ll now) {
	int m = s.size();
	h[m + 1] = 1;
	for (int i = m; i >= 1; i --) {
		h[i] = h[i + 1] * s[i];
	}
	ll ret = 0;
	for (int i = 1; i <= m + 1; i ++) {
		ll t = now / h[i];
		now %= h[i];
		if (now > h[i] - now) {
			ll diff = now * 2 - h[i];
			if (i != m + 1 && diff > h[i + 1]) {
				ret += t + 1;
				now = h[i] - now;
			} else {
				ret += t;
			}
		} else {
			ret += t;
		}
	}
	if (ret > 1e9) return LIM;
	return ret * d;
}


ll dfs (ll now) {
	if (dp.count(now)) 
		return dp[now];
	if (now >= n)
		return dp[now] = calc(now - n);

	dp[now] = calc(n - now);
	s.push(2);
	dp[now] = min(dp[now], a + dfs(now * 2));
	s.pop();
	s.push(3); 
	dp[now] = min(dp[now], b + dfs(now * 3));
	s.pop();
	s.push(5);
	dp[now] = min(dp[now], c + dfs(now * 5));
	s.pop();
	return dp[now];
}

