bool isOverflow(long long a, long long b) 
{ 
    // Check if either of them is zero 
    if (a == 0 || b == 0)  
        return false; 

    long long result = a * b; 
    if (a == result / b) 
        return false; 
    else
        return true; 
} 

int rec(int n)
{
    if(n<=1)
        return 0;
    if(dp.find(n)!=dp.end())
        return dp[n];
    int x,y,z,ans;
    x=rec(n/2)+d*(n%2);
    if(n%2)
        x=min(rec(n/2)+d*(n%2),rec(n/2+1)+d*(2-n%2));
    x+=a;
    y=rec(n/3)+d*(n%3);
    if(n%3)
        y=min(rec(n/3)+d*(n%3),rec(n/3+1)+d*(3-n%3));
    y+=b;
    z=rec(n/5)+d*(n%5);
    if(n%5)
        z=min(rec(n/5)+d*(n%5),rec(n/5+1)+d*(5-n%5));
    z+=c;
    ans=min(x,min(y,z));
    if(!isOverflow(n-1,d))
        ans=min(ans,(n-1)*d);
    //cout<<n<<" "<<ans<<endl;
    dp[n]=ans;
    return ans;
}
