namespace IO
{
	template <typename T> inline void read(T &x)
	{
		int f = 1; x = 0; char c = getchar();
		for (; !isdigit(c); c = getchar()) if (c == '-') f = -1;
		for (; isdigit(c); c = getchar()) x = (x << 3) + (x << 1) + (c ^ 48);
		x *= f;
	}

	template <typename T> inline void chkmax(T &x, T y) { x = x > y ? x : y; }
	template <typename T> inline void chkmin(T &x, T y) { x = x < y ? x : y; }

	template <typename T> inline void write(T x)
	{
		if (x < 0) putchar('-'), x = -x;
		if (x > 9) write(x / 10);
		putchar(x % 10 + '0');
	}
	template <typename T> inline void writesp(T x) { write(x); putchar(' '); }
	template <typename T> inline void writeln(T x) { write(x); putchar('\n'); }
}
using namespace IO;
ll n, a, b, c, d;
map <ll, ll> f;
inline ll solve(ll n)
{
	if (n == 0) return 0;
	if (n == 1) return d;
	if (f.count(n)) return f[n];
	ll ret = LONG_LONG_MAX / 2;
	if (ret / d > n) ret = d * n;

	if (n % 2 == 0) chkmin(ret, solve(n / 2) + a);
	if (n % 3 == 0) chkmin(ret, solve(n / 3) + b);
	if (n % 5 == 0) chkmin(ret, solve(n / 5) + c);

	if (n % 2 == 1) chkmin(ret, a + d + min(solve(n / 2), solve(n / 2 + 1)));

	if (n % 3 == 1) chkmin(ret, b + min(1 * d + solve(n / 3), 2 * d + solve(n / 3 + 1)));
	if (n % 3 == 2) chkmin(ret, b + min(2 * d + solve(n / 3), 1 * d + solve(n / 3 + 1)));

	if (n % 5 == 1) chkmin(ret, c + min(1 * d + solve(n / 5), 4 * d + solve(n / 5 + 1)));
	if (n % 5 == 2) chkmin(ret, c + min(2 * d + solve(n / 5), 3 * d + solve(n / 5 + 1)));
	if (n % 5 == 3) chkmin(ret, c + min(3 * d + solve(n / 5), 2 * d + solve(n / 5 + 1)));
	if (n % 5 == 4) chkmin(ret, c + min(4 * d + solve(n / 5), 1 * d + solve(n / 5 + 1)));

	return f[n] = ret;
}
inline void doit()
{
	read(n); read(a); read(b); read(c); read(d);
	writeln(solve(n));
}
int main(){
	int T;
	read(T);
	while (T--) {
		f.clear();
		doit();
	}
  return 0;
}

