    if(abs(N-3*(N/3))<(INF+1000)/D) res=min(res,D*abs(N-3*(N/3))+B+dfs(N/3));
    if(abs(N-3*((N+2)/3))<(INF+1000)/D) res=min(res,D*abs(N-3*((N+2)/3))+B+dfs((N+2)/3));
