// 0 → x にかかるコストを求める
long long func(long long x){
	if(x == 0) return 0;
	if(memo.count(x)){
		return memo[x];
	}

	long long ans = INF;
	if(INF/d > x){
		ans = x * d;
	}

	auto func2 = [&](long long y){
		if(y >= x){ // 更新しても、小さくならなかったとき
			return INF;
		}
		return func(y);
	};

	{
		long long floo = x/2 * 2;
		long long cell = floo + 2;
		ans = std::min(ans, func2(floo/2) + a + (x-floo) * d);
		ans = std::min(ans, func2(cell/2) + a + (cell-x) * d);
	}
	{
		long long floo = x/3 * 3;
		long long cell = floo + 3;
		ans = std::min(ans, func2(floo/3) + b + (x-floo) * d);
		ans = std::min(ans, func2(cell/3) + b + (cell-x) * d);
	}
	{
		long long floo = x/5 * 5;
		long long cell = floo + 5;
		ans = std::min(ans, func2(floo/5) + c + (x-floo) * d);
		ans = std::min(ans, func2(cell/5) + c + (cell-x) * d);
	}

	return memo[x] = ans;
}

