ll GetValFor(const ll n, const ll v, const ll div) {
  ll rem1 = n % div;
  ll rem2 = div - rem1;
  ll ans = rem1 * d + v + solve((n - rem1) / div);
  if (rem1 != 0) {
    ans = min(ans, rem2 * d + v + solve((n + rem2) / div));
  }
  return ans;
}

// ll recC = 0;
ll solve(const ll n) {
  // recC++;
  if (n == 0) {
    return 0;
  }
  if (n == 1) {
    return d;
  }
  if (vals.find(n) != vals.end())
    return vals[n];
  ll vv = GetMin({GetValFor(n, a, 2), GetValFor(n, b, 3), GetValFor(n, c, 5)});
  if ((double)n < (double)vv / d)
    vv = d * n;
  return vals[n] = vv;
}

