    r = div[i] - r;
    ll nx = n / div[i] + 1;
    if (nx >= n) continue;
    ans = min(ans, solve(n / div[i] + 1, a, b, c, d, memo) + d * r + cst[i]);
  }
  if (n <= 1e9) {
    ans = min(ans, d * n);
  }
  memo[n] = ans;
  return ans;
}

