ll cost(ll x){
    if(x == 0) return 0;
    if(x == 1) return d;
    if(memo.count(x)) return memo[x];

    ll result = LLONG_MAX / d > x ? x * d : LLONG_MAX;
    ll rate, pay;

    rate = 2;
    pay = a;
    chmin(result, cost(x / rate) + x % rate * d + pay);
