typedef long long ll;

const ll Inf = 4e18;

ll mul(ll a, ll b) {
  if (a <= Inf / b) return min(Inf, a * b);
  else return Inf;
}

void add(ll &a, ll b) {
  a += b;
  a = min(a, Inf);
}

ll ans, n;
int a, b, c, d;

void rec1(vector <int> have, ll pr) {
  if (pr == Inf) return;
  vector <ll> pref;
  pref.push_back(1);
  for (int i = (int)have.size() - 1; i >= 0; --i) {
    pref.push_back(mul(pref.back(), have[i]));
  }
  reverse(pref.begin(), pref.end());
  ll need = abs(n - pr);
  ll extra = 1;
  for (int i = 0; i < (int)pref.size(); ++i) {
    add(extra, need / pref[i]);
    need %= pref[i];
  }
  ll all = mul(extra, d);
  for (int x : have) {
    if (x == 2) add(all, a);
    if (x == 3) add(all, b);
    if (x == 5) add(all, c);
  }
  ans = min(ans, all);
  for (int nx : {5, 3, 2}) {
    if (have.empty() || nx <= have.back()) {
      have.push_back(nx);
      rec1(have, mul(pr, nx));
      have.pop_back();
    }
  }
}

void rec2(vector <int> have, ll pr) {
  if (pr == Inf) return;
  vector <ll> pref;
  pref.push_back(1);
  for (int i = (int)have.size() - 1; i >= 0; --i) {
    pref.push_back(mul(pref.back(), have[i]));
  }
  reverse(pref.begin(), pref.end());
  ll need = abs(n - pr);
  ll extra = 1;
  for (int i = 0; i < (int)pref.size(); ++i) {
    add(extra, need / pref[i]);
    need %= pref[i];
  }
  ll all = mul(extra, d);
  for (int x : have) {
    if (x == 2) add(all, a);
    if (x == 3) add(all, b);
    if (x == 5) add(all, c);
  }
  ans = min(ans, all);
  for (int nx : {2, 3, 5}) {
    if (have.empty() || nx >= have.back()) {
      have.push_back(nx);
      rec2(have, mul(pr, nx));
      have.pop_back();
    }
  }
}

