#include <bits/stdc++.h>

using namespace std;

using ll = long long;

constexpr char newl = '\n';
constexpr ll INF = 1e18;

ll solve(ll n, ll a, ll b, ll c, ll d, map<ll, ll>& memo) {
    if (n == 0) return 0;
    if (memo.find(n) != memo.end()) return memo[n];

    ll res = solve(n / 2, a, b, c, d, memo) + n % 2 * d + (ll)min((__int128_t)a, (__int128_t)n / 2 * d);


    ll tar = (n + 2 - n % 2) / 2;
    if (tar < n) {
        res = min(res, solve(tar, a, b, c, d, memo) + (2 - n % 2) * d + (ll)min((__int128_t)a, (__int128_t)tar * d));
    }

    res = min(res, solve(n / 3, a, b, c, d, memo) + n % 3 * d + (ll)min((__int128_t)b, (__int128_t)n / 3 * 2 * d));

    tar = (n + 3 - n % 3) / 3;
    if (tar < n) {
        res = min(res, solve(tar, a, b, c, d, memo) + (3 - n % 3) * d + (ll)min((__int128_t)b, (__int128_t)tar * 2 * d));
    }

    res = min(res, solve(n / 5, a, b, c, d, memo) + n % 5 * d + (ll)min((__int128_t)c, (__int128_t)n / 5 * 4 * d));

    tar = (n + 5 - n % 5) / 5;
    if (tar < n) {
        res = min(res, solve(tar, a, b, c, d, memo) + (5 - n % 5) * d + (ll)min((__int128_t)c, (__int128_t)tar * 4 * d));
    }

    __int128_t tmp = n;
    tmp *= d;
    if (tmp < INF) {
        res = min(res, n * d);
    }
    return memo[n] = res;
}

