map <ll, ll> M;

ll Solve(ll x)
{
    if (x == 0) return 0;
    if (x == 1) return d;
    map <ll, ll>::iterator it = M.find(x);
    if (it == M.end()) {
        ll res = Inf;
        if (x <= Inf / d) res = x * d;
        res = min(res, a + Solve(x / 2) + (x % 2) * d);
        if (x / 2 + 1 < x)
            res = min(res, a + Solve(x / 2 + 1) + (2 - x % 2) * d);
        res = min(res, b + Solve(x / 3) + (x % 3) * d);
        if (x / 3 + 1 < x)
            res = min(res, b + Solve(x / 3 + 1) + (3 - x % 3) * d);
        res = min(res, c + Solve(x / 5) + (x % 5) * d);
        if (x / 5 + 1 < x)
            res = min(res, c + Solve(x / 5 + 1) + (5 - x % 5) * d);
        M.insert(make_pair(x, res));
        return res;
    }
    return it->second;
}

