ll mod = 1000000007;

ul solve(map<ul, ul> &m, ul n, ul a, ul b, ul c, ul d) {
    if (m[n] != 0) {
        return m[n];
    }
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return d;
    }
    ul ans = d * n;
    if (n % 2 == 0) {
        ul temp = solve(m, n / 2, a, b, c, d) + a;
        ans = min(temp, ans);
    } else {
        ul temp0 = solve(m, (n - 1) / 2, a, b, c, d) + d + a;
        ul temp1 = solve(m, (n + 1) / 2, a, b, c, d) + d + a;
        ul temp = min(temp0, temp1);
        ans = min(temp, ans);
    }
    if (n % 3 == 0) {
        ul temp = solve(m, n / 3, a, b, c, d) + b;
        ans = min(temp, ans);
    } else {
        ul num = n % 3;
        ul temp0 = solve(m, (n - num) / 3, a, b, c, d) + d * num + b;
        ul temp1 =
            solve(m, (n + (3 - num)) / 3, a, b, c, d) + d * (3 - num) + b;
        ul temp = min(temp0, temp1);
        ans = min(temp, ans);
    }
    if (n % 5 == 0) {
        ul temp = solve(m, n / 5, a, b, c, d) + c;
        ans = min(temp, ans);
    } else {
        ul num = n % 5;
        ul temp0 = solve(m, (n - num) / 5, a, b, c, d) + d * num + c;
        ul temp1 =
            solve(m, (n + (5 - num)) / 5, a, b, c, d) + d * (5 - num) + c;
        ul temp = min(temp0, temp1);
        ans = min(temp, ans);
    }

    m[n] = ans;
    return ans;
}

