const ll INF = ll(6e18);

ll mult(ll a, ll b)
{
	if(a==0||b==0) return 0;
	if(a>=INF/b) return INF;
	return a*b;
}

ll add(ll a, ll b)
{
	if(a>=INF-b) return INF;
	return a+b;
}

void dfs(vector<vector<ll> > &seqs, vector<ll> &v, ll cur = 1)
{
	cout<<seqs.size()<<endl;
	bool nopush=1;
	if(mult(cur,2)<INF)
	{
		nopush=0;
		v.pb(2);
		dfs(seqs,v,cur*2);
		v.pop_back();
	}
	if(mult(cur,3)<INF)
	{
		nopush=0;
		v.pb(3);
		dfs(seqs,v,cur*3);
		v.pop_back();
	}
	if(mult(cur,5)<INF)
	{
		nopush=0;
		v.pb(5);
		dfs(seqs,v,cur*5);
		v.pop_back();
	}
	if(nopush) seqs.pb(v);
}

void solve()
{
	ll n,a,b,c,d; cin>>n>>a>>b>>c>>d;
	ll ans = ll(9e18);
	vector<ll> cost = {0,0,a,b,0,c};
	vi p = {2,3,5};
	do
	{
		vector<ll> v;
		v.pb(1);
		ll curi = 1;
		for(int i=0;i<=60;i++)
		{
			if(i>0) v.pb(curi);
			ll curj=curi;
			for(int j=0;j<=60;j++)
			{
				ll curk=curj;
				if(j>0) v.pb(curj);
				for(int k=0;k<=60;k++)
				{
					if(k>0) v.pb(curk);
					ll val = cost[p[0]]*i+cost[p[1]]*j+cost[p[2]]*k;
					//cerr<<i<<' '<<j<<' '<<k<<' '<<val<<'\n';
					//for(ll x:v) cerr<<x<<' ';
					//cerr<<'\n';
					//greedy?
					ll curn=n;
					for(int z=int(v.size())-1;z>=0;z--)
					{
						ll x = v[z];
						if(curn==0) break;
						if(curn>0)
						{
							ll q = curn/x;
							val=add(mult(q,d),val);
							curn-=q*x;
							if(abs(curn-x)<abs(curn))
							{
								curn-=x;
								val+=d;
							}
						}
						else
						{
							ll q = abs(curn)/x;
							val=add(mult(q,d),val);
							curn+=q*x;
							if(abs(curn+x)<abs(curn))
							{
								curn+=x;
								val+=d;
							}
						}
					}
					ans=min(ans,val);
					curk=mult(curk,p[2]);
					if(curk>=INF) 
					{
						for(int z=1;z<=k;z++) v.pop_back();
						break;
					}
				}
				curj=mult(curj,p[1]);
				if(curj>=INF) 
				{
					for(int k=1;k<=j;k++) v.pop_back();
					break;
				}
			}
			curi=mult(curi,p[0]);
			if(curi>=INF) break;
		}
	}while(next_permutation(p.begin(),p.end()));
	cout<<ans<<'\n';
}

