map<ll, ll> memo;

ll f(ll n)
{
  if (n == 0)
    return 0;
  if (memo.count(n))
    return memo[n];

  ll Min = LINF;
  ll down, up;
  // 2
  down = n / 2 * 2, up = CEIL(n, 2) * 2;
  if (n - down <= up - n)
    chmin(Min, (n - down) * d + f(down / 2) + a);
  else
    chmin(Min, (up - n) * d + f(up / 2) + a);
  // 3
  down = n / 3 * 3, up = CEIL(n, 3) * 3;
  if (n - down <= up - n)
    chmin(Min, (n - down) * d + f(down / 3) + b);
  else
    chmin(Min, (up - n) * d + f(up / 3) + b);
  // 5
  down = n / 5 * 5, up = CEIL(n, 5) * 5;
  if (n - down <= up - n)
    chmin(Min, (n - down) * d + f(down / 5) + c);
  else
    chmin(Min, (up - n) * d + f(up / 5) + c);
  // そのまま
  ll result;
  if (!__builtin_smulll_overflow(n, d, &result))
    chmin(Min, result);
  return memo[n] = Min;
}

