ll ans(ll n, ll a, ll b, ll c, ll d, map<ll,ll> &memo){
  if(n==0) return 0;
  if(n==1) return d;
  if(memo.count(n)) return memo.at(n);

  ll ko1 = ans(n/2,a,b,c,d,memo) + (n%2)*d + a;
  ll ko2 = ans((n+1)/2,a,b,c,d,memo) + (n%2)*d + a; 
  ll ko3 = ans(n/3,a,b,c,d,memo) + (n%3)*d + b;
  ll ko4 = ans((n+2)/3,a,b,c,d,memo) + (2-((n-1)%3))*d + b;
  ll ko5 = ans(n/5,a,b,c,d,memo) + (n%5)*d + c;
  ll ko6 = ans((n+4)/5,a,b,c,d,memo) + (4-((n-1)%5))*d + c; 

  vector<ll> p={ko1,ko2,ko3,ko4,ko5,ko6};
  sort(all(p));

  if(p[0]/d>n) p[0]=d*n;

  memo[n]=p[0];

  return p[0];
}


