  int T;
  cin >> T;
  for (int i = 0; i < T; i++){
    long long N, A, B, C, D;
    cin >> N >> A >> B >> C >> D;
    map<long long, long long> mp;
    cout << dp(N, A, B, C, D, mp) << endl;
  }
}

