int main() {
    int t; cin >> t;
    while (t--) {
        long long N, A, B, C, D; cin >> N >> A >> B >> C >> D;
        priority_queue<pair<long long, long long> > pq;
        pq.push({0LL, N});
        unordered_map<long long, long long> dist;
        dist[N] = 0;
        function<void(long long, long long)> add = [&](long long x, long long c) {
            if (dist.find(x) == dist.end() || dist[x] > c) {
                dist[x] = c;
                pq.push({-c, x});
            }
        };
        int count = 0;
        while (!pq.empty()) {
            count++;
            long long c = -pq.top().first, n = pq.top().second;
            pq.pop();
            if (dist.find(n) != dist.end() && dist[n] < c) continue;
            if (n == 1) {
                cerr << count << endl;
                cout << c + D << endl;
                break;
            }
            for (int d : {2, 3, 5}) {
                long long cost = d == 2 ? A : d == 3 ? B : C;
                long long r = n / d;
                if (n - r > 1e9) {
                    add(r, c + D * (n % d) + cost);
                    add(r+1, c + D * (d - n % d) + cost);
                } else {
                    add(r, c + min(D * (n - r), D * (n % d) + cost));
                    add(r+1, c + min(D * (n - r - 1), D * (d - n % d) + cost));
                }
            }
        }
    }
}

