using namespace std;

typedef long long ll;

const ll t[3]={2,3,5};

ll c[3],d;
unordered_map<ll,ll> memo;
ll solve(ll n){
	if(n==0)return 0;
	if(n==1)return d;
	if(memo.find(n)!=memo.end())return memo[n];
	ll ret=1000000000000000000;
	if((long double)d*(long double)n<=ret){
		ret=d*n;
	}
	for(int k=0;k<3;k++){
		ll a=n/t[k];
		ll b=n%t[k];
		if(k==0){
			ret=min(ret,solve(a)+c[k]+b*d);
			if(a+1!=n)ret=min(ret,solve(a+1)+c[k]+(t[k]-b)*d);
		}
		else {
			if(b<=t[k]-b){
				ret=min(ret,solve(a)+c[k]+b*d);
			}
			else {
				ret=min(ret,solve(a+1)+c[k]+(t[k]-b)*d);
			}
		}
	}
	memo[n]=ret;
	return ret;
}

int main(){
	int T;
	scanf("%d",&T);
	for(;T>0;T--){
		ll n;
		cin>>n>>c[0]>>c[1]>>c[2]>>d;
		cout<<solve(n)<<endl;
		memo.clear();
	}
}

