ll tr(ll x,ll y){
	if (INF/(x-y)>=D)return D*(x-y);
	return INF;
}
void get(ll x,ll y){
	if (s[x]==0){s[x]=y;p.insert(x);}else s[x]=min(s[x],y);
}
int main(){
