			auto g=p.end();g--;
			ll x=(*g);p.erase(g);
			ll y=s[x];if (y>s[0])continue;
			get(x/2,y+min(A+D*(x-(x/2)*2),tr(x,x/2)));
			if (x%2!=0)get(x/2+1,y+min(A+D,tr(x,x/2+1)));
			if (x%3<=1)get(x/3,y+min(B+D*(x-(x/3)*3),tr(x,x/3)));
			if (x%3>1)get(x/3+1,y+min(B+D*((x/3+1)*3-x),tr(x,x/3+1)));
			if (x%5<3)get(x/5,y+min(C+D*(x-(x/5)*5),tr(x,x/5)));
			if (x%5>2)get(x/5+1,y+min(C+D*((x/5+1)*5-x),tr(x,x/5+1)));
		}
		cout<<s[0]<<endl;
	}
