	REP(u,-2,2) if (n+u>=0&&(n+u)%3==0) {
		t = solve((n+u)/3);
		ans=min(ans,t+b+abs(u)*d);
		if (2*n/3<=(ans-t-abs(u)*d)/d) ans=t+2*n/3*d+abs(u)*d;
	}
	REP(u,-4,4) if (n+u>=0&&(n+u)%5==0) {
		t = solve((n+u)/5);
		ans=min(ans,t+c+abs(u)*d);
		if (4*n/5<=(ans-t-abs(u)*d)/d) ans=t+4*n/5*d+abs(u)*d;
	}
	if (n>mi/d&&ans!=4e18) { 
		dp[n]=ans;
	}
	else dp[n]=min(ans,solve(n-1)+d);
	return dp[n];
}

void work() {
	dp.clear();
	scanf("%lld%lld%lld%lld%lld",&n,&a,&b,&c,&d);
	mi=min({a,b,c,d});
	dp[1]=d;
	printf("%lld\n",solve(n));
}
int main() {
	int t;
	scanf("%d", &t);
	while (t--) work();
}

