long long modinv(long long a, long long m) {
    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

long long gcd(long long a, long long b)
{
   if (a%b == 0)
   {
       return(b);
   }
   else
   {
       return(gcd(b, a%b));
   }
}

map<long long, long long> costs;
long long solve(long long N, long long A, long long B, long long C, long long D, long long maxN, int depth) {
    if (depth == 100) {
        return 10e+18;
    }
    if (N == 1) {
        return D;
    } else if (costs[N] != 0) {
        return costs[N];
    }

    costs[N] = 10e+18;
    if (N < 10e+16 / D) {
        costs[N] = N * D;
    }
    if (N % 2 == 0) {
        costs[N] = min(costs[N], A + solve(N / 2, A, B, C, D, maxN, depth + 1));
    } else {
        if (N + 1 < maxN) {
            costs[N] = min(costs[N], D + A + solve((N+1) / 2, A, B, C, D, maxN, depth + 1));
        }
        costs[N] = min(costs[N], D + A + solve((N-1) / 2, A, B, C, D, maxN, depth + 1));
    }

    if (N % 3 == 0) {
        costs[N] = min(costs[N], B + solve(N / 3, A, B, C, D, maxN, depth + 1));
    } else {
        long long m = N % 3;
        if (N + (3 - m) < maxN) {
            costs[N] = min(costs[N],  (3 - m) * D + B + solve((N+ (3 - m)) / 3, A, B, C, D, maxN, depth + 1));
        }

        if (N > 3) {
            costs[N] = min(costs[N], m * D + B + solve((N-m) / 3, A, B, C, D, maxN, depth + 1));
        }
    }

    if (N % 5 == 0) {
        costs[N] = min(costs[N], C + solve(N / 5, A, B, C, D, maxN, depth + 1));
    } else {
        long long m = N % 5;
        if (N + (5 - m) < maxN) {
            costs[N] = min(costs[N],  (5 - m) * D + C + solve((N+ (5 - m)) / 5, A, B, C, D, maxN, depth + 1));
        }

        if (N > 5) {
            costs[N] = min(costs[N], m * D + C + solve((N-m) / 5, A, B, C, D, maxN, depth + 1));
        }
    }
//    cout << "returning " << costs[N] << " for " << N << endl;
    return costs[N];
}

