using cat = long long;

cat A, B, C, D, ans;
constexpr int MX = 2000000;
vector<cat> ans_sm(MX+1);
map<cat, cat> ans_cache;

void prec(cat N) {
	ans_sm[N] = D*N;
	if(N <= 1) return;
	cat d3 = N%3, d5 = N%5, n3 = N/3, n5 = N/5;
	if(d3 == 2) d3 = 1, n3++;
	if(d5 == 3) d5 = 2, n5++;
	if(d5 == 4) d5 = 1, n5++;
	ans_sm[N] = min(ans_sm[N], d5*D+C+ans_sm[n5]);
	ans_sm[N] = min(ans_sm[N], d3*D+B+ans_sm[n3]);
	cat d2 = N%2, n2 = N/2;
	ans_sm[N] = min(ans_sm[N], d2*D+A+ans_sm[n2]);
	if(d2) ans_sm[N] = min(ans_sm[N], d2*D+A+ans_sm[n2+1]);
}

int main() {
	cin.sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);
	int T;
	cin >> T;
	while(T--) {
		cat N;
		cin >> N >> A >> B >> C >> D;
		for(int i = 0; i <= MX; i++) prec(i);
		ans = 1000*(A+D);
		ans_cache.clear();
		ans_cache[N] = 0;
		auto it = begin(ans_cache);
		while(true) {
			cat cur = it->first, cur_ans = it->second;
			if(cur <= MX) ans = min(ans, cur_ans + ans_sm[cur]);
			else if(cur_ans < ans) {
				if(cur <= ans/D) ans = min(ans, cur_ans+D*cur);
				cat d3 = cur%3, d5 = cur%5, n3 = cur/3, n5 = cur/5;
				if(d3 == 2) d3 = 1, n3++;
				if(d5 == 3) d5 = 2, n5++;
				if(d5 == 4) d5 = 1, n5++;
				cat d2 = cur%2, n2 = cur/2;
				auto jt = ans_cache.find(n5);
				if(jt == end(ans_cache)) ans_cache[n5] = cur_ans+d5*D+C;
				else jt->second = min(jt->second, cur_ans+d5*D+C);
				jt = ans_cache.find(n3);
				if(jt == end(ans_cache)) ans_cache[n3] = cur_ans+d3*D+B;
				else jt->second = min(jt->second, cur_ans+d3*D+B);
				jt = ans_cache.find(n2);
				if(jt == end(ans_cache)) ans_cache[n2] = cur_ans+d2*D+A;
				else jt->second = min(jt->second, cur_ans+d2*D+A);
				if(d2) {
					jt = ans_cache.find(n2+1);
					if(jt == end(ans_cache)) ans_cache[n2] = cur_ans+d2*D+A;
					else jt->second = min(jt->second, cur_ans+d2*D+A);
				}
			}
			if(it == begin(ans_cache)) break;
			it--;
		}
		cout << ans << endl;
	}
}

