long long max_co(long long N){
	//cout<<N<<endl;
	if(dp.count(N)){
		return dp[N];
	}
	long long ans = INF;
	if(N==1) return D;
	if(N==0) return 0;
	vector<int> aii(3,0);
	if(N%2 == 0){
		aii[0] = 1;
		long long p = max_co(N/2);
