			ans = min(p+((N/2)*D),ans);
		}
	}
	if(N%3==0){
		aii[1] = 1;
		long long p = max_co(N/3);
		ans = min(p+B,ans);
		if(((N*2)/3)<INF/D){
			ans = min(p+(D*((N*2)/3)),ans);
		}
