int main() {
  int T;
  cin>>T;
  ll N, A, B, C, D;
  pair<ll, ll> state;
  ll ans[T];
  for(int i=0;i<T;++i) {
    cin>>N>>A>>B>>C>>D;
    priority_queue<pair<ll, ll>, vector<pair<ll, ll> >, greater<pair<ll, ll> > > que;
    map<ll, ll> amap;
    que.push(mp(0, N));
    while(!que.empty()) {
      state = que.top();que.pop();
      if(amap[state.se]>0) continue;
      amap[state.se] = state.fi;
      if(state.se==0) break;
      if(state.se%2==0 && amap[state.se/2]==0 && state.se/2!=N) {
        if(A/D>=state.se/2) {
          que.push(mp(state.fi+(state.se/2)*D, state.se/2));
        }
        else que.push(mp(state.fi+A, state.se/2));
      }
      if(state.se%3==0 && amap[state.se/3]==0 && state.se/3!=N) {
        if(B/D>=state.se/3*2) {
          que.push(mp(state.fi+(state.se/3*2)*D, state.se/3));
        }
        else que.push(mp(state.fi+B, state.se/3));
      }
      if(state.se%5==0 && amap[state.se/5]==0 && state.se/5!=N) {
        if(C/D>=state.se/5*4) {
          que.push(mp(state.fi+(state.se/5*4)*D, state.se/5));
        }
        else que.push(mp(state.fi+C, state.se/5));
      }
      if(amap[state.se-(state.se%2)]==0 && state.se-(state.se%2)!=N) {
        que.push(mp(state.fi+(state.se%2)*D, state.se-(state.se%2)));
      }
      if(amap[state.se-(state.se%3)]==0 && state.se-(state.se%3)!=N) {
        que.push(mp(state.fi+(state.se%3)*D, state.se-(state.se%3)));
      }
      if(amap[state.se-(state.se%5)]==0 && state.se-(state.se%5)!=N) {
        que.push(mp(state.fi+(state.se%5)*D, state.se-(state.se%5)));
      }
      if(amap[state.se+(2-state.se%2)%2]==0 && state.se+(2-state.se%2)%2!=N) {
        que.push(mp(state.fi+((2-state.se%2)%2)*D, state.se+(2-state.se%2)%2));
      }
      if(amap[state.se+(3-state.se%3)%3]==0 && state.se+(3-state.se%3)%3!=N) {
        que.push(mp(state.fi+((3-state.se%3)%3)*D, state.se+(3-state.se%3)%3));
      }
      if(amap[state.se+(5-state.se%5)%5]==0 && state.se+(5-state.se%5)%5!=N) {
        que.push(mp(state.fi+((5-state.se%5)%5)*D, state.se+(5-state.se%5)%5));
      }
    }
