const ll mod=1e9+7;
//const ll mod=998244353;
const ll inf=1LL<<61;

ll a,b,c,d;
map<ll,ll> dp;
ll dfs(ll n) {
  if(n<2) return n*d;
  if(dp.count(n)) return dp[n];
  ll &res=dp[n]=1LL<<62;
  if(res/d>=n) res=n*d;
  res=min(res,dfs(n/2)+a+d*abs(n/2*2-n));
  res=min(res,dfs(n/3)+b+d*abs(n/3*3-n));
  res=min(res,dfs(n/5)+c+d*abs(n/5*5-n));
  res=min(res,dfs((n+1)/2)+a+d*abs((n+1)/2*2-n));
  res=min(res,dfs((n+2)/3)+b+d*abs((n+2)/3*3-n));
  res=min(res,dfs((n+4)/5)+c+d*abs((n+4)/5*5-n));

  return res;
}

int main() {
  ll t;
  cin >> t;
  while(t--) {
    ll n;
    dp.clear();
    cin >> n >> a >> b >> c >> d;
    cout << dfs(n) << endl;
  }
}

#include <iostream>
#include <unordered_map>
#include <vector>
#define rep(i, n) for (int i = 0; i < (n); ++i)
using namespace std;
int64_t A, B, C, D;
unordered_map<int64_t, int64_t> memo;

int64_t solve(int64_t N) {
  if (N == 0)
    return 0;
  else if (N == 1)
    return D;
  if (memo.count(N)) return memo[N];

  int64_t ret = INT64_MAX;
  if (N < ret / D) ret = N * D;

  vector<int> coin = {2, 3, 5};
  vector<int64_t> cost = {A, B, C};
  rep(i, 3) {
    int m = coin[i];
    int64_t ln = N / m;
    int64_t rn = N / m;
    ret = min(ret, abs(ln * m - N) * D + cost[i] + solve(ln));
    ret = min(ret, abs(rn * m - N) * D + cost[i] + solve(rn));
  }
  return memo[N] = ret;
}

int main(void) {
  ios::sync_with_stdio(false);
  int T;
  cin >> T;
  rep(i, T) {
    int64_t N;
    cin >> N >> A >> B >> C >> D;
    memo.clear();
    int64_t answer = solve(N);
    cout << answer << endl;
  }
  return 0;
}

