bigint dp(int n, map<int, bigint>& hash) {
  if (hash.find(n) != hash.end()) return hash[n];
  if (n == 0) return 0;
  if (n == 1) return d;
  hash[n] = infl;
  hash[n] = min(hash[n], a + dp(n/2, hash) + d * (n % 2));
  hash[n] = min(hash[n], d * (n - n/2) + dp(n/2, hash));
  hash[n] = min(hash[n], b + dp(n/3, hash) + d * (n % 3));
  hash[n] = min(hash[n], d * (n - n/3) + dp(n/3, hash));
  hash[n] = min(hash[n], c + dp(n/5, hash) + d * (n % 5));
  hash[n] = min(hash[n], d * (n - n/5) + dp(n/5, hash));
  hash[n] = min(hash[n], a + dp(n/2 + 1, hash) + d * (2 - n % 2));
  hash[n] = min(hash[n], d * (n - n/2 - 1) + dp(n/2 + 1, hash));
  hash[n] = min(hash[n], b + dp(n/3 + 1, hash) + d * (3 - n % 3));
  hash[n] = min(hash[n], d * (n - n/3 - 1) + dp(n/3 + 1, hash));
  hash[n] = min(hash[n], c + dp(n/5 + 1, hash) + d * (5 - n % 5));
  hash[n] = min(hash[n], d * (n - n/5 - 1) + dp(n/5 + 1, hash));
  return hash[n];
}

