using LL = long long;

const int MOD = 1e9 + 7;
const int INF = 0x3f3f3f3f;
const LL LLINF = 0x3f3f3f3f3f3f3f3f;
const int MAX_N = 200005;

void solve(int) {
    using P = pair<LL, LL>;
    LL N, A, B, C, D;
    cin >> N >> A >> B >> C >> D;
    priority_queue<P, vector<P>, greater<P>> pq;
    pq.push({0, N});

    LL ans = -1;
    unordered_map<LL, LL> dist;
    while(pq.size()) {
        LL cost, n;
        tie(cost, n) = pq.top();
        pq.pop();

        //debug() << imie(cost) imie(n) << endl;

        if(n == 0) {
            if(ans == -1 or ans > cost) {
                ans = cost;
            }
            break;
        }

        if(dist.find(n) != dist.end() and cost > dist[n]) {
            continue;
        }
        dist[n] = cost;

        for(int i = 0; i <= 4 and n - i >= 1; ++i) {
            auto m = n - i;
            if(i < 2 and m % 2 == 0) {
                auto cost1 = A;
                if(m - m / 2 <= LLONG_MAX / D) {
                    cost1 = min(A, D * (m - m / 2));
                }
                cost1 += i * D;
                if(dist.find(m / 2) == dist.end() or dist[m / 2] > cost + cost1) {
                    dist[m / 2] = cost + cost1;
                    pq.push({cost + cost1, m / 2});
                }
            }
            if(i < 3 and m % 3 == 0) {
                auto cost1 = B;
                if(m - m / 3 <= LLONG_MAX / D) {
                    cost1 = min(B, D * (m - m / 3));
                }
                cost1 += i * D;
                if(dist.find(m / 3) == dist.end() or dist[m / 3] > cost + cost1) {
                    dist[m / 3] = cost + cost1;
                    pq.push({cost + cost1, m / 3});
                }
            }
            if(m % 5 == 0) {
                auto cost1 = C;
                if(m - m / 5 <= LLONG_MAX / D) {
                    cost1 = min(C, D * (m - m / 5));
                }
                cost1 += i * D;
                if(dist.find(m / 5) == dist.end() or dist[m / 5] > cost + cost1) {
                    dist[m / 5] = cost + cost1;
                    pq.push({cost + cost1, m / 5});
                }
            }
        }
        if(n <= LLONG_MAX / D and (dist.find(0) == dist.end() or dist[0] > cost + n * D)) {
            dist[0] = cost + n * D;
            pq.push({cost + n * D, 0});
        }

    }
    cout << ans << endl;
}

int main() {
    int T = 1;
    cin >> T;
    for(int i = 1; i <= T; ++i) {
        solve(i);
    }
    return 0;
}

