    if (x == 1ll) return d;
    if (mem.count(x)) return mem[x];
    //printf("%lld\n",x);
    ll res = INF;
    if (x <= INF/d) res = d*x;
    ll L,R,l,r;
    L = x/2;
    R = L+1;
    l = x-L*2;
    r = R*2-x;
    res = min(res,l*d+a+dp(L));
    if (R < x) res = min(res,r*d+a+dp(R));
    L = x/3;
    R = L+1;
    l = x-L*3;
    r = R*3-x;
    res = min(res,l*d+b+dp(L));
