    L = x/5;
    R = L+1;
    l = x-L*5;
    r = R*5-x;
    res = min(res,l*d+c+dp(L));
    if (R < x) res = min(res,r*d+c+dp(R));
    //printf("%lld: %lld\n",x,res);
    return mem[x] = res;
}
