using M = map<ll, ll>;

ll INF = (1LL<<62)-1;

ll a, b, c, d;
M m;

ll f(ll n, ll val) {
  // printf("%lld, %lld\n", n, val);

  if(n < 1) {
    return INF;
  }
  if(n == 1) {
    return val + d;
  }
  if(m[n]) {
    return m[n];
  }

  ll next_val = INF;
  ll delta = 0;
  while(delta < 5) {
    if ((n + delta) % 2 == 0 && delta >= 1 && delta < 2) {
      next_val = min(next_val, f((n+delta)/2, val+delta*d+a));
    }
    if ((n - delta) % 2 == 0 && delta < 2) {
      next_val = min(next_val, f((n-delta)/2, val+delta*d+a));
    }
    if ((n + delta) % 3 == 0 && delta >= 1 && delta < 3) {
      next_val = min(next_val, f((n+delta)/3, val+delta*d+b));
    }
    if ((n - delta) % 3 == 0 && delta < 3) {
      next_val = min(next_val, f((n-delta)/3, val+delta*d+b));
    }
    if ((n + delta) % 5 == 0 && delta >= 1 && delta < 5) {
      next_val = min(next_val, f((n+delta)/5, val+delta*d+c));
    }
    if ((n - delta) % 5 == 0 && delta < 5) {
      next_val = min(next_val, f((n-delta)/5, val+delta*d+c));
    }
    delta++;
  }
  return m[n] = next_val;
}

