int main(){
    int Q;
    cin>>Q;

    while(Q--){
        ll N,A,B,C,D;
        cin>>N>>A>>B>>C>>D;

        // dp[i] := 整数iにするための最小コスト
        map<ll,ll> dp;
        dp[N]=0;

        // que.front() := 次の処理する整数
        queue<ll> que;
        que.push(N);

        // cout<<N<<endl;

        while(!que.empty()){
            ll v=que.front();que.pop();

            // 終了条件
            if(v==0)continue;

            bool ok=true;

            // 継続
            if(v%2==0){
                ll nv=v/2;

                if(dp.find(nv)==dp.end())dp[nv]=INF;
                if(dp[nv]>dp[v]+A){
                    que.push(nv);
                    dp[nv]=dp[v]+A;

                    // cout<<nv<<endl;
                }
            }else ok=false;

            if(v%3==0){
                ll nv=v/3;

                if(dp.find(nv)==dp.end())dp[nv]=INF;
                if(dp[nv]>dp[v]+B){
                    que.push(nv);
                    dp[nv]=dp[v]+B;

                    // cout<<nv<<endl;
                }
            }else ok=false;

            if(v%5==0){
                ll nv=v/5;

                if(dp.find(nv)==dp.end())dp[nv]=INF;
                if(dp[nv]>dp[v]+C){
                    que.push(nv);
                    dp[nv]=dp[v]+C;

                    // cout<<nv<<endl;
                }
            }else ok=false;

            if(!ok){
                ll nv1=v-1,nv2=v+1;

                if(dp.find(nv1)==dp.end())dp[nv1]=INF;
                if(dp[v-1]>dp[v]+D){
                    que.push(v-1);
                    dp[v-1]=dp[v]+D;

                    // cout<<nv1<<endl;
                }

                if(dp.find(nv2)==dp.end())dp[nv2]=INF;
                if(dp[v+1]>dp[v]+D){
                    que.push(v+1);
                    dp[v+1]=dp[v]+D;

                    // cout<<nv2<<endl;
                }
            }
        }

        cout<<dp[0]<<endl;

        // cout<<endl;
    }
}

