#define int long long
#define inf (int)(1e18 + 1000)

int A, B, C, D;

int solve(int N, map<int, int> &mp){
//	printf("solve(%lld)\n", N);
	if(mp.find(N) == mp.end()){
		int res = inf;
		res = min(res, A + D * (N - N / 2 * 2) + solve(N / 2, mp));
		res = min(res, A + D * ((N + 1) / 2 * 2 - N) + solve((N + 1) / 2, mp));
		res = min(res, B + D * (N - N / 3 * 3) + solve(N / 3, mp));
		res = min(res, B + D * ((N + 2) / 3 * 3 - N) + solve((N + 2) / 3, mp));
		res = min(res, C + D * (N - N / 5 * 5) + solve(N / 5, mp));
		res = min(res, C + D * ((N + 4) / 5 * 5 - N) + solve((N + 4) / 5, mp));
		mp[N] = res;
	}
	return mp[N];
}

