ll go(ll n) {
    if (n == 0) return 0;
    if (n == 1) return d;

    if (dp.count(n)) return dp[n];

    ll ans = INF;
    if (ans / n > d)
        ans = min(ans, n * d);

    for (auto i: action) {
        ll mul = i.first;
        ll cost = i.second;
        if (n % mul == 0) {
            ans = min(ans, cost + go(n / mul));
        } else {
            ll down = n / mul * mul;
            ans = min(ans, cost + d*(n - down) + go(n / mul)); // or ans = ... + go(down / mul) result is same 
            ll up = down + mul;
            ans = min(ans, cost + d*(up - n) + go(n / mul + 1)); //or ans = ... + go(up / mul) result is same
        }
    }

    dp[n] = ans;
    return ans;
}

