long long rec(long long n) {
    if (n == 0) return 0;
    if (memo.count(n)) return memo[n];
    long long res = n * d;
    if (n % 5 == 0) {
        res = min(res, rec(n / 5) + c);
    } else if (n % 5 == 1) {
        res = min(res, rec(n / 5) + c + d);
    } else if (n % 5 == 2) {
        res = min(res, rec(n / 5) + c + d + d);
    } else if (n % 5 == 3) {
        res = min(res, rec((n / 5) + 1) + c + d + d);
    } else if (n % 5 == 4) {
        res = min(res, rec((n / 5) + 1) + c + d);
    }
    if (n % 3 == 0) {
        res = min(res, rec(n / 3) + b);
    } else if (n % 3 == 1) {
        res = min(res, rec(n / 3) + b + d);
    } else if (n % 3 == 2) {
        res = min(res, rec((n / 3) + 1) + b + d);
    }
    if (n % 2 == 0) {
        res = min(res, rec(n / 2) + a);
    } else if (n % 2 == 1) {
        res = min(res, rec(n / 2) + a + d);
        res = min(res, rec((n / 2) + 1) + a + d);
    }
    return res;
}

