ll cost[3], D;
ll val[3] = {2, 3, 5};
map<ll, ll> mem;

const ll MAX_ANSWER = 2LL * 60 * 1e9 + 5;

bool overflow(long double a, long double b)
{
    return a * b > MAX_ANSWER;
}

ll f(ll n)
{
    if (n == 1)
        return D;
    if (mem.count(n))
        return mem[n];
    ll &ret = mem[n];
    ret = LLONG_MAX;
    if (!overflow(n, D)) // no division
        ret = n * D;

    for (int i = 0; i < 3; ++i)
    {
        ll mod = n%val[i];
        ll to = (n - mod)/val[i];
        ret = min(ret, f(to) + mod * D + cost[i]);

        mod = val[i] - mod;
        to = (n + mod)/val[i];
        ret = min(ret, f(to) + mod * D + cost[i]);
    }
    return ret;
}

