    vector<lint> ret(t);
    for (int z = 0; z < t; ++z) {
        lint n, a, b, c, d;
        cin >> n >> a >> b >> c >> d;
        map<lint, lint> cost;
        cost[n]                  = 0;
        cost[1]                  = inf;
        function<void(lint)> dfs = [&](lint k) {
            if (k == 1)
                return;
            for (lint x = max(1LL, k - 5); x <= min(n + 5, k + 5); ++x) {
                if (x == 1) {
                    if (cost[k] + d * abs(x - k) < cost[x])
                        cost[x] = cost[k] + d * abs(x - k);
                }
                if (x % 2 == 0) {
                    if (cost.count(x / 2) == 0)
                        cost[x / 2] = inf;
                    // cost[k / 2] == d *(n - k / 2);
                    lint mindist = min(cost[k] + a + d * abs(x - k), cost[k] + d * abs(x / 2 - k));
                    if (mindist < cost[x / 2]) {
                        cost[x / 2] = mindist;
                        dfs(x / 2);
                    }
                }
                if (x % 3 == 0) {
                    if (cost.count(x / 3) == 0)
                        cost[x / 3] = inf;
                    // cost[k / 3] == d *(n - k / 3);
                    lint mindist = min(cost[k] + b + d * abs(x - k), cost[k] + d * abs(x / 3 - k));
                    if (mindist < cost[x / 3]) {
                        cost[x / 3] = mindist;
                        dfs(x / 3);
                    }
                }
                if (x % 5 == 0) {
                    if (cost.count(x / 5) == 0)
                        cost[x / 5] = inf;
                    // cost[k / 5] == d *(n - k / 5);
                    lint mindist = min(cost[k] + c + d * abs(x - k), cost[k] + d * abs(x / 5 - k));
                    if (mindist < cost[x / 5]) {
                        cost[x / 5] = mindist;
                        dfs(x / 5);
                    }
                }
            }
        };
        dfs(n);
        ret[z] = cost[1] + d;
    }
    for (auto &r : ret) {
        cout << r << "\n";
    }
    return 0;
}

