        return dp[x] = 0;
    }
    if (x % 2 == 0) {
        chmin(dp[x], calc(x / 2) + A);
    } else {
        chmin(dp[x], calc((x - 1) / 2) + A + D);
        chmin(dp[x], calc((x + 1) / 2) + A + D);
    }
    if (x % 3 == 0) {
        chmin(dp[x], calc(x / 3) + B);
    } else {
        int m = x % 3;
        if (m <= 1) {
            chmin(dp[x], calc(x / 3) + B + D);
        } else {
            chmin(dp[x], calc(x / 3 + 1) + B + D);
        }
    }
    if (x % 5 == 0) {
        chmin(dp[x], calc(x / 5) + C);
    } else {
        int m = x % 5;
        if (m <= 2) {
            chmin(dp[x], calc(x / 5) + C + m * D);
        } else {
            chmin(dp[x], calc(x / 5 + 1) + C + D * (5 - m));
        }
    }
    if (dp[x] < 0) {
        debug(x);
        debug(dp.size());
        exit(-1);
    }
    return dp[x];
}

