vector<int> parms = { 2,3,5 };
vector<long long> cost;



long long act(long long x) {

	long long dist = -1, next = -100, n;

	sets.insert(x);


	while (!sets.empty()) {


		auto itr = max_element(sets.begin(), sets.end());
		n = *itr;



		dist = -1; next = -100;

        // if(dp.count(n) > 0){
        //     sets.erase(n);
        //     continue;
        // }




		if (n == 1) {
			if (dp[n - 1] != 0) {
				dp[n - 1] = min(dp[n - 1], dp[n] + D);
			}
			else {
				dp[n - 1] = dp[n] + D;
			}

			sets.erase(n);
			continue;
		}

		if (n == -1) {
			if (dp[n + 1] != 0) {
				dp[n + 1] = min(dp[n + 1], dp[n] + D);
			}
			else {
				dp[n + 1] = dp[n] + D;
			}

			sets.erase(n);
			continue;
		}



		int par = 1;
		for (int param_index = 0; param_index < parms.size(); param_index++) {
			int par = parms[param_index];

			dist = par - n % par;
			if (dp[(n - dist) / par] != 0) {
				dp[(n - dist) / par] = min(dp[(n - dist) / par], dp[n] + D * dist + cost[param_index]);
			}
			else {
				dp[(n - dist) / par] = min(dp[n] + D * dist + cost[param_index], dp[n] + (n - (n - dist) / par)*D);
			}
			next = (n - dist) / par;
			sets.insert(next);


			dist = n % par;
			if (dp[(n + dist) / par] != 0) {
				dp[(n + dist) / par] = min(dp[(n + dist) / par], dp[n] + dist * D + cost[param_index]);
			}
			else {
				dp[(n + dist) / par] = min(dp[n] + dist * D + cost[param_index], dp[n] + (n- ((n + dist) / par) )*D);
			}
			next = (n + dist) / par;
			sets.insert(next);

		}

        if(dp[n-1] != 0){
            dp[n-1]=min(dp[n-1],dp[n]+D);
        }else{
            dp[n-1]=dp[n]+D;
        }


		sets.erase(n);


	}

	return dp[0];


}



