#define INF 1e18
#define ll long long
ll n, a, b, c, d;
vector<ll> x;
vector<ll> co;
map<pair<ll, ll>, ll> mp;
ll dp[7];

void gen()
{
    dp[1] = d;
    dp[2] = min(2*d, d+a);
    dp[3] = min(3*d, 2*d+a);
    dp[3] = min(dp[3], d+b);
    dp[3] = min(dp[3], 3*d+c);
    dp[4] = min(4*d, d+2*a);
    dp[4] = min(dp[4], 2*d+b);
    dp[4] = min(dp[4], 2*d+c);
}

ll nows(ll x, ll inc)
{
    if(x == 1) return d;
    ll mins = INF;
    if(x%2 == 0) mins = min(mins, nows(x/2, inc)+a);
    if(x%3 == 0) mins = min(mins, nows(x/3, inc)+b);
    if(x%5 == 0) mins = min(mins, nows(x/5, inc)+c);
    mins = min(mins, nows(x-1, inc)+d);
    if(inc > 0) mins = min(mins, nows(x+1, inc-1)+d);
    return mins;
}

ll mul(ll a, ll b)
{
    if(a >= INF/b) return INF;
    return (a*b);
}

ll calc(ll n, ll wh)
{
    if(n <= 6) return dp[n];
    pair<ll, ll> P = make_pair(n, wh);
    if(mp.find(P) != mp.end()) return mp[P];
    ll mins = INF;
    mins = mul(n, d);
    if(n%x[wh] == 0){
        for(int i=0; i<3; i++){
            mins = min(mins, calc(n/x[wh], i)+co[wh]);
            if(n/x[wh] + 1 < n) mins = min(mins, calc(n/x[wh] + 1, i) + co[wh] + dp[x[wh]]);
        }
    }
    else {
        ll div = x[wh];
        ll prev = (n/div) * div;
        ll nxt = ((n+div-1)/div)*div;
        ll cost1 = calc(prev, wh) + dp[n-prev];
        ll cost2 = calc(nxt, wh) + dp[nxt-n];
        mins = min(cost1, cost2);
    }
    return mp[P] = mins;
}

