        for(int i=1; i<=6; i++) dp[i] = nows(i, 4);
        x = {2, 3, 5};
        co = {a, b, c};
        ll ans = INF;
        for(int i=0; i<3; i++) ans = min(ans, calc(n, i));
        cout << ans << endl;
        mp.clear();
    }
}

