map<ll,ll> mp;

ll Solve(ll x){
    if(!x)
        return 0;
    if(x == 1)
        return D;
    if(mp.find(x) != mp.end())
        return mp[x];
    ll res = INF;
    if(x < res / D)
        res = x * D;
    res = min(res,x % 2 * D + Solve(x / 2) + A);
    res = min(res,(2 - x % 2) * D + Solve((x + 1) / 2) + A);
    res = min(res,x % 3 * D + Solve(x / 3) + B);
    res = min(res,(3 - x % 3) * D + Solve((x + 2) / 3) + B);
    res = min(res,x % 5 * D + Solve(x / 5) + C);
    res = min(res,(5 - x % 5) * D + Solve((x + 4) / 5) + C);
    mp[x] = res;
    return res;
}

