    auto it = vis.find(x);
    if (it != vis.end())
      return it->second;
    else
      return infLL;
  };
  auto emp = [&](ll x, ll y) {
    if (val(y) > x) {
      vis[y] = x;
      Q.emplace(x, y);
    }
  };
  emp(0, N);

  __int128_t ans = infLL;

  while (1) {
    auto cur = Q.top();
    Q.pop();
    ll x = cur.first;
    ll y = cur.second;
    amin(ans, (__int128_t)x + (__int128_t)y * D);
    if (y == 1) {
