ll rec(ll n, ll d, vector<ll> cost){
    if(n == 0){
        return 0;
    }
    if(n == 1){
        return d;
    }

    if(memo.find(n) != memo.end()){
        return memo[n];
    }

    ll res = INF;

    for(int i = 0; i < 3; i++){
        if(n % di[i] == 0){
            res = min(res, rec(n / di[i], d, cost)) + cost[i];
        } else {
            res = min(res, rec((n - (n % di[i])) / di[i], d, cost) + d * (n % di[i]) + cost[i]);
            res = min(res, rec((n + (di[i] - (n % di[i]))) / di[i], d, cost) + d * (di[i] - (n % di[i])) + cost[i]);
        }
    }
    if(n <= INF / d) res = min(res, n * d);

    return memo[n] = res;
