long long solveit(long long goal)
{
	if(goal==0)
		return 0;
	if(goal==1)
		return d;
	if(qmap.count(goal))
	{
		return qmap[goal];
	}
	long long best=INF;
	if(d<best/goal)
	{
		best=min(best,d*goal);
	}
	for(int i=0;i<3;i++)
	{
		long long mul=vector<long long > {2,3,5}[i];
		long long cost=vector<long long > {a,b,c}[i];
		if(goal%mul==0)
		{
			best=min( best , cost + solveit(goal / mul) );
		}		
		else
		{
			long long down= (goal / mul) * mul;
			best=min(best , cost + (goal - down) * d + solveit (goal / mul));
			long long up = down + mul;
			best=min(best, cost + (up - goal) * d + solveit(goal / mul + 1));
		}
	}
	qmap[goal]=best;
	return best;
}
