	Min = min(Min, solve((u-u%2)/2) + A + u%2*D);
	if(u%3 <= 1) Min = min(Min, solve((u-u%3)/3) + B + u%3*D);
	else Min = min(Min, solve((u+3-u%3)/3) + B + (3-u%3)*D);
	if(u%5 <= 3)Min = min(Min, solve((u-u%5)/5) + C + u%5*D);
	if(u%5 >= 3) Min = min(Min, solve((u+5-u%5)/5) + C + (5-u%5)*D);
	if(u%2 != 0) Min = min(Min, solve((u+2-u%2)/2) + A + (2-u%2)*D);
	dp[u] = Min;
	return Min;
}
