		if (nex == 0) {
			chmin(res, cur);
			continue;
		}
		if (nex % 2 == 0) {
			ll nexv = f(nex / 2, a, b, c, d);
			// if (2. * a / d + 1000 > n) chmin(res, nex / 2 * d + cur + nexv);
			if ((long double)nex / 2 * d + cur + nexv < longINF) chmin(res, nex / 2 * d + cur + nexv);
			if ((long double)a + cur + nexv < longINF) chmin(res, a + cur + nexv);
		}
		if (nex % 3 == 0) {
			ll nexv = f(nex / 3, a, b, c, d);
			// if (3. * b / 2. / d + 1000 > n) chmin(res, nex / 3 * 2 * d + cur + nexv);
			if ((long double)nex / 3 * 2 * d + cur + nexv < longINF) chmin(res, nex / 3 * 2 * d + cur + nexv);
			if ((long double)b + cur + nexv < longINF) chmin(res, b + cur + nexv);
		}
		if (nex % 5 == 0) {
			ll nexv = f(nex / 5, a, b, c, d);
			// if (5. * c / 4. / d + 1000 > n) chmin(res, nex / 5 * 4 * d + cur + nexv);
			if ((long double)nex / 5 * 4 * d + cur + nexv < longINF) chmin(res, nex / 5 * 4 * d + cur + nexv);
			if ((long double)c + cur + nexv < longINF) chmin(res, c + cur + nexv);
		}
	}
	return mm[n] = res;
}

