int answer(int number, vector<int> &actions, bool plused) {
  int a = actions.at(0);
  int b = actions.at(1);
  int c = actions.at(2);
  int d = actions.at(3);

  vector<int> coins;
  if(number == 1){
    return d;
  }

  if(number%2==0){
    coins.push_back(a + answer(number/2,actions,false));
  } else{
    int re = 2- number % 2;
    int target = number + re;
    coins.push_back( d * re + a + answer(target/2,actions,true));
  }

  if(number%3==0){
    coins.push_back(b + answer(number/3,actions,false));
  } else {
    int re = 3 - number % 3;
    int target = number + re;
    coins.push_back( d * re + b + answer(target/3,actions,true));
  }

  if(number%5==0){
    coins.push_back(c + answer(number/5,actions,false));
  }else{
    int re = 5 - number % 5 ;
    int target = number + re;
    coins.push_back( d * re + c + answer(target/5,actions,true));
  }

  if(number%30 != 0){
    coins.push_back( d + answer(number-1,actions,false));
  }

  sort(coins.begin(), coins.end());

  return coins[0];
}

