	ll z = x / 3;
	ans(z);
	ans(z + 1);

	ll w = x / 5;
	ans(w);
	ans(w + 1);

	ll ret = INF;
	if (x <= INF / A) { ret = A * x; }
	ret = min(ret, mp[y] + B + A*(x%2));
	if(x>2)ret = min(ret, mp[y + 1] + B + A*(2-x%2));
	ret = min(ret, mp[z] + C + A * (x % 3));
	ret = min(ret, mp[z + 1] + C + A*(3-x%3));
	ret = min(ret, mp[w] + D + A * (x % 5));
	ret = min(ret, mp[w + 1] + D + A * (5 - x % 5));

	mp[x] = ret;
}



