long long ab(long long x){return x<0ll?-x:x;}
long long solve(long long n){
	if(n<0ll)
		return infCost;
	if(n<=1ll)
		return n*d;
	if(memo.count(n))
		return memo[n];
	long long ret=infCost;
	if(log10d+log10(n)<12.0){
		ret=min(ret, d*n);
	}
	for(int i = n%2;i > -2;i -= 2){
		ret=min(ret, solve((n-i)/2)+d*ab(i)+a);
	}
	for(int i = n%3;i > -3;i -= 3){
		ret=min(ret, solve((n-i)/3)+d*ab(i)+b);
	}
	for(int i = n%5;i > -5;i -= 5){
		ret=min(ret, solve((n-i)/5)+d*ab(i)+c);
	}
	// printf("%lld %lld\n", n, ret);
	return memo[n]=ret;
}
