    }
    if (n % 3 == 0) {
        dp[n] = min(dp[n], dfs(n / 3) + b); 
    }
    else {
        dp[n] = min(dp[n], dfs(n / 3) + b + d * (n % 3)); 
        dp[n] = min(dp[n], dfs(n / 3 + 1) + b + d * (3 - n % 3)); 
