long long mul(long long x, long long y) {
    if (!x || !y) {
        return 0;
    }
    if (x > inf / y) {
        return inf;
    }
    return x * y;
}

void upd(int i, int x, long long val) {
    if (dp[i][x] == -1) {
        dp[i][x] = val;
    } else {
        dp[i][x] = min(dp[i][x], val);
    }
}

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    for (int i = 0; i < 3; ++i) {
        pw[i].push_back(1);
        while (mul(val[i], pw[i].back()) < inf) {
            pw[i].push_back(pw[i].back() * val[i]);
        }
        //cout << pw[i].size() << endl;
    }
    vector<int> ids[3];
    vector<long long> vals;
    memset(num, -1, sizeof(num));
    for (int i = 0; i < pw[0].size(); ++i) {
        for (int j = 0; j < pw[1].size(); ++j) {
            for (int k = 0; k < pw[2].size(); ++k) {
                long long val = mul(pw[0][i], mul(pw[1][j], pw[2][k]));
                if (val < inf) {
                    num[i][j][k] = ids[0].size();
                    ids[0].push_back(i);
                    ids[1].push_back(j);
                    ids[2].push_back(k);
                    vals.push_back(val);
                }
            }
        }
