        long long ans = inf;
        for (int i = 0; i < ids[0].size(); ++i) {
            for (int x = 0; x + 1 < max_x; ++x) {
                if (dp[i][x] == -1) {
                    continue;
                }
                upd(i, x + 1, dp[i][x] + d);
            }
            for (int x = max_x - 1; x; --x) {
                if (dp[i][x] == -1) {
                    continue;
                }
                upd(i, x - 1, dp[i][x] + d);
            }
            for (int x = 0; x < max_x; ++x) {
                if (dp[i][x] == -1) {
                    continue;
                }
                long long cur = n / vals[i] + x - shift;
                if (cur < 0) {
