                    if (to == -1) {
                        continue;
                    }
                    long long tox = cur / val[j] + shift - n / vals[to];
                    if (0 <= tox && tox < max_x) {
                        upd(to, tox, dp[i][x] + a[j]);
                    }
                }
            }
        }
        cout << ans << endl;
    }
    return 0;
}

