map<ll, ll> mp;
inline ll changeAns(ll x){
    if(mp[x]) return mp[x];
    if(x==0) return 0;
    mp[x] = 1e18;

    ll ret = 1e18;
    if(1e18 / d >= x) ret = d * x;

    if(x%2==0) ret = min(ret, changeAns(x/2) + a);
    else{
        ll tmp1 = (x-1)/2;
        ll tmp2 = tmp1+1;
        ret = min(ret, changeAns(tmp1) + d + (tmp1 ? a : 0));
        ret = min(ret, changeAns(tmp2) + d + a);
    }

    if(x%3==0) ret = min(ret, changeAns(x/3) + b);
    else{
        ll tmp1 = x/3;
        ll tmp2 = tmp1+1;
        ret = min(ret, changeAns(tmp1) + d * (x - 3*tmp1) + (tmp1 ? b : 0));
        ret = min(ret, changeAns(tmp2) + d * (3*tmp2 - x) + b);
    }

    if(x%5==0) ret = min(ret, changeAns(x/5) + c);
    else{
        ll tmp1 = x/5;
        ll tmp2 = tmp1+1;
        ret = min(ret, changeAns(tmp1) + d * (x - 5*tmp1) + (tmp1 ? c : 0));
        ret = min(ret, changeAns(tmp2) + d * (5*tmp2 - x) + c);
    }

    return mp[x] = ret;
}

