{
	if(mp.count(x)) return mp[x];
	if(vis.count(x)) return 1e18;
	vis[x]=1;
	if(!x) return 0;
	ll ans=(1.0*x*D<=1e18?x*D:1e18);
	//printf("x=%lld,ans=%lld\n",x,ans);
	for(ll i=x;;i--)
		if(i%2==0)
		{
			ans=min(ans,(x-i)*D+A+getans(i/2));
			break;
		}
	for(ll i=x;;i++)
		if(i%2==0)
		{
			ans=min(ans,(i-x)*D+A+getans(i/2));
			break;
		}
	for(ll i=x;;i--)
		if(i%3==0)
		{
			ans=min(ans,(x-i)*D+B+getans(i/3));
			break;
		}
	for(ll i=x;;i++)
		if(i%3==0)
		{
			ans=min(ans,(i-x)*D+B+getans(i/3));
			break;
		}
	for(ll i=x;;i--)
		if(i%5==0)
		{
			ans=min(ans,(x-i)*D+C+getans(i/5));
			break;
		}
	for(ll i=x;;i++)
		if(i%5==0)
		{
			ans=min(ans,(i-x)*D+C+getans(i/5));
			break;
		}
	vis.erase(x);
	return mp[x]=ans;
}
int main()
{
	scanf("%d",&t);
	while(t--)
	{
		mp.clear();
		scanf("%lld%lld%lld%lld%lld",&n,&A,&B,&C,&D);
		printf("%lld\n",getans(n));
	}
	return 0;
}

