LL sub() {
	LL N, A, B, C, D;
	cin >> N >> A >> B >> C >> D;

	map<LL, LL> dist;
	PriorityQ<PP> Q;
	Q.push(PP(0, N));
	while (!Q.empty()) {
		PP p = Q.top(); Q.pop();
		LL d = p.first;
		LL from = p.second;
		if (dist.count(from)) continue;
		if (from == 0) return d;
		dist[from] = d;

		if (double(from) * D <= 2e18) Q.push(PP(d + from * D, 0));
		Q.push(PP(d + A + D * (from % 2), from / 2));
		Q.push(PP(d + A + D * (2 - from % 2), from / 2 + 1));
		Q.push(PP(d + B + D * (from % 3), from / 3));
		Q.push(PP(d + B + D * (3 - from % 3), from / 3 + 1));
		Q.push(PP(d + C + D * (from % 5), from / 5));
		Q.push(PP(d + C + D * (5 - from % 5), from / 5 + 1));
	}
	return INFLL;
}

