	if((x+2-1)/2<x&&x-(x+2-1)/2<=LLONG_MAX/d)res=min(res,dfs((x+2-1)/2)+(x-(x+2-1)/2)*d);
	if((x+3-1)/3<x&&x-(x+3-1)/3<=LLONG_MAX/d)res=min(res,dfs((x+3-1)/3)+(x-(x+3-1)/3)*d);
	if((x+5-1)/5<x&&x-(x+5-1)/5<=LLONG_MAX/d)res=min(res,dfs((x+5-1)/5)+(x-(x+5-1)/5)*d);
	//-----------------------------------------------------------------------------------
	if(x/2<x)res=min(res,dfs(x/2)+x%2*d+a);
	if(x/3<x)res=min(res,dfs(x/3)+x%3*d+b);
	if(x/5<x)res=min(res,dfs(x/5)+x%5*d+c);
	if(x/2<x&&x-x/2<=LLONG_MAX/d)res=min(res,dfs(x/2)+(x-x/2)*d);
	if(x/3<x&&x-x/3<=LLONG_MAX/d)res=min(res,dfs(x/3)+(x-x/3)*d);
	if(x/5<x&&x-x/5<=LLONG_MAX/d)res=min(res,dfs(x/5)+(x-x/5)*d);
	//-----------------------------------------------------------------------------------
	if((x+2-1)/2+1<x)res=min(res,dfs((x+2-1)/2+1)+(2-x%2)%2*d+2*d+a);
	if((x+3-1)/3+1<x)res=min(res,dfs((x+3-1)/3+1)+(3-x%3)%3*d+3*d+b);
	if((x+5-1)/5+1<x)res=min(res,dfs((x+5-1)/5+1)+(5-x%5)%5*d+5*d+c);
	if((x+2-1)/2+1<x&&x-(x+2-1)/2-1<=LLONG_MAX/d)res=min(res,dfs((x+2-1)/2+1)+(x-(x+2-1)/2-1)*d);
	if((x+3-1)/3+1<x&&x-(x+3-1)/3-1<=LLONG_MAX/d)res=min(res,dfs((x+3-1)/3+1)+(x-(x+3-1)/3-1)*d);
	if((x+5-1)/5+1<x&&x-(x+5-1)/5-1<=LLONG_MAX/d)res=min(res,dfs((x+5-1)/5+1)+(x-(x+5-1)/5-1)*d);
	//-----------------------------------------------------------------------------------
	if(0<=x/2-1&&x/2-1<x)res=min(res,dfs(x/2-1)+x%2*d+2*d+a);
	if(0<=x/3-1&&x/3-1<x)res=min(res,dfs(x/3-1)+x%3*d+3*d+b);
	if(0<=x/5-1&&x/5-1<x)res=min(res,dfs(x/5-1)+x%5*d+5*d+c);
	if(0<=x/2-1&&x/2-1<x&&x-x/2+1<=LLONG_MAX/d)res=min(res,dfs(x/2-1)+(x-x/2+1)*d);
	if(0<=x/3-1&&x/3-1<x&&x-x/3+1<=LLONG_MAX/d)res=min(res,dfs(x/3-1)+(x-x/3+1)*d);
	if(0<=x/5-1&&x/5-1<x&&x-x/5+1<=LLONG_MAX/d)res=min(res,dfs(x/5-1)+(x-x/5+1)*d);
	return res;
}
