constexpr ll INF = 1000000000000000000;

map<ll, ll> memo;

ll bases[3];
ll baseCost[3];
ll d;

ll stupidUpperBound(ll x) {
	if (x <= 1000000000) return x * d;
	if (x == 0) return 0;
	else return baseCost[0] + stupidUpperBound(x/2) + (x % 2 == 0 ? 0 : d);
}

ll getAns(ll x) {
	if (x < 0) return INF;
	if (x == 0) return 0;
	if (memo.count(x) > 0) {
		return memo[x];
	}
//	printf("CALL %lld\n", x);
	memo[x] = -1;
	ll ans = stupidUpperBound(x);
	for (int k = 0; k < 3; ++k) {
		for (int delta = -bases[k] + 1; delta <= bases[k] - 1; ++delta) {
			ll afterMul = x + delta;
//			printf("attempting jump base %lld delta %lld\n", bases[k], afterMul);
			if (afterMul >= 0 && afterMul % bases[k] == 0) {
				if (memo.count(afterMul / bases[k]) > 0 && memo[afterMul/bases[k]] == -1) continue;
//				printf("recursing to %lld from %lld->%lld\n", afterMul / bases[k], x, afterMul);
				ans = min(ans, getAns(afterMul / bases[k]) + abs(delta) * d + baseCost[k]);
			}
		}
	}
//	printf("GA %lld %lld\n", x, ans);
	return memo[x] = ans;
}


