unordered_map<ull,ull> dp;
ull dfs(ull x,ull a,ull b,ull c,ull d){
    if(x==0) return 0;
    if(x==1) return d;
    if(x==2) return min(2*d,a+d);
    if(dp[x]) return dp[x];
    ull ret = 1e18;
    ull r3 = x%3;
    ull r5 = x%5;
    ret = min(ret,d*x);
    if(x%2==0) ret = min(ret,a+dfs(x/2,a,b,c,d));
    else {
        ret = min(ret,a+d+dfs((x+1)/2,a,b,c,d));
        ret = min(ret,a+d+dfs((x-1)/2,a,b,c,d));
        }
    if(x%3==0) ret = min(ret,b+dfs(x/3,a,b,c,d));
    else{
        ret = min(ret,b+d*(3-r3)+dfs((x+3-r3)/3,a,b,c,d));
        ret = min(ret,b+d*r3+dfs((x-r3)/3,a,b,c,d));
    }
    if(x%5==0) ret = min(ret,c+dfs(x/5,a,b,c,d));
    else{
        ret = min(ret,c+d*(5-r5)+dfs((x+5-r5)/5,a,b,c,d));
        ret = min(ret,c+d*r5+dfs((x-r5)/5,a,b,c,d));
    }
    return dp[x] = ret;
}

