i64 calc(i64 N, i64 A, i64 B, i64 C, i64 D) {

  // A:x2 B:x3 C:x5 D:+-1

  unordered_map<i64, i64> dp;

  auto dfs = [&](auto dfs, i64 n, i64 cost)->void {

    auto it = dp.find(n);
    if (it != dp.end() && it->second <= cost) return;

    dp[n] = cost;
    if (n == 0) return;

    i64 t;

    if (n % 5 == 0) {
      dfs(dfs, n / 5, cost + C);
    }
    else {
      t = n / 5;
      dfs(dfs, t, cost + C + (n - t * 5) * D);
      t = n / 5 + 1;
      dfs(dfs, t, cost + C + (t * 5 - n) * D);
    }
    if (n % 3 == 0) {
      dfs(dfs, n / 3, cost + B);
    }
    else {
      t = n / 3;
      dfs(dfs, t, cost + B + (n - t * 3) * D);
      t = n / 3 + 1;
      dfs(dfs, t, cost + B + (t * 3 - n) * D);
    }
    if (n % 2 == 0) {
      dfs(dfs, n / 2, cost + A);
    }
    else {
      t = n / 2;
      dfs(dfs, t, cost + A + (n - t * 2) * D);
      t = n / 2 + 1;
      dfs(dfs, t, cost + A + (t * 2 - n) * D);
    }

    if (n < (INT64_MAX - cost) / D) {
      dfs(dfs, 0, cost + n * D);
    }
  };
  dfs(dfs, N, 0);

  return dp[0];
}

