ll f(ll n, ll a, ll b, ll c, ll d) {
	//cout << n << endl;
	if (n==0LL) return 0LL;
	if (n==1LL) return d;
	if (n==2LL) return min({2LL*d,a+d,b+2LL*d,c+4LL*d}); 
	ll up2,dn2,up3,dn3,up5,dn5;
	//up2 = 0, dn2 = 0, up3 = 0, dn3 = 0, up5 = 0, dn5 = 0;
	ll r2 = n%2LL;
	ll r3 = n%3LL;
	ll r5 = n%5LL;
	up2 = f((n-r2)/2LL+1LL,a,b,c,d) + a + (2LL-r2)*d;
	dn2 = f((n-r2)/2LL,a,b,c,d)   + a + r2*d;
	up3 = f((n-r3)/3LL+1LL,a,b,c,d) + b + (3LL-r3)*d;
	dn3 = f((n-r3)/3LL,a,b,c,d)   + b + r3*d;
	up5 = f((n-r5)/5LL+1LL,a,b,c,d) + c + (5LL-r5)*d;
	dn5 = f((n-r5)/5LL,a,b,c,d)   + c + r5*d;
	return min({d*n, up2, dn2, up3, dn3, up5, dn5});
}

