ll f(ll n) {
	if (memo.count(n)) return memo[n];
	ll r = (double)D * n >= (1LL<<62) ? (1LL<<62) : D*n;
	if (n >= 2) {
		r = min(r, f(n / 2) + A + (n % 2) * D);
		if (n/2+1 < n) r = min(r, f(n/2+1) + A + (2-n%2) * D);
	}
	if (n >= 3) {
		r = min(r, f(n/3) + B + (n%3) * D);
