void operate_coin(int& num, int(&c)[4], int p){
    if(p == 0){
        num = num*2;
        c[0]++;
    }
    else if(p == 1){
        num = num*3;
        c[1]++;
    }
    else if(p == 2){
        num = num*5;
        c[2]++;
    }
    else if(p == 3){
        num = num + 1;
        c[3]++;
    }
    else if(p == 4){
        num = num - 1;
        c[3]++;
    }
}

