void solve(){
	ll a,b,c,d,n ;
	cin >> n >> a >> b >> c >> d ;
	map<ll,ll> m ;
	priority_queue<pll> pq ;
	pq.emplace(0,n) ;
	while(!pq.empty()){
		ll cur = pq.top().second ;
		ll cost = -pq.top().first ;
		pq.pop() ;
		if(m.count(cur)) continue ;
		m[cur] = cost ;
		if(cur==0){
			cout << cost << endl ;
			return ;
		}
		if(cur%2==0){
			if(!m.count(cur/2)){
				if(a/d>=cur/2) pq.emplace(-cost-cur/2*d,cur/2) ;
				else pq.emplace(-cost-a,cur/2) ;
			}
//			if(!m.count(cur+2)) pq.emplace(-cost-2*d,cur+2) ;
		}else{
			if(!m.count(cur+1)) pq.emplace(-cost-d,cur+1) ;
			if(!m.count(cur-1)) pq.emplace(-cost-d,cur-1) ;
		}
		if(cur%3==0){
			if(!m.count(cur/3)){
				if(b/d>=cur/3*2) pq.emplace(-cost-cur/3*2*d,cur/3) ;
				else pq.emplace(-cost-b,cur/3) ;
			}
//			if(!m.count(cur+3)) pq.emplace(-cost-3*d,cur+3) ;
		}else{
			if(!m.count(cur+3-cur%3)) pq.emplace(-cost-(3-cur%3)*d,cur+3-cur%3) ;
			if(!m.count(cur-cur%3)) pq.emplace(-cost-cur%3*d,cur-cur%3) ;
		}
		if(cur%5==0){
			if(!m.count(cur/5)){
				if(c/d>=cur/5*4) pq.emplace(-cost-cur/5*4*d,cur/5) ;
				else pq.emplace(-cost-c,cur/5) ;
			}
//			if(!m.count(cur+5)) pq.emplace(-cost-5*d,cur+5) ;
		}else{
			if(!m.count(cur+5-cur%5)) pq.emplace(-cost-(5-cur%5)*d,cur+5-cur%5) ;
			if(!m.count(cur-cur%5)) pq.emplace(-cost-cur%5*d,cur-cur%5) ;
		}
	}
}

