#define PII pair <int, int>

const int N = 1e6 + 7;
const int MX = 1e9 + 7;
const LL INF = 1LL * MX * MX;

LL a, b, c, d;
map <LL, LL> M;

LL go(LL n){
	if(n <= 1)
		return n * d;

	if(n == 2)
		return min(d * 2, d + a);

	if(M.count(n))
		return M[n];

	LL ret = INF;
	if(INF / d >= n)
		ret = d * n;

	ret = min(ret, (n % 2) * d + a + go(n / 2));
	ret = min(ret, (2 - n % 2) * d + a + go(n / 2 + 1));

	ret = min(ret, (n % 3) * d + b + go(n / 3));
	ret = min(ret, (3 - n % 3) * d + b + go(n / 3 + 1));

	ret = min(ret, (n % 5) * d + c + go(n / 5));
	ret = min(ret, (5 - n % 5) * d + c + go(n / 5 + 1));
//	printf("%lld :: %lld\n", n, ret);
	return M[n] = ret;
}

