void solveCase() {
    long long n, d;
    vector<long long> costs(3);
    vector<int> muls = {2, 3, 5};
    cin >> n;
    for (int i = 0; i < muls.size(); i++) {
        cin >> costs[i];
    }
    cin >> d;
    map<long long, long long> mem;
    function<long long(long long)> dp;
    long long MX = 2e18;
    dp = [&] (long long v) -> long long {
        if (v <= 0) {
            return 0;
        }
        if (mem.count(v) == 0) {
            long long ans = v > 1e9 ? MX : v*d;
            for (int st = -4; st <= 4; st++) {
                long long nxt = st + v;
                if (nxt < 0) {
                    continue;
                }
                for (int i = 0; i < muls.size(); i++) {
                    int mul = muls[i];
                    long long cur = d*abs(st) + costs[i];
                    if (nxt % mul == 0 && nxt/mul < v) {
                        ans = min(ans, cur + dp(nxt/mul));
                    }
                }
            }
            mem[v] = ans;
        }
        return mem[v];
    };
    auto res = dp(n);
    cout << res << endl;
}

