#define N_TIMES(i, n)     for ( uint64_t i = 0;     i <  n; ++i )
#define N_TIMES_REV(i, n) for (  int64_t i = n - 1; i >= 0; --i )

using namespace std;

map<uint64_t, uint64_t> cache;

inline uint64_t int_floor(uint64_t x, uint64_t y) { return x / y; }
inline uint64_t int_ceil(uint64_t x, uint64_t y) {
  return int_floor(x, y) + (x % y == 0 ? 0 : 1);
}

uint64_t search(uint64_t N, uint64_t A, uint64_t B, uint64_t C, uint64_t D)
{
  if (cache.find(N) != cache.end()) {
    return cache[N];
  }

  if (N == 0) { return 0; }
  if (N == 1) { return D; }

  auto cost = [&](uint64_t k) {
    switch(k) {
    case 2: return A;
    case 3: return B;
    case 5: return C;
    default: return static_cast<uint64_t>(-1);
    }
  };

  cache[N] = 1e+19;
  if (N < cache[N] / D) {
    cache[N] = N * D;
  }

  for (uint64_t k : {2, 3, 5}) {
    uint64_t P = int_floor(N, k), Q = int_ceil(N, k);
    uint64_t s = N - (P * k), t = (Q * k) - N;

    cache[N] = min(cache[N], search(P, A, B, C, D) + cost(k) + s * D);
    cache[N] = min(cache[N], search(Q, A, B, C, D) + cost(k) + t * D);
  }

  return cache[N];
}

int main()
{
  uint64_t T;
  cin >> T;

  N_TIMES(t, T) {
    uint64_t N, A, B, C, D;
    cin >> N >> A >> B >> C >> D;

    cache = map<uint64_t, uint64_t>();
    cout << search(N, A, B, C, D) << endl;
  }

  return 0;
}

