using namespace std;
const int maxn=200000;
const long long inf=1e18;
long long n,ans,cur,dp[222222];
priority_queue<pair<long long,int> > pq;
int t,a,b,c,d;
map<pair<long long,int>,long long> mp;
long long get(long long n,int num)
{
	if (n<=maxn) return dp[n];
	if (mp.find(make_pair(n,num))!=mp.end()) return mp[make_pair(n,num)];
	long long res=1e18;
	if (n%2==0) res=min(res,get(n/2,0)+a);
	if (n%3==0) res=min(res,get(n/3,0)+b);
	if (n%5==0) res=min(res,get(n/5,0)+c);
	if (!num) 
	{
		for (int i=-8;i<=3;i++)
		{
			res=min(res,get(n+i,1)+1ll*abs(i)*d);
		}
	}
	if (n<inf/d) res=min(res,1ll*n*d);
	return mp[make_pair(n,num)]=res;
}
int main()
{
	scanf("%d",&t);
	while(t--)
	{
		scanf("%lld%d%d%d%d",&n,&a,&b,&c,&d);
		ans=1e18;dp[0]=0;pq.push(make_pair(0,0));
		for (int i=1;i<=maxn;i++) dp[i]=1e18;
		mp.clear();
		while(!pq.empty())
		{
			int x=pq.top().second;long long y=-pq.top().first;
			pq.pop();
			if (dp[x]!=y) continue;
			if (x>=1 && dp[x-1]>dp[x]+d)
			{
				dp[x-1]=dp[x]+d;
				pq.push(make_pair(-dp[x-1],x-1));
			}
			if (x<maxn && dp[x+1]>dp[x]+d)
			{
				dp[x+1]=dp[x]+d;
				pq.push(make_pair(-dp[x+1],x+1));
			}
			if (2*x<=maxn && dp[2*x]>dp[x]+a)
			{
				dp[2*x]=dp[x]+a;
				pq.push(make_pair(-dp[2*x],2*x));
			}
			if (3*x<=maxn && dp[3*x]>dp[x]+b)
			{
				dp[3*x]=dp[x]+b;
				pq.push(make_pair(-dp[3*x],3*x));
			}
			if (5*x<=maxn && dp[5*x]>dp[x]+c)
			{
				dp[5*x]=dp[x]+c;
				pq.push(make_pair(-dp[5*x],5*x));
			}
		}
		printf("%lld\n",get(n,0));
	}
	return Accepted;
