void solve(){
	ll sum = 1e18,n,d;
	ll w[10];int a[10],r[10],lim[10];
	scanf("%lld%lld%lld%lld%lld",&n,&w[1],&w[2],&w[3],&d);
	a[1]=2;a[2]=3;a[3]=5;
	r[1]=1;r[2]=2;r[3]=3;
	lim[1]=64;lim[2]=40;lim[3]=30;
	do {

		for(register int i=0;i<=lim[r[1]];++i)
		for(register int j=0;j<=lim[r[2]];++j)
		for(register int k=0;k<=lim[r[3]];++k){
			ll N = n;ll ans = 0;
			#define debug (i == 1 && j == 2 && k == 0 && r[1] == 2 && r[2] == 1) 
		//	if (debug) {printf("%lld %lld\n",N,ans);}
			for(register int l=1;l<=i;++l){
				ll a1 = N%a[r[1]], a2 = a[r[1]] - N%a[r[1]]; 
				if (a1<=a2) { N = N / a[r[1]]; ans += w[r[1]] + a1 * d;}
				else { N = N / a[r[1]] + 1; ans += w[r[1]] + a2 * d; }
				if(N==0)break;
			//	if (sum < ans) break;
				//if (debug) printf("%lld %lld\n",N,ans);
			}
			for(register int l=1;l<=j;++l){
				ll a1 = N%a[r[2]], a2 = a[r[2]] - N%a[r[2]]; 
				if (a1<=a2) { N = N / a[r[2]]; ans += w[r[2]] + a1 * d;}
				else { N = N / a[r[2]] + 1; ans += w[r[2]] + a2 * d; }
				if(N==0)break;
			//	if (sum < ans) break;
			//	if (debug) printf("%lld %lld\n",N,ans);
			}
			for(register int l=1;l<=k;++l){
				ll a1 = N%a[r[3]], a2 = a[r[3]] - N%a[r[3]]; 
				if (a1<=a2) { N = N / a[r[3]]; ans += w[r[3]] + a1 * d;}
				else { N = N / a[r[3]] + 1; ans += w[r[3]] + a2 * d; }
				if(N==0)break;
			//	if (sum < ans) break;
			//	if (debug) printf("%lld %lld\n",N,ans);
			}
			if (N > 1e9) break;
			ans+=N*d;
			sum=std::min(sum,ans);
		}
	}while(std::next_permutation(r+1,r+3+1));
	printf("%lld\n",sum);
}


int main(){
	int t;scanf("%d",&t);while(t--)solve();
	return 0;
}

