#include <iostream>
#include <queue>
#include <vector>
#include <unordered_map>

using namespace std;
typedef long long ll;
typedef pair<ll, ll> pll;

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	int T;
	cin >> T;
	while(T --> 0) {
		ll N, A, B, C, D;
		cin >> N >> A >> B >> C >> D;
		priority_queue<pll> q;
		unordered_map<ll, ll> ds;
		q.emplace(0, N);
		ds[N] = 0;
		ds[0] = N <= INT64_MAX/D ? D*N : INT64_MAX;
		while(!q.empty()) {
			ll n = q.top().second;
			ll d = - q.top().first;
			q.pop();
			if(ds[n] < d) continue;
			if(d >= ds[0]) break;
			if(n <= (INT64_MAX-d) / D) ds[0] = min(ds[0], d+n*D);
			vector<ll> d2s = { d+A+D*(n%2), d+B+D*(n%3), d+C+D*(n%5) };
			vector<ll> n2s = { n/2, n/3, n/5 };
			for(int i = 0; i < 3; ++i) {
				ll n2 = n2s[i], d2 = d2s[i];
				if(!ds.count(n2) || d2 < ds[n2]) {
					ds[n2] = d2;
					q.emplace(-d2, n2);
				}
			}
		}
		cout << ds[0] << "\n";
	}

	return 0;
}

