    map<i64, i64> memo;
    auto dfs = [&](auto dfs, i64 x) -> i64 {
      if (memo.count(x)) {
        return memo[x];
      }
      if (x == 0) return 0;
      if (x == 1) return d;
      auto f = [&](i64 y) -> i64 {
