        amin(ret, f(l / 2) + (x - l) * d + a);
        amin(ret, f(r / 2) + (r - x) * d + a);
      }
      {
        i64 l = x / 3 * 3, r = l + 3;
        amin(ret, f(l / 3) + (x - l) * d + b);
        amin(ret, f(r / 3) + (r - x) * d + b);
      }
      {
        i64 l = x / 5 * 5, r = l + 5;
        amin(ret, f(l / 5) + (x - l) * d + c);
        amin(ret, f(r / 5) + (r - x) * d + c);
      }
      return memo[x] = ret;
    };
