ll N, A, B, C, D;
map<ll, ll>mp;
ll fs(ll n){
    if(n == 0) return 0;
    if(n == 1) return D;
    if(mp.count(n)) return mp[n];
    ll res = 1e18;
    if(n <= 9e9) res = n * D;

    for(int i = -1; i <= 1; i++){
        ll x = n + i;
        if(x < 0 || x % 2 != 0) continue;
        ll y = x / 2;
        res = min(res, abs(i) * D + fs(y) + A);
    }
    for(int i = -2; i <= 2; i++){
        ll x = n + i;
        if(x < 0 || x % 3 != 0) continue;
        ll y = x / 3;
        res = min(res, abs(i) * D + fs(y) + B);
    }
    for(int i = -4; i <= 4; i++){
        ll x = n + i;
        if(x < 0 || x % 5 != 0) continue;
        ll y = x / 5;
        res = min(res, abs(i) * D + fs(y) + C);
    }
    mp[n] = res;
    return mp[n];
}

