pair<ll,ll> addBest(ll n,ll c1,ll c2,ll r1,ll r2,ll a,ll b){
	ll cc1=c1,cc2=c2,cr1=r1,cr2=r2;
	if(c1<c2){
		while(c1<=c2){
			if(abs(n-r1)<abs(n-r2)) return {cr1,cc1};
			r1*=a;
			c1+=c1;
		}
		return {cr2,cc2};
	}else if(c2<=c1){
		while(c2<c1){
			if(abs(n-r2)<abs(n-r1)) return {cr2,cc2};
			r2+=1;
			c2+=c2;
		}
		return {cr1,cc1};
	}else{
		if(abs(n-r1)<abs(n-r2)) return {cr1,cc1};
		else return {cr2,cc2};
	}
}
