typedef pair<long long, long long> pairll;

set<pairll> determined; 

long long coins(long long N, int A, int B, int C, int D){
    if(N == 0)return 0;
    if(N == 1)return D;

    auto itr = determined.lower_bound(pairll(N, 0));
    if((*itr).first == N)return (*itr).second;

    cout << N << endl;

    long long res;
    if(N % 2 == 0){
        res = A + coins(N/2, A, B, C, D);
    }else{
        res = (long long)D + A + coins((N+1)/2, A, B, C, D);
        res = min(res, (long long)D + A + coins((N-1)/2, A, B, C, D));
    }
    switch(N % 3){
        case 0:
            res = min(res, B + coins(N/3, A, B, C, D));
            break;
        case 1:
            res = min(res, (long long)D + B + coins((N-1)/3, A, B, C, D));
            res = min(res, 2LL*D + B + coins((N+2)/3, A, B, C, D));
            break;
        case 2:
            res = min(res, (long long)D + B + coins((N+1)/3, A, B, C, D));
            res = min(res, 2LL*D + B + coins((N-2)/3, A, B, C, D));
            break;
    }
    switch(N % 5){
        case 0:
            res = min(res, (long long)C + coins(N/5, A, B, C, D));
            break;
        case 1:
            res = min(res, (long long)D + C + coins((N-1)/5, A, B, C, D));
            break;
        case 2:
            res = min(res, 2LL*D + C + coins((N-2)/5, A, B, C, D));
            res = min(res, 3LL*D + C + coins((N+3)/5, A, B, C, D));
            break;
        case 3:
            res = min(res, 3LL*D + C + coins((N-3)/5, A, B, C, D));
            res = min(res, 2LL*D + C + coins((N+2)/5, A, B, C, D));
            break;
        case 4:
            res = min(res, (long long)D + C + coins((N+1)/5, A, B, C, D));
            break;
    }
    if(res/D >= N){
        res = N*D;
    }
    determined.insert(pairll(N, res));
    return res;
}

