const int MAX_N = 100010;


int T, N, A, B, C, D;
map<int, int> dp;

int dfs(int cur) {
    if(cur == 0) { return 0; }
    if(cur == 1) { return D; }
    if(dp.count(cur) > 0) { return dp[cur]; }

    int ret = LLINF;
    if(cur < ret / D) { ret = cur * D; }

    // + か - どっちか近い方で割り切れるやつに行く
    auto SubDiv = [&](int div, int add) { 
        int cand1 = cur % div;
        int cand2 = div - (cur % div);
        if(cand1 == 0) {
            chmin(ret, dfs((cur - cand1) / div) + D * cand1 + add);
        }
        else if(cand2 == 0) {
            chmin(ret, dfs((cur + cand2) / div) + D * cand2 + add);
        }
        else {
            chmin(ret, dfs((cur - cand1) / div) + D * cand1 + add);
            chmin(ret, dfs((cur + cand2) / div) + D * cand2 + add);
        }
    };
    SubDiv(2, A);
    SubDiv(3, B);
    SubDiv(5, C);

    dp[cur] = ret;
    return ret;
}

int solve() {
    cin >> N >> A >> B >> C >> D;
    dp.clear();
    int ret = dfs(N);
    return ret;
}

