map<ll, ll> mp;
ll A, B, C, D;
ll dp(ll N) {
    if(mp.count(N)) return mp[N];
    if(N == 0) return mp[N] = 0;

    ll ans;
    if(__builtin_mul_overflow(N, D, &ans)) ans = LONGINF;
    vector<ll> cal = {A, B, C};
    vector<ll> div = {2, 3, 5};

    for(int i=0; i<3; i++) {
        ll c = cal[i], d = div[i];
        // ceil
        {
            ll k = (N+d-1) / d;
            if(k!=N) chmin(ans, dp(k) + (k*d - N)*D + c);
        }
        // floor
        {
            ll k = N / d;
            if(k!=N) chmin(ans, dp(k) + (N - k*d)*D + c);
        }
    }
    return mp[N] = ans;
}

