			if (kk) {
				y = table[ii][jj][kk - 1];
				lc = ansl[i] + c;
				lc += d * (n / r[y].first - n / r[i].first * 5);
				if (ansl[y] > lc)ansl[y] = lc;
				rc = ansr[i] + c;
				rc += d * ((n / r[i].first + 1) * 5 - (n / r[y].first + 1));
				if (ansr[y] > rc)ansr[y] = rc;
			}
