mp<int, int> cache;

int A;
int B;
int C;
int D;

int calc(int n) {
	if (n == 0) {
		return 0;
	}

	int c;
	if (cache.get(n, &c)) {
		return c;
	}

	int a1 = (n / 2) * 2;
	int a2 = (n / 2 + 1) * 2;
	int r = calc(a1 / 2) + A + abs(n - a1) * D;
	if (a2 / 2 != n) {
		chmin(r, calc(a2 / 2) + A + abs(n - a2) * D);
	}

	int b1 = (n / 3) * 3;
	int b2 = (n / 3 + 1) * 3;
	chmin(r, calc(b1 / 3) + B + abs(n - b1) * D);
	if (b2 / 3 != n) {
		chmin(r, calc(b2 / 3) + B + abs(n - b2) * D);
	}

	int c1 = (n / 5) * 5;
	int c2 = (n / 5 + 1) * 5;
	chmin(r, calc(c1 / 5) + C + abs(n - c1) * D);
	if (c2 / 5 != n) {
		chmin(r, calc(c2 / 5) + C + abs(n - c2) * D);
	}

	if (n <= INT64_MAX / D) {
		chmin(r, n * D);
	}

	cache[n] = r;

	return r;
}

void myMain() {
	int T = input;
	REP(i, T) {
		int N = input;
		A = input;
		B = input;
		C = input;
		D = input;
		cache.clear();

		int ans = calc(N);
		output(ans);
	}
}

