constexpr ll LINF = 4e18;

int a, b, c, d;
map<ll, ll> mp;
map<int, int> cost;

ll calc(ll s, ll g, int p) {
    ll k = abs(g * p - s);
    if ((double)k * cost[1] + cost[p] < (double)abs(s - g) * cost[1])
        return k * cost[1] + cost[p];
    return abs(s - g) * cost[1];
}

ll f(ll n) {
    if (mp.find(n) != mp.end())
        return mp[n];
    if (n == 1)
        return cost[1];

    vector<int> v = {2, 3, 5};
    ll ret = LINF;
    for (auto p : v) {
        ll l = n / p, r = rup(n, p);
        if (l == 0)
            ret = min(ret, calc(n, r, p) + f(r));
        else
            ret = min(ret, min(calc(n, l, p) + f(l), calc(n, r, p) + f(r)));
    }
    mp[n] = ret;
    return ret;
}

