        cost.clear();
        cost[1] = d;
        cost[2] = a;
        cost[3] = b;
        cost[5] = c;
        mp.clear();
        f(n);
        ans[i] = mp[n];
    }

    for (int i = 0; i < t; i++)
        cout << ans[i] << endl;

    return 0;
}

