        std::function<int64_t(int64_t)> get_cost = [&](int64_t num) {
            if (num == 0)
                return (int64_t)0;

            auto it = cst.find(num);
            if (it != cst.end())
                return it->second;

            int64_t res = min(__int128_t(TYPEMAX(int64_t) / 2), d * __int128_t(num));

