                    res = min(res, get_cost(num / fact) + cost_this);
                else {
                    res = min(res, get_cost(num / fact) + cost_this + d * (num % fact));

                    if (num / fact + 1 < num)
                        res = min(res, get_cost(num / fact + 1) + cost_this + d * (fact - num % fact));
                }
            }

            return cst[num] = res;
        };

