    ret = min(ret, (3 - n%3)*d + b + solve(n/3 + 1));
    ret = min(ret, (n%5)*d + c + solve(n/5));
    ret = min(ret, (5 - n%5)*d + c + solve(n/5 + 1));

    return memo[n] = ret;
}

