map<int, int> mp;
int dp(int n) {
    if(n == 0) return 0;
    if(n == 1) return d;
    if(mp[n] != 0) return mp[n];
    int res = INF;
    if(n < res / d) res = n * d;
    int l = n / 2, r = (n + 1) / 2;
    res = min(res, d * (n - l * 2) + a + dp(l));
    res = min(res, d * (r * 2 - n) + a + dp(r));
    l = n / 3, r = (n + 2) / 3;
    res = min(res, dp(l) + d * (n - l * 3) + b);
    res = min(res, dp(r) + (r * 3 - n) * d + b);
    l = n / 5, r = (n + 4) / 5;
    res = min(res, dp(l) + c + (n - l * 5) * d);
    res = min(res, dp(r) + c + (r * 5 - n) * d);
    mp[n] = res;
    return res;
}

