struct TestCase{
  ll N;
  ll A;
  ll B;
  ll C;
  ll D;
};

void Check(TestCase *Tes, ll num,ll nowcost,ll N, ll* mincost){
  if(num==N){
    if(nowcost<*mincost){
      *mincost = nowcost;
    }
  }else{

    ll n,nc;
    if(nowcost>*mincost){
      Check(Tes,N,nowcost,N,mincost);
    }else if(num>N){
      n = num-1;
      nc = nowcost+Tes->D;
      Check(Tes,n,nc,N,mincost);
    }else{
      n = num+1;
      nc = nowcost+Tes->D;
      Check(Tes,n,nc,N,mincost);
      n = num*2;
      nc = nowcost+Tes->A;
      Check(Tes,n,nc,N,mincost);
      n = num*3;
      nc = nowcost+Tes->B;
      Check(Tes,n,nc,N,mincost);
      n = num*5;
      nc = nowcost+Tes->C;
      Check(Tes,n,nc,N,mincost);
    }
  }

}


