			return n*d;
	}
	if(n%2==0){
		ans=min(ans,solve(n/2)+a);
	}else{
		ans=min(ans,solve(n/2)+(n-n/2*2)*d+a);
		ans=min(ans,solve((n+1)/2)+abs(n-(n+1)/2*2)*d+a);
	}
	if(n%3==0){
		ans=min(ans,solve(n/3)+b);
	}else {
		ans=min(ans,solve(n/3)+(n-n/3*3)*d+b);
		ans=min(ans,solve((n+2)/3)+abs(n-(n+2)/3*3)*d+b);
