ll dfs(ll x){
    if(x==0) return 0;

    if(mp.find(x)!=mp.end()) return mp[x];
    ll a2=2,a3=3,a5=5,a1=1,a4=4;

    ll k=dfs(x/a2)+a+x%a2*d;
    if((x+a1)/a2<x) k=min(k,dfs((x+a1)/a2)+a+x%a2*d);
    ll j=dfs(x/a3)+b+x%a3*d;
    if((x+a2)/a3<x)j=min(j,dfs((x+a2)/a3)+b+(a2-(x+a2)%a3)*d);
    ll q=dfs(x/a5)+c+x%a5*d;
    if((x+a4)/a5<x) q=min(q,dfs((x+a4)/a5)+c+(a4-(x+a4)%a5)*d);
    ll h;
    if(k/x<d) h=k; else h=x*d;
    h=min(h,j);
    h=min(h,q);
    mp[x]=h;

    if(h<0) cout<<"ERR";
    return mp[x];
}

