    // dbg(dp0);
    // dbg(dpk);
    // dbg(dpyo);
    // dbg(ret);
    return ret;
}

lint rec(lint x)
{
    if (x == 0) return 0;
    if (x == 1) return D;
    if (mp.count(x)) return mp[x];
    __int128 ret = __int128(D) * x;
    {
        // use 2 only
        chmin(ret, solve2(x));
    }
    int mod3 = x % 3;
    chmin<__int128>(ret, rec(x / 3 + (mod3 >= 2)) + B + (mod3 > 0) * D);
    int mod5 = x % 5;
    chmin<__int128>(ret, rec(x / 5 + (mod5 >= 3)) + C + min(mod5, (5 - mod5) % 5) * D);
    mp[x] = ret;
    return ret;
}

