typedef pair <ll, ll> pii;

map <ll, bool> vis;
priority_queue <pii, vector <pii>, greater <pii> > Q;

void solve() {
  cin >> N >> A >> B >> C >> D;
  vis.clear();
  while (!Q.empty()) Q.pop();
  Q.push(pii(0, N)), vis[N] = 1;
  while (1) {
    pii p = Q.top();
    ll val = p.first, num = p.second;
//    printf("(%lld %lld)\n", val, num);
    if (num == 1) {
      printf("%lld\n", val);
      return;
    }
    Q.pop();
    ll tmp = num, cnt = 0;
    tmp = num;
    if (num % 2 == 0) {
      while (tmp % 2 == 0) tmp /= 2, cnt++;
      if (!vis[tmp]) Q.push(pii(val + cnt * A, tmp)), vis[tmp] = 1;
    }
    tmp = num, cnt = 0;
    if (num % 3 == 0) {
      while (tmp % 3 == 0) tmp /= 3, cnt++;
      if (!vis[tmp]) Q.push(pii(val + cnt * B, tmp)), vis[tmp] = 1;
    }
    tmp = num, cnt = 0;
    if (num % 5 == 0) {
      while (tmp % 5 == 0) tmp /= 5, cnt++;
      if (!vis[tmp]) Q.push(pii(val + cnt * C, tmp)), vis[tmp] = 1;
    }
    tmp = num, cnt = 0;
    while (tmp % 2 != 0) tmp++, cnt++;
    if (!vis[tmp]) Q.push(pii(val + cnt * D, tmp)), vis[tmp] = 1;
    tmp = num, cnt = 0;
    while (tmp % 3 != 0) tmp++, cnt++;
    if (!vis[tmp]) Q.push(pii(val + cnt * D, tmp)), vis[tmp] = 1;
    tmp = num, cnt = 0;
    while (tmp % 5 != 0) tmp++, cnt++;
    if (!vis[tmp]) Q.push(pii(val + cnt * D, tmp)), vis[tmp] = 1;
    tmp = num, cnt = 0;
    while (tmp % 2 != 0 && tmp > 0) tmp--, cnt++;
    if (!vis[tmp] && tmp > 0) Q.push(pii(val + cnt * D, tmp)), vis[tmp] = 1;
    tmp = num, cnt = 0;
    while (tmp % 3 != 0 && tmp > 0) tmp--, cnt++;
    if (!vis[tmp] && tmp > 0) Q.push(pii(val + cnt * D, tmp)), vis[tmp] = 1;
    tmp = num, cnt = 0;
    while (tmp % 5 != 0 && tmp > 0) tmp--, cnt++;
    if (!vis[tmp] && tmp > 0) Q.push(pii(val + cnt * D, tmp)), vis[tmp] = 1;
  }
}

