bool ad(ll x, ll v) {
	if (dp.find(x) == dp.end() || dp[x] > v) {
		dp[x] = v;
		return true;
	}
	else return false;
}

void dfs(ll x) {
	//cout << x << " " << dp[x] << endl;
	if (x == 0) return;
	if (x%2 == 0) {
		ll v = min(a, d*(x/2)) + dp[x];
		if (ad(x/2, v)) dfs(x/2);
	}
	else {
		ll v = min(a+d, d + d*(x/2)) + dp[x];
		if (ad(x/2, v)) dfs(x/2);
		v = min(a+d, d + d*(x/2+1)) + dp[x];
		if (ad(x/2+1, v)) dfs(x/2+1);
	}
	if (x%3 == 0) {
		ll v = min(b, d*2*(x/3)) + dp[x];
		if (ad(x/3, v)) dfs(x/3);
	}
	else {
		ll m = x%3;
		ll v = min(b+d*m, d*m + d*2*(x/3)) + dp[x];
		if (ad(x/3, v)) dfs(x/3);
		v = min(b+d*(3-m), d*(3-m) + d*2*(x/3+1)) + dp[x];
		if (ad(x/3+1, v)) dfs(x/3+1);
	}
	if (x%5 == 0) {
		ll v = min(c, d*4*(x/5)) + dp[x];
		if (ad(x/5, v)) dfs(x/5);
	}
	else {
		ll m = x%5;
		ll v = min(c+d*m, d*m + d*4*(x/5)) + dp[x];
		if (ad(x/5, v)) dfs(x/5);
		v = min(b+d*(5-m), d*(5-m) + d*4*(x/5+1)) + dp[x];
		if (ad(x/5+1, v)) dfs(x/5+1);
	}
	return;
}

