ll solve(ll n){
    if(n==0) return 0;
    if(n==1) return D;
    if(mp[n]>0) return  mp[n];
    ll l1=(n/2)*2LL;
    ll r1=((n+1)/2)*2LL;
    ll l2=(n/3)*3LL;
    ll r2=((n+2)/3)*3LL;
    ll l3=(n/5)*5LL;
    ll r3=((n+4)/5)*5LL;

    ll ans=(ll)1e18;
