    res = min(res, llabs(dole2 - n) * d + a + dfs(dole2 / 2));
    res = min(res, llabs(gore2 - n) * d + a + dfs(gore2 / 2));
    res = min(res, llabs(dole3 - n) * d + b + dfs(dole3 / 3));
    res = min(res, llabs(gore3 - n) * d + b + dfs(gore3 / 3));
    res = min(res, llabs(dole5 - n) * d + c + dfs(dole5 / 5));
    res = min(res, llabs(gore5 - n) * d + c + dfs(gore5 / 5));

    m[n] = res;

