	if (n % 3) ret = min(ret, solve(n/3+1) + b+d*(3-n%3));

	ret = min(ret, solve(n/5) + c+d*(n%5));
	if (n % 5) ret = min(ret, solve(n/5+1) + c+d*(5-n%5));

	return dp[n] = ret;
}

