{
	int T; scanf("%d", &T);
	while (T--) {
		dp.clear();
		ull n; scanf("%llu%llu%llu%llu%llu", &n, &a, &b, &c, &d);
		dp[0] = 0; dp[1] = d;
		printf("%llu\n", solve(n));
	}
	return 0;
}

