	ret=min(ret,Query(n/2+1)+min((__int128)(2-n%2)*D+A,(__int128)(n-n/2-1)*D));
	ret=min(ret,Query(n/3)+min((__int128)n%3*D+B,(__int128)(n-n/3)*D));
