ll arr[6];
void solve() {
    ll N,A,B,C,D; cin >> N >> A >> B >> C >> D;

    map<ll, ll> dist;
    dist[1] = 1e18;
    dist[N] = 0;
    arr[2] = A;
    arr[3] = B;
    arr[5] = C;
    priority_queue<pll, vector<pll>, greater<pll>> pq;
    pq.emplace(0,N);
    auto func=[&](ll x, ll d, int num) {
        int k = x%num;
        ll cost1 = d+D*k;
        if (!dist.count(x/num)) dist[x/num] = 1e18;
        if (chmin(dist[x/num],cost1+arr[num])) {
            pq.emplace(dist[x/num],x/num);
        }
        if (k) {
            ll cost2 = d+D*(num-k);
            if (!dist.count(x/num+1)) dist[x/num+1] = 1e18;
            if (chmin(dist[x/num+1],cost2+arr[num])) {
                pq.emplace(dist[x/num+1],x/num+1);
            }
        }
    };
    while (!pq.empty()) {
        auto[d,v] = pq.top(); pq.pop();
        if (d > dist[v]) continue;
        if (v <= 2e18/D) chmin(dist[1],dist[v]+D*(v-1));
        func(v,d,2);
        func(v,d,3);
        func(v,d,5);
    }

    cout << dist[1]+D << ln;
}
