template <typename T> inline void ckmax(T &a, T b) { a < b ? a = b : 0; }
template <typename T> inline void ckmin(T &a, T b) { a > b ? a = b : 0; }
template <typename T> inline T Abs(T a) { return a < 0 ? -a : a; }
template <typename T> inline T gcd(T a, T b) {
  T t;
  while (b) t = a, a = b, b = t - t / a * a;
  return a;
}
template <typename T> inline void exgcd(T a, T b, T &x, T &y) {
  if (!b) {
    x = 1, y = 0;
    return;
  }
  exgcd(b, a - a / b * b, y, x);
  y -= a / b * x;
}
map <ll, ll> ff;
ll n, a, b, c, d;
inline ll F(ll n) {
  if (!n) return 0;
  if (ff.count(n)) return ff[n];
  ll res = 5e18;
  if (res / n >= d) ckmin(res, n * d);
  if (n < 3) return res;
  ll tp = n / 2 * 2;
  ckmin(res, F(n / 2) + a + d * (n - tp));
  ckmin(res, F(n / 2 + 1) + a + d * (tp + 2 - n));
  tp = n / 3 * 3;
  ckmin(res, F(n / 3) + b + d * (n - tp));
  ckmin(res, F(n / 3 + 1) + b + d * (tp + 3 - n));
  tp = n / 5 * 5;
  ckmin(res, F(n / 5) + c + d * (n - tp));
  ckmin(res, F(n / 5 + 1) + c + d * (tp + 5 - n));
  return ff[n] = res;
}
