		   chmin(res, f(f, (nn-1)/2) + a[i] + d[i]);		   
		 }
		 if(nn % 3 == 0) chmin(res, f(f, nn/3) + b[i]);
		 else {
		   chmin(res, f(f, nn/3) + b[i] + d[i]*(nn % 3));
		   chmin(res, f(f, nn/3 + 1) + b[i] + d[i]*(3 - nn%3));		   		   
		 }
		 if(nn % 5 == 0) chmin(res, f(f, nn/5) + c[i]);
		 else {
		   chmin(res, f(f, nn/5) + c[i] + d[i]*(nn % 5));
		   chmin(res, f(f, nn/5 + 1) + c[i] + d[i]*(5 - nn%5));		   		   
		 }
		 return dp[nn] = res;
	       };
    cout << rec(rec, n[i]) << "\n";
  }

  return 0;
}

