ll solve(ll n)
{
    if(n==0)return 0;
    else if(n==1)return d;
    else if(dp.count(n))return dp[n];

    ll l2 = (n/2) * 2;
    ll r2 = ((n+1)/2) * 2;

    ll l3 = (n/3) * 3;
    ll r3 = ((n+2)/3) * 3;

    ll l5 = (n/5) * 5;
    ll r5 = ((n+4)/5) * 5;

    ll res = 1e18;
    if(n<=res/d)res = n*d;

    res = min(res , llabs(l2-n)*d + a + solve(l2));
    res = min(res, llabs(r2-n)*d + a + solve(r2));

    res = min(res , llabs(l3-n)*d + b + solve(l3));
    res = min(res, llabs(r3-n)*d + b + solve(r3));

    res = min(res , llabs(l5-n)*d + c + solve(l5));
    res = min(res, llabs(r5-n)*d + c + solve(r5));

    dp[n] = res;
    return res;
}

