      t = n / 5 + 1;
      fs.emplace_back(t, C + (t * 5 - n) * D);
      t = n / 5;
      fs.emplace_back(t, C + (n - t * 5) * D);
    }
    if (n % 3 == 0) {
      fs.emplace_back(n / 3, B);
