const ll INF = 5e18;

ll mul(ll x, ll y) {
	if (y && x >= INF / y) return INF;
	return x * y;
}

ll add(ll x, ll y) {
	if (x >= INF - y) return INF;
	return x + y;
}

const int sz = 1 << 20;
ll mem[sz];

ll f(ll diff, vector <int> &v, ll d, int i = 0) {
	if (!diff) return 0;
	if (diff < sz && ~mem[diff]) return mem[diff];
	if (i == int(v.size())) return mul(diff, d);
	ll ans = INF;
	if (diff % v[i] < v[i] - diff % v[i] || rand() % 2)
		ans = min(ans, f(diff / v[i], v, d, i + 1) + mul(diff % v[i], d));
	if (diff % v[i] > v[i] - diff % v[i] || rand() % 2)
		ans = min(ans, f(diff / v[i] + 1, v, d, i + 1) + mul(v[i] - diff % v[i], d));
	if (diff < sz) mem[diff] = ans;
	return ans;
}

