void solve()
{
	lint n, a, b, c, d;
	cin >> n >> a >> b >> c >> d;

	hashmap<lint, lint> m;
	m[n] = 0;
	m[1] = inf;
	m[0] = inf;
	priq<lint> q;
	q.push(n);
	while (!q.empty())
	{
		lint x = q.top();
		q.pop();

		if (x <= 1e9)
			m[0] = mmin(m[0], m[x] + d * x);

		lint b2 = x / 2, a2 = div2(x, 2);
		lint b3 = x / 3, a3 = div2(x, 3);
		lint b5 = x / 5, a5 = div2(x, 5);

		if (!exist(m, b2))
		{
			m.insert({ b2, inf });
			q.push(b2);
		}
		if (!exist(m, b3))
		{
			m.insert({ b3, inf });
			q.push(b3);
		}
		if (!exist(m, b5))
		{
			m.insert({ b5, inf });
			q.push(b5);
		}
		if (!exist(m, a2))
		{
			m.insert({ a2, inf });
			q.push(a2);
		}
		if (!exist(m, a3))
		{
			m.insert({ a3, inf });
			q.push(a3);
		}
		if (!exist(m, a5))
		{
			m.insert({ a5, inf });
			q.push(a5);
		}

		m[b2] = mmin(m[b2], m[x] + d * (x - b2 * 2) + a);
		m[b3] = mmin(m[b3], m[x] + d * (x - b3 * 3) + b);
		m[b5] = mmin(m[b5], m[x] + d * (x - b5 * 5) + c);
		m[a2] = mmin(m[a2], m[x] + d * (a2 * 2 - x) + a);
		m[a3] = mmin(m[a3], m[x] + d * (a3 * 3 - x) + b);
		m[a5] = mmin(m[a5], m[x] + d * (a5 * 5 - x) + c);
	}

	cout << mmin(m[1] + d, m[0]) << endl;
}

