			ans = min(ans, d * abs(i) + a + work(nxtN / 2));
		if(nxtN % 3 == 0 && nxtN / 3 < n)
			ans = min(ans, d * abs(i) + b + work(nxtN / 3));
		if(nxtN % 5 == 0 && nxtN / 5 < n)
			ans = min(ans, d * abs(i) + c + work(nxtN / 5));
		if(nxtN % 6 == 0 && nxtN / 6 < n)
