LL n, a, b, c, d, now;

unordered_map<LL, LL> ma;
priority_queue<LL> que;

void update(LL x, LL y)
{
	if (x >= now) return;
	if (!ma[x]) ma[x] = inf / (n - x) >= d ? (n - x) * d : inf, que.push(x);
	ma[x] = min(ma[x], y);
}

