		{
			LL x = que.top(); que.pop();
			now = x;
			if (inf / d >= x) update(0, ma[x] + d * x);
			if (x % 2 != 0)
			{
				update((x + 1) / 2, ma[x] + d + a);
				update((x - 1) / 2, ma[x] + d + a);
			}
			else update(x / 2, ma[x] + a);
			if (x % 3 != 0)
			{
				update(x / 3 + 1, ma[x] + d * (3 - x % 3) + b);
