void solve(){
    cin >> N >> A >> B >> C >> D;
    map<ll, ll> mp;
    ll ans = linf;
    mp[N] = 0;
    priority_queue<pll, vector<pll>, greater<pll>> pq;
    pq.push({0, N});

    while(!pq.empty()){
        pll p = pq.top(); pq.pop();
        ll t = p.second;
        ll c = mp[t];
        if(c < p.first) continue;
        if(t == 0){
            chmin(ans, c);
            break;
        }
        if((ans / D) + 1 >= t) chmin(ans, c + D * t);
        auto culc = [&](ll num, ll d, ll cost){
            if(mp.find(num / d) == mp.end()) mp[num / d] = linf;
            if(mp[num / d] > cost){
                mp[num / d] = cost;
                pq.push({cost, num / d});
            }
        };

        if(t % 2 == 0){
            culc(t, 2, c + A);
        }else{
            culc(t + 1, 2, c + D + A);
            culc(t - 1, 2, c + D + A);
        }

        if(t % 3 == 0){
            culc(t, 3, c + B);
        }else if(t % 3 == 1){
            culc(t - 1, 3, c + D + B);
        }else{
            culc(t + 1, 3, c + D + B);
        }

        if(t % 5 == 0){
            culc(t, 5, c + C);
        }else if(t % 5 == 1){
            culc(t - 1, 5, c + D + C);
        }else if(t % 5 == 2){
            culc(t - 2, 5, c + D * 2 + C);
        }else if(t % 5 == 3){
            culc(t + 2, 5, c + D * 2 + C);
        }else{
            culc(t + 1, 5, c + D + C);
        }
    }
    cout << ans << endl;
}

