const int DIV[3] = {2, 3, 5};

ll solve(ll n, const vector<ll> &coin, ll d, map<ll, ll> &memo) {
    if (memo.count(n)) return memo[n];
    if (n == 0) return 0;
    if (n == 1) return d;

    ll res = 1e18;
    rep(i, 3) {
        if (n % DIV[i] == 0) {
            chmin(res, coin[i] + solve(n / DIV[i], coin, d, memo));
            continue;
        }
        ll down = n / DIV[i] * DIV[i];
        chmin(res, (n - down) * d + coin[i] + solve(down / DIV[i], coin, d, memo));
        ll up = (n + DIV[i] - 1) / DIV[i] * DIV[i];
        chmin(res, (up - n) * d + coin[i] + solve(up / DIV[i], coin, d, memo));
    }
    return memo[n] = res;
}

