ll N,A,B,C,D;
map<ll,ll> mp; // key:num val:cost

void input() {
	cin>>N>>A>>B>>C>>D;
}

ll calc(ll num) {
	if(num<2) return mp[num]=num*D;
	if(mp.find(num)!=mp.end()) return mp[num];
	ll tmp=LLINF;
	if(num < 1000000001) tmp=num*D;

	chmin(tmp,calc(num/2) + A + num%2*D);
	chmin(tmp,calc((num+1)/2) + A + num%2*D);
	chmin(tmp,calc(num/3) + B + (num-num/3*3)*D);
	chmin(tmp,calc((num+2)/3) + B + ((num+2)/3*3-num)*D);
	chmin(tmp,calc(num/5) + C + (num-num/5*5)*D);
	chmin(tmp,calc((num+4)/5) + C + ((num+4)/5*5-num)*D);

	return mp[num]=tmp;
}

void solve() {
	mp.clear();
	cout<<calc(N)<<endl;
}

int main() {
	cin>>T;
	while(T) {
		input();
		solve();
		T--;
	}
}

