ll n, a, b, c, d;
map<ll, __int128_t> dp;

__int128_t dfs(ll x) {
    if (dp.count(x)) return dp[x];
    if (x == 0) return 0;
    if (x == 1) return d;
    __int128_t res = (__int128_t)d * x;
    chmin(res, dfs(x / 2) + a + abs((x / 2) * 2 - x) * d);
    if (x % 2 != 0)
        chmin(res, dfs(x / 2 + 1) + a + abs((x / 2 + 1) * 2 - x) * d);
    chmin(res, dfs(x / 3) + b + abs((x / 3) * 3 - x) * d);
    if (x % 3 != 0)
        chmin(res, dfs(x / 3 + 1) + b + abs((x / 3 + 1) * 3 - x) * d);
    chmin(res, dfs(x / 5) + c + abs((x / 5) * 5 - x) * d);
    if (x % 5 != 0)
        chmin(res, dfs(x / 5 + 1) + c + abs((x / 5 + 1) * 5 - x) * d);
    return dp[x] = res;
}

