ll a, b, c, d, n;

Pll f(ll prev_cost, ll prev_n,  ll base, bool increase) {
    if(increase) {
        ll next_n = (prev_n + base - 1) / base * base / base;
        return Pll(
            prev_cost + ((base - prev_n % base) % base) * d + ((base==2)?a:((base==3)?b:c)), 
            next_n
        );
    } else {
        ll next_n = prev_n / base * base / base;
        return Pll(
            prev_cost + (prev_n % base) * d + ((base==2)?a:((base==3)?b:c)),
            next_n
        );
    }
}

void solve() {
    cin >> n >> a >> b >> c >> d;

    map<ll, ll> mp;
    mp[n] = 0;
    priority_queue<Pll, vector<Pll>, greater<Pll>> que;
    que.emplace(0, n);
    while(!que.empty()) {
        Pll p = que.top(); que.pop();
        if(mp.find(p.second) != mp.end() && mp[p.second] < p.first) continue;

        Pll q[6];
        q[0] = f(p.first, p.second, 2LL, true);
        q[1] = f(p.first, p.second, 2LL, false);
        q[2] = f(p.first, p.second, 3LL, true);
        q[3] = f(p.first, p.second, 3LL, false);
        q[4] = f(p.first, p.second, 5LL, true);
        q[5] = f(p.first, p.second, 5LL, false);
        for(int i=0;i<6;++i) {
            if(mp.find(q[i].second) == mp.end() || q[i].first < mp[q[i].second]) {
                que.push(q[i]);
                mp[q[i].second] = q[i].first;
            }
        }
        if(p.second < 1000000000LL && (mp.find(0LL) == mp.end() || p.first + d * p.second < mp[0])) {
            mp[0LL] = p.first + d * p.second;
        }

    }

    cout << mp[0] << endl;
}

