    void solve(istream& cin, ostream& cout) {
      SPEED;
      int t; cin >> t;
      while(t--) {
        ll n, a, b, c, d; cin >> n >> a >> b >> c >> d;
        unordered_map<ll, ll> mp;

        priority_queue<P, vector<P>, greater<>> que;
        que.emplace(0, n);
        mp[n] = 0;
        mp[0] = LLONG_MAX/2;
        while(!que.empty()) {
          auto pa = que.top(); que.pop();
          auto cost = pa.first;
          auto u = pa.second;
          debug(cost, u);
          if (cost > mp[u]) continue;

          auto k = u%5;
          // down
          auto v = u/5;
          auto cc = cost + c + k*d;
          if (abs(u-v) < 1e+9) chmin(cc, cost + (u-v)*d);
          if (mp.find(v) == mp.end() || mp[v] > cc) {
            mp[v] = cc;
            debug(cc, v);
            if (cc < mp[0]) que.emplace(cc, v);
          }

          v++;
          cc = cost + c + (5-k)*d;
          if (abs(u-v) < 1e+9) chmin(cc, cost + abs(u-v)*d);
          if (mp.find(v) == mp.end() || mp[v] > cc) {
            mp[v] = cc;
            debug(cc, v);
            if (cc < mp[0]) que.emplace(cc, v);
          }

          k = u%3;
          v = u/3;
          cc = cost + b + k*d;
          if (abs(u-v) < 1e+9) chmin(cc, cost + abs(u-v)*d);
          if (mp.find(v) == mp.end() || mp[v] > cc) {
            mp[v] = cc;
            debug(cc, v);
            if (cc < mp[0]) que.emplace(cc, v);
          }

          v++;
          cc = cost + b + (3-k)*d;
          if (abs(u-v) < 1e+9) chmin(cc, cost + abs(u-v)*d);
          if (mp.find(v) == mp.end() || mp[v] > cc) {
            mp[v] = cc;
            debug(cc, v);
            if (cc < mp[0]) que.emplace(cc, v);
          }

          k = u%2;
          v = u/2;
          cc = cost + a + k*d;
          if (abs(u-v) < 1e+9) chmin(cc, cost + (u-v)*d);
          if (mp.find(v) == mp.end() || mp[v] > cc) {
            mp[v] = cc;
            debug(cc, v);
            if (cc < mp[0]) que.emplace(cc, v);
          }

          v++;
          cc = cost + a + (2-k)*d;
          if (abs(u-v) < 1e+9) chmin(cc, cost + abs(u-v)*d);
          if (mp.find(v) == mp.end() || mp[v] > cc) {
            mp[v] = cc;
            debug(cc, v);
            if (cc < mp[0]) que.emplace(cc, v);
          }
        }

        cout << mp[0] << endl;

      }
    }
};

