  if (!n) return 0;
  if (ff.count(n)) return ff[n];
  ll res = 5e18;
  if (res / n >= d) ckmin(res, n * d);
  if (n == 1) return res;
  ll tp = n / 2 * 2;
  ckmin(res, F(n / 2) + a + d * (n - tp));
  if (n > 2) ckmin(res, F(n / 2 + 1) + a + d * (tp + 2 - n));
  tp = n / 3 * 3;
