long long INF = 1000000000000000000;
long long dp(long long N, long long A, long long B, long long C, long long D, map<long long, long long> &mp){
  if (mp.count(N)){
    return mp[N];
  } else if (N == 0){
    return 0;
  } else if (N == 1){
    return D;
  } else {
    long long ans = INF;
    if (N <= 10000000000){
      ans = min(ans, N * D);
    }
    ans = min(ans, dp(N / 2, A, B, C, D, mp) + A + (N % 2) * D);
    ans = min(ans, dp((N + 1) / 2, A, B, C, D, mp) + A + (2 - N % 2) % 2 * D);
    ans = min(ans, dp(N / 3, A, B, C, D, mp) + B + (N % 3) * D);
    ans = min(ans, dp((N + 2) / 3, A, B, C, D, mp) + B + (3 - N % 3) % 3 * D);
    ans = min(ans, dp(N / 5, A, B, C, D, mp) + C + (N % 5) * D);
    ans = min(ans, dp((N + 4) / 5, A, B, C, D, mp) + C + (5 - N % 5) % 5 * D);
    mp[N] = ans;
    return ans;
  }
}
