	if(dist > INF / d){
		dist = INF;
	}else{
		dist *= d;
	}
	return dist;
}

ll cost1(ll a, ll b){
	ll dist = abs(a-b);

	if(dist > INF / d){
		dist = INF;
	}else{
		dist *= d;
	}
	return dist;
}

ll geth(ll x){
	return 0;
	// expected from x to n
	ll dist = cost1(x);

	// muls
	if(x != 0){
		ll now, cs;
		now = x;
		cs = 0;
		while(now){
			if(now % 2 == 0){
				now /= 2;
				cs += min(a, cost1(now, now/2));
			}else{
				now--;
				cs += d;
			}
		}
		dist = min(dist, cs);
		now = x;
		cs = 0;
		while(now){
			if(now % 3 == 0){
				now /= 3;
				cs += min(b, cost1(now, now/2));
			}else{
				now--;
				cs += d;
			}
		}
		dist = min(dist, cs);
		now = x;
		cs = 0;
		while(now){
			if(now % 5 == 0){
				now /= 5;
				cs += min(c, cost1(now, now/2));
			}else{
				now--;
				cs += d;
			}
		}
		dist = min(dist, cs);

	}

	return dist;
}

ll safeadd(ll a, ll b){
	if(a + b > INF)return INF;
	return a+b;
}

