ll f(ll N){

	if (N == 0) return 0;
	if (N == 1) return d;
	if(rec.find(N)!=rec.end())return rec[N];
	ll ans = 1e18;
	if (N<=1e18/d) ans = N * d;
	ll l1 = (N/2)*2, r1 = ((N+1)/2)*2;
	ll l2 = (N/3)*3, r2 = ((N+2)/3)*3;
	ll l3 = (N/5)*5, r3 = ((N+4)/5)*5;
	ans = std::min(ans, f(l1/2) + (N-l1) * d + a);
	ans = std::min(ans, f(l2/3) + (N-l2) * d + b);
	ans = std::min(ans, f(l3/5) + (N-l3) * d + c);
	ans = std::min(ans, f(r1/2) + (r1-N) * d + a);
	ans = std::min(ans, f(r2/3) + (r2-N) * d + b);
	ans = std::min(ans, f(r3/5) + (r3-N) * d + c);
	rec[N] = ans;
	return ans;
}

