ll solve(ll n) {
    //cerr << n << endl;
    if (n == 0) 
        return 0;
    if (n == 1) {
        return c[3];
    }
    if (n == 2) {
        return min(2 * c[3], c[3] + c[0]);
    }
    //cerr << n << " " << mp.size() << endl;
    if (mp.find(n) != mp.end()) {
        return mp[n];
    }
    ll res = N;
    if (n <= res / c[3])
        res = c[3] * n;
    vector<ll> r = {n % 2, n % 3, n % 5};
    vector<int> d = {2, 3, 5};
    for (int i = 0; i < 3; ++i) {
        if (i == 0) {
            res = min(res, solve((n - r[i]) / d[i]) + r[i] * c[3] + c[i]);
            if (r[i] != 0)
                res = min(res, solve((n + d[i] - r[i]) / d[i]) + (d[i] - r[i]) * c[3] + c[i]);
            continue;
        }
        if (r[i] * 2 < d[i])
            res = min(res, solve((n - r[i]) / d[i]) + r[i] * c[3] + c[i]);
        else
            res = min(res, solve((n + d[i] - r[i]) / d[i]) + (d[i] - r[i]) * c[3] + c[i]);
    }
    mp[n] = res;
    return res;
}

