void solve() {
    int t;
    cin >> t;
    vl l{2, 3, 5};
    while (t--) {
        ll n, a, b, c, d;
        cin >> n >> a >> b >> c >> d;
        vl p{0, 1, a, b, 4, c};
        ll lim = LINF / d;
        map<ll, ll> memo;
        memo[n] = 0;
        function<void(ll)> rec = [&](ll m) {
            // cout << m << ": " << memo[m] << endl;
            if (m == 1) {
                if (memo.count(0) == 0 or memo[0] > memo[1] + d) memo[0] = memo[1] + d;
                return;
            }
            for (auto k : l) {
                ll r = m % k;
                ll mn = p[k] + d * r;
                if (m - (m / k) <= lim) chmin(mn, d * (m - (m / k)));
                if (memo.count(m / k) == 0 or memo[m / k] > memo[m] + mn) {
                    memo[m / k] = memo[m] + mn;
                    rec(m / k);
                }
                mn = p[k] + d * (k - r);
                if (m - (m / k + 1) <= lim) chmin(mn, d * (m - (m / k + 1)));
                if (memo.count(m / k + 1) == 0 or memo[m / k + 1] > memo[m] + mn) {
                    memo[m / k + 1] = memo[m] + mn;
                    rec(m / k + 1);
                }
            }
        };
        rec(n);
        cout << memo[0] << endl;
    }
}

