long long rec(long long x, long long A, long long B, long long C, long long D, map<long long, long long>& dp){
  if(dp.count(x)) return dp[x];
  if(x == 1) return D;

  long long ret = INF;

  if(x <= 1000000000) ret = x * D;

  if(x >= 2) ret = min(rec(x / 2, A, B, C, D, dp) + A + D * (x % 2), ret);
  if((x + 1) / 2 != x) ret = min(rec((x + 1) / 2, A, B, C, D, dp) + A + D * (2 - x % 2), ret);

  if(x >= 3) ret = min(rec(x / 3, A, B, C, D, dp) + B + D * (x % 3), ret);
  if((x + 2) / 3 != x) ret = min(rec((x + 2) / 3, A, B, C, D, dp) + B + D * (3 - x % 3), ret);

  if(x >= 5) ret = min(rec(x / 5, A, B, C, D, dp) + C + D * (x % 5), ret);
  if((x + 4) / 5 != x) ret = min(rec((x + 4) / 5, A, B, C, D, dp) + C + D * (5 - x % 5), ret);

  return dp[x] = ret;
}

