map<long long, long long> dp;
long long a, b, c, d;

long long rec(long long n) {
  if (n == 0) return 0;
  if (n == 1) return d;
  auto I = dp.find(n);
  if (I != dp.end()) return I->second;
  long long best = LLONG_MAX;
  if (n % 2 == 0) {
    best = min(best, a + rec(n / 2));
  }
  if (n % 3 == 0) {
    best = min(best, b + rec(n / 3));
  }
  if (n % 5 == 0) {
    best = min(best, c + rec(n / 5));
  }
  if (LLONG_MAX / d > n) {
    best = min(best, d*n);
  }
  for (int i = -5; i <= 5; i++) {
    long long m = n + i;
    if (m < 0) continue;
    if (m % 2 == 0 && m / 2 < n) {
      best = min(best, abs(i) * d + a + rec(m/2));
    }
    if (m % 3 == 0 && m / 3 < n) {
      best = min(best, abs(i) * d + b + rec(m/3));
    }
    if (m % 5 == 0 && m / 5 < n) {
      best = min(best, abs(i) * d + c + rec(m/5));
    }
  }
  dp[n] = best;
  return best;
}

