ll dist(ll k) {
	if (m.find(k) != m.end()) {
		return m[k];
	}

	if (k == 0) {
		m[0] = 0;
		return 0;
	}
	if (k == 1) {
		m[1] = d;
		return d;
	}

	ll r = d * k;
	if (INF / d < k) {
		r = INF;
	}

	for (int i = -1; i <= 1; ++i) {
		ll num = k + i;

		if (num >= 0 && num % 2 == 0) {
			r = min(r, dist(num / 2) + a + d * abs(i));
		}
	}

	for (int i = -2; i <= 2; ++i) {
		ll num = k + i;
		if (num >= 0 && num % 3 == 0) {
			r = min(r, dist(num / 3) + b + d * abs(i));
		}
	}
	for (int i = -3; i <= 3; ++i) {
		ll num = k + i;
		if (num >= 0 && num % 5 == 0) {
			r = min(r, dist(num / 5) + c + d * abs(i));
		}
	}
	m[k] = r;

	return m[k];
}




