ll F(ll N,ll &A,ll &B,ll &C,ll &D,Map &M){
    if(M[N])return M[N];
    if(N==0)return 0;
    if(N==1)return D;
    ll a2=INF,a3=INF,a5=INF;
    ll b2,b3,b5;
    ll c2,c3,c5;
    b2=N%2;b3=N%3;b5=N%5;
    c2=N-b2;c3=N-b3;c5=N-b5;
    a2=b2*D+A+F(c2/2,A,B,C,D,M);
    a3=b3*D+B+F(c3/3,A,B,C,D,M);
    a5=b5*D+C+F(c5/5,A,B,C,D,M);
    if(c2/2+1<N){
        chmin(a2,(2-b2)*D+A+F(c2/2+1,A,B,C,D,M));
        double r=(double)(2-b2)+(double)(A/D);
        if(r>(N-(c2/2+1)))
        chmin(a2,D*(N-(c2/2+1))+F(c2/2+1,A,B,C,D,M));
    }
    if(c3/3+1<N){
        chmin(a3,(3-b3)*D+B+F(c3/3+1,A,B,C,D,M));
        double r=(double)(3-b3)+(double)(B/D);
        if(r>(N-(c3/3+1)))
        chmin(a3,D*(N-(c3/3+1))+F(c3/3+1,A,B,C,D,M));
    }
    if(c5/5+1<N){
        chmin(a5,(5-b5)*D+C+F(c5/5+1,A,B,C,D,M));
        double r=(double)(5-b5)+(double)(C/D);
        if(r>(N-(c5/5+1)))
        chmin(a5,D*(N-(c5/5+1))+F(c5/5+1,A,B,C,D,M));
    }
    return M[N]=(min(a2,min(a3,a5)));
}

