#include <bits/stdc++.h>
using namespace std;

int calculate(int64_t n, int a, int b, int c, int d)
{
  double n2 = n;
  int k = 0;//kはnを２で割れる回数
  int64_t M, sum;//Mは値,sumは必要コイン合計
  int k1, k2;//k1はaの回数, k2はbの回数
  int i = 1;//カウンタ変数

  M++; sum += d;//M = 1,コインはd枚使用
  while(n2 < 2)
  {
    n2 /= 2;
    k++;
  }//kの値(=a + b + cの値確定)

  int total[n * (n + 1) / 2];

  k1 = k;
  while(k1 > 0)
  {
    k2 = k - k1;
    while(k2 > 0)
    {
      M *= 2 * k1 * 3 * k2 * 5 * (k - k1 - k2);
      sum += a * k1 + b * k2 + c * (k - k1 - k2);
      if(n < M)
      {
        sum += d * (M - n);
      }
      if(n > M)
      {
        sum += d * (n - M);
      }
      total[i] = sum;
      i++;
      M = 1;
      sum = d;
      k2--;
    }
    k1--;
  }

  int64_t max = 0;

  for(int j = 1; j <= n * (n + 1) / 2; j++)
  {
    if(max < total[i])
    {
      max = total[i];
    }   
  }

  cout << max << endl;
}

