int solve(int n) {
	if (n == 0)return 0;
	if (n == 1)return D;
	if (memo[n] != 0)return memo[n];

	int res = LLINF;
	if (res / D > n)res = n * D;
	if (n % 2 == 0) {
		chmin(res, solve(n / 2) + A);
	}
	else {
		chmin(res, solve(n / 2) + A + D);
		chmin(res, solve((n + 1) / 2) + A + D);
	}
	if (n % 3 == 0) {
		chmin(res, solve(n / 3) + B);
	}
	else {
		if (n / 3 != 0)chmin(res, solve(n / 3) + B + D * (n % 3));
		else chmin(res, D*n);
		chmin(res, solve((n + 3) / 3) + B + D * (3 - (n % 3)));
	}
	if (n % 5 == 0) {
		chmin(res, solve(n / 5) + C);
	}
	else {
		if (n / 5 != 0)chmin(res, solve(n / 5) + C + D * (n % 5));
		else chmin(res, D*n);
		chmin(res, solve((n + 5) / 5) + C + D * (5 - (n % 5)));
	}
	return memo[n] = res;
}

