inline int nxt() {
	int x;
	scanf("%d", &x);
	return x;
}

const int N = 100000;
long long small[N];

void solve() {
	long long n;
	scanf("%lld", &n);
	int a = nxt(), b = nxt(), c = nxt(), d = nxt();
	fill_n(small, N, (long long)1e18);
	small[0] = 0;
	set<pair<long long, int>> S;
	S.insert({0, 0});
	while (!S.empty()) {
		auto [val, pos] = *S.begin();
		S.erase(S.begin());
		if (pos > 0 && small[pos - 1] > val + d) {
			S.erase({small[pos - 1], pos - 1});
			small[pos - 1] = val + d;
			S.insert({small[pos - 1], pos - 1});
		}
		if (pos + 1 < N && small[pos + 1] > val + d) {
			S.erase({small[pos + 1], pos + 1});
			small[pos + 1] = val + d;
			S.insert({small[pos + 1], pos + 1});
		}
		if (pos * 2 < N && small[pos * 2] > val + a) {
			S.erase({small[pos * 2], pos * 2});
			small[pos * 2] = val + a;
			S.insert({small[pos * 2], pos * 2});
		}
		if (pos * 3 < N && small[pos * 3] > val + b) {
			S.erase({small[pos * 3], pos * 3});
			small[pos * 3] = val + b;
			S.insert({small[pos * 3], pos * 3});
		}
		if (pos * 5 < N && small[pos * 5] > val + c) {
			S.erase({small[pos * 5], pos * 5});
			small[pos * 5] = val + c;
			S.insert({small[pos * 5], pos * 5});
		}
	}
	map<long long, long long> cache;
	auto rec = [&](long long n, const auto& rec) {
		if (n < N) {
			return small[n];
		}
		if (cache.count(n)) {
			return cache[n];
		}
		long long res = 1e18;
		if (n < 2e18 / d) {
			res = n * d;
		}
		res = min(res, n % 2 * d + a + rec((n - n % 2) / 2, rec));
		res = min(res, (2 - n % 2) * d + a + rec((n + 2 - n % 2) / 2, rec));
		res = min(res, n % 3 * d + b + rec((n - n % 3) / 3, rec));
		res = min(res, (3 - n % 3) * d + b + rec((n + 3 - n % 3) / 3, rec));
		res = min(res, n % 5 * d + c + rec((n - n % 5) / 5, rec));
		res = min(res, (5 - n % 5) * d + c + rec((n + 5 - n % 5) / 5, rec));
		return cache[n] = res;
	};
	cout << rec(n, rec) << "\n";
}

int main() {
	int t = nxt();
	while (t--) {
		solve();
	}

	return 0;
}

