const LL Inf=(LL)9223372036854775807;
LL res=Inf;
LL X[3],Y[3];

map<LL,LL> memo;
LL f(LL n) {
  if(memo.count(n)) return memo[n];
  LL &res=memo[n];
  res=Inf;
  if(n<=1e9) res=D*n;
  REP(i,3) {
    LL y=Y[i],c=X[i];
    vector<LL> ts={(n+y-1)/y, n/y};
    //dump(n,y,ts[0],ts[1]);
    FORR(t,ts) {
      SMIN(res,abs(n-t*y)*D+c+f(t));
    }
  }
  //dump(n,res);
  return res;
}

LL solve() {
  X[0]=C,X[1]=B,X[2]=A;
  Y[0]=5,Y[1]=3,Y[2]=2;
  memo.clear();
  LL res=f(N);
  //dump(N,SZ(memo),res);
  return res;
}

void dfs(__int128_t cur, __int128_t coin, int i) {
  dump(cur,coin,i);
  if(cur>=N||i>=3) {
    __int128_t a=coin+D*max(N-cur,cur-N);
    if(a>=Inf) return;
    SMIN(res,(LL)a);
    return;
  }
  dfs(cur,coin,i+1);
  while(cur<N) {
    cur*=Y[i],coin+=X[i];
    dfs(cur,coin,i+1);
  }
}

