long long solve() {
  map<long long, long long> mp;
  mp[n] = 0;
  mp[0] = 1e18;
  using P = pair<long long, long long>;
  priority_queue<P, vector<P>, greater<P>> pq;
  pq.push(P(0, n));
  while (pq.size()) {
    auto [cost, num] = pq.top();
    pq.pop();
    if (cost > mp[0]) return mp[0];
    if (cost > mp[num]) continue;
    if (num == 0) return cost;
    long long nextcos = cost, nextnum = num;
    if (cost + num * d >= 0) mp[0] = min(mp[0], cost + num * d);
    for (int i = 0; i < 3; ++i) {
      nextnum = num, nextcos = cost;
      long long tmp = x[i] - num % x[i];
      nextnum += tmp;
      nextnum /= x[i];
      nextcos += d * tmp;
      nextcos += a[i];
      if (mp.find(nextnum) == mp.end() || mp[nextnum] > nextcos) {
        mp[nextnum] = nextcos;
        pq.push(P(nextcos, nextnum));
      }
      nextnum = num, nextcos = cost;
      tmp = num % x[i];
      nextnum -= tmp;
      nextnum /= x[i];
      nextcos += d * tmp;
      nextcos += a[i];
      if (mp.find(nextnum) == mp.end() || mp[nextnum] > nextcos) {
        mp[nextnum] = nextcos;
        pq.push(P(nextcos, nextnum));
      }
    }
  }
  return mp[0];
}

