const ll LINF = 6e18;

ll c2, c3, c5, c1;
map<ll, ll> mp;

ll dfs(ll n) {
  if (!mp.count(n)) {
    if (n == 0) {
      mp[n] = 0;
    } else if (n == 1) {
      mp[n] = c1;
    //} else if (n == 2) {
      //mp[n] = c1 + min(c1, c2);
    } else {
      ll res = LINF;
      if (n <= res / c1) res = min(res, c1 * n);
      res = min(res, dfs(n / 2) + c2 + c1 * (n % 2));
      res = min(res, dfs(n / 3) + c3 + c1 * (n % 3));
      res = min(res, dfs(n / 5) + c5 + c1 * (n % 5));
      res = min(res, dfs(1 + n / 2) + c2 + c1 * (2 - (n % 2)));
      res = min(res, dfs(1 + n / 3) + c3 + c1 * (3 - (n % 3)));
      res = min(res, dfs(1 + n / 5) + c5 + c1 * (5 - (n % 5)));
      mp[n] = res;
    }
  }
  return mp[n];
}

