map<ll,ll> memo;
ll rec(vll A,ll m)
{
    if(m == 0)
    return 0;
    if(m == 1)
    return A.back();
    if(memo.count(m))
    {
        return memo[m];
    }
    ll res=INF;
    if(__builtin_mul_overflow(A.back(),m,&res))res=INF;
    vll div = {2,3,5};
    for (int i = 0;i<3;i++)
    {
        for (int j = 0; j < div[i]; j++)
        {
            if((m+j) % div[i] == 0)
            chmin(res,j*A.back()+A[i]+rec(A,(m+j)/div[i]));
            if((m-j)%div[i] == 0)
            chmin(res,j*A.back()+A[i]+rec(A,(m-j)/div[i]));
        }

    }
    memo[m]=res;
    return res;
}
