ll go(ll n) {
    set<pair<int128, int128>> st;
    dp[n] = 0;
    dp[0] = n * d;
    st.insert({ 0, n });
    st.insert({ n * d, 0 });
    while (!st.empty()) {
        auto p = *st.begin();
        st.erase(st.begin());
        int128 x = p.Y, dd = p.X;
        if (x == 0) return dd;
        if (dd >= dp[0]) continue;
        for (int128 i = 0; i < 3; i++) {
            int128 ddd = kek[i] - x % kek[i];
            int128 y = (x + ddd) / kek[i];
            if (dp.find(y) == dp.end() or dp[y] > dd + rofl[i] + ddd * d) {
                st.erase({ dp[y], y });
                dp[y] = dd + rofl[i] + ddd * d;
                st.insert({ dp[y], y });
            }
            ddd = x % kek[i];
            y = (x - ddd) / kek[i];
            if (dp.find(y) == dp.end() or dp[y] > dd + rofl[i] + ddd * d) {
                st.erase({ dp[y], y });
                dp[y] = dd + rofl[i] + ddd * d;
                st.insert({ dp[y], y });
            }
        }
        int128 ddd = x;
        int128 y = 0;
        if (dp[y] > dd + ddd * d) {
            st.erase({ dp[y], y });
            dp[y] = dd + ddd * d;
            st.insert({ dp[y], y });
        }
    }
    return dp[0];
}

