void solve() {
    ll N, A, B, C, D; cin >> N >> A >> B >> C >> D;
    // gmin = LINF;
    vi k = {2, 3, 5};
    PQ<ll> q;
    map<ll, ll> mp;
    ll p, prevp, np, curcost, ncost, deltacost;
    int mul;
    ll mulcost;
    q.push(N);
    mp[N] = 0;
    q.push(0);
    mp[0] = LINF;
    prevp = -1;
    while(!q.empty()) {
        p = q.top();
        curcost = mp[p];
        // cout << "got N:" << p << ", cost:" << curcost << endl;
        if (p == 0) {
            print(curcost);
            break;
        }
        if (p == prevp) continue;
        if ((LINF - curcost)/D>p) {
            mp[0] = min(mp[0], curcost + D*p);
        }
        REP(i, k.size()) {
            mul = k[i];
            if (mul == 2) mulcost = A;
            if (mul == 3) mulcost = B;
            if (mul == 5) mulcost = C;
            if (p % mul == 0) {
                np = p / mul;
                if (D < LINF/(np*(mul-1)) && np * (mul-1) * D < mulcost) {
                    ncost = curcost + np * (mul-1) * D;
                } else {
                    ncost = curcost + mulcost;
                }
                if(!mp[np]) {
                    mp[np] = ncost;
                    q.push(np);
                    // cout << "push(1):" << np << endl;
                } else if (mp[np] > ncost) {
                    mp[np] = ncost;
                }
            } else {
                // lower
                np = p - (p % mul);
                deltacost = (p % mul) * D;

                if (np > 0) {
                    np = np / mul;
                    if (D < LINF/(np*(mul-1)) && np * (mul-1) * D < mulcost) {
                        ncost = curcost + np * (mul-1) * D;
                    } else {
                        ncost = curcost + mulcost;
                    }
                    ncost += deltacost;
                    if(!mp[np]) {
                        mp[np] = ncost;
                        q.push(np);
                        // cout << "push(2):" << np << endl;
                    } else if (mp[np] > ncost) {
                        mp[np] = ncost;
                    }
                }


                // upper
                np = p + (mul - (p % mul));
                deltacost = (mul - (p % mul)) * D;

                np = np / mul;
                if (D < LINF/(np*(mul-1)) && np * (mul-1) * D < mulcost) {
                    ncost = curcost + np * (mul-1) * D;
                } else {
                    ncost = curcost + mulcost;
                }
                ncost += deltacost;
                if(!mp[np]) {
                    mp[np] = ncost;
                    q.push(np);
                    // cout << "push(3):" << np << endl;
                } else if (mp[np] > ncost) {
                    mp[np] = ncost;
                }
            }
        }
        prevp = p;
        q.pop();
    }
    // print(gmin);
}

