			ans = min(ans, d * rem3 + b + rec(n / 3LL));
		else
			ans = min(ans, (3 - rem3) * d) + b + rec((n + 2LL) / 3LL);
	}

	if (n>=5)
	{
		long long rem5 = n % 5;
		if (rem5 < (5 - rem5))
			ans = min(ans, d * rem5 + c + rec(n / 5LL));
