		if (n % 2 == 0)
			ans = min(ans, a + rec(n / 2LL));
		else
		{
				ans = min(ans, d + c + rec((n + 1) / 2LL));
				ans = min(ans, d + c + rec((n) / 2LL));

		}
	}
	mm[n] = ans;
	return ans;
}

