void chemthan() {
    int test; cin >> test;
    while (test--) {
        long long n; cin >> n;
        long long a, b, c, d; cin >> a >> b >> c >> d;
        map<long long, long long> dp;
        function<long long(long long)> calc = [&] (long long n) {
            if (!n) return 0LL;
            if (dp.count(n)) return dp[n];
            long long& res = dp[n];
            res = 4 * LINF;
            if (d < 4 * LINF / abs(n)) {
                res = (long long) d * abs(n);
            }
            FOR(i, -10, 10 + 1) {
                long long nn = n + i;
                if (nn % 2 == 0) {
                    chkmin(res, calc(nn / 2) + a + d * abs(i));
                }
                if (nn % 3 == 0) {
                    chkmin(res, calc(nn / 3) + b + d * abs(i));
                }
                if (nn % 5 == 0) {
                    chkmin(res, calc(nn / 5) + c + d * abs(i));
                }
            }
            return res;
        };
        cout << calc(n) << "\n";
    }
}

