typedef long long LL;
LL n,a,b,c,d,w;
map<LL,LL> F;
void eat(LL u,LL f) {
	if(u>=w) return;
	LL g=F[u];
	if(!g||f<g) F[u]=f;
}
void magic() {
	scanf("%lld%lld%lld%lld%lld",&n,&a,&b,&c,&d);
	F.clear();
	LL h=0,t=1,ans=1LL<<60; F[n]=0;
	while(h<t) {
		LL x=F.rbegin()->first,f=F.rbegin()->second;
		w=x;
		if(1.*x*d<1e18) ans=min(ans,x*d+f);
		if(x==0) break;
		F.erase(--F.end());
		eat(x/2,a+(x%2)*d+f);
		eat(x/3,b+(x%3)*d+f);
		eat(x/5,c+(x%5)*d+f);
		eat((x+1)/2,a+(2-x%2)*d+f);
		eat((x+2)/3,b+(3-x%3)*d+f);
		eat((x+4)/5,c+(5-x%5)*d+f);
	}
	printf("%lld\n",ans);
}
