priority_queue<q_t> que;


void push(q_t q)
{
	que.push(q);
}


int pop(q_t& q)
{
	if(que.empty()) return 0;
	q=que.top();
	que.pop();
	return 1;
}


ll calc(ll n, q_t&q)
{
	ll d=llabs(n-q.v);
	ll ret=0;

	for(ll r:q.h)
	{
		ret+=d/r;
		d%=r;
		while(min_u(d, llabs(d-r)))
		{
			ret++;
		}
	}
	return ret;
}


ll calc2(ll n, int an, int bn, int cn)
{
	ll ret=0LL;
	vi nabc={0, cn, bn, an};
	vi r={0, 5, 3, 2};

	for(;;)
	{
		int m_min=999;
		int m_min_i=0;

		for(int i=1;i<=3;i++)
		{
			if(nabc[i]<=0) continue;
			if(min_u(m_min, n%r[i])) m_min_i=i;
			if(min_u(m_min, (r[i]-n%r[i])%r[i])) m_min_i=-i;
		}
		if(m_min==999) break;

		if(m_min_i>0)
		{
			ret+=m_min;
			n/=r[m_min_i];
			nabc[m_min_i]--;
		}
		else
		{
			ret+=m_min;
			n=n/r[-m_min_i]+1;
			nabc[-m_min_i]--;
		}
	}
	ret+=n;
	return ret;
}


ll solve(ll n, ll a, ll b, ll c, ll d)
{
	if(n==0LL) return 0LL;
	if(n==1LL) return d;

	q_t q={d, 1, {1}};
	vi rl={2,3,5};
	vll cl={a,b,c,d};


	ll min_cost=v_cost(n, a, d);
	ll d_max=min_cost/d;
	ll wa=1LL;
	ll ca=0LL;
	for(int i=0;;i++)
	{
		ll wb=wa;
		ll cb=ca;
		for(int j=0;;j++)
		{
			ll wc=wb;
			ll cc=cb;
			for(int k=0;;k++)
			{
				ll dcnt=calc2(n, i, j, k);
				if(dcnt<d_max)
				{
					if(min_u(min_cost, cc+dcnt*d))
					{
//						printf("update(%d,%d,%d) dcnt=%lld cost=%lld\n", i, j, k, dcnt, min_cost);
