#define MAX_N 1010101
long long extgcd(long long a, long long b, long long& x, long long& y) {
    long long d = a;
    if (b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1; y = 0;
    }
    return d;
}
long long mod_inverse(long long a, long long m) {
    long long x, y;
    if(extgcd(a, m, x, y) == 1) return (m + x % m) % m;
    else return -1;
}
vector<long long> fact(MAX_N+1, inf);
long long mod_fact(long long n, long long& e) {
    if(fact[0] == inf) {
        fact[0]=1;
        if(MAX_N != 0) fact[1]=1;
        for(ll i = 2; i <= MAX_N; ++i) {
            fact[i] = (fact[i-1] * i) % mod;
        }
    }
    e = 0;
    if(n == 0) return 1;
    long long res = mod_fact(n / mod, e);
    e += n / mod;
    if((n / mod) % 2 != 0) return (res * (mod - fact[n % mod])) % mod;
    return (res * fact[n % mod]) % mod;
}
// return nCk
long long mod_comb(long long n, long long k) {
    if(n < 0 || k < 0 || n < k) return 0;
    long long e1, e2, e3;
    long long a1 = mod_fact(n, e1), a2 = mod_fact(k, e2), a3 = mod_fact(n - k, e3);
    if(e1 > e2 + e3) return 0;
    return (a1 * mod_inverse((a2 * a3) % mod, mod)) % mod;
}

using mi = modint;

mi mod_pow(mi a, ll n) {
    mi ret = 1;
    mi tmp = a;
    while(n > 0) {
        if(n % 2) ret *= tmp;
        tmp = tmp * tmp;
        n /= 2;
    }
    return ret;
}

ll gcd(ll a, ll b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

using ld = long double;

ll n, a, b, c, d;
map<__int128, __int128> mp;

__int128 solve(__int128 m) {
    if(mp.count(m)) return mp[m];
    if(m == 0) return 0;
    __int128 ret = d * m;
    if(m % 2 == 0) {
        ret = min(ret, a + solve(m / 2));
    } else {
        if(m != 1) ret = min(ret, a + d + solve((m + 1) / 2));
        ret = min(ret, a + d + solve((m - 1) / 2));
    }
    if(m % 3 == 0 || m % 3 == 1) {
        ret = min(ret, b + d * (m % 3) + solve((m - (m % 3)) / 3));
    } else {
        ret = min(ret, b + d + solve((m + 1) / 3));
    }
    if(m % 5 == 0 || m % 5 == 1 || m % 5 == 2) {
        ret = min(ret, c + d * (m % 5) + solve((m - (m % 5)) / 5));
    } else {
        ret = min(ret, c + d * (5 - (m % 5)) + solve((m + (5 - (m % 5))) / 5));
    }
    return mp[m] = ret;
}


