 int N; 
vi cost;
vector<bool> occ;

void dfs(int curr, int c, bool first=true) {
    if (curr <= 0 || curr > N*N) return; // out of the square
    if (!first && cost[curr] <= c) return; // do not yield improvements

    cost[curr] = c;

    c += occ[curr];
    if (curr%N != 0) update(curr+1 , c, false); // cell to the right
    if (curr%N != 1) update(curr-1, c, false); // cell to the left
    update(curr+N, c, false);
    update(curr-N, c, false);
}

void solve() {
    cin >> N;
    cost = vi(N*N+1);
    occ = vector<bool>(N*N+1, true);

    // assign cost
    for (int i=0; i<N; ++i) for (int j=0; j<N; ++j) {
            cost[i*N+j+1] = min(min(i, N-i-1), min(j, N-j-1));
    }

    ll ans = 0;
    for (int i=0; i<N*N; ++i) {
        int p; cin >> p;
        occ[p] = false;
        ans += cost[p];
        dfs(i, cost[i]);
    }

    cout << ans << "\n";
}

int main () {
    solve();
    return 0;
}

