using namespace std;

ll n, a, b, c, d;
ll INF = 1e15;
unordered_map<ll, ll> memo;
ll calc(ll x) {
  if (memo.find(x) != end(memo)) {
    return memo.at(x);
  }
  ll ans = INF;
  if ((double)x * d < ans) {
    ans = x * d;
  }

  if (x % 2 == 0) {
    ans = min(ans, calc(x / 2) + a);
  } else {
    ans = min(ans, calc(x / 2) + a + d);
    ans = min(ans, calc(x / 2 + 1) + a + d);
  }
  if (x % 3 == 0) {
    ans = min(ans, calc(x / 3) + b);
  } else {
    ans = min(ans, calc(x / 3) + b + d * (x%3));
    ans = min(ans, calc(x / 3 + 1) + b + d * (3 - x%3));
  }
  if (x % 5 == 0) {
    ans = min(ans, calc(x / 5) + c);
  } else {
    ans = min(ans, calc(x / 5) + c + d * (x%5));
    ans = min(ans, calc(x / 5 + 1) + c + d * (5 - x%5));
  }
  memo[x] = ans;
  return ans;
}

void solve() {
  scan(n, a, b, c, d);
  memo.clear();
  memo[0] = 0;
  memo[1] = d;
  ll ans = calc(n);
  for (auto p : memo) {
    debug2(p.first, p.second);
  }
  print(ans);
}

int main() {
  int t;
  scan(t);
  rep (_i, t) {
    solve();
  }
  return 0;
}

