ll A,B,C,D;
map<ll,ll> memo;

ll dfs(ll x){
    if(x==0) return 0;
    if(x==1) return D;
    if(memo.count(x) ) return memo[x]; 
    ll res = 1e18+10;

    ll l2 = (x/2)*2;
    ll r2 = ((x+1)/2)*2;
    ll l3 = (x/3)*3;
    ll r3 = ((x+2)/3)*3;
    ll l5 = (x/5)*5;
    ll r5 = ((x+4)/5)*5;

    if(x < res/D) res = x*D;
    res = min(res, dfs(l2/2) + A + D * llabs(l2-x) );
    res = min(res, dfs(r2/2) + A + D * llabs(r2-x) );
    res = min(res, dfs(l3/3) + B + D * llabs(l3-x) );
    res = min(res, dfs(r3/3) + B + D * llabs(r3-x) );
    res = min(res, dfs(l5/5) + C + D * llabs(l5-x) );
    res = min(res, dfs(r5/5) + C + D * llabs(r5-x) );

    memo[x] = res;
    return res;
}

