void push(ll cost, ll from, ll to, ll div, ll divcost, priority_queue<P, vector<P>, greater<P>> &pq, map<ll, ll>& mp) {
  if (from == to) return;
  ll nc = cost + divcost + abs(from - div * to) * d;
  if (from - to <= 1000000000) nc = min(nc, cost + (from-to) * d);
  if (mp.count(to) == 1 && mp[to] <= nc) return;
  mp[to] = nc;
  pq.push(P(nc, to));
}

