I int128 read() {
	int128 x = 0, f = 1; char ch = getchar();
	while(ch < '0' || ch > '9') {if(ch == '-') f = -1; ch = getchar();}
	while(ch >= '0' && ch <= '9') x = (x << 3) + (x << 1) + (ch ^ 48), ch = getchar();
	return x * f;
}
I void ptt(int128 x) {if(x >= 10) ptt(x / 10); putchar(x % 10 + '0');}
I void put(int128 x) {x < 0 ? putchar('-'), ptt(-x) : ptt(x);}
I void pr1(int128 x) {put(x), putchar(' ');}
I void pr2(int128 x) {put(x), puts("");}

I int pow_mod(reg a, reg k) {reg ans = 1; for(; k; k >>= 1, a = (LL)a * a % mod) if(k & 1) ans = (LL)ans * a % mod; return ans;}

map<int128, int128> f;
LL A, B, C, D;

I int128 dfs(int128 n) {
	if(!n) return 0;
	if(n == 1) return D;
	if(f.count(n)) return f[n];
	int128 ans = D * n;
	reg o = n % 2;
	if(!o) ans = min(ans, dfs(n / 2) + A);
	else ans = min(ans, min(dfs((n - 1) / 2), dfs((n + 1) / 2)) + A + D);
	o = n % 3;
	if(o <= 1) ans = min(ans, dfs((n - o) / 3) + B + D * o);
	else ans = min(ans, dfs((n + 3 - o) / 3) + B + (3 - o) * D);
	o = n % 5;
	if(o <= 2) ans = min(ans, dfs((n - o) / 5) + C + D * o);
	else ans = min(ans, dfs((n - o + 5) / 5) + C + D * (5 - o));
	return f[n] = ans;
}

int main() {
	reg T = read();
	while(T--) {
		int128 n = read(); A = read(), B = read(), C = read(), D = read();
		f.clear(), pr2(dfs(n));
	}
	return 0;
}

