ll solve(ll n){
    if(n==1) return d;
    if(n==0) return 0;
    ll l1,l2,l3,r1,r2,r3;
    if(mp.count(n)) return mp[n];
    l1=n/2;
    r1=(n+1)/2;
    l2=n/3;
    r2=(n+2)/3;
    l3=n/5;
    r3=(n+4)/5;
    ll res=1e18;
    if(n<mx/d) res=n*d;
    res=min(res,solve(l1)+(n-l1*2)*d+a);
