//--------------------------------------------------------------------------------//
queue<pair<ll, ll>> q;
ll C[10];
ll N, D;

void reg(ll rest, ll cost, ll r, map<ll,ll>& mp){
    ll re = rest % r;
    // 余り0
    if(re == 0){
        if(1.0L * D * (rest - rest / r) + cost> 1e18)
            cost = cost + C[r];
        else 
            cost = min(D * (rest - rest / r) + cost, cost + C[r]);
        if(mp.find(rest/r) == mp.end()){
            mp[rest / r] = cost;
            q.emplace(rest / r, cost);
        }
        else{
            if(chmin(mp[rest/r], cost))
                q.emplace(rest / r, cost);
        }
    }
    // 0以外
    else{
        ll r1 = (rest + r)/r, r2 = rest/r, d1 = D * (r - re), d2 = D * re;

        ll c1, c2;
        if(1.0L * D * (rest - r1) > 1e18 or 1.0L * D * (rest - r2) > 1e18)
            c1 = cost + d1 + C[r], c2 = cost + d2 + C[r];
        else{
            c1 = min(cost + d1 + C[r], D * (rest - r1) + cost), c2 = min(cost + d2 + C[r], D * (rest - r2) + cost);
        }
        // err(c1, c2, d1, d2);

        if(mp.find(r1) == mp.end()){
            mp[r1] = c1;
            q.emplace(r1, c1);
        }
        else{
            if(chmin(mp[r1], c1))
                q.emplace(r1, c1);
        }
        if(mp.find(r2)==mp.end()){
            mp[r2] = c2;
            q.emplace(r2, c2);
        }
        else{
            if(chmin(mp[r2], c2))
                q.emplace(r2, c2);
        }
    }
}
int main() {
    init();
    ll T;
    cin >> T;
    while(T--){
        cin >> N >> C[2] >> C[3] >> C[5] >> D;
        map<ll, ll> mp;

        q.emplace(N, 0);
        while(!q.empty()){
            ll rest, cost;
            tie(rest, cost) = q.front(), q.pop();
            if (rest <= 1) continue;

            // 2
            reg(rest, cost, 2, mp);
            // 3
            reg(rest, cost, 3, mp);
            // 5
            reg(rest, cost, 5, mp);
        }

        cout << mp[1] + D << endl;
    }
}

