ll nextLong() { ll x; scanf("%lld", &x); return x;}


struct State {
  ll n;
  ll cost;
  bool operator < (const State& o) const {
    return cost > o.cost;
  }
};

int main2() {
  ll N = nextLong();
  ll A = nextLong();
  ll B = nextLong();
  ll C = nextLong();
  ll D = nextLong();

  priority_queue<State> pq;
  pq.push((State){ N, 0 });
  map< ll, ll > dp;

  ll ans = -1;
  while (!pq.empty()) {
    auto s = pq.top(); pq.pop();

    if (s.n == 0) {
      ans = s.cost;
      break;
    }

    const ll n = s.n;

    vector<State> nxts;
    if ((double)n * (double)D <= 1e17) {
      State nxt = { 0, s.cost + n * D };
      nxts.push_back(nxt);
    }

    {
      ll m = n / 2 * 2;
      nxts.push_back((State){ m/2, s.cost + abs(n-m) * D + A });
    }
    {
      ll m = (n + 1) / 2 * 2;
      nxts.push_back((State){ m/2, s.cost + abs(n-m) * D + A });
    }

    {
      ll m = n / 3 * 3;
      nxts.push_back((State){ m/3, s.cost + abs(n-m) * D + B });
    }
    {
      ll m = (n + 2) / 3 * 3;
      nxts.push_back((State){ m/3, s.cost + abs(n-m) * D + B });
    }


    {
      ll m = n / 5 * 5;
      nxts.push_back((State){ m/5, s.cost + abs(n-m) * D + C });
    }
    {
      ll m = (n + 4) / 5 * 5;
      nxts.push_back((State){ m/5, s.cost + abs(n-m) * D + C });
    }


    for (State nxt : nxts) {
      if (dp.count(nxt.n) == 0 || dp[nxt.n] > nxt.cost) {
        dp[nxt.n] = nxt.cost;
        pq.push(nxt);
      }
    }

  }


  cout << ans << endl;

  return 0;
}

int main() {
  int t = nextLong();
  while (t--)
    main2();
  return 0;
}

