vector<ll> dijkstra(const graph& g, ll n, ll v) {
    priority_queue<pll, vector<pll>, greater<pll>> q;
    vector<bool> seen(n);
    vector<ll> d(n);
    vector<ll> prev(n);

    rep(i, n) {
        seen[i] = false;
        d[i] = INF;
        prev[i] = -1;
    }
    d[v] = 0;
    q.push(mp(0, 0));

    while(!q.empty()) {
        ll v = q.top().second;
        seen[v] = true;
        q.pop();
        for(auto i : g[v]) {
            if(seen[i]) continue;
            if(d[i] > d[v] + 1) {
                d[i] = d[v] + 1;
                prev[i] = v;
                q.push(mp(d[i], i));
            }
        }
    }
    return prev;
}

