LL A, B, C, D, N, M;
constexpr LL inf = 1e18;
LL dp(LL N){
    if(mp.count(N)) return mp[N];
    LL& res = mp[N];
    res = inf;
    if(N <= inf / D) res = N * D;
    LL M = N / 2 * 2;
    if(N == M){
        if(A < res) res = min(res, dp(N / 2) + A);
    }
    else{
        if((N - M) * D + A < res) 
           res = min(res, (N - M) * D + dp(M / 2) + A);
        M += 2;
        if((M - N) * D + A < res)
            res = min(res, (M - N) * D + dp(M / 2) + A);
    }
    M = N / 3 * 3;
    if(N == M){
        if(B < res) res = min(res, dp(N / 3) + B);
        res = min(res, dp(N / 3) + B);
    }
    else{
        if((N - M) * D + B < res) 
            res = min(res, (N - M) * D + dp(M / 3) + B);
        M += 3;
        if((M - N) * D + B < res)
            res = min(res, (M - N) * D + dp(M / 3) + B);
    }
    M = N / 5 * 5;
    if(N == M){
        if(C < res) res = min(res, dp(N / 5) + C);
    }
    else{
        if((N - M) * D + C < res) 
            res = min(res, (N - M) * D + dp(M / 5) + C);
        M += 5;
        if((M - N) * D + C < res)
            res = min(res, (M - N) * D + dp(M / 5) + C);
    }
    return res;
}
