void push(lli v, lli cv)
{
    lli &k = cost[v];
    if(k && k <= cv) return;
    pq.push_back({cv,v});
    std::push_heap(pq.begin(),pq.end(),std::greater<std::pair<lli,lli>>());
    k = cv;
}

int main()
