        push(n,0);
        lli ans;
        while(!pq.empty())
        {
            lli u=pq.front().sd, cu=pq.front().ft;
            std::pop_heap(pq.begin(),pq.end(),std::greater<std::pair<lli,lli>>()), pq.pop_back();
            dbg_pri("poi 1: %lld %lld\n",u,cu);
            if(u==0)
            {
                ans = cu;
