map <long long, long long> dp;

long long dfs(long long n) {
    if (dp[n]) return dp[n]; 
    if (n == 0) return 0; 
    dp[n] = 1e18;  
    if (n < dp[n] / d) 
        dp[n] = min(dp[n], n * d);
    if (n % 2 == 0) {
        dp[n] = min(dp[n], dfs(n / 2) + a); 
    }
    else {
        dp[n] = min(dp[n], dfs((n + 1) / 2) + a + d); 
        dp[n] = min(dp[n], dfs((n - 1) / 2) + a + d); 
    }
    if (n % 3 == 0) {
        dp[n] = min(dp[n], dfs(n / 3) + b); 
    }
    else {
        dp[n] = min(dp[n], dfs(n / 3) + b + d * (n % 3)); 
        dp[n] = min(dp[n], dfs(n / 3 + 1) + b + d * (3 - n % 3)); 
    }
    if (n % 5 == 0) {
        dp[n] = min(dp[n], dfs(n / 5) + c); 
    }
    else {
        dp[n] = min(dp[n], dfs(n / 5) + c + d * (n % 5)); 
        dp[n] = min(dp[n], dfs(n / 5 + 1) + c + d * (5 - n % 5)); 
    }
    return dp[n]; 
}
