    ll n,a,b,c,d; cin >> n >> a >> b >> c >> d;
    map<ll,ll> m;
    auto dfs = [&](ll here, auto &dfs)->ll{
        if(m[here]!=0) return m[here];
        if(here<=0) return 0;
        if(here==1) return d;
        ll t = LNF;
        if(here<LNF/d) t = here*d;
        chmin(t,a+d*(here%2ll)+dfs(here/2ll,dfs));
        if(here%2==1){
            chmin(t,a+d+dfs((here+1ll)/2ll,dfs));
        }
        chmin(t,b+d*(here%3ll)+dfs(here/3ll,dfs));
        if(here%3!=0){
            chmin(t,b+d*(3ll-here%3ll)+dfs((here+2ll)/3ll,dfs));
        }
        chmin(t,c+d*(here%5ll)+dfs(here/5ll,dfs));
        if(here%5!=0){
            chmin(t,c+d*(5ll-here%5ll)+dfs((here+4ll)/5ll,dfs));
        }
        m[here] = t;
        return t;
    };
    dfs(n,dfs);
    cout << m[n] << endl;
    return 0;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int t; cin >> t;
    rep(_,0,t){
        solve();
    }
}

