map<long long, long long> m;

long long dp(long long x){
    if(x == 0){return 0;}
    if(x == 1){return D;}
    if(m.find(x) != m.end()){ return m[x]; }

    long long ans = 1LL << 61;
    if((double)x*D < 1.02e18){
        ans = min(ans, x*D);
    }
    long long prevMul2 = x/2*2;

    if((double)(x-x/2)*D < 1.03e9){
        ans = min(ans, D*abs(prevMul2-x)+min(A, (x-x/2)*D) + dp(x/2));
        if(prevMul2 != x){
            ans = min(ans, D*abs(prevMul2+2-x)+min(A, (x-x/2)*D) + dp(1+x/2));
        }
    }else{
        ans = min(ans, D*abs(prevMul2-x)+A + dp(x/2));
        if(prevMul2 != x){
            ans = min(ans, D*abs(prevMul2+2-x)+A + dp(1+x/2));
        }
    }

    long long prevMul3 = x/3*3;
    if((double)(x-x/3)*D < 1.03e9){
        ans = min(ans, D*abs(prevMul3-x)+min(B, (x-x/3)*D) + dp(x/3));
        if(prevMul3 != x){
            ans = min(ans, D*abs(prevMul3+3-x)+min(B, (x-x/3)*D) + dp(1+x/3));
        }
    }else{
        ans = min(ans, D*abs(prevMul3-x)+B + dp(x/3));
        if(prevMul3 != x){
            ans = min(ans, D*abs(prevMul3+3-x)+B + dp(1+x/3));
        }
    }

    long long prevMul5 = x/5*5;
    if((double)(x-x/5)*D < 1.03e9){
        ans = min(ans, D*abs(prevMul5-x)+min(C, (x-x/5)*D) + dp(x/5));
        if(prevMul5 != x){
            ans = min(ans, D*abs(prevMul5+5-x)+min(C, (x-x/5)*D) + dp(1+x/5));
        }
    }else{
        ans = min(ans, D*abs(prevMul5-x)+C + dp(x/5));
        if(prevMul5 != x){
            ans = min(ans, D*abs(prevMul5+5-x)+C + dp(1+x/5));
        }
    }

    return m[x] = ans;
}

