	ll ans=mult(n,d);
	if(n/2+1<n) ans=min(ans,solve(n/2+1)+a+(2-n%2)*d);
	if(n/2>0) ans=min(ans,solve(n/2)+a+(n%2)*d);
	if(n/3+1<n) ans=min(ans,solve(n/3+1)+b+(3-n%3)*d);
