int64_t anss = 0;
int64_t primeFactorization(int64_t a, int64_t A, int64_t B, int64_t C, int64_t D){ //素因数分解を出力するプログラム
    int64_t i,sq;
    if(a%2==0){ //偶数の場合
        anss += A;
        return primeFactorization(a/2, A, B, C, D); //2で割った値で再帰
    }
    sq = a/2+1;
    for(i=3;i<=sq;i+=2){ //3以上√a以下の奇数の場合
        if(a%i==0){
            if (i == 3)
            {
                anss += B;
                return primeFactorization(a/i, A, B, C, D); //割れた値で再帰
            }

            else if (i == 5)
            {
                anss += C;
                return primeFactorization(a/i, A, B, C, D); //割れた値で再帰
            }

            else
            {
                anss += D;
                return primeFactorization(a-1, A, B, C, D);
            }


        }
    }
    if (a != 1)
    {
        if (a == 5)
        {
            anss += C;
            return primeFactorization(a/5, A, B, C, D);
        }

        if (a == 3)
        {
            anss += B;
            return primeFactorization(a/3, A, B, C, D);
        }


        anss += D;
        return primeFactorization(a-1, A, B, C, D);
    }

    //偶数でも3以上√a以下の奇数の場合でも割り切れない場合
    if(a==1){ //aが1でないなら、a自身は素数
        anss += D;
    }
    return anss;
}

