long long A, B, C, D, N;
const long long INF = 1LL << 60;
unordered_map < long long, long long > mp;

int modul (int x)
{
    if (x < 0)
        return -x;
    return x;
}

const int K = 100;

long long solve (long long N)
{
    if (mp.count (N))
        return mp[N];
    long long best = INF;
    if (N < 100)
        best = 1LL * N * D;
    for (int i=-4; i<=4; i++)
        if (N - i >= 0)
        {
            long long M = N - i, xtra = 1LL * D * modul (i);
            if (M % 2 == 0 && -1 <= i && i <= 1)
            {
                long long curr = solve (M / 2) + A + xtra;
                if (curr < best)
                    best = curr;
            }
            if (M % 3 == 0 && -2 <= i && i <= 2)
            {
                long long curr = solve (M / 3) + B + xtra;
                if (curr < best)
                    best = curr;
            }
            if (M % 5 == 0)
            {
                long long curr = solve (M / 5) + C + xtra;
                if (curr < best)
                    best = curr;
            }
        }
    mp[N] = best;
    return best;
}

