  if (mp[n] > 0) return co + mp[n];
  ll ac, bc, cc, dc;
  if (n % 2 == 0) {
    if (n < a / d) {
      ac = n * d;
    } else {
      ac = f(n / 2, co) + a;
    }
  } else {
    if (n - 1 < a / d) {
      ac = n * d;
    } else {
      ac = f((n - 1) / 2, co) + a + d;
    }
  }
  if (n % 3 == 0) {
    if (n < b / d) {
      bc = n * d;
    } else {
      bc = f(n / 3, co) + b;
    }
  } else if (n % 3 == 1) {
    if (n - 1 < b / d) {
      bc = n * d;
    } else {
      bc = f((n - 1) / 3, co) + b + d;
    }
  } else {
    if (n - 2 < b / d) {
      bc = n * d;
    } else {
      bc = f((n + 1) / 3, co) + b + d;
    }
  }
  if (n % 5 == 0) {
    if (n < c / d) {
      cc = n * d;
    } else {
      cc = f(n / 5, co) + c;
    }
  } else if (n % 5 == 1) {
    if (n - 1 < c / d) {
      cc = n * d;
    } else {
      cc = f((n - 1) / 5, co) + c + d;
    }
  } else if (n % 5 == 2) {
    if (n - 2 < c / d) {
      cc = n * d;
    } else {
      cc = f((n - 2) / 5, co) + c + d * 2;
    }
  } else if (n % 5 == 3) {
    if (n - 3 < c / d) {
      cc = n * d;
    } else {
      cc = f((n + 2) / 5, co) + c + d * 2;
    }
  } else {
    if (n - 4 < c / d) {
      cc = n * d;
    } else {
      cc = f((n + 1) / 5, co) + c + d;
    }
  }
  ll ans = min(ac, bc);
  ans = min(ans, cc);
  if (n < a * 2 && n < b * 3 && n < c * 5) {
  // // if (n < a / d || n < b / d && n < c / d) {
    dc = n * d;
    ans = min(ans, dc);
  }
  mp[n] = ans;
  return co + ans;
}

