map<int, int> memo;
int A, B, C, D;
int calcans(int N){
    //debug(N);
    if(N == 0) return 0;
    if(N == 1) return D;
    if(memo.count(N)) return memo[N];

    int ans = INF;
    if((double)N * D < INF) Min(ans, N * D);

    int r2 = N % 2;
    if(r2){
        Min(ans, calcans((N - r2) / 2) + A + r2 * D);
        Min(ans, calcans((N + 2 - r2) / 2) + A + (2 - r2) * D);
    }else Min(ans, calcans(N / 2) + A);

    int r3 = N % 3;
    if(r3){
        Min(ans, calcans((N - r3) / 3) + B + r3 * D);
        Min(ans, calcans((N + 3 - r3) / 3) + B + (3 - r3) * D);
    }else Min(ans, calcans(N / 3) + B);

    int r5 = N % 5;
    if(r5){
        Min(ans, calcans((N - r5) / 5) + C + r5 * D);
        Min(ans, calcans((N + 5 - r5) / 5) + C + (5 - r5) * D);
    }else Min(ans, calcans(N / 5) + C);

    memo[N] = ans;

    return ans;
}

signed main(){

    int T; cin >> T;

    REP(q, T){
        int N; cin >> N >> A >> B >> C >> D;
        memo.erase(all(memo));
        int ans = calcans(N);
        Out(ans);
    }

    return 0;
}

#include<bits/stdc++.h>
#define INF 1000000000000000000LL
using namespace std;
typedef long long ll;
map<ll, ll> score;
ll T, N, A, B, C, D;

ll calc(ll N) {
  if(N==0) return 0;
  if(N==1) return D;
  if(N==2) return min(2LL*D, D + A);
  if(score[N]) return score[N];

  ll ret  = INF;
  if(N  <= INF / D) {
    ret = N*D;
  }

  ret = min(ret, 1LL*(N%2) * D + A + calc (N/2));
  if(N%2) {
    ret = min(ret, 1LL*(2 - N%2) * D + A + calc (N/2 + 1));
  }

  ret = min(ret, 1LL* (N%3) * D + B + calc (N/3));
  if(N%3) {
    ret = min(ret, 1LL*(3 - N%3) * D + B + calc (N/3+1));
  }

  ret = min(ret, 1LL*(N%5) * D + C + calc (N/5));
  if(N%5) {
    ret = min(ret, 1LL* (5 - N%5) * D + C + calc (N/5+1));
  }
  score[N] = ret;
  //cout<<N<<" "<<score[N]<<endl;
  return ret;
} 

int main() {
  cin>>T;
  while(T--) {
    score.clear();
    cin>>N>>A>>B>>C>>D;
    cout<<calc(N)<<endl;
  }
  return 0;
}

