ll N, A, B, C, D;
unordered_map<ll, ll> mp;


ll dfs(ll x){
	if (mp.count(x)==1) return mp[x];

	ll val=INF;
	if (x*(dd)D<INF) chmin(val, x*D);
	//5で割る
	{
		ll v;
		if (x%5>=3) v=CEIL(x, 5);
		else        v=x/5;
		ll c = abs(x-v*5)*D+C;
		chmin(val, dfs(v)+c);
	}
	//3で割る
	{
		ll v;
		if (x%3>=2) v=CEIL(x, 3);
		else        v=x/3;
		ll c = abs(x-v*3)*D+B;
		chmin(val, dfs(v)+c);
	}
	//2で割る
	{
		ll v;
		v=x/2;
		ll c = (x%2)*D+A;
		chmin(val, dfs(v)+c);
		if (x%2==1){
			v=x/2+1;
			chmin(val, dfs(v)+c);
		}
	}

	mp[x]=val;
	return mp[x];
}

void solve()
{
	cin >> N >> A >> B >> C >> D;
	mp.clear();

	mp[0]=0;
	mp[1]=D;
	mp[2]=min(2*D, D+A);
	ll ans=dfs(N);
	cout << ans << '\n';
	EACH(e, mp){
		cout<<e.first<<" "<<e.second<<endl;
	}
}

