}

inline void gao(ll x,ll y)
{
	if (!mp.count(x)) mp[x]=y;
	else mp[x]=min(mp[x],y);
}

inline void work()
{
	n=rd();a=rd();b=rd();c=rd();d=rd();
	mp.clear();mp[n]=0;
	ll ans=inf;
	while (233)
	{
		map<ll,ll>::iterator it=mp.end();it--;
		ll x=it->first,y=it->second;
		ans=min(ans,y+x*d);
		if (!x) break;
		if (x%2==0) gao(x/2,y+a);
		else gao(x/2,y+a+d),gao(x/2+1,y+a+d);
