int soinsucheck(int test){
    while(test % 5 == 0){
        test = test / 5;
    }
    while(test % 3 == 0){
        test = test / 3;
    }
    while(test % 2 == 0){
        test = test / 2;
    }

    return test;
}

int soinsu(int test, int a, int b, int c){
    int acount = 0;
    int bcount = 0;
    int ccount = 0;

    while(test % 5 == 0){
        test = test / 5;
        ccount++;
    }
    while(test % 3 == 0){
        test = test / 3;
        bcount++;
    }
    while(test % 2 == 0){
        test = test / 2;
        acount++;
    }

    return a*acount + b*bcount + c*ccount;
}

