ll solve(ll n) {
	if (!memo.count(n)) {
		if (n <= 1) {
			memo[n] = n * c1;
		} else {
			ll res = 7e18;
			if (n <= res / c1) setmin(res, c1 * n);
			setmin(res, solve(n / 2) + c2 + c1 * (n % 2));
			setmin(res, solve(n / 3) + c3 + c1 * (n % 3));
			setmin(res, solve(n / 5) + c5 + c1 * (n % 5));
