			setmin(res, solve(n / 3 + 1) + c3 + c1 * (3 - n % 3));
			setmin(res, solve(n / 5 + 1) + c5 + c1 * (5 - n % 5));
			memo[n] = res;
		}
	}
	return memo[n];
}

