long long m[] = {2, 3, 5};
long long cst[3], d;
map<long long, long long> dp;

long long go(long long n) {
	if (n == 0) return 0;
	if (n == 1) return d;
	if (dp.find(n) != dp.end()) return dp[n];

	long long ans = (n <= 1000000000 ? n*d : 1e18);
	long long nxt, tmp;

	for (int i = 0; i < 3; i++) {
		nxt = n, tmp = 0;
		while (nxt % m[i]) {nxt--; tmp += d;}	
		ans = min(ans, tmp + cst[i] + go(nxt/m[i]));

		nxt = n, tmp = 0;
		while (nxt % m[i]) {nxt++; tmp += d;}	
		ans = min(ans, tmp + cst[i] + go(nxt/m[i]));
	}

	return dp[n] = ans;
}

