	ll res = (d < 2 * UPPER / n) ? d * n : 2 * UPPER; // ここから操作dのみ行ったときのコストか2*10^18の小さいほう
	chmin(res, dp(n / 2, a, b, c, d) + a + f2 * d);
	chmin(res, dp((n + 1) / 2, a, b, c, d) + a + c2 * d);
	chmin(res, dp(n / 3, a, b, c, d) + b + f3 * d);
	chmin(res, dp((n + 2) / 3, a, b, c, d) + b + c3 * d);
	chmin(res, dp(n / 5, a, b, c, d) + c + f5 * d);
	chmin(res, dp((n + 4) / 5, a, b, c, d) + c + c5 * d);
	mp[n] = res;
	return mp[n];
}
