ll solve(ll n)
{
    if (!n)
        return 0;
    if (n == 1)
        return D;
    if (cache.find(n) != cache.end())
        return cache[n];
    ll ans = LONG_LONG_MAX;
    ll c2s = solve(n / 2), c2c = solve(my_ceil(n, 2)), c3s = solve(n / 3), c3c = solve(my_ceil(n, 3)), c5s = solve(n / 5), c5c = solve(my_ceil(n, 5));
    if (n > 2e9)
    {
        if (n % 2 == 0)
            ans = min(ans, c2s + A);
        else
            ans = min(ans, min(c2s + D + A, c2c + D + A));
        if (n % 3 == 0)
            ans = min(ans, c3s + B);
        else
            ans = min(ans, min(c3s + D * (n % 3) + B, c3c + D * (3 - n % 3) + B));
        if (n % 5 == 0)
            ans = min(ans, c5s + C);
        else
            ans = min(ans, min(c5s + D * (n % 5) + C, c5c + D * (5 - n % 5) + C));
    }
    else
    {
        if (n % 2 == 0)
            ans = min(ans, c2s + min(A, D * (n / 2)));
        else
            ans = min(ans, min(c2s + D + min(A, D * (n / 2)), c2c + D + min(A, D * (my_ceil(n, 2)))));
        if (n % 3 == 0)
            ans = min(ans, c3s + min(B, D * (2 * n / 3)));
        else
            ans = min(ans, min(c3s + D * (n % 3) + min(B, 2 * D * (n / 3)), c3c + D * (3 - n % 3) + min(B, 2 * D * (my_ceil(n, 3)))));
        if (n % 5 == 0)
            ans = min(ans, c5s + min(C, D * (4 * n / 5)));
        else
            ans = min(ans, min(c5s + D * (n % 5) + min(C, 4 * D * (n / 5)), c5c + D * (5 - n % 5) + min(C, 4 * D * (my_ceil(n, 5)))));
    }
    return cache[n] = ans;
}

