long long find(long long n, map<long long, long long> &memo)
{
  long long w = 9e18;
  if(n < 9e18 / cost[1])
    w = n * cost[1];

  if(n == 0)
    return 0;

  if(n == 1)
    return cost[1];

  if(memo[n])
    return memo[n];

  for(long long i = 1; i < 6; i++)
  {
    if(i == 2 || i == 3 || i == 5)
    {
      if(n % i == 0)
      {
        w = min(w, cost[i] + find(n / i, memo));
      }
      else
      {
        int rem = n % i;
        long long tmp = rem * cost[1];
        long long tn = n - rem;
        w = min(w, tmp + cost[i] + find(tn / i, memo));

        rem = i - rem;
        tmp = rem * cost[1];
        tn = n + rem;
        w = min(w, tmp + cost[i] + find(tn / i, memo));
      }
    }
  }

  memo[n] = w;
  return w;
}

