    ans = min(ans, f(x / 5, a, b, c, d, memo) + c + (x - x / 5 * 5) * d);
    ans = min(ans, f((x + 4) / 5, a, b, c, d, memo) + c + ((x + 4) / 5 * 5 - x) * d);
    return memo[x] = ans;
}

