const ll INF = 1LL << 50;

map<ll, ll> memo;
ll a, b, c, d;
ll f(ll n) {
  if (n == 0) return 0;  
  if (n == 1) return d;

  if(memo.count(n)) return memo[n];
  ll ret = INF;
  if (n < ret/d) ret = n*d;
  if (n % 2 == 0) {
    chmin(ret, a + f(n / 2));
  } else {
    chmin(ret, a + d + f((n + 1)/2));
    chmin(ret, a + d + f((n - 1)/2));
  }
  if (n % 3 == 0)
    chmin(ret, b + f(n / 3));
  else {
    ll r = n % 3;
    chmin(ret, b + d * (3 - r) + f((n + 3 - r) / 3));
    if (n - r >= 0) chmin(ret, b + d * r + f((n - r) / 3));
  }
  if (n % 5 == 0)
    chmin(ret, c + f(n / 5));
  else {
    ll r = n % 5;
    chmin(ret, c + d * (5 - r) + f((n + 5 - r) / 5));
    if (n - r >= 0) chmin(ret, c + d * r + f((n - r) / 5));
  }
  return memo[n] = ret;
}

