		get(N, A, B);
		get(C, D);

		LLONG cost[6] = { 0 };
		cost[2] = A;
		cost[3] = B;
		cost[5] = C;

		LLONG ans = 1e18;
		std::priority_queue<LPair, std::vector<LPair>, std::greater<LPair>> que;
		std::map<LLONG, LLONG> memo;

		auto insert = [&](LLONG v, LLONG n) {
			if (v < ans && (!memo.count(n) || v < memo[n])) {
				que.emplace(v, n);
				memo[n] = v;
			}
		};

		que.emplace(0, N);
		while (!que.empty()) {
			auto lp = que.top(); que.pop();
			LLONG val = lp.first, num = lp.second;

			if (val >= ans) break;
			if (num <= 2e18 / D) ans = std::min(ans, val + num * D);

			for (int d : {2, 3, 5}) {
				int r = num % d;
				LLONG val2 = val + r * D + cost[d];
				insert(val2, num / d);
				val2 = val + (d - r) * D + cost[d];
				insert(val2, num / d + 1);
			}
		}
		printf("%lld\n", ans);
	}
}

