    // dp[x] = min(dp[x], fun(x-1)+d);
    int tmp = inf;
    if(inf/d > (x-x/2))tmp = d*(x-x/2);
    dp[x] = min(dp[x], fun(x/2)+min(a+(x-x/2*2)*d, tmp));
    tmp = inf;
    if(inf/d > (x-x/3))tmp = d*(x-x/3);
    dp[x] = min(dp[x], fun(x/3)+min(b+min((x-x/3*3)*d, ((x/3+1)*3-x)*d+d), tmp));
