void dijkstra(){
    dis[N]=0;
    priority_queue<pair<ll,ll>,vector<pair<ll,ll>>,greater<pair<ll,ll>>> PQ;
    y={A,B,C};

    PQ.push(make_pair(0LL,N));
    while(!PQ.empty()){
        ll a=PQ.top().first;
        ll b=PQ.top().second;
        PQ.pop();
        if(dis[b]<a) continue;

        for(int i=0;i<3;i++){
            if(b%x[i]==0){
                if(dis.count(b/x[i])==0||dis[b/x[i]]>a+y[i]){
                    dis[b/x[i]]=a+y[i];
                    PQ.push(mp(dis[b/x[i]],b/x[i]));
                }
            }else{
                ll to=b/x[i];
                if(to>=0){
                    if(dis.count(to)==0||dis[to]>a+y[i]+D*(b-to*x[i])){
                        dis[to]=a+y[i]+D*(b-to*x[i]);
                        PQ.push(mp(dis[to],to));
                    }
                }
                to++;
                if(to>=0){
                    if(dis.count(to)==0||dis[to]>a+y[i]+D*(to*x[i]-b)){
                        dis[to]=a+y[i]+D*(to*x[i]-b);
                        PQ.push(mp(dis[to],to));
                    }
                }
            }
        }

        if(log10(D)+log10(b)<=18.0){
            if(dis.count(0)==0) dis[0]=a+D*b;
            else chmin(dis[0],a+D*b);
        }
    }
    return;
}//a,dが長さ

