        next_lst.push_back(2 * v);
        flag = true;
      }
      if (mp.count(3 * v)) {
        if (mp[v] + b < mp[3 * v] and mp[v] + b < min_cost) {
          mp[3 * v] = mp[v] + b;
          next_lst.push_back(3 * v);
          flag = true;
          if (3 * v == n) min_cost = min_ll(min_cost, mp[v] + b);
        }
      } else if (mp[v] + b < min_cost) {
        mp[3 * v] = mp[v] + b;
        next_lst.push_back(3 * v);
        flag = true;
      }
      if (mp.count(5 * v)) {
        if (mp[v] + c < mp[5 * v] and mp[v] + c < min_cost) {
          mp[5 * v] = mp[v] + c;
          next_lst.push_back(5 * v);
          flag = true;
          if (5 * v == n) min_cost = min_ll(min_cost, mp[v] + c);
        }
      } else if (mp[v] + c < min_cost) {
        mp[5 * v] = mp[v] + c;
        next_lst.push_back(5 * v);
        flag = true;
      }
      if (mp.count(v - 1)) {
        if (mp[v] + d < mp[v - 1] and mp[v] + d < min_cost) {
          mp[v - 1] = mp[v] + d;
          next_lst.push_back(v - 1);
          flag = true;
          if (v - 1 == n) min_cost = min_ll(min_cost, mp[v] + d);
        }
      } else if (mp[v] + d < min_cost) {
        mp[v - 1] = mp[v] + d;
        next_lst.push_back(v - 1);
        flag = true;
      }
      if (mp.count(v + 1)) {
        if (mp[v] + d < mp[v + 1] and mp[v] + d < min_cost) {
          mp[v + 1] = mp[v] + d;
          next_lst.push_back(v + 1);
          flag = true;
          if (v + 1 == n) min_cost = min_ll(min_cost, mp[v] + d);
        }
      } else if (mp[v] + d < min_cost) {
        mp[v + 1] = mp[v] + d;
        next_lst.push_back(v + 1);
        flag = true;
      }
    }
    lst = next_lst;
  }
  return min_cost;
}

