sll parent[301910], size[301910];
void init (sll n) {
	for (sll i = 0; i < n; i++) {
		parent[i] = i;
		size[i] = 1;
	}
}
sll find (ull x) {
	if (parent[x] == x) return x;
	return parent[x] = find(parent[x]);
}
bool unite (sll v, sll u) {
	v = find(v);
	u = find(u);

	if (v == u) return false;

	if (size[v] < size[u]) {
		ull tmp = v;
		v = u;
		u = tmp;
	}
	size[v] += size[u];
	parent[u] = v;
	return true;
}

