    return;
  }

  if(ans<=cost)return;

  solve((now )/5,cost+c + d*(now%5));

  if(ans<=cost)return;

  solve((now)/3,cost+b+d*(now%3));

  if(ans<=cost)return;
  solve((now)/2,cost+a+d*(now%2));
  if(ans<=cost)return;
  if(now%5!=0){

  solve((now +4)/5,cost+c + d*(5-now%5));
  }

  if(ans<=cost)return;
  if(now%3!=0){

  solve((now+2)/3,cost+b+d*(3-now%3));
  }

  if(ans<=cost)return;
  if(now%2!=0){

  solve((now+1)/2,cost+a+d*(2-now%2));
  }
  if(ans<=cost)return;
  ans=min(ans,now*d);
  return;
}
