const ll INF = 1000000000000000000LL;

using namespace std;

ll N, A, B, C, D;
map<ll, ll> memo;

ll rec(ll n) {
	if (n <= 1){
		return memo[n] = n * D;
	}
	if (memo[n] != 0) {
		return memo[n];
	}

	ll ret = INF;
	if (n <= INF / D){
		ret = n * D;
	}
	ll ref[3] = {2, 3, 5};
	ll add[3] = {A, B, C};
	for (int ii = 0; ii < 3; ++ii){
		ll q = n / ref[ii];
		ll r = n % ref[ii];
		if (r == 0){
			ret = min(ret, rec(q) + add[ii]);
		} else {
			ret = min(ret, rec(q) + add[ii] + r * D);
			ret = min(ret, rec(q+1) + add[ii] + (ref[ii] - r) * D);
		}
	}

	return memo[n] = ret;
}

int main() {
	int T;
	cin >> T;

	for (int ii = 0; ii < T; ++ii){
		cin >> N >> A >> B >> C >> D;

		memo.clear();
		ll ans = rec(N);
		cout << ans << "\n";
	}

	return 0;
}

