map<ll, ll> ps2cost;
priority_queue<pl> newlydef;//-cost,position

void addcost(ll posi, ll cost) {
    if (ps2cost.count(posi) == 0) {
        ps2cost[posi] = cost;
        newlydef.emplace(mp(-cost, -posi));
    } else {
        if (ckmin(ps2cost[posi], cost))
            newlydef.emplace(mp(-cost, -posi));
    }

}

void solve(int ti) {
    ll n, a, b, c, d;
    { re(n, a, b, c, d); }
    //bfs
    ps2cost.clear();
    while (not newlydef.empty())
        newlydef.pop();
//    auto &nd = newlydef;
    addcost(n, 0);
    vpl modcosts = {{2, a},
                    {3, b},
                    {5, c}};
    set<ll> seen_as_top;
    while (newlydef.top().second != 0) {
        auto top = newlydef.top();
        newlydef.pop();
        ll cost = -top.f, posi = -top.s;
        if (ps2cost[posi] == cost and seen_as_top.count(posi) == 0) {
            seen_as_top.emplace(posi);
//            cerr << top.f << ' ' << top.s << endl;
            trav(modcost, modcosts) {
                if (posi % modcost.first == 0)
                    addcost(posi / modcost.first, cost + modcost.second);
                else {
                    ll modulo = (posi % modcost.first);
                    addcost(posi + (modcost.first - modulo), cost + d * (modcost.first - modulo));
                    addcost(posi - modulo, cost + d * modulo);
                }
            }
        }
    }
    ps(-newlydef.top().first);
}

