        }
        int64_t nn, aa, bb, cc, count, N;
        count = 0;
        for(int64_t i=-pow(10,3);i<pow(10,3);i++){
            nn = n + i;

            if(nn<0){
                continue;
            }else if(nn%2!=0 && nn%3!=0 && nn%5!=0){
                continue;
            }


            aa = factorization(nn,2);
            bb = factorization(nn,3);
            cc = factorization(nn,5);

            N = aa*a + bb*b + cc*c + (abs(i)+1)*d;

            if(count == 0){
                minimum = N;
            }else{
                minimum = min(N,minimum);
            }
        }
        minimum = min(minimum,d*n);
        cout << minimum << endl;
    }

    return 0;
}

