		ret=n*d;
	int t=n%5;
	if(t<=2)
		ret=min(ret,dfs((n-t)/5)+c+t*d);
	else 
		ret=min(ret,dfs((n+5-t)/5)+c+(5-t)*d);
	t=n%3;
	if(t<=1)
		ret=min(ret,dfs((n-t)/3)+b+t*d);
	else
		ret=min(ret,dfs((n+3-t)/3)+b+(3-t)*d);
	t=n%2;
	if(t==0) ret=min(ret,dfs(n/2)+a);
	else
		ret=min(ret,min(dfs((n-1)/2),dfs((n+1)/2))+a+d);
	mp[n]=ret;
//	printf("[%lld %lld]\n",n,ret);
	return ret;
}
