    mins(add, f((n - 1) / 3, co) + b + d);
    mins(add, f((n + 2) / 3, co) + b + d * 2);
  } else {
    mins(add, f((n - 2) / 3, co) + b + d * 2);
    mins(add, f((n + 1) / 3, co) + b + d);
  }
  if (n % 5 == 0) {
    mins(add, f(n / 5, co) + c);
  } else if (n % 5 == 1) {
    mins(add, f((n - 1) / 5, co) + c + d);
    mins(add, f((n + 4) / 5, co) + c + d * 4);
  } else if (n % 5 == 2) {
    mins(add, f((n - 2) / 5, co) + c + d * 2);
    mins(add, f((n + 3) / 5, co) + c + d * 3);
  } else if (n % 5 == 3) {
    mins(add, f((n - 3) / 5, co) + c + d * 3);
    mins(add, f((n + 2) / 5, co) + c + d * 2);
  } else {
    mins(add, f((n - 4) / 5, co) + c + d * 4);
    mins(add, f((n + 1) / 5, co) + c + d);
