long long dfs(long long N) {
    if (N == 0) return 0;
    if (N == 1) return D;
    if (memo.count(N)) return memo[N];
    long long l2 = (N / 2)  * 2;
    long long r2 = ((N + 1) / 2) * 2;
    long long l3 = (N / 3)  * 3;
    long long r3 = ((N + 2) / 3) * 3;
    long long l5 = (N / 5)  * 5;
    long long r5 = ((N + 4) / 5) * 5;

    long long res = 1e18;
    if (N < res / D) res = N * D;
    res = min(res, llabs(l2 - N) * D + A + dfs(l2 / 2));
    res = min(res, llabs(r2 - N) * D + A + dfs(r2 / 2));

    res = min(res, llabs(l3 - N) * D + B + dfs(l3 / 3));
    res = min(res, llabs(r3 - N) * D + B + dfs(r3 / 3));

    res = min(res, llabs(l5 - N) * D + C + dfs(l5 / 5));
    res = min(res, llabs(r5 - N) * D + C + dfs(r5 / 5));

    memo[N] = res;

    return res;
}

