struct Branch
{
	long long to, coins;
};

struct Node
{
	long long coins;
	Node() :coins(1LL << 60) {}
};

int main()
{
	auto& in = cin;
	int T;
	long long N, A, B, C, D;
	in >> T;
	for (int t = 0; t < T; ++t) {
		in >> N >> A >> B >> C >> D;
		map<long long, Node> nodes;
		vector<Branch> branches = { {N, 0} };
		do {
			vector<Branch> next;
			for (const auto& branch : branches) {
				if (branch.to < 0)
					continue;
				auto& to = nodes[branch.to];
				if (branch.coins < to.coins) {
					to.coins = branch.coins;
					long long n = branch.to;
					if (n != 0) {
						long long mod5 = n % 5;
						if (mod5 == 0) {
							long long coinsD = ((n - n / 5) < 1000000000000000LL / D) ? (n - n / 5) * D : 1000000000000000LL;
							long long nextCoins = min(branch.coins + C, branch.coins + coinsD);
							next.emplace_back(Branch{ n / 5, nextCoins });
						}
						else {
							if (mod5 <= 2)
								next.emplace_back(Branch{ n - mod5, branch.coins + mod5 * D });
							else
								next.emplace_back(Branch{ n + (5 - mod5), branch.coins + (5 - mod5) * D });
						}
						long long mod3 = n % 3;
						if (mod3 == 0) {
							long long coinsD = ((n - n / 3) < 1000000000000000LL / D) ? (n - n / 3) * D : 1000000000000000LL;
							long long nextCoins = min(branch.coins + B, branch.coins + coinsD);
							next.emplace_back(Branch{ n / 3, nextCoins });
						}
						else {
							if (mod3 == 1)
								next.emplace_back(Branch{ n - mod3, branch.coins + mod3 * D });
							else
								next.emplace_back(Branch{ n + (3 - mod3), branch.coins + (3 - mod3) * D });
						}
						long long mod2 = n % 2;
						if (mod2 == 0) {
							long long coinsD = ((n - n / 2) < 1000000000000000LL / D) ? (n - n / 2) * D : 1000000000000000LL;
							long long nextCoins = min(branch.coins + A, branch.coins + coinsD);
							next.emplace_back(Branch{ n / 2, nextCoins });
						}
						else {
							next.emplace_back(Branch{ n - mod2, branch.coins + mod2 * D });
							//next.emplace_back(Branch{ n + (2 - mod2), branch.coins + (2 - mod2) * D });
						}
					}
				}
			}
			branches.swap(next);
		} while (!branches.empty());

		cout << nodes[0].coins << endl;
	}
	return 0;
}

