int rec(int n) {
	if (memo[n]) {
		return memo[n];
	}
	int res = INF;
	if (n == 0) {
		res = 0;
	}
	else if (n == 1) {
		res = d;
	}
	else {
		if (n <= INF / d)res = n * d;
		int to = n / 2 * 2;
		chmin(res, abs(n - to)*d + rec(n / 2) + a);
		to = (n + 1) / 2 * 2;
		chmin(res, abs(n - to)*d + rec((n+1) / 2) + a);
		to = n / 3 * 3;
		chmin(res, abs(n - to)*d + rec(n / 3) + b);
		to = (n + 2) / 3 * 3;
		chmin(res, abs(n - to)*d + rec((n+2) / 3) + b);
		to = n / 5 * 5;
		chmin(res, abs(n - to)*d + rec(n / 5) + c);
		to = (n + 4) / 5 * 5;
		chmin(res, abs(n - to)*d + rec((n+4) / 5) + c);
	}
	return memo[n] = res;
}

