ll dfs(ll n, ll high) {
    if (mp.find(n) != mp.end()) return mp[n];

    ll res = n < 4e9 ? n * D : INT64_MAX;
    ll m;

    m = n / 2 * 2;
    if (m > 0) res = min(res, D * abs(m - n) + A + dfs(m / 2, n));
    m = (n + 1) / 2 * 2;
    if (m < high && m / 2 < n) res = min(res, D * abs(m - n) + A + dfs(m / 2, n));
    m = n / 3 * 3;
    if (m > 0) res = min(res, D * abs(m - n) + B + dfs(m / 3, n));
    m = (n + 2) / 3 * 3;
    if (m < high && m / 3 < n) res = min(res, D * abs(m - n) + B + dfs(m / 3, n));
    m = n / 5 * 5;
    if (m > 0) res = min(res, D * abs(m - n) + C + dfs(m / 5, n));
    m = (n + 4) / 5 * 5;
    if (m < high && m / 5 < n) res = min(res, D * abs(m - n) + C + dfs(m / 5, n));

    mp[n] = res;
    return res;
}

