map<ll, ll> memo;

ll dfs(ll X) {
    // Xをすでに計算した場合はメモした値を返す
    if (memo.count(X)) {
        // cout << "X already" << X << endl;
        return memo[X];
    }

    // メモがない場合は、6通りのパターンを探索する
    ll min_costs = 1e18;
    ll d2f = X/2, d2c = (X+1) / 2, 
        d3f = X/3, d3c = (X+2) / 3, 
        d5f = X/5, d5c = (X+4) / 5;
    if (d2f != X) min_costs = min(min_costs, dfs(d2f) + min(abs(X - d2f * 2) * D + A, abs(X - d2f) * D));
    if (d3f != X) min_costs = min(min_costs, dfs(d3f) + min(abs(X - d3f * 3) * D + B, abs(X - d3f) * D));
    if (d5f != X) min_costs = min(min_costs, dfs(d5f) + min(abs(X - d5f * 5) * D + C, abs(X - d5f) * D));
    if (d2c != X) min_costs = min(min_costs, dfs(d2c) + min(abs(X - d2c * 2) * D + A, abs(X - d2c) * D));
    if (d3c != X) min_costs = min(min_costs, dfs(d3c) + min(abs(X - d3c * 3) * D + B, abs(X - d3c) * D));
    if (d5c != X) min_costs = min(min_costs, dfs(d5c) + min(abs(X - d5c * 5) * D + C, abs(X - d5c) * D));
    memo[X] = min_costs;
    return memo[X];
}

