ll a,b,c,d;
ll rec(ll n){
  if(n == 0) return 0;
  if(n == 1) return d;
  if(mcount.count(n)) return mcount[n];

  ll u2 = (n+1)/2*2;
  ll l2 = n/2*2;
  ll u3 = (n+2)/3*3;
  ll l3 = n/3*3;
  ll u5 = (n+4)/5*5;
  ll l5 = n/5*5;

  ll ret = 1e18;
  if(n < 1e18/d) ret = n*d;
  ret = min(ret, llabs(l2-n)*d + a + rec(l2/2));
  ret = min(ret, llabs(u2-n)*d + a + rec(u2/2));

  ret = min(ret, llabs(l3-n)*d + b + rec(l3/3));
  ret = min(ret, llabs(u3-n)*d + b + rec(u3/3));

  ret = min(ret, llabs(l5-n)*d + c + rec(l5/5));
  ret = min(ret, llabs(u5-n)*d + c + rec(u5/5));

  mcount[n] = ret;
  return ret;

}

