ll n, a[3], d;
ll val[3] = {2, 3, 5};

ll f(ll x) {
	if (x == 0) {
		return 0;
	}
	if (x == 1) {
		return d;
	}
	if (dp.count(x)) {
		return dp[x];
	}
	ll res = 9e18;
	if (x < res / d) {
		res = min(res, x * d);
	}
	for (int i = 0; i < 3; i++) {
		if (x % val[i] == 0) {
			res = min(res, a[i] + f(x / val[i]));
		}	else {
			ll A = x / val[i];
			ll B = (x + val[i] - 1) / val[i];
			A *= val[i], B *= val[i];
			res = min(res, d * abs(x - A) + a[i] + f(A / val[i]));
			res = min(res, d * abs(x - B) + a[i] + f(B / val[i]));
		}
	}
	return dp[x] = res;
}

