map<ll,ll> memo, nmemo;

ll pay(ll n, int a, int b, int c, int d){

    //cout << n << endl;

    if(n==0)return 0;
    if(n==1)return d;

    if(memo.count(n)) return memo.at(n);

    ll rtn;

    rtn = d*(n-(n/2)*2) + a + pay(n/2,a,b,c,d);
    rtn = min(rtn, d*(((n+1)/2)*2-n) + a + pay((n+1)/2,a,b,c,d));
    rtn = min(rtn, d*(n-(n/3)*3) + b + pay(n/3,a,b,c,d));
    rtn = min(rtn, d*(((n+2)/3)*3-n) + b + pay((n+2)/3,a,b,c,d));
    rtn = min(rtn, d*(n-(n/5)*5) + c + pay(n/5,a,b,c,d));
    rtn = min(rtn, d*(((n+4)/5)*5-n) + c + pay((n+4)/5,a,b,c,d));
    if(rtn/d >=n)
        rtn = d*n;

    memo[n] = rtn;
    return rtn;
}

