class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    ll N, A, B, C, D;
    bool input() {
        is >> N >> A>> B >> C >> D;
        return !!is;
    }

    unordered_map<ll, ll> dp;
    ll dfs(ll x){
        if(x == 0) return 0;
        if(dp.count(x)) {
            assert(dp[x] != INFLL);
            return dp[x];
        }
        ll d5 = x%5;
        ll d3 = x%3;
        ll d2 = x%2;

        dp[x] = INFLL;
        if(x < INFLL / D) dp[x] = x *D;
        UPMIN(dp[x], dfs((x-d5)/5) + C + d5*D);
        if(d5 > 0 and x > 5){
            d5 = 5 - d5;
            UPMIN(dp[x], dfs((x+d5)/5) + C + d5*D);
        }
        UPMIN(dp[x], dfs((x-d3)/3) + B + d3*D);
        if(d3 > 0 and x > 3){
            d3 = 3 - d3;
            UPMIN(dp[x], dfs((x+d3)/3) + B + d3*D);
        }
        UPMIN(dp[x], dfs((x-d2)/2)+A+d2*D);

        return dp[x];
    }


    void run();
};

int main(int argc, char *argv[]) {
    cin.tie(nullptr);
