long long get_ans(long long n) {
  if (best_result.find(n) != best_result.end())
    return best_result[n];
  //cout << "n: " << n << "\n";
  // for 5
  long long prev = n - n % 5;
  long long next = prev + 5;
  //cout << "prev/5 = " << prev/5 << "; next/5 = " << next/5 << "\n";
  long long prev_ans_5 = get_ans(prev / 5) + c + (n - prev) * d;
  long long next_ans_5 = abs_max;
  if (next / 5 != n)
    next_ans_5 = get_ans(next / 5) + c + (next - n) * d;
  // for 3
  prev = n - n % 3;
  next = prev + 3;
  //cout << "prev/3 = " << prev/3 << "; next/3 = " << next/3 << "\n";
  long long prev_ans_3 = get_ans(prev / 3) + b + (n - prev) * d;
  long long next_ans_3 = abs_max;
  if (next / 3 != n)
    next_ans_3 = get_ans(next / 3) + b + (next - n) * d;
  // for 2
  prev  = n - n % 2;
  next = prev + 2;
  //cout << "prev/2 = " << prev/2 << "; next/2 = " << next/2 << "\n";
  long long prev_ans_2 = get_ans(prev / 2) + a + (n - prev) * d;
  long long next_ans_2 = abs_max;
  if (next / 2 != n)
    next_ans_2 = get_ans(next / 2) + a + (next - n) * d;
  // for +1
  long long no_multi = abs_max;
  if (n <= 1000000000LL)
    no_multi = n * d;
  best_result[n] = min(prev_ans_5, 
    min(next_ans_5, 
    min(prev_ans_3,
    min(next_ans_3,
    min(prev_ans_2,
    min(next_ans_2,
    no_multi))))));
  //cout << "n: " << n << "; best_result: " << best_result[n] << "\n";
  return best_result[n];
}

