map<ll, __int128> mem;

__int128 dp (ll n) {
	if (n == 0) return 0;

	if (mem.count(n)) return mem[n];
	__int128 &res = mem[n];
	res = d * n;

	ll to = n - n % 2;
	res = min(res, d * (n - to) + a * bool(to) + dp(to / 2));

	to += 2;
	res = min(res, d * (to - n) + a * bool(to) + dp(to / 2));

	to = n - n % 3;
	res = min(res, d * (n - to) + b * bool(to) + dp(to / 3));

	to += 3;
	res = min(res, d * (to - n) + b * bool(to) + dp(to / 3));

	to = n - n % 5;
	res = min(res, d * (n - to) + c * bool(to) + dp(to / 5));

	to += 5;
	res = min(res, d * (to - n) + c * bool(to) + dp(to / 5));

	return res;
}

