	if(md==3) xx = b;
	if(md==5) xx = c;
	if(xx < d*(nn-nn/md)) {
		cc += xx;
	}
	else {
		cc += d*(nn-nn/md);
	}
	ret = nn/md;
	return cc;
}

ll getCost2(ll num, ll md, ll& ret) {
	ll tt = (num%md);
	if(tt==0) {
		ret = num;
		return 0;
	}
	ll cc = (md-tt)*d;
	ll nn = num + (md-tt);
	ll xx = a;
	if(md==3) xx = b;
	if(md==5) xx = c;
	if(xx < d*(nn-nn/md)) {
		cc += xx;
	}
	else {
		cc += d*(nn-nn/md);
	}
	ret = nn/md;
	return cc;
}

