int SOLVE(){
	long long n, a, b, c, d;
	cin >> n >> a >> b >> c >> d;
	vector<long long> price(10);
	price[2] = a, price[3] = b, price[5] = c;
	map<long long, long long> cost;
	cost[0] = 0, cost[1] = d;
	static const vector<long long> qu{2, 3, 5};
	function<long long(long long)> solve = [&](long long n){
		if(cost.count(n)) return cost[n];
		long long res = __builtin_mul_overflow_p(n, d, 0LL) ? numeric_limits<long long>::max() : n * d;
		for(auto p: qu){
			int rem = n % p;
			if(rem){
				ctmin(res, min(solve((n - rem) / p) + rem * d, solve((n + p - rem) / p) + (p - rem) * d) + price[p]);
			}
			else{
				ctmin(res, solve(n / p) + price[p]);
			}
		}
		return cost[n] = res;
	};
	cout << solve(n) << "\n";
	return 0;
}

