using ll = long long;

ll tansaku(map<ll,ll>& mp, ll n, ll a, ll b, ll c, ll d)
{
    if(n == 0) return mp[0] = 0;
    if(n == 1) return mp[1] = d;
    if(mp.count(n)) return mp[n]; 
    ll i,j;
    ll ans = 1e18;
    double ansd;
    double dn = n;
    double dd = d;
    ansd = dn*dd;
    if(ansd < 2e18){
        ll tmp = n*d;
        ans = min(ans, tmp);
    }
    for(i = 0;i < 3;++i){
        ll p = 1;
        ll cost = 0;
        if(i == 0) p = 2, cost = a;
        else if(i == 1) p = 3, cost = b;
        else if(i == 2) p = 5, cost = c;
        if(n%p == 0){
            ll tmp = tansaku(mp,n/p,a,b,c,d) + cost;
            ans = min(ans, tmp);
        }else{
            ll tc = n + (p - n%p);
            ll tf = n - n%p;
            ll tmp = tansaku(mp,tc/p,a,b,c,d) + (tc - n)*d + cost;
            ans = min(ans,tmp);
            tmp = tansaku(mp,tf/p,a,b,c,d) + (n - tf)*d + cost;
            ans = min(ans,tmp);
        }
    }
    return mp[n] = ans;
}

ll solve()
{
    ll n,a,b,c,d;
    cin >> n >> a >> b >> c >> d;
    if(n == 1) return d;
    map<ll,ll> mp;
    tansaku(mp, n, a, b, c, d);
    return mp[n];
}

