using namespace std;

typedef unsigned long long ll;

void calc(ll n, ll a, ll b, ll c, ll d, map<ll,ll>&m) {
  if (m.find(n) != m.end() || n == 0) {
    return;
  }
  m[n] = n*d;
  ll u2 = n,l2 = n,u3 = n,l3 = n,u5 = n,l5 = n;
  while (u2 % 2 != 0) ++u2;
  while (l2 % 2 != 0) --l2;
  while (u3 % 3 != 0) ++u3;
  while (l3 % 3 != 0) --l3;
  while (u5 % 5 != 0) ++u5;
  while (l5 % 5 != 0) --l5;
  calc(u2/2,a,b,c,d,m);
  calc(l2/2,a,b,c,d,m);
  calc(u3/3,a,b,c,d,m);
  calc(l3/3,a,b,c,d,m);
  calc(u5/5,a,b,c,d,m);
  calc(l5/5,a,b,c,d,m);
  m[n] = min(m[n], a+m[u2/2]+d*(u2-n));
  m[n] = min(m[n], a+m[l2/2]+d*(n-l2));
  m[n] = min(m[n], b+m[u3/3]+d*(u3-n));
  m[n] = min(m[n], b+m[l3/3]+d*(n-l3));
  m[n] = min(m[n], c+m[u5/5]+d*(u5-n));
  m[n] = min(m[n], c+m[l5/5]+d*(n-l5));
}

