const int N = 505;
bool killed[N][N];
int n;
int memo[N][N] = { 0 };
int dist[N][N] = { 0 };

int dx[4] = { -1, 1, 0, 0 };
int dy[4] = { 0, 0, -1, 1 };
vector<pair<int, int>> nei[N][N];

int main() {
    //c_p_c();
    n = read();
    for (auto row = 0; row < n; row++) {
        for (auto col = 0; col < n; col++) {
            dist[row][col] = 1 + min({ row, n - 1 - row, col , n - 1 - col });
        }
    }

    for (int row = 0; row < n; ++row) {
        for (int col = 0; col < n; ++col) {
            for (int dir = 0; dir < 4; ++dir) {
                int r2 = row + dx[dir];
                int c2 = col + dy[dir];
                if (0 <= r2 && 0 <= c2 && r2 < n && c2 < n) {
                    nei[row][col].emplace_back(r2, c2);
                }
            }
        }
    }

    long long answer = 0;
    for (auto turn = 1; turn <= n * n; turn++) {
        int who = read();
        who--;
        int row = who / n;
        int col = who % n;
        answer += dist[row][col] - 1;
        dist[row][col]--;
        killed[row][col] = true;
        vector<pair<int, int>> q;
        q.emplace_back(row, col);
        for (int i = 0; i < (int)q.size(); i++) {
            pair<int, int> a = q[i];
            for (const pair<int, int>& b : nei[a.first][a.second]) {
                int maybe = dist[a.first][a.second];
                if (!killed[b.first][b.second])
                    maybe++;
                if (dist[b.first][b.second] > maybe) {
                    dist[b.first][b.second] = maybe;
                    q.push_back(b);
                }
            }
        }
    }

    cout << answer << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD = 1000000007;
//cout << setprecision(20) << 
const ll INF = 1e18;

map<ll, ll> memo;

ll solve(ll N, ll A, ll B, ll C, ll D) {
    if (memo.count(N)) return memo[N];

    if (N == 1) {
        memo[N] = D;
        return memo[N];
    }
    if (N == 0) {
        memo[N] = 0;
        return memo[N];
    }

    ll up_2   = solve( ceil((double)N/2), A, B, C, D) + abs(  ceil((double)N/2) * 2 - N) * D + A;
    ll down_2 = solve(floor((double)N/2), A, B, C, D) + abs(-floor((double)N/2) * 2 + N) * D + A;
    ll up_3   = solve( ceil((double)N/3), A, B, C, D) + abs(  ceil((double)N/3) * 3 - N) * D + B;
    ll down_3 = solve(floor((double)N/3), A, B, C, D) + abs(-floor((double)N/3) * 3 + N) * D + B;
    ll up_5   = solve( ceil((double)N/5), A, B, C, D) + abs(  ceil((double)N/5) * 5 - N) * D + C;
    ll down_5 = solve(floor((double)N/5), A, B, C, D) + abs(-floor((double)N/5) * 5 + N) * D + C;

    ll min_n;
    if (N < INF / D) min_n = N * D;
    else min_n = INF;
    min_n = min(min_n, up_2);
    min_n = min(min_n, up_3);
    min_n = min(min_n, up_5);
    min_n = min(min_n, down_2);
    min_n = min(min_n, down_3);
    min_n = min(min_n, down_5);

    memo[N] = min_n;
    return memo[N];
}

int main() {
    int T; cin >> T;
    for (int i = 0; i < T; ++i) {
        memo.clear();
        ll N, A, B, C, D; cin >> N >> A >> B >> C >> D;
        cout << solve(N, A, B, C, D) << endl;
    }
}

