void Go(map<long long,long long> &mp,long long key,long long value){
	if(mp.count(key))mp[key] = min(mp[key],value);
	else mp[key] = value;
}

int main(){


	int T;
	cin>>T;

	for(int i=0;i<T;i++){
		long long N,A,B,C,D;
		cin>>N>>A>>B>>C>>D;
		long long ans = Inf;
		map<long long,long long> mp;
		mp[N] = 0;

		while(mp.size()!=0){

			map<long long,long long> Nmp;
			for(auto a:mp){
				//cout<<a.first<<','<<a.second<<endl;
				for(int j=-1;j<=1;j++){
					long long t = a.first+j;
					if(t<0)continue;
					if(t%2!=0)continue;
					if(t/2>=a.first)continue;
					Go(Nmp,t/2,a.second + A + D * abs(j));
				}

				for(int j=-2;j<=2;j++){
					long long t = a.first+j;
					if(t<0)continue;
					if(t%3!=0)continue;
					if(t/3>=a.first)continue;
					Go(Nmp,t/3,a.second + B + D * abs(j));
				}

				for(int j=-4;j<=4;j++){
					long long t = a.first+j;
					if(t<0)continue;
					if(t%5!=0)continue;
					if(t/5>=a.first)continue;
					Go(Nmp,t/5,a.second + C + D * abs(j));
