			}
			for(auto a:Nmp){
				if(a.first!=0&&D>Inf/a.first)continue;
				ans = min(ans,a.second + D * a.first);
			}
			Nmp.erase(0);
			Nmp.erase(1);
			mp = Nmp;
			//cout<<endl;
		}
