      if(!already.insert(n).second) continue;
      // cout << n << negc << endl;
      switch(n%2) {
      case 0:
        if(p>n-n/2) pq.emplace(max(negc-a, negc-d*(n/2)), n/2);
        else pq.emplace(negc-a, n/2);
        break;
      case 1:
        if(p>n-n/2) pq.emplace(max(negc-a-d, negc-d*(n-n/2)), n/2);
        else pq.emplace(negc-a-d, n/2);
        if(p>n-n/2+1) pq.emplace(max(negc-a-d, negc-d*(n-(n/2+1))), n/2+1);
        else pq.emplace(negc-a-d, n/2+1);
        break;
      }
      switch(n%3) {
      case 0:
        if(p>n-n/3) pq.emplace(max(negc-b, negc-d*(n-n/3)), n/3);
        else pq.emplace(negc-b, n/3);
        break;
      case 1:
        if(p>n-n/3) pq.emplace(max(negc-b-d, negc-d*(n-n/3)), n/3);
        else pq.emplace(negc-b-d, n/3);
        break;
      case 2:
        if(p>n-(n/3+1)) pq.emplace(max(negc-b-d, negc-d*(n-(n/3+1))), n/3+1);
        else pq.emplace(negc-b-d, n/3);
        break;
      }
      switch(n%5) {
      case 0:
        if(p>n-n/5) pq.emplace(max(negc-c, negc-d*(n-n/5)), n/5);
        else pq.emplace(negc-c, n/5);
        break;
      case 1:
        if(p>n-n/5) pq.emplace(max(negc-c-d, negc-d*(n-n/5)), n/5);
        else pq.emplace(negc-c-d, n/5);
        break;
      case 2:
        if(p>n-n/5) pq.emplace(max(negc-c-d-d, negc-d*(n-n/5)), n/5);
        else pq.emplace(negc-c-d-d, n/5);
        break;
      case 3:
        if(p>n-(n/5+1)) pq.emplace(max(negc-c-d-d, negc-d*(n-(n/5+1))), n/5+1);
        else pq.emplace(negc-c-d-d, n/5);
        break;
      case 4:
        if(p>n-(n/5+1)) pq.emplace(max(negc-c-d, negc-d*(n-(n/5+1))), n/5+1);
        else pq.emplace(negc-c-d, n/5);
        break;
      }
    }
  }
  return 0;
}

