const ll INF = 1e18;
const ll ALOT = 4e9;

ll n, a, b, c, d;

map<ll, ll> mm;

void solve() {
	ll ans = INF;
	cin >> n >> a >> b >> c >> d;
	mm.clear();
	mm[n] = 0;
	auto updmm = [](ll n, ll x) {
		if (mm.count(n)) {
			mm[n] = min(mm[n], x);
		} else {
			mm[n] = x;
		}
	};
	auto upd = [&updmm] (ll n, ll div, ll cost, ll add) {
		if (n % div == 0) {
			updmm(n / div, add + cost);
		} else {
			updmm(n / div, add + cost + d * (n % div));
			updmm(n / div + 1, add + cost + d * (div -  n % div));
		}
	};
	while (!mm.empty()) {
		ll n = mm.rbegin()->first;
		ll cost = mm.rbegin()->second;
		mm.erase(n);
		if (n <= ALOT && cost <= INF) {
			ans = min(ans, cost + n * d);
		}
		if (n > 1) {
			upd(n, 2, a, cost);
			upd(n, 3, b, cost);
			upd(n, 5, c, cost);
		}
	}
	cout << ans << "\n";
}

int main() {
	ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);
	cout.setf(ios::fixed), cout.precision(20);
	int tt;
	cin >> tt;
	for (int i = 0; i < tt; ++i) {
		solve();
	}
	return 0;
}

