ll check(ll n,ll &a,ll &b,ll &c, ll &d,ll min,ll count,char op,vll &memo){
    if(n==1) return d;
    if(n<10000000&&memo[n]!=0) return memo[n];
    if(n%5==0){
        ll an=check(n/5,a,b,c,d,n/5*d,0,'a',memo);
        if(min>an+c) min=an+c;
    }
    if(n%3==0&&count<3){
        ll an=check(n/3,a,b,c,d,n/3*d,0,'a',memo);
        if(min>an+b) min=an+b;
    }
    if(n%2==0&&count<2){
        ll an=check(n/2,a,b,c,d,n/2*d,0,'a',memo);
        if(min>an+a) min=an+a;
    }
    if(count!=4){
        count++;
        if(op!='+'){
            ll an=check(n-1,a,b,c,d,(n-1)*d,count,'-',memo);
            if(an+d<min) min=an+d;
        }
        if(op!='-'){
            ll bn=check(n+1,a,b,c,d,(n+1)*d,count,'+',memo);
            if(bn+d<min) min=bn+d;
        }
    }
    if(n<10000000) memo[n]=min;
    return min;
}



