void solve()
{
	ll N, A, B, C, D; cin >> N >> A >> B >> C >> D;
	unordered_map<ll, ll> mp;
	//mp.clear();

	mp[0]=0;
	mp[1]=D;
	mp[2]=min(2*D, D+A);

	//ラムダ式で再帰を実現するおまじない(Zコンビネータ)
	auto curry = [](auto f){  return [=](auto&&... xs){  return [&](auto&&... ys){
		return f(forward<decltype(xs)>(xs)..., forward<decltype(ys)>(ys)...);
	};};};
	auto Z = [&](auto f){ return curry(f)(f); };


	auto Dfs = Z([&](auto dfs, ll x)->ll{
		if (mp.count(x)==1) return mp[x];

		ll val=INF;
		if (x*(dd)D<INF) chmin(val, x*D);
		//5で割る
		{
			ll v;
			if (x%5>=3) v=CEIL(x, 5);
			else        v=x/5;
			ll c = abs(x-v*5)*D+C;
			chmin(val, dfs(dfs, v)+c);
		}
		//3で割る
		{
			ll v;
			if (x%3>=2) v=CEIL(x, 3);
			else        v=x/3;
			ll c = abs(x-v*3)*D+B;
			chmin(val, dfs(dfs, v)+c);
		}
		//2で割る
		{
			ll v;
			v=x/2;
			ll c = (x%2)*D+A;
			chmin(val, dfs(dfs, v)+c);
			if (x%2==1){
				v=x/2+1;
				chmin(val, dfs(dfs, v)+c);
			}
		}

		mp[x]=val;
		return mp[x];
	});

	ll ans=Dfs(N);
	cout << ans << '\n';
}

