map<int,int> mp; //mp[]表示转移到first的最小代价为second
int n,a,b,c,d;
void push(int n,int cost){
	if(mp.count(n))mp[n]=min(mp[n],cost);
	else mp[n]=cost;
}
void solve(){
	cin>>n>>a>>b>>c>>d;
	mp.clear();
	mp[n]=0;
	while(1){
		auto it=--mp.end();
		int n=it->fi,cost=it->se;
		if(n==0){cout<<cost<<endl; return;}
		push(n/2,cost+a+d*(n%2));
		push(n/2+1,cost+a+d*(2-n%2));
		push(n/3,cost+b+d*(n%3));
		push(n/3+1,cost+b+d*(3-n%3));
		push(n/5,cost+c+d*(n%5));
		push(n/5+1,cost+c+d*(5-n%5));
		if(n<int(1e18-cost)/d)
			push(0,cost+d*n);
		mp.erase(--mp.end());
	}
}
signed main(){
	int T; cin>>T;
	while(T--){
		solve();
	}
	return 0;
}

#include <bits/stdc++.h>

using namespace std;

#define INF 1e14
#define ll long long
ll n, a, b, c, d;
vector<ll> x;
vector<ll> co;
map<ll, ll> mp;
ll dp[7];

void gen()
{
    dp[1] = d;
    dp[2] = min(2*d, d+a);
    dp[3] = min(3*d, 2*d+a);
    dp[3] = min(dp[3], d+b);
    dp[3] = min(dp[3], 3*d+c);
    dp[4] = min(4*d, d+2*a);
    dp[4] = min(dp[4], 2*d+b);
    dp[4] = min(dp[4], 2*d+c);
}

ll nows(ll x, ll inc)
{
    if(x == 1) return d;
    ll mins = INF;
    if(x%2 == 0) mins = min(mins, nows(x/2, inc)+a);
    if(x%3 == 0) mins = min(mins, nows(x/3, inc)+b);
    if(x%5 == 0) mins = min(mins, nows(x/5, inc)+c);
    mins = min(mins, nows(x-1, inc)+d);
    if(inc > 0) mins = min(mins, nows(x+1, inc-1)+d);
    return mins;
}

ll mul(ll a, ll b)
{
    if(a >= INF/b) return INF;
    return (a*b);
}

ll calc(ll n)
{
    if(n == 0) return INF;
    if(n == 1) return d;
    if(mp.find(n) != mp.end()) return mp[n];
    ll mins = mul(n, d);
    for(int i=0; i<x.size(); i++){
        ll p = x[i], cost = co[i];
        if(n%p == 0){
            ll newN = n/p;
            mins = min(mins, min(mul(n-newN, d), cost)+calc(newN));
        }
        else if(n < p){
            ll hi = p - n%p;
            ll newN = (n+hi)/p;
            mins = min(mins, min(mul(n-newN, d), cost)+calc(newN)+dp[hi]);
        }
        else {
            ll lo = n%p;
            ll hi = p - lo;
            ll newN1 = (n-lo)/p;
            mins = min(mins, min(mul(n-newN1, d), cost)+calc(newN1)+dp[lo]);
            ll newN2 = (n+hi)/p;
            mins = min(mins, min(mul(n-newN2, d), cost)+calc(newN2)+dp[hi]);
        }
    }
    //cout << n << " " << mins << endl;
    return mp[n] = mins;
}

