unordered_map<ll, ll> cache;

ll calc(ll n, ll a, ll b, ll c, ll d, ll curr) {
    if (cache.find(n) != cache.end()) return curr + cache.at(n);
    ll ans = curr + abs(n) * d;

    if (n % 2 == 0) {
        ll c = calc(n / 2, a, b, c, d, curr+a);
        ans = min(ans, c);
    }
    if (n % 3 == 0) {
        ll c = calc(n / 3, a, b, c, d, curr+b);
        ans = min(ans, c);
    }
    if (n % 5 == 0) {
        ll c = calc(n / 5, a, b, c, d, curr+c);
        ans = min(ans, c);
    }
    if (n % 2 != 0 && n % 3 != 0 && n % 5 != 0) {
        for (int i=1; i<2; i++) {
            ll c = calc(n-i, a, b, c, d, curr+d);
            ans = min(ans, c);
            c = calc(n+i, a, b, c, d, curr+d);
            ans = min(ans, c);
        }
    }
    out(n << ' ' << ans - curr);
    cache.insert(make_pair(n, ans-curr));
    return ans;
}

