#include <bits/stdc++.h>

using int64 = long long;
using uint64 = unsigned long long;

using namespace std;

map<int64, int64> memo;

int64 solve(int64 n, int64 a, int64 b, int64 c, int64 d) {
    if (memo.count(n)) {
        return memo[n];
    }
    if (n == 0) {
        return memo[n] = 0;
    }

    int nums[] = {2, 3, 5};
    int64 cost[] = {a, b, c};

    memo[n] = (1LL << 60);
    for (int i = 0; i < 3; i++) {
        int64 prev = (n / nums[i]) * nums[i],
              next = (n + nums[i] - 1) / nums[i] * nums[i];
        if (prev / nums[i] != n) {
            memo[n] = min(memo[n], cost[i] + abs(prev - n) * d + solve(prev / nums[i], a, b, c, d));
        }
        if (next / nums[i] != n) {
            memo[n] = min(memo[n], cost[i] + abs(next - n) * d + solve(next / nums[i], a, b, c, d));
        }
    }
    if (n < (memo[n] + d - 1) / d) {
        memo[n] = min(memo[n], n * d);
    }
    return memo[n];
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    int t;
    cin >> t;

    for (int _ = 0; _ < t; _++) {
        int64 n, a, b, c, d;
        cin >> n >> a >> b >> c >> d;
        memo.clear();
        cout << solve(n, a, b, c, d) << endl;
    }

    return 0;
}

