unordered_map <LL,LL> dp;
LL n,A,B,C,D;
LL DP(LL n){
	if (n==0)
		return 0;
	if (n==1)
		return D;
	if (dp.count(n))
		return dp[n];
	LL res=(1e18/n)>=D?n*D:1e18;
	res=min(res,min(DP(n/2)+A+D*(n%2),
			n==2?(LL)1e18:(DP(n/2+1)+A+D*(2-n%2))));
	res=min(res,min(DP(n/3)+B+D*(n%3),DP(n/3+1)+B+D*(3-n%3)));
	res=min(res,min(DP(n/5)+C+D*(n%5),DP(n/5+1)+C+D*(5-n%5)));
	return dp[n]=res;
}
