#include <bits/stdc++.h>
using namespace std;
#define LL long long int
LL A, B, C, D;
map<LL, LL> memo;
LL INF = (LL)5e18;
LL solve(LL n){
    if(n==0) return 0;
    if(n==1) return D;
    if (memo.count(n)) return memo[n];
    LL l2 = (n/2)*2;
    LL r2 = ((n+1)/2)*2;

    LL l3 = (n/3)*3;
    LL r3 = ((n+2)/3)*3;

    LL l5 = (n/5)*5;
    LL r5 = ((n+4)/5)*5;

    LL res = INF;
    if(n < res/D){
        res = n*D;
    }

    res = min(res, llabs(l2-n)*D + A + solve(l2/2));
    res = min(res, llabs(r2-n)*D + A + solve(r2/2));

    res = min(res, llabs(l3-n)*D + B + solve(l3/3));
    res = min(res, llabs(r3-n)*D + B + solve(r3/3));

    res = min(res, llabs(l5-n)*D + C + solve(l5/5));
    res = min(res, llabs(r5-n)*D + C + solve(r5/5));

    return memo[n] = res;
}
