int bit_count(ll v)
{
	int ret=0;

	for(;v>0;)
	{
		ret++;
		v&=v-1;
	}

	return ret;
}


int msb(ll v)
{
	if(v==0) return -1;

	int ret=0;
	if(v & 0xFFFFFFFF00000000LL) v>>=32,ret+=32;
	if(v & 0xFFFF0000LL) v>>=16,ret+=16;
	if(v & 0xFF00) v>>=8,ret+=8;
	if(v & 0xF0) v>>=4,ret+=4;
	if(v & 0xC) v>>=2,ret+=2;
	if(v & 0x2) v>>=1,ret+=1;
	return ret;
}


int lsb(ll v)
{
	if(v==0) return -1;

	int ret=0;
	if(!(v & 0xFFFFFFFFLL)) v>>=32,ret+=32;
	if(!(v & 0xFFFF)) v>>=16,ret+=16;
	if(!(v & 0xFF)) v>>=8,ret+=8;
	if(!(v & 0xF)) v>>=4,ret+=4;
	if(!(v & 0x3)) v>>=2,ret+=2;
	if(!(v & 0x1)) v>>=1,ret+=1;
	return ret;
}


