        add(y, cost+a, m, pq);
    }else{
        ll y = x/k;
        ll diff = abs(x-y*k);
        add(y, cost+a+d*diff, m, pq);
        y = x/k+1;
        diff = abs(x-y*k);
        add(y, cost+a+d*diff, m, pq);
    }
}

void solve(ll n, ll a, ll b, ll c, ll d){
    unordered_map<ll,ll> m;
    priority_queue<ll> pq;
    pq.push(n);
    m[n] = 0;
    ll ans = INF;
    while(!pq.empty()){
        ll x = pq.top();
        ll cost = m[x];
        pq.pop();
        // debug(x);
        // debug(cost);
        if(x < 2000000000) chmin(ans, cost+x*d);
        move(x, cost, 2, a, d, m, pq);
        move(x, cost, 3, b, d, m, pq);
        move(x, cost, 5, c, d, m, pq);

    }
    cout << ans << endl;


}

int main(){
    cin >> t;
    for(ll i = 0;i < t;i++){
        cin >> n >> a >> b >> c >> d;
        solve(n, a, b, c, d);
    }
}

