const ll INF = 1e18;

ll a, b, c, d;
map<ll, ll> mp;

ll dfs(ll x){
    if(x == 0) return 0;
    if(mp[x] > 0) return mp[x];
    ll res = INF;
    if(INF/d > x) res = x * d;
    auto f2 = [&](ll y){
        if(y >= x) return INF;
        return dfs(y);
    };
    {
        ll l = x/2*2, r = l+2;
        chmin(res, f2(l/2)+a+(x-l)*d);
        chmin(res, f2(r/2)+a+(r-x)*d);
    }
    {
        ll l = x/3*3, r = l+3;
        chmin(res, f2(l/3)+b+(x-l)*d);
        chmin(res, f2(r/3)+b+(r-x)*d);
    }
    {
        ll l = x/5*5, r = l+5;
        chmin(res, f2(l/5)+c+(x-l)*d);
        chmin(res, f2(r/5)+c+(r-x)*d);
    }
    return mp[x] = res;
}

