ll solve(ll n, bool plus1allowed, bool minus1allowed) {
  //~ cout << "Solving n = " << n << endl;
  if (n <= 0) return 0;
  if (done.find(n) != done.end()) {
    //~ cout << "I already know that Solve(" << n << ") = " << done[n] << endl;
    return done[n];
  }

  ll res = D*n;
  if (res <= (ll)0) res = LLONG_MAX;
  ll x;

  if (n % (ll)2 == (ll)0) {
    x = solve(n/(ll)2, true, true);
    if (x + A >= (ll)0) res = min(res, A + x);
  }
  else {
    if (plus1allowed) {
      x = solve((n+(ll)1)/(ll)2, true, false);
      if (A + D + x >= (ll) 0) res = min(res, A + D + x);
    }
    if (minus1allowed) {
      x = solve((n-(ll)1)/(ll)2, false, true);
      if (x + A + D >= (ll) 0) res = min(res, A + D + x);
    }
  }

  if (n % (ll)3 == (ll)0) {
    x = solve(n/(ll)3, true, true);
    if (x + B >= (ll)0) res = min(res, B + x);
  }
  else if (n % (ll)3 == (ll)1) {
    x = solve((n-(ll)1)/(ll)3, true, true);
    if (x + B + D >= (ll)0) res = min(res, B + D + x);
  }
  else {
    x = solve((n+(ll)1)/(ll)3, true, true);
    if (x + B + D >= (ll)0) res = min(res, B + D + x);
  }

  if (n % (ll)5 == (ll)0) {
    x = solve(n/(ll)5, true, true);
    if (x + C >= (ll)0) res = min(res, C + x);
  }
  else if (n % (ll)5 == (ll)1) {
    x = solve((n-(ll)1)/(ll)5, true, true);
    if (x + C + D >= (ll)0) res = min(res, C + D + x);
  }
  else if (n % (ll)5 == (ll)2) {
    x = solve((n-(ll)2)/(ll)5, true, true);
    if (x + C + D + D>= (ll)0) res = min(res, C + (ll)2*D + x);
  }
  else if (n % (ll)5 == (ll)3) {
    x = solve((n+(ll)2)/(ll)5, true, true);
    if (x + C + D + D>= (ll)0) res = min(res, C + (ll)2*D + x);
  }
  else {
    x = solve((n+(ll)1)/(ll)5, true, true);
    if (x + C + D >= (ll)0) res = min(res, C + D + x);
  }

  done[n] = res;
  //~ cout << "Solve(" << n << ") = " << res << endl;
  return res;
}

int main() {
  cin >> T;
  for (int t=0; t<T; t++) {
    cin >> N >> A >> B >> C >> D;
    done.clear();
    done[1] = D;
    cout << solve(N, true, true) << endl;
  }

  return 0;
}

