ll min_price(ll n) {
    if (n == 1)
        return d;

    if (values.find(n) != values.end())
        return values[n];

    bool found1 = false, found2 = false, found3 = false;
    values.insert(make_pair(n, 2e18));

    if (n % 2 == 0) {
        values[n] = min(values[n], a + min_price(n / 2));
        if ((n / 2) <= (4e18 - min_price(n / 2)) / d)
            values[n] = min(values[n], d * (n / 2) + min_price(n / 2));
        found1 = true;
    }
    if (n % 3 == 0) {
        values[n] = min(values[n], b + min_price(n / 3));
        if (2 * (n / 3) <= (4e18 - min_price(n / 3)) / d)
            values[n] = min(values[n], d * 2 * (n / 3) + min_price(n / 3));
        found2 = true;
    }
    if (n % 5 == 0) {
        values[n] = min(values[n], c + min_price(n / 5));
        if (4 * (n / 5) <= (4e18 - min_price(n / 5)) / d)
            values[n] = min(values[n], d * 4 * (n / 5) + min_price(n / 5));
        found3 = true;
    }

    if (!found1 || !found2 || !found3) {
        values[n] = min(values[n], d + min_price(n - 1));
        values[n] = min(values[n], d + min_price(n + 1));
    }

    return values[n];
}

