long long dfs(long long a){
    if(a == 0) return 0;
    if(a == 1) return D;
    if(m.count(a)) return m[a];
    long long res = 1e18;
    if(a < res / D) res = a * D;
    long long l2 = a/2*2, r2 = (a + 1) / 2*2;
    long long l3 = a/3*3, r3 = (a + 2) / 3*3;
    long long l5 = a/5*5, r5 = (a + 4) / 5*5;
    res = min(res, min(llabs(a - l2) * D + A + dfs(l2 / 2), llabs(a - r2) * D + A + dfs(r2 / 2)));
    res = min(res, min(llabs(a - l3) * D + B + dfs(l3 / 3), llabs(a - r3) * D + B + dfs(r3 / 3)));
    res = min(res, min(llabs(a - l5) * D + C + dfs(l5 / 5), llabs(a - r5) * D + C + dfs(r5 / 5)));
    m[a] = res;
    return res;
}
