#define mp(x, y) std::make_pair(x, y)

const int MaxN = 66; 

int m; 
s128 ans;
s64 n, a, b, c, d; 

struct node
{
	s64 val; 
	int x, y, z; 

	node(){}
	node(s64 v, int a, int b, int c):
		val(v), x(a), y(b), z(c) {}

	inline bool operator < (const node &rhs) const
	{
		return val > rhs.val; 
	}
	inline s64 calc() const
	{
		return x * a + y * b + z * c; 
	}
}p[100101]; 

template <class T>
inline T abs(T x)
{
	return x < 0 ? -x : x; 
}

inline s64 solve(int i, s64 n, const node &frm)
{
	if (i > m)
		return 0; 
	if (p[i].x > frm.x || p[i].y > frm.y || p[i].z > frm.z)
		return solve(i + 1, n, frm); 

	s64 cnt = n / p[i].val; 
	if (n - cnt * p[i].val <= (cnt + 1) * p[i].val - n)
		return solve(i + 1, n - cnt * p[i].val, frm) + cnt; 
	else
		return solve(i + 1, (cnt + 1) * p[i].val - n, frm) + cnt + 1; 
}

inline void work()
{
	ans = (s128)1e27; 
	read(n), read(a), read(b), read(c), read(d); 

	for (int i = 1; i <= m; ++i)
		if (p[i].val <= 2 * n)
		{
			tense(ans, p[i].calc() + (s128)solve(i, n, p[i]) * d); 
		}

	putint(ans); 
	putchar('\n'); 
}

int main()
{
	s128 p2, p3, p5; 
	int  c2, c3, c5; 
	for (c2 = 0, p2 = 1; p2 <= 2e18				; p2 *= 2, ++c2)
	for (c3 = 0, p3 = 1; p2 * p3 <= 2e18		; p3 *= 3, ++c3)
	for (c5 = 0, p5 = 1; p2 * p3 * p5 <= 2e18	; p5 *= 5, ++c5)
		p[++m] = node(p2 * p3 * p5, c2, c3, c5); 
	std::sort(p + 1, p + m + 1); 

	int T; 
	read(T); 
	while (T--)
		work(); 
	return 0; 
}

