ll res(ll n){
    if(2 <= n && n <= 100000 && dp[query][n] != 0){
        return dp[query][n];
    }
    if(n == 0){
        return 0ll;
    }else if(n == 1){
        return d;
    }else if(n < 0){
        return INF;
    }
    ll tmp = INF;
    ll two = n / 2;
    if(n != two)tmp = min(tmp, res(two) + a + d * abs(two * 2 - n));
    if(n != two + 1 && n % 2 != 0)tmp = min(tmp, res(two + 1) + a + d * abs(two * 2 + 2 - n));
    ll three = n / 3;
    if(n != three)tmp = min(tmp, res(three) + b + d * abs(three * 3 - n));
    if(n != three + 1 && n % 3 != 0)tmp = min(tmp, res(three + 1) + b + d * abs(three * 3 + 3 - n));
    ll five = n / 5;
    if(n != five)tmp = min(tmp, res(five) + c + d * abs(five * 5 - n));
    if(n != five + 1 && n % 5 != 0)tmp = min(tmp, res(five + 1) + c + d * abs(five * 5 + 5 - n));
    if(n <= 100000){
        dp[query][n] = tmp;
    }
    return tmp;
}

ll mul(ll a, ll b){
    if(a > INF / b){
        return INF;
    }else{
        return a * b;
    }
}

void solve(){
    query++;
    cin >> n;
    cin >> a >> b >> c >> d;
    while(!pqps.empty())pqps.pop();
    pqps.push(P(0, n));
    map<ll, ll> mp;
    mp[n] = 0;

    x[2] = c, x[1] = b, x[0] = a;
    y[2] = 5, y[1] = 3, y[0] = 2;
    ll ans = mul(n, d);
    while(!pqps.empty()){
        P p = pqps.top();
        pqps.pop();
        ll v = p.second;
        ll nowcost = p.first;
        if(nowcost > mp[v] && !(mp[v] == 0 && v != 0))continue;
        ll two = v / 2, three = v / 3, five = v / 5;
        vector<bool> skip = {false, false, false, false, false, false};
        for(ll i=0;i<3;i++){
            if(v % y[i] == 0)skip[i*2+1] = true;
        }
        vector<ll> nvs;
        nvs.pb(two); nvs.pb(two + 1); nvs.pb(three); nvs.pb(three + 1); nvs.pb(five); nvs.pb(five + 1);
        for(ll i=0;i<nvs.size();i++){
            if(skip[i])continue;
            ll nv = nvs[i];
            ll idx;
            if(i <= 5)idx = 2;
            if(i <= 3)idx = 1;
            if(i <= 1)idx = 0;
            ll newcost = mp[v] + x[idx] + d * abs(nv * y[idx] - v);
            if(mp[nv] > newcost || (mp[nv] == 0 && nv >= 1)){
                if(mul(nv, d) != INF)ans = min(ans, nv * d + newcost);
                mp[nv] = newcost;
                pqps.push(P(newcost, nv));
            }
        }   
    }
    p(ans);
    return;
}


