    mem[0] = 0;
    mem[1] = d;
    auto rec = [&](auto& rec, ll x) -> ll {
      if (mem.count(x)) {
        return mem[x];
      }
      ll res = ((long double)d*x < inf) ? d*x : inf;
      for (auto [m,cost]:ops) {
        res = min(res, rec(rec, x/m) + cost + d*(x%m));
        if (x%m!=0) {
          res = min(res, rec(rec, x/m+1) + cost + d*(m-x%m));
        }
      }
      mem[x] = res;
      return res;
    };
    cout << rec(rec, n) << endl;
  }

  return 0;
}

