const ll INF = 1LL << 60;
const ll divisors[3] = {2, 3, 5};

ll dfs(const vector<ll>& costs, map<ll, ll>& dp, ll val) {
    if (dp.count(val)) {
        return dp[val];
    }
    if (!val) {
        return 0;
    }
    if (val == 1) {
        return costs[3];
    }
    ll res = INF;
    rep(i, 0, 3) {
        ll d = divisors[i];
        if (val / d) {
            chmin(res, dfs(costs, dp, val / d) + (val % d) * costs[3] + costs[i]);
        }
        chmin(res, dfs(costs, dp, (val + d - 1) / d) + ((d - val % d) % d) * costs[3] + costs[i]);
    }
    if ((res + val - 1) / val >= costs[3]) {
        chmin(res, val * costs[3]);
    }
    return dp[val] = res;
}

