LL N,A,B,C,D;
map<LL,LL> mp;
LL dfs(LL N){
    if(N==1) return D;
    if(N==0) return 0;
    if(mp.find(N) != mp.end()){
        return mp[N];
    }
    LL res = LINF;
    if(N <= LL(1e9)+40){
        res = N * D;
    }

    // 2
    if(N%2 == 0){
        chmin(res,dfs(N/2) + A);
    }else{
        chmin(res,dfs((N+1)/2) + A + D);
        chmin(res,dfs((N-1)/2) + A + D);
    }

    if(N%3 == 0){
        chmin(res,dfs(N/3) + B);
    }else{
        LL rem = N % 3;
        chmin(res,dfs((N-rem)/3) + B + D*rem);
        chmin(res,dfs((N+3-rem)/3) + B + D*(3-rem));
    }

    if(N%5 == 0){
        chmin(res,dfs(N/5) + C);
    }else{
        LL rem = N % 5;
        chmin(res,dfs((N-rem)/5) + C + D*rem);
        chmin(res,dfs((N+5-rem)/5) + C + D*(5-rem));
    }


    return mp[N] = res;
}

