int L;
int a,b,c,d;
map<int,int>ma;
int dfs(int n){
	if(n==0)return 0;
	if(n==1)return d;
	if(ma.count(n))return ma[n];
	int ans=1000000000ll*inf;

	if(L/n>=d)ans=min(ans,n*d);

	if(n%2){
		ans=min(ans,d+a+dfs((n-1)/2));
		ans=min(ans,d+a+dfs((n+1)/2));

	}
	else{
		ans=min(ans,a+dfs(n/2));
	}


	if(n%3==1){
		ans=min(ans,2*d+b+dfs((n+2)/3));
		ans=min(ans,d+b+dfs((n-1)/3));

	}
	else if(n%3==2){
		ans=min(ans,2*d+b+dfs((n-2)/3));
		ans=min(ans,d+b+dfs((n+1)/3));

	}else{
		ans=min(ans,b+dfs(n/3));
	}

	int g=n%5;
	if(g!=0){
			ans=min(ans,g*d+c+dfs((n-g)/5));
		ans=min(ans,(5-g)*d+c+dfs((n+(5-g))/5));
	}
	else{
		ans=min(ans,c+dfs(n/5));

	}
	ma[n]=ans;
	return ans;
}

