void rec(vector <int> have, ll pr) {
  if (pr == Inf) return;
  vector <ll> pref;
  pref.push_back(1);
  for (int i = (int)have.size() - 1; i >= 0; --i) {
    pref.push_back(mul(pref.back(), have[i]));
  }
  reverse(pref.begin(), pref.end());
  ll need = abs(n - pr);
  ll extra = 1;
  for (int i = 0; i < (int)pref.size(); ++i) {
    extra += need / pref[i];
    need %= pref[i];
  }
  ll all = mul(extra, d);
  for (int x : have) {
    if (x == 2) add(all, a);
    if (x == 3) add(all, b);
    if (x == 5) add(all, c);
  }
  ans = min(ans, all);
  for (int nx : {5, 3, 2}) {
    if (have.empty() || nx <= have.back()) {
      have.push_back(nx);
      rec(have, mul(pr, nx));
      have.pop_back();
    }
  }
}

