ll solve(ll n){
    if(n==0)return 0;
    if(n==1)return d;
    if(mp.count(n))return mp[n];
    //cout<<n<<endl;
    ll l2=(n/2)*2;
    ll r2=((n+1)/2)*2;

    ll l3=(n/3)*3;
    ll r3=((n+2)/3)*3;

    ll l5=(n/5)*5;
    ll r5=((n+4)/5)*5;
    ll ans=1e18;
    //ll ans=min(n*d,(ll)1e18);
    if (n < ans/d) ans = n*d;
    ans=min(ans, llabs(l2-n)*d + a + solve(l2/2));
    ans=min(ans, llabs(r2-n)*d + a + solve(r2/2));

    ans=min(ans, llabs(l3-n)*d + b + solve(l3/3));
    ans=min(ans, llabs(r3-n)*d + b + solve(r3/3));

    ans=min(ans, llabs(l5-n)*d + c + solve(l5/5));
    ans=min(ans, llabs(r5-n)*d + c + solve(r5/5));

    mp[n]=ans;
    return ans;
}
