INT cost(INT x)
{
    if (x == 0)
        return 0;
    if (x == 1)
        return D;
    if (dp[x] != 0)
        return dp[x];
    INT res = 10000000000000000000;
    INT u5 = (x + 4) / 5;
    INT d5 = x / 5;
    INT u3 = (x + 2) / 3;
    INT d3 = x / 3;
    INT u2 = (x + 1) / 2;
    INT d2 = x / 2;
    res = min(res, D * x);
    res = min(res, D * (x - d5 * 5) + C + cost(d5));
    res = min(res, D * (u5 * 5 - x) + C + cost(u5));
    res = min(res, D * (x - d3 * 3) + B + cost(d3));
    res = min(res, D * (u3 * 3 - x) + B + cost(u3));
    res = min(res, D * (x - d2 * 2) + A + cost(d2));
    res = min(res, D * (u2 * 2 - x) + A + cost(u2));
    return dp[x] = res;
}
