void tc() {
    lli n, d;
    scanf("%I64d %I64d %I64d %I64d %I64d", &n, &op[0].second, &op[1].second, &op[2].second, &d);

    map<lli, lli> cost;

    priority_queue<pair<lli, lli>> pq;
    pq.push({0, n});
    while(!pq.empty()) {
        pair<lli, lli> u = pq.top(); pq.pop();
        // printf("%I64d %I64d\n", u.first, u.second);

        if(cost.find(u.second) != cost.end() and cost[u.second] != -u.first) {
            continue;
        }

        if(!u.second) {
            printf("%I64d\n", -u.first);
            break;
        }

        if(u.second == 1) {
            lli new_cost = -u.first + d;
            if(cost.find(0) == cost.end() or new_cost < cost[0]) {
                cost[0] = new_cost;
                pq.push({-new_cost, 0});
            }
            continue;
        }

        if(u.second <= 1000000000) {
            lli new_cost = -u.first + u.second*d;
            if(cost.find(0) == cost.end() or new_cost < cost[0]) {
                cost[0] = new_cost;
                pq.push({-new_cost, 0});
            }
        }

        for(int i=0; i<3; i++) {
            lli rem, new_cost, new_value;

            // decrease
            if(u.second >= op[i].first) {
                rem = u.second%op[i].first;
                new_cost = -u.first + rem*d + op[i].second;
                new_value = (u.second - rem) / op[i].first;
                if(cost.find(new_value) == cost.end() or new_cost < cost[new_value]) {
                    cost[new_value] = new_cost;
                    pq.push({-new_cost, new_value});
                }
            }

            // increase
            if(u.second%op[i].first != 0) {
                rem = u.second%op[i].first;
                new_cost = -u.first + ((op[i].first-rem)*d) + op[i].second;
                new_value = (u.second + (op[i].first-rem)) / op[i].first;
                if(cost.find(new_value) == cost.end() or new_cost < cost[new_value]) {
                    cost[new_value] = new_cost;
                    pq.push({-new_cost, new_value});
                }
            }
        }
    }
}

