ll A, B, C, D;
map<ll, ll> ma;

ll solve_sub(ll n)
{
	if (n == 0) return 0;
	if (ma.count(n)) return ma[n];
	ll res;
	if (n <= 3e9) res = n*D;
	else res = 1e18;

	for (ll i = -1; i <= 1; ++i)
	{
		ll x = n + i;
		if (x < 0 || x & 1) continue;
		ll y = x/2;
		if (y < n)
			res = min(res, abs(i)*D + A + solve_sub(y));
	}

	for (ll i = -2; i <= 2; ++i)
	{
		ll x = n + i;
		if (x < 0 || x % 3 != 0) continue;
		ll y = x/3;
		if (y < n)
			res = min(res, abs(i)*D + B + solve_sub(y));
	}

	for (ll i = -4; i <= 4; ++i)
	{
		ll x = n + i;
		if (x < 0 || x % 5 != 0) continue;
		ll y = x/5;
		if (y < n)
			res = min(res, abs(i)*D + C + solve_sub(y));
	}

	return ma[n] = res;
}

ll solve()
{
	ll N;
	cin >> N >> A >> B >> C >> D;
	ma.clear();
	return solve_sub(N);
}

