ll a,b,c,d;
ll n;
map <ll,ll> m;
ll fun(ll n)
{
    if(n==0)
    {
        return 0;
    }
    if(n==1)
    {
        return d;
    }
    if(m[n])
    {
        return m[n];
    }
    ll v[6];
    v[0]=(n/2)*2;
    v[1]=((n+1)/2)*2;
    v[2]=(n/3)*3;
    v[3]=((n+2)/3)*3;
    v[4]=(n/5)*5;
    v[5]=((n+4)/5)*5;
    ll res=1E18;
    if(res/n>=d)
    {
        res=n*d;
    }
    ll tp[6];
    tp[0]=abs(v[0]-n)*d+a+fun(v[0]/2);
    tp[1]=abs(v[1]-n)*d+a+fun(v[1]/2);
    tp[2]=abs(v[2]-n)*d+b+fun(v[2]/3);
    tp[3]=abs(v[3]-n)*d+b+fun(v[3]/3);
    tp[4]=abs(v[4]-n)*d+c+fun(v[4]/5);
    tp[5]=abs(v[5]-n)*d+c+fun(v[5]/5);
    return m[n]=min(*min_element(tp,tp+6),res);
}
