ll dp[65][65][65][2];
ll val[65][65][65][2];

void solve()
{
    ll n, a, b, c, d;
    scanf("%lld%lld%lld%lld%lld", &n, &a, &b, &c, &d);

    int i, j, k, m;
    for (i = 0; i <= 60; i++) {
        for (j = 0; j <= 60; j++) {
            for (k = 0; k <= 60; k++) {
                dp[i][j][k][0] = LINF;
                dp[i][j][k][1] = LINF;
            }
        }
    }

    ll ans = LINF;
    dp[0][0][0][0] = 0;
    val[0][0][0][0] = n;
    for (i = 0; i < 61; i++) {
        for (j = 0; j < 61; j++) {
            for (k = 0; k < 61; k++) {
                for (m = 0; m < 2; m++) {
                    if (dp[i][j][k][m] < LINF) {
                        ll tmp=val[i][j][k][m];
                        if ((double)dp[i][j][k][m] + (double)val[i][j][k][m] * d < LINF) {
                            ans = MIN(ans, dp[i][j][k][m] + val[i][j][k][m] * d);
                        }
                        if (tmp <= 0) {
                            continue;
                        }
                        {
                            ll tmp2 = tmp / 2;
                            if((double)dp[i][j][k][m] + (double)(tmp % 2)*d + a < LINF){
                                dp[i+1][j][k][0]=MIN(dp[i+1][j][k][0], dp[i][j][k][m] + (tmp % 2)*d + a);
                                val[i + 1][j][k][0] = tmp2;
                            }
                            if (tmp % 2 && (double)dp[i][j][k][m] + (double)(2-tmp % 2)*d + a <LINF) {
                                dp[i+1][j][k][1]=MIN(dp[i+1][j][k][1], dp[i][j][k][m] + (2-tmp % 2)*d + a);
                                val[i + 1][j][k][1] = tmp2+1;
                            }
                        }
                        {
                            ll tmp3 = tmp / 3;
                            if((double)dp[i][j][k][m] + (double)(tmp % 3)*d + a < LINF){
                                dp[i][j+1][k][0]=MIN(dp[i][j+1][k][0], dp[i][j][k][m] + (tmp % 3)*d + b);
                                val[i][j + 1][k][0] = tmp3;
                            }
                            if (tmp % 3 && (double)dp[i][j][k][m] + (double)(3-tmp % 3)*d + a <LINF) {
                                dp[i][j+1][k][1]=MIN(dp[i][j+1][k][1], dp[i][j][k][m] + (3-tmp % 3)*d + b);
                                val[i][j + 1][k][1] = tmp3 + 1;
                            }
                        }
                        {
                            ll tmp5 = tmp / 5;
                            if((double)dp[i][j][k][m] + (double)(tmp % 5)*d + a < LINF){
                                dp[i][j][k+1][0]=MIN(dp[i][j][k+1][0], dp[i][j][k][m] + (tmp % 5)*d + c);
                                val[i][j][k + 1][0] = tmp5;
                            }
                            if (tmp % 5 && (double)dp[i][j][k][m] + (double)(5-tmp % 5)*d + a <LINF) {
                                dp[i][j][k+1][1]=MIN(dp[i][j][k+1][1], dp[i][j][k][m] + (5-tmp % 5)*d + c);
                                val[i][j][k + 1][1] = tmp5+1;
                            }
                        }
                    }
                }
            }
        }
    }

    printf("%lld\n", ans);

    return;
}


