using namespace std;

long long a, b, c, d;
map<long long, long long> mp;

long long calc(long long n) {
    int i;
    long long ans = 1e18;

    if (mp.count(n)) return mp[n];
    if (n == 0) return mp[n] = 0;

    for (i = -1; i <= 1; i++) {
        if (n + i > 0 && (n + i) % 2 == 0 && (n + i) / 2 < n) ans = min(ans, calc((n + i) / 2) + a + abs(i) * d);
    }

    for (i = -2; i <= 2; i++) {
        if (n + i > 0 && (n + i) % 3 == 0 && (n + i) / 3 < n) ans = min(ans, calc((n + i) / 3) + b + abs(i) * d);
    }

    for (i = -4; i <= 4; i++) {
        if (n + i > 0 && (n + i) % 5 == 0 && (n + i) / 5 < n) ans = min(ans, calc((n + i) / 5) + c + abs(i) * d);
    }

    if (n <= ans / d) ans = min(ans, n * d);

    return mp[n] = ans;
}

