array<int, 101> factoring(int x) {
    array<int, 101> ret{};
    for (int i = 2; x >= i * i; i++) {
        while (x % i == 0) {
            ret[i]++;
            x /= i;
        }
    }
    if (x > 1) ret[x]++;
    return ret;
}
long long n, a, b, c, d, t;
map<long long, long long> memo;
long long func(long long x) {
    if (memo.count(x)) {
        return memo[x];
    }
    memo[x] = min({func(x / 2) + d * (x % 2) + a, func(x / 3) + d * (x % 3) + b, func(x / 5) + d * (x % 5) + c,
                   func((x + 1) / 2) + d * (x % 2) + a, func((x + 2) / 3) + d * (3 - x % 3) + b,
                   func((x + 4) / 5) + d * (5 - x % 5) + c});
    if (1ll * 1e12 / x < d) {
        memo[x] = min(memo[x], x * d);
    }
    return memo[x];
}
