		return 0;
	}

	ll res = (ll)1e18;

	if (c != 0) {
		int num = x % 5;

		if (num <= 2) {
			res = min(res, go(x / 5, a, b, c - 1) + num * d + cc);
		}
		else {
			res = min(res, go(x / 5 + 1, a, b, c - 1) + (5 - num) * d + cc);
		}
	}
	else if (b != 0) {
		int num = x % 3;

		if (num <= 1) {
			res = min(res, go(x / 3, a, b - 1, c) + num * d + bb);
		}
		else {
			res = min(res, go(x / 3 + 1, a, b - 1, c) + (3 - num) * d + bb);
		}
	}
	else if (a != 0) {
		int num = x % 2;

		res = min(res, go(x / 2, a - 1, b, c) + num * d + aa);
	}
	else {
		if (x <= (ll)1e18 / d) {
			res = x * d;
		}
	}

	return res;
}

