		for (int i = 0; i <= 65; i++) {
			for (int j = 0; j <= 65; j++) {
				for (int k = 0; k <= 65; k++) {
					res = min(res, go(n, i, j, k));
				}
			}
		}

		cout << res << '\n';
	}
}

