ll dfs(ll n) {
  if (n == 0) { return 0; }
  if (n == 1) { return d; }
  if (mp.find(n) != mp.end()) {
    return mp[n];
  }

  // Here, we skip
  ll res = INF;
  // try D(+/- 1)
  if (n < res/d) { // n*d < res
    chmin(res, n*d);
  }
  // try A,B,C
  rep(i,3) {
    ll cost = costs[i];
    ll num  = nums[i];
    {
      // floor
      ll t = n/num; // target
      ll now = dfs(t) + cost;
      now += abs(n-(num*t))*d;
      chmin(res,now);
    }
    {
      // ceil
      ll t = (n+num-1)/num; // target
      ll now = dfs(t) + cost;
      now += abs(n-(num*t))*d;
      chmin(res,now);
    }
  }
  return mp[n] = res;
}

