        }
        a = a * a;
        n >>= 1;
    }
    return x;
}


ll COM(int n, int k, const lvec &fac, const lvec &finv)
{
    if (n < k)
        return 0;
    if (n < 0 || k < 0)
        return 0;
    return (fac[n] * (finv[k] * finv[n - k] % MOD)) % MOD;
}

ll modinv(ll a, ll m)
{
    ll b = m, u = 1, v = 0;
    while (b)
    {
        ll t = a / b;
        a -= t * b;
        swap(a, b);
        u -= t * v;
        swap(u, v);
    }
    u %= m;
    if (u < 0)
        u += m;
    return u;
}

// union by size + path having
class UnionFind {
public:
    vector <ll> par; // 各元の親を表す配列
    vector <ll> siz; // 素集合のサイズを表す配列(1 で初期化)

    // Constructor
    UnionFind(ll sz_): par(sz_), siz(sz_, 1LL) {
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }
    void init(ll sz_) {
        par.resize(sz_);
        siz.assign(sz_, 1LL);  // resize だとなぜか初期化されなかった
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }

    // Member Function
    // Find
    ll root(ll x) { // 根の検索
        while (par[x] != x) {
            x = par[x] = par[par[x]]; // x の親の親を x の親とする
        }
        return x;
    }

    // Union(Unite, Merge)
    bool merge(ll x, ll y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        // merge technique（データ構造をマージするテク．小を大にくっつける）
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }

    bool issame(ll x, ll y) { // 連結判定
        return root(x) == root(y);
    }

    ll size(ll x) { // 素集合のサイズ
        return siz[root(x)];
    }
};

ll solve(ll a, ll b, ll c, ll d, ll n){
    map<ll, ll> m;
    m[0] = 0;
    m[1] = d;
    m[2] = m[1] + min(d, a);
    ll maxll = 1ll << 62;

    function<ll(ll)> dfs = [&](ll x){
        if(m.count(x)) return m[x];
        ll res = maxll;
        if(n < res/d) res = x*d;
        ll wa = min(dfs(x/2) + d*(x - 2*(x/2)) + a, dfs((x/2 + 1)) + d*((x/2 + 1)*2 - x) + a);
        ll wb = min(dfs(x/3) + d*(x - 3*(x/3)) + b, dfs((x/3 + 1)) + d*((x/3 + 1)*3 - x) + b);
        ll wc = min(dfs(x/5) + d*(x - 5*(x/5)) + c, dfs((x/5 + 1)) + d*((x/5 + 1)*5 - x) + c);
        res = min(res, wa);
        res = min(res, wb);
        res = min(res, wc);
        m[x] = res;
        return m[x];
    };
    dfs(n);

    return m[n];
}

