map<lint, lint> dp;
lint A, B, C, D;
void solve(lint N, lint cost) {
    if(dp.find(N) != dp.end()) {
        if (dp[N] <= cost) return;
    }
    dp[N] = cost;
    if(N <= 0) return;
    if(N == 1) {
        solve(0, cost+D);
        return;
    }
    if((double)cost + (double)N*(double)D < 1e18) solve(0, cost+N*D);
    if(N >= 2) solve(N/2, cost + (N%2)*D + A);
    if(N >= 3 && N%2 != 0) solve((N/2)+1, cost + (2-(N%2))*D + A);
    if(N >= 3) solve(N/3, cost + (N%3)*D + B);
    if(N >= 4 && N%3 != 0) solve((N/3)+1, cost + (3-(N%3))*D + B);
    if(N >= 5) solve(N/5, cost + (N%5)*D + C);
    if(N >= 6 && N%5 != 0) solve((N/5)+1, cost + (5-(N%5))*D + C);
}
