using ll = long long;

class Recursive
{
private:
    ll P1;
    std::map<int,ll> divmaps;
    std::map<ll,ll> memo;

    ll ff(ll n)
    {
        if (auto it = memo.find(n); it != memo.end()) return memo[n];

        ll ans = (n >= LLONG_MAX / P1) ? LLONG_MAX : n * P1;


        for (auto [div, T] : divmaps)
        {
            if (n >= div)
            {
                ll fp = ff(n/div);
                if (int m = n % div; m == 0)
                    ans = std::min(ans, fp + T);
                else
                {
                    ll fn = ff(n/div+1);
                    ans = std::min({ans, fp + T + P1 * m, fn + T + P1 * (div-m)});
                }
            }
        }

        return memo[n] = ans;
    }

public:
    Recursive(int A, int B, int C, int D)
    {
        divmaps[2] = A;
        divmaps[3] = B;
        divmaps[5] = C;
        P1 = D;
    }

    ll go(ll N)
    {
        return ff(N);
    }
};

