const ll inf = 1LL << 60;

// {0, positive, 1 negative }

ll n, a, b, c, d;
bool visited[61][41][31];
ll memo[61][41][31][2];

inline ll add(ll a, ll b) {
	if(a + b >= inf) {
		return inf;
	} else {
		return a + b;
	}
}


inline ll mul(ll a, ll b) {
	if (a == 0 or b == 0) return 0LL;

	if(a >= inf / b) {
		return inf;
	} else {
		return a * b;
	}
}

ll calc(ll ca, ll cb, ll cc) {
	ll ret = 1LL;
	rep(loop, ca) ret = mul(ret, 2LL);
	rep(loop, cb) ret = mul(ret, 3LL);
	rep(loop, cc) ret = mul(ret, 5LL);
	return ret;
}

