void solve(ll ca, ll cb, ll cc) {
	if (visited[ca][cb][cc]) return;
	visited[ca][cb][cc] = true;

	memo[ca][cb][cc][0] = inf;
	memo[ca][cb][cc][1] = inf;
	const ll coef = calc(ca, cb, cc);

	if(coef >= inf) {
		return;
	}

	const ll to[2] = {n % coef, n % coef - coef};
	rep(ti, 2) {
		const ll cost = mul(d, abs(n - to[ti]) / coef);
		chmin(memo[ca][cb][cc][ti], cost);
	}


	{
		const ll ncoef = calc(ca + 1, cb, cc);
		const ll from[2] = {n % ncoef, n % ncoef - ncoef};
		solve(ca + 1, cb, cc);
		rep(fi, 2) rep(ti, 2) {
			const ll cost = a + mul(d, abs(to[ti] - from[fi]) / coef);
			const ll nval = add(memo[ca + 1][cb][cc][fi], cost);
			chmin(memo[ca][cb][cc][ti], nval);
		}
	}

	{
		const ll ncoef = calc(ca, cb + 1, cc);
		const ll from[2] = {n % ncoef, n % ncoef - ncoef};
		solve(ca, cb + 1, cc);
		rep(fi, 2) rep(ti, 2) {
			const ll cost = b + mul(d, abs(to[ti] - from[fi]) / coef);
			const ll nval = add(memo[ca][cb + 1][cc][fi], cost);
			chmin(memo[ca][cb][cc][ti], nval);
		}
	}

	{
		const ll ncoef = calc(ca, cb, cc + 1);
		const ll from[2] = {n % ncoef, n % ncoef - ncoef};
		solve(ca, cb, cc + 1);
		rep(fi, 2) rep(ti, 2) {
			const ll cost = c + mul(d, abs(to[ti] - from[fi]) / coef);
			const ll nval = add(memo[ca][cb][cc + 1][fi], cost);
			chmin(memo[ca][cb][cc][ti], nval);
		}
	}
}

