	rep(loop, t) {
		cin >> n >> a >> b >> c >> d;
		rep(i, 61) rep(j, 41) rep(k, 31) visited[i][j][k] = false;
		solve(0, 0, 0);
		cout << memo[0][0][0][0] << endl;
	}

	return 0;
}

