const int64_t INF64 = int64_t(2e18) + 5;

int64_t N, A, B, C, D;
unordered_map<int64_t, int64_t> save;
set<int64_t> divisions;

int64_t evaluate(int a, int b, int c) {
    int64_t n = N;
    while (a-- > 0) n /= 2;
    while (b-- > 0) n /= 3;
    while (c-- > 0) n /= 5;
    return n;
}

int64_t closest(int64_t n) {
    int64_t dist = INF64;
    auto it = divisions.lower_bound(n);

    if (it != divisions.end())
        dist = min(dist, *it - n);

    if (it != divisions.begin()) {
        it--;
        dist = min(dist, n - *it);
    }

    return dist;
}

const int CUTOFF = 1;

int64_t solve(int64_t n) {
    if (n == 0)
        return 0;

    if (n == 1)
        return D;

    if (closest(n) > CUTOFF)
        return INF64;

    if (save.find(n) != save.end())
        return save[n];

    int64_t ans = (long double) D * n < INF64 ? D * n : INF64;

    ans = min(ans, n % 2 * D + A + solve(n / 2));
    ans = min(ans, n % 3 * D + B + solve(n / 3));
    ans = min(ans, n % 5 * D + C + solve(n / 5));

    if (n > 2) ans = min(ans, (2 - n % 2) * D + A + solve(n / 2 + 1));
    ans = min(ans, (3 - n % 3) * D + B + solve(n / 3 + 1));
    ans = min(ans, (5 - n % 5) * D + C + solve(n / 5 + 1));

    return save[n] = ans;
}

void run_case() {
    cin >> N >> A >> B >> C >> D;
    save.clear();
    divisions.clear();

    for (int a = 0; a <= 60; a++)
        for (int b = 0; b <= 40; b++)
            for (int c = 0; c <= 30; c++)
                divisions.insert(evaluate(a, b, c));

    cout << solve(N) << '\n';
}

