ll f(ll n){
    if(n == 0){ return 0; }
    if(n == 1){ return d; }
    if(cache.count(n)){ return cache[n]; }

    ll ret = numeric_limits<ll>::max();

    // div 2
    ret = min(
        ret,
        min(
            f((n + 1) / 2) + a + d * (n % 2),
            f(n / 2) + a + d * (n % 2)
        )
    );

    // div 3
    ret = min(
        ret,
        min(
            f((n + 2) / 3) + b + d * (3 - n % 3),
            f(n / 3) + b + d * (n % 3)
        )
    );

    // div 5
    ret = min(
        ret,
        min(
            f((n + 4) / 5) + c + d * (5 - n % 5),
            f(n / 5) + c + d * (n % 5)
        )
    );

    if(ret / d > n){
        ret = min(ret, n * d);
    }
    cache[n] = ret;
    return ret;
}

