long long A,B,C,D;
std::map<long long,long long> dp;

long long dfs(long long N){
    if(dp[N]!=0){
        return dp[N];
    }
    if(N<=0){
        return 0;
    }
    if(N==1){
        return D;
    }

    long long R = INF;
    if(N<INF/D){
        R = N*D;
    }

    //2 floor 
    R = std::min(R,A+D*(N%2)+dfs(N/2));

    //2 ceil
    if(N%2!=0){
        R = std::min(R,A+D*(2-N%2)+dfs(Ceil(N,2)));
    }

    //3 floor 
    R = std::min(R,B+D*(N%3)+dfs(N/3));

    //3 ceil
    if(N%3!=0){
        R = std::min(R,B+D*(3-N%3)+dfs(Ceil(N,3)));
    }

    //5 floor 
    R = std::min(R,C+D*(N%5)+dfs(N/5));

    //5 ceil
    if(N%5!=0){
        R = std::min(R,C+D*(5-N%5)+dfs(Ceil(N,5)));
    }

    dp[N]=R;
    return R;
}

