LL dfs(LL x) {
    if (x <= 1) return x * cost;

    if (dp[x]) return dp[x];

    LL mn = INF_LL;
    if (cost <= mn / x) mn = (LL) cost * x;
    for (auto v : op) {
        int p = v.fi, t = v.se;
        mn = min(mn, (LL) cost * (x % p) + t + dfs(x / p));
        if (x % p != 0) mn = min(mn, (LL) cost * (p - x % p) + t + dfs(x / p + 1));
    }

    return dp[x] = mn;
}

