int64_t dfs(int64_t x) {
	if (memo.count(x)) return memo[x];
	if (x == 0) return memo[0] = 0;
	if (x == 1) return memo[1] = d;
	int64_t res = 1000000000000000000;
	if (x & 1) {
		res = std::min({res, std::min<int64_t>(a + d, cost(x, x / 2)) + dfs(x / 2),
							 std::min<int64_t>(a + d, cost(x, x / 2 + 1)) + dfs(x / 2 + 1)});
	} else res = std::min(res, std::min<int64_t>(a, cost(x, x / 2)) + dfs(x / 2));
	int64_t next = x / 3;
	int amari = x % 3;
	if (3 - x % 3 < x % 3) amari = 3 - x % 3, next++;
	res = std::min(res, std::min(b + (int64_t) amari * d, cost(x, next)) + dfs(next));
