#include <bits/stdc++.h>
using namespace std;
typedef long long LL;

LL A, B, C, D;
map<LL,LL> m;


LL llmin(LL A, LL B) {
    if (A < B) return A;
    else return B;
}

LL solve(LL N) {
    if (N == 0) return 0;
    if (N == 1) return D;
    if (m.count(N)) return m[N];

    LL l2 = (N/2)*2;
    LL r2 = ((N+1)/2)*2;

    LL l3 = (N/3)*3;
    LL r3 = ((N+1)/3)*3;

    LL l5 = (N/5)*5;
    LL r5 = ((N+1)/5)*5;

    LL res = 1e18;
    if (N < res/D) res = N * D;

    res = llmin(res, llabs(l2-N)*D + A + solve(l2/2));
    res = llmin(res, llabs(r2-N)*D + A + solve(r2/2));

    res = llmin(res, llabs(l3-N)*D + B + solve(l3/2));
    res = llmin(res, llabs(r3-N)*D + B + solve(r3/2));

    res = llmin(res, llabs(l5-N)*D + C + solve(l5/2));
    res = llmin(res, llabs(r5-N)*D + C + solve(r5/2));

    m[N] = res;

    return res;
}

