using namespace std;

map<long long, long long> memo;
long long A;
long long B;
long long C; 
long long D;

long long rec(long long N){
    long long ans;

    if( memo.count(N) > 0 ){
        return memo[N];
    }

    if(N == 0){
        ans = 0;
        return memo[N] = ans; 
    }

    if(N == 1){
        ans = D;
        return memo[N] = ans; 
    }

    //2
    ans = ( (rec(N/2) + A) + (N%2) * D);
    if(N %2 != 0){
        ans = min(ans, ( (rec(N/2+1) + A) + ((N/2+1)*2- N)*D ) );
    }
    //3
    ans = min(ans, ( (rec(N/3) + B) + (N%3) * D) );
    if(N%3 != 0){
        ans = min(ans, ( (rec(N/3+1) + B) + ((N/3+1)*3- N)*D ) );
    }
    //5
    ans = min(ans, ( (rec(N/5) + C) + (N%5) * D) );
    if(N%5 != 0){
        ans = min(ans, ( (rec(N/5+1) + C) + ((N/5+1)*5- N)*D ) );
    }

    return memo[N] = ans; 
}


int main(){
    long long N;
    cin >> N >> A >> B >> C >> D;

    long long ans;
