using namespace std;
typedef long long ll;
const double PI = acos(-1.0);
const double eps = 1e-6;
const ll INF = 5e18;
const int MAXN = 1e5 + 10;
ll T, n, S[5], s[5];            //S[]是代价，s[]是金额
map<ll, ll> mp;
ll f(ll x)
{
    if(x == 0)  return 0;
    else if(x == 1) return S[4];
    if(mp[x]) return mp[x];
    ll ret = INF;
    if(ret / S[4] > x) ret = S[4] * x;  //如果直接ret = S[4] * x 会爆LL
    for(int i = 1; i <= 3; i++)
    {
        if(x % s[i] == 0)
            ret = min(ret, f(x / s[i]) + S[i]);
        else 
        {
            ll up = x / s[i] * s[i];                   //向下
            ll co = (x - up) * S[4];
            ret = min(ret, f(x / s[i]) + S[i] + co);
            up = (x / s[i] + 1) * s[i];
            co = (up - x) * S[4];
            ret = min(ret, f(x / s[i]) + S[i] + co);
        }
    }
    return mp[x] = ret;
}

