ll n, a, b, c, d;
map<ll, ll> memo; 

ll solve(ll x) {
    if (!x) return 0;
    if (x == 1) return d;

    if (memo.count(x)) return memo[x];

    ll l2 = (x / 2) * 2;
    ll r2 = ((x + 1) / 2) * 2;
    ll l3 = (x / 3) * 3;
    ll r3 = ((x + 2) / 3) * 3;
    ll l5 = (x / 5) * 5;
    ll r5 = ((x + 4) / 5) * 5;

    ll res = 1e18;
    if (x < res / d) res = x * d;

    res = min(res, llabs(x - l2) * d + a + solve(l2 / 2));
    res = min(res, llabs(x - r2) * d + a + solve(r2 / 2));

    res = min(res, llabs(x - l3) * d + b + solve(l3 / 3));
    res = min(res, llabs(x - r3) * d + b + solve(r3 / 3));

    res = min(res, llabs(x - l5) * d + c + solve(l5 / 5));
    res = min(res, llabs(x - r5) * d + c + solve(r5 / 5));

    memo[x] = res;
    return res;
}

