  }
  if(solve(n/3)<INF){
    ret = min(ret, d*(n%3)+b+solve(n/3));
  }
  if(solve((n/3)+1)<INF){
    ret = min(ret, d*(3-(n%3))+b+solve((n/3)+1));
  }
  if(solve(n/5)<INF){
    ret = min(ret, d*(n%5)+c+solve(n/5));
  }
  if(solve((n/5)+1)<INF){
    ret = min(ret, d*(5-(n%5))+c+solve((n/5)+1));
  }
  if((INF/d)>abs(n)) ret = min(ret, d*abs(n));
  auto itr = mp.find(n);
  (*itr).second = ret;
  return ret;
}

