const ll INF = (ll) 1e18;
//const ld PI = acos(-1L);
//
ll a, b, c, d;

ll calc(ll n, unordered_map<ll, ll>& cache) {
    if (cache.find(n) != cache.end()) return cache.at(n);
    ll ans = INF;
    if ((ld) n * (ld) d < (ld) INF) ans = n * d;

    if (n % 2 == 0) {
        ll ca = calc(n / 2LL, cache) + a;
        ans = min(ans, ca);
    }
    else {
        ll ca = min(calc(n / 2LL, cache) + a + d, calc(n / 2LL + 1, cache) + a + d);
        ans = min(ans, ca);
    }

    if (n % 3 == 0) {
        ll ca = calc(n / 3LL, cache) + b;
        ans = min(ans, ca);
    }
    else {
        ll D = n % 3;
        ll U = 3 - D;
        ll ca = min(calc(n / 3LL, cache) + b + D*d, calc(n / 3LL + 1, cache) + b + U*d);
        ans = min(ans, ca);
    }

    if (n % 5 == 0) {
        ll ca = calc(n / 5LL, cache) + c;
        ans = min(ans, ca);
    }
    else {
        ll D = n % 5;
        ll U = 5 - D;
        ll ca = min(calc(n / 5LL, cache) + c + D*d, calc(n / 5LL + 1, cache) + c + U*d);
        ans = min(ans, ca);
    }

    cache.insert(make_pair(n, ans));
    out(n << ' ' << ans);
    return ans;
}

