typedef pair<li, li> PI;

inline void solve() {
    li n, a, b, c, d;
    cin >> n >> a >> b >> c >> d;

    map<li, li> memo;

    // cost, pos
    priority_queue<PI> pq;

    auto try_push = [&](li cost, li prev, li prev_cost, li num) {
        if ((abs(prev - num)*d) / d == abs(prev - num) && prev_cost + abs(prev - num)*d >= 0) {
            cost = min(cost, prev_cost + abs(prev - num) * d);
        }
        if (memo.count(num) == 0 || memo[num] > cost) {
            pq.push({ -cost, num});
        }
    };
    pq.push({0, n});
    li res = bit(62);
    while (!pq.empty()) {
        li now = pq.top().S;
        li now_cost = -pq.top().F;
        pq.pop();
        if (memo.count(now) > 0 && memo[now] <= now_cost) {
            continue;
        }
        memo[now] = now_cost;
        if (d * now / d == now && d * now + now_cost >= 0) {
            pq.push({ -d * now - now_cost, 0});
        }
        //p2(now, now_cost);
        if (now == 0) {
            cout << now_cost << endl;
            return;
        }
        if (now % 2 == 0) {
            try_push(now_cost + a, now, now_cost, now / 2);
        } else {
            try_push(now_cost + a + d, now, now_cost,  now / 2);
            try_push(now_cost + a + d, now, now_cost,  now / 2 + 1);
        }
        if (now % 3 == 0) {
            try_push(now_cost + b, now, now_cost,  now / 3);
        } else {
            li amari = now % 3;
            try_push(now_cost + b + d * amari, now, now_cost,  now / 3);
            try_push(now_cost + b + d * (3 - amari), now, now_cost,  now / 3 + 1);
        }
        if (now % 5 == 0) {
            try_push(now_cost + c, now, now_cost,  now / 5);
        } else {
            li amari = now % 5;
            try_push(now_cost + c + d * amari, now, now_cost,  now / 5);
            try_push(now_cost + c + d * (5 - amari), now, now_cost,  now / 5 + 1);
        }
    }
}

int main() {
    li t;
    cin >> t;
    rep(i, t) {
        solve();
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
static const long long MAX=1000000000000000;

long long solve(long long N,long long A, long long B, long long C,long long D){
  long long lmaxdif=MAX;
  long long rmaxdif=MAX;
  long long temp;
  long long ri=0,rj=0,rk=0,li=0,lj=0,lk=0;
  for(long long i=0;i<62;i++){
    if(pow(2,i)>N+MAX) break;
    for(long long j=0;j<42;j++){
      if(pow(2,i)*pow(3,j)>N+MAX) break;   
      for(long long k=0;k<32;k++){
        temp=pow(2,i)*pow(3,j)*pow(5,k);
        //cout<<temp<<endl;
        if(temp>N+MAX) break; 
        if(temp>=N && temp-N<rmaxdif){
          //cout<<"R"<<temp<<" "<<temp-N<<endl;
          rmaxdif=temp-N;
          ri=i;
          rj=j;
          rk=k;
        }
        if(temp<=N && N-temp<lmaxdif){
          //cout<<"L"<<temp<<" "<<N-temp<<endl;
          lmaxdif=N-temp;
          li=i;
          lj=j;
          lk=k;
        }
      }
    }
  }
  long long ans=min(A*ri+B*rj+C*rk+D*rmaxdif,A*li+B*lj+C*lk+D*lmaxdif);
  //cout<<ri<<" "<<rj<<" "<<rk<<" "<<li<<" "<<lj<<" "<<lk<<endl;
  //cout<<"#1"<<A*ri+B*rj+C*rk+D*rmaxdif<<endl;
  //cout<<"#2"<<A*li+B*lj+C*lk+D*lmaxdif<<endl;
  //cout<<lmaxdif<<" "<<rmaxdif<<endl;
  return ans+D;
}

int main(){
  int T;
  cin>>T;
  long long N,A,B,C,D;
  for(int i=0;i<T;i++){
    cin>>N>>A>>B>>C>>D;
    cout<<solve(N,A,B,C,D)<<endl;
  }
  return 0;
}

