map<ll,__int128> dp;
ll dfs(ll val)
{
    if(val==0) return 0;
    if(dp.count(val)) return dp[val];
    __int128 ret=1e18;
    ret=min(ret,dfs(val/2)+min<__int128>(val%2*d+a,(__int128)(val-val/2)*d));
    ret=min(ret,dfs(val/3)+min<__int128>(val%3*d+b,(__int128)(val-val/3)*d));
    ret=min(ret,dfs(val/5)+min<__int128>(val%5*d+c,(__int128)(val-val/5)*d));
    if((val+1)/2!=val)
    {
        ll dis=(val+1)/2*2-val;
        ret=min(ret,dfs((val+1)/2)+min((__int128)dis*d+a,(__int128)(val-(val+1)/2)*d));
    }
    if((val+2)/3!=val)
    {
        ll dis=(val+2)/3*3-val;
        ret=min(ret,dfs((val+2)/3)+min((__int128)dis*d+b,(__int128)(val-(val+2)/3)*d));
    }
    if((val+4)/5!=val)
    {
        ll dis=(val+4)/5*5-val;
        ret=min(ret,dfs((val+4)/5)+min((__int128)dis*d+c,(__int128)(val-(val+4)/5)*d));
    }
    return dp[val]=ret;
}
