map<ll, bool> used;
map<ll, ll>memo;
ll calc(ll n) {
	if (n == 0)return 0;
	if (used[n])return memo[n];
	used[n] = true;
	ll x1, x2, y1, y2, z1, z2;
	x1 = x2 = y1 = y2 = z1 = z2 = INF;
	x1 = calc(n / 2) + a + d * (n % 2);
	if(n/2+1<n)x2 = calc(n / 2 + 1) + a + d * (2 - n % 2);

	y1 = calc(n / 3) + b + d * (n % 3);
	y2 = calc(n / 3 + 1) + b + d * (3 - n % 3);
	z1 = calc(n / 5) + c + d * (n % 5);
	z2 = calc(n / 5 + 1) + c + d * (5 - n % 5);
	ll res = min({ x1,x2,y1,y2,z1,z2 });
	if (INF / d >= n) {
		res = min(res, d*n);
	}
	return memo[n] = res;
}

