map<ll,ll> dis;

ll dfs(ll n)
{
	if(dis.find(n) != dis.end()) return dis[n];

	ll res = linf;
	if(n <= res/d) res = n*d;

	for(int i=0; i<3; ++i)
	{
		int p = ::p[i];
		ll cost = ::cost[i];

		chk_min(res, dfs(n/p) + cost + n%p * d);
		if(n%p) chk_min(res, dfs(n/p+1) + cost + (p-n%p) * d);
	}
	return dis[n] = res;
}

