	for (int _t = 0; _t < T; _t++) {
		ll N; cin >> N;
		ll A, B, C, D; cin >> A >> B >> C >> D;

		ll ans = 1LL << 60;

		{
			ll N1 = N;
			ll temp = 0;
			while (N1 > 0) {
				if (N1 % 2 == 1) {
					temp += D;
					if (N1 == 1) { break; }
				}
				temp += A;
				N1 /= 2;
			}
			ans = temp;
		}

		ll nmin = N, temp = 0;

		set<pair<ll, ll>, greater<pair<ll, ll>>> st;
		st.insert({ N, 0 });
		while (st.size() > 0) {
			auto itr = st.begin();
			auto p = *itr;
			st.erase(itr);

			if (((1LL << 60) - p.second) / D + 3 > p.first) {
				chmin(ans, p.first * D + p.second);
			}

			for (ll i = -4; i <= 4; i++) {
				ll M = p.first + i;
				if (M < 0) { continue; }
				ll k = abs(i);
				ll X = D * k;
				if (M == 0) {
					chmin(ans, p.second + X);
					continue;
				}
				if (k <= 1 && M % 2 == 0) {
					if (k + (A / D + 1) < p.first - M / 2) {
						if (nmin >= M / 2 || p.second + X + A <= temp) {
							st.insert({ M / 2, p.second + X + A });
