							st.insert({ M / 3, p.second + X + B });
							if (nmin > M / 3) {
								temp = p.second + X + B;
							}
						}
					}
				}
				if (k <= 4 && M % 5 == 0) {
					if (k + (C / D + 1) < p.first - M / 5) {
						if (nmin >= M / 5 || p.second + X + C <= temp) {
							st.insert({ M / 5, p.second + X + C });
							if (nmin > M / 5) {
								temp = p.second + X + C;
							}
						}
					}
				}
			}
		}

