ll rec(ll cur, map<ll, ll> &mp) {
  auto itr = mp.find(cur);
  if (itr != mp.end()) {
    return itr->second;
  }
  ll ans = numeric_limits<ll>::max();

  // 一番近い倍数だけチェックすればOK(そうでない場合は、遷移した先で1動かしたほうが得)
  REP(i, 3) {
    ll next, diff, cost;
    if (cur % ary[i] == 0) {
      next = cur / ary[i];
      diff = cur - next;
      // d*diffのオーバーフロー対策
      cost = diff < (ll)2e9 / d ? min(c[i], d * diff) : c[i];
      chmin(ans, rec(next, mp) + cost);
      continue;
    }
    next = (cur - cur % ary[i]) / ary[i];
    diff = cur - next;
    cost = (diff < (ll)2e9 / d ? min(c[i], d * diff) : c[i]) + (cur % ary[i]) * d;
    chmin(ans, rec(next, mp) + cost);

    next = (cur + ary[i] - cur % ary[i]) / ary[i];
    diff = cur - next;
    cost = (diff < (ll)2e9 / d ? min(c[i], d * diff) : c[i]) + (ary[i] - (cur % ary[i])) * d;
    chmin(ans, rec(next, mp) + cost);
  }
  mp.insert({cur, ans});
  return mp[cur];
}

