  int n,a,b,c,d;
  cin >> n >> a >> b >> c >> d;
  PQi pq;
  pq.push(n);
  int ans = INF;
  map<int,int> tmp;
  tmp[n] = 0;

  auto chmin = [&] (int p,int q) {
    if(tmp[p] == 0) {
      tmp[p] = INF;
      pq.push(p);
    }
    tmp[p] = min(tmp[p],q);
  };

  Vi Z = {2,3,5};
  Vi costv = {a,b,c};

  while(!pq.empty()){
    int now = pq.top();
    pq.pop();
    if(now==0) break;

    int cost = tmp[now];
    int add = cost + d*now;
    if(add < 0) add = INF;

    //cerr << now << ' '<< cost << endl;

    ans = min(ans,add);

    rep(i,0,3){
      int wa = Z[i];
      if(now%wa==0){
        int qw = cost + costv[i];
        if(qw < 0) qw = INF;
        chmin(now/wa,qw);
      }
      else {
        int am = now%wa;
        int L = now - am;
        int R = L + wa;
        int qw;
        qw = costv[i] + d * am + cost;
        if(qw < 0) qw = INF;
        chmin(L/wa,qw);
        qw = costv[i] + d * (wa-am) + cost;
        if(qw < 0) qw = INF;
        chmin(R/wa,qw);
      }
    }

  }

  cout << ans << endl;
}

