array<long long, 3> dv = {2ll, 3ll, 5ll};
vector<long long> cost(3);
long long solve()
{
    long long n, add;
    cin >> n >> cost[0] >> cost[1] >> cost[2] >> add;
    // agora quero saber qual a forma mais barata de chegar de n ate 1

    unordered_map<long long, long long> memo;
    memo[0ll] = 0ll; 
    memo[1ll] = add;
    // nunca vou chamar a recursao para cima, porque ai vai dar merda!!!

    function<long long(long long)> recur = [&] (long long val) 
    {
        if(memo.count(val)) return memo[val];
        long long ans = linf;
        for(int i = 0; i < 3; ++i) {
            if(val % dv[i] == 0) {
                long long nxt = val / dv[i];
                long long delta = val - nxt;
                long long price = cost[i];
                if(delta < MOD) price = min(price, delta * add);
                ans = min(ans, recur(nxt) + price);
            }
            else
            {
                // ai vamos ter duas solucoes, chamar pra cima e chamar pra baixo
                // pra baixo...
                long long nxt = val / dv[i];
                long long delta = val - nxt;
                long long price = cost[i] + (val % dv[i]) * add;
                if(delta < MOD) price = min(price, delta * add);
                ans = min(ans, recur(nxt) + price);

                // pra cima...
                nxt = val / dv[i] + 1;
                delta = val - nxt;
                price = cost[i] + (dv[i] - (val % dv[i])) * add;
                if(delta < MOD) price = min(price, delta * add);
                ans = min(ans, recur(nxt) + price);
            }
        }
        return memo[val] = ans;
    };
    recur(n);
    return memo[n];
}

