inline LL dfs(LL x)
{
	if(f.count(x)) return f[x];
	LL res;
	if(1.0 * x * D < (double)INF) res = x * D;
	else res = INF;
	res = min(res, dfs(x / 2) + A + (x % 2) * D);
	if(x % 2) res = min(res, dfs(x / 2 + 1) + A + (2 - x % 2) * D);
	res = min(res, dfs(x / 3) + B + (x % 3) * D);
	if(x % 3) res = min(res, dfs(x / 3 + 1) + B + (3 - x % 3) * D);
	res = min(res, dfs(x / 5) + C + (x % 5) * D);
	if(x % 5) res = min(res, dfs(x / 5 + 1) + C + (5 - x % 5) * D);
	return f[x] = res;
}

