ll dfs(ll n, unordered_map<ll, ll> &f, ll a, ll b, ll c, ll d) {
    if (f.count(n))
        return f[n];
    auto &g = f[n];
    if (n == 0)
        g = 0;
    elif (n == 1) g = d;
    else {
        g = inf<ll>();
        if (n < 1e18 / d)
            tmin(g, n * d);
        tmin(g, dfs(n / 2, f, a, b, c, d) + a + abs(n / 2 * 2 - n) * d);
        if (n % 2)
            tmin(g, dfs(n / 2 + 1, f, a, b, c, d) + a +
                        abs(n / 2 * 2 + 2 - n) * d);
        tmin(g, dfs(n / 3, f, a, b, c, d) + b + abs(n / 3 * 3 - n) * d);
        if (n % 3)
            tmin(g, dfs(n / 3 + 1, f, a, b, c, d) + b +
                        abs(n / 3 * 3 + 3 - n) * d);
        tmin(g, dfs(n / 5, f, a, b, c, d) + c + abs(n / 5 * 5 - n) * d);
        if (n % 5)
            tmin(g, dfs(n / 5 + 1, f, a, b, c, d) + c +
                        abs(n / 5 * 5 + 5 - n) * d);
    }
    return g;
}
