    while (T--) {
        ll n, a, b, c, d;
        cin>>n>>a>>b>>c>>d;

        map<ll, ll> memo;
        ll cnt = 0;

        auto dfs = [&](auto dfs, ll x)->ll {
            if(x==0){
                return memo[x] = 0;
            }
            if(x==1){
                return memo[x] = d;
            }
            if(x==2){
                return memo[x] = min(d*2,d+c);
            }
            if(x==3){
                return memo[x] = min(d*3,d+b);
            }
            if(memo.count(x) > 0) {
                return memo[x];
            }
            if(x > 5*n){
                return  INF;
            }

            ll res = INF;
            if(x <= 1e9){
                res = d*x;
            }

            ll da = x%2;
            ll db = x%3;
            ll dc = x%5;

            ll c1 = (x-dc+5)/5;
            ll c2 = (x-dc)/5;

            if(memo.count(c1)==0){
                chmin(res, (5-dc)*d + c + dfs(dfs, c1));
            }else{
                chmin(res, (5-dc)*d + c + memo[c1]);
            }

            if(memo.count(c2)==0){
                chmin(res, dc*d + c+dfs(dfs, c2));
            }else{
                chmin(res, dc*d + c + memo[c2]);
            }

            ll b1 = (x-db+3)/3;
            ll b2 = (x-db)/3;

            if(memo.count(b1)==0) {
                chmin(res, (3-db)*d+b+dfs(dfs, b1));
            } else{
                chmin(res, (3-db)*d+b+memo[b1]);
            }

            if(memo.count(b2)==0) {
                chmin(res, db*d+b+dfs(dfs, b2));
            }else{
                chmin(res, db*d+b+memo[b2]);
            }

            ll a1 = (x-da+2)/2;
            ll a2 = (x-da)/2;

            if(memo.count(a1)==0) {
                chmin(res, (2-da)*d+ a +dfs(dfs, (x-da+2)/2));
            }else{
                chmin(res, (2-da)*d+ a +memo[a1]);
            }

            if(memo.count(a2)==0) {
                chmin(res, da*d + a +dfs(dfs, (x-da)/2));
            }else{
                chmin(res, da*d + a + memo[a2]);
            }

            return memo[x] = res;
        };

        out(dfs(dfs, n));

    }
    return 0;
}

