ll chg(ll x)
{
    if(x==0) return 0;
    if(x==1) return d;
    if(cc[x]) return cc[x];
    ll res = 1e18;
    if(x<res/d) res = x*d;
    res = min(res,chg(x/2) + (x%2)*d + a);
    if(x>2&&x%2)res = min(res,chg(x/2+1) + (2 - x%2) * d + a);
    if(x%3<2)res = min(res,chg(x/3) + (x%3)*d + b);
