			if (top.first == 0) break;
			if (min_cost[top.first] != top.second) continue;
			for (auto i = 0; i < costs.size(); ++i) {
				const auto m = multipier[i];
				const auto cost = costs[i];
				auto upper = (top.first + m - 1) / m;
				auto lower = top.first / m;
				auto diff = d * std::abs(top.first - upper * m);
				if (diff + cost + top.second < max && (min_cost.find(upper) == min_cost.end() || min_cost[upper] > diff + cost + top.second)) {
					min_cost[upper] = diff + cost + top.second;
					queue.emplace(upper, diff + cost + top.second);
				}
				diff = d * std::abs(top.first - lower * m);
				if (diff + cost + top.second < max && (min_cost.find(lower) == min_cost.end() || min_cost[lower] > diff + cost + top.second)) {
					min_cost[lower] = diff + cost + top.second;
					queue.emplace(lower, diff + cost + top.second);
				}
				if (lower == 0 && (min_cost.find(lower) == min_cost.end() || min_cost[lower] > diff + top.second)) {
					min_cost[lower] = diff + top.second;
					queue.emplace(lower, diff + top.second);
				}
			}
		}
		std::cout << min_cost[0] << '\n';
	}
}

