template<class T>
void chmin (T &a, T b) {
    if (a > b) a = b;
}

long long a, b, c, d;
map<long long, long long> mp;
const long long INF = (1LL << 60);

long long dfs (long long n) {
    if (n == 0) return 0;
    if (n == 1) return d;
    if (mp.count(n)) return mp[n];
    long long ret = INF;
    if (n < INF / d) chmin(ret, n * d);
    for (int i = 0; i < 3; i++) {
        long long t = vector{2LL, 3LL, 5LL}[i];
        long long cost = vector{a, b, c}[i];
        if (n % t == 0) {
            chmin(ret, cost + dfs(n / t));
        } else {
            long long l = n / t * t, r = l + t;
            chmin(ret, cost + d * (n - l) + dfs(n / t));
            chmin(ret, cost + d * (r - n) + dfs(n / t + 1));
        }
    }
    return mp[n] = ret;
}

