using namespace std;
int64_t A, B, C, D;
unordered_map<int64_t, int64_t> memo;

int64_t solve(int64_t N) {
  if (N == 0)
    return 0;
  else if (N == 1)
    return D;
  if (memo.count(N)) return memo[N];

  int64_t ret = INT64_MAX;
  if (N < ret / D) ret = N * D;

  vector<int64_t> coin = {2, 3, 5};
  vector<int64_t> cost = {A, B, C};
  rep(i, 3) {
    int64_t m = coin[i];
    int64_t ln = N / m;
    int64_t rn = (N + 1) / m;
    ret = min(ret, abs(ln * m - N) * D + cost[i] + solve(ln));
    ret = min(ret, abs(rn * m - N) * D + cost[i] + solve(rn));
  }
  return memo[N] = ret;
}

int main(void) {
  ios::sync_with_stdio(false);
  int T;
  cin >> T;
  vector<int64_t> answer(T);
  rep(i, T) {
    int64_t N;
    cin >> N >> A >> B >> C >> D;
    memo.clear();
    answer[i] = solve(N);
  }
  rep(i, T) { cout << answer[i] << endl; }
  return 0;
}

