long long go(long long n)
{
	auto I = res.find(n);
	if (I != res.end()) return I->second;
	auto& r = res[n];

	r = 9e18;
	if (9e18 / d >= n) r = d * n;

	for (int k = 0; k < 3; k++){
		long long np = n / p[k];
