void sub(ll n, ll a, ll b, ll c, ll d) {
    // 0 を始点にグラフを構築する？ -> だめ?
    // BFS してみる
    um<ll, ll> dp; // たどり着いた数，0からそこに至るまでの最小コイン枚数
    dp[0] = 0;
    dp[1] = d;
    auto keyin = [&dp](ll key) { return dp.find(key) != dp.end(); };

    auto dfs = [&](auto &&dfs, ll num) -> ll {
        if (keyin(num)) return dp[num];
        // dump(num);

        ll ret = INF;
        REPM(dif, -1, 1) {
            ll cnum = num + dif;
            if (cnum % 2 == 0) {
                if (cnum > 0)
                    chmin(ret, dfs(dfs, cnum / 2) + a + d * abs(dif));
                else if (cnum == 0)
                    chmin(ret, d * abs(dif));
            }
        }
        REPM(dif, -2, 2) {
            ll cnum = num + dif;
            if (cnum % 3 == 0) {
                if (cnum > 0)
                    chmin(ret, dfs(dfs, cnum / 3) + b + d * abs(dif));
                else if (cnum == 0)
                    chmin(ret, d * abs(dif));
            }
        }
        REPM(dif, -4, 4) {
            ll cnum = num + dif;
            if (cnum % 5 == 0) {
                if (cnum > 0)
                    chmin(ret, dfs(dfs, cnum / 5) + c + d * abs(dif));
                else if (cnum == 0)
                    chmin(ret, d * abs(dif));
            }
        }
        if ((ld)d * (ld)num < ret) chmin(ret, d * num);
        return dp[num] = ret;
    };
    cout << dfs(dfs, n) << endl;
}

