long long solve (long long N)
{
    if (mp.count (N))
        return mp[N];
    long long best = INF;
    if (N <= INF / D)
        best = 1LL * N * D;
    for (int i=-4; i<=4; i++)
        if (N - i >= 0)
        {
            long long M = N - i, xtra = 1LL * D * modul (i);
            if (M % 2 == 0 && -1 <= i && i <= 1)
            {
                long long curr = add (solve (M / 2), add (A, xtra));
                if (curr < best)
                    best = curr;
            }
            if (M % 3 == 0 && -2 <= i && i <= 2)
            {
                long long curr = add (solve (M / 3), add (B, xtra));
                if (curr < best)
                    best = curr;
            }
            if (M % 5 == 0)
            {
                long long curr = add (solve (M / 5), add (C, xtra));
                if (curr < best)
                    best = curr;
            }
        }
    mp[N] = best;
    return best;
}

