ll dfs(ll n){
  if(n==0)return memo[0]=0;
  if(n==1)return memo[1]=d;
  if(memo.count(n))return memo[n];
  ll d2,u2;
  d2 = n+2-n%2;
  u2 = n+n%2;
  ll d3,u3;
  d3 = n+3-n%3;
  u3 = n+n%3;
  ll d5,u5;
  d5 = n+5-n%5;
  u5 = n+n%5;
  ll res = INF;
  if(n<res/d)res=n*d;
  if(n%2==0)chmin(res,dfs(n/2)+a);
  else{
    chmin(res,dfs(d2/2)+abs(n-d2)*d+a);
    chmin(res,dfs(u2/2)+abs(n-u2)*d+a);
  }
  if(n%3==0)chmin(res,dfs(n/3)+b);
  else{
    chmin(res,dfs(d3/3)+abs(n-d3)*d+b);
    chmin(res,dfs(u3/3)+abs(n-u3)*d+b);
