  if(n%5==0)chmin(res,dfs(n/5)+c);
  else{
    chmin(res,dfs(d5/5)+abs(n-d5)*d+c);
    chmin(res,dfs(u5/5)+abs(n-u5)*d+c);
  }
  return memo[n] = res;
}

