ll solve(ll x){
  if(x <= 1) return x*d;
  if(dp.count(x)) return dp[x];

  ll res = LLONG_MAX;
  if(x < res/d) res = x*d;

  for(int i=0; i<3; i++){
    ll bwh = (x/dvs[i])*dvs[i];
    ll atas = ((x+dvs[i]-1)/dvs[i])*dvs[i];
