const long long INF = 0x3f3f3f3f3f3f3f3fll;

long long n, A, B, C, D;

std::map<long long, long long> f;

long long calc(long long n, int v) {
	long long dn = n - n / v;
	long long t = v == 2 ? A : (v == 3 ? B : C);
	if (dn > INF / D) {
		return t;
	} else {
		return std::min(t, dn * D);
	}
}

long long DP(long long n) {
	if (n == 0) {
		return 0;
	}
	if (n == 1) {
		return D;
	}
	if (f.count(n)) {
		return f[n];
	}
	long long ans = INF;
	for (int v : {2, 3, 5}) {
		int d = n % v;
		ans = std::min(ans, DP((n - d) / v) + D * d + calc(n - d, v));
		d = (v - d) % v;
		ans = std::min(ans, DP((n + d) / v) + D * d + calc(n + d, v));
	}
	return f[n] = ans;
}

void solve() {
	read(n), read(A), read(B), read(C), read(D);
	f.clear();
	print(DP(n));
}

int main() {
	int T = 1;
	read(T);
	while (T--) {
		solve();
	}
}

