bool unite (sll v, sll u) {
	v = find(v);
	u = find(u);

	if (v == u) return false;

	if (size[v] < size[u]) {
		ull tmp = v;
		v = u;
		u = tmp;
	}
	size[v] += size[u];
	parent[u] = v;
	return true;
}

