                else dp[m / 2] = dp[m] + a + d;
                que.push(m / 2);
                if(dp[m / 2 + 1]) dp[m / 2 + 1] = min(dp[m / 2 + 1], dp[m] + a + d);
                else dp[m / 2 + 1] = dp[m] + a + d;
                que.push(m / 2 + 1);
