long long int Search(map<long long int, long long int >&mp, long long int num) {
	//cout << num << endl;
	if (mp.find(num) != mp.end()) {
		return mp[num];
	}
	long long int ret = MOD * MOD;
	for (int i = -4; i <= 4; i++) {
		long long int nx = num + i;
		if (nx < 0)continue;
		if (nx == 0) {
