		}
		if (nx&&nx % 2 == 0 && nx / 2 < num) {
			ret = min(ret, Search(mp, nx / 2) + a + abs(i)*d);
		}
		if (nx&&nx % 3 == 0 && nx / 3 < num) {
			ret = min(ret, Search(mp, nx / 3) + b + abs(i)*d);
		}
		if (nx&&nx % 5 == 0 && nx / 5 < num) {
			ret = min(ret, Search(mp, nx / 5) + c + abs(i)*d);
		}
	}
	if (num < ret / d)mp[num] = num * d;
	else mp[num] = ret;
	return mp[num];
}

