ll N, A, B, C, D;

ll rec(ll N, map<ll, ll> &dp) {
    if(dp.count(N))
        return dp[N];
    if(N == 1) {
        return dp[N] = D;
    } else if(N == 0) {
        return dp[N] = 0;
    }
    ll l2 = (N / 2) * 2;
    ll u2 = ((N + 1) / 2) * 2;
    ll l3 = (N / 3) * 3;
    ll u3 = ((N + 2) / 3) * 3;
    ll l5 = (N / 5) * 5;
    ll u5 = ((N + 4) / 5) * 5;

    ll ret = LINF;
    if(LINF / D > N)
        ret = N * D;
    ret = min(ret, rec(l2 / 2, dp) + A + abs(N - l2) * D);
    ret = min(ret, rec(u2 / 2, dp) + A + abs(N - u2) * D);
    ret = min(ret, rec(l3 / 3, dp) + B + abs(N - l3) * D);
    ret = min(ret, rec(u3 / 3, dp) + B + abs(N - u3) * D);
    ret = min(ret, rec(l5 / 5, dp) + C + abs(N - l5) * D);
    ret = min(ret, rec(u5 / 5, dp) + C + abs(N - u5) * D);

    return dp[N] = ret;
}

