ii handle1(int64 cur, int64 t, int64 c1, int64 c2, map<int64, int64>& d) {
  int64 r = t - cur % t;
  if (r == t) r = 0;
  int64 nxt = (cur + r) / t;
  int64 nxt_cost = d[cur] + r * c1 + c2;
  auto it = d.find(nxt);
  if (it == d.end() || it->second > nxt_cost) {
    d[nxt] = nxt_cost;
    return {nxt_cost, nxt};
  }
  return {-1, -1};
}

ii handle2(int64 cur, int64 t, int64 c1, int64 c2, map<int64, int64>& d) {
  int64 r = cur % t;
  int64 nxt = (cur - r) / t;
  int64 nxt_cost = d[cur] + r * c1 + c2;
  auto it = d.find(nxt);
  if (it == d.end() || it->second > nxt_cost) {
    d[nxt] = nxt_cost;
    return {nxt_cost, nxt};
  }
  return {-1, -1};
}

