#define REP(i, n) for (ll i = 1; i <= n; i++)
#define rep(i, n) for (ll i = 0; i < n; i++)
#define ll long long
#define ld long double
using namespace std;

struct Datas
{
    ll num;
    ll x;
    ll depth;
    ll coins;
};

//ansはD枚スタート

int T;
ll currentCoin = 0;
ll currentNum = 0;
queue<Datas> q;
vector<ll> ans(T);
vector<vector<ll>> cases(T, vector<ll>(5));

ll A(ll &coin)  //coinはnumのこと
{
    coin *= 2;
    return coin;
}

ll B(ll &coin)
{
    coin *= 3;
    return coin;
}

ll C(ll &coin)
{
    coin *= 5;
    return coin;
}

ll D1(ll &coin)
{
    coin += 1;
    return coin;
}

ll D2(ll &coin)
{
    coin += -1;
    return coin;
}

ll bfs(ll k)
{
    while (!q.empty())
    {
        // キューの先頭の要素を取り出す dequeue(pop)
        Datas now = q.front();
        q.pop();
        currentNum = now.num;
        // 停止条件
        // if (now.hoge == target) return ~;  // 探索対象
        if (now.num == cases[k][0])
            return now.coins;

        // BFS
        for (int i = 0; i < 5; ++i)
        {
            Datas next;
            switch (i)
            {
            case 0:
                next = {A(currentNum),
                              now.x,
                              now.depth + 1,
                              currentCoin += cases[k][1]
                              };
                break;
            case 1:
                next = {B(currentNum),
                              now.x + 1,
                              now.depth + 1,
                              currentCoin += cases[k][2]
                              };
                break;
            case 2:
                next = {C(currentNum),
                              now.x + 2,
                              now.depth + 1,
                              currentCoin += cases[k][3]
                              };
                break;
            case 3:
                next = {D1(currentNum),
                              now.x + 3,
                              now.depth + 1,
                              currentCoin += cases[k][4]
                              };
                break;
            case 4:
                next = {D2(currentNum),
                              now.x + 4,
                              now.depth + 1};
                              currentCoin += cases[k][4];
                break;
            }
            // 深さ（ステップ数）を一つ足す
            if (true)
            {

                // 条件を満たしたら enqueue(push)
                // 問題により，同じ状態に戻らないようにする処理を書く（無限ループを防ぐ）
                q.push(next);
            }
        }
    }
}

int main()
{

    cin >> T;

    rep(i, T)
    {
        rep(j, 5)
        {
            cin >> cases[i][j];
        }
    }
    Datas start = {1, 0, 0};
    q.push(start);
    q.emplace(start);

    rep(k,T){
        ans[k] = bfs(k);
    }
    rep(k,T){
        cout << ans[k] << endl;
    }
}

