unsigned long long dp(ll N, map<unsigned long long, unsigned long long>& mp) {
	//cout << "dp" << endl;
	if (N == 0) return mp[0] = 0;
	//if (N == 1) return mp[1] = D;
	if (mp[N]) return mp[N];
	mp[N] = D * N;
	mp[N] = min(mp[N], min(D * abs(N % 5) + C + dp(N / (ll)5, mp), D * abs(5 - N % 5) + C + dp((N + 4) / (ll)5, mp)));
	mp[N] = min(mp[N], min(D * abs(N % 3) + B + dp(N / (ll)3, mp), D * abs(3 - N % 3) + B + dp((N + 2) / (ll)3, mp)));
