ll solve(ll num);

ll t, n, a, b, c, d;
map<ll, ll> memo;
ll ans;

int main(){

    cin >> t;

    for (int i=0; i<t; ++i){
        //  条件ごとにmapをクリア
        memo.clear();
        cin >> n >> a >> b >> c >> d;

        //  再帰関数を呼び出し
        ans = solve(n);
        cout << ans << endl;
    }

