ll solve(ll num){

    ll cost, l2, r2, l3, r3, l5, r5;

    // 再帰を抜ける処理
    if (num == 0) return 0;
    if (num == 1) return d;
    if (memo.count(num)) return memo.at(num);

    // 2, 3, 5で割り切れる数値に移動して商を計算
    // numが2, 3, 5で割り切れる値の場合は、numをそのままl(num), r(num)とする
    l2 = (num/2)*2;
    r2 = ((num+1)/2)*2;
    l2 = (num/3)*3;
    r2 = ((num+2)/3)*3;
    l2 = (num/5)*5;
    r2 = ((num+4)/5)*5;

    // numまで操作dを実施した場合のコストで初期化
    cost = num*d;

    // コストを計算
    // 割った回数だけa, b, cをコストに加算、割り切れない分はdとして加算
    cost = min(cost, abs(num-l2)*d + a + solve(num/2));
    cost = min(cost, abs(num-r2)*d + a + solve(num/2));
    cost = min(cost, abs(num-l3)*d + b + solve(num/3));
    cost = min(cost, abs(num-r3)*d + b + solve(num/3));
    cost = min(cost, abs(num-l5)*d + c + solve(num/5));
    cost = min(cost, abs(num-r5)*d + c + solve(num/5));

    // 計算したコストをmapに記憶
    memo.at(num) = cost;

    return num;
}

