using namespace std;
typedef long long ll;

struct Node {
  ll n;
  ll cost;

  Node(ll n = -1, ll cost = -1) {
    this->n = n;
    this->cost = cost;
  }

  bool operator>(const Node &n) const {
    return cost > n.cost;
  }
};

int main() {
  ll N, T, A, B, C, D;

  cin >> T;

  for (int i = 0; i < T; ++i) {
    cin >> N >> A >> B >> C >> D;
    priority_queue <Node, vector<Node>, greater<Node>> pque;

    pque.push(Node(N, 0));
    map<ll, bool> memo;

    ll ans = LONG_MAX;

    while (!pque.empty()) {
      Node node = pque.top();
      pque.pop();

      assert(node.n <= N);

      if (memo[node.n]) continue;
      memo[node.n] = true;

      if (node.n == 1) {
        cout << node.cost + D << endl;
        break;
      }

      if (node.n % 2 == 0) {
        ll diff = node.n - node.n / 2;

        if (A / (double) diff > D) {
          pque.push(Node(node.n / 2, node.cost + diff * D));
        } else {
          pque.push(Node(node.n / 2, node.cost + A));
        }
      } else {
        ll d1 = node.n - (node.n - 1) / 2;

        if (A / (double) d1 > D) {
          pque.push(Node((node.n - 1) / 2, node.cost + d1 * D));
        } else {
          pque.push(Node((node.n - 1) / 2, node.cost + A + D));
        }

        ll d2 = node.n - (node.n + 1) / 2;

        if (A / (double) d2 > D) {
          pque.push(Node((node.n + 1) / 2, node.cost + d2 * D));
        } else {
          pque.push(Node((node.n + 1) / 2, node.cost + A + D));
        }
      }

      if (node.n % 3 == 0) {
        ll diff = node.n - node.n / 3;

        if (B / (double) diff > D) {
          pque.push(Node(node.n / 3, node.cost + diff * D));
        } else {
          pque.push(Node(node.n / 3, node.cost + B));
        }
      } else {
        ll s1 = node.n - 3 * floor(node.n / 3.0);
        ll d1 = node.n - (node.n - s1) / 3;

        if (node.n - s1 >= 3) {
          if (B / (double) d1 > D) {
            pque.push(Node((node.n - s1) / 3, node.cost + d1 * D));
          } else {
            pque.push(Node((node.n - s1) / 3, node.cost + B + s1 * D));
          }
        }

        ll s2 = 3 * ceil(node.n / 3.0) - node.n;
        ll d2 = node.n - (node.n + s2) / 3;

        if (B / (double) d2 > D) {
          pque.push(Node((node.n + s2) / 3, node.cost + d2 * D));
        } else {
          pque.push(Node((node.n + s2) / 3, node.cost + B + s2 * D));
        }
      }

      if (node.n % 5 == 0) {
        ll diff = node.n - node.n / 5;

        if (C / (double) diff > D) {
          pque.push(Node(node.n / 5, node.cost + diff * D));
        } else {
          pque.push(Node(node.n / 5, node.cost + C));
        }
      } else {
        ll s1 = node.n - 5 * floor(node.n / 5.0);
        ll d1 = node.n - (node.n - s1) / 5;

        if (node.n - s1 >= 5) {
          if (C / (double) d1 > D) {
            pque.push(Node((node.n - s1) / 5, node.cost + d1 * D));
          } else {
            pque.push(Node((node.n - s1) / 5, node.cost + C + s1 * D));
          }
        }

        ll s2 = 5 * ceil(node.n / 5.0) - node.n;
        ll d2 = node.n - (node.n - s2) / 5;

        if (C / (double) d2 > D) {
          pque.push(Node((node.n + s2) / 5, node.cost + d2 * D));
        } else {
          pque.push(Node((node.n + s2) / 5, node.cost + C + s2 * D));
        }
      }
    }
  }

  return 0;
}

