long long dg(long long x)
{
	long long s,t;
	if (x>1e18/d) s=1000000000000000000;
	else s=x*d;
	if (x==0) return 0;
	if (H[x]) return H[x];
	t=findnear(x,2,1);
	if (t/2!=x) s=min(s,dg(t/2)+a+d*abs(t-x));
	t=findnear(x,2,2);
	if (t/2!=x) s=min(s,dg(t/2)+a+d*abs(t-x));
	t=findnear(x,3,1);
	if (t/3!=x) s=min(s,dg(t/3)+b+d*abs(t-x));
	t=findnear(x,3,2);
	if (t/3!=x) s=min(s,dg(t/3)+b+d*abs(t-x));
	t=findnear(x,5,1);
	if (t/5!=x) s=min(s,dg(t/5)+c+d*abs(t-x));
	t=findnear(x,5,2);
	if (t/5!=x) s=min(s,dg(t/5)+c+d*abs(t-x));
	H[x]=s;
	return s;
}

