	ans=min(ans,calc((x-g)/3)+g*d+b);
	else
	ans=min(ans,calc((x-g)/3+1)+(3-g)*d+b);

	g=x%5;
	if(g<=2)
	ans=min(ans,calc((x-g)/5)+g*d+c);
	else 
	ans=min(ans,calc((x-g)/5+1)+(5-g)*d+c);
	return s[x]=ans;
}
