int64_t a, b, c, d;
map<int64_t, int64_t> dp;
int64_t dfs(int64_t n) {
  if (n == 0) return 0;
  if (n == 1) {
    return d;
  }
  if (dp.count(n)) {
    return dp[n];
  }
  int64_t cost = numeric_limits<int64_t>::max();
  if (n % 2 == 0) {
    if (n - n / 2 <= 1000000000) {
      cost = min(cost, dfs(n / 2) + min((n - n / 2) * d, a));
    } else {
      cost = min(cost, dfs(n / 2) + a);
    }
  } else {
    int64_t f = 2 * (n / 2);
    int64_t ce = 2 * ((n + 1) / 2);
    int64_t c1;
    if (ce - ce / 2 <= 1000000000) {
      c1 = dfs(n / 2) + (n - f) * d + min(a, (f - f / 2) * d);
      c1 = min(c1, dfs(ce / 2) + (ce - n) * d + min(a, (ce - ce / 2) * d));
    } else {
      c1 = dfs(n / 2) + (n - f) * d + a;
      c1 = min(c1, dfs(ce / 2) + (ce - n) * d + a);
    }
    cost = min(cost, c1);
  }
  if (n % 3 == 0) {
    if (n - n / 3 <= 1000000000) {
      cost = min(cost, dfs(n / 3) + min((n - n / 3) * d, b));
    } else {
      cost = min(cost, dfs(n / 3) + b);
    }
  } else {
    int64_t f = 3 * (n / 3);
    int64_t ce = 3 * ((n + 2) / 3);
    int64_t c1;
    if (ce - ce / 3 <= 1000000000) {
      c1 = dfs(n / 3) + (n - f) * d + min(b, (f - f / 3) * d);
      c1 = min(c1, dfs(ce / 2) + (ce - n) * d + min(b, (ce - ce / 3) * d));
    } else {
      c1 = dfs(n / 3) + (n - f) * d + b;
      c1 = min(c1, dfs(ce / 3) + (ce - n) * d + b);
    }
    cost = min(cost, c1);
  }
  if (n % 5 == 0) {
    if (n - n / 5 <= 1000000000) {
      cost = min(cost, dfs(n / 5) + min((n - n / 5) * d, c));
    } else {
      cost = min(cost, dfs(n / 5) + c);
    }
  } else {
    int64_t f = 5 * (n / 5);
    int64_t ce = 5 * ((n + 4) / 5);
    int64_t c1;
    if (ce - ce / 5 <= 1000000000) {
      c1 = dfs(n / 5) + (n - f) * d + min(c, (f - f / 5) * d);
      c1 = min(c1, dfs(ce / 5) + (ce - n) * d + min(c, (ce - ce / 5) * d));
    } else {
      c1 = dfs(n / 5) + (n - f) * d + c;
      c1 = min(c1, dfs(ce / 5) + (ce - n) * d + c);
    }
    cost = min(cost, c1);
  }
  return dp[n] = cost;
}

