int main() {
    int64_t T;
    cin >> T;

    const vector<int64_t> v = { 2, 3, 5 };
    for (int64_t _ = 0; _ < T; _++) {
        int64_t N, D;
        vector<int64_t> costs(3);
        cin >> N >> costs[0] >> costs[1] >> costs[2] >> D;

        map<int64_t, int64_t> memo;
        function<int64_t(int64_t)> f = [&](int64_t x){
            if (x == 0) {
                return (int64_t)0;
            } else if (x == 1) {
                return D;
            } else if (memo.count(x)) {
                return memo[x];
            }

            int64_t ans = LLONG_MAX;

            //Dをx回
            //ここオーバーフローしかねないのでチェックをいれる
            if ((double)D * x <= 1e18) {
                ans = min(ans, D * x);
            }

            for (uint64_t i = 0; i < v.size(); i++) {
                int64_t target = v[i];
                int64_t cost = costs[i];

                //x以上でtargetで割り切れる一番小さい数
                int64_t up = (x + target - 1) / target * target;
                ans = min(ans, f(up / target) + cost + D * abs(up - x));

                //x以下でtargetで割り切れる一番大きい数
                int64_t down = x / target * target;
                ans = min(ans, f(down / target) + cost + D * abs(down - x));
            }

            return memo[x] = ans;
        };

        cout << f(N) << endl;
    }
}

