inline ll dfs(ll x){
	if(x==1)return d;
	if(x==0)return 0;
	if(m[x])return m[x];
	m[x]=1e16;
	if((x&1)==0)m[x]=min(m[x],dfs(x/2)+a);
	else m[x]=min(m[x],min(dfs(x/2)+a+d,dfs(x/2+1)+a+d));
	if(x%3==0)m[x]=min(m[x],dfs(x/3)+b);
	else m[x]=min(m[x],min(dfs(x/3)+b+(x%3)*d,dfs(x/3+1)+b+(3-x%3)*d));
	if(x%5==0)m[x]=min(m[x],dfs(x/5)+c);
	else m[x]=min(m[x],min(dfs(x/5)+c+(x%5)*d,dfs(x/5+1)+c+(5-x%5)*d));
	return m[x];
}
