#include<bits/stdc++.h>
using namespace std;

typedef long long LL;

const LL lim = (LL)1e18;
const int N = 1e3 + 10;

int T;
LL n, a, b, c, d;
bool done[N];
LL dp[N];
unordered_map<LL, LL> MP;
unordered_set<LL> ST;

struct Node{
	LL val, cost;
	Node(){}
	Node(LL val, LL cost):val(val),cost(cost){}
	bool operator < (const Node &A)const{
		return cost > A.cost;
	}
};

vector<Node> V;
priority_queue<Node> Q;

void add(LL v, LL c){
	if(!MP.count(v) || c < MP[v]){
		MP[v] = c;
		Q.push(Node(v, c));
	}
}

void add2(LL v, LL c){
	if(c < dp[v]){
		dp[v] = c;
		Q.push(Node(v, c));
	}
}

LL mul(LL cur, LL cost, LL num){
	double p = cur + (double)cost * num;
	if(p >= lim)	return lim;
	return cur + cost * num;
}

void init(){
	MP.clear();
	ST.clear();
	while(!Q.empty())	Q.pop();

	Q.push(Node(n, 0));
	MP[n] = 0;
	Node nd;
	V.clear();
	LL val;
	while(!Q.empty()){
		nd = Q.top(); Q.pop();

		if(nd.val < N){
			dp[nd.val] = min(dp[nd.val], nd.cost);
			continue;
		}

		if(ST.count(nd.val)){
			continue;
		}

		ST.insert(nd.val);

		for(int i=0; i<=5; i++){
			for(int j=-1; j<=1; j+=2){
				val = nd.val + i * j;
				if(val < 0)	continue;
				if(val % 2 == 0){
					add(val / 2, mul(nd.cost + a, d, i));
					add(val / 2, mul(nd.cost, d, nd.val - val / 2));
				}
				if(val % 3 == 0){
					add(val / 3, mul(nd.cost + b, d, i));
					add(val / 3, mul(nd.cost, d, nd.val - val / 3));
				}
				if(val % 5 == 0){
					add(val / 5, mul(nd.cost + c, d, i));
					add(val / 5, mul(nd.cost, d, nd.val - val / 5));
				}
			}
		}
	}
}

LL cal(){
	for(int i=0; i<N; i++){
		dp[i] = lim;
		done[i] = 0;
	}
	init();

	while(!Q.empty())	Q.pop();

	for(int i=0; i<N; i++){
		if(dp[i] < lim)	Q.push(Node(i, dp[i]));
	}

	LL ret;
	Node nd;

	while(!Q.empty()){
		nd = Q.top(); Q.pop();

		if(nd.val == 0){
			ret = nd.cost;
			break;
		}

		if(done[nd.val])	continue;
		done[nd.val] = 1;

		if(nd.val + 1 < N){
			add2(nd.val+1, dp[nd.val]+d);
		}
		add2(nd.val-1, dp[nd.val]+d);
		if(nd.val % 2 == 0){
			add2(nd.val/2, dp[nd.val]+a);
		}
		if(nd.val % 3 == 0){
			add2(nd.val/3, dp[nd.val]+b);
		}
		if(nd.val % 5 == 0){
			add2(nd.val/5, dp[nd.val]+c);
		}
	}

	return ret;
}

int main(){
	scanf("%d", &T);
	while(T--){
		scanf("%lld %lld %lld %lld %lld", &n, &a, &b, &c, &d);
		printf("%lld\n", cal());
	}
	return 0;
}

