        return !(a <= std::numeric_limits<ll>::max() - b);
    };

    auto is_overflow_m = [](ll a, ll b) {
        return !(a <= std::numeric_limits<ll>::max() / b);
    };

    update(n, 0);
    while (pq.size()) {
        auto [ cd, cur ] = pq.top();
        pq.pop();
        if (cur == 0) break;
        if (costs[cur] < cd) continue;
        if (!is_overflow_m(d, cur) && !is_overflow_t(cd, d * cur)) update(0, cd + d * cur);
        ll dl[] = { 2, 3, 5, };
        ll cl[] = { a, b, c, };
        for (ll i = 0; i < 3; i++) {
            ll m = cur % dl[i];
            if (!is_overflow_t(cd, m * d) && !is_overflow_t(cd + m * d, cl[i])) update((cur - m) / dl[i], cl[i] + m * d + cd);
            ll rm = (dl[i] - m) % dl[i];
            if (!is_overflow_t(cd, rm * d) && !is_overflow_t(cd + rm * d, cl[i])) update((cur + rm) / dl[i], cl[i] + rm * d + cd);
        }
    }

    return costs[0];
}

