void solve() {
  cin >> n >> a >> b >> c >> d;
  memo.clear();

  while (!q.empty()) {
    q.pop();
  }

  LL pot = 1;
  LL mnoz = 2;
  LL res = -1;
  for (auto x : pre) {
    if (abs(x.second.second - n) <= 1000000000) {
      LL val = abs(x.second.second - n) * d;
      toQueue(-val, x.second.second, 0);
      debug(x.second.second);
    }
  }
  for (int i = 0; i < 60; ++i) {
    if (pot * mnoz >= n) {
      LL act1 = pot;
      LL act2 = pot * mnoz;
      toQueue(-(d * (n - act1)), pot * mnoz, 0);
      toQueue(-(d * (n - act2)), pot, 0);
      break;
    }
  }

  pot = 1;
  mnoz = 3;
  for (int i = 0; i < 38; ++i) {
    if (pot * mnoz >= n) {
      LL act1 = pot;
      LL act2 = pot * mnoz;
      toQueue(-(d * (n - act1)), pot * mnoz, 0);
      toQueue(-(d * (n - act2)), pot, 0);
      break;
    }
  }

  pot = 1;
  mnoz = 5;
  for (int i = 0; i < 26; ++i) {
    if (pot * mnoz >= n) {
      LL act1 = pot;
      LL act2 = pot * mnoz;
      toQueue(-(d * (n - act1)), pot * mnoz, 0);
      toQueue(-(d * (n - act2)), pot, 0);
      break;
    }
  }
  q.push({{0, n}, 0});
  while(!q.empty()) {
    auto xx = q.top();
    LL val = -xx.first.first;
    LL w = xx.first.second;
    LL cnt = xx.second;
    q.pop();
    // debug(val, w, cnt);
    if (w <= 1000000000000000000 / d) {
      if (res == -1) {
        res = w * d + val;
      }
      res = min(res, w * d + val);
    }

    if (memo.count(w)) {
      continue;
    }

    memo[w] = val;
    if (w == 0) {
      if (res == -1) {
        res = val;
      }
      cout << min(val, res) << endl;
      break;  
    }

    if (w % 2 == 0) {
      toQueue(-(val + a), w / 2, cnt);
    }

    if (w % 3 == 0) {
      toQueue(-(val + b), w / 3, cnt);
    }

    if (w % 5 == 0) {
      toQueue(-(val + c), w / 5, cnt);
    }

    if (cnt <= 60) {
      toQueue(-(val + d), w + 1, cnt + 1);
      if (w - 1 >= 0) {
        toQueue(-(val + d), w - 1, cnt + 1);
      }
    }
  }
}
