int a,b,c,d;
map<long long,long long>v;
inline long long sol(long long x){
	if(v.find(x)!=v.end())return v[x];

	long long ret=((x<200000000000/d)?x*d:200000000000);

	chkmin(ret,(1ll*d*(x%2))+1ll*a+sol(x/2));
	if(x%2)chkmin(ret,(1ll*d)+1ll*a+sol((x+1)/2));
	chkmin(ret,(1ll*d*(x%3))+1ll*b+sol(x/3));
	if(x%3)chkmin(ret,(1ll*d*(3-(x%3)))+1ll*b+sol(x/3+1));
	chkmin(ret,(1ll*d*(x%5))+1ll*c+sol(x/5));
	if(x%5)chkmin(ret,(1ll*d*(5-(x%5)))+1ll*c+sol(x/5+1));
	v[x]=ret;return ret;
}

