map<Int, Int> mp;

Int calc(Int x){
  if(x == 0)return 0;
  if(mp.find(x) != mp.end())return mp[x];
  Int res = x * d;
  // 2
  Int rem = x % 2;
  if((x + rem) / 2 < x)chmin(res, rem * d + a + calc((x + rem)/2));
  if(x - rem > 0 && (x - rem) / 2 < x)chmin(res, rem * d + a + calc((x - rem)/2));
  // 3
  rem = x % 3;
  if(x - rem > 0 && (x - rem) / 3 < x)chmin(res, rem * d + b + calc((x - rem) / 3));
  if(x + 3 - rem > 0 && (x + 3 - rem) / 3 < x)chmin(res, (3 - rem) * d + b + calc((x + 3 - rem) / 3));
  // 5
  rem = x % 5;
  if(x - rem > 0 && (x - rem) / 5 < x)chmin(res, rem * d + c + calc((x - rem) / 5));
  if(x + 5 - rem > 0 && (x + 5 - rem) / 5 < x)chmin(res, (5 - rem) * d + c + calc((x + 5 - rem) / 5));
  return mp[x] = res;
}

