		priority_queue<pair<int64_t, int64_t>, vector<pair<int64_t, int64_t>>, greater<pair<int64_t, int64_t>>> pq;
		pq.emplace(0, n);
		while(not pq.empty()) {
			auto [cost, num] = pq.top();
			pq.pop();
			if(dp.count(num) and cost > dp[num]) continue;
			for(int64_t i = -5; i <= 5; ++i) {
				int64_t nxt = num + i;
				int64_t nc = cost + abs(i) * d;
				for(int j = 0; j < 3; ++j) {
					if(nxt % dir[j] != 0) continue;
					int64_t _nxt = nxt / dir[j];
					int64_t _nc = nc + a[j];
					if(not dp.count(_nxt) or _nc < dp[_nxt]) {
						dp[_nxt] = _nc;
						pq.emplace(_nc, _nxt);
					}
				}
			}
			constexpr int64_t INF = 1e18;
			if(num < INF / d) {
				int64_t _nxt = 0;
				int64_t _nc = cost + num * d;
				if(not dp.count(_nxt) or _nc < dp[_nxt]) {
					dp[_nxt] = _nc;
					pq.emplace(_nc, _nxt);
				}
			}
		}
		cout << dp[0] << '\n';
	}
	return 0;
}

