#include <bits/stdc++.h>

using namespace std;
using ll = long long;

const ll inf = numeric_limits<ll>::max() / 3;

ll work (const ll n, const ll a, const ll b, const ll c, const ll d, map<ll, ll> &mem)
{
	if (mem.count(n))
		return mem.at(n);

	auto &cur = mem[n];
	cur = inf;
	if (double(n) * double(d) < 2 * double(cur))
		cur = min(cur, n * d);

	for (int i = -4; i <= 4; i++)
	{
		const ll x = n + i;
		if (x < 0)
			continue;

		if (x / 2 < n && x % 2 == 0)
			cur = min(cur, a + abs(i) * d + work(x / 2, a, b, c, d, mem));
		if (x / 3 < n && x % 3 == 0)
			cur = min(cur, b + abs(i) * d + work(x / 3, a, b, c, d, mem));
		if (x / 5 < n && x % 5 == 0)
			cur = min(cur, c + abs(i) * d + work(x / 5, a, b, c, d, mem));
	}

	return cur;
}

void solve_test(istream &cin = std::cin, ostream &cout = std::cout)
{
	map<ll, ll> mem;

	ll n, a, b, c, d;
	cin >> n >> a >> b >> c >> d;
	cout << work(n, a, b, c, d, mem) << endl;
}

void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	int t;
	cin >> t;

	for (int i = 0; i < t; i++)
		solve_test(cin, cout);
}

