s64 N, A, B, C, D;
map<s64, s64> m;
s64 now;

s64 dfs(s64 n, s64 cost)
{
    // if (n == 0) return cost;
    if (now <= cost) return 1e18;
    if (m[n] && m[n] <= cost) return 1e18;
    m[n] = cost;

    // cout << "n, cost, cnt = " << n << ", " << cost << "\n";
    s64 ret = 1e18;
    vs64 temp(3, 1e18);
    for (s64 i = 0; i <= 5; ++i)
    {
        s64 nextp = n + i;
        s64 nextm = n - i;
        s64 dc = i * D;
        s64 div[3] = {2, 3, 5};
        s64 c[3] = {A, B, C};
        s64 num;
        s64 cnt;
        rep (j, 3)
        {
            if (nextp == 0)
            {
                ret = min(ret, cost + dc);
                break;
            }
            if (nextp % div[j] == 0)
            {
                num = div[j];
                cnt = 1;
                while (nextp % num == 0)
                {
                    if ((nextp - nextp / num) * D < 0 || (nextp - nextp / num) * D > cnt * c[j])
                    {
                        temp[j] = min(temp[j], dfs(nextp / num, cost + cnt * c[j] + dc));
                    }
                    else
                    {
                        temp[j] = min(temp[j], dfs(nextp / num, cost + dc + (nextp - nextp / num) * D));
                    }
                    ++cnt;
                    num *= div[j];
                }
            }
        }
        rep (j, 3)
        {
            if (nextm < 0) break;
            if (nextm == 0)
            {
                ret = min(ret, cost + dc);
                break;
            }
            if (nextm % div[j] == 0)
            {
                num = div[j];
                cnt = 1;
                while (nextm % num == 0)
                {
                    if ((abs(nextm) - abs(nextm) / num) * D < 0 || (abs(nextm) - abs(nextm) / num) * D > cnt * c[j])
                    {
                        temp[j] = min(temp[j], dfs(nextm / num, cost + cnt * c[j] + dc));
                    }
                    else
                    {
                        temp[j] = min(temp[j], dfs(nextm / num, cost + (abs(nextm) - abs(nextm) / num) * D + dc));
                    }
                                    num *= div[j];
                ++cnt;
                }
            }
        }
    }

    rep (i, 3) ret = min(ret, temp[i]);
    // cout << "n, ret: " << n << ", " << ret << "\n";
    now = min(now, ret);
    m[n] = min(m[n], ret);
    return ret;
}

