const ll MX = 1e18;
ll dfs(map<ll,ll> &mp,ll n,ll a,ll b,ll c,ll d){
  if(mp.count(n) != 0)return mp[n];
  if(n == 1)return d;
  if(n <= 0)return 0;
  ll res = MX;
  if(MX/n >= d)res = d*n;
  res = min(res,dfs(mp,n/2,a,b,c,d)+(n & 1)*d+a);
  res = min(res,dfs(mp,n/3,a,b,c,d)+(n%3)*d+b);
  res = min(res,dfs(mp,n/5,a,b,c,d)+(n%5)*d+c);
  res = min(res,dfs(mp,n/3+1,a,b,c,d)+(3-n%3)*d+b);
  res = min(res,dfs(mp,n/5+1,a,b,c,d)+(5-n%5)*d+c);
  return mp[n] = res;
}

