map<long long , long long > f;
int T;
long long n,a,b,c,d;
long long dfs(long long x) {
  if(x==0) return 0;
  if(x==1) return d;
  if(f.count(x)) return f[x];
  long long l1=x/2*2,r1=((x+1)/2)*2;
  long long l2=x/3*3,r2=((x+2)/3)*3;
  long long l3=x/5*5,r3=((x+4)/5)*5;
  long long ret=1e18;
  if(x<(ret/d)) ret=x*d;
  ret=min(ret,llabs(x-l1)*d+dfs(l1/2)+a);
  ret=min(ret,llabs(r1-x)*d+dfs(r1/2)+a);
  ret=min(ret,llabs(x-l2)*d+dfs(l2/3)+b);
  ret=min(ret,llabs(r2-x)*d+dfs(r2/3)+b);
  ret=min(ret,llabs(x-l3)*d+dfs(l3/5)+c);
  ret=min(ret,llabs(l3-x)*d+dfs(r3/5)+c);
  f[x]=ret;
}
