using namespace std;
typedef long long ll;
ll a, b, c, d;
map<ll, ll>ma;
ll min(ll a, ll b)
{
	if (a < 0)
		return b;
	if (b < 0)
		return a;
	return a < b ? a : b;
}
ll solve(ll n)
{
	if (n == 0)
		return 0;
	if (n == 1)
		return d;
	if (ma.count(n))
		return ma[n];
	ll l2 = (n / 2) * 2;
	ll r2 = ((n + 1) / 2) * 2;
	ll l3 = (n / 3) * 3;
	ll r3 = ((n + 2) / 3) * 3;
	ll l5 = (n / 5) * 5;
	ll r5 = ((n + 4) / 5) * 5;
	ll res = min(1e18, n * d);
	res = min(res, llabs(n - l2) * 1LL * d + a + solve(l2 / 2));
	res = min(res, llabs(n - r2) * 1LL * d + a + solve(r2 / 2));
	res = min(res, llabs(n - l3) * 1LL * d + b + solve(l3 / 3));
	res = min(res, llabs(n - r3) * 1LL * d + b + solve(r3 / 3));
	res = min(res, llabs(n - l5) * 1LL * d + c + solve(l5 / 5));
	res = min(res, llabs(n - r5) * 1LL * d + c + solve(r5 / 5));
	ma[n] = res;
	return res;
}
int main()
{
	int t;
	cin >> t;
	while (t--)
	{
		ll n;
		cin >> n >> a >> b >> c >> d;
		ma.clear();
		cout << solve(n) << endl;
	}
	return 0;
}

