map<ll,ll> m;
ll A, B, C, D;
ll solve(ll N){
  if(N == 0) return 0;
  if(N == 1) return D;
  if(m.count(N)) return m[N];

  m[N] = 1e18;
  if(N / 1e9 * D < 3e9) m[N] = min(m[N] , N * D);

  m[N] = min(m[N] , A + D * (N % 2) + solve(N / 2) );
  m[N] = min(m[N] , A + D * (2 - N % 2) + solve((N + 1) / 2) );

  m[N] = min(m[N] , B + D * (N % 3) + solve(N / 3) );
  m[N] = min(m[N] , B + D * (3 - N % 3) + solve((N + 2) / 3) );

  m[N] = min(m[N] , C + D * (N % 5) + solve(N / 5) );
  m[N] = min(m[N] , C + D * (5 - N % 5) + solve((N + 1) / 5) );

  return m[N];

}

