#include<bits/stdc++.h>
using namespace std;
const long long INF = 1e16;
int Td;
long long n, A, B, C, D;

struct Node{
	long long x, rs;
	Node(long long x = 0, long long rs = 0) : x(x), rs(rs) {}
	bool operator < (const Node & b) const{
		return x < b.x;
	}
};

set<Node> G;
set<Node>::iterator it;

long long dfs(long long x) {
	if(x == 0) return 0;
	if(x == 1) return D;
	it = G.lower_bound(Node(x, 0));
	//cerr << x << endl;
	if((it != G.end()) && it->x == x) return it->rs;
	long long rs = INF, tmp = INF, y;
	if(x <= INF / D) rs = x * D;
	y = x % 5;
	tmp = dfs((x - y) / 5);
	rs = min(rs, tmp + y * D + C);
	y = 5 - x % 5;
	tmp = dfs((x + y) / 5);
	rs = min(rs, tmp + y * D + C);
	y = x % 3;
	tmp = dfs((x - y) / 3);
	rs = min(rs, tmp + y * D + B);
	y = 3 - x % 3;
	tmp = dfs((x + y) / 3);
	rs = min(rs, tmp + y * D + B);
	y = x % 2;
	tmp = dfs((x - y) / 2);
	rs = min(rs, tmp + y * D + A);
	if(x > 2) {
		y = 2 - x % 2;
		tmp = dfs((x + y) / 2);
		rs = min(rs, tmp + y * D + A);
	}
	G.insert(Node(x, rs));
	//printf("%lld, %lld\n", x, rs);
	return rs;
}

int main() {
	scanf("%d", &Td);
	while(Td--) {
		scanf("%lld%lld%lld%lld%lld", &n, &A, &B, &C, &D);
		G.clear(); 
		printf("%lld\n", dfs(n));
	}
	return 0;
}

