		else
			ans = min(ans, (3 - rem3) * d) + b + rec((n + 2LL) / 3LL);
	}

	if (n>=5)
	{
		long long rem5 = n % 5;
		if (rem5 < (5 - rem5))
			ans = min(ans, d * rem5 + c + rec(n / 5LL));
		else
			ans = min(ans, d * (5 - rem5)) + c + rec((n + 4LL) / 5LL);
	}

	if (1)
	{
		if (n % 2 == 0)
			ans = min(ans, a + rec(n / 2LL));
		else
		{
				ans = min(ans, d + a + rec((n + 1) / 2LL));
				ans = min(ans, d + a + rec((n) / 2LL));

		}
	}
	mm[n] = ans;
	return ans;
}

