ll solve(ll n) {
    if (memo.count(n)) return memo[n];
    ll mi = 1e12;
    // n/2
    mi = min(mi, solve(n/2) + a + n % 2 * d);

    // n/2 + 1
    if (n % 2 == 1)
        mi = min(mi, solve(n/2+1) + a + d);

    // n/3
    mi = min(mi, solve(n/3) + b + n % 3 * d);

    // n/3 + 1
    if (n % 3 != 0)
        mi = min(mi, solve(n/3+1) + b + (3 - n % 3) * d);

