map<ll, ll> memo;

ll solve(ll N, ll A, ll B, ll C, ll D) {
    if (memo.count(N)) return memo[N];

    if (N == 1) {
        memo[N] = D;
        return memo[N];
    }
    if (N == 0) {
        memo[N] = 0;
        return memo[N];
    }

    ll up_2   = solve( ceil((double)N/2), A, B, C, D) + (  ceil((double)N/2) * 2 - N) * D + A;
    ll down_2 = solve(floor((double)N/2), A, B, C, D) + (-floor((double)N/2) * 2 + N) * D + A;
    ll up_3   = solve( ceil((double)N/3), A, B, C, D) + (  ceil((double)N/3) * 3 - N) * D + B;
    ll down_3 = solve(floor((double)N/3), A, B, C, D) + (-floor((double)N/3) * 3 + N) * D + B;
    ll up_5   = solve( ceil((double)N/5), A, B, C, D) + (  ceil((double)N/5) * 5 - N) * D + C;
    ll down_5 = solve(floor((double)N/5), A, B, C, D) + (-floor((double)N/5) * 5 + N) * D + C;

    ll min_n;
    if (N < INF / D) min_n = N * D;
    else min_n = INF;
    min_n = min(min_n, up_2);
