int calc(int n, int a, int b, int c, int d) {
  if (n == 0) return 0;
  int cnta = 0;
  while (n % 2 == 0) {
    cnta += a;
    n /= 2;
  }
  int cntb = 0;
  while (n % 3 == 0) {
    cntb += b;
    n /= 3;
  }
  int cntc = 0;
  while (n % 5 == 0) {
    cntc += c;
    n /= 5;
  }
  int ans = cnta + cntb + cntc + n * d;
  return ans;
}

