const long long INF = (1ll << 61);

long long rec(long long x, long long A, long long B, long long C, long long D, map<long long, long long>& dp){
  if(dp.count(x)) return dp[x];
  if(x == 0) return 0;
  if(x == 1) return D;

  long long ret = INF;

  if(x <= ret / D) ret = x * D;

  ret = min(rec(x / 2, A, B, C, D, dp) + A + D * (x % 2), ret);
  ret = min(rec((x + 1) / 2, A, B, C, D, dp) + A + D * (2 - x % 2), ret);

  ret = min(rec(x / 3, A, B, C, D, dp) + B + D * (x % 3), ret);
  ret = min(rec((x + 2) / 3, A, B, C, D, dp) + B + D * (3 - x % 3), ret);

  ret = min(rec(x / 5, A, B, C, D, dp) + C + D * (x % 5), ret);
  ret = min(rec((x + 4) / 5, A, B, C, D, dp) + C + D * (5 - x % 5), ret);

  return dp[x] = ret;
}

