const long long INF = 10000000000000000;
map<long long, long long> memo;
long long n;
int a, b, c, d;

long long rec(long long n, long long x) {
    if (n == 0) return 0;
    if (memo.count(n)) return memo[n];
    long long res = n;
    if (n < 0) {
        res = min(res, rec(memo, n - (- 1), a, b, c, d, --x));
    } else {
        for (int i = 0; i < 4; i++) {
            if (i == 0) {
                res = min(res, rec(memo, n - (x * 5), a, b, c, d, x * 5));
            } else if (i == 1) {
                res = min(res, rec(memo, n - (x * 3), a, b, c, d, x * 3));
            } else if (i == 2) {
                res = min(res, rec(memo, n - (x * 2), a, b, c, d, x * 2));
            } else if (i == 3) {
                res = min(res, rec(memo, n - 1, a, b, c, d, ++x));
            }
        }
    }
    memo[n] = res;
    return memo[n];
}

