        scanf("%lld %lld %lld %lld %lld", &n, &a, &b, &c, &d);
        for(int i=1; i<=6; i++){
            dp[i] = nows(i, 4);
        }
        x = {2, 3, 5};
        co = {a, b, c};
        ll ans = calc(n);
        cout << ans << endl;
        mp.clear();
    }
}

