		return 0;

	if (p == 1)
		return d;

	vector<int>  multi = {2, 3, 5};
	vector<int>  cost = {a, b, c};
	if (m.count(p))
		return m[p];

	int ans = INF;
	if (p < INF / d)
		ans = p * d;
	for (int i = 0; i < multi.size(); i++) {
		if (p % multi[i] == 0) {
			ans = min(ans, solve(p / multi[i]) + cost[i]);
		}
		else {
			int down = (p / multi[i]) * multi[i];
			ans = min(ans, solve(down / multi[i]) + d * (p - down) + cost[i]);
			int up = down + multi[i];
			ans = min(ans, solve(up / multi[i]) + d * (up - p) + cost[i]);
		}
	}
	m[p] = ans;
	return ans;
}


