const long long MOD = 1000000007;
const long long HIGHINF = (long long)1e18;
const int INF = (int)1e9;

map<ll, ll> memo;
ll n, a, b, c, d;

ll dfs(ll myn) {
    if (memo.find(myn) != memo.end()) return memo[myn];
    if (myn == 0) return 0;
    if (myn == 1) return d;

    ll u2 = (myn + 1) / 2, d2 = myn / 2;
    ll u3 = (myn + 2) / 3, d3 = myn / 3;
    ll u5 = (myn + 4) / 5, d5 = myn / 5;

    ll ret = HIGHINF + 7;
    chmin(ret, (u2 * 2LL - myn) * d + a + dfs(u2));
    chmin(ret, (myn - d2 * 2LL) * d + a + dfs(d2));
    chmin(ret, (u3 * 3LL - myn) * d + b + dfs(u3));
    chmin(ret, (myn - d3 * 3LL) * d + b + dfs(d3));
    chmin(ret, (u5 * 5LL - myn) * d + c + dfs(u5));
    chmin(ret, (myn - d5 * 5LL) * d + c + dfs(d5));
    if (myn < ret / d) chmin(ret, myn * d);
    return memo[myn] = ret;
}

