ll n,a,b,c,d;
map<ll,ll>mp;

ll solve(ll now)
{
    if(now==0)
    {
        return 0;
    }
    if(now==1)
    {
        return d;
    }
    if(mp.count(now))
        return mp[now];
    ll ans = 3e18;
    if(d*now>0)
    {
        ans = min(ans , d*now);
    }
    if(now%2==0)
    {
        ans = min(ans , a + solve(now/2));
    }
    else{
        ll md = now%2;
        ans = min(ans , a+ d*md + solve((now-md)/2));
        md = 2- md;
        ans = min(ans , a+ d*md + solve((now+md)/2));
    }
    if(now%3==0)
    {
        ans = min(ans , b + solve(now/3));
    }
    else{
        ll md = now%3;
        ans = min(ans , b+ d*md + solve((now-md)/3));
        md = 3- md;
        ans = min(ans , b+ d*md + solve((now+md)/3));
    }
    if(now%5==0)
    {
        ans = min(ans , c + solve(now/5));
    }
    else{
        ll md = now%5;
        ans = min(ans , c+ d*md + solve((now-md)/5));
        md = 5- md;
        ans = min(ans , c+ d*md + solve((now+md)/5));
    }
    return mp[now]= ans;
}

