ll D;
ll cost[6];
map <ll, ll> dp;
ll go (ll n);

ll call (ll n, ll i) {
    ll l = n - (n % i);
    ll r = l + i;
    if (l == n)
        r = n;
    return min (go (l / i) + cost[i] + (n - l) * D, go (r / i) + cost[i] + (r - n) * D);
}

const ll INF = 1e18;

ll go (ll n) {
    if (dp.find (n) != dp.end ())
        return dp[n];
    ll ans = INF;
    if (ans / D > n)
        ans = D * n;
    ans = min (ans, call (n, 2));
    ans = min (ans, call (n, 3));
    ans = min (ans, call (n, 5));
    dp[n] = ans;
    return dp[n];
}

