using namespace std;
int T,A,B,C,D;
map<long long int,long long int> M;
long long int solve(long long int n){
	int id[3]={2,3,5},cost[3]={A,B,C};
	long long int a[3],m;
	if(M.count(n))return M[n];
	for(int i=0;i<3;i++){
		if(n%id[i]>0&&n>id[i]){
			a[i]=min(
				solve(n/id[i])+min((n%id[i])*D+cost[i],(n-n/id[i])*D),
				solve(n/id[i]+1)+min((id[i]-n%id[i])*D+cost[i],(n-(n/id[i]+1))*D)
			);
		}else if(n%id[i]==0 && n>=id[i])a[i]=solve(n/id[i])+min((long long int)cost[i],(n-n/id[i])*D);
		else a[i]=n*D;
	}
	m=min(min(a[0],a[1]),a[2]);
	M[n]=m;
	return m;
}
int main(){
	long long int N;
	cin>>T;
	for(int i=0;i<T;i++){
		M.clear();
		cin>>N>>A>>B>>C>>D;
		M[0]=0;M[1]=D;
		cout<<solve(N)<<endl;
	}
	return 0;
}

