const long LIM=1e18;
int T;
long N,A,B,C,D;
main()
{
	cin>>T;
	for(;T--;)
	{
		cin>>N>>A>>B>>C>>D;
		vector<pair<long,long> >X;
		X.push_back(make_pair(2,A));
		X.push_back(make_pair(3,B));
		X.push_back(make_pair(5,C));
		long ans=60*(A+D);
		map<long,long>all;
		all[N]=0;
		priority_queue<pair<long,long> >Q;
		Q.push(make_pair(-N,0L));
		while(!Q.empty())
		{
			long t=-Q.top().first,c=Q.top().second;Q.pop();
			if(all[t]<c||ans<=c)continue;
			if(t<=ans/D)
			{
				ans=min(ans,c+t*D);
			}
			for(pair<long,long>q:X)
			{
				long a=t%q.first,b=t/q.first;
				int lim=q.first%2?q.first%3?5:3:2;
				if(a<lim&&b>0&&a*D+q.second+c<ans)
				{
					long nc=a*D+q.second+c;
					if(all.find(b)==all.end()||all[b]>nc)
					{
						Q.push(make_pair(-b,nc));
						all[b]=nc;
					}
				}
				if(q.first-a<lim&&(q.first-a)*D+q.second+c<ans)
				{
					long nc=(q.first-a)*D+q.second+c;
					if(all.find(b+1)==all.end()||all[b+1]>nc)
					{
						Q.push(make_pair(-b-1,nc));
						all[b+1]=nc;
					}
				}
				if(q.first>t)break;
			}
		}
		cout<<ans<<endl;
	}
}

