LL solve(LL m) {
    if(f.count(m)) {
        return f[m];
    }

    LL a2 = m/2*2, b2 = (m+1)/2*2;
    LL a3 = m/3*3, b3 = (m+2)/3*3;
    LL a5 = m/5*5, b5 = (m+4)/5*5;

    LL ans = 1000000000000000000LL;
    if(m < ans/d) {
        ans = m*d;
    }

    ans = min(ans, abs(a2-m)*d + a + solve(a2/2));
    if(b2 != a2)
        ans = min(ans, abs(b2-m)*d + a + solve(b2/2));
    ans = min(ans, abs(a3-m)*d + b + solve(a3/3));
