ll minCoins(ll n)
{
    if (mp.count(n))
    {
        return mp[n];
    }
    if (n == 0)
    {
        return 0;
    }
    ll best = LLONG_MAX;
    if (n == 1)
    {
        return d;
    }

    if (n % 2 == 0)
    {
        best = min(best, a + minCoins(n / 2));
    }
    else
    {
        ll ch = n / 2 * 2;
        best = min(best, a + (n - ch) * d + minCoins(n / 2));
        ch += 2;
        best = min(best, a + (ch - n) * d + minCoins(n / 2 + 1));
    }
    if (n % 3 == 0)
    {
        best = min(best, b + minCoins(n / 3));
    }
    else
    {
        ll ch = n / 3 * 3;
        best = min(best, b + (n - ch) * d + minCoins(n / 3));
        ch += 3;
        best = min(best, b + (ch - n) * d + minCoins(n / 3 + 1));
    }
    if (n % 5 == 0)
    {
        best = min(best, c + minCoins(n / 5));
    }
    else
    {
        ll ch = n / 5 * 5;
        best = min(best, c + (n - ch) * d + minCoins(n / 5));
        ch += 5;
        best = min(best, c + (ch - n) * d + minCoins(n / 5 + 1));
    }

    if (d < LLONG_MAX / n)
    {
        best = min(best, d * n);
    }
    return mp[n] = best;
}

