unordered_map<LL, LL, custom_hash> dist;
void dijk(dt now){
    if(dist.count(now.pos) && now.step > dist[now.pos]) return;
    if(now.pos == 0) return;
    if(now.pos <= (1000000000000000000LL-now.step)/d) ans = min(ans,now.step+now.pos*d);
    // cout << now.pos << " " << now.step << endl;
    for(int i = 0;i < 3;i++){
