        {
            LL nx = now.pos/go[i]; nx++;
            LL nxstep = now.step+((go[i]-need)*d)+cost[i];
            if(!(dist.count(nx) && nxstep >= dist[nx])){
                dist[nx] = nxstep;
                antri.push({nx,nxstep});
