using namespace std;

typedef long long ll;
const int _max = 501;

ll a, b, c, d;

map<ll, ll> Map;

ll solve(ll n) {
    if (n == 0) return 0;
    if (n == 1) return d;
    if (Map.count(n)) return Map[n];
    ll l2 = n / 2 * 2, r2 = (n + 1) / 2 * 2;
    ll l3 = n / 3 * 3, r3 = (n + 2) / 3 * 3;
    ll l5 = n / 5 * 5, r5 = (n + 4) / 5 * 5;
    ll res = 1e18;
    if (n < res / d) res = n * d;
    res = min(res, abs(l2 - n) * d + a + solve(l2 / 2));
    res = min(res, abs(r2 - n) * d + a + solve(r2 / 2));

    res = min(res, abs(l3 - n) * d + b + solve(l3 / 3));
    res = min(res, abs(r3 - n) * d + b + solve(r3 / 3));

    res = min(res, abs(l5 - n) * d + c + solve(l5 / 5));
    res = min(res, abs(r5 - n) * d + c + solve(r5 / 5));
    Map[n] = res;
    return res;
}

int main() {
    int t;
    cin >> t;
    for (int i = 0; i < t; i++) {
        Map.clear();
        ll n;
        cin >> n >> a >> b >> c >> d;
        cout<<solve(n)<<endl;
    }

}

