						pq[nx]=y+abs(i)*d+b;

				}
			for(int i=-2;i<=2;i++)
				if((x+i)%5==0){
					long long int nx=(x+i)/5;
					if(pq.count(nx))
						pq[nx]=min(pq[nx],y+abs(i)*d+c);
					else
						pq[nx]=y+abs(i)*d+c;
				}
		}
