  while (cas--) {
    int64 n, a, b, c, d;
    scanf("%lld%lld%lld%lld%lld", &n, &a, &b, &c, &d);
    map<int64, int64> dp;
    dp[n] = 0;
    priority_queue<ii, vector<ii>, greater<ii>> Q;
    Q.push({dp[n], n});
    int64 best = 1LL << 60;
    while (!Q.empty()) {
      int64 dd = Q.top().first;
      int64 x = Q.top().second;
      Q.pop();
      if (dd != dp[x]) continue;
      best = min((__int128)best, (__int128)x * d + dd);
      // trace(x, dp[x], x * d + dd);
      ii nxt = handle1(x, 2, d, a, dp);
      if (nxt.first >= 0) Q.push(nxt);
      nxt = handle2(x, 2, d, a, dp);
      if (nxt.first >= 0) Q.push(nxt);
      nxt = handle1(x, 3, d, b, dp);
      if (nxt.first >= 0) Q.push(nxt);
      nxt = handle2(x, 3, d, b, dp);
      if (nxt.first >= 0) Q.push(nxt);
      nxt = handle1(x, 5, d, c, dp);
      if (nxt.first >= 0) Q.push(nxt);
      nxt = handle2(x, 5, d, c, dp);
