ll loop(ll n) {
	if(dp.count(n)) return dp[n];
	if(n <= 1) return n * D;
	ll v2l = A + loop(n / 2) + D * (n % 2);
	ll v2r = A + loop((n + 1) / 2) + D * (2 - n % 2);
	ll v3l = B + loop(n / 3) + D * (n % 3);
	ll v3r = B + loop((n + 2) / 3) + D * (3 - n % 3);
	ll v5l = C + loop(n / 5) + D * (n % 5);
	ll v5r = C + loop((n + 4) / 5) + D * (5 - n % 5);
	ll s = 2e18;
	if(1.0 * D * (n / 2) < 2e18) {
		s = loop((n + 1) / 2) + D * (n - (n + 1) / 2);
	}
	ll res = min(min(min(min(v2l, v2r), min(v3l, v3r)), min(v5l, v5r)), s);
	dp[n] = res;
	return res;
}

