  for (int i = -5; i <= min(5LL, v); ++i) {
    long long cur = v - i;
    if ((cur % 2) == 0 && cur / 2 < v) {
      upd(res, calc(cur/2) + a + d * abs(i));
      // break;
    }
  }
  return mem[v] = res;
}

