ll C[4];
ll arr[3] = {2,3,5};
const ll INF = 1e18;
void solve() {
    ll N; cin >> N;
    rep(i,4) cin >> C[i];

    unordered_map<ll, ll> dic;
    dic.reserve(100000);
    auto dfs=[&](auto&& self, ll n)->ll {
        if (dic.count(n)) return dic[n];
        if (n==1) return dic[n] = C[3];
        dic[n] = INF;
        if (C[3] <= INF/n) dic[n] = C[3]*n;
        rep(i,3) {
            ll m1 = n/arr[i];
            ll m2 = m1+1;
            ll l = m1*arr[i];
            ll r = m2*arr[i];
            if (m1 and m1 < n) {
                chmin(dic[n],self(self,m1)+(n-l)*C[3]+C[i]);
            }
            if (m2 < n) {
                chmin(dic[n],self(self,m2)+(r-n)*C[3]+C[i]);
            }
        }

        return dic[n];
    };

    cout << dfs(dfs,N) << ln;
}

int main() { 
    int Q; cin >> Q;
    while (Q--) {
        solve();
    }
}

