unordered_map<li, li> memo;

inline li dfs(li x) {
    if (x == 0) {
        return memo[x] = 0;
    }
    if (x == 1) {
        return memo[x] = d;
    }
    if (memo.count(x) > 0) {
        return memo[x];
    }
    //cout << x << endl;
    li res = bit(62);
    if (res / d > x) {
        res = min(res, d * x);
    }
    res = min(res, a + (x % 2) * d + dfs(x / 2));
    if (x % 2 > 0)res = min(res, a + (2 - x % 2) * d + dfs(x / 2 + 1));
    res = min(res, b + (x % 3) * d + dfs(x / 3));
    if (x % 3 > 0)res = min(res, b + (3 - x % 3) * d + dfs(x / 3 + 1));
    res = min(res, c + (x % 5) * d + dfs(x / 5));
    if (x % 5 > 0)res = min(res, c + (5 - x % 5) * d + dfs(x / 5 + 1));
    return memo[x] = res;
}

