typedef unsigned long long ll;
typedef map<ll, ll> mlll;
typedef set<ll> sll;

const ll INF = 9000000000000000000;
ll a, b, c, d;

ll minCost(ll n, mlll &pw) {
	if (n == 1)
		return d;
	if (n == 2)
		return d + a;
	if (n == 3)
		return d + b;
	if (n == 5)
		return d + c;
	auto jt = pw.find(n);
	if (jt == pw.end()) {
		sll ns;
		ns.insert(n - (n % 2)); ns.insert(n + (2 - (n % 2)));
		ns.insert(n - (n % 3)); ns.insert(n + (3 - (n % 3)));
		ns.insert(n - (n % 5)); ns.insert(n + (5 - (n % 5)));
		ll _min = (((int)log(n)) + ((int)log(d)) <= 18 ? n * d : INF);
		for (auto it = ns.begin(); it != ns.end(); it++) {
			if ((*it) > 0) {
				if ((*it) % 2 == 0)
					_min = min(_min, a + minCost((*it) / 2, pw) + d * (n >= (*it) ? n - (*it) : (*it) - n));
				if ((*it) % 3 == 0)
					_min = min(_min, b + minCost((*it) / 3, pw) + d * (n >= (*it) ? n - (*it) : (*it) - n));
				if ((*it) % 5 == 0)
					_min = min(_min, c + minCost((*it) / 5, pw) + d * (n >= (*it) ? n - (*it) : (*it) - n));
			}
		}
		pw[n] = _min;
		return _min;
	} else
		return jt->second;
}

