ll n, a, b, c, d;

vector <pair<ll, ll > > gg;
map<ll, ll> dp;

ll go (ll n) {
	if(n == 0) return 0;
	if(n == 1) return d;
	if(dp.count(n)) return dp[n];
	ll &res = dp[n];
	res = INF;
	if(n < res / d) res = n * d;

	for (auto it : gg) {
		ll l = n / it.first;
		ll r = (n+it.first-1) / it.first;
		r *= it.first;
		l *= it.first;

		res = min(res, go(l / it.first) + it.second + llabs(n-l) * d);
		res = min(res, go(r / it.first) + it.second + llabs(n-r) * d);
	}

	return res;
}

