void solve()
{
	ll N, A, B, C, D;  cin >> N >> A >> B >> C >> D;

	ll ans=INF;
	priority_queue<pll> pque;
	pque.emplace(N, 0);
	while (!pque.empty()){
		ll V; ll cost;  tie(V, cost) = pque.top(); pque.pop();
		if (not pque.empty() and V == pque.top().first) continue;

		//直で0
		if (V*(dd)D < INF){
			chmin(ans, cost+V*D);
		}
		//5で割る
		if (V>=4){
			ll VV;
			if (V%5>=3) VV=CEIL(V, 5);
			else        VV=V/5;
			ll c=abs(V-VV*5)*D+C;
			pque.emplace(VV, cost+c);
		}
		//3で割る
		if (V>=3){
			ll VV;
			if (V%3>=2) VV=CEIL(V, 3);
			else        VV=V/3;
			ll c=abs(V-VV*3)*D+B;
			pque.emplace(VV, cost+c);
		}
		//2で割る
		if(V>=2){
			ll VV;
			ll c=(V%2)*D+A;
			if (V%2==1 and V>3) {
				VV=V/2+1;
				pque.emplace(VV, cost+c);
			}
			VV=V/2;
			pque.emplace(VV, cost+c);
		}
	}
	cout << ans << '\n';
}

