                    }else{
                        mai+=1;
                        cost+=d;
                        last_act=1;
                    }
                }
            }
        }
        // exceed mai*5 < n
        ll c_cost = c + d*(mai*5-n);
        ll b_cost = b + abs(d*(mai*3-n));
        ll a_cost = a + abs(d*(mai*2-n));

        ll d_cost = d*(n-mai);
        if(last_act == 5 && abs(mai-n) >= 5){
            d_cost = d_cost - d * int(abs(mai-n)/5) * 4; //この回数の+1は*5の前にやれ
        }
        if(last_act == 3 && abs(mai-n) >= 3){
            d_cost = d_cost - d * int(abs(mai-n)/3) * 2; //この回数の+1は*5の前にやれ
        }
        if(last_act == 2 && abs(mai-n) >= 2){
            d_cost = d_cost - d * int(abs(mai-n)/2) * 1; //この回数の+1は*5の前にやれ
        }

        cost+= min(min(min(a_cost,b_cost),c_cost),d_cost);
        ans[i]=cost;
    }
    rep(i,t) cout<<ans[i]<<endl;
    return 0;

} // end of main


