void solve(ll N, ll tmp) {
    if (mp.count(N) > 0) {
        if (mp[N] <= tmp) {
            return;
        } else {
            mp[N] = tmp;
        }
    } else {
        mp[N] = tmp;
    }
    // cout << N << " " << tmp << endl;
    if (tmp >= ans) {
        return;
    }
    if (N == 1) {
        // cout << tmp << endl;
        ans = min(ans, D + tmp);
        return;
    }
    if (N <= llmax / D && N * D <= llmax - tmp) {
        ans = min(ans, N * D + tmp);
    }
    if (N % 2 == 0) {
        solve(N / 2, tmp + A);
    } else {
        solve((N - 1) / 2, tmp + A + D);
        // solve((N + 1) / 2, tmp + A + D);
    }
    if (N % 3 == 0) {
        solve(N / 3, tmp + B);
    } else if (N % 3 == 1) {
        solve((N - 1) / 3, tmp + B + D);
        // solve((N + 2) / 3, tmp + B + 2 * D);
    } else {
        solve((N + 1) / 3, tmp + B + D);
        // if (N > 2) {
        //     solve((N - 2) / 3, tmp + B + 2 * D);
        // }
    }
    if (N % 5 == 0) {
        solve(N / 5, tmp + C);
    } else if (N % 5 == 1) {
        solve((N - 1) / 5, tmp + C + D);
        // solve((N + 4) / 5, tmp + C + 4 * D);
    } else if (N % 5 == 2) {
        if (N > 2) {
            solve((N - 2) / 5, tmp + C + 2 * D);
        }
        // solve((N + 3) / 5, tmp + C + 3 * D);
    } else if (N % 5 == 3) {
        // if (N > 3) {
        //     solve((N - 3) / 5, tmp + C + 3 * D);
        // }
        solve((N + 2) / 5, tmp + C + 2 * D);
    } else {
        // if (N > 4) {
        //     solve((N - 4) / 5, tmp + C + 4 * D);
        // }
        solve((N + 1) / 5, tmp + C + D);
    }
}

