i64 calc(i64 N, i64 A, i64 B, i64 C, i64 D) {

  // A:x2 B:x3 C:x5 D:+-1

  // こすぱ
  i64 ca = A * 30 / 2, cb = B * 30 / 3, cc = C * 30 / 5;

  int dps = 200000;

  vector<i64> dp(dps + 2, INT64_MAX);
  dp[0] = 0;
  dp[1] = D;
  FOR(i, 1, dps + 1) {
    chmin(dp[i - 1], dp[i] + D);
    chmin(dp[i + 1], dp[i] + D);
    if (i * 2 < dp.size()) chmin(dp[i * 2], dp[i] + A);
    if (i * 3 < dp.size()) chmin(dp[i * 3], dp[i] + B);
    if (i * 5 < dp.size())  chmin(dp[i * 5], dp[i] + C);
  }

  if (N < dps + 1) {
    return dp[N];
  }

  i64 n = N;
  i64 result = INT64_MAX;
  i64 score = 0;
  while (n > dps) {

    if (n < (INT64_MAX - score) / D) chmin(result, score + n* D);

    vector<Future> fs;
    i64 t;

    if (n % 5 == 0) {

      fs.emplace_back(n / 5, C);
    }
    else {
      t = n / 5 + 1;
      fs.emplace_back(t, C + (t * 5 - n) * D);
      t = n / 5;
      fs.emplace_back(t, C + (n - t * 5) * D);
    }
    if (n % 3 == 0) {
      fs.emplace_back(n / 3, B);
    }
    else {
      t = n / 3 + 1;
      fs.emplace_back(t, B + (t * 3 - n) * D);
      t = n / 3;
      fs.emplace_back(t, B + (n - t * 3) * D);
    }
    if (n % 2 == 0) {
      fs.emplace_back(n / 2, A);
    }
    else {
      t = n / 2 + 1;
      fs.emplace_back(t, A + (t * 2 - n) * D);
      t = n / 2;
      fs.emplace_back(t, A + (n - t * 2) * D);
    }
    sort(rng(fs), fcmp);

    F0R(i, fs.size()) {
      if (fs[i].n < (INT64_MAX - score - fs[i].cost) / D) chmin(result, score + fs[i].cost + fs[i].n * D);
    }

    n = fs[0].n;
    score += fs[0].cost;
    //debug(n);
    //debug(score);
  }
  score += dp[n];
  chmin(result, score);

  return result;
}

