void
add(priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>> & q, map<ll, ll> & best, ll value, ll cost) {
  if (value < 0) return;

  if (best.find(value) == best.end() || best[value] > cost) {
    //cout<<value<<":"<<cost<<endl;
    best[value] = cost;
    q.push({cost, value});
  }
}

void
check( priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>> & q, map<ll, ll> & best, 
    ll value, ll cost, ll mul, ll mul_cost, ll one_cost) {

  if (value % mul == 0) {
    add(q, best, value / mul, cost + mul_cost);

    ll change = value / mul * (mul-1);
    if (change <= mul_cost/one_cost + 1)
      add(q, best, value / mul, cost + change * one_cost);
  }
  else {
    ll mod = value % mul;
    check(q, best, value - mod, cost + mod * one_cost, mul, mul_cost, one_cost);

    ll left = mul - mod;
    check(q, best, value + left, cost + left * one_cost, mul, mul_cost, one_cost);
  }
}

void
solve() {
  ll n, a, b, c, d;
  cin>>n>>a>>b>>c>>d;

  map<ll, ll> best;
  priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>> q;
  best[n] = 0;
  q.push({0, n});
  //cout<<n<<":"<<0<<endl;
  while (1) {
    auto p = q.top();
    q.pop();
    if (best.find(0) != best.end() && best[0] < p.first) break;

    //cout<<"current "<<p.second<<":"<<p.first<<endl;

    check(q, best, p.second, p.first, 2, a, d);
    check(q, best, p.second, p.first, 3, b, d);
    check(q, best, p.second, p.first, 5, c, d);
  }

  cout<<best[0]<<endl;
}

