int64_t INF = std::numeric_limits<int64_t>::max();

void solve() {
  int64_t N, A, B, C, D; std::cin >> N >> A >> B >> C >> D;
  std::map<int64_t, int64_t> dp;
  auto calc = [&](auto&& f, int64_t n)->int64_t {
    if(n <= 1) return n*D;
    if(dp.count(n) > 0) return dp[n];
    int64_t res = INF;
    if(n < INF/D) res = n*D;
    // ceil[n/2]
    int64_t m = (n+1)/2;
    res = std::min(res, (m*2 - n)*D + A + f(f, m));
    if(n%2 != 0) {
      m = n/2;
      res = std::min(res, (n - m*2)*D + A + f(f, m));
    }
    m = (n+2)/3;
    res = std::min(res, (m*3 - n)*D + B + f(f, m));
    if(n%3 != 0) {
      m = n/3;
      res = std::min(res, (n - m*3)*D + B + f(f, m));
    }
    m = (n+4)/5;
    res = std::min(res, (m*5 - n)*D + C + f(f, m));
    if(n%5 != 0) {
      m = n/5;
      res = std::min(res, (n - m*5)*D + C + f(f, m));
    }
    return dp[n] = res;
  };
  std::cout << calc(calc, N) << "\n";
}

int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  int T; std::cin >> T;
  for(int i = 0; i < T; ++i) solve();
  return 0;
}

