    }
    __int128 res = INT64_C(1) << 59;
    __int128 mx = N + 15;
    priority_queue<pair<__int128, __int128>, vector<pair<__int128, __int128>>,
                   greater<pair<__int128, __int128>>>
        que;
    que.push(make_pair(0, N));
    set<__int128> st;
    while (!que.empty()) {
      auto q = que.top();
      que.pop();
      __int128 c = q.first, n = q.second;
      if (c > res) continue;
      if (st.find(n) != st.end()) continue;
      st.insert(n);
