using ll = long long;
const int maxn = 10;
const ll inf = 1e16;
ll cost[maxn];
ll solve() {
	ll n, a, b, c, d;
	cin >> n >> a >> b >> c >> d;
	cost[2] = a, cost[3] = b, cost[5] = c;
	map<ll, ll> dp;
	queue<ll> togo;
	togo.push(n);
	ll res = inf / n >= d ? d * n : inf;
	while (togo.size()) {
		ll n = togo.front(), v = dp[n];
		togo.pop();
		if (v >= res) continue;
		auto update = [&](ll val, ll cost) {
			//cerr << val << ' ' << cost << "  VC\n";
			if (val == 0) res = min(res, cost);
			else if (!dp.count(val) || dp[val] > cost)
				dp[val] = cost, togo.push(val);
		};
		//cerr << n << " : " << v << '\n';
		if (inf / n >= d) res = min(res, v + d * n);
		for (int i : {2, 3, 5}) {
			for (int j = -i;j <= i;++j) if ((n+j > 0) && (n + j) % i == 0 && (cost[i] + abs(j) * d + v <= inf))
				update((n + j) / i, v + abs(j) * d + cost[i]);
		}
	}
	//cerr << '\n';
	return res;
}
