ll solve(ll);

ll solvex(ll N, ll d, ll c) {
  if (c+D*ll128(N%d) < D*ll128(N-N/d))
    return solve(N/d)+c+D*(N%d);
  else
    return solve(N/d)+D*(N-N/d);
}

ll solvey(ll N, ll d, ll c) {
  if (D*ll128(d-N%d) > 4e18) return 4e18;
  return solve((N+d)/d)+c+D*(d-N%d);
}

map<ll, ll> ss;
ll solve(ll N) {
  if (N == 0) return 0;
  if (N == 1) return D;
  if (ss.count(N)) return ss[N];
  ll best = 2e18;
  chmin(best, solvex(N, 2, A));
  chmin(best, solvex(N, 3, B));
  chmin(best, solvex(N, 5, C));
  // chmin(best, solvey(N, 2, A));
  chmin(best, solvey(N, 3, B));
  chmin(best, solvey(N, 5, C));
  return ss[N] = best;
}

