map <int, int> ans;

void calc(int n, int a, int b, int c, int d) {
    if (ans.find(n) != ans.end())
        return;
    ans[n] = (n > N ? INF : n * d);

    calc(n / 2, a, b, c, d);
    calc((n + 1) / 2, a, b, c, d);
    ans[n] = min({ ans[n], ans[n / 2] + a + n % 2 * d, ans[(n + 1) / 2] + a + (2 - n % 2) * d });

    calc(n / 3, a, b, c, d);
    calc((n + 2) / 3, a, b, c, d);
    ans[n] = min({ ans[n], ans[n / 3] + b + n % 3 * d, ans[(n + 2) / 3] + b + (3 - n % 3) * d });

    calc(n / 5, a, b, c, d);
    calc((n + 4) / 5, a, b, c, d);
    ans[n] = min({ ans[n], ans[n / 5] + c + n % 5 * d, ans[(n + 4) / 5] + c + (5 - n % 5) * d });
}

