map<LL, LL> mp;

int Dig(LL num) {
    int dig = 0;
    while(num > 0) {
        num /= 10;
        ++dig;
    }

    return dig;
}

void dfs(LL n, LL cost) {
    if(n == 1) {
        res = min(res, cost + D);
        return;
    }
    if(res <= cost || (mp[n] != 0 && mp[n] <= cost)) return;
    mp[n] = cost;
    if(cost == -1) cost = 0;
    if(n % 5 == 0) {
        t = LINF;
        if(Dig(n - n / 5) + ddig < 18) t = (n - n / 5) * D;
        dfs(n / 5, cost + min(t, C));
    }
    if(n % 3 == 0) {
        t = LINF;
        if(Dig(n - n / 3) + ddig < 18) t = (n - n / 3) * D;
        dfs(n / 3, cost + min(t, B));
    }
    if(n % 2 == 0) {
        t = LINF;
        if(Dig(n / 2) + ddig < 18) t = (n / 2) * D;
        dfs(n / 2, cost + min(t, A));
    }

    for(LL i = max(2ll, n - 4); i <= n + 4; ++i) {
        if(i % 5 == 0) {
            t = LINF;
            if(Dig(i - (i / 5)) + ddig < 10) t = (i - i / 5) * D;
            dfs(i / 5, cost + min(C, t) + D * llabs(i - n));
        }
    }
    for(LL i = max(2ll, n - 2); i <= n + 2; ++i) {
        if(i % 3 == 0) {
            t = LINF;
            if(Dig(i - (i / 3)) + ddig < 10) t = (i - i / 3) * D;
            dfs(i / 3, cost + min(B, t) + D * llabs(i - n));
        }
    }
    for(LL i = max(2ll, n - 1); i <= n + 1; ++i) {
        if(i % 2 == 0) {
            t = LINF;
            if(Dig(i - (i / 2)) + ddig < 10) t = (i - i / 2) * D;
            dfs(i / 2, cost + min(A, t) + D * llabs(i - n));
        }
    }

    /*
    if(n - (n % 5) >= 5) dfs((n - n % 5) / 5, cost + C + D * (n % 5));
    dfs((n + (5 - n % 5)) / 5, cost + C + D * (5 - n % 5));

    if(n - (n % 3) >= 3) dfs((n - n % 3) / 3, cost + B + D * (n % 3));
    dfs((n + (3 - n % 3)) / 3, cost + B + D * (3 - n % 3));

    if(n - (n % 2) >= 2) dfs((n - n % 2) / 2, cost + A + D * (n % 2));
    dfs((n + (2 - n % 2)) / 2, cost + A + D * (2 - n % 2));
    */

    if(Dig(n) + ddig < 18) res = min(res, cost + n * D);

    return;
}

