using i64 = long long;

i64 a, b, c, d;
std::map<i64, i64> memo;

i64 rec(const i64 n) {
    if (n <= 1) return n * d;
    if (memo.find(n) != memo.end()) return memo[n];
    const i64 p = rec(n / 2) + a + n % 2 * d,
        q = n > 2 ? rec(n / 2 + 1) + a + (2 - n % 2) * d : p,
        r = rec(n / 3) + b + n % 3 * d,
        s = rec(n / 3 + 1) + b + (3 - n % 3) * d,
        t = rec(n / 5) + c + n % 5 * d,
        u = rec(n / 5 + 1) + c + (5 - n % 5) * d;
    i64 min = std::min({ p, q, r, s, t, u });
    if (n < min / d) min = n * d;
    return memo[n] = min;
}

