    if (abs(need - go) >= abs(need - (go + pref[i]))) ++tk;
    need = abs(need - tk * pref[i]);
    add(extra, tk);
  }
  ll all = mul(extra, d);
  for (int x : have) {
    if (x == 2) add(all, a);
    if (x == 3) add(all, b);
    if (x == 5) add(all, c);
  }
