ll A,B,C,D,N;

map<ll,ll> dp;

const ll inf=1e18;

ll dfs(ll x){
	if(dp.count(x)){
		return dp[x];
	}

	if(x==0){
		return 0;
	}
	if(x==1){
		return D;
	}

	ll ans=inf;

	ans=min(ans,x%2*D+dfs(x/2)+A);
	if(x%2!=0)ans=min(ans,(2-x%2)*D+dfs(x/2+1)+A);

	ans=min(ans,x%3*D+dfs(x/3)+B);
	if(x%3!=0)ans=min(ans,(3-x%3)*D+dfs(x/3+1)+B);

	ans=min(ans,x%5*D+dfs(x/5)+C);
	if(x%5!=0)ans=min(ans,(5-x%5)*D+dfs(x/5+1)+C);

	if(x*D>=0 && x*D<=ans){
		ans=x*D;
	}

	return dp[x]=ans;
}
