void paytowin(long long N, int A, int B, int C, int D){
  long long ans[4];
  int a, b, c, d;
  long long tmp;
  int cost[4]={A, B, C, D};
  for(int i=0;i<4;i++){
    for(int j=i;j<4;j++){
      if(cost[i] > cost[j]){
        tmp = cost[i];
        cost[i] = cost[j];
        cost[j] = tmp;
      }
    }
  }
  for(int i=0;i<4;i++){
    if(cost[i] == A){
      a = i;
    }else if(cost[i] == B){
      b = i;
    }else if(cost[i] == C){
      c = i;
    }else if(cost[i] == D){
      d = i;
    }
  }
  long long para[4] = {0, 0, 0, 0};
  long long coins;
  bool end_flag = 1;
  while(end_flag){
    while(end_flag){
      while(end_flag){
        while(end_flag){
          if( NUM(para[a], para[b], para[c], para[d]) == N ){
            for(int i=0;i<4;i++){
              ans[i] = para[i];
              end_flag = 0;
            }
          }
          coins = A*para[a] + B*para[b] + C*para[c] +D*para[d];
          para[1]++;
          tmp = para[0];
          para[0] = 0;
          if( A*para[a] + B*para[b] + C*para[c] +D*para[d] > coins ){
            coins = A*para[a] + B*para[b] + C*para[c] +D*para[d];
            break;
          }else{
            para[1]--;
            para[0] = tmp + 1;
          }
        }
        if(para[1] != 0){
          para[2]++;
          tmp = para[1];
          para[1] = 0;
          if( A*para[a] + B*para[b] + C*para[c] +D*para[d] > coins ){
            coins = A*para[a] + B*para[b] + C*para[c] +D*para[d];
            break;
          }else{
            para[2]--;
            para[1] = tmp + 1;
          }
        }
      }
      if(para[2] != 0){
        para[3]++;
        tmp = para[2];
        para[2] = 0;
        if( A*para[a] + B*para[b] + C*para[c] +D*para[d] > coins ){
          coins = A*para[a] + B*para[b] + C*para[c] +D*para[d];
          break;
        }else{
          para[3]--;
          para[2] = tmp + 1;
        }
      }
    }
  }
  cout << (A*ans[a] + B*ans[b] + C*ans[c] +D*ans[d] + D) << endl;
  cout << ans[a] << endl << ans[b] << endl << ans[c] << endl << ans[d];
}

