const int ITER_MAX = 1E6, LMT = 2E9;
int n, val[10];

int BFS(int s = n) {
	set<int> vis = {s};
	map<int, int> cost;
	set<pi> best = {{0, s}};
	int iter = 0;
	while(!best.empty()) {
		int nr = (*best.begin()).sd;
		best.erase(best.begin());
		for(int x : {2, 3, 5}) {
			//decrease
			int maybe = (nr % x) * val[1] + val[x];
			if(nr/x < LMT)
				maybe = min(maybe, (nr - nr/x) * val[1]);
			if(!vis.count(nr/x) || cost[nr/x] > cost[nr] + maybe) {
				vis.insert(nr/x);
				cost[nr/x] = cost[nr] + maybe;
				best.insert({cost[nr/x], nr/x});
			}
			if(nr/x < LMT)
				maybe = min(maybe, (nr - (nr + x - 1)/x * val[1]));
			maybe = ((x - nr % x) % x) * val[1] + val[x];
			if(!vis.count((nr + x - 1)/x) || cost[(nr + x - 1)/x] > cost[nr] + maybe) {
				vis.insert((nr + x - 1)/x);
				cost[(nr + x - 1)/x] = cost[nr] + maybe;
				best.insert({cost[(nr + x - 1)/x], (nr + x - 1)/x});
			}
		}	
		++iter;
	}
	return cost[1] + val[1];
}

