const long double EPS = 1e-8;

bool overflowAdd(ll a, ll b) {
    return LLONG_MAX - b <= a;
}

bool overflowProduct(ll a, ll b) {
    if (a == 0 || b == 0) return false;
    ll product = a * b;
    return product / a != b;
}

ll dfs(ll N, ll A, ll B, ll C, ll D, unordered_map<ll, ll>& memo) {
    if (memo.find(N) != memo.end()) return memo[N];
    ll cost = LLONG_MAX;
    vector<pair<ll, ll>> pairList{{2, A}, {3, B}, {5, C}};
    for (const auto& p : pairList) {
        for (const ll diff : {1, -1}) {
            ll n = N;
            while (n % p.first != 0) n += diff;
            if (n / p.first >= N) continue;
            ll newCost = abs(N-n) * D + p.second;
            if (overflowAdd(newCost, dfs(n/p.first, A, B, C, D, memo))) continue;
            newCost += dfs(n/p.first, A, B, C, D, memo);
            cost = min(cost, newCost);
        }
    }
    if (!overflowProduct(N, D)) {
        cost = min(cost, N*D);
    }
    memo[N] = cost;
    assert(cost > 0);
    return cost;
}

