	if (n == 0)return 0;
	else if (n == 1)return d;
	int res = INF;
	if (n <= INF / d) {
		res = n * d;
	}
	int to = n / 2;
	chmin(res, abs(n - to * 2)*d + rec(to) + a);
	to = (n + 1) / 2;
	chmin(res, abs(n - to * 2)*d + rec(to) + a);
	to = n / 3;
	chmin(res, abs(n - to * 3)*d + rec(to) + b);
	to = (n + 2) / 3;
	chmin(res, abs(n - to * 3)*d + rec(to) + b);
	to = n / 5;
	chmin(res, abs(n - to * 5)*d + rec(to) + c);
	to = (n + 4) / 5;
	chmin(res, abs(n - to * 5)*d + rec(to) + c);
	return mp[n] = res;
