llint solve(llint n, llint a, llint b, llint c, llint d){
  std::priority_queue<std::array<llint, 2> > pq;

  std::map<llint, llint> M;

  std::set<std::array<llint,2> > check;
  pq.push({-0, n});
  while(!pq.empty()){
    const auto top = pq.top();
    //std::cout << top[0] << " " << top[1] << std::endl;
    if(top[1]==0) return -top[0];
    pq.pop();

    // d
    if(top[1]==1){
      std::array<llint, 2> data = {top[0]-d, top[1]-1};
      if(check.find(data) == check.end()){
	pq.push(data);
	check.insert(data);
      }
    }

    // a
    if(top[1]<2) continue;
    llint tmp = top[1]/2;
    llint amari = top[1]%2;
    llint added_cost = std::min(a+amari*d, std::abs(top[1]-tmp)*d);
    if(added_cost < 0) added_cost = a+amari*d;
    std::array<llint, 2> data = {top[0]-added_cost, tmp };
    if(check.find(data) == check.end()){
      pq.push(data);
      check.insert(data);
    }
    if(amari){
      added_cost = std::min(a+(2-amari)*d, std::abs(top[1]-tmp+1)*d);
      if(added_cost < 0) added_cost = a+(2-amari)*d;
      data = {top[0]-added_cost, tmp+1};
      if(check.find(data) == check.end()){
	pq.push(data);
	check.insert(data);
      }
    }

    // b
    if(top[1]<3) continue;
    tmp = top[1]/3;
    amari = top[1]%3;
    added_cost = std::min(b + amari*d, std::abs(top[1]-tmp)*d);
    if(added_cost < 0) added_cost = b+amari*d;
    data = {top[0]-added_cost, tmp };
    if(check.find(data) == check.end()){
      pq.push(data);
      check.insert(data);
    }
    if(amari){
      added_cost = std::min(b+(3-amari)*d, std::abs(top[1]-tmp+1)*d);
      if(added_cost < 0) added_cost = b+(3-amari)*d;
      data = {top[0]-added_cost, tmp+1};
      if(check.find(data) == check.end()){
	pq.push(data);
	check.insert(data);
      }
    }

    // c
    if(top[1]<5) continue;
    tmp = top[1]/5;
    amari = top[1]%5;
    added_cost = std::min(c + amari*d, std::abs(top[1]-tmp)*d);
    if(added_cost < 0) added_cost = c+amari*d;
    data = {top[0]-added_cost, tmp };
    if(check.find(data) == check.end()){
      pq.push(data);
      check.insert(data);
    }    
