constexpr int I_INF = numeric_limits<int>::max();
constexpr ll L_INF = numeric_limits<ll>::max();

//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

ll N, A, B, C, D;
ll score;
unordered_map<ll, ll> dp;

ll dfs(ll x, ll cost) {
    if (dp.find(x) != dp.end()) {
        return dp[x];
    }
    if (cost >= score) {
        return L_INF;
    }

    ll res = L_INF;
    dp[x] = L_INF;

    // all D
    ll r2 = x % 2;
    ll r3 = x % 3;
    ll r5 = x % 5;
    bool ok = true;
    ok &= x <= r2 + A / D;
    ok &= x <= r3 + B / D;
    ok &= x <= (3 - r3) + B / D;
    ok &= x <= r5 + C / D;
    ok &= x <= (5 - r5) + C / D;
    if (ok) {
        score = min(score, cost + D * x);
        dp[x] = min(dp[x], score);
        return score;
    }

    // 2
    dfs(x / 2, cost + r2 * D + A);

    // 3
    if (r3 <= 1) {
        dfs(x / 3, cost + r3 * D + B);
    }
    else {
        dfs(x / 3 + 1, cost + (3 - r3) * D + B);
    }

    // 5
    if (r5 <= 2) {
        dfs(x / 5, cost + r5 * D + C);
    }
    else {
        dfs(x / 5 + 1, cost + (5 - r5) * D + C);
    }

    dp[x] = res;
    return res;
}

void solve() {
    int Q;
    cin >> Q;
    while (Q--) {
        cin >> N >> A >> B >> C >> D;

        dp.clear();
        priority_queue<Pll, vector<Pll>, greater<Pll>> q;
        dp[N] = 0;
        q.emplace(0, N);
        while (!q.empty()) {
            auto [c, x] = q.top();
            q.pop();
            if (dp[x] < c) continue;

            ll r2 = x % 2;
            ll r3 = x % 3;
            ll r5 = x % 5;

            bool ok = true;
            ok &= x <= r2 + A / D;
            ok &= x <= r3 + B / D;
            ok &= x <= (3 - r3) + B / D;
            ok &= x <= r5 + C / D;
            ok &= x <= (5 - r5) + C / D;
            if (ok) {
                ll nc = c + D * x;
                if (dp.find(0) == dp.end()) {
                    dp[0] = L_INF;
                }
                dp[0] = min(dp[0], nc);
                continue;
            }

            // 2
            ll nc;
            nc = c + r2 * D + A;
            if (dp.find(x / 2) == dp.end()) {
                dp[x / 2] = L_INF;
            }
            if (nc < dp[x / 2]) {
                dp[x / 2] = nc;
                q.emplace(nc, x / 2);
            }

            // 3
            if (r3 <= 1) {
                nc = c + r3 * D + B;
                if (dp.find(x / 3) == dp.end()) {
                    dp[x / 3] = L_INF;
                }
                if (nc < dp[x / 3]) {
                    dp[x / 3] = nc;
                    q.emplace(nc, x / 3);
                }
            }
            else {
                nc = c + (3 - r3) * D + B;
                if (dp.find(x / 3 + 1) == dp.end()) {
                    dp[x / 3 + 1] = L_INF;
                }
                if (nc < dp[x / 3 + 1]) {
                    dp[x / 3 + 1] = nc;
                    q.emplace(nc, x / 3 + 1);
                }
            }

            // 5
            if (r5 <= 2) {
                nc = c + r5 * D + C;
                if (dp.find(x / 5) == dp.end()) {
                    dp[x / 5] = L_INF;
                }
                if (nc < dp[x / 5]) {
                    dp[x / 5] = nc;
                    q.emplace(nc, x / 5);
                }
            }
            else {
                nc = c + (5 - r5) * D + C;
                if (dp.find(x / 5 + 1) == dp.end()) {
                    dp[x / 5 + 1] = L_INF;
                }
                if (nc < dp[x / 5 + 1]) {
                    dp[x / 5 + 1] = nc;
                    q.emplace(nc, x / 5 + 1);
                }
            }
        }

        cout << dp[0] << "\n";
    }
}

