std::map<ll, ll> memo;


ll Solve(ll N, ll A, ll B, ll C, ll D)
{

	if(N == 0) return 0;
	if(N == 1) return D;
	if(memo[N] > 0) return memo[N];

	ll result = LONG_MAX;
	if(N < result/D)
		result = N*D;

	if(N%3 == 0)
		result = min(result, Solve(N/3, A, B, C, D) + B);
	else
	{
		result = min(result, B + (D*(N%3)) + Solve((N-(N%3)) / 3, A, B, C, D));
		result = min(result, B + (D*(3- N%3)) + Solve((N+(3 - N%3)) / 3, A, B, C, D));
	}

	if(N%5 == 0)
		result = min(result, Solve(N/5, A, B, C, D) + C);
	else
	{
		result = min(result, C + (D*(N%5)) + Solve((N-(N%5)) / 5, A, B, C, D));
		result = min(result, C + (D*(5- N%5)) + Solve((N+5-N%5) / 5, A, B, C, D));
	}


	if(N%2 == 0)
		result = min(result, Solve(N/2, A, B, C, D) + A);
	else
	{
		result = min(result, A + D + Solve((N+1)/2, A, B, C, D));
		result = min(result, A + D + Solve((N-1)/2, A, B, C, D));
	}


	return memo[N] = result;
}

