LL solve(LL n){
  if(n == 0)return 0;
  if(n == 1)return d;
  if(memo.count(n))return memo[n];
  LL res = LINF;

  if(n < res/d) res = n*d;

  chmin(res, solve(n/2)+a+d*(n%2));
  chmin(res, solve(n/3)+b+d*(n%3));
  chmin(res, solve(n/5)+c+d*(n%5));

