	return 0;
	if(mp.find(n)!=mp.end())
	    return mp[n];
	r1=n%2;
	r2=n%3;
	r3=n%5;
	ll k1=r1*d+a+solve((n-r1)/2);
	ll k2=r2*d+b+solve((n-r2)/3);
