	if(n>1)
	k6=(5-r3)*d+c+solve((n+5-r3)/5);
	mp[n]=min(k1,min(k2,min(k3,min(k4,min(k5,k6)))));
	if(n<1e9)
	mp[n]=min(mp[n],n*d);
