template <typename F>
inline constexpr decltype(auto) fix(F&& f) noexcept {
    return [=](auto g) {
        return [=](auto&&... args) {
            return f(g(g), std::forward<decltype(args)>(args)...);
        };
    }([=](auto g) {
        return [=](auto&&... args) {
            return f(g(g), std::forward<decltype(args)>(args)...);
        };
    });
}

void solve() {
    int Q;
    cin >> Q;
    unordered_map<ll, ll> dp;
    while (Q--) {
        ll N, A, B, C, D;
        cin >> N >> A >> B >> C >> D;
        dp.clear();

        auto dfs = [&](auto&& dfs, ll x) -> ll {
            if (dp.find(x) != dp.end()) {
                return dp[x];
            }

            if (x == 0) {
                dp[x] = 0;
                return dp[x];
            }

            if (x == 1) {
                dp[x] = D;
                return dp[x];
            }

            ll res = L_INF;

            ll r2 = x % 2;
            ll r3 = x % 3;
            ll r5 = x % 5;

            // goto 0
            if (x < L_INF / D) {
                res = dfs(0) + x * D;
            }

            // 2
            res = min(res, dfs(x / 2) + A + r2 * D);
            res = min(res, dfs((x + 1) / 2) + A + r2 * D);

            // 3
            res = min(res, dfs(x / 3) + B + r3 * D);
            res = min(res, dfs((x + 2) / 3) + B + (3 - r3) * D);

            // 5
            res = min(res, dfs(x / 5) + C + r5 * D);
            res = min(res, dfs((x + 4) / 5) + C + (5 - r5) * D);

            dp[x] = res;
            return res;
        };

        ll res = fix(dfs)(N);
        cout << res << "\n";
    }
}

