void q() {
  inl(N, A, B, C, D);

  priority_queue<P, vp, greater<>> Q;
  unordered_map<ll, ll> vis;
  auto val = [&](ll x) -> ll {
    auto it = vis.find(x);
    if (it != vis.end())
      return it->second;
    else
      return infLL;
  };
  auto emp = [&](ll x, ll y) {
    if (val(y) > x){
      vis[y] = x;
      Q.emplace(x, y);
    }
  };

  emp(0, N);
  while (1) {
    auto cur = Q.top();
    Q.pop();
    ll x = cur.first;
    ll y = cur.second;
    //trc(cur, x, y);
    if (y == 0) {
      out(x);
      return;
    }

    if (y % 2 == 0) {
      emp(x + A, y / 2);
    } else {
      ll y2 = y, x2 = x + A;
      while (y2 % 2 != 0) y2++, x += D;
      emp(x2, y2);
      y2 = y, x2 = x + A;
      while (y2 % 2 != 0) y2--, x += D;
      emp(x2, y2);
    }

    if (y % 3 == 0) {
      emp(x + B, y / 3);
    } else {
      ll y2 = y, x2 = x + B;
      while (y2 % 3 != 0) y2++, x += D;
      emp(x2, y2);
      y2 = y, x2 = x + B;
      while (y2 % 3 != 0) y2--, x += D;
      emp(x2, y2);
    }

    if (y % 5 == 0) {
      emp(x + C, y / 5);
    } else {
      ll y2 = y, x2 = x + C;
      while (y2 % 5 != 0) y2++, x += D;
      emp(x2, y2);
      y2 = y, x2 = x + C;
      while (y2 % 5 != 0) y2--, x += D;
      emp(x2, y2);
    }
  }
}

