ll solve(ll N, vll cost) {
    map<ll, ll> best_cost;
    pql<pair<ll, ll>> Q;
    Q.push(mp(0, N));
    vi num = {2, 3, 5};
    while (!Q.empty()) {
        auto [coin, n] = Q.top();
        Q.pop();
        if (Contains(best_cost, n) && coin >= best_cost[n]) continue;
        best_cost[n] = coin;
        // dump(n, coin);
        rep(i, 3) {
            int k = num[i];
            if (n % k == 0) {
                ll new_cost = coin + cost[i];
                ll new_n = n / k;
                if (!Contains(best_cost, new_n) || new_cost < best_cost[new_n]) {
                    Q.push(mp(new_cost, new_n));
                }
            } else {
                ll new_n = n / k;
                ll new_cost = coin + cost[3] * abs(new_n * k - n) + cost[i];
                if (!Contains(best_cost, new_n) || new_cost < best_cost[new_n]) {
                    Q.push(mp(new_cost, new_n));
                }

                new_n = (n + k - 1) / k;
                new_cost = coin + cost[3] * abs(new_n * k - n) + cost[i];
                if (!Contains(best_cost, new_n) || new_cost < best_cost[new_n]) {
                    Q.push(mp(new_cost, new_n));
                }
            }
        }
    }
    return best_cost[1] + cost[3];
}

