#define all(x) (x).begin(), (x).end()

ll d;

ll divs[3] = {2, 3, 5};
ll costs[3];

unordered_map<ll, ll> memo;

ll Solve(ll n) {
  if (memo.find(n) != memo.end()) return memo[n];
  ll ret = LLONG_MAX;
  if (n == 1) {
    ret = min(ret, d);
    return memo[1] = ret;
  }

  for (int i = 0; i < 3; i++) {
    ll div = divs[i];
    ll lower = n / div;
    if (lower) {
      ll addcost = costs[i] + d * (n % div);
      if (n < 1e9 + 100) addcost = min(addcost, d * (n - lower));
      ret = min(ret, Solve(lower) + addcost);
    }
    if (n % div) {
      ll addcost = costs[i] + d * (div - (n % div));
      if (n < 1e9 + 100) addcost = min(addcost, d * (n - (lower + 1)));
      ret = min(ret, Solve(lower + 1) + addcost);
    }
  }

  return memo[n] = ret;
}

