// [l, r) from l to r
struct range {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { ++i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr l, r;
  constexpr range(int l_, int r_): l(l_), r(std::max(l_, r_)) { }
  constexpr itr begin() const { return l; }
  constexpr itr end() const { return r; }
};

// [l, r) from r to l
struct revrange {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { --i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr l, r;
  constexpr revrange(int l_, int r_): l(l_ - 1), r(std::max(l_, r_) - 1) { }
  constexpr itr begin() const { return r; }
  constexpr itr end() const { return l; }
};

template <class T>
struct fix_point: private T {
  explicit constexpr fix_point(T &&func): T(std::forward<T>(func)) { }
  template <class... Args>
  constexpr decltype(auto) operator () (Args &&... args) const {
    return T::operator()(*this, std::forward<Args>(args)...);
  }
};

constexpr int64_t inf = (1ll << 60);

int solve() {
  int64_t N, A, B, C, D;
  std::cin >> N >> A >> B >> C >> D;
  std::map<int64_t, int64_t> dp;
  dp[0] = 0;
  dp[1] = D;
  std::cout << fix_point([&](auto dfs, int64_t cur) -> int64_t {
    if (auto it = dp.find(cur); it != dp.end()) {
      return it -> second;
    }
    int64_t res = inf;
    if (D <= inf / cur) {
      chmin(res, D * cur);
    }
    {
      int tmp = cur % 2;
      if (cur - tmp > 0) {
        chmin(res, A + dfs((cur - tmp) / 2) + D * tmp);
      }
      if (tmp != 0) {
        chmin(res, A + dfs((cur + 2 - tmp) / 2) + D * (2 - tmp));
      }
    }
    {
      int tmp = cur % 3;
      if (cur - tmp > 0) {
        chmin(res, B + dfs((cur - tmp) / 3) + D * tmp);
      }
      if (tmp != 0) {
        chmin(res, B + dfs((cur + 3 - tmp) / 3) + D * (3 - tmp));
      }
    }
    {
      int tmp = cur % 5;
      if (cur - tmp > 0) {
        chmin(res, C + dfs((cur - tmp) / 5) + D * tmp);
      }
      if (tmp != 0) {
        chmin(res, C + dfs((cur + 5 - tmp) / 5) + D * (5 - tmp));
      }
    }
    return dp[cur] = res;
  })(N) << '\n';
  return 0;
}

