            dist[i] = inf;
        while(!que.empty()) {
            pair<long long, int> pr = que.top(); que.pop();
            if(pr.first > dist[pr.second]) continue;
            int u = pr.second, v;
            v = u * 2;
            if(v <= upp && dist[u] + A < dist[v]) {
                dist[v] = dist[u] + A;
                que.emplace(dist[v], v);
            }
            v = u * 3;
            if(v <= upp && dist[u] + B < dist[v]) {
                dist[v] = dist[u] + B;
                que.emplace(dist[v], v);
            }
            v = u * 5;
            if(v <= upp && dist[u] + C < dist[v]) {
                dist[v] = dist[u] + C;
                que.emplace(dist[v], v);
            }
            v = u + 1;
            if(v <= upp && dist[u] + D < dist[v]) {
                dist[v] = dist[u] + D;
                que.emplace(dist[v], v);
            }
            v = u - 1;
            if(v >= 0 && v <= upp && dist[u] + D < dist[v]) {
                dist[v] = dist[u] + D;
                que.emplace(dist[v], v);
            }
        }
        for(int i = -5; i <= 5; ++i)
            f[i] = D * abs(i);
        while(N > upp) {
            ca = inf;
            cb = inf;
            cc = inf;
            for(int i = -5; i <= 5; ++i) {
                if(N + i < 0) continue;
                if((N + i) % 2 == 0) {
                    t = (N + i) / 2;
                    if(t >= N) continue;
                    c = 1.0 * (A + f[i]) / (N - t);
                    if(c < ca) {
                        ca = c;
                        tA = t;
                    }
                }
                if((N + i) % 3 == 0) {
                    t = (N + i) / 3;
                    if(t >= N) continue;
                    c = 1.0 * (B + f[i]) / (N - t);
                    if(c < cb) {
                        cb = c;
                        tB = t;
                    }
