                if((N + i) % 5 == 0) {
                    t = (N + i) / 5;
                    if(t >= N) continue;
                    c = 1.0 * (C + f[i]) / (N - t);
                    if(c < cc) {
                        cc = c;
                        tC = t;
                    }
                }
            }
            if(ca <= cb && ca <= cc && ca <= D) {
                ans += A + f[tA * 2 - N];
                N = tA;
            } else if(cb <= ca && cb <= cc && cb <= D) {
                ans += B + f[tB * 3 - N];
