                ans = MIN(ans, ans1);
            }
        }

        {
            ll tmp = calc(m);
            if ((double)tmp + (double)(n % prime[k]) * d + a[k] < LINF3) {
                ll ans1 = tmp + (n % prime[k]) * d + a[k];
                ans = MIN(ans, ans1);
            }
        }

        if (n % prime[k]) {
            ll tmp = calc(m + 1);
            if ((double)tmp + (double)(prime[k] - n % prime[k]) * d + a[k] < LINF3) {
                ll ans1 = tmp + (prime[k] - n % prime[k]) * d + a[k];
                ans = MIN(ans, ans1);
