LL multi(LL a, LL b) {
	LL myInf = getInf();
	LL res = 0;
	LL aa = a, bb = b;
	while (aa < myInf && res < myInf && bb > (LL)(0)) {
		res += (bb & (LL)(1)) * aa;
		aa = aa * (LL)(2);
		bb = bb / (LL)(2);
	}
	if (aa >= myInf || res >= myInf) {
		return myInf; 
	} else {
		return res;
	}
}

