ll dfs(ll n,ll a,ll b,ll c,ll d,ll minn,ll coin,ll &mincoin,bool &correct){
  if(correct){
    if(n<minn){
      mincoin=min(coin+n-1,mincoin);
      return min(coin+n-1,mincoin);
    }
    if(n==1){
      mincoin=min(coin,mincoin);
      return min(coin,mincoin);
    }
    if(coin>mincoin){
      return mincoin;
    }
    ll s=mincoin;
    if(n%5==0){
      s=min(s,dfs(n/5,a,b,c,d,minn,coin+c,mincoin,correct));
    }
    if(n%3==0){
      s=min(s,dfs(n/3,a,b,c,d,minn,coin+b,mincoin,correct));
    }
    if(n%2==0){
      s=min(s,dfs(n/2,a,b,c,d,minn,coin+a,mincoin,correct));
    }
    s=min(s,dfs(n-1,a,b,c,d,minn,coin+d,mincoin,correct));
    s=min(s,dfs(n+1,a,b,c,d,minn,coin+d,mincoin,correct));
    mincoin=s;
    return s;
  }else{
    if(n<minn){
      mincoin=coin+n-1;
      correct=true;
      return coin+n-1;
    }
    if(n==1){
      mincoin=coin;
      correct=true;
      return coin;
    }
    ll s;
    if(n%5==0){
      s=dfs(n/5,a,b,c,d,minn,coin+c,mincoin,correct);
    }
    if(n%3==0){
      s=min(s,dfs(n/3,a,b,c,d,minn,coin+b,mincoin,correct));
    }
    if(n%2==0){
      s=min(s,dfs(n/2,a,b,c,d,minn,coin+a,mincoin,correct));
    }
    s=min(s,dfs(n-1,a,b,c,d,minn,coin+d,mincoin,correct));
    s=min(s,dfs(n+1,a,b,c,d,minn,coin+d,mincoin,correct));
    mincoin=s;
    correct=true;
    return s;
  }
}

