using namespace std;
vector<unsigned int>cost;

unsigned long long pay2win(long long goal) {
    if (goal == 1) {
        return cost[3];
    }
    if (goal == 0) {
        return 0;
    }
    vector<unsigned long long>output;
    if (goal % 2 == 0) {
        output.push_back(pay2win(goal / 2) + cost[0]);
    }
    else {
        output.push_back(pay2win((goal + 1) / 2) + cost[3] + cost[0]);
        output.push_back(pay2win((goal - 1) / 2) + cost[3] + cost[0]);
    }
    if (goal % 3 == 0) {
        output.push_back(pay2win(goal / 3) + cost[1]);
    }
    else if (goal % 3 == 1) {
        output.push_back(pay2win(goal / 3) + cost[1] + cost[3]);
    }
    else {
        output.push_back(pay2win((goal + 1) / 3) + cost[1] + cost[3]);
    }
    if (goal % 5 == 0) {
        output.push_back(pay2win(goal / 5) + cost[2]);
    }
    else if(goal%5==1){
        output.push_back(pay2win(goal / 5) + cost[2]+cost[3]);
    }
    else if (goal % 5 == 2) {
        output.push_back(pay2win(goal / 5) + cost[2] + 2 * cost[3]);
    }
    else if (goal % 5 == 3) {
        output.push_back(pay2win((goal - 2) / 5) + cost[2] +  cost[3] * 2);
    }
    else if (goal % 5 == 4) {
        output.push_back(pay2win((goal - 1) / 5) + cost[2] + cost[3]);
    }
    if (output.empty()) {
        output.push_back(pay2win(goal - 1) + cost[3]);
        output.push_back(pay2win(goal + 1) + cost[3]);
    }

    sort(output.begin(), output.end());
    return output[0];
}

int main()
{
    int times;
    unsigned int goal;
    cost.resize(4);
    cin >> times;
    vector<unsigned long long>output;
    for (int i = 0; i < times; i++) {
        cin >> goal;
        for (int j = 0; j < 4; j++) {
            cin >> cost[j];
        }
        output.push_back(pay2win(goal));
    }
    for (int i = 0; i < times; i++) {
        cout << output[i] << endl;
    }

    return 0;
}

