map<llong, llong> mp;

llong dfs(llong coin) {
    if (coin <= 0) return 0;
    if (mp.count(coin) != 0) return mp[coin];

    llong ret = numeric_limits<llong>::max();
    if (coin <= 2000000000) ret = coin * d;

    if (coin >= 2) {
        ret = min(dfs(coin / 2) + a + d * (coin % 2), ret);
    }
    else {
        ret = min(dfs(0) + d, ret);
    }

    if (coin >= 3) {
        ret = min(dfs(coin / 3) + b + d * (coin % 3), ret);
    }
    else {
        ret = min(dfs(0) + d * coin, ret);
    }

    if (coin >= 5) {
        ret = min(dfs(coin / 5) + c + d * (coin % 5), ret);
    }
    else {
        ret = min(dfs(0) + d * coin, ret);
    }

    return mp[coin] = ret;
}

