map<ll,ll> memo;
vl mult = {2,3,5};
vl cst = {-1,-1,-1};
ll d;
const double inf = 1e18;

ll f(ll n){
    auto it = memo.find(n);
    if(it != memo.end()) return it->second;
    ll ans = inf;
    if(double(n) * d < inf){
        ans = n*d;
    }
    for(int i=0;i<3;i++){
        auto k = mult[i];
        ll cr = ((n%k)*d) + f(n/k) + cst[i];
        ans = min(ans, cr);
        if(n%k != 0){
            cr = ((k - (n%k))*d) + f((n+k-1)/k) + cst[i];
            ans = min(ans, cr);
        }
    }
    memo[n] = ans;
    return ans;
}

