typedef long long int ll;
const int INF = 1<<30;
const long long LINF = 1LL<<60;
const long long MOD = (long long)1e9 + 7;

map<ll, ll> memo;
ll n, a, b, c, d;

ll dfs(ll x){
    if(memo.find(x) != end(memo)){
        return memo[x];
    }
    if(x <= 1){
        return x * d;
    }
    ll res = LINF;
    if(x <= (ll)1e9){
        res = min(res, x * d);
    }
    if(x % 2 == 0){
        res = min(res, dfs(x / 2) + a);
    }else{
        res = min(res, dfs((x + 1) / 2) + a + d);
        res = min(res, dfs((x - 1) / 2) + a + d);
    }
    if(x % 3 == 0){
        res = min(res, dfs(x / 3) + b);
    }else{
        res = min(res, dfs((x + 3 - (x % 3)) / 3) + b + (3 - (x % 3)) * d);
        res = min(res, dfs((x - (x % 3)) / 3) + b + (x % 3) * d);
    }
    if(x % 5 == 0){
        res = min(res, dfs(x / 5) + c);
    }else{
        res = min(res, dfs((x + 5 - (x % 5)) / 5) + c + (5 - (x % 5)) * d);
        res = min(res, dfs((x - (x % 5)) / 5) + c + (x % 5) * d);
    }
    return memo[x] = res;
}

