ll a, b, c, d;
map<ll, ll> H;
ll solve(ll n){
    if (H.count(n)) return H[n];
    ll res = 1e18;
    if ( n <= res / d) res = n*d;
    res = min(res, abs(n - n/2*2) * d + a + solve(n/2));
    res = min(res, abs(n - (n+1)/2*2) * d + a + solve((n+1)/2));
    res = min(res, abs(n - n/3*3) * d + b + solve(n/3));
    res = min(res, abs(n - (n+2)/3*3) * d + b + solve((n+2)/3));
    res = min(res, abs(n - n/5*5) * d + c + solve(n/5));
    res = min(res, abs(n - (n+4)/5*5) * d + c + solve((n+4)/5));
    return H[n] = res;
}

