using namespace std;

long long a, b, c, d, n, t, ans, i, j, k, x, cost;
map<long long, long long> dp;

long long solve(long long n) {
	if (n == 1) return d;
	if (n == 0) return 0;
	if (n < 0) return 1LL << 60;

	if (dp.find(n) != dp.end()) return dp[n];

	long long ans = 1LL << 60;

	if (n < (1LL << 62) / d) ans = n * d;

	if (n % 2 == 0) ans = min(ans, a + solve(n / 2));
	else {
		ans = min(ans, solve((n + 1) / 2) + a + d);
		ans = min(ans, solve((n - 1) / 2) + a + d);
	}

	if (n % 3 == 0) ans = min(ans, b + solve(n / 3));
	else {
		if ((n + 1) % 3 == 0) ans = min(ans, solve((n + 1) / 3) + b + d);
		if ((n + 2) % 3 == 0) ans = min(ans, solve((n + 2) / 3) + b + d + d);
		if ((n - 1) % 3 == 0) ans = min(ans, solve((n - 1) / 3) + b + d);
		if ((n - 2) % 3 == 0) ans = min(ans, solve((n - 2) / 3) + b + d + d);
	}
	if (n % 5 == 0) ans = min(ans, c + solve(n / 5));

	else {
		if ((n + 1) % 5 == 0) ans = min(ans, solve((n + 1) / 5) + c + d);
		if ((n + 2) % 5 == 0) ans = min(ans, solve((n + 2) / 5) + c + d + d);
		if ((n + 3) % 5 == 0) ans = min(ans, solve((n + 3) / 5) + c + d * 3);
		if ((n + 4) % 5 == 0) ans = min(ans, solve((n + 4) / 5) + c + d * 4);

		if ((n - 1) % 5 == 0) ans = min(ans, solve((n - 1) / 5) + c + d);
		if ((n - 2) % 5 == 0) ans = min(ans, solve((n - 2) / 5) + c + d + d);
		if ((n - 3) % 5 == 0) ans = min(ans, solve((n - 3) / 5) + c + d * 3);
		if ((n - 4) % 5 == 0) ans = min(ans, solve((n - 4) / 5) + c + d * 4);
	}

	dp[n] = ans;
	return ans;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> t;
	while (t--) {
		cin >> n >> a >> b >> c >> d;

		ans = solve(n);
		dp.clear();

		cout << ans << "\n";
	}

	return 0;
}

