struct custom_hash {
    static uint64_t splitmix64(uint64_t x) {
        // http://xorshift.di.unimi.it/splitmix64.c
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }

    size_t operator()(uint64_t x) const {
        static const uint64_t FIXED_RANDOM = chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64(x + FIXED_RANDOM);
    }
};

gp_hash_table<long long, ll, custom_hash> mp;

ll calc(ll n) {
	if(n == 1) return d;
	if(n == 0) return 0;
	ll ret = 1e18;
	if(mp.find(n) != mp.end()) return mp[n];
	ret = min(ret, d * (n % 2) + calc(n / 2) + a);
	ret = min(ret, d * (n % 3) + calc(n / 3) + b);
	ret = min(ret, d * (n % 5) + calc(n / 5) + c);

	ll d1 = ((n+(2-n%2)))/2;
	ll d2 = ((n+(3-n%3)))/3;
	ll d3 = ((n+(5-n%5)))/5;

	if(d1 < n) ret = min(ret, d * (2 - n % 2) + calc(d1) + a);
	if(d2 < n) ret = min(ret, d * (3 - n % 3) + calc(d2) + b);
	if(d3 < n) ret = min(ret, d * (5 - n % 5) + calc(d3) + c);
	ret = min(ret, d * n);

	return mp[n] = ret;
}

