int INF = 1e+18;
int a[3], d;
map<int, int> dp;

int dfs(int n) {
	if (n <= 1) return n * d;
	if (dp.find(n) != dp.end()) return dp[n];

	vector<int> ks = {2, 3, 5};
	int res, ret = (n <= INF / d) ? n * d : INF;
	for (int i = 0; i < 3; i++) {
		int k = ks[i];
		int l = n / k; l *= k;				//l <= n, lはkの倍数となるlの最大
		int r = (n + k - 1) / k; r *= k;	//n <= r, rはkの倍数となるrの最小

		if (n - l <= ret / d) {
			res = dfs(l / k) + d * (n - l) + a[i];
			ret = min(ret, res);
		}
		if (r - n <= ret / d) {
			res = dfs(r / k) + d * (r - n) + a[i];
			ret = min(ret, res);
		}
	}
	return dp[n] = ret;
}

void solve() {
	int n;
	cin >> n >> a[0] >> a[1] >> a[2] >> d;
	dp.clear();
	cout << dfs(n) << endl;
}

