ll f(ll n){
	if (memo.find(n) != memo.end()) return memo[n];
	if (n == 0) return 0;
	if (n == 1) return d;
	ll res = LINF;
	if (n <= 1e9) chmin(res, n * d);

	if (n % 2 == 0) chmin(res, a + f(n / 2));
	else{
