	if (n % 5 == 0) chmin(res, c + f(n / 5));
	else{
		ll rest = n - n / 5 * 5;
		chmin(res, d * rest + c + f((n - rest) / 5));
		chmin(res, d * (5 - rest) + c + f((n - rest) / 5 + 1));
	}
	return memo[n] = res;
