void solve(){
    priority_queue<pl, vector<pl>, greater<pl> > pq;
    dis.clear();
    dis[n] = 0;
    pq.push(mp(0, n)); 
    while(!pq.empty()){
        pl p = pq.top(); pq.pop();
        ll d = p.fi;
