        if(id == 1)
            break;
        for(int i = 0;i < 3;i++){
            ll to = id / A[i];
            ll d1 = dis[id] + cost[i] + (id - A[i] * to) * cost[3];
            if(!dis.count(to) or (dis[to] > d1)){
                dis[to] = d1;
                pq.push(mp(dis[to], to));
            }
            to = to + 1;
            d1 = dis[id] + cost[i] + (A[i] * to - id) * cost[3];
            if(!dis.count(to) or (dis[to] > d1)){
