i64 mul(i64 x, i64 y) {
	constexpr i64 Inf = std::numeric_limits<i64>::max();
	return (y <= Inf / x ? x * y : Inf);
}

int main() {
	int t;
	std::cin >> t;

	std::vector<Pair> buf;
	buf.reserve(1000000);
	std::unordered_set<i64> visited;
	while (t--) {
		i64 n, a, b, c, d;
		std::cin >> n >> a >> b >> c >> d;

		auto calc = [d](i64 t, i64 x) {
			return ((t + d - 1) / d >= x ? x * d : t);
		};

		std::priority_queue pque(std::greater<>{}, buf);
		pque.emplace(0, n);
		while (!pque.empty()) {
			auto [cost, x] = pque.top();
			pque.pop();

			if (x == 1) {
				std::cout << cost + d << std::endl;
				break;
			}
			if (visited.count(x))
				continue;

			visited.insert(x);

			auto push = [&](i64 c, i64 nx) {
				if (!visited.count(nx))
					pque.emplace(c, nx);
			};

			if (x % 2 == 0)
				push(cost + calc(a, x / 2), x / 2);
			else {
				push(cost + d + calc(a, (x + 1) / 2), (x + 1) / 2);
				if (x > 1)
					push(cost + d + calc(a, (x - 1) / 2), (x - 1) / 2);
			}

			if (x % 3 == 0)
				push(cost + calc(b, x / 3 * 2), x / 3);
			else {
				push(cost + std::min(mul(d, x - (x+2)/3), d * (3 - x % 3) + b), (x + 2) / 3);
				if (x > 2)
					push(cost + d * (x % 3) + calc(b, x / 3 * 2), x / 3);
			}

			if (x % 5 == 0)
				push(cost + calc(c, x / 5 * 4), x / 5);
			else {
				push(cost + std::min(mul(d, x - (x+4)/5), d * (5 - x % 5) + c), (x + 4) / 5);
				if (x > 4)
					push(cost + d * (x % 5) + calc(c, x / 5 * 4), x / 5);
			}
		}

		visited.clear();
	}
}

