void min_self(ll& a,ll b){
	if(a>b) a=b;
}

ll calc(ll goal){
	if(!goal) return 0;
	if(goal==1) return d;
	if(maps.count(goal)) return maps[goal];
	ll minn=oo;
	if(d<oo/goal){
		min_self(minn,d*goal);
	}
	for(int i=0;i<3;++i){
		int mul=muls[i];
		ll cost=vector<ll>{a,b,c}[i];
		if(goal%mul==0){
			min_self(minn,cost+calc(goal/mul));
		}
		else{
			ll low=goal/mul*mul;
			min_self(minn,cost+d*(goal-low)+calc(goal/mul));
			ll high=low+mul;
			min_self(minn,cost+d*(high-goal)+calc(goal/mul+1));
		}
	}
	return maps[goal]=minn;
}

