ull Func(ull n){
    if(n==0)return 0;
    if(n==1)return D;
    if(mp.count(n)!=0)return mp[n];
    ull ret=n*D;
    if(n%2==0)ret=min(ret,A+Func(n/2));
    else ret=min({ret,D+A+Func((n-1)/2),D+A+Func((n+1)/2)});
    if(n%3==0)ret=min(ret,B+Func(n/3));
    else{
        if(n%3==1)  ret=min({ret,D+B+Func((n-1)/3),D*2+B+Func((n+2)/3)});
        else        ret=min({ret,D+B+Func((n+1)/3),D*2+B+Func((n-2)/3)});
    }
    if(n%5==0)ret=min(ret,C+Func(n/5));
    else{
        for(ll i=-min((ull)4,n);i<=4;i++){
            if((n+i)%5!=0)continue;
            if(i==0)continue;
            ret=min(ret,D*abs(i)+C+Func((n+i)/5));
        }
    }
    return mp[n]=ret;
}
