map<ll, ll> dp;
ll dfs(ll k)
{
    if (dp.find(k) != dp.end())
        return dp[k];
    if (k == 0)
    {
        dp[0] = 0;
        return 0;
    }
    if (k == 1)
    {
        dp[k] = d;
        return d;
    }
    ll res = d * k;
    if (res < 0)
        res = LINF;
    //cout << k << " " << res << "\n";
    if (k >= 2)
