unordered_map<ll,ll> H[4];
ll a,b,c,d;
ll solve(ll x,int z)
{
	if(x<=1)
		return d*x;
	if(H[z].find(x)!=H[z].end())
		return H[z][x];
	ll res=1e18;
	if(x<=(ll)1e18/d)
		res=x*d;
	// cout<<x<<" "<<z<<endl;
	if(z==1)
	{
		// category of 2
		if(x%2==0)
		{
			res=min(res,a+solve(x/2,1));
		}		
		else
		{
			res=min(res,d+a+min(solve((x+1)/2,1),solve((x-1)/2,1)));
		}
	}
	if(z==2)
	{
		res=min(res,solve(x,1));
		ll r=x%3;
		if(r<=3-r)
		{
			res=min(res,b+r*d+solve(x/3,2));
		}
		if(r>=3-r)
		{
			res=min(res,b+(3-r)*d+solve(x/3+1,2));
		}
	}
	if(z==3)
	{
		res=min(res,solve(x,2));
		ll r=x%5;
		if(r<=5-r)
		{
			res=min(res,c+r*d+solve(x/5,3));
		}
		if(r>=5-r)
		{
			res=min(res,c+(5-r)*d+solve(x/5+1,3));
		}
	}
	return H[z][x]=res;
}
