typedef long long ll;
const int MAX = 1e7 + 10;
const ll INF = 9e18;

int T;
ll N, A, B, C, D;
ll f[MAX], n = 1e7;
map<ll, ll> mp;

ll calc(ll x) {
    if (x < 0) return INF;
    return x;
}

ll dp(ll x) {
    if (x <= n) return f[x];
    if (mp.count(x)) return mp[x];
    ll res = 9e18;
    if (x % 2 == 0) res = min(res, A + dp(x / 2));
    else {
        ll t = x % 2;
        res = min(res, min(dp(x / 2) + min(A + t * D, calc((x - x / 2) * D)), dp(x / 2 + 1) + min(A + (2 - t) * D, calc((x - x / 2 - 1) * D))));
    }
    if (x % 3 == 0) res = min(res, B + dp(x / 3));
    else {
        ll t = x % 3;
        res = min(res, min(dp(x / 3) + min(B + t * D, calc((x - x / 3) * D)), dp(x / 3 + 1) + min(B + (3 - t) * D, calc((x - x / 3 - 1) * D))));
    }
    if (x % 5 == 0) res = min(res, C + dp(x / 5));
    else {
        ll t = x % 5;
        res = min(res, min(dp(x / 5) + min(C + t * D, calc((x - x / 5) * D)), dp(x / 5 + 1) + min(C + (5 - t) * D, calc((x - x / 5 - 1) * D))));
    }
    return mp[x] = res;
}

