constexpr LL inf = LL(1e18);

LL get(LL n) {
	if(n == 0)
		return 0;
	if(pre.find(n) != pre.end())
		return pre[n];
	debug(n);

	LL ans = inf;
	pre[n] = ans;
	if(n <= ans / d and n * d <= ans)
		ans = min(ans, n * d);

	auto consider = [&](int cost, int div) {
		LL m = n;
		while(m % div)
			--m;
		ans = min(ans, get(m / div) + cost + d * abs(m - n));
		m = n;
		while(m % div)
			++m;
		ans = min(ans, get(m / div) + cost + d * abs(m - n));
	};
	consider(a, 2);
	consider(b, 3);
	consider(c, 5);
	return pre[n] = ans;
}

