int T;
LL N[10],A[10],B[10],C[10],D[10];

LL ans[10];

map<LL,LL> cost;
int i=0;
LL dfs(LL num){
	//out << num << endl;
	if(num==1LL) return 0;
	if(num==2LL) return min(D[i],A[i]);
	if(cost[num]>0){
		//cout << "costret=" << num << endl;
		return cost[num];
	}

	LL ret = D[i]*(num-1LL);

	if(num%2LL==0){
		LL divided = dfs(num/2LL);
		ret = min(ret,divided+A[i]);
		ret = min(ret,divided+D[i]*num/2LL);
	}else{
		LL divided_ceil = dfs((num+1LL)/2LL);
		ret = min(ret,divided_ceil+A[i]+D[i]);
		ret = min(ret,divided_ceil+((num+1LL)/2LL+1LL)*D[i]);
		LL divided_floor = dfs((num-1LL)/2LL);
		ret = min(ret,divided_floor+A[i]+D[i]);
		ret = min(ret,divided_floor+((num-1LL)/2LL+1LL)*D[i]);
	}

	if(num%3LL==0){
		LL divided = dfs(num/3LL);
		ret = min(ret,divided+B[i]);
		ret = min(ret,divided+D[i]*num*2LL/3LL);
	}else{
		LL upper = num-num%3LL+3LL;
		LL upper_diff = upper - num;
		LL divided_ceil = dfs(upper/3LL);
		ret = min(ret,divided_ceil+B[i]+D[i]*(upper_diff));
		ret = min(ret,divided_ceil+D[i]*(upper_diff + upper*2LL/3LL));

		LL lower = num-num%3LL;
		LL lower_diff = num - lower;
		LL divided_floor = dfs(lower/3LL);
		ret = min(ret,divided_floor+B[i]+D[i]*(lower_diff));
		ret = min(ret,divided_floor+D[i]*(lower_diff + lower*2LL/3LL));
	}

	if(num>=5){
		if(num%5LL==0){
			LL divided = dfs(num/5LL);
			ret = min(ret,divided+C[i]);
			ret = min(ret,divided+D[i]*num*4LL/5LL);
		}else{
			LL upper = num-num%5LL+5LL;
			LL upper_diff = upper - num;
			LL divided_ceil = dfs(upper/5LL);
			ret = min(ret,divided_ceil+C[i]+D[i]*(upper_diff));
			ret = min(ret,divided_ceil+D[i]*(upper_diff + upper*4LL/5LL));

			LL lower = num-num%5LL;
			LL lower_diff = num - lower;
			LL divided_floor = dfs(lower/5LL);
			ret = min(ret,divided_floor+C[i]+D[i]*(lower_diff));
			ret = min(ret,divided_floor+D[i]*(lower_diff + lower*4LL/5LL));
		}
	}

	cost[num] = ret;
	//cout << "cost[" << num << "]:" << cost[num] << endl;

	return ret;
}

void solve(){
	for(i=0;i<T;i++){
		ans[i] = dfs(N[i])+D[i];
		cost.clear();
	}
}

