__int128 read() {
    __int128 x = 0, f = 1;
    char ch = getchar_unlocked();
    while (ch < '0' || ch > '9') {
        if (ch == '-') f = -1;
        ch = getchar_unlocked();
    }
    while (ch >= '0' && ch <= '9') {
        x = x * 10 + ch - '0';
        ch = getchar_unlocked();
    }
    return x * f;
}
void print(__int128 x) {
    if (x < 0) {
        putchar_unlocked('-');
        x = -x;
    }
    if (x > 9) print(x / 10);
    putchar_unlocked(x % 10 + '0');
}
bool cmp(__int128 x, __int128 y) { return x > y; }

ll readLL (void) {
	bool minus = false;
	ll result = 0;
	char ch;
	ch = getchar_unlocked();
	while (true) {
		if (ch == '-') break;
		if (ch >= '0' && ch <= '9') break;
		ch = getchar_unlocked();
	}
	if (ch == '-') minus = true; else result = ch-'0';
	while (true) {
		ch = getchar_unlocked();
		if (ch < '0' || ch > '9') break;
		result = result*10 + (ch - '0');
	}
	if (minus)
		return -result;
	else
		return result;
}

map<ll, __int128> memo;

__int128 xd(ll n, ll &a, ll &b, ll &c, ll &d)
{
	if(!n)
	return 0;
	else if(n == 1)
	return d;	
	else if(memo.find(n) != memo.end())
	return memo[n];
	__int128 fd = n;
	__int128 ans = fd * d;
	ans = min(ans, xd((n/2), a, b, c, d) + a + d*(n%2));
	if(n % 2)
	ans = min(ans, xd(((n+1)/2), a, b, c, d) + a + d*(2 - (n%2)));
	ans = min(ans, xd((n/3), a, b, c, d) + b + d*(n%3));
	if(n % 3)
	ans = min(ans, xd(((n+2)/3), a, b, c, d) + b + d*(3 - (n%3)));
	ans = min(ans, xd((n/5), a, b, c, d) + c + d*(n%5));
	if(n % 5)
	ans = min(ans, xd(((n+4)/5), a, b, c, d) + c + d*(5 - (n%5)));
	memo[n] = ans;
	return ans;
}

void solve(int T)
{
	memo.clear();
	ll n,a,b,c,d;
	n = readLL(); a = readLL(); b = readLL(); c = readLL(); d = readLL();
	__int128 res = xd(n, a, b, c, d);
	print(res);
	putchar_unlocked('\n');
	return;
}

