ll mul(ll a,ll b)
{
	if(a==0||b==0)return 0;
	if((a*b)/b!=a)return 2e18;
	return a*b;
}

ll go(ll n)
{
	if(n==0)return 1;
	if(n==1)return d;
	if(present(dp,n))return dp[n];
	ll ans=mul(n,d);
	if(n%2==0)
	{
		ans=min(ans,go(n/2)+min(a,mul(n-n/2,d)));
	}
	else
	{
		ans=min(ans,go((n+1)/2)+min(a,mul(n-(n+1)/2,d))+d);
		ans=min(ans,go((n-1)/2)+min(a,mul(n-(n-1)/2,d))+d);

	}
	if(n%3==0)
	{
		ans=min(ans,go(n/3)+min(b,mul(n-n/3,d)));

	}
	else
	{
		ll kk=n%3;
		ans=min(ans,go((n+2)/3)+min(b,mul(n-(n+2)/3,d))+(3-kk)*d);
		ans=min(ans,go((n)/3)+min(b,mul(n-(n)/3,d))+kk*d);

	}
	if(n%5==0)
	{
		ans=min(ans,go(n/5)+min(c,mul(n-n/5,d)));
	}
	else
	{
		ll kk=n%5;
		ans=min(ans,go((n+4)/5)+min(c,mul(n-(n+4)/5,d))+(5-kk)*d);
		//ol(ans);on;
		ans=min(ans,go((n)/5)+min(c,mul(n-(n)/5,d))+kk*d);
		//ol(ans);on;
	}
	dp[n]=ans;
	//o2(n,dp[n]);on;
	return ans;
}

