map < long long , long long > dp;

long long solve(long long cur){
	if(cur == 0)
		return 0;
	if(cur == 1)
		return d;
	if(dp.find(cur) != dp.end())
		return dp[cur];
	long long res = 1e18;
	if(cur < res / d)
		res = min(res , cur * d);
	for(long long tmp = max(1LL , cur - 1);tmp <= cur + 1;tmp++){
		if(tmp % 2 == 0){
			res = min(res , a + solve(tmp / 2) + abs(tmp - cur) * (long long)d);
		}
	}
	for(long long tmp = max(1LL , cur - 2);tmp <= cur + 2;tmp++){
		if(tmp % 3 == 0){
			res = min(res , b + solve(tmp / 3) + abs(tmp - cur) * (long long)d);
		}
	}
	for(long long tmp = max(1LL , cur - 4);tmp <= cur + 4;tmp++){
		if(tmp % 5 == 0){
			res = min(res , c + solve(tmp / 5) + abs(tmp - cur) * (long long)d);
		}
	}
	return dp[cur] = res;

}


