ll solve(ll n, ll cnt){
    // cout << n << " " << cnt << endl;
    if(mp[n] > 0 && mp[n] < cnt) return mp[n];
    ll cntmin = INF;
    if(n == 0) return cnt;
    if(n%5==0){
        cntmin = min(cntmin,solve(n/5,cnt+c));
    }else if(n > n/5+1) {
        ll ofs = 5-n%5;
        cntmin = min(cntmin, solve(n/5+1,cnt+c+d*ofs));
    }
    if(n%3==0){
        cntmin = min(cntmin,solve(n/3,cnt+b));
    }else if(n > n/3+1) {
        ll ofs = 3-n%3;
        cntmin = min(cntmin,solve(n/3+1,cnt+b+d*ofs));
    }
    if(n%2==0){
        cntmin = min(cntmin,solve(n/2,cnt+a));
    }else if(n > n/2+1) {
        cntmin = min(cntmin,solve(n/2+1,cnt+a+d));
    }
    cntmin = min(cntmin, solve(n-1,cnt+d));
    // cout << n << " " << cntmin << endl;
    mp[n] = cntmin;
    return cntmin;
}

