long long plus1(long long x){
  if(x>N+5){
    return 100000000000;
  }
  if(x==N){
    return d;
  }

  x += 1;
  return min(kake2(x), kake3(x), kake5(x)) + d;
}

long long kake2(long long x){
  if(x>N+5){
    return 1000000000000;
  }
  if(x==N){
    return a;
  }

  x *= 2;
  return min(plus1(x), kake3(x), kake5(x)) + a;
}

long long kake3(long long x){
  if(x>N+5){
    return 1000000000000;
  }
  if(x==N){
    return b;
  }

  x *= 3;
  return min(kake2(x), plus1(x), kake5(x)) + b;
}

long long kake5(long long x){
  if(x>N+5){
    return 10000000000000;
  }
  if(x==N){
    return c;
  }

  x *= 5;
  return min(kake2(x), kake3(x), plus1(x)) + c;
}

