map<int, int> dp;

int f(int x) {
	if(x == 0) return x;
	if(dp.find(x) != dp.end()) return dp[x];
	dp[x] = +oo;
	int DP = +oo;
	if(+oo / d >= x) {
		DP = min(DP, x * d);
	}
	if(x % 5LL == 0) {
		if(+oo / d >= 4LL * (x / 5LL)) DP = min(DP, (4LL*(x/5LL))*d + f(x/5LL));
		DP = min(DP, c + f(x / 5LL));
	}
	else {
		int y = 5LL * (x / 5LL);
		int z = y + 5LL;
		if(y == 0) DP = min(DP, (x - y) * d);
		DP = min(DP, (x - y) * d + c + f(y / 5LL));
		if(+oo / d >= 4LL*(y/5LL)) DP = min(DP, (x - y) * d + (4LL*(y/5LL))*d + f(y/5LL));
		DP = min(DP, (z - x) * d + c + f(z / 5LL));
		if(+oo / d >= 4LL*(z/5LL)) DP = min(DP, (z - x) * d + (4LL*(z/5LL))*d + f(z/5LL));
	}
	if(x % 2LL == 0) {
		if(+oo / d >= (x / 2LL)) DP = min(DP, (x / 2LL) * d + f(x / 2LL));
		DP = min(DP, a + f(x / 2LL));
	}
	else {
		int y = 2LL * (x / 2LL);
		int z = y + 2LL;
		if(y == 0) DP = min(DP, (x - y) * d);
		DP = min(DP, (x - y) * d + a + f(y / 2LL));
		if(+oo / d >= y / 2LL) DP = min(DP, (x - y) * d + (y / 2LL) * d + f(y / 2LL));
		DP = min(DP, (z - x) * d + a + f(z / 2LL));
		if(+oo / d >= z / 2LL) DP = min(DP, (z - x) * d + (z / 2LL) * d + f(z / 2LL));
	}
	if(x % 3LL == 0) {
		if(+oo/d >= 2LL*(x/3LL)) DP = min(DP, (2LL*(x/3LL))*d+f(x/3LL));
		DP = min(DP, b + f(x / 3LL));
	}
	else {
		int y = 3LL * (x / 3LL);
		int z = y + 3LL;
		if(y == 0) DP = min(DP, (x - y) * d);
		DP = min(DP, (x - y) * d + b + f(y / 3LL));
		if(+oo/d >= 2LL*(y/3LL)) DP = min(DP, (x - y) * d + (2LL*(y/3LL)) * d + f(y/3LL));
		DP = min(DP, (z - x) * d + b + f(z / 3LL));
		if(+oo/d >= 2LL*(z/3LL)) DP = min(DP, (z - x) * d + (2LL*(z/3LL)) * d + f(z/3LL));
	}
//	cout << x << " " << DP << endl;
	return dp[x] = DP;
}

