ll solve(ll x) {
	if (x == 0) {
		return 0;
	}
	if (mem.find(x) != mem.end()) {
		return mem[x];
	}
	ll ans = 6e18;
	if (x <= 10000) {
		chkmin(ans, x * d);
	}
	for (int it = 0; it < 5; it++) {
		if (x >= it) {
			ll val = x - it;
			ll add = d * it;
			if (val % 2 == 0) {
				chkmin(ans, add + solve(val / 2) + a);
			}
			if (val % 3 == 0) {
				chkmin(ans, add + solve(val / 3) + b);
			}
			if (val % 5 == 0) {
				chkmin(ans, add + solve(val / 5) + c);
			}
		}
	}
	mem[x] = ans;
	return ans;
}


