int atk(long int n,long int a, long int b, long int c, long int d){
    long int cost;

    while(n % 5 == 0){
        n /= 5;
        cost += c;
    }

    while(n % 3 == 0){
        n /= 3;
        cost += b;
    }

    while(n % 2 == 0){
        n /= 2;
        cost += a;
    }

    cost += n * d;

    return cost;
}






