ll cost[10];
VI M = {5,3,2};

ll f(ll a){
  if(mp.count(a)) return mp[a];
  if(a==1) return D;
  if(a==0) return 0;

  VI V; // candidate

  if(a<=1e9){
    V.push_back(a*D);
  }

  if(a==2) V.push_back(2*D);
  if(a==3) V.push_back(3*D);
  if(a==5) V.push_back(5*D);

  for(ll m : M){
    ll c = cost[m];
    if(a%m==0){
      V.push_back(f(a/m) + c);
    }else{
      ll r = a%m;
      // upper
      ll add = m-r;
      ll right = a + add;
      V.push_back(f(right/m) + c + add*D);
      // lower
      ll left = a - r;
      V.push_back(f(left/m) + c + r*D);
    }
  }
  return mp[a] = MIN(V);
}

