int main() {
  int T;
  io.read(T);
  while (T--) {
    ll N, A, B, C, D;
    io.read(N, A, B, C, D);
    map<ll, ll> dist;
    priority_queue<Pll, vector<Pll>, greater<Pll>> q;
    q.push(Pll(0, N));
    ll ans = LLINF;
    while (!q.empty()) {
      ll d = q.top().first, v = q.top().second;
      q.pop();
      if (dist.count(v) && dist[v] <= d) continue;
      dist[v] = d;
      if (abs(v) < (LLINF - d) / D) ans = min(ans, d + abs(v) * D);
      if (v == 0) {
        ans = min(ans, d);
        break;
      }
      if (v % 2 == 0 && (dist.count(v / 2) ? dist[v / 2] : LLINF) > d + A) {
        q.push(Pll(d + A, v / 2));
      }
      if (v % 3 == 0 && (dist.count(v / 3) ? dist[v / 3] : LLINF) > d + B) {
        q.push(Pll(d + B, v / 3));
      }
      if (v % 5 == 0 && (dist.count(v / 5) ? dist[v / 5] : LLINF) > d + C) {
        q.push(Pll(d + C, v / 5));
      }
      for (ll div : {2, 3, 5}) {
        if (v % div != 0) {
          if ((dist.count(v / div * div) ? dist[v / div * div] : LLINF) >
              d + D * (v % div)) {
            q.push(Pll(d + D * (v % div), v / div * div));
          }
          if ((dist.count((v / div + 1) * div)
                   ? dist[(v / div + 1) * div + 1]
                   : LLINF) > d + D * (div - (v % div))) {
            q.push(Pll(d + D * (div - (v % div)), (v / div + 1) * div));
          }
        }
      }
    }
    io.writeln(ans);
  }
  return 0;
}

