    else if (n % 5 == 2)
    {
        ans = min(ans, rec((n-2) / 5) + c+d+d);
    }
    else if (n % 5 == 3)
    {
        ans = min(ans, rec((n+2) / 5) + c+d+d);
    }
    else if (n % 5 == 4)
    {
        ans = min(ans, rec((n+1) / 5) + c+d);
    }

    stored[n]=ans;
    return ans;
}

