template<class T> inline bool chmin(T &a, T b)
{
    if(a > b)
    {
        a = b;
        return true;
    }
    return false;
}

void setdp(ll N, ll num, ll cost, ll one_cost, priority_queue<ll> &q, map<ll, ll> &dp)
{
    ll upper = (N+num-1)/num;
    ll lower = N/num;
    if(dp.count(upper))
    {
        chmin(dp[upper], dp[N] + llabs(N - upper*num)*one_cost + cost);
    }
    else
    {
        dp[upper] = dp[N] + llabs(N - upper*num)*one_cost + cost;
        q.push(upper);
    }
    if((cost + one_cost - 1) / one_cost > llabs(N - upper) - llabs(N - upper*num))
    {
        chmin(dp[upper], dp[N] + llabs(N - upper)*one_cost);
    }
    if(dp.count(lower))
    {
        chmin(dp[lower], dp[N] + llabs(N - lower*num)*one_cost + cost);
    }
    else
    {
        dp[lower] = dp[N] + llabs(N - lower*num)*one_cost + cost;
        q.push(lower);
    }
    if((cost + one_cost - 1) / one_cost > llabs(N - lower) - llabs(N - lower*num))
    {
        chmin(dp[lower], dp[N] + llabs(N - lower)*one_cost);
    }
    return;
}

void solve(ll N, ll A, ll B, ll C, ll D)
{
    map<ll, ll> dp; // 持っている数, 払ったコインの枚数
    dp[N] = 0;

    // BFS
    priority_queue<ll> q;
    q.push(N);
    while(!q.empty())
    {
        ll now = q.top(); q.pop();
        if(now==0) break;
        if(now==1)
        {
            if(dp.count(0)) chmin(dp[0], dp[1] + D);
            else
            {
                dp[0] = dp[1] + D;
            }
            break;
        }
        setdp(now, 2, A, D, q, dp);
        setdp(now, 3, B, D, q, dp);
        setdp(now, 5, C, D, q, dp);
    }
    cout << dp[0] << endl;
    return;
}

