ll dist(ll k) {
  if (dp[k]) return dp[k];
  if (k == 0) return dp[0] = 0;
  if (k == 1) return dp[1] = d;
  ll res = d * k;
  if (INF / d < k) res = INF;
  if (k%2 == 0) res = min(res, dist(k/2)+a);
  else res = min({res, dist(k/2)+a+d, dist(k/2+1)+a+d});
  for (int i = -1; i <= 1; ++i) {
    if ((k+i)%3 == 0) res = min(res, dist((k+i)/3)+b+d*abs(i));
  }
  for (int i = -2; i <= 2; ++i) {
    if ((k+i)%5 == 0) res = min(res, dist((k+i)/5)+c+d*abs(i));
  }
  return dp[k] = res;
}

