map <long long, long long> dp;
long long a, b, c, d;

long long dfs(long long n) {
	if (n < 0) return INF;
	if (n == 0) return 0;
	if (dp.count(n)) return dp[n];
	long long res = INF;
	for (long long nn = n - 1; nn <= n + 1; nn++) {
		if (nn % 2 == 0 && nn / 2 < n) res = min(res, dfs(nn / 2) + abs(n - nn) * d + a);
	}
	for (long long nn = n - 2; nn <= n + 2; nn++) {
		if (nn % 3 == 0 && nn / 3 < n) res = min(res, dfs(nn / 3) + abs(n - nn) * d + b);
	}
	for (long long nn = n - 4; nn <= n + 4; nn++) {
		if (nn % 5 == 0 && nn / 5 < n) res = min(res, dfs(nn / 5) + abs(n - nn) * d + c);
	}
	if (INF / n >= d) res = min(res, n * d);
	return dp[n] = res;
}

