            if (v == 1) {
                q.emplace(sum + d, 0);
                continue;
            }

            //LL maxn = n + 1'000'000'000;
            //LL maxn = n + (1LL<<60) + 1;
            LL maxn = n * 100;

            LL sr = (1LL<<60) / d;
            if (v % 2 == 0) {
                if (v /2 <= sr && a > v / 2 * d) q.emplace(sum + v / 2 * d, v / 2); 
                else q.emplace(sum + a, v / 2);
            }
            else {
                q.emplace(sum + d, v - 1);
                if (v + 1 < maxn) q.emplace(sum + d, v + 1);
            }
            if (v % 3 == 0) {
                if (v / 3 * 2 <= sr && b > v / 3 * d * 2) q.emplace(sum + v / 3 * d * 2, v / 3);
                else q.emplace(sum + b, v / 3);
            }
            else {
                q.emplace(sum + d * (v % 3), v - v % 3);
                if (v + (3 - v % 3) < maxn) q.emplace(sum + d * (3 - (v % 3)), v + (3 - v % 3));
