long long func(long long x) {
    if (memo.count(x)) {
        return memo[x];
    }
    memo[x] = min({func(x / 2) + d * (x % 2) + a, func(x / 3) + d * (x % 3) + b, func(x / 5) + d * (x % 5) + c,
