			ll c2 = min((k/2LL)*d, a);
			ll c3 = min((k/3LL)*d*2LL, b);
			ll c5 = min((k/5LL)*d*4LL, c);
			if(k%2==0){ 
				pq.push({-(v+c2), k/2LL});
			}
			else{
				ll ca = v+(k%2LL)*d + c2;
				ll cb = v+(2LL-k%2LL)*d + c2;
				pq.push({-ca, k/2LL});
				pq.push({-cb, (k+1LL)/2LL});
			}
			if(k%3==0){
				pq.push({-(v+c3), k/3LL});
			}
			else{
				ll ca = v+(k%3LL)*d + c3;
				ll cb = v+(3LL-k%3LL)*d + c3;
				pq.push({-(ca), k/3LL});
				pq.push({-(cb), (k+2LL)/3LL});
			}
			if(k%5==0){
				pq.push({-(v+c5), k/5LL});
			}
			else{
				ll ca = v+(k%5LL)*d + c5;
				ll cb = v+(5LL-k%5LL)*d + c5;
				pq.push({-ca, k/5LL});
				pq.push({-cb, (k+4LL)/5LL});
			}
		}
		cout << ans << endl;
	}
}

