	//  printf("%lld\n", x);
	if(F.find(x)!=F.end()) return F[x];
	vector <ll> mul {2,3,5}, cost{A,B,C};
	ll wyn = INF;
	for(int i=0;i<3;++i)
	{
		if(x%mul[i]==0)
		{
			wyn = min(wyn, cost[i] + f(x/mul[i]));
		}
		else
		{
			ll down = x/mul[i] * mul[i];
			wyn = min(wyn, D*(x - down) + cost[i] + f(x/mul[i]));
			ll up = down + mul[i];
			wyn = min(wyn, D*(up-x) + cost[i] + f(x/mul[i] + 1));
		}
	}
	F[x]=wyn;
	return wyn;
}

