void solve() {
	dist.clear();
	int n;
	int a;
	int b;
	int c;
	int d;
	cin >> n >> a >> b >> c >> d;
	priority_queue<pii, vector<pii>, greater<pii>> q;
	q.emplace(0, n);
	int ans = INF;
	while (q.size()) {
		int dst;
		int v;
		tie(dst, v) = q.top();
		q.pop();
		if (dist.find(v) != dist.end() && dist[v] <= dst) {
			continue;
		}
		dist[v] = dst;
		if (dst >= ans) {
			break;
		}
		ans = min(ans, dst + mul(d, v));
		q.emplace(dst + d * (v % 2) + a, v / 2);
		q.emplace(dst + d * (2 - v % 2) + a, v / 2 + 1);
		q.emplace(dst + d * (v % 3) + b, v / 3);
		q.emplace(dst + d * (3 - v % 3) + b, v / 3 + 1);
		q.emplace(dst + d * (v % 5) + c, v / 5);
		q.emplace(dst + d * (5 - v % 5) + c, v / 5 + 1);
	}
	cout << ans << "\n";
}

