int main(){
  int T; cin >> T;
  rep(t, T) {
    long long N; cin >> N;
    long long A, B, C, D; cin >> A >> B >> C >> D;
    map<long long, int> mp;
    priority_queue<pair<long long, long long>,
                   vector<pair<long long, long long>>,
                   greater<pair<long long, long long>>>
        q;

    q.emplace(0, N);
    long long ans = INF;
    while (!q.empty()) {
      long long used, now;
      if (ans <= used) break;
      tie(used, now) = q.top(); q.pop();
      if (mp[now] == 1) continue;

      if (now < INF / D) ans = min(ans, used + D * now);

      mp[now] = 1;
      if (now % 2 == 1) {
        q.emplace(used + A + D, now / 2);
        q.emplace(used + A + D, now / 2 + 1);
      } else {
        q.emplace(used + A, now / 2);
      }
      int num = min(now % 3, 3 - (now % 3));
      q.emplace(used + B + D * num, (now + 1) / 3);
      num = min(now % 5, 5 - (now % 5));
      q.emplace(used + C + D * num, (now + 2) / 5);
    }

    cout << ans << endl;
  }
}

