ll a, b, c, d;
map<ll, ll> mp;
ll f(ll n, ll co) {
  // dump(n, co);
  if (n == 0) return co;
  if (n == 1) return co + d;
  if (mp[n] > 0) return co + mp[n];
  ll ac, bc, cc, dc;
  if (n % 2 == 0) {
    ac = f(n / 2, co) + a;
  } else {
    ac = f((n - 1) / 2, co) + a + d;
  }
  if (n % 3 == 0) {
    bc = f(n / 3, co) + b;
  } else if (n % 3 == 1) {
    bc = f((n - 1) / 3, co) + b + d;
  } else {
    bc = f((n + 1) / 3, co) + b + d;
  }
  if (n % 5 == 0) {
    cc = f(n / 5, co) + c;
  } else if (n % 5 == 1) {
    cc = f((n - 1) / 5, co) + c + d;
  } else if (n % 5 == 2) {
    cc = f((n - 2) / 5, co) + c + d * 2;
  } else if (n % 5 == 3) {
    cc = f((n + 2) / 5, co) + c + d * 2;
  } else {
    cc = f((n + 1) / 5, co) + c + d;
  }
  ll ans = min(ac, bc);
  ans = min(ans, cc);
  if (n <= a * 2 && n <= b * 3 && n <= c * 5) {
    dc = n * d;
    ans = min(ans, dc);
  }
  mp[n] = ans;
  return co + ans;
}

