#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const ll LIM = 1e6;
const ll INF = 1e18;
const ll BIG = 1e9;
ll mem[LIM + 10], a, b, c, d, n;
map<ll, ll> mem2;

ll dp(ll m) {
    if(m == 0)
        return 0;
    if(m < LIM && mem[m] != -1)
        return mem[m];
    if(mem2.count(m))
        return mem2[m];
    if(m == 1)
        return mem[1] = d;
    ll ans = INF;
    if(m <= BIG)
        ans = d * m;
    for(ll x = max(m - 1, 0LL); x <= m + 1; x++) {
        if(x % 2 == 0 && x / 2 < m)
            ans = min(ans, d*abs(x - m) + a + dp(x/2));
    }
    for(ll x = max(m - 1, 0LL); x <= m + 1; x++) {
        if(x % 3 == 0 && x / 3 < m)
            ans = min(ans, d*abs(x - m) + b + dp(x/3));
    }
    for(ll x = max(m - 2, 0LL); x <= m + 2; x++) {
        if(x % 5 == 0 && x / 5 < m)
            ans = min(ans, d*abs(x - m) + c + dp(x/5));
    }
    if(m < LIM)
        return mem[m] = ans;
    return mem2[m] = ans;
}

