ll dfs(ll num){
    if(seen[num]) return cost[num];
    seen[num] = true;
    ll a = INF;

    int by[3] = {2,3,5};
    ll ABC[3] = {A,B,C};
    ll dD[6];
    ll next[6];
    REP(i,3)
    {
        next[2 * i] = floor(num / by[i]);
        next[2 * i + 1] = ceil(num / by[i]);
        dD[2 * i] = (num - by[i] * floor((double)num / by[i])) * D;
        dD[2 * i + 1] = (by[i] * ceil((double)num / by[i]) - num) * D;
    }
    REP(i,6)
    {
        cost[num] = min(cost[num], dfs(next[i]) + ABC[i/2] + dD[i]);    
    }
    //cout << "dfs(" << num << ")=" << cost[num] <<endl;
    return cost[num];
}
