using Int = unsigned long long;

using namespace std;

void solve() {
	Int N, A, B, C, D;
	cin >> N >> A >> B >> C >> D;

	Int ans = 1e18;
	deque<pair<Int, Int>> que;
	que.emplace_back(N, 0);
	map<Int, Int> mp;
	while (!que.empty()) {
		auto p = que.front(); que.pop_front();
		Int n = p.first, cost = p.second;
		if (mp.count(n) && mp[n] <= cost) { continue; }
		mp[n] = cost;
		if (n == 0) {
			ans = min(ans, cost);
			continue;
		}

		if (n % 2 == 0) {
			que.emplace_back( n / 2, cost + min(A, n / 2 * D) );
		} else {
			que.emplace_back( n - 1, cost + D );
			que.emplace_back( n + 1, cost + D );
		}

		if (n % 3 == 0) {
		   que.emplace_back( n / 3, cost + min(B, n / 3 * 2 * D) );
		} else {
			Int m = n % 3;
			que.emplace_back( n - m, cost + D * m );
			que.emplace_back( n + (3 - m), cost + D * (3 - m) );
		}

		if (n % 5 == 0) {
			que.emplace_back( n / 5, cost + min(C, n / 5 * 4 * D) );
		} else {
			Int m = n % 5;
			que.emplace_back( n - m, cost + D * m );
			que.emplace_back( n + (5 - m), cost + D * (5 - m) );
		}
	}
	cout << ans << endl;
}

int main() {
	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int T;
	cin >> T;
	while (T--) {
		solve();
	}

	return 0;
}

