ll n,a,b,c,d;
map<ll,ll> memo;

ll f(ll n){
    if(n==0){return 0;}
    if(n==1){return d;}
    if(memo.count(n)){return memo[n];}

    ll l2=n/2*2;
    ll r2=(n+1)/2*2;
    ll l3=n/3*3;
    ll r3=(n+2)/3*3;
    ll l5=n/5*5;
    ll r5=(n+4)/5*5;
    ll res=INF;
    if(n<res/d){res=n*d;}
    res=min(res,llabs(l2-n)*d+f(l2/2)+a);
    res=min(res,llabs(r2-n)*d+f(r2/2)+a);
    res=min(res,llabs(l3-n)*d+f(l3/3)+b);
    res=min(res,llabs(r3-n)*d+f(r3/3)+b);
    res=min(res,llabs(l5-n)*d+f(l5/5)+c);
    res=min(res,llabs(r5-n)*d+f(r5/5)+c);
    memo[n]=res;
    return res;

}

