int64_t n,a,b,c,d;
std::map<int64_t,int64_t> memo;

int64_t dfs(int64_t n){
  if(memo[n].count())return memo[n];
  int64_ t tmp = (1LL<<58);
  if(n%2==0)tmp = std::min(tmp,dfs(n/2)+a);
  else{
    tmp = std::min(tmp,dfs((n+1)/2)+a+d);
    tmp = std::min(tmp,dfs((n-1)/2)+a+d);
  }
  if(n%3==0)tmp = std::min(tmp,dfs(n/3)+b);
  else{
    int64_t low3 = n/3*3;
    int64_t high3 = (n/3+1)*3;
    tmp = std::min(tmp,dfs(low3)+b+d*(n-low3));
    tmp = std::min(tmp,dfs(high3)+b+d*(high3-n));
  }
  if(n%5==0)tmp = std::min(tmp,dfs(n/5)+c);
  else{
    int64_t low5 = n/5*5;
    int64_t high5 = (n/5+1)*5;
    tmp = std::min(tmp,dfs(low5)+c+d*(n-low5));
    tmp = std::min(tmp,dfs(high5)+c+d*(high5-n));
  }
  return memo[n] = tmp;
}

void solve(){
  std::cin>>n>>a>>b>>c>>d;
  memo.clear();
  dfs(n);
  memo[0] = 0;
  memo[1] = d;
  std::cout<< memp[n] <std::endl;
}

