cout << fixed << setprecision(2) << 3.14 << endl; //3.1

 int: -2,147,483,648 ～ 2,147,483,647 (2×10^9)
 ll: -9,223,372,036,854,775,808 ~ 9,223,372,036,854,775,807 (9×10^18)

*/

int ganba(ll a, ll b, ll c, ll d, ll n){
  ll count=0;
  while(n!=1){
    double aa=n/a, bb=2*n/b, cc=4*n/c,dd=1/d;

    if(n%2==0 && aa>=dd){
      n/=2;
      count+=a;
    }
    else if(n%3==0 && bb>=dd){
      n/=3;
      count+=b;
    }
    else if(n%5==0 && cc>=dd){
      n/=5;
      count+=c;
    } else {
      count+=d;
      switch (n%30)
      {
      case 1:
        n--;
        break;
      case 7:
        n--;
        break;
      case 13:
        n--;
        break;
      case 17:
        n++;
        break;
      case 19:
        n++;
        break;
      case 23:
        n++;
        break;
      case 29:
        n++;
        break;      
      default:
        n--;
        break;
      }
    }

  }
  count+=d;
  return count;
}

