#include <bits/stdc++.h>
using namespace std;

long long A, B, C, D;
map<long long, long long> dp;
long long f(long long N) {
  if (dp[N] != 0) return dp[N];
  if (N == 0) return dp[N] = 0;
  if (N == 1) return dp[N] = D;

  long long res = 1e18;
  if (N < res / D) res = min(res, N * D);

  int num[] = {2, 3, 5};
  int cost[] = {A, B, C};
  for (int i = 0; i < 3; ++i) {
    if (N % num[i] == 0) {
      res = min(res, f(N/num[i]) + cost[i]);
      continue;
    }

    int d = N % num[i];
    res = min(res, f((N-d) / num[i]) + cost[i] + D * d);
    d = num[i] - d;
    res = min(res, f((N+d) / num[i]) + cost[i] + D * d);
  }

  return dp[N] = res;
}

int main() {
  int T;
  cin >> T;

  for (int i = 0; i < T; ++i) {
    long long N;
    cin >> N >> A >> B >> C >> D;
    dp.clear();
    cout << f(N) << endl;
  }
}

