ll solve(ll n, ll a, ll b, ll c, ll d, unordered_map<ll,ll>& memo) {
  if (memo.count(n)) return memo.at(n);
  if (n == 0) return 0;
  if (n == 1) return d;
  ll ans = 3e12;
  ll div[3] = {2,3,5};
  ll cst[3] = {a,b,c};
  REP(i,3) {
    ll r = n % div[i];
    ans = min(ans, solve(n / div[i], a, b, c, d, memo) + d * r + cst[i]);
    if (r > 0) {
      r = div[i] - r;
      ans = min(ans, solve(n / div[i] + 1, a, b, c, d, memo) + d * r + cst[i]);
    }
  }
  if (n <= 1e9) {
    ans = min(ans, d * n);
  }
  memo[n] = ans;
  return ans;
}

