  cin>>t;
  REP(casenum,t) {
    ll n,a,b,c,d;
    cin>>n>>a>>b>>c>>d;
    unordered_map<ll,ll> memo;
    ll ans = solve(n, a, b, c, d, memo);
    cout<<ans<<endl;
  }
