ll dfs(ll x,map<ll,ll> &M){
    if(M.find(x)!=M.end()) return M[x];
    M[x]=INF;
    ll cost=INF;
    if(INF/D>=x) chmin(cost,D*x);
    //2で割る
    if(x<2);
    else if(x%2==0) chmin(cost,dfs(x/2,M)+A);
    else if(x%2){
        chmin(cost,min(dfs(x/2,M)+A+x%2*D,dfs((x+2)/2,M)+A+(2-x%2)*D ));
    }
    //3で割る
    if(x<3) ;
    else if(x%3==0) chmin(cost,dfs(x/3,M)+B);
    else if(x%3){
        chmin(cost,min(dfs(x/3,M)+B+x%3*D,dfs((x+3)/3,M)+B+(3-x%3)*D ));
    }
    //5で割る
    if(x<5) ;
    else if(x%5==0) chmin(cost,dfs(x/5,M)+C);
    else if(x%5){
        chmin(cost,min(dfs(x/5,M)+C+x%5*D,dfs((x+5)/5,M)+C+(5-x%5)*D ));
    }
    M[x]=cost;
    return cost;
}

