const long long INF = 1e18;
int Td;
long long n, A, B, C, D;
long long ans = INF;

struct Node{
	long long x, rs;
	Node(long long x = 0, long long rs = 0) : x(x), rs(rs) {}
	bool operator < (const Node & b) const{
		return x < b.x;
	}
};

set<Node> G;
set<Node>::iterator it;

long long dfs(long long x, long long now) {
	if(now >= ans) return INF;
	if(x == 0) {
		ans = now;
		return 0;
	}
	if(x == 1) {
		ans = min(ans, now + D);
		return D;
	}
	it = G.find(x);
	if(it != G.end()) {
		ans = min(ans, now + it->rs);
		return it->rs;
	}
	long long rs = INF, tmp = INF, y;
	if(x <= INF / D) rs = x * D;
	y = x % 5;
	tmp = dfs((x - y) / 5, now + y * D + C);
	rs = min(rs, tmp + y * D + C);
	y = 5 - x % 5;
	tmp = dfs((x + y) / 5, now + y * D + C);
	rs = min(rs, tmp + y * D + C);
	y = x % 3;
	tmp = dfs((x - y) / 3, now + y * D + B);
	rs = min(rs, tmp + y * D + B);
	y = 3 - x % 3;
	tmp = dfs((x + y) / 3, now + y * D + B);
	rs = min(rs, tmp + y * D + B);
	y = x % 2;
	tmp = dfs((x - y) / 2, now + y * D + A);
	rs = min(rs, tmp + y * D + A);
	y = 2 - x % 2;
	tmp = dfs((x + y) / 2, now + y * D + A);
	rs = min(rs, tmp + y * D + A);
	G.insert(Node(x, rs));
	//printf("%lld, %lld\n", x, rs);
	return rs;
}

