			}
			//next = max(next, n / 5);
			next = n / 5;
			sets.insert(next);

		}
		else {
			dist = 5 - n % 5;
			if (dp[(n + dist) / 5] != 0) {
				dp[(n + dist) / 5] = min(dp[(n + dist) / 5], dp[n] + C + D * dist);
			}
			else {
				dp[(n + dist) / 5] = min(dp[n] + C + D * dist, dp[n] + (n - (n + dist) / 5 + 1)*D);
			}
			//next = max(next, (n + dist) / 5);
			next = (n + dist) / 5;
			sets.insert(next);


			dist = n % 5;
			if (dp[(n - dist) / 5] != 0) {
				dp[(n - dist) / 5] = min(dp[(n - dist) / 5], dp[n] + C + D * dist);
			}
			else {
				dp[(n - dist) / 5] = min(dp[n] + C + D * dist, dp[n] + (n - (n - dist) / 5 + 1)*D);
			}
			//next = max(next, (n - dist) / 5);
			next = (n - dist) / 5;
			sets.insert(next);
		}

		sets.erase(n);


	}

	return dp[0];
	//return act(next);
	//return act(n - 1);

}



