map<ll, ll> memo;
ll a, b, c, d;

ll calc(ll n){
    if (memo.count(n)) return memo[n];
    if (n == 0) return 0;
    if (n == 1) return d;
    ll ret = 1e18;
    if (n < 1e9) chmin(ret, n * d);
    if (n % 2 == 0) chmin(ret, calc(n / 2) + a);
    else{
        chmin(ret, calc(n / 2) + a + d);
        chmin(ret, calc(n / 2 + 1) + a + d);
    }
    if (n % 3 == 0) chmin(ret, calc(n / 3) + b);
    else if (n % 3 == 1){
        chmin(ret, calc(n / 3) + b + d);
        chmin(ret, calc(n / 3 + 1) + b + 2 * d);
    }else{
        chmin(ret, calc(n / 3) + b + 2 * d);
        chmin(ret, calc(n / 3 + 1) + b + d);
    }
    if (n % 5 == 0){
        chmin(ret, calc(n / 5) + c);
    }else{
        int r = n % 5;
        chmin(ret, calc(n / 5) + c + r * d);
        chmin(ret, calc(n / 5 + 1) + c + (5 - r) * d);
    }
    return memo[n] = ret;
}

