    res = min(res, llabs(x % 2) * D + A + dp(x / 2));
    res = min(res, llabs(2 - x % 2) * D + A + dp(x / 2 + 1));

    res = min(res, llabs(x % 3) * D + B + dp(x / 3));
    res = min(res, llabs(3 - x % 3) * D + B + dp(x / 3 + 1));

    res = min(res, llabs(x % 5) * D + C + dp(x / 5));
    res = min(res, llabs(5 - x % 5) * D + C + dp(x / 5 + 1));


    return mp[x] = res;
}

