	auto it = mm.find(n);
	if (it != mm.end()) return it->se;

	ll res = longINF;
	if ((double)n * d < longINF) res = n * d;

	int pv[] = {2, 3, 5};
	ll cost[] = {a, b, c};
	for (int i = 0; i < 3; ++i) {
		for (int t = 0; t < 2; ++t) {
			ll nex = t == 0 ? n / pv[i] : (n + pv[i] - 1) / pv[i];
			if (n == nex) continue;
			ll pre = nex * pv[i];
			ll nc = abs(pre - n) * d + f(nex, a, b, c, d);
			if ((double)abs(pre - nex) * d + nc < longINF) chmin(res, abs(pre - nex) * d + nc);
			if ((double)cost[i] + nc < longINF) chmin(res, cost[i] + nc);
		}
	}

	return mm[n] = res;
}

int main() {
	int T;
	cin >> T;
	while (T--) {
		mm.clear();
		ll N, A, B, C, D;
		cin >> N >> A >> B >> C >> D;
		cout << f(N, A, B, C, D) << endl;

	}
	return 0;
}

