using namespace std;

typedef long long ll;

template<class T>
inline bool chmax(T &a, T b) {
    if(a < b) {
        a = b;
        return true;
    }
    return false;
}

template<class T>
inline bool chmin(T &a, T b) {
    if(a > b) {
        a = b;
        return true;
    }
    return false;
}

ll solve(const ll n, const ll A, const ll B, const ll C, const ll D, map<ll, ll> &memo) {
    if (memo.find(n) != memo.end()) {
        return memo[n];
    }

    // printf("n: %lld\n", n);

    ll cand = LONG_LONG_MAX / 2;

    const vector<ll> costs = {A, B, C};
    const vector<ll> muls = {2LL, 3LL, 5LL};
    for (int i = 0; i < 3; i++) {
        const ll cost = costs[i];
        const ll mul = muls[i];
        const ll above = ((n - 1 + mul) / mul) * mul;
        chmin(cand, (above - n) * D + cost + solve(above / mul, A, B, C, D, memo));
        const ll below = (n / mul) * mul;
        chmin(cand, (n - below) * D + cost + solve(below / mul, A, B, C, D, memo));
    }

    // it might be better to decrease one by one if n <= 2 * 1e9
    if (n <= 2LL * 1000LL * 1000LL * 1000LL) {
        chmin(cand, D * n);
    }

    memo[n] = cand;
    // printf("n: %lld, ans: %lld\n", n, cand);
    return cand;
}

int main(void) {
    int T;
    cin >> T;
    for (int i = 0; i < T; i++) {
        ll N, A, B, C, D;
        cin >> N >> A >> B >> C >> D;
        map<ll, ll> memo;
        memo[0] = 0LL;
        memo[1] = D;
        cout << solve(N, A, B, C, D, memo) << endl;
    }
    return 0;
}

