typedef long long LL;

LL A, B, C, D;
map<LL,LL> dp;

LL solve(LL N) {
    if(N == 0) return 0;
    if(N == 1) return D;

    if(dp.find(N) != dp.end()) return dp[N];
    LL ans = 1e18;
    double lg = log10(N) + log10(D);
    if(lg <= 16) ans = N*D;

    LL x = N%2;
    ans = min(ans, solve(N/2)+x*D+A);
    if(x > 0) ans = min(ans, solve((N+1)/2)+(2-x)*D+A);

    x = N%3;
    ans = min(ans, solve(N/3)+x*D+B);
    if(x > 0) ans = min(ans, solve((N+2)/3)+(3-x)*D+B);

    x = N%5;
    ans = min(ans, solve(N/5)+x*D+C);
    if(x > 0) ans = min(ans, solve((N+4)/5)+(5-x)*D+C);

    return dp[N] = ans;
}

