  for (int i = 0; i < T; i++) {
    int N, Nn, A, B, C, D; //入力
    int min=0, goal;
    int x; //コインの枚数
    int y; //目標に近づける数

    // N: 目標の数
    // A: 2倍するときのコインの数
    // B: 3倍するときのコインの数
    // C: 5倍するときのコインの数
    // D: +1 or -1 するときのコインの数
    cin >> N >> A >> B >> C >> D;

    int cnst = 9;
    for (int j=0; j < cnst; j++) {
    //N-jからN+jまで検討
      Nn = N - (cnst / 2 + 1);
      x = D;
      y = 1;
      int tmp = Nn + j;

      while (tmp % 2 == 0) {
        tmp = tmp / 2;
        if (A < y * D) {
          x = x + A;
          y = y * 2;
        }
        else {
          x = x + y * D;
          y = y * 2;
        }
      }
      while (tmp % 3 == 0) {
        tmp = tmp / 3;
        if (B < y * 2 * D) {
          x = x + B;
          y = y * 3;
        }
        else {
          x = x + y * 2 * D;
          y = y * 3;
        }
      }
      while (tmp % 5 == 0) {
        tmp = tmp / 5;
        if (C < y * 4 * D) {
          x = x + C;
          y = y * 5;
        }
        else {
          x = x + y * 4 * D;
          y = y * 5;
        }
      }

      x = x + abs((cnst / 2 + 1) - j) * D;
      y = y + ((cnst / 2 + 1) - j);
      if (y == N) {
        if (min == 0) {
          min = x;
          goal = y;
        }
        else if (min > x) {
          min = x;
          goal = y;
        }
      }
    }
    // 出力
//    cout << "最終的な最小枚数は" << endl;
    cout << min << endl;
