ll n, a, b, c, d;
map<ll, ll> memo;
ll solve(ll k)
{
    if (memo.count(k) > 0)
    {
        return memo[k];
    }

    if (k < 0)
    {
        cout << k << endl;
        return 0;
    }
    if (k == 0)
    {
        memo[k] = 0;
        return 0;
    }
    if (k == 1)
    {
        memo[k] = d;
        return d;
    }
    if (k == 2)
    {
        memo[k] = min(2 * d, d + a);
        return memo[k];
    }

    ll ret = solve(k / 5) + c + k % 5 * d;
    if (k % 5 != 0)
        ret = min(ret, solve(k / 5 + 1) + c + (5 - k % 5) * d);

    ret = min(ret, solve(k / 3) + b + k % 3 * d);
    if (k % 3 != 0)
        ret = min(ret, solve(k / 3 + 1) + b + (3 - k % 3) * d);
    ret = min(ret, solve(k / 2) + a + k % 2 * d);
    memo[k] = ret;
    return ret;
}

