				if (!visited.count(nx))
					pque.emplace(c, nx);
			};

			for (auto [t, u] : { Pair(a, 2), Pair(b, 3), Pair(c, 5) }) {
				if (x % u == 0) {
					push(cost + std::min(t, mul(d, x - x / u)), x / u);
					continue;
				}

				push(cost + std::min(t + d * (u - x % u), mul(d, x - (x + u - 1) / u)), (x + u - 1) / u);
				if (x >= u)
					push(cost + std::min(t + d * (x % u), mul(d, x - x / u)), x / u);
			}
		}

		visited.clear();
	}
}

