map<long,long> memo;
int A,B,C,D;
long N;

long _min( long a, long b ) {
	return a<b ? a : b;
}

long solve(long N) {
		if(memo.find(N)!=memo.end())
			return memo[N];

		long min = 0x3f3f3f3f3f3f3f3f;
		if(N < 0x3f3f3f3f3f3f3f3f/D)
			min = N*D;

		for(int i=-1; i<=1; i++) {
			if((N+i)%2==0)
				min = _min(min, solve((N+i)/2)+abs(i)*D+A);
		}
		for(int i=-1; i<=1; i++) {
			if((N+i)%3==0)
				min = _min(min, solve((N+i)/3)+abs(i)*D+B);
		}
		for(int i=-2; i<=2; i++) {
			if((N+i)%5==0)
				min = _min(min, solve((N+i)/5)+abs(i)*D+C);
		}

		memo[N] = min;
		return min;
	}

