int dfs(int n) {
  if (n == 0) {
    return 0;
  }
  if (n == 1) {
    return D[t];
  }
  if (m.find(n) != m.end()) {
    return m[n];
  }
  int ret = INF_LL;
  chmin(ret, (dfs(n / 5) + (n % 5) * D[t] + C[t]));
  chmin(ret, (dfs(n / 3) + (n % 3) * D[t] + B[t]));
  chmin(ret, (dfs(n / 2) + (n % 2) * D[t] + A[t]));
  chmin(ret, (dfs((n + 4) / 5) + (5 - n % 5) * D[t] + C[t]));
  chmin(ret, (dfs((n + 2) / 3) + (3 - n % 3) * D[t] + B[t]));
  chmin(ret, (dfs((n + 1) / 2) + (2 - n % 2) * D[t] + A[t]));
  if(1.0*n*D[t] < INF_LL) chmin(ret, n*D[t]);
  m[n] = ret;
