ll dfs(ll N){
    if(mem.find(N) != mem.end()){
        return mem[N];
    }
    if(N==0){
        return INF;
    }
    if(N==1){
        mem[1] = D;
        return D;
    }
    //ベースライン
    ll retVal;
    if(N <=INF/D){
        retVal = N*D;
    }else{
        retVal = INF;
    }

    ll least2 = ((N-1)/2);
    retVal = min(retVal,(N-least2*2)*D + A + dfs(least2));
    least2++;
    retVal = min(retVal,(least2*2-N)*D +A +dfs(least2));

    ll least3 = ((N-1)/3);
    retVal = min(retVal,(N-least3*3)*D + B +dfs(least3));
