      ll cost = operation.S;
      mini(res, dfs(x / num) + cost + d * (x % num));
      if (x % num != 0) {
        mini(res, dfs(1 + x / num) + cost + d * (num - x % num));
      }
    }
    return mp[x] = res;
  }

