ll dfs(ll x){
	if(mp.find(x) != mp.end()){return mp[x];}
	if(x == 0){return 0;}
	if(x == 1){return d;}

	ll res = INF;

	if(x <= 1e9){
		if(x % 5 == 0){
			res = min(res, dfs(x / 5) + min(c, 4 * d * (x / 5)));
		}else if(x % 5 <= 2){
			ll r = x % 5;
			res = min(res, dfs((x - r) / 5) + d * r + min(c, 4 * d * ((x - r) / 5)));
		}else{
			ll r = 5 - x % 5;
			res = min(res, dfs((x + r) / 5) + d * r + min(c, 4 * d * ((x + r) / 5)));
		}

		if(x % 3 == 0){
			res = min(res, dfs(x / 3) + min(b, d * 2 * (x / 3)));	
		}else if(x % 3 == 1){
			res = min(res, dfs((x - 1) / 3) + d + min(b, 2 * d * ((x - 1) / 3)));
		}else{
			res = min(res, dfs((x + 1) / 3) + d + min(b, 2 * d * ((x + 1) / 3)));
		}

		if(x % 2){
			res = min(res, dfs((x + 1) / 2) + d + min(a, d * (x + 1) / 2));
			res = min(res, dfs((x - 1) / 2) + d + min(a, d * (x - 1) / 2));
		}else{
			res = min(res, dfs(x / 2) + min(a, d * x / 2));
		}
	}else{
		if(x % 5 == 0){
			res = min(res, dfs(x / 5) + c);
		}else if(x % 5 <= 2){
			ll r = x % 5;
			res = min(res, dfs((x - r) / 5) + d * r + c);
		}else{
			ll r = 5 - x % 5;
			res = min(res, dfs((x + r) / 5) + d * r + c);
		}

		if(x % 3 == 0){
			res = min(res, dfs(x / 3) + b);	
		}else if(x % 3 == 1){
			res = min(res, dfs((x - 1) / 3) + d + b);
		}else{
			res = min(res, dfs((x + 1) / 3) + d + b);
		}

		if(x % 2){
			res = min(res, dfs((x + 1) / 2) + d + a);
			res = min(res, dfs((x - 1) / 2) + d + a);
		}else{
			res = min(res, dfs(x / 2) + a);
		}
	}
	return mp[x] = res;
}

