template<ll Modulus>
struct ModInt {
    ll a;

    constexpr ModInt(const ll x = 0) noexcept: a((x % mod + mod) % mod) {}

    constexpr ll &value() noexcept { return a; }

    constexpr const ll &value() const noexcept { return a; }

    constexpr ModInt operator+(const ModInt x) const noexcept {
      return ModInt(*this) += x;
    }

    constexpr ModInt operator-(const ModInt x) const noexcept {
      return ModInt(*this) -= x;
    }

    constexpr ModInt operator*(const ModInt x) const noexcept {
      return ModInt(*this) *= x;
    }

    constexpr ModInt operator/(const ModInt x) const noexcept {
      return ModInt(*this) /= x;
    }

    constexpr ModInt &operator+=(const ModInt x) noexcept {
      a += x.a;
      if (a >= Modulus) {
        a -= Modulus;
      }
      return *this;
    }

    constexpr ModInt &operator-=(const ModInt x) noexcept {
      if (a < x.a) {
        a += Modulus;
      }
      a -= x.a;
      return *this;
    }

    constexpr ModInt &operator*=(const ModInt x) noexcept {
      a = a * x.a % Modulus;
      return *this;
    }

    constexpr ModInt &operator/=(ModInt x) noexcept {
      ll exp = Modulus - 2;
      while (exp) {
        if (exp % 2) {
          *this *= x;
        }
        x *= x;
        exp /= 2;
      }
      return *this;
    }

    constexpr ModInt operator-() noexcept {
      return ModInt(-a);
    }

    friend ostream &operator<<(ostream &os, const ModInt &m) {
      os << m.a;
      return os;
    }
};

using mint = ModInt<mod>;

map<ll, ll> memo;
ll a, b, c, d;
ll solve(ll n) {
  if(n == 0) return 0;
  if(n == 1) return d;
  if(memo.count(n)) return memo[n];
  ll l2 = n/2*2;
  ll r2 = (n+1)/2*2;
  ll l3 = n/3*3;
  ll r3 = (n+2)/3*3;
  ll l5 = n/5*5;
  ll r5 = (n+4)/5*5;
  ll ans = inf;
  if(ans/d > n) ans = n * d;
  ans = min(ans, llabs(l2-n) * d + a + solve(l2/2));
  ans = min(ans, llabs(r2-n) * d + a + solve(r2/2));
  ans = min(ans, llabs(l3-n) * d + b + solve(l3/3));
  ans = min(ans, llabs(r3-n) * d + b + solve(r3/3));
  ans = min(ans, llabs(l5-n) * d + c + solve(l5/5));
  ans = min(ans, llabs(r5-n) * d + c + solve(r5/5));
  return memo[n] = ans;
}

