typedef long long ll;
typedef pair<ll, ll> pll;

const ll INF = ll(9E18);

ll N, A, B, C, D;

void solve() {
	scanf("%lld%lld%lld%lld%lld", &N, &A, &B, &C, &D);
	set<ll>st;
	priority_queue<pll, vector<pll>, greater<pll> >que;
	que.push(make_pair(0, N)); ll ans = INF;
	while( !que.empty() ) {
		pll t = que.top(); que.pop();
		if( t.first > ans ) continue;
		if( t.second <= (ans - t.first) / D ) ans = t.second*D + t.first;
		if( st.count(t.second) ) continue;
		st.insert(t.second);

		ll d1, d2, r1, r2;

		r1 = t.second % 2, r2 = (2 - t.second % 2) % 2, d1 = r1*D + A, d2 = r2*D + A;
		if( d2 + D > d1 ) que.push(make_pair(t.first + d1, (t.second - r1) / 2));
		if( d1 + D > d2 ) que.push(make_pair(t.first + d2, (t.second + r2) / 2));

		r1 = t.second % 3, r2 = (3 - t.second % 3) % 3, d1 = r1*D + B, d2 = r2*D + B;
		if( d2 + D > d1 ) que.push(make_pair(t.first + d1, (t.second - r1) / 3));
		if( d1 + D > d2 ) que.push(make_pair(t.first + d2, (t.second + r2) / 3));

		r1 = t.second % 5, r2 = (5 - t.second % 5) % 5, d1 = r1*D + C, d2 = r2*D + C;
		if( d2 + D > d1 ) que.push(make_pair(t.first + d1, (t.second - r1) / 5));
		if( d1 + D > d2 ) que.push(make_pair(t.first + d2, (t.second + r2) / 5));
	}
	printf("%lld\n", ans);
}

int main() {
	int T; scanf("%d", &T);
	while( T-- ) solve();
}

