s64 dfs(s64 n, s64 cost)
{
    // if (n == 0) return cost;
    if (now <= cost) return 1e18;
    if (m[n] && m[n] <= cost) return 1e18;
    m[n] = cost;

    // cout << "n, cost, cnt = " << n << ", " << cost << "\n";
    s64 ret = 1e18;
    vs64 temp(3, 1e18);
    // vector< bool > done(6, false);
    for (s64 i = 0; i <= 5; ++i)
    {
        s64 nextp = n + i;
        s64 nextm = n - i;
        s64 dc = i * D;
        s64 div[3] = {2, 3, 5};
        s64 c[3] = {A, B, C};
        rep (j, 3)
        {
            if (nextp == 0)
            {
                ret = min(ret, cost + dc);
                break;
            }
            if (nextp % div[j] == 0 /*&& !done[2 * j]*/)
            {
                if ((nextp - nextp / div[j]) * D < 0 || (nextp - nextp / div[j]) * D > c[j])
                {
                    temp[j] = min(temp[j], dfs(nextp / div[j], cost + c[j] + dc));
                }
                else
                {
                    temp[j] = min(temp[j], dfs(nextp / div[j], cost + dc + (nextp - nextp / div[j]) * D));
                }
                // done[2 * j] = true;
            }
        }
        rep (j, 3)
        {
            if (nextm < 0) break;
            if (nextm == 0)
            {
                ret = min(ret, cost + dc);
                break;
            }
            if (nextm % div[j] == 0 /*&& !done[2 * j + 1]*/)
            {
                if ((abs(nextm) - abs(nextm) / div[j]) * D < 0 || (abs(nextm) - abs(nextm) / div[j]) * D > c[j])
                {
                    temp[j] = min(temp[j], dfs(nextm / div[j], cost + c[j] + dc));
                }
                else
                {
                    temp[j] = min(temp[j], dfs(nextm / div[j], cost + (abs(nextm) - abs(nextm) / div[j]) * D + dc));
                }
                // done[2 * j + 1] = true;
            }
        }
    }

    rep (i, 3) ret = min(ret, temp[i]);
    // cout << "n, ret: " << n << ", " << ret << "\n";
    now = min(now, ret);
    m[n] = min(m[n], ret);
    return ret;
}

