      for (int j = 0; j < N; ++j) {
        for (int k = 0; k < N; ++k) {
          if (i + 1 < N) pr[i + 1][j][k] = mul(pr[i][j][k], 2);
          if (j + 1 < N) pr[i][j + 1][k] = mul(pr[i][j][k], 3);
          if (k + 1 < N) pr[i][j][k + 1] = mul(pr[i][j][k], 5);
          dp[i][j][k][0] = dp[i][j][k][1] = Inf;
        }
      }
    }
    auto gettk = [&] (ll x, ll y, int t) {
      if (y == Inf) return Inf;
      ll tk = x / y;

      ll f = x % y;
      ll s = (y - f) % y;
      if ((f < s) ^ t) ++tk;
      return tk;
    };
    auto getx = [&] (ll x, ll y, int t) {
      if (x == Inf || y == Inf) return Inf;
      ll tk = x / y;

      ll f = x % y;
      ll s = (y - f) % y;
      if ((f < s) ^ t) ++tk;

      return abs(x - tk * y);
    };
    dp[0][0][0][0] = dp[0][0][0][1] = 0;
    for (int i = 0; i < N; ++i) {
      for (int j = 0; j < N; ++j) {
