              if (i + 1 < N) {
                dp[i][j + 1][k][nt] = min(dp[i][j + 1][k][nt], sum(dp[i][j][k][t], gettk(getx(n, pr[i][j + 1][k], nt), pr[i][j][k], t)));
              }
              if (i + 1 < N) {
                dp[i][j][k + 1][nt] = min(dp[i][j][k + 1][nt], sum(dp[i][j][k][t], gettk(getx(n, pr[i][j][k + 1], nt), pr[i][j][k], t)));
              }
            }
            ll tk = gettk(n, pr[i][j][k], t);
            ll need = sum(dp[i][j][k][t], tk);
            ll all = mul(need, d);
            add(all, mul(i, a));
            add(all, mul(j, b));
            add(all, mul(k, c));
            ans = min(ans, all);
          }
        }
      }
    }
    cout << ans << '\n'; 
  }
}

