ll plus_div(ll n, bool is_plus, ll divnum, ll unit_cost) { // nをdivで割れるまでプラスして割る
    ll start = n;
    ll cost = 0;
    while (n%divnum){
        n += is_plus ? 1 : -1;
        cost += D;
    }
    if (n != 0) cost += unit_cost;
    ll goal = n/divnum;
    ll dist = abs(start - goal);
    double per_cost = cost / dist;
    if (per_cost > D) { // 割るだけ無駄な時
        return solve(n/divnum) + D * dist;
    }
    return solve(n/divnum) + cost;
}
ll solve(ll n) {
    if (n == 0) return 0;
    if (memo[n] > 0) return memo[n];
    ll res = 5* 1e18;
    res = min(res, plus_div(n, true, 2, A));
    res = min(res, plus_div(n, false, 2, A));
    res = min(res, plus_div(n, true, 3, B));
    res = min(res, plus_div(n, false, 3, B));
    res = min(res, plus_div(n, true, 5, C));
    res = min(res, plus_div(n, false, 5, C));
    return memo[n] = res;
}
