{
	ll n, a, b, c, d;
	cin >> n >> a >> b >> c >> d;

	map<ll, bool> visit;

	priority_queue<pll> que;
	que.push(pll(0, n));

	ll ans = 0;

	for (int i = 0;; i++)
	{
		if (que.empty())
		{
			break;
		}

		pll top = que.top();
		que.pop();

		ll cost = top.first;
		ll num = top.second;

		if (visit[num])
		{
			continue;
		}
		visit[num] = true;

		if (num <= 0)
		{
			continue;
		}

		//cout << cost << " " << num << endl;

		if (num == 1)
		{
			ans = -cost + d;
			break;
		}

		que.push(pll(cost - d * num, 0));

		ll mod2 = num % 2;
		ll mod3 = num % 3;
		ll mod5 = num % 5;

		if (mod2 != 0)
		{
			que.push(pll(cost - d * mod2 - a, num / 2));
			que.push(pll(cost - d * (2 - mod2) - a, num / 2 + 1));
		}
		else
		{
			que.push(pll(cost - a, num / 2));
		}

		if (mod3 != 0)
		{
			que.push(pll(cost - d * mod3 - b, num / 3));
			que.push(pll(cost - d * (3 - mod3) - b, num / 3 + 1));
		}
		else
		{
			que.push(pll(cost - b, num / 3));
		}

