struct Edge {
	ll np, cost;

	bool operator<(const Edge & o)const{
		if(cost != o.cost){
			return cost < o.cost;
		}
		return np < o.np;
	}
};

ll N, D;
map<ll,ll> costs;
ll brute(){
	set<Edge> q;
	set<ll> vis;
	q.insert(Edge({N,0}));	
	while(q.size()){
		auto e = q.begin();
		if(e->np == 0) {
			return e->cost;
		}

		if(vis.find(e->np) != vis.end()) {
			q.erase(e); 
			continue;	
		}

		vis.insert(e->np);		
		if(e->np*D + e->cost > 0){
			q.insert(Edge({
				0,
				e->cost + e->np*D
			}));
		}

		for(auto c : costs){			
			ll r = e->np % c.first;
			if(r == 0){
				q.insert(Edge({
					e->np / c.first,
					e->cost + c.second
				}));
				continue ;
			}

			q.insert(Edge({
				(e->np - r) / c.first,
				e->cost + c.second + r*D
			}));

			ll m = e->np - r + c.first;
			q.insert(Edge({
				m / c.first,
				e->cost + c.second + (m  - e->np)*D
			}));		
		}
		q.erase(e); 
	}
	return -1;
}

