long long rec(vector<long long> &memo, long long n, int a, int b, int c, int d, long long x) {
    if (n == 0) return 0;
    if (memo[n] != -1) return memo[n];
    long long res = n;
    if (n < 0) {
        res = min(res, rec(memo, n - (- 1), a, b, c, d, --x));
    } else {
        for (int i = 0; i < 4; i++) {
            if (i == 0) {
                res = min(res, rec(memo, n - (x * 5), a, b, c, d, x * 5));
            } else if (i == 1) {
                res = min(res, rec(memo, n - (x * 3), a, b, c, d, x * 3));
            } else if (i == 2) {
                res = min(res, rec(memo, n - (x * 2), a, b, c, d, x * 2));
            } else if (i == 3) {
                res = min(res, rec(memo, n - 1, a, b, c, d, ++x));
            }
        }
    }
    return memo[n] = res;
}

