class InputReader {
public:
    InputReader() {
        input_file = stdin;
        cursor = 0;
        fread(buffer, SIZE, 1, input_file);
    }
    InputReader(const char *file_name) {
        input_file = fopen(file_name, "r");
        cursor = 0;
        fread(buffer, SIZE, 1, input_file);
    }
    inline InputReader &operator >>(int &n) {
        while((buffer[cursor] < '0' || buffer[cursor] > '9') && buffer[cursor] != '-') {
            advance();
        }
        int sign = 1;
        if (buffer[cursor] == '-') {
            sign = -1;
            advance();
        }
        n = 0;
        while('0' <= buffer[cursor] && buffer[cursor] <= '9') {
            n = n * 10 + buffer[cursor] - '0';
            advance();
        }
        n *= sign;
        return *this;
    }
private:
    FILE *input_file;
    static const int SIZE = 1 << 17;
    int cursor;
    char buffer[SIZE];
    inline void advance() {
        ++ cursor;
        if(cursor == SIZE) {
            cursor = 0;
            fread(buffer, SIZE, 1, input_file);
        }
    }
};

const long long INF = 1000000000000000000LL;

map<long long, long long> dp;

long long p[3] = {2, 3, 5};
long long cost[3], d;

long long compute(long long n) {
    if (dp.count(n)) {
        return dp[n];
    }
    if (n == 0) {
        dp[n] = 0;
    } else if (n == 1) {
        dp[n] = d;
    } else {
        long long best = INF;
        if (n <= 1000000000)
            best = d * n;
        for (int i = 0; i < 3; i++) {
            long long r1 = n % p[i];
            long long r2 = (p[i] - r1) % p[i];
            best = min(best, min(d * r1 + cost[i] + compute((n - r1) / p[i]), d * r2 + cost[i] + compute((n + r2) / p[i])));
        }
        dp[n] = best;
    }
    return dp[n];
}

