  int T;
  cin >> T;
  vector<int64_t> answer(T);
  rep(i, T) {
    int64_t N;
    cin >> N >> A >> B >> C >> D;
    memo.clear();
    answer[i] = solve(N);
  }
  rep(i, T) { cout << answer[i] << endl; }
  return 0;
}

