using namespace std;

using cat = long long;

cat A, B, C, D, ans;
constexpr int MX = 5000000;
constexpr cat rep = 1000000;
int cur_rep = 0;
vector<cat> ans_sm(MX+1);

void prec(cat N) {
	ans_sm[N] = D*N;
	if(N <= 1) return;
	cat d3 = N%3, d5 = N%5, n3 = N/3, n5 = N/5;
	if(d3 == 2) d3 = 1, n3++;
	if(d5 == 3) d5 = 2, n5++;
	if(d5 == 4) d5 = 1, n5++;
	ans_sm[N] = min(ans_sm[N], d5*D+C+ans_sm[n5]);
	ans_sm[N] = min(ans_sm[N], d3*D+B+ans_sm[n3]);
	cat d2 = N%2, n2 = N/2;
	ans_sm[N] = min(ans_sm[N], d2*D+A+ans_sm[n2]);
	if(d2) ans_sm[N] = min(ans_sm[N], d2*D+A+ans_sm[n2+1]);
}

void bt(cat N, cat cur) {
	if(N <= MX) {
		ans = min(ans, cur + ans_sm[N]);
		return;
	}
	if(N <= ans/D) ans = min(ans, cur+D*N);
	if(cur >= ans) return;
	if(cur_rep == rep) return;
	cur_rep++;
	cat d3 = N%3, d5 = N%5, n3 = N/3, n5 = N/5;
	if(d3 == 2) d3 = 1, n3++;
	if(d5 == 3) d5 = 2, n5++;
	if(d5 == 4) d5 = 1, n5++;
	bt(n5, cur+d5*D+C);
	bt(n3, cur+d3*D+B);
	cat d2 = N%2, n2 = N/2;
	bt(n2, cur+d2*D+A);
	if(d2) bt(n2+1, cur+d2*D+A);
}

int main() {
	cin.sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);
	int T;
	cin >> T;
	while(T--) {
		cat N;
		cin >> N >> A >> B >> C >> D;
		for(int i = 0; i <= MX; i++) prec(i);
		cur_rep = 0;
		ans = 1000*(A+D);
		bt(N, 0);
		cout << ans << endl;
	}
}

