    if (dp[x] != 0)
        return dp[x];
    ll res = 1e18;
    ll u5 = (x + 4) / 5;
    ll d5 = x / 5;
    ll u3 = (x + 2) / 3;
    ll d3 = x / 3;
    ll u2 = (x + 1) / 2;
