  }
  else if( N % 10 == 0) {
    chinko(res, chinko(chinko( kotae( N + 1,A,B,C,D) + D,kotae( N - 1,A,B,C,D) + D),chinko(kotae(N/2,A,B,C,D)+A,kotae(N/5,A,B,C,D)+C)));
  }
  else if( N % 15 == 0){
    chinko(res, chinko(chinko( kotae( N + 1,A,B,C,D) + D,kotae( N - 1,A,B,C,D) + D),chinko(kotae(N/3,A,B,C,D)+B,kotae(N/5,A,B,C,D)+C)));
  }
  else if ( N % 2 == 0) {
    chinko(res, chinko(chinko( kotae( N + 1,A,B,C,D) + D,kotae( N - 1,A,B,C,D) + D),kotae(N/2,A,B,C,D)+A));
  }
  else if ( N % 3 == 0) {
    chinko(res, chinko(chinko( kotae( N + 1,A,B,C,D) + D,kotae( N - 1,A,B,C,D) + D),kotae(N/3,A,B,C,D)+B));
  }
  else if ( N % 5 == 0) {
