void solve()
{
    long long n, a, b, c, d;
    cin >> n >> a >> b >> c >> d;

    long long answer = 1000000000000000000LL;

    typedef pair<long long, long long> state;
    priority_queue<state, vector<state>, greater<state>> pq;
    map<long long, long long> visited;

    pq.push({0, n});
    visited[n] = 0;

    auto check = [&](long long num, long long cost) {
        if (cost > answer)
        {
            return;
        }

        auto it = visited.lower_bound(num);

        if (it == visited.end() || it->first != num || cost < it->second)
        {
            visited[num] = cost;
            pq.push({cost, num});
        }
    };

    while (!pq.empty())
    {
        long long cost, num;
        tie(cost, num) = pq.top();
        pq.pop();

        if (num <= (answer - cost) / d)
        {
            answer = min(answer, d * num + cost);
        }

        auto r2 = num % 2, r3 = num % 3, r5 = num % 5;

        if (r2 || r3 || r5)
        {
            check(num - 1, cost + d);
            check(num + 1, cost + d);
        }

        if (r2 == 0)
        {
            check(num / 2, cost + a);
        }

        if (r3 == 0)
        {
            check(num / 3, cost + b);
        }

        if (r5 == 0)
        {
            check(num / 5, cost + c);
        }
    }

    cout << answer << endl;
}

