ll n, a, b, c, d;
unordered_map<ll, ll> pairs;
ll ans;
unordered_set<ll> done;

void dfs(unordered_map<ll, ll>& dp, ll cur = n) {
    // cout << cur << endl;
    if (cur == 0) {
        ans = min(ans, dp[cur]);
        return;
    }
    if (cur == 1) {
        ans = min(ans, dp[cur] + d);
        return;
    }
    for (auto p : pairs) {
        ll div = p.first;
        ll cost = p.second;
        ll red = cur % div;
        ll to = (cur + div - red) / div;
        ll totalcost = dp[cur] + d * (div - red) + cost;
        if (!done.count(to)) {
            dp[to] = totalcost;
            done.insert(to);
            dfs(dp, to);
        } else if (dp[to] > totalcost) {
            dp[to] = totalcost;
            dfs(dp, to);
        }

        to = (cur - red) / div;
        totalcost = dp[cur] + d * red + cost;
        if (!done.count(to)) {
            dp[to] = totalcost;
            done.insert(to);
            dfs(dp, to);
        } else if (dp[to] > totalcost) {
            dp[to] = totalcost;
            dfs(dp, to);
        }
    }
}

