long long asd(long long N,long long A,long long B,long long C,long long D) {
  long long n2,n3,n5,r;
  long long ans = 1000000007ll * 1000000007ll;
  vector<vector<vector<vector<long long>>>> dp(100,vector<vector<vector<long long>>> (100,vector<vector<long long>>(100,vector<long long>(2,1000000007ll * 1000000007ll))));
  n2 = 1;
  dp[0][0][0][0] = 0;
  dp[0][0][0][1] = D;
  for (int i=0; i<100; i++) {
    if (n2 > N*2) break;
    for (int j=0; j<100; j++) {
      if (n2 * n3 > N*2) break;
      for (int k=0; k<100; k++) {
        if (n2 * n3 * n5 > N*2) break;
        if (i != 0) {
          r = (N/(n2/2*n3*n5)) % 2;
          dp[i][j][k][0] = min(dp[i-1][j][k][0] + A + D*r,dp[i][j][k][0]);
          dp[i][j][k][1] = min(dp[i-1][j][k][1] + A + (1ll-r)*D,dp[i][j][k][1]);
        }
        if (j != 0) {
          r = (N/(n2 * n3 / 3 * n5)) % 3;
          dp[i][j][k][0] = min(dp[i][j-1][k][0] + B + r*D,dp[i][j][k][0]);
          dp[i][j][k][1] = min(dp[i][j-1][k][1] + B + (2ll-r)*D,dp[i][j][k][1]);
        }
        if (k != 0) {
          r = (N/(n2 * n3 * n5 / 5)) % 5;
          dp[i][j][k][0] = min(dp[i][j][k-1][0] + C + (r - r/4 * 2)*D,dp[i][j][k][0]);
          if (r == 0) r=2;
          dp[i][j][k][1] = min(dp[i][j][k-1][1] + C + (4ll-r)*D,dp[i][j][k][1]);
        }

        if (N/n2/n3/n5 < 1000000007ll * 1000000007ll / D) {
          ans = min(ans,D*(N/n2/n3/n5) + dp[i][j][k][0]);
          ans = min(ans,D*(N/n2/n3/n5+1) + dp[i][j][k][1]);
        }

        n5 *= 5;
      }
      n3 *= 3;
      n5 = 1;
    }
    n2 *= 2;
    n3 = 1;
  }
  return ans;
}

