    else {e.emplace_back(a+d,(x-1)/2);e.emplace_back(a+d,(x+1)/2);}
    if(x%3==0) e.emplace_back(b,x/3);
    else {e.emplace_back(b+d*r3,(x-r3)/3);e.emplace_back(b+d*(3-r3),(x+3-r3)/3);}
    if(x%5==0) e.emplace_back(c,x/5);
    else {e.emplace_back(c+d*r5,(x-r5)/5);e.emplace_back(c+d*(5-r5),(x+5-r5)/5);}
