ll dijkstra(ll x, ll a, ll b, ll c, ll d){
    auto cmp = [](pll a, pll b){return a.first>b.first;};
    priority_queue<pll,vector<pll>,decltype(cmp)> pq(cmp);
    pq.emplace(d,1);
    unordered_map<ll,ll> dist;
    unordered_map<ll,ll> seen;
    dist[0] = 0;
    dist[1] = d;
    seen[0] = seen[1] = true;
    while(!pq.empty()){
        ll cost,cur;
        tie(cost,cur) = pq.top();
        pq.pop();
        DBG(make_pair(cost,cur))
        if(cur==x) return cost;
        if(dist[cur]<cost) continue;
        ll nc,nt;
        if(cur>x){
            dist[x] = cost+(cur-x)*d;
            pq.emplace(cost+(cur-x)*d,x);
        }
        else{
            nc = cost+d;
            nt = cur-1;
            if(dist[nt]>nc || !seen[nt])
            {
                seen[nt] = true;
                dist[nt] = nc;
                pq.emplace(nc,nt);
            }
        }
        if(cur>x) continue;
        nc = cost+d;
        nt = cur+1;
        if(dist[nt]>nc || !seen[nt])
        {
            seen[nt] = true;
            dist[nt] = nc;
            pq.emplace(nc,nt);
        }
        nc = cost+a;
        nt = cur*2;
        if(dist[nt]>nc || !seen[nt])
        {
            seen[nt] = true;
            dist[nt] = nc;
            pq.emplace(nc,nt);
        }
        nc = cost+b;
        nt = cur*3;
        if(dist[nt]>nc || !seen[nt])
        {
            seen[nt] = true;
            dist[nt] = nc;
            pq.emplace(nc,nt);
        }
        nc = cost+c;
        nt = cur*5;
        if(dist[nt]>nc || !seen[nt])
        {
            seen[nt] = true;
            dist[nt] = nc;
            pq.emplace(nc,nt);
        }

    }
    return 0;
}

ll dfs(ll x,ll a,ll b,ll c,ll d){
    if(x==0) return 0;
    if(x==1) return d;
    if(x==2) return min(2*d,a+d);
    if(dp[x]) return dp[x];
    ll ret = 1e18;
    ll r3 = x%3;
    ll r5 = x%5;
    if(x%2==0) ret = min(ret,a+dfs(x/2,a,b,c,d));
    else {
        ret = min(ret,a+d+dfs((x+1)/2,a,b,c,d));
        ret = min(ret,a+d+dfs((x-1)/2,a,b,c,d));
        }
    if(x%3==0) ret = min(ret,b+dfs(x/3,a,b,c,d));
    else{
        ret = min(ret,b+d*(3-r3)+dfs((x+3-r3)/3,a,b,c,d));
        ret = min(ret,b+d*r3+dfs((x-r3)/3,a,b,c,d));
    }
    if(x%5==0) ret = min(ret,c+dfs(x/5,a,b,c,d));
    else{
        ret = min(ret,c+d*(5-r5)+dfs((x+5-r5)/5,a,b,c,d));
        ret = min(ret,c+d*r5+dfs((x-r5)/5,a,b,c,d));
    }
    return dp[x] = ret;
}

