int main () {
	int T;
	cin >> T;
	while (T--) {
		long long N, A, B, C, D;
		cin >> N;
		cin >> A >> B >> C >> D;

		unordered_map<ll, ll> dp;

		priority_queue<pair<ll, ll>> pq;

		pq.push({0, N});
		while (!pq.empty()) {
			ll dist = -pq.top().first;
			ll x = pq.top().second;
			pq.pop();
			if (DB) cout << "State = " << x << " " << dist << endl;
			if (x == 0) {
				break;
			}

			if (1.0 * x * D < 1e18 && (dp.count(0) == 0 || dist + x * D < dp[0])) {
				pq.push({-(dist + x*D), 0});
				dp[0] = dist + x * D;
			}

			if (x % 2 == 0) {
				if (dp.count(x/2) == 0 || dist + A < dp[x/2]) {
					pq.push({-(dist+A), x/2});
					dp[x/2] = dist + A;
				}
			}

			if (x % 3 == 0) {
				if (dp.count(x/3) == 0 || dist + B < dp[x/3]){
					pq.push({-(dist+B), x/3});
					dp[x/3] = dist + B;
				}
			}
			if (x % 5 == 0) {
				if (dp.count(x/5) == 0 || dist + C < dp[x/5]){
					pq.push({-(dist+C), x/5});
					dp[x/5] = dist + C;
				}
			}
			if (x % 30 != 0) {
				if (dp.count(x-1) == 0 || dist + D < dp[x-1]){
					pq.push({-(dist+D), x-1});
					dp[x-1] = dist + D;
				}
				if (dp.count(x+1) == 0 || dist + D < dp[x+1]){
					pq.push({-(dist+D), x+1});
					dp[x+1] = dist + D;
				}
			}
		}

		cout << dp[0] << endl;
	}
}

