long long N, A, B, C, D;

map<long long, unsigned long long> dp;
set<long long> sets;
vector<int> parms = { 2, 3, 5 };
vector<long long> cost;

long long solve(long long x)
{

	if (x == 0)
	{
		return 0;
	}
	if (x == 1)
	{
		return D;
	}
	if (dp.count(x) > 0)
	{
		return dp[x];
	}

	long long ret = 1e18;

	int par = 1;
	for (int param_index = 0; param_index < parms.size(); param_index++)
	{
		int par = parms[param_index];
		long long dist_u, dist_l;

		dist_l = par - x % par;
		dist_u = x % par;

		ret = min(ret, solve((x - dist_l) / par) + cost[param_index] + dist_l * D);
		ret = min(ret, solve((x - dist_l) / par) + D * (x - ((x - dist_l) / par)));

		ret = min(ret, solve((x + dist_u) / par) + cost[param_index] + dist_u * D);
		ret = min(ret, solve((x + dist_u) / par) + (x - ((x + dist_u) / par))*D);

	}

	dp[x] = ret;

	return ret;
}

