ll N;
ll A;
ll B;
ll C;
ll D;
map<ll, ll> dp;

ll solve(ll n) {
	if (n == 0) {
		return 0;
	}

	if (dp.count(n) > 0) {
		return dp[n];
	}

	ll result = INF;

	if (n > 1) { //元の1に戻すループなので意味ない
		reps(i, -4, 4) {
			if (n + i <= 0) {
				continue;
			}

			if ((n + i) % 5 == 0) {
				ll cost = C + abs(i) * D;
				ll next = (n + i) / 5;
				ll ans = solve(next) + cost;
				chmin(result, ans);
			}
		}

		reps(i, -2, 2) {
			if (n + i <= 0) {
				continue;
			}

			if ((n + i) % 3 == 0) {
				ll cost = B + abs(i) * D;
				ll next = (n + i) / 3;
				ll ans = solve(next) + cost;
				chmin(result, ans);
			}
		}

		reps(i, -1, 1) {
			if (n + i <= 0) {
				continue;
			}

			if ((n + i) % 2 == 0) {
				ll cost = A + abs(i) * D;
				ll next = (n + i) / 2;
				ll ans = solve(next) + cost;
				chmin(result, ans);
			}
		}
	}

	//-1の連打
	ll temp = INF / n;
	if (temp + 1 >= D) {
		ll ans = n * D;
		chmin(result, ans);
	}

	dp[n] = result;

	return result;
}

int main() {
	ll T;
	cin >> T;

	rep(i, T) {
		cin >> N;
		cin >> A;
		cin >> B;
		cin >> C;
		cin >> D;

		dp.clear();

		ll result = solve(N);

		cout << result << endl;
	}

	return 0;
}

