ll rec(ll _n) {
	if (m_ans.find(_n) != m_ans.end()) {
		return m_ans[_n];
	}
	ll ans_a1 = rec(_n / 2LL) + (_n % 2LL) * d + a;
	ll ans_b1 = rec(_n / 3LL) + (_n % 3LL) * d + b;
	ll ans_c1 = rec(_n / 5LL) + (_n % 5LL) * d + c;
	ll ans_a2 = rec((_n+1) / 2LL) + (2LL - _n % 2) * d + a;
	ll ans_b2 = rec((_n+2) / 3LL) + (3LL - _n % 3) * d + b;
	ll ans_c2 = rec((_n+4) / 5LL) + (5LL - _n % 5) * d + c;
	ll ans_d = _n * d;
	if (_n > 1000000000)ans_d = 1000000000000000000;
	ll ans = min(min(min(ans_a1, ans_b1), min(ans_c1, ans_d)), min(min(ans_a2, ans_b2), ans_c2));
