ll N,A,B,C,D;
map<ll,ll> memo;

ll dfs(ll n){
    if(!n)return 0;
    if(memo.count(n)) return memo[n];
    auto f2 = [&](ll nn) {
        if (nn >= n) return ll(1e18+100);
        return dfs(nn);
    };
    ll m = 1e18+100;
    if(ll(1e18+100)/D > n) m = n*D;
    if(n%2 == 0){
        cmin(m, A+f2(n/2));
        cmin(m, A+D*2+f2(n/2+2));
    }else{
        cmin(m, A+D+f2((n+1)/2));
        cmin(m, A+D+f2((n-1)/2));
    }
    if(n%3 == 0){
        cmin(m, B+f2(n/3));
        cmin(m, B+D*3+f2(n/3+3));
    }else{
        ll r = n%3;
        cmin(m, B+D*r+f2((n-r)/3));
        cmin(m, B+D*(3-r)+f2((n+3-r)/3));
    }
    if(n%5 == 0){
        cmin(m, C+f2(n/5));
        cmin(m, C+D*5+f2(n/5+5));
    }else{
        ll r = n%5;
        cmin(m, C+D*r+f2((n-r)/5));
        cmin(m, C+D*(5-r)+f2((n+5-r)/5));
    }
    memo[n] = m;
    return m;
}

