#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using pii = pair<ll,ll>;


ll solve() {
    ll N;
    vector<ll> A(4);
    vector<ll> ms{2,3,5};
    cin >> N;
    for ( int i = 0; i < 4; i++ ) {
        cin >> A[i];
    }
    ll INF = 1e18;
    map<ll, ll> coin;  // n, cost
    priority_queue<pii, vector<pii>, greater<>> q;    // cost, n
    coin[N] = 0;
    q.push(pii(0,N));
    while ( !q.empty() ) {
        ll c0 = q.top().first;
        ll n0 = q.top().second;
        q.pop();
        if ( n0 == 0 ) return c0;
        if ( coin.count(n0) > 0 && coin[n0] < c0 ) continue;
        for ( int i = 0; i < 3; i++ ) {
            ll m = ms[i];
            if ( n0 / m == 0 ) {
                ll c = c0 + A[3]*n0;
                ll n = 0;
                if ( coin.count(n) == 0 || coin[n] > c ) {
                    coin[n] = c;
                    q.push(pii(c,n));
                }
            }
            ll r = n0 % m;
            if ( r > 0 ) {
                ll c = c0 + A[3]*(m-r) + A[i];
                ll n = (n0 + m-r)/m;
                if ( coin.count(n) == 0 || coin[n] > c ) {
                    coin[n] = c;
                    q.push(pii(c,n));
                }
            }
            {
                ll c = c0 + A[3]*r + A[i];
                if ( n0 <= (m*A[i])/((m-1)*A[3]) ) {
                    c = min(c, c0 + A[3]*(n0 - (n0-r)/m));
                }
                ll n = (n0 - r)/m;
                if ( coin.count(n) == 0 || coin[n] > c ) {
                    coin[n] = c;
                    q.push(pii(c,n));
                }
            }
        }
    }
    return -1LL;
}

