    int T;
    cin >> T;
    vector<ll> ans(T);
    for ( int t = 0 ; t < T ; t++ ) {
        ans[t] = solve();
    }
    for ( int t = 0; t < T; t++ ) {
        cout << ans[t] << "\n";
    }
    return 0;
}

