s64 N, A, B, C, D;
map<s64, s64> m;

s64 dfs(s64 n)
{
    if (n == 0) return 0;
    if (n == 1) return D;
    if (m.count(n) > 0) return m[n];

    s64 ret = 1e18;
    if (n < ret / D) ret = n * D;
    vs64 temp(6);
    static const s64 div[3] = {2, 3, 5};
    s64 c[3] = {A, B, C};
    rep (i, 3)
    {
