        temp[2 * i + 1] = abs(n - CEIL(n, div[i]) * div[i]) * D + c[i] + dfs(CEIL(n, div[i]));
    }

    rep (i, 6) ret = min(ret, temp[i]);
    m[n] = ret;
    return ret;
}

