const ll LINF = 6e18;
#define chmin(a,b) a=min(a,b);

ll a, b, c, d;
map<ll, ll> mp;

ll dfs(ll n) {
  if (!mp.count(n)) {
    if (n == 0) {
      mp[n] = 0;
    } else {
      ll res = LINF;
      if (n <= res / d) chmin(res, d * n);
      chmin(res, dfs(n / 2) + a + d * (n % 2));
      chmin(res, dfs(n / 3) + b + d * (n % 3));
      chmin(res, dfs(n / 5) + c + d * (n % 5));
      if (n > 1) {
        if (n > 2) chmin(res, dfs(1 + n / 2) + a + d * (2 - (n % 2)));
        chmin(res, dfs(1 + n / 3) + b + d * (3 - (n % 3)));
        chmin(res, dfs(1 + n / 5) + c + d * (5 - (n % 5)));
      }
      mp[n] = res;
    }
  }
  return mp[n];
}

