ll a, b, c, d;
map<ll, ll> resmap;

// Nから減らしていって0にすると考える
ll calc_recursive(ll n){
  if (n == 0) return 0;
  if (n == 1) return d; // 増やして2, 3, 5にしてから割っても1に戻ってしまうので、この場合は -1 するしかない
  if ( resmap.find(n) != resmap.end() ) return resmap[n];
  ll res = LINF;

  // +-1 だけをして辿り着く場合
  // ※最大で N*D = 10^18*10^9 に達してしまうが、+-4してから1/5したり、+-2してから1/3したりを繰り返せば、明らかに答えはLINF以下で収まるので、N*Dが大きすぎる場合は無視していい
  // よって、n*dがオーバーフローしなかった場合だけ chmin する
  if (n * d / n == d) chmin(res, n * d);

  // (2の倍数でなければ+-してから) 1/2 ※
  ll mod2 = n % 2;
  if (mod2==0) chmin(res, a + calc_recursive(n/2));
  else{
    chmin(res, d + a + calc_recursive((n+1)/2)); // + してから 1/2
    chmin(res, d + a + calc_recursive((n-1)/2));
  }

  // 1/3
  ll mod3 = n % 3;
  if (mod3==0) chmin(res, b + calc_recursive(n/3));
  else{
    chmin(res, d * (3 - mod3) + b + calc_recursive(ceil_divide(n, 3)));
    chmin(res, d * mod3 + b + calc_recursive(n/3));    
  }

  // 1/5
  ll mod5 = n % 5;
  if (mod5==0) chmin(res, c + calc_recursive(n/5));
  else{
    chmin(res, d * (5 - mod5) + c + calc_recursive(ceil_divide(n, 5)));
    chmin(res, d * mod5 + c + calc_recursive(n/5));    
  }

  if ( resmap.find(n) != resmap.end() ) chmin(resmap[n], res);
  else resmap[n] = res;
  return resmap[n];

}

