		else mi1 = min(k1 + c + (3 - x%3) * a, k1 + (x - (x/3 + 1))*a + (3 - x%3) * a);
		mi[1] = min(mi0, mi1);
	}
	if(x/5 == 0){
		mi[2] = x*a;
	}else if(x%5 == 0){
		ll k = f(x/5);
		if(x - x/5 > 1000000000) mi[2] = k + d;
		else mi[2] = min(k + d, k + (x - x/5)*a);
