int dfs(int n, int a, int b, int c, int d, map<int, int> &dp)
{
    if (dp.find(n) != dp.end()) {
        return dp[n];
    }
    if (n) {
        // cout << n << endl;
        int ret = INF;
        if (n < 1010001000LL) {
            if (n * d / d == n) {
                ret = min(ret, n * d);
            }
        }
        if (n/2 != n && n/2 != 0) {
            int k = dfs(n/2, a, b, c, d, dp);
            if (k + a + (n % 2) * d >= 0) 
            ret = min(ret, dfs(n/2, a, b, c, d, dp) + a + (n % 2) * d);
        }
        if (n/2+1 != n) {
            int k = dfs(n/2+1, a, b, c, d, dp);
            if (k + a + (2 - n % 2) * d >= 0) 
            ret = min(ret, dfs(n/2+1, a, b, c, d, dp) + a + (2 - n % 2) * d);
        }
        if (n/3 != n && n/3 != 0) {
            int k = dfs(n/3, a, b, c, d, dp);
            if (k + b + (n % 3) * d >= 0) 
            ret = min(ret, dfs(n/3, a, b, c, d, dp) + b + (n % 3) * d);
        }
        if (n/3+1 != n) {
            int k = dfs(n/3+1, a, b, c, d, dp);
            if (k + b + (3 - n % 3) * d >= 0) 
            ret = min(ret, dfs(n/3+1, a, b, c, d, dp) + b + (3 - n % 3) * d);
        }
        if (n/5 != n && n/5 != 0) {
            int k = dfs(n/5, a, b, c, d, dp);
            if (k + c + (n % 5) * d >= 0) 
            ret = min(ret, dfs(n/5, a, b, c, d, dp) + c + (n % 5) * d);
        }
        if (n/5+1 != n) {
            int k = dfs(n/5, a, b, c, d, dp);
            if (k + c + (5 - n % 5) * d >= 0) 
            ret = min(ret, dfs(n/5+1, a, b, c, d, dp) + c + (5 - n % 5) * d);
        }
        dp[n] = ret;
        return ret;
    } else {
        return 0;
    }
}

int bfs(int n, int a, int b, int c, int d)
{
    priority_queue<pair<int, int>> pq; // value , num
    int score = INF;
    map<int, int> dp;
    pq.push({0, 0});
    while (pq.size()) {
        pair<int, int> data = pq.top();
        pq.pop();
        if (data.second < 0) continue;
        //if (data.second > n * n) continue;
        if (data.second > n) {
            score = min(score, data.first + (data.second - n) * d);
            continue;
        }
        if (dp.find(data.second) != dp.end()) {
            if (dp[data.second] <= data.first) {
                continue;
            } else {
                dp[data.second] = data.first;
            }
        } else {
            dp[data.second] = data.first;
        }
        //cout << data.first << " " << data.second << endl;
        if (data.second == n) {
            score = min(score, data.first);
        } else if (data.first <= score) {
            pq.push(make_pair(data.first + d, data.second + 1));
            pq.push(make_pair(data.first + d, data.second - 1));
            pq.push(make_pair(data.first + a, data.second * 2));
            pq.push(make_pair(data.first + b, data.second * 3));
            pq.push(make_pair(data.first + c, data.second * 5));
        }
    }
    return score;
}

