ll solve(ll n){
    if(n == 0) return 0;
    if(mp.count(n)) return mp[n];
    ll ans = 1e18;
    if(n <= 3e9) ans = n*d;

    for(int p=-1; p<=1;p++){
        ll x = n + p;
        if(x%2 != 0 || x<0) continue;
        ll y = x/2;
        if(y < n)
        ans = min(ans,abs(p)*d + a + solve(y));
    }
    for(int p =-2; p<=2; p++){
        ll x = n + p;
        if(x%3 !=0 || x < 0) continue;
        ll y = x/3;
        if(y < n)
        ans = min(ans,abs(p)*d + b + solve(y));
    }
    for(int p = -4; p<= 4 ; p++){
        ll x = n + p;
        if(x%5 !=0 || x < 0) continue;
        ll y = x/5;
        if(y < n)
        ans = min(ans,abs(p)*d + c+ solve(y));
    }

    return mp[n] = ans ;
}

