            }
            if(x==1){
                return memo[x] = d;
            }
            if(x==2){
                return memo[x] = min(d*2,d+c);
            }
            if(memo.count(x) > 0) {
                return memo[x];
            }
            if(x > 5*n){
                return  INF;
            }

            ll res = INF;
            if(x <= 1e9){
                res = d*x;
            }

            ll da = x%2;
            ll db = x%3;
            ll dc = x%5;

            ll c1 = (x-dc+5)/5;
            ll c2 = (x-dc)/5;

            if(memo.count(c1)==0){
                chmin(res, (5-dc)*d + c + dfs(dfs, c1));
            }else{
                chmin(res, (5-dc)*d + c + memo[c1]);
            }

            if(memo.count(c2)==0){
                chmin(res, dc*d + c+dfs(dfs, c2));
            }else{
                chmin(res, dc*d + c + memo[c2]);
            }

            ll b1 = (x-db+3)/3;
            ll b2 = (x-db)/3;

