#include <bits/stdc++.h>
using namespace std;
using lint = long long;

void Solve() {
  lint N, A, B, C, D;
  cin >> N >> A >> B >> C >> D;

  map<lint, lint> memo;
  priority_queue<pair<lint, lint>, vector<pair<lint, lint>>, greater<pair<lint, lint>>> pq;

  pq.emplace(0, N);
  memo[N] = 0;

  auto Relax = [&](lint n, lint cost) {
    if (n < 0) return;
    if (n <= 100 && memo.count(n) == 0 || memo[n] > cost) {
      memo[n] = cost;
      pq.emplace(memo[n], n);
    }
    if (n == 0) return;
    if (n % 2 == 0) {
      lint c = min(A, lint((1ll * n / 2) <= (1e18 / D) ? (1ll * n / 2) * D : 1e18));
      if (memo.count(n / 2) == 0 || memo[n / 2] > cost + c) {
        memo[n / 2] = cost + c;
        pq.emplace(memo[n / 2], n / 2);
      }
    }
    if (n % 3 == 0) {
      lint c = min(B, lint((2ll * n / 3) <= (1e18 / D) ? (2ll * n / 3) * D : 1e18));
      if (memo.count(n / 3) == 0 || memo[n / 3] > cost + c) {
        memo[n / 3] = cost + c;
        pq.emplace(memo[n / 3], n / 3);
      }
    }
    if (n % 5 == 0) {
      lint c = min(C, lint((4ll * n / 5) <= (1e18 / D) ? (4ll * n / 5) * D : 1e18));
      if (memo.count(n / 5) == 0 || memo[n / 5] > cost + c) {
        memo[n / 5] = cost + c;
        pq.emplace(memo[n / 5], n / 5);
      }
    }
  };

  while (!pq.empty()) {
    lint n = pq.top().second;
    lint cost = pq.top().first;
    pq.pop();
    if (n == 0) {
      cout << cost << "\n";
      return;
    }
    if (cost > 1e18) continue;
    if (memo[n] != cost) continue;

    bool split = 0;
    Relax(n, cost);
    for (lint i = 1; i <= 5; i++) {
      Relax(n + i, cost + i * D);
      Relax(n - i, cost + i * D);
    }
  }
}

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);

  int T;
  cin >> T;
  while (T--) {
    Solve();
  }
}

