		if(n%x==0) ret = min(ret, calc(n/x)+ex);
		else {
			ll up = (n/x+1ll)*x;
			ll down = (n/x)*x;
			ret = min(ret, calc(down/x)+D*(n-down)+ex);
			ret = min(ret, calc(up/x)+D*(up-n)+ex);
		}
	}
	return Map[n] = ret;
}

