const ll inf = 1LL << 52;
const int maxPow = 61;

int t;
ll n, a, b, c, d;
ll dp[maxPow + 1][maxPow + 1][maxPow + 1][2];

void upd(ll& dest, ll sour) {
  if (sour < dest) dest = sour;
}

void expand(int i, int j, int k, int bonus, ll rem, ll cost) {
  ll act = rem % 2;
  upd(dp[i + 1][j][k][(bonus && (act == 0)) ? 1 : 0], cost + a + act * d);
  if (act != 0) upd(dp[i + 1][j][k][1], cost + a + (2 - act) * d);

  act = rem % 3;
  upd(dp[i][j + 1][k][(bonus && (act == 0)) ? 1 : 0], cost + b + act * d);
  if (act != 0) upd(dp[i][j + 1][k][1], cost + b + (3 - act) * d);

  act = rem % 5;
  upd(dp[i][j][k + 1][(bonus && (act == 0)) ? 1 : 0], cost + c + act * d);
  if (act != 0) upd(dp[i][j][k + 1][1], cost + c + (5 - act) * d);
}

ll solve() {
  ll answer = inf;

  for (int i = 0; i < maxPow; i++)
    for (int j = 0; j < maxPow; j++)
      for (int k = 0; k < maxPow; k++)
        dp[i][j][k][0] = dp[i][j][k][1] = inf;

  dp[0][0][0][0] = 0;

  ll auxi = n;
  for (int i = 0; i < maxPow; i++, auxi >>= 1) {
    ll auxj = auxi;

    for (int j = 0; j < maxPow; j++, auxj /= 3) {
      ll auxk = auxj;

      for (int k = 0; k < maxPow; k++, auxk /= 5) {
       ll aux = auxk;

       for (ll bonus = 0; bonus < 2; bonus++, aux++) {

         if (dp[i][j][k][bonus] >= answer) continue;

         /*
         cerr << i << ' ' << j << ' ' << k << ' ' << bonus << '\n';
         cerr << answer << ' ' << aux << ' ' << dp[i][j][k][bonus] << '\n';
         cerr << '\n';
         */

         if (aux == 0 || (answer - dp[i][j][k][bonus]) / aux >= d)
           upd(answer, dp[i][j][k][bonus] + d * aux);

         if (aux == 0) continue;
         expand(i, j, k, bonus, aux, dp[i][j][k][bonus]);
       }
      }
    }
  }

  return answer;
}

