    }

    ll ans = INF;
    if (n <= INF/D) {
        ans = n*D;
    }

    int a = n%2, b = n%3, c = n%5;

    ans = min(ans, calc(n/2) + A + a*D);
    if (n > 2) {
        ans = min(ans, calc(n/2+1) + A + (2-a)*D);
    }

    ans = min(ans, calc(n/3) + B + b*D);
    if (n > 1) {
        ans = min(ans, calc(n/3+1) + B + (3-b)*D);
    }

    ans = min(ans, calc(n/5) + C + c*D);
    if (n > 1) {
        ans = min(ans, calc(n/5+1) + C + (5-c)*D);
    }

    return cache[n] = ans;
}

