const int INF = 1e18;

int a,b,c,d;
int solve(const int n) {
  const int divcost[] = {INF,INF,a,b,INF,c};

  int solution = 61*(a+d);  // can be done in 60*d + 59*a
  set<pii> pq;
  pq.insert({0,n});
  while (!pq.empty()) {
    int cost, curr;
    tie(cost, curr) = *pq.begin();
    pq.erase(pq.begin());
    if (cost >= solution)  // stop when we can't find a better solution anymore
      return solution;

    if ((solution-cost)/d >= curr)  // anti-overflow
      solution = min(solution, cost+curr*d);

    {
      const pii pd = {-(curr%5), 5};
      int next = (curr + pd.first)/pd.second;
      if (next >= 0 && next < curr)
        pq.insert({cost + abs(pd.first)*d + divcost[pd.second], next});
    }
    {
      const pii pd = {5-(curr%5), 5};
      if (pd.first < 5) {
        int next = (curr + pd.first)/pd.second;
        if (next >= 0 && next < curr)
          pq.insert({cost + abs(pd.first)*d + divcost[pd.second], next});
      }
    }
    {
      const pii pd = {-(curr%3), 3};
      int next = (curr + pd.first)/pd.second;
      if (next >= 0 && next < curr)
        pq.insert({cost + abs(pd.first)*d + divcost[pd.second], next});
    }
    {
      const pii pd = {3-(curr%3), 3};
      if (pd.first < 3) {
        int next = (curr + pd.first)/pd.second;
        if (next >= 0 && next < curr)
          pq.insert({cost + abs(pd.first)*d + divcost[pd.second], next});
      }
    }
    {
      const pii pd = {-(curr%2), 2};
      int next = (curr + pd.first)/pd.second;
      if (next >= 0 && next < curr)
        pq.insert({cost + abs(pd.first)*d + divcost[pd.second], next});
    }
    {
      const pii pd = {2-(curr%2), 2};
      if (pd.first < 2) {
        int next = (curr + pd.first)/pd.second;
        if (next >= 0 && next < curr)
          pq.insert({cost + abs(pd.first)*d + divcost[pd.second], next});
      }
    }
  }
  return solution;
}

