typedef long long int lld;

lld n,a,b,c,d;
map<lld,lld> mm;

void recur(lld n,lld dist){
	mm[n] = dist;
	if(n==1) return;
	lld dist1 = (n%2)*d + dist + a;
	lld dist2 = (n%3)*d + dist + b;
	lld dist3 = (n%5)*d + dist + c;
	if((n/2)>=1&&(double)(n-(n/2))<=(double)dist1/(double)d) dist1 = min(dist1,(n-(n/2))*d+dist);
	if((n/3)>=1&&(double)(n-(n/3))<=(double)dist2/(double)d) dist2 = min(dist2,(n-(n/3))*d+dist);
	if((n/5)>=1&&(double)(n-(n/5))<=(double)dist3/(double)d) dist3 = min(dist3,(n-(n/5))*d+dist);
	if((n/2)>=1&&mm[n/2]==0||mm[n/2]>dist1) recur(n/2,dist1);
	if((n/3)>=1&&mm[n/3]==0||mm[n/3]>dist2) recur(n/3,dist2);
	if((n/5)>=1&&mm[n/5]==0||mm[n/5]>dist3) recur(n/5,dist3);
	lld dist4 = (2-(n%2))*d + dist + a;
	lld dist5 = (3-(n%3))*d + dist + b;
	lld dist6 = (5-(n%5))*d + dist + c;
	if(n>2){
		if((double)(n-(n/2)-1)<=(double)dist4/(double)d) dist4 = min(dist4,(n-(n/2)-1)*d+dist);
		if((double)(n-(n/3)-1)<=(double)dist5/(double)d) dist5 = min(dist5,(n-(n/3)-1)*d+dist);
		if((double)(n-(n/5)-1)<=(double)dist6/(double)d) dist6 = min(dist6,(n-(n/5)-1)*d+dist);
	}
	if(mm[(n/2)+1]==0||mm[(n/2)+1]>dist4) recur((n/2)+1,dist4);
	if(mm[(n/3)+1]==0||mm[(n/3)+1]>dist5) recur((n/3)+1,dist5);
	if(mm[(n/5)+1]==0||mm[(n/5)+1]>dist6) recur((n/5)+1,dist6); 
}
