using namespace std;

#define INF 1e15

ll N,A,B,C,D;

ll dfs(map<ll,ll> &memo, ll x)
{
    if (memo.count(x)) return memo[x];
    ll ret=INF;
    chmin(ret, dfs(memo,(x-x%2)/2) + x%2*D + A);
    chmin(ret, dfs(memo,(x+x%2)/2) + x%2*D + A);
    chmin(ret, dfs(memo,(x-x%3)/3) + x%3*D + B);
    chmin(ret, dfs(memo,(x+3-x%3)/3) + (3-x%3)*D + B);
    chmin(ret, dfs(memo,(x-x%5)/5) + x%5*D + C);
    chmin(ret, dfs(memo,(x+5-x%5)/5) + (5-x%5)*D + C);
    if (D<=INF/x) chmin(ret, x*D);
    return memo[x]=ret;
}

