using ull = unsigned long long;

template <typename F>
struct y_comb {
  F func;

  template <typename... Args>
  decltype(auto) operator()(Args&&... args) {
    return func(*this, std::forward<Args>(args)...);
  }

  template <typename... Args>
  decltype(auto) operator()(Args&&... args) const {
    return func(*this, std::forward<Args>(args)...);
  }
};

template <typename F>
y_comb(F) -> y_comb<F>;

constexpr ull maxAns = 1ull << 40;

int main() {
  int ntc;
  cin >> ntc;
  for (int itc = 0; itc < ntc; itc++) {
    ull n, a, b, c, d;
    cin >> n >> a >> b >> c >> d;
    unordered_map<ull, ull> memo;
    auto f = y_comb{[&](auto& self, ull x) -> ull {
      ull& ret = memo[x];
      if (ret) return ret;
      if (x == 0) return 0;
      ret = (x < maxAns / d) ? x * d : maxAns;
      int r2 = x % 2;
      ret = min(ret, a + (r2 == 0 ? self(x / 2)
                                  : d + min(self(x / 2), self(x / 2 + 1))));
      int r3 = x % 3;
      ret = min(ret, b + (r3 <= 1 ? r3 * d + self(x / 3)
                                  : (3 - r3) * d + self(x / 3 + 1)));
      int r5 = x % 5;
      ret = min(ret, c + (r5 <= 2 ? r5 * d + self(x / 5)
                                  : (5 - r5) * d + self(x / 5 + 1)));
      return ret;
    }};
    cout << f(n) << '\n';
  }
  return 0;
}

