template<class T> inline bool UpdateMin(T& a, T b) {
  if (a > b) { a = b; return 1; } return 0;
}

template<class T> inline bool UpdateMax(T& a, T b) {
  if (a < b) { a = b; return 1; } return 0;
}

int64 SolveCase() {
  int64 n, a, b, c, d;
  cin >> n >> a >> b >> c >> d;

  unordered_map<int64, int64> cache;
  cache[0] = 0;
  cache[1] = d;
  function<int64(int64)> solve_fn = [&](int64 x) -> int64 {
    if (cache.find(x) != cache.end()) {
      return cache[x];
    }

    int64 min = INT64_MAX;
    if (x <= INT64_MAX / d) {
      UpdateMin(min, x * d);
    }

    for (const auto [divisor, cost] : vector<tuple<int64, int64>>({{2, a}, {3, b}, {5, c}})) {
      if (x % divisor == 0) {
        UpdateMin(min, solve_fn(x / divisor) + cost);
      }
      int64 r = x % divisor;
      UpdateMin(min, solve_fn(x / divisor) + cost + r * d);
      if (x / divisor + 1 < x) {
        UpdateMin(min, solve_fn(x / divisor + 1) + cost + (divisor - r) * d);
      }
    }

    cache[x] = min;
    return min;
  };
  return solve_fn(n);
}

