Int N, A, B, C, D, res;
map<Int, Int> memo;

Int Y[] = {5, 3, 2}, Z[3];

Int rec(Int x) {
  if (memo.count(x)) {
    return memo[x];
  }
  Int ans = INFLL;
  if (x <= INF) {
    chmin(ans, x * D);
  }
  memo[x] = INFLL;
  for (int i = 0; i < 3; ++i) {
    if (x / Y[i] > 0) {
      chmin(ans, rec(x / Y[i]) + (x % Y[i]) * D + Z[i]);
    }
    if (x % Y[i] > 0 && x % Y[i] + 1 != x) {
      chmin(ans, rec(x / Y[i] + 1) + (Y[i] - x % Y[i]) * D + Z[i]);
    }
  }
  memo[x] = ans;
  return ans;
}

