ll dfs(ll x) {
    if (dp.count(x)) return dp[x];
    if (x == 0) return 0;
    if (x == 1) return d;
    ll res = (x <= INF ? d * x : LINF);
    chmin(res, dfs(x / 2) + a + abs((x / 2) * 2 - x) * d);
    if (x % 2 != 0)
