void app() {
  int t;
  cin>>t;

  rep(t_,t){
    lint n,a,b,c,d;
    cin>>n>>a>>b>>c>>d;
    lint ans=-1;

    map<lint,lint> dp;
    using state=pair<lint,lint>;
    priority_queue<state,vector<state>,greater<state>> q;
    dp[n]=9e18;
    q.emplace(0,n);
    while(!q.empty()){
      auto up=q.top();
      q.pop();
      lint ucost=up.first;
      lint u=up.second;
      //cout<<ucost<<u<<endl;

      if(u==0){
        ans=ucost;
        break;
      }
      if(u<0) continue;

      vector<pair<lint,lint>> g;
      if(u<=5){
        g.emplace_back(ucost+d*u,0);
      }
      g.emplace_back(ucost+a+u%2*d,u/2);
      g.emplace_back(ucost+b+u%3*d,u/3);
      g.emplace_back(ucost+c+u%5*d,u/5);
      g.emplace_back(ucost+a+(2-u%2)*d,u/2+1);
      g.emplace_back(ucost+b+(3-u%3)*d,u/3+1);
      g.emplace_back(ucost+c+(5-u%5)*d,u/5+1);
      if(u-u/2<(9e18-ucost)/d){
        g.emplace_back(ucost+(u-u/2)*d,u/2);
      }
      if(u-u/3<(9e18-ucost)/d){
        g.emplace_back(ucost+(u-u/3)*d,u/3);
      }
      if(u-u/5<(9e18-ucost)/d){
        g.emplace_back(ucost+(u-u/5)*d,u/5);
      }
      for(auto p:g){
        lint v=p.second;
        if(v>2e18||v<0) continue;
        if(dp[v]==0) dp[v]=9e18;
        if(chmin(dp[v],p.first)) q.push(p);
      }
    }
    cout<<ans<<endl;
  }
}

