typedef long long LL;

const LL INF=(1LL<<60)-1,inf=(1LL<<30)-1;
const int pr[3]={2,3,5};

LL n,a[3],d;

void into(){
  scanf("%lld%lld%lld%lld%lld",&n,&a[0],&a[1],&a[2],&d);
}

map<LL,LL>dp;

LL Dfs_dp(LL n){
  if (dp.find(n)!=dp.end()) return dp[n];
  LL res=INF;
  for (int i=0;i<3;++i){
	int t=pr[i];
	LL l=n/t,r=(n+t-1)/t;
	if (l<n) res=min(res,Dfs_dp(l)+a[i]+d*(n-l*t)),assert(l*t<=n);
	if (l<n&&n-l<inf) res=min(res,Dfs_dp(l)+d*(n-l));
	if (r<n) res=min(res,Dfs_dp(r)+a[i]+d*(r*t-n)),assert(r*t>=n);
	if (r<n&&n-r<inf) res=min(res,Dfs_dp(r)+d*(n-r));
  }
  return dp[n]=res;
}

void Get_dp(){
  dp.clear();
  dp[0]=0;
  dp[1]=d;
  Dfs_dp(n);
}

void work(){
  Get_dp();
}

void outo(){
  printf("%lld\n",dp[n]);
}

int main(){
  int T;
  scanf("%d",&T);
  for (;T--;){
    into();
	work();
