ll N, A, B, C, D;
map <ll, ll> MP;

ll Solve(ll num){
  if (num <= 0) return 0;
  if (num == 1) return MP[num] = D;
  if (MP[num] > 0) return MP[num];

  ll ans = INF;
  for (ll i = -1; i <= 5; i++){
    ll now = num - i;
    if (now < 0) continue;
    if (now % 2 == 0){
      ans = min(ans, Solve(now / 2) + A + abs(i) * D);
      ll Lim = (INF - Solve(now / 2)) / D;
      ll deg = abs(now / 2 - num);
      if (deg <= Lim){
        ans = min(ans, Solve(now / 2) + deg * D);
      }
    }
    if (now % 3 == 0){
      ans = min(ans, Solve(now / 3) + B + abs(i) * D);
      ll Lim = (INF - Solve(now / 3)) / D;
      ll deg = abs(now / 3 - num);
      if (deg <= Lim){
        ans = min(ans, Solve(now / 3) + deg * D);
      }
    }
    if (now % 5 == 0){
      ans = min(ans, Solve(now / 5) + C + abs(i) * D);
      ll Lim = (INF - Solve(now / 5)) / D;
      ll deg = abs(now / 5 - num);
      if (deg <= Lim){
        ans = min(ans, Solve(now / 5) + deg * D);
      }
    }
    if (MP[now] > 0) ans = min(ans, MP[now] + abs(i) * D);
  }
  return MP[num] = ans;
}

int Ans(){
  MP = {};
  cin >> N >> A >> B >> C >> D;
  MP[1] = D;
  cout << Solve(N) << endl;
  return 0;
}

int main(){
  int T; cin >> T;
  for (int i = 0; i < T; i++) Ans();
  return 0;
}

