    } else if (pre == 2) {
        foo = min(foo, solve(u + 1, pre + 1) + d);
        foo = min(foo, solve(u - 1, pre + 1) + d);
        if (u % 3 == 0) foo = min(foo, solve(u / 3, 0) + b);
        if (u % 5 == 0) foo = min(foo, solve(u / 5, 0) + c);
    } else if (pre == 3) {
        foo = min(foo, solve(u + 1, pre + 1) + d);
        foo = min(foo, solve(u - 1, pre + 1) + d);
        if (u % 5 == 0) foo = min(foo, solve(u / 5, 0) + c);
    } else if (pre == 4) {
        if (u % 5 == 0) foo = min(foo, solve(u / 5, 0) + c);
    }
    return mp[pre][u] = foo;
