using namespace std;
using ll = long long;
using ld = long double;
const ll inf = 1000000000000000008;
ll N, A, B, C, D;
vector<ll> mul = {2, 3, 5};

unordered_map<ll, ll> Map;

ll calc(ll n) {
	if(n==0ll) return 0ll;
	if(n==1ll) return D;
	if(Map.count(n)) return Map[n];

	ll ret = inf;
	if(n<ret/D) ret = n*D;
	for(auto x:mul) {
		ll ex;
		if(x==2) ex = A;
		else if(x==3) ex =B;
		else ex = C;
		if(n%x==0) ret = min(ret, calc(n/x)+ex);
		else {
			ll up = (n/x+1)*x;
			ll down = (n/x)*x;
			ret = min(ret, calc(down/x)+D*(n-down)+ex);
			ret = min(ret, calc(up/x)+D*(up-n)+ex);
		}
	}
	return Map[n] = ret;
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	ll tc; cin>>tc;
	while(tc--) {
		cin>>N>>A>>B>>C>>D;
		cout << calc(N) << '\n';
		Map.clear();
	}
	return 0;
}

