  }
  res = min(res, tmp + dfs(id, l));
  if (n % 2LL != 0) {
    r = l + 1LL;
    if (n > 1e10) {
      tmp = abs(n - 2LL * r) * d + a;
    } else {
      tmp = min((n - r) * d, abs(n - 2LL * r) * d + a);
    }
    res = min(res, tmp + dfs(id, r));
  }
  ///////////////3
  if (n >= 3LL) {
    l = n / 3LL;
    if (n > 1e10) {
      tmp = abs(n - 3LL * l) * d + b;
    } else {
      tmp = min((n - l) * d, (n - 3LL * l) * d + b);
