      } else {
        tmp = min((n - r) * d, abs(n - 3LL * r) * d + b);
      }
      res = min(res, tmp + dfs(id, r));
    }
  }
  ///////////////5
  if (n >= 5LL) {
    l = n / 5LL;
    if (n > 1e10) {
      tmp = abs(n - 5LL * l) * d + c;
    } else {
      tmp = min((n - l) * d, (n - 5LL * l) * d + c);
    }
