        tmp = abs(n - 5LL * r) * d + c;
      } else {
        tmp = min((n - r) * d, abs(n - 5LL * r) * d + c);
      }

      res = min(res, tmp + dfs(id, r));
    }
  }
  mp[n] = res;
  // cout << n << " " << res << endl;
  return mp[n] = res;
}
