void solve(ll X){
  if(X<2) return;
  if(D<=(INF-mp[X])/(X-1)){
    if(mp.find(1)==mp.end()) mp[1]=INF;
    mp[1]=min(mp[1],(X-1)*D+mp[X]);
  }
  int mo=X%2;
  if(mp.find(X/2)==mp.end()) mp[X/2]=INF;
  judge(X/2,mp[X]+A+D*mo);
  if(mo){
    ll Y=X+2-mo;
    if(mp.find(Y/2)==mp.end()) mp[Y/2]=INF;
    judge(Y/2,mp[X]+A+D);
  }

  if(mp.find(X/3)==mp.end()) mp[X/3]=INF;
  mo=X%3;
  judge(X/3,mp[X]+B+D*mo);
  if(mo){
    ll Y=X+3-mo;
    if(mp.find(Y/3)==mp.end()) mp[Y/3]=INF;
    judge(Y/3,mp[X]+B+D*(3-mo));
