  mo=X%5;
  if(mp.find(X/5)==mp.end()) mp[X/5]=INF;
  judge(X/5,mp[X]+C+D*mo);
  if(mo){
    ll Y=X+5-mo;
    if(mp.find(Y/5)==mp.end()) mp[Y/5]=INF;
    judge(Y/5,mp[X]+C+D*(5-mo));
  }
}

