int N,A,B,C,D;
map<int,int>dp;
int solve(int n){
	if( n == 0 ) return 0;
	if( n == 1 ) return D;
	if( dp.count(n) )return dp[n];
	if( __builtin_mul_overflow(n,D,&dp[n]) ){
		dp[n] = 1e18;
	}
	int x = (n/2)*2;
	int X = ((n+1)/2)*2;
	int y = (n/3)*3;
	int Y = ((n+2)/3)*3;
	int z = (n/5)*5;
	int Z = ((n+4)/5)*5;

	dp[n] = min( dp[n] , D * abs(x-n) + A + solve(x/2) );
	dp[n] = min( dp[n] , D * abs(X-n) + A + solve(X/2) );

	dp[n] = min( dp[n] , D * abs(y-n) + B + solve(y/3) );
	dp[n] = min( dp[n] , D * abs(Y-n) + B + solve(Y/3) );

	dp[n] = min( dp[n] , D * abs(z-n) + C + solve(z/5) );
	dp[n] = min( dp[n] , D * abs(Z-n) + C + solve(Z/5) );

	return dp[n];
}

