constexpr ll INF = 9223372036854775807LL;
ll N, A, B, C, D;
map<ll, ll> res;

ll _solve(ll n){
    // cout << "Called : _solve(" << n << ")" << endl;
    if (n < 0) return INF;
    if (n == 0)
        return res[0] = 0;
    else if (n == 1) res[1] = D;
    if (res[n] > 0) return res[n];
    ll tmp;
    if (n <= INF / D) tmp = n * D;
    else tmp = INF;
    const vector<int> lis = {2, 3, 5};
    for (auto op : lis){
        ll cost = (op == 2 ? A : op == 3 ? B : C);
        if (n % op == 0)
            tmp = min(tmp, cost + _solve(n / op));
        ll prv = (n - 1) / op * op;
        tmp = min(tmp, (n - prv) * D + cost + _solve(prv / op));
        prv += op;
        if (prv != n)
            tmp = min(tmp, (prv - n) * D + cost + _solve(prv / op));
    }
    return res[n] = tmp;
}

void solve(){
    res.clear();
    cin >> N >> A >> B >> C >> D;
    cout << _solve(N) << endl;
} 

int main(){
    int T; cin >> T;
    while (T--) solve();
    return 0;
}

