    else{
      Q.emplace(make_pair((n1+1)/2,n2+A+D));
      if(M[(n1+1)/2]==0) M[(n1+1)/2]=n2+A+D;
      else M[(n1+1)/2]=min(M[(n1+1)/2],n2+A+D);
      Q.emplace(make_pair((n1-1)/2,n2+A+D));
      if(M[(n1-1)/2]) M[(n1-1)/2]=n2+A+D;
