    if(log10(C)>log10(((5+n1)/5)*D)) M[0]=min(M[0],n2+n1*D);
    else if(n1%5==0){
      Q.emplace(make_pair(n1/5,n2+C));
      if(M[n1/5]==0) M[n1/5]=n2+C;
      else M[n1/5]=min(M[n1/5],n2+C);
