ll solve(ll n, ll a, ll b, ll c, ll d){
	ll dp[60][36][26][2]={};
	dp[0][0][0][1]=2e18;
	ll ans=1e18;
	for(int i=0; i<60; i++){
		for(int j=0; j<36; j++){
			for(int k=0; k<26; k++){
				if(i==0 && j==0 && k==0) continue;
				ll p=1;
				bool dame=0;
				for(int l=0; l<i; l++){
					if(p>2e18/2){
						dame=1; break;
					}
					p*=2;
				}
				if(dame) continue;
				for(int l=0; l<j; l++){
					if(p>2e18/3){
						dame=1; break;
					}
					p*=3;
				}
				if(dame) continue;
				for(int l=0; l<k; l++){
					if(p>2e18/5){
						dame=1; break;
					}
					p*=5;
				}
				if(dame) continue;
				ll r=n%p, r1=n%(p/2);
				dp[i][j][k][0]=2e18, dp[i][j][k][1]=2e18;
				if(i){
					dp[i][j][k][0]=min(dp[i][j][k][0], dp[i-1][j][k][0]+abs(r-r1)/(p/2));
					dp[i][j][k][0]=min(dp[i][j][k][0], dp[i-1][j][k][1]+abs(r+p/2-r1)/(p/2));
					dp[i][j][k][1]=min(dp[i][j][k][1], dp[i-1][j][k][0]+abs(p-r+r1)/(p/2));
					dp[i][j][k][1]=min(dp[i][j][k][1], dp[i-1][j][k][1]+abs(p-r-p/2+r1)/(p/2));
				}
				if(j){
					r1=n%(p/3);
					dp[i][j][k][0]=min(dp[i][j][k][0], dp[i][j-1][k][0]+abs(r-r1)/(p/3));
					dp[i][j][k][0]=min(dp[i][j][k][0], dp[i][j-1][k][1]+abs(r+p/3-r1)/(p/3));
					dp[i][j][k][1]=min(dp[i][j][k][1], dp[i][j-1][k][0]+abs(p-r+r1)/(p/3));
					dp[i][j][k][1]=min(dp[i][j][k][1], dp[i][j-1][k][1]+abs(p-r-p/3+r1)/(p/3));
				}
				if(k){
					r1=n%(p/5);
					dp[i][j][k][0]=min(dp[i][j][k][0], dp[i][j][k-1][0]+abs(r-r1)/(p/5));
					dp[i][j][k][0]=min(dp[i][j][k][0], dp[i][j][k-1][1]+abs(r+p/5-r1)/(p/5));
					dp[i][j][k][1]=min(dp[i][j][k][1], dp[i][j][k-1][0]+abs(p-r+r1)/(p/5));
					dp[i][j][k][1]=min(dp[i][j][k][1], dp[i][j][k-1][1]+abs(p-r-p/5+r1)/(p/5));
				}
				if(((n-r)/p+dp[i][j][k][0])<(ll)(2e18)/d) ans=min(ans, ((n-r)/p+dp[i][j][k][0])*d+a*i+b*j+c*k);
				if(((n+p-r)/p+dp[i][j][k][1])<(ll)(2e18)/d) ans=min(ans, ((n+p-r)/p+dp[i][j][k][1])*d+a*i+b*j+c*k);

			}
		}
	}
	return ans;
}
