using namespace std;
using ll = long long;
const ll oo = 4e18;

ll solve(ll n, int a, int b, int c, int d) {
	map<ll, ll> dp;
	auto push = [&dp](ll u, ll dt) {
		if(dt > oo) return;
		auto it = dp.find(u);
		if(it == dp.end()) dp[u] = dt;
		else it->second = min(it->second, dt);
	};
	push(n, 0);
	while(prev(dp.end())->first != 1) {
		ll u, dt;
		tie(u, dt) = *prev(dp.end());
		dp.erase(prev(dp.end()));
// 		printf(".. dist[%lld] = %lld\n", u, dt);
		ll t2 = (2 - u % 2) % 2;
		ll t3 = (3 - u % 3) % 3;
		ll t5 = (5 - u % 5) % 5;
		ll v2 = (u + t2) / 2;
		ll v3 = (u + t3) / 3;
		ll v5 = (u + t5) / 5;
		push(v2, t2 * d + a + dt);
		push(v3, t3 * d + b + dt);
		push(v5, t5 * d + c + dt);

		if((u - v2) < oo / d)
			push(v2, (u - v2) * d + dt);
		if((u - v3) < oo / d)
			push(v3, (u - v3) * d + dt);
		if((u - v5) < oo / d)
			push(v5, (u - v5) * d + dt);

		push((u - u % 2) / 2, u % 2 * d + a + dt);
		push((u - u % 3) / 3, u % 3 * d + b + dt);
		push((u - u % 5) / 5, u % 5 * d + c + dt);
	}
// 	cout << ".." << dp[1] << endl;
	push(0, dp[1] + d);
// 	assert(dp.size() == 1);
	return dp[0];
}

