const pii dxy[] = { {-1, 0}, {1, 0}, {0, 1}, {0, -1} };
const int mod = 1e9 + 7;
const int INF = 2e18;
const ld EPS = 1e-9;
const int NN = 1e5 + 2;

map<int, int> cache;

int up(int x, int k) {
	return x/k + (x%k > 0);
}

vi nums = {2, 3, 5};

vi costs(4);

int DP_recur(int x) {
	if(cache.count(x))
		return cache[x];
	int ans = INF;
	for(int i = 0; i < 3; i++) {
		int k = nums[i], add = costs[i];
		int v = x/k, v_ = up(x, k);
		if(v > 0) {
			int d = DP_recur(v);
			int a = INF;
			if(abs(v * k - x) < INF / costs[3])
				a = d + costs[3] * abs(v * k - x) + add;
			remin(ans, a);
			if(x - v < INF / costs[3])
				remin(ans, (x - v) * costs[3] + d);
		}
		int d = DP_recur(v_);
		if(abs(v_ * k - x) < INF / costs[3])
			remin(ans, d + costs[3] * abs(v_ * k - x) + add);
		if(x - v_ < INF / costs[3])
			remin(ans, d + costs[3] * (x - v_));
	}

	// cout << x << el;
	return cache[x] = ans;
}

