long long int n, a, b, c, d;
unordered_map<int, long long int> um;

void update_res(long long int ret, long long int& res) {
    if (res == -1 || res > ret) res = ret;
}

long long int f(long long int m) {
    if (m == 0) return 0;
    if (um.find(m) != um.end()) {
        return um[m];
    }
    long long int res = -1;
    long long int mm = m;
    while (mm % 2 != 0) {
        mm++;
    }
    if (mm >= 0) update_res(f(mm / 2) + a + (mm - m) * d, res);
    if (mm > 0 && a / (mm / 2) >= d) update_res(f(mm / 2) + mm / 2 * d + (mm - m) * d, res);
    mm = m;
    while (mm % 2 != 0) {
        mm--;
    }
    if (mm >= 0) update_res(f(mm / 2) + a + (m - mm) * d, res);
    if (mm > 0 && a / (mm / 2) >= d) update_res(f(mm / 2) + mm / 2 * d + (m - mm) * d, res);

    mm = m;
    while (mm % 3 != 0) {
        mm++;
    }
    if (mm >= 0) update_res(f(mm / 3) + b + (mm - m) * d, res);
    if (mm > 0 && b / (mm / 3 * 2) >= d) update_res(f(mm / 3) + min(b, mm / 3 * 2 * d) + (mm - m) * d, res);
    mm = m;
    while (mm % 3 != 0) {
        mm--;
    }
    if (mm >= 0) update_res(f(mm / 3) + b + (m - mm) * d, res);
    if (mm > 0 && b / (mm / 3 * 2) >= d) update_res(f(mm / 3) + min(b, mm / 3 * 2 * d) + (m - mm) * d, res);

    mm = m;
    while (mm % 5 != 0) {
        mm++;
    }
    if (mm >= 0) update_res(f(mm / 5) + c + (mm - m) * d, res);
    if (mm > 0 && c / (mm / 5 * 4) >= d) update_res(f(mm / 5) + min(c, mm / 5 * 4 * d) + (mm - m) * d, res);
    mm = m;
    while (mm % 5 != 0) {
        mm--;
    }
    if (mm >= 0) update_res(f(mm / 5) + c + (m - mm) * d, res);
    if (mm > 0 && c / (mm / 5 * 4) >= d) update_res(f(mm / 5) + min(c, mm / 5 * 4 * d) + (m - mm) * d, res);

    um[m] = res;
    return res;
}

int main() {
    int t;
    cin >> t;
    for (int i = 0; i < t; i++) {
        cin >> n >> a >> b >> c >> d;
        um.clear();
        um[0] = 0;
        um[1] = d;
        cout << f(n) << endl;
    }
}

