#include<bits/stdc++.h>
using namespace std;
using UL = unsigned int;
using ULL = unsigned long long;
using LL = long long;
#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {
public:

	void Solve() {
		UL T; cin >> T;
		while (T--) {
			ULL N; cin >> N;
			priority_queue<pair<ULL, ULL>, vector<pair<ULL, ULL>>, greater<pair<ULL, ULL>>> Q;
			set<ULL> S;
			Q.push({ 0, N });
			ULL A, B, C, D; cin >> A >> B >> C >> D;
			ULL ans;
			while (Q.size()) {
				ULL p = Q.top().second;
				ULL d = Q.top().first;
				Q.pop();
				if (S.count(p)) continue;
				S.insert(p);
				if (p == 0) { ans = d; break; }
				switch (p % 2) {
				case 0:
					Q.push({ d + A, p / 2 }); break;
				case 1:
					Q.push({ d + A + D, p / 2 });
					Q.push({ d + A + D, (p + 1) / 2 }); break;
				}
				switch (p % 3) {
				case 0: Q.push({ d + B, p / 3 }); break;
				case 1: Q.push({ d + B + D, p / 3 }); break;
				case 2: Q.push({ d + B + D, p / 3 + 1 }); break;
				}
				switch (p % 5) {
				case 0: Q.push({ d + C, p / 5 }); break;
				case 1: Q.push({ d + C + D, p / 5 }); break;
				case 2: Q.push({ d + C + D + D, p / 5 }); break;
				case 3: Q.push({ d + C + D + D, p / 5 + 1 }); break;
				case 4: Q.push({ d + C + D, p / 5 + 1 }); break;
				}
				if ((ULL)1e18 / p > D) Q.push({ d + D * p, 0 });
			}
			cout << ans << endl;
		}
	}
};

int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}

