P get(ll n, ll g) {
    if (n % g == 0)
        return P(n, -1);
    else {
        ll u1 = n / g * g;
        ll u2 = n / g * g + g;
        if (n - u1 == u2 - n) {
            return P(u1, u2);
        } else if (n - u1 < u2 - n) {
            return P(u1, -1);
        } else {
            return P(-1, u2);
        }
    }
}

