    if (n == 0) return 0;
    if (memo.count(n)) return memo[n];

    ll &res = memo[n];
    res = INF;
    if (n <= INF/c[3]) res = n*c[3];
    forn(i,3) {
        int m = ms[i];
        int d = n%m;
        res = min(res, go((n-d)/m) + c[i] + d*c[3]);
        res = min(res, go((n+m-d)/m) + c[i] + (m-d)*c[3]);
    }
    return res;
}

