#include <bits/stdc++.h>
using namespace std;

const double INF = 2e40;
const int M = 37;

void solve() {
    int64_t N;
    double A, B, C, D;
    cin >> N >> A >> B >> C >> D;
    map<int64_t, double> mp;

    double ans = INF;
    auto dfs = [&](auto &&dfs, int64_t n, double v, int depth) -> void {
        if(depth > M or n < 0 or v > INF) return;
        double t = mp[n];
        if(t != 0 && t <= v) return;
        mp[n] = v;

        ans = min(ans, v + (double)n * D);

        if(n % 2 == 0) dfs(dfs, n / 2, v + A, depth + 1);
        if(n % 3 == 0) dfs(dfs, n / 3, v + B, depth + 1);
        if(n % 5 == 0) dfs(dfs, n / 5, v + C, depth + 1);

        for(int i : {1}) {
            dfs(dfs, n - i, v + D * i, depth + 1);
            dfs(dfs, n + i, v + D * i, depth + 1);
        }
    };
    dfs(dfs, N, 0, 0);

    for(int x : {2, 3, 5}) {
        int64_t s = 1LL;
        for(int i = 0; i < 30; ++i) {
            s *= x;
            if(s > N) dfs(dfs, s, fabs(N - s) * D, 0);
        }
    }

    if(mp[0]) ans = min(ans, mp[0]);
    cout << (int64_t)ans << '\n';
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int t; cin >> t;
    while(t--) solve();
    return 0;
}

