void solve() {
    li n, a, b, c, d;
    cin >> n >> a >> b >> c >> d;
    priority_queue<pair<li, li>> q;
    q.emplace(0, n);

    const li costs[3] = {a, b, c};

    __int128 nn = n, dd = d;
    __int128 mcost = nn * dd;

    map<li, li> memo;
    while (true) {
        auto t = q.top();
        q.pop();
        const li cost = -t.first;
        const li value = t.second;

        if (cost >= mcost) {
            cout << (li) mcost << '\n';
            return;
        }
        if (value == 0) {
            cout << cost << '\n';
            return;
        }
        if (value <= (li)(1e18) / d) {
            q.emplace(-(cost + d * value), 0);
        }
        for (int r = 0; r < 3; ++r) {
            const li rem = rems[r];
            const li rr = value % rem;
            {
                const li ncost = (cost + rr * d + costs[r]);
                const li nv = (value - rr) / rem;
                if (memo.find(nv) == memo.end() || memo[nv] > ncost) {
                    q.emplace(-ncost, nv);
                    memo[nv] = ncost;

                }
            }
            {
                const li ncost = (cost + d * (rem - rr) + costs[r]);
                const li nv = (value + rem - rr) / rem;
                if (memo.find(nv) == memo.end() || memo[nv] > ncost) {
                    q.emplace(-ncost, nv);
                    memo[nv] = ncost;

                }
            }
//            q.emplace(-(cost + (rem - rr) * d + costs[r]), (value + (rem - rr)) / rem);
        }
    }
}

