//mint
struct mint {
    ll x; // typedef long long ll;
    mint(ll x = 0) : x((x%MOD+MOD)%MOD) {}

    mint &operator+=(const mint a) {
        if((x += a.x) >= MOD) x -= MOD;
        return *this;
    }

    mint &operator-=(const mint a) {
        if((x += MOD-a.x) >= MOD) x -= MOD;
        return *this;
    }

    mint &operator*=(const mint a) {
        (x *= a.x) %= MOD;
        return *this;
    }

    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }

    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }

    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }

    mint pow(ll t) const {
        if(!t) return 1;
        mint a = pow(t>>1);
        a *= a;
        if(t & 1) a *= *this;
        return a;
    }

    // for prime MOD
    mint inv() const {
        return pow(MOD-2);
    }

    mint &operator/=(const mint a) {
        return (*this) *= a.inv();
    }

    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }
};

typedef vector<mint> Vmint;

struct combination {
    vector<mint> fact, ifact;

    combination(int n) : fact(n+1), ifact(n+1) {
        assert(n < MOD);
        fact[0] = 1;
        for(int i = 1; i <= n; ++i) fact[i] = fact[i-1]*i;
        ifact[n] = fact[n].inv();
        for(int i = n; i >= 1; --i) ifact[i-1] = ifact[i]*i;
    }

    mint operator()(int n, int k) {
        if(k < 0 || k > n) return 0;
        return fact[n]*ifact[k]*ifact[n-k];
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout<<std::setprecision(10);

    ll T;
    cin>>T;
    while (T--) {
        ll n, a, b, c, d;
        cin>>n>>a>>b>>c>>d;

        map<ll, ll> memo;
        auto dfs = [&](auto dfs, ll x)->ll {
            if(memo.count(x) > 0) {
                return memo[x];
            }
            if(x == 0) {
                return memo[x] = 0;
            }
            if(x == 1) {
                return memo[x] = d;
            }

            ll res = INF;
            if(x < 1e18/d) res = x*d;

            ll da = x%2;
            ll db = x%3;
            ll dc = x%5;

            ll c1 = (x-dc+5)/5;
            ll c2 = (x-dc)/5;

            if(dc > 0) {
                chmin(res, (5-dc)*d + c +dfs(dfs, c1));
            }
            chmin(res, dc*d + c +dfs(dfs, c2));

            ll b1 = (x-db+3)/3;
            ll b2 = (x-db)/3;

            if(db > 0) {
                chmin(res, (3-db)*d + b + dfs(dfs, b1));
            }
            chmin(res, db*d + b + dfs(dfs, b2));

            ll a1 = (x-da+2)/2;
            ll a2 = (x-da)/2;

            if(da > 0) {
                chmin(res, (2-da)*d + a + dfs(dfs, a1));
            }
            chmin(res, da*d + a + dfs(dfs, a2));

            return memo[x] = res;
        };

        out(dfs(dfs, n));

    }
    return 0;
}

