using namespace std;

typedef long long ll;

ll A, B, C, D;
unordered_map<ll, ll> dp;
const ll MAXN = 1e18;

ll dfs(ll n)
{
    if (n <= 0) return 0;
    if (n == 1) return D;
    // メモ済みならそのまま返す
    if (dp[n] > 0)
    {
        return dp[n];
    }

    ll res = MAXN;
    if (n < res / D)
    {
        res = n * D;
    }
    ll minus, plus;
    if (n % 2 == 0)
    {
        // そのまま割る
        res = min(res, dfs(n / 2) + A);
    }
    else
    {
        // 引いて2で割る
        minus = n % 2;
        res = min(res, dfs((n - minus) / 2) + A + minus * D);
        // 足して2で割る
        plus = 2 - n % 2;
        res = min(res, dfs((n + plus) / 2) + A + plus * D);
    }

    if (n % 3 == 0)
    {
        // そのまま割る
        res = min(res, dfs(n / 3) + B);
    }
    else
    {
        // 引いて3で割る
        minus = n % 3;
        res = min(res, dfs((n - minus) / 3) + B + minus * D);
        // 足して3で割る
        plus = 3 - n % 3;
        res = min(res, dfs((n + plus) / 3) + B + plus * D);
    }
    if (n % 5 == 0)
    {
        // そのまま割る
        res = min(res, dfs(n / 5) + C);
    }
    else
    {
        // 引いて5で割る
        minus = n % 5;
        res = min(res, dfs((n - minus) / 5) + C + minus * D);
        // 足して5で割る
        plus = 5 - n % 5;
        res = min(res, dfs((n + plus) / 5) + C + plus * D);
    }

    // メモする
    dp[n] = res;

    return res;
}

int main()
{
    ll T;
