long long getf(long long n)
{
	if (f[n]!=0) return f[n];
	long long ans=1000000000000000000ll;
	if (ans/D>=n) ans=n*D;
	if (!(n&1)) ans=min(ans,getf(n/2)+A); else
	ans=min(ans,min(getf(n/2),getf(n/2+1))+A+D);
	if (n%3<=1&&n>=3) ans=min(ans,getf(n/3)+D*(n%3)+B);
	else ans=min(ans,getf(n/3+1)+D+B);
	if (n%5<=2&&n>=5) ans=min(ans,getf(n/5)+D*(n%5)+C);
	else ans=min(ans,getf(n/5+1)+D*(5-n%5)+C);
	return f[n]=ans;
}

