vector<LL> Div(LL n) {
    vector<LL> ret;
    for(LL i = 1; i * i <= n; ++i) {
        if(n % i == 0) {
            ret.pb(i);
            if(i * i != n) ret.pb(n / i);
        }
    }
    sort(all(ret));
    return ret;
}

LL N, A, B, C, D;
int ddig;
LL res, t;
map<LL, LL> mp;

int Dig(LL num) {
    int dig = 0;
    while(num > 0) {
        num /= 10;
        ++dig;
    }

    return dig;
}

void dfs(LL n, LL cost) {
    if(n == 1) {
        if(cost == -1) cost = 0;
        res = min(res, cost + D);
        return;
    }
    if(res <= cost || (mp[n] != 0 && mp[n] <= cost)) return;
    mp[n] = cost;
    if(cost == -1) cost = 0;

    for(LL i = max(2ll, n - 4); i <= n + 4; ++i) {
        if(i % 5 == 0) {
            t = LINF;
            if(Dig(i - (i / 5)) + ddig < 10) t = (i - i / 5) * D;
            dfs(i / 5, cost + min(C, t) + D * llabs(i - n));
        }
    }
    for(LL i = max(2ll, n - 2); i <= n + 2; ++i) {
        if(i % 3 == 0) {
            t = LINF;
            if(Dig(i - (i / 3)) + ddig < 10) t = (i - i / 3) * D;
            dfs(i / 3, cost + min(B, t) + D * llabs(i - n));
        }
    }
    for(LL i = max(2ll, n - 1); i <= n + 1; ++i) {
        if(i % 2 == 0) {
            t = LINF;
            if(Dig(i - (i / 2)) + ddig < 10) t = (i - i / 2) * D;
            dfs(i / 2, cost + min(A, t) + D * llabs(i - n));
        }
    }

    if(Dig(n) + ddig < 16) res = min(res, cost + n * D);

    return;
}

void solve() {
    cin >> N >> A >> B >> C >> D;

    mp.clear();
    res = LINF;
    ddig = Dig(D);
    dfs(N, -1);

    cout << res << endl;
    return;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int T;
    cin >> T;
    while(T--) {
        solve();
    }

    return 0;
}

