typedef long long ll;

ll a, b, c, d;
map<ll, ll> ma[11];

ll f(ll n, int i1){
    if (ma[i1][n]) return ma[i1][n];
    ll pi=1e18;
    if (n<=1e9){
        pi=min(n*d, pi);
    }
    if (n==1){
        ma[i1][1]=d;
        return d;
    }
    for (ll i=0; i<=5; ++i){
        if ((n+i)%2==0 && ((n+i)/2)<n){
            pi=min(pi, f((n+i)/2, i1)+a+i*d);
        }
        if ((n+i)%3==0 && ((n+i)/3)<n){
            pi=min(pi, f((n+i)/3, i1)+b+i*d);
        }
        if ((n+i)%5==0 && ((n+i)/5)<n){
            pi=min(pi, f((n+i)/5, i1)+c+i*d);
        }
    }
    for (ll i=-1; i>=-5; --i){
        if ((n+i)>=1){
            if ((n+i)%2==0){
                pi=min(pi, f((n+i)/2,i1)+a-i*d);
            }
            if ((n+i)%3==0){
                pi=min(pi, f((n+i)/3, i1)+b-i*d);
            }
            if ((n+i)%5==0){
                pi=min(pi, f((n+i)/5, i1)+c-i*d);
            }
        }
    }
    ma[i1][n]=pi;
    return pi;
}

