map<LL, LL> mp;
LL chk(LL x) {
	if (x == 0) return 0;
	if (mp.count(x)) return mp[x];

	if (x == 1) return mp[x] = d;
	LL ans = 1e18;
	if (x <= (ans + d - 1) / d) ans = min(ans, x * d);


	for (LL i = max(x - 4, 0LL); i <= x + 4; i ++) {
		if (i % 2 && i % 3 && i % 5) continue; 
		if (i % 2 == 0 && i / 2 < x) ans = min(ans, chk(i / 2) + a + abs(i - x) * d);
		if (i % 3 == 0 && i / 3 < x) ans = min(ans, chk(i / 3) + b + abs(i - x) * d);
		if (i % 5 == 0 && i / 5 < x) ans = min(ans, chk(i / 5) + c + abs(i - x) * d);

	}	
	return mp[x] = ans;

}
