		rep(i, cnt3) nw = mul(nw, 3);
		rep(i, cnt5) nw = mul(nw, 5);
		if (nw == INF) break;
		ll diff = abs(n - nw);
		vector <int> v;
		rep(i, cnt5) v.pb(5);
		rep(i, cnt3) v.pb(3);
