long long power(long long a, long long b, long long m = mod) {
    if(b < 0) {
        return power(power(a, -b), mod-2);
    }
    long long x = 1;
    while(b) {
        if(b & 1) {
            x = 1ll * x * a % m;
        }
        a = 1ll * a * a % m;
        b /= 2;
    }
    return x;
}
const int INT_INF = 1e9+9;
const ll LL_INF = 2e18;
const int N = 3e5+9;
ll add_lim(ll x, ll y) {
    return min(LL_INF, x + y);
}
ll mul_lim(ll x, ll y) {
    if(x == 0) return 0;
    if (LL_INF / x < y) return LL_INF;
    return min(LL_INF, x * y);
}
const ll nums[3] = {2,3,5};
ll c[3], d;
map<ll, ll> dp;
ll solve(ll n) {
    if(n < 0) return LL_INF;
    if(n == 0) return 0;
    if(dp.count(n)) return dp[n];
    ll &ret = dp[n];
    ret = LL_INF;
    for(int i = 0; i < 3; i++) {
        ll k = nums[i];
        ret = min(ret, add_lim(solve(n/k), mul_lim(n-n/k, d)));
        ll t = (n+k-1) / k;
        ret = min(ret, add_lim(solve(t), mul_lim(n-t, d)));
        ll u = add_lim(mul_lim(n - n/k * k, d), c[i]);
        ret = min(ret, add_lim(solve(n / k), u));
        u = add_lim(mul_lim(t * k - n, d), c[i]);
        ret = min(ret, add_lim(solve(t), u));
    }
    return ret;
}
