#include <bits/stdc++.h>
using namespace std;
using ll=long long;
using Graph=vector<vector<int>>;
#define INF 1000000000000000000
#define MOD 1000000007

ll dfs(ll N,ll A,ll B,ll C,ll D,map<ll,ll> &m){
  if(N==1){
    return D;
  }
  if(N==2){
    return min(2*D,D+A);
  }
  if(N==3){
    return min({3*D,2*D+A,D+B});
  }
  if(N==4){
    return min({4*D,D+2*A,2*D+B,2*D+C});
  }
  if(N==5){
    return min({5*D,2*D+2*A,4*D+A,2*D+A+B,3*D+B,D+C});
  }
  if(m[N]>0){
    return m[N];
  }
  ll ret=dfs(N/2,A,B,C,D,m)+A+(N%2)*D;
  ret=min(ret,dfs((N-1)/2+1,A,B,C,D,m)+A+(N%2)*D);
  ret=min(ret,dfs(N/3,A,B,C,D,m)+B+(N%3)*D);
  ret=min(ret,dfs((N-1)/3+1,A,B,C,D,m)+B+(3-N%3)%3*D);
  ret=min(ret,dfs(N/5,A,B,C,D,m)+C+(N%5)*D);
  ret=min(ret,dfs((N-1)/5+1,A,B,C,D,m)+C+(5-N%5)%5*D);
  if(N<8000000000){
    ret=min(ret,N*D);
  }
  return m[N]=ret;
}

ll solve(ll N,ll A,ll B,ll C,ll D){
  map<ll,ll> m;
  return dfs(N,A,B,C,D,m);
}

int main(){
  int T;
