long long N, A, B, C, D; 
map<long long, long long> dp; 
long long F(long long n){
	if(n == 1) return dp[1] = D; 
	if(n == 0) return dp[0] = 0; 
	if(dp[n]) return dp[n]; 
	long long c1, c2, c3; 
	long long c4 = 1e18; 
	if(n % 2 == 0) c1 = F(n/2) + A; 
	else c1 = min(F((n+1)/2), F((n-1)/2)) + A + D;
	if(n % 3 == 0) c2 = F(n/3) + B; 
	else if(n % 3 == 1) c2 = min(F((n-1)/3) + B + D, F((n+2)/3) + B + D * 2); 
	else c2 = min(F((n-2)/3) + B + D * 2, F((n+1)/3) + B + D); 
	if(n % 5 == 0) c3 = F(n/5) + C; 
	else if(n % 5 == 1) c3 = min(F((n-1)/5) + C + D, F((n+4)/5) + C + D * 4);  
	else if(n % 5 == 2) c3 = min(F((n-2)/5) + C + D * 2, F((n+3)/5) + C + D * 3); 
	else if(n % 5 == 3) c3 = min(F((n-3)/5) + C + D * 3, F((n+2)/5) + C + D * 2); 
	else if(n % 5 == 4) c3 = min(F((n-4)/5) + C + D * 4, F((n+1)/5) + C + D); 
	if(n <= (long long) 1000000000000000 / D) c4 = D * n; 
	return dp[n] = min({c1, c2, c3, c4}); 
}
