inline s128 solve(s64 n)
{
	if (f.find(n) != f.end())
		return f[n]; 

	s128 res = (s128)d * n; 

	if (n >= 2)
		tense(res, solve(n / 2) + (n % 2) * d + a); 
	if (n % 2)
		tense(res, solve(n / 2 + 1) + d + a); 

	if (n >= 3)
		tense(res, solve(n / 3) + (n % 3) * d + b); 
	if (n % 3)
		tense(res, solve(n / 3 + 1) + (3 - n % 3) * d + b); 

	if (n >= 5)
		tense(res, solve(n / 5) + (n % 5) * d + c); 
	if (n % 5)
		tense(res, solve(n / 5 + 1) + (5 - n % 5) * d + c); 

	// std::cout << n << ':' << (s64)res << '\n'; 

	return f[n] = res; 
}

