#include <bits/stdc++.h>
using int_t = std::uint64_t;

inline std::unordered_map<std::int64_t, int_t> memo{};

int_t solve(std::int64_t N, int_t A, int_t B, int_t C, int_t D)
{
    if(N == 0)
    {
        return 0;
    }
    if(N == 1)
    {
        return D;
    }


    if(memo.count(N) != 0)
    {
        return memo.at(N);
    }

    const auto Nmod2 = N % 2;
    const auto Nmod3 = N % 3;
    const auto Nmod5 = N % 5;

    int_t tok2;


    if(Nmod2 == 0)
    {
        tok2 = std::min(A, D * (N / 2)) + solve(N / 2, A, B, C, D);
    }
    else
    {
        const int_t tok2p = D *      Nmod2  + std::min(A, D * (N-Nmod2  )/2) + solve((N - Nmod2)     / 2, A, B, C, D);
        const int_t tok2n = D * (2 - Nmod2) + std::min(A, D * (N-Nmod2+2)/2) + solve((N - Nmod2 + 2) / 2, A, B, C, D);
        tok2 = std::min(tok2p, tok2n);
    }

    int_t tok3;

    if(Nmod3 == 0)
    {
        tok3 = std::min(B, D * (2 * N / 3)) + solve(N / 3, A, B, C, D);
    }
    else
    {
        const int_t tok3p = D *      Nmod3  + std::min(B, D * (N-(N-Nmod3  )/3)) + solve((N - Nmod3)     / 3, A, B, C, D);
        const int_t tok3n = D * (3 - Nmod3) + std::min(B, D * (N-(N-Nmod3+3)/3)) + solve((N - Nmod3 + 3) / 3, A, B, C, D);
        tok3 = std::min(tok3p, tok3n);
    }

    int_t tok5;
    if(Nmod5 == 0)
    {
        tok5 = std::min(C, D*N*4/5) + solve(N / 5, A, B, C, D);
    }
    else
    {
        const int_t tok5p = D *      Nmod5  + std::min(C, D * (N-(N-Nmod5  )/5)) + solve((N - Nmod5)     / 5, A, B, C, D);
        const int_t tok5n = D * (5 - Nmod5) + std::min(C, D * (N-(N-Nmod5+5)/5)) + solve((N - Nmod5 + 5) / 5, A, B, C, D);
        tok5 = std::min(tok5p, tok5n);
    }
    const auto score = std::min(std::min(tok2, tok3), tok5);
    memo[N] = score;
    return score;
}

int main()
{
    std::size_t T;
    std::cin >> T;

    for(std::size_t t=0; t<T; ++t)
    {
        memo.clear();
        std::size_t N, A, B, C, D;
        std::cin >> N >> A >> B >> C >> D;
        std::cout << solve(N, A, B, C, D) << std::endl;
    }
    return 0;
}

