map<int,int> mp;
int dfs(int x){
	if(x==0)return 0;
	int &res=mp[x];
	if(res)return res;
	res=x<=1.*LLONG_MAX/d?x*d:inf;
	if(x<=100)res=min(res,dfs(x-1)+d);
	if((x+2-1)/2<x)res=min(res,dfs((x+2-1)/2)+(2-x%2)%2*d+a);
	if((x+3-1)/3<x)res=min(res,dfs((x+3-1)/3)+(3-x%3)%3*d+b);
