        const ll cost = costs[i];
        const ll mul = muls[i];
        const ll above = ((n - 1 + mul) / mul) * mul;
        chmin(cand, (above - n) * D + cost + solve(above / mul, A, B, C, D, memo));
        const ll below = (n / mul) * mul;
        chmin(cand, (n - below) * D + cost + solve(below / mul, A, B, C, D, memo));
    }

    // it might be better to decrease one by one if n <= 1e9
    if (n <= 1000LL * 1000LL * 1000LL) {
        chmin(cand, D * n);
    }

    memo[n] = cand;
    return cand;
}

int main(void) {
    int T;
    cin >> T;
    for (int i = 0; i < T; i++) {
        ll N, A, B, C, D;
        cin >> N >> A >> B >> C >> D;
        map<ll, ll> memo;
        memo[0] = 0LL;
        memo[1] = D;
        cout << solve(N, A, B, C, D, memo) << endl;
    }
    return 0;
}

