using Bigint = __int128;


Bigint Calc(long long n, long long a, long long b, long long c, long long d, map<long long, Bigint>& memoization) {
  if (n == 0) return 0;
  if (memoization.count(n)) return memoization[n];
  Bigint result = (Bigint) d * n;
  for (int i = -4; i <= 4; ++i) {
    if (n + i < 0) continue;
    if ((n + i) % 2 == 0 && (n + i) / 2 < n) result = min(result, Calc((n + i) / 2, a, b, c, d, memoization) + d * abs(i) + a);
    if ((n + i) % 3 == 0 && (n + i) / 3 < n) result = min(result, Calc((n + i) / 3, a, b, c, d, memoization) + d * abs(i) + b);
    if ((n + i) % 5 == 0 && (n + i) / 5 < n) result = min(result, Calc((n + i) / 5, a, b, c, d, memoization) + d * abs(i) + c);
  }

  return memoization[n] = result;
}

