int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);
  ll t;
  cin >> t;
  // 何倍にできるか
  ll rate[] = {2, 3, 5};

  rep(_, t){
    ll n, d;
    // rate倍にするときのコスト
    vector<ll> c(3);
    cin >> n >> c[0] >> c[1] >> c[2] >> d;

    // ダイクストラ用のグラフ．頂点数は多めに
    Graph g(500000);
    // 値が頂点で何番に対応するかを保持するmap
    map<ll, ll> mp;
    mp[n] = 1;
    ll cnt = 2;
    // dp[i] = i番目から出るエッジをすべて張ったか
    vector<ll> dp(500000);
    // グラフを構築する再帰関数 n2はみてる値
    function<void(ll)> f = [&](ll n2){
      // n2が0になったら終わり
      if(n2 == 0){
        dp[n2] = 1;
        if(mp[n2] == 0){
          mp[n2] = cnt;
          cnt++;
        }
        return;
      }

      // rateで割る
      rep(i, 3){
        // 切り捨て
        ll tmp1 = (n2 / rate[i]) * rate[i];
        // 切り上げ
        ll tmp2 = ((n2+rate[i]-1) / rate[i]) * rate[i];
        // 次に見る値
        ll next1 = tmp1/rate[i];
        ll next2 = tmp2/rate[i];
        //値と頂点番号が対応していなかったら対応付ける
        if(mp[next1] == 0) {
          mp[next1] = cnt;
          cnt++;
        }
        if(mp[next2] == 0) {
          mp[next2] = cnt;
          cnt++;
        }

        if(dp[mp[n2]]) return;

        // グラフ構築
        g[mp[n2]].push_back({mp[next1], abs(tmp1-n2)*d+c[i]*(next1!=0)});
        f(next1);
        // 1 -> 5 -> 1 -> 5みたいなエッジのループをなくすための分岐
        if(n2 == next2) continue;
        g[mp[n2]].push_back({mp[next2], abs(tmp2-n2)*d+c[i]*(next2!=0)});
        f(next2);
      }
      dp[mp[n2]] = 1;
    };

    f(n);
    vector<ll> dist;
    vector<ll> prev;
    dijkstra(g, mp[n], dist, prev);
    cout << dist[mp[0]] << endl;
  }

}

