ll n,a,b,c,d,ans;

void roop(ll count,ll num){
  ll bed = abs(num-n);
  if(bed<1000000000){
    ans=min(ans,count+bed*d);
  }
  if(num>n) return;

  roop(count+a,num*2);
  roop(count+a+d,num*2+1);
  if(num!=1) roop(count+a+d,num*2-1);
  roop(count+b,  num*3);
  roop(count+b+d,num*3+1);
  roop(count+b+d,num*3-1);
  roop(count+c,num*5);
  roop(count+c+d ,num*5+1);
  roop(count+c+d ,num*5-1);
  double aa,bb,cc,dd;
  aa=num/a;
  bb=num/b;
  cc=num/c;
  dd=1/d;
  if(dd<aa && dd<bb && dd<cc) return;
  roop(count+d,num+1);
}

