    if (!x) return 0;
    if (m.count(x)) return m[x];
    ll res = LINF;
    if (LINF/d > x) res = x*d;
    auto f2 = [&](ll y) {
        if (y >= x) return LINF;
        return f(y);
    };
    {
        ll l = x/2*2, r = l+2;
        res = min(res, f2(l/2)+(x-1)*d);
        res = min(res, f2(r/2)+(r-x)*d);
