void c_fac(int x=pow(10,6)+10) { fac.resize(x,true); rep(i,x) fac[i] = i ? (fac[i-1]*i)%MOD : 1; }
ll inv(ll a, ll m=MOD) { ll b = m, x = 1, y = 0; while (b!=0) { int d = a/b; a -= b*d; swap(a,b); x -= y*d; swap(x,y); } return (x+m)%m; }
ll nck(ll n, ll k) { return fac[n]*inv(fac[k]*fac[n-k]%MOD)%MOD; }
ll gcd(ll a, ll b) { if (a<b) swap(a,b); return b==0 ? a : gcd(b, a%b); }
ll lcm(ll a, ll b) { return a/gcd(a,b)*b; }

ll A, B, C, D;
map<ll, ll> res;

ll dfs(ll N) {
  if (res.count(N)) return res[N];
  ll result = LLINF;

  if (N%2==0) result = min(result, dfs(N/2)+A);
  else if (N%2==1) result = min(result,min(dfs(N/2)+A+D, dfs(N/2+1)+A+D));

  if (N%3==0) result = min(result, dfs(N/3)+B);
  else if (N%3==1) result = min(result,dfs(N/3)+B+D);
  else if (N%3==2) result = min(result,dfs(N/3+1)+B+D);

  if (N%5==0) result = min(result, dfs(N/5)+C);
  else if (N%5==1) result = min(result,dfs(N/5)+C+D);
  else if (N%5==2) result = min(result,dfs(N/5)+C+D*2);
  else if (N%5==3) result = min(result,dfs(N/5+1)+C+D*2);
  else if (N%5==4) result = min(result,dfs(N/5+1)+C+D);

  if (N<=pow(2,63)/D) result = min(result,D*N);
  // cout << N << "->" << result << endl;
  return res[N] = result;

}

