LL dfs(LL n) {
	if (n == 0) return 0;
	if (n == 1) return D;
	if (dp.count(n)) return dp[n];

	dp[n] = (LL)inf * inf;
	if (dp[n] / D >= n)
		dp[n] = min(dp[n], n*D);

	LL lt, rt;
	lt = n / 2;
	rt = (n + 1) / 2;
	dp[n] = min(dp[n], dfs(lt) + A + (n - lt * 2)*D);
	dp[n] = min(dp[n], dfs(rt) + A + (rt * 2 - n)*D);

	lt = n / 3;
	rt = (n + 2) / 3;
	dp[n] = min(dp[n], dfs(lt) + B + (n - lt * 3)*D);
	dp[n] = min(dp[n], dfs(rt) + B + (rt * 3 - n)*D);

	lt = n / 5;
	rt = (n + 4) / 5;
	dp[n] = min(dp[n], dfs(lt) + C + (n - lt * 5)*D);
	dp[n] = min(dp[n], dfs(rt) + C + (rt * 5 - n)*D);
	return dp[n];
}
