        set<ll> used;
        priority_queue<array<ll, 2>> q;
        q.push(array<ll, 2>{-0, N});
        while(!q.empty()){
            auto v = q.top();
            if(v[1] == 1) break;
            q.pop();
            if(used.count(v[1])) continue;
            used.insert(v[1]);

            for(int i=0; i<3; i++){
