                auto Ndr = v[1] / r;
                auto Nr = v[1] % r;
                auto cNr = r - Nr;
                {
                    if(D * (r - 1) * Ndr < 0 || costs[i] < D * (r - 1) * Ndr){
                        q.push(array<ll, 2>{v[0] - D * Nr - costs[i], Ndr});
                    }else{
                        q.push(array<ll, 2>{v[0] - D * Nr - D * (r - 1) * Ndr, Ndr});
                    }
                }
                if(Nr > 0){
                    if(D * (r - 1) * Ndr < 0 || costs[i] + D * cNr < D * Nr + D * (r - 1) * Ndr + D){
                        q.push(array<ll, 2>{v[0] - D * cNr - costs[i], Ndr + 1});
                    }else{
                        q.push(array<ll, 2>{v[0] - D * Nr - D * (r - 1) * Ndr + D, Ndr + 1});
                    }
                }
            }
        }
        res.push_back(D - q.top()[0]);
