unordered_map<Int, Int> dist;

void solve(){
    Int n, a, b, c, d;
    dist.clear();
    cin >> n >> a >> b >> c >> d;
    priority_queue<P, vector<P>, greater<P>> pq;
    dist[n] = 0;
    pq.push(P(0,n));
    Int ans = LINF;
    while(!pq.empty()){
        P tmp = pq.top();pq.pop();
        Int from = tmp.second;
        if(dist[from] < tmp.first)continue;
        if((double)d * from < 1e18)
