        if((from+1) % 2 == 0)nxt.push_back({(from+1) / 2, a+d});
        if((from-1) % 2 == 0)nxt.push_back({(from-1) / 2, a+d});
        if(from % 3 == 0)nxt.push_back({from / 3, b});
        if((from+1) % 3 == 0)nxt.push_back({(from+1) / 3, b+d});
        if((from+2) % 3 == 0)nxt.push_back({(from+2) / 3, b+d+d});
        if((from-1) % 3 == 0)nxt.push_back({(from-1) / 3, b+d});
        if((from-2) % 3 == 0)nxt.push_back({(from-2) / 3, b+d+d});
        if(from % 5 == 0)nxt.push_back({from / 5, c});
        if((from+1) % 5 == 0)nxt.push_back({(from+1) / 5, c+d});
        if((from+2) % 5 == 0)nxt.push_back({(from+2) / 5, c+d+d});
        if((from+3) % 5 == 0)nxt.push_back({(from+3) / 5, c+d+d+d});
        if((from+4) % 5 == 0)nxt.push_back({(from+4) / 5, c+d+d+d+d});
        if((from-1) % 5 == 0)nxt.push_back({(from-1) / 5, c+d});
        if((from-2) % 5 == 0)nxt.push_back({(from-2) / 5, c+d+d});
        if((from-3) % 5 == 0)nxt.push_back({(from-3) / 5, c+d+d+d});
        if((from-4) % 5 == 0)nxt.push_back({(from-4) / 5, c+d+d+d+d});
        for(auto p:nxt){
            Int to = p.first;
