map<ll, ll> mp;

void dfs(ll n, ll tmp){
    // cout << n << ' ' << tmp << endl;
    if(mp.count(n) != 0 && mp[n] <= tmp) return;
    mp[n] = tmp;
    if(n == 0){
        ans = min(ans, tmp);
        return;
    }
    if(n < 5){
        ans = min(ans, tmp+D*(n));
    }
    double d = (double)(n)*(double)D;
    if((double) ans > (double)tmp+d) ans = tmp+(n)*D;

    for(ll i = 0; i < 5; i++){
        if((n+i)%5 == 0){
            dfs((n+i)/5, tmp+D*i+C);
            break;
        }
    }
    for(ll i = 1; i < 5; i++){
        if((n-i)%5 == 0){
            dfs((n-i)/5, tmp+D*i+C);
            break;
        }
    }
    // 3
    for(ll i = 0; i < 3; i++){
        if((n+i)%3 == 0){
            dfs((n+i)/3, tmp+D*i+B);
            break;
        }
    }
    for(ll i = 1; i < 3; i++){
        if((n-i)%3 == 0){
            dfs((n-i)/3, tmp+D*i+B);
            break;
        }
    }

    // 2
    for(ll i = 0; i < 2; i++){
        if((n+i)%2 == 0){
            dfs((n+i)/2, tmp+D*i+A);
            break;
        }
    }
    for(ll i = 1; i < 2; i++){
        if((n-i)%2 == 0){
            dfs((n-i)/2, tmp+D*i+A);
            break;
        }
    }
}

