std::string ll2bitstr(long long x)
{
    std::string ret;
    while (x)
    {
        ret += x % 2 + '0', x /= 2;
    }
    std::reverse(ret.begin(), ret.end());
    return ret;
}

__int128 solve2(lint x)
{
    string s = ll2bitstr(x);
    int N = s.length() + 1;

    vector<lint> dp0(N, 1e12);
    vector<lint> dpk(N, 1e12);
    vector<lint> dpyo(N, 1e12);
    dp0[0] = 0;
    dp0[1] = D + A * (s.length() - 1);
    dpyo[0] = D + A * s.length();
    REP(i, s.length())
    {
        if (s[i] == '0')
        {
            dp0[i + 1] = min(dp0[i], dpk[i]);
            dpyo[i + 1] = min({dp0[i] + D, dpk[i] + D});
        }
        else
        {
            if (i != 0) dp0[i + 1] = min({dp0[i] + D, dpk[i] + D, dpyo[i] + D});
            dpk[i + 1] = min(dpk[i], dpyo[i] + D);
        }
    }
    lint ret = min(dp0.back(), dpk.back());
    if (__int128(x) * D < ret) ret = x * D;
    // dbg(x);
    // dbg(s);
    // dbg(dp0);
    // dbg(dpk);
    // dbg(dpyo);
    // dbg(ret);
    return ret;
}
map<pair<lint, bool>, lint> mp;

__int128 rec(lint x, bool ok_add)
{
    if (x == 0) return 0;
    if (x == 1) return D;
    if (mp.count(make_pair(x, ok_add))) return mp[make_pair(x, ok_add)];

    __int128 ret = __int128(D) * x;

    if (x % 2)
    {
        if (ok_add) chmin(ret, rec(x / 2 + 1, false) + A);
        else chmin(ret, rec(x / 2, true) + A + D);
    }
    else
    {
        chmin(ret, rec(x / 2, false) + A);
    }

    int mod3 = x % 3;
    if (mod3 == 1 and ok_add)
    {
        chmin(ret, rec(x / 3, true) + B + D);
    }
    else if (mod3 <= 1)
    {
        chmin(ret, rec(x / 3, false) + B + D * mod3);
    }
    else
    {
        chmin(ret, rec(x / 3 + 1, false) + B + D * (3 - mod3 - ok_add));
    }
    int mod5 = x % 5;
    if (mod5 == 2 and ok_add)
    {
        chmin(ret, rec(x / 5, true) + C + D * mod5);
    }
    else if (mod5 <= 2)
    {
        chmin(ret, rec(x / 5, false) + C + D * mod5);
    }
    else
    {
        chmin(ret, rec(x / 5 + 1, false) + C + D * (5 - mod5 - ok_add));
    }

    mp[make_pair(x, ok_add)] = ret;
    return ret;
}

lint Sol()
{
    mp.clear();
    cin >> N >> A >> B >> C >> D;
    return rec(N, false);
}

