const ll LINF = LONG_MAX;

ll A, B, C, D;
map<ll, ll> mp;

void init() {
  mp.clear();
  mp[0] = 0;
  mp[1] = D;

  mp[2] = 2*D;
  chmin(mp[2], D+A);

  mp[3] = 3*D;
  chmin(mp[3], D+A+D);
  chmin(mp[3], D+B);

  mp[4] = 4*D;
  chmin(mp[4], A+mp[2]);
  chmin(mp[4], 2*A+D);
  chmin(mp[4], D+mp[3]);
  chmin(mp[4], D+C+D);
};

ll dfs(ll N) {
  if (Find(mp, N)) return mp[N];
  ll res = LINF;
  if (LINF/D > N) res = N * D;

  {
    ll n = (N/5);
    ll nn = ((N+4)/5);
    chmin(res, C+abs(N-n*5)*D+dfs(n));
    chmin(res, C+abs(N-nn*5)*D+dfs(nn));
  }

  {
    ll n = (N/3);
    ll nn = ((N+2)/3);
    chmin(res, B+abs(N-n*3)*D+dfs(n));
    chmin(res, B+abs(N-nn*3)*D+dfs(nn));
  }

  {
    ll n = (N/2);
    ll nn = ((N+1)/2);
    chmin(res, A+abs(N-n*2)*D+dfs(n));
    chmin(res, A+abs(N-nn*2)*D+dfs(nn));
  }

  return mp[N] = res;
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int T; cin >> T;
  while (T--) {
    ll N;
    cin >> N >> A >> B >> C >> D;
    init();
    cout << dfs(N) << endl;
  }

  return 0;
};

