long long f(long long n) {
	if (n < 2)
		return n * d;
	if (m[n])
		return m[n];
	long long rv;
	if (n % 2)
		rv = d + a + min(f(n / 2), f(n / 2 + 1));
	else
		rv = a + f(n / 2);
	if (n % 3 < 2)
		rv = min(rv, n % 3 * d + b + +f(n / 3));
	else
		rv = min(rv, d + b + +f(n / 3 + 1));
	if (n % 5 < 3)
		rv = min(rv, n % 5 * d + c + +f(n / 5));
	else
		rv = min(rv, (5 - n % 5) * d + c + +f(n / 5 + 1));

	if (rv / d >= n)
		rv = d * n;
	m[n] = rv;
	return rv;
}

