void push_el(priority_queue<tup, vector<tup>, decltype(compare)> &q, ll num, ll coin, vector<ll> &plus_minus) {
    auto itr = m.find(num);

    if (num < 0) return;
    if(m.find(0) != m.end() && coin >= m[0]) {
        return;
    }
    // cout << "stacked: " ;
    if(itr == m.end()|| m[num] > coin) {
        m[num] = coin;
        plus_minus.push_back(num);
       // cout << "stacked: " << num << "-" << coin << "-" << endl;;
        q.push(make_tuple( num , coin, plus_minus));
    }
}

