        // vector<ll> sorted_v({A,B,C,D});
        // sort(sorted_v.begin(), sorted_v.end());

        priority_queue<tup, vector<tup>, decltype(compare)> q {compare};

        ll min_coin = -1;
        ll min_coin_theory = min({D*N, 60*(A+D)});
        //cout << min_coin_theory << endl;
        q.push(make_tuple(N, 0, vector<ll>()));
        while(q.size() >= 1) {
            //cout << "***********************" << endl;
            tup el = q.top();q.pop();
            ll num = get<0>(el);
            ll coin = get<1>(el);
            vector<ll> plus_minus = get<2>(el);

            //cout << num << ":" << coin << ":" << endl;

            if(coin >= min_coin_theory + 1) continue;
            if(num == 0) {
                if(coin < 0) continue;
                if(min_coin < 0) min_coin = coin;
                else min_coin = min(coin, min_coin);
                continue;
