            if (num > 0 && 2e18 / num >= D )  push_el(q, 0, coin + num* D, plus_minus);
            if(num % 2 == 0) push_el(q, num / 2, min({coin + A}), plus_minus);
            if(num % 2 == 1 && num != 1) {
                push_el(q, (num - 1) / 2, min({coin + A + D}), plus_minus);
                push_el(q, (num + 1) / 2, min({coin + A + D}), plus_minus);
            }
            if(num % 3 == 0) push_el(q, num / 3, min({coin + B}), plus_minus);
