                push_el(q, (num + 2) / 3, min({coin + B + (2 * D)}), plus_minus);
            }
            if(num % 3 == 2 && num != 2) {
                push_el(q, (num - 2) / 3, min({coin + B + (2* D)}), plus_minus);
                push_el(q, (num + 1) / 3, min({coin + B +  D}), plus_minus);
            }
            if(num % 5 == 0) push_el(q, num / 5, min({coin + C}), plus_minus);
            if(num % 5 == 1 && num != 1) {
                push_el(q, (num - 1) / 5, min({coin + C + D}), plus_minus);
                push_el(q, (num + 4) / 5, min({coin + C + (4 * D)}), plus_minus);
            }
            if(num % 5 == 2 && num != 2) {
                push_el(q, (num - 2) / 5, min({coin + C + (2 * D)}), plus_minus);
                push_el(q, (num + 3) / 5, min({coin + C + (3 * D) }), plus_minus);
            }
            if(num % 5 == 3 && num != 3) {
                push_el(q, (num - 3) / 5, min({coin + C + (3 * D)}), plus_minus);
                push_el(q, (num + 2) / 5, min({coin + C + (2 * D) }), plus_minus);
            }
            if(num % 5 == 4 && num != 4) {
                push_el(q, (num - 4) / 5, min({coin + C + (4 * D) }), plus_minus);
                push_el(q, (num + 1) / 5, min({coin + C +  D}), plus_minus);
            }
        }
