typedef long long ll;

ll A, B, C, D;
map<ll, ll> dp;

ll calc_dp (ll x) {
  if (dp.count(x)) return dp[x];

  ll l2 = x - x % 2;
  ll l2a = D * (x - l2) + A + calc_dp(l2 / 2);
  ll ans = l2a;

  if (l2 != x) {
    ll h2 = l2 + 2;
    ll h2a = D * (h2 - x) + A + calc_dp(h2 / 2);
    ans = min(ans, h2a);
  }

  ll l3 = x - x % 3;
  ll l3a = D * (x - l3) + B + calc_dp(l3 / 3);
  ans = min(ans, l3a);

  if (l3 != x) {
    ll h3 = l3 + 3;
    ll h3a = D * (h3 - x) + B + calc_dp(h3 / 3);
    ans = min(ans, h3a);
  }

  ll l5 = x - x % 5;
  ll l5a = D * (x - l5) + C + calc_dp(l5 / 5);
  ans = min(ans, l5a);

  if (l5 != x) {
    ll h5 = l5 + 5;
    ll h5a = D * (h5 - x) + C + calc_dp(h5 / 5);
    ans = min(ans, h5a);
  }

  dp[x] = ans;

  return ans;
}

void solve () {
  dp.clear();
  dp[0] = 0;

  ll N;
  cin >> N >> A >> B >> C >> D;
  dp[1] = D;

  cout << calc_dp(N) << '\n';
}

