int main() {
	int T;
	ignore = scanf("%d", &T);
	while (T--) {
		long long n, a, b, c, d;
		ignore = scanf("%lld %lld %lld %lld %lld", &n, &a, &b, &c, &d);

		const int q[3] = {2, 3, 5};
		const long long p[3] = {a, b, c};

		long long k = min({a / d, b / (2 * d), c / (4 * d)}) + 1;

		map<long long, long long> dp;
		function<long long(long long)> calc = [&](long long x) {
			if (x <= k) return x * d;
			if (dp.count(x) == 1) return dp[x];

			long long res = INF;
			if (x <= INF / d) res = x * d;

			for (int i = 0; i < 3; i++) {
				long long cur = (x % q[i]) * d + p[i] + calc(x / q[i]);
				res = min(res, cur);

				cur = (q[i] - x % q[i]) % q[i] * d + p[i] + calc((x + q[i] - 1) / q[i]);
				res = min(res, cur);
			}

			return dp[x] = res;
		};

		printf("%lld\n", calc(n));
	}

	return 0;
