ll calc(map<ll,ll> &mp,ll n,ll a,ll b,ll c,ll d)
{
	ll tmp,m;
	ll ret=LLONG_MAX;
	if (ret/d>n) ret=d*n;

	if (n==0) return 0;
	if (n==1) return d;
	if (mp.count(n)) return mp[n];
	//cerr<<n<<" "<<a<<" "<<b<<" "<<c<<" "<<d<<endl;

	m=n%2;
	tmp=calc(mp,(n-m)/2,a,b,c,d)+a+d*m;if (tmp<ret)ret=tmp;
	if (m) tmp=calc(mp,(n+2-m)/2,a,b,c,d)+a+d*(2-m);if (tmp<ret)ret=tmp;

	m=n%3;
	tmp=calc(mp,(n-m)/3,a,b,c,d)+b+d*m;if (tmp<ret)ret=tmp;
	if (m) tmp=calc(mp,(n+3-m)/3,a,b,c,d)+b+d*(3-m);if (tmp<ret)ret=tmp;

	m=n%5;
	tmp=calc(mp,(n-m)/5,a,b,c,d)+c+d*m;if (tmp<ret)ret=tmp;
	if (m) tmp=calc(mp,(n+5-m)/5,a,b,c,d)+c+d*(5-m);if (tmp<ret)ret=tmp;

	//cerr<<"cacl("<<n<<")="<<ret<<endl;
	mp[n]=ret;
	return ret;
}


