    res = min(res, llabs(l2-N)*D + A + dp(l2/2));
    res = min(res, llabs(r2-N)*D + A + dp(r2/2));

    res = min(res, llabs(l3-N)*D + B + dp(l3/3));
    res = min(res, llabs(r3-N)*D + B + dp(r3/3));

    res = min(res, llabs(l5-N)*D + C + dp(l5/5));
    res = min(res, llabs(r5-N)*D + C + dp(r5/5));


    return mp[x] = res;
}

