    for (int i = 0; i < N; ++i) {
      for (int j = 0; j < N; ++j) {
        for (int k = 0; k < N; ++k) {
          if (i + 1 < N) pr[i + 1][j][k] = mul(pr[i][j][k], 2);
          if (j + 1 < N) pr[i][j + 1][k] = mul(pr[i][j][k], 3);
          if (k + 1 < N) pr[i][j][k + 1] = mul(pr[i][j][k], 5);
          dp[i][j][k] = Inf;
        }
      }
    }
    auto gettk = [&] (ll x, ll y) {
      if (y == Inf) return Inf;
      ll tk = x / y;
      ll go = tk * y;
      if (abs(x - go) > abs(x - (go + y))) ++tk;
      return tk;
    };
    auto getx = [&] (ll x, ll y) {
      if (x == Inf || y == Inf) return Inf;
      ll tk = x / y;
      ll go = tk * y;
      if (abs(x - go) > abs(x - (go + y))) ++tk;
      return abs(x - tk * y);
    };
    dp[0][0][0] = 0;
    for (int i = 0; i < N; ++i) {
      for (int j = 0; j < N; ++j) {
        for (int k = 0; k < N; ++k) {
          if (i + 1 < N) {
            dp[i + 1][j][k] = min(dp[i + 1][j][k], sum(dp[i][j][k], gettk(getx(n, pr[i + 1][j][k]), pr[i][j][k])));
          }
          if (j + 1 < N) {
            dp[i][j + 1][k] = min(dp[i][j + 1][k], sum(dp[i][j][k], gettk(getx(n, pr[i][j + 1][k]), pr[i][j][k])));
          } 
          if (k + 1 < N) {
            dp[i][j][k + 1] = min(dp[i][j][k + 1], sum(dp[i][j][k], gettk(getx(n, pr[i][j][k + 1]), pr[i][j][k])));
          }
          ll tk = gettk(n, pr[i][j][k]);
          ll need = sum(dp[i][j][k], tk);
          ll all = mul(need, d);
          add(all, mul(i, a));
          add(all, mul(j, b));
          add(all, mul(k, c));
          ans = min(ans, all);
        }
      }
    }
    cout << ans << '\n'; 
  }
}

