vector<LL> intoBase(LL x, vector<LL> &bases) {
	vector<LL> res;
	for (int i = 0; i < bases.size(); ++i) {
		res.push_back(x % bases[i]);
		x /= bases[i];
	}
	res.push_back(x);
	return res;
}

LL getBaseAns(vector<LL> &base, vector<LL> &bit) {
	int l = 0, r = base.size() - 1;
	while (l <= r && bit[l] == 0) {
		++l;
	}
	while (l <= r && bit[r] == 0) {
		--r;
	}
	LL frontRes = 0, backRes = 1;
	LL res = 0;
	for (int i = l; i <= r; ++i) {
		frontRes += bit[i];
		backRes += (base[i] - bit[i] - 1);
		if (frontRes > backRes + 1 && (i == r || bit[i + 1] != base[i + 1] - 1)) {
			res += backRes;
			frontRes = 0;
			backRes = 1;
			if (i == r) {
				res += 1;
			} else {
				bit[i + 1] += 1;
			}
		}
	}
	return res + min(frontRes, backRes);
}

