		sort(g.begin(), g.end());
		g.erase(unique(g.begin(), g.end()), g.end());
		int S = g.size();
		vector<long long> targetl(S), targetr(S);
		for (int i = 0; i < S; ++i) {
			int x = g[i][0], y = g[i][1], z = g[i][2];
			long long b = pw2[x] * pw3[y] * pw5[z];
			targetr[i] = N % b;
			targetl[i] = N % b - b;
		}
		vector<long long> dpl(S, inf), dpr(S, inf);
		dpl[0] = 1; dpr[0] = 0;
		for (int i = 1; i < S; ++i) {
			int x = g[i][0], y = g[i][1], z = g[i][2];
			long long b = pw2[x] * pw3[y] * pw5[z];
			if (x >= 1) {
				int ptr = lower_bound(g.begin(), g.end(), vector<int>({ x - 1, y, z })) - g.begin();
				dpl[i] = min(dpl[ptr] + abs(targetl[ptr] - targetl[i]) / (b / 2), dpr[ptr] + abs(targetr[ptr] - targetl[i]) / (b / 2));
				dpr[i] = min(dpl[ptr] + abs(targetl[ptr] - targetr[i]) / (b / 2), dpr[ptr] + abs(targetr[ptr] - targetr[i]) / (b / 2));
			}
			if (y >= 1) {
				int ptr = lower_bound(g.begin(), g.end(), vector<int>({ x, y - 1, z })) - g.begin();
				dpl[i] = min(dpl[ptr] + abs(targetl[ptr] - targetl[i]) / (b / 3), dpr[ptr] + abs(targetr[ptr] - targetl[i]) / (b / 3));
				dpr[i] = min(dpl[ptr] + abs(targetl[ptr] - targetr[i]) / (b / 3), dpr[ptr] + abs(targetr[ptr] - targetr[i]) / (b / 3));
			}
			if (z >= 1) {
				int ptr = lower_bound(g.begin(), g.end(), vector<int>({ x, y, z - 1 })) - g.begin();
				dpl[i] = min(dpl[ptr] + abs(targetl[ptr] - targetl[i]) / (b / 5), dpr[ptr] + abs(targetr[ptr] - targetl[i]) / (b / 5));
				dpr[i] = min(dpl[ptr] + abs(targetl[ptr] - targetr[i]) / (b / 5), dpr[ptr] + abs(targetr[ptr] - targetr[i]) / (b / 5));
			}
			if (dpr[i] - dpl[i] >= 2) dpr[i] = dpl[i] + 1;
			if (dpl[i] - dpr[i] >= 2) dpl[i] = dpr[i] + 1;
		}
		long long ans = inf;
		for (int i = 0; i < S; ++i) {
			int x = g[i][0], y = g[i][1], z = g[i][2];
			long long b = pw2[x] * pw3[y] * pw5[z];
			long long rem = (N - targetr[i]) / b;
			double respre = x * A + y * B + z * C + (1.0 * dpr[i] + rem) * D;
			if (respre < ans * 1.01) {
				long long res = x * A + y * B + z * C + (dpr[i] + rem) * D;
				ans = min(ans, res);
			}
		}
		cout << ans << endl;
	}
	return 0;
}

