			if( cost > ans ) break;
			if( loc == 0 ) ans = min( ans, cost );
			else if( loc == 1 ) {
				if( cost + D[i] >= 0 ) push( cost + D[i], 0 );
			}
			else {
				if( loc % 2 == 0 ) {
					if( cost + A[i] >= 0 ) push( cost + A[i], loc / 2 );
				}
				else {
					if( cost + A[i] + D[i] >= 0 ) push( cost + A[i] + D[i], (loc - 1) / 2 );
				}
				if( loc % 3 == 0 ) {
					if( cost + B[i] >= 0 ) push( cost + B[i], loc / 3 );
				}
				else {
					int m = loc % 3;
					if( m < 3 - m ) {
						if( cost + B[i] + D[i] * m >= 0 && D[i] * m >= 0 ) push( cost + B[i] + D[i] * m, (loc - m) / 3 );
					}
					else {
						if( cost + B[i] + D[i] * (3 - m) >= 0 && D[i] * (3 - m) >= 0 && loc + (3 - m) >= 0 ) push( cost + B[i] + D[i] * (3 - m), (loc + (3 - m)) / 3 );
					}
				}
				if( loc % 5 == 0 ) {
					if( cost + C[i] >= 0 ) push( cost + C[i], loc / 5 );
				}
				else {
					int m = loc % 5;
					if( m < 5 - m ) {
						if( cost + C[i] + D[i] * m >= 0 && D[i] * m >= 0 ) push( cost + C[i] + D[i] * m, (loc - m) / 5 );
					}
					else {
						if( cost + C[i] + D[i] * (5 - m) >= 0 && D[i] * (5 - m) >= 0 ) push( cost + C[i] + D[i] * (5 - m), (loc + (5 - m)) / 5 );
					}
				}
				if( cost + loc * D[i] >= 0 && loc * D[i] >= 0 ) push( cost + loc * D[i], 0 );
			}
		}
		cout << ans << endl;
	}
}

