long long n;
int a, b, c, d;
const __int128 one = 1;

void solve() {
  scanf("%lld %d %d %d %d", &n, &a, &b, &c, &d);
  __int128 ans = one * d * n;
  for (int i = 0; i < 200; i++) {
    for (int j = 0; i + j*1.585 < 200; j++) {
      for (int k = 0; i + j*1.585 + k*2.322 < 200; k++) {
        int ca = i;
        int cb = j;
        int cc = k;
        long long cd = 0;
        long long nn = n;
        while (cc) {
          switch (nn % 5) {
            case 0:
              cc--;
              nn = nn / 5;
              break;
            case 1: case 2:
              cd += nn % 5;
              nn -= nn % 5;
              break;
            case 3: case 4:
              cd += 5 - nn % 5;
              nn += 5 - nn % 5;
              break;
          }
        }
        while (cb) {
          switch (nn % 3) {
            case 0:
              cb--;
              nn = nn / 3;
              break;
            case 1:
              cd++;
              nn--;
              break;
            case 2:
              cd++;
              nn++;
              break;
          }
        }
        while (ca) {
          switch (nn % 2) {
            case 0:
              ca--;
              nn = nn / 2;
              break;
            case 1:
              cd++;
              nn--;
              break;
          }
        }
        cd += nn;
        __int128 res = one * i * a + one * j * b + one * k * c + one * cd * d;
        if (res < ans) {
          ans = res;
        }
      }
    }
  }
  printf("%lld\n", (long long) ans);
}

