typedef long long Long;

const int RANDOM =
    chrono::high_resolution_clock::now().time_since_epoch().count();
struct chash {  // To use most bits rather than just the lowest ones:
  const uint64_t C = Long(4e18 * acos(0)) | 71;  // large odd number
  Long operator()(Long x) const { return __builtin_bswap64((x ^ RANDOM) * C); }
};
__gnu_pbds::gp_hash_table<Long, Long, chash> ht({}, {}, {}, {}, {1 << 16});

Long a, b, c, d;

Long mul(Long x, Long y) {
  if (x > LLONG_MAX / y) return LLONG_MAX;
  return x * y;
}

Long solve(Long x) {
  if (x == 0) return 0;
  if (x == 1) return d;
  if (x == 2) return d + min(a, d);
  auto it = ht.find(x);
  if (it != ht.end()) return it->second;
  Long res = 1e15;
  // 2
  res = min(res, solve(x / 2) + min(a, mul(x / 2, d)) + (x % 2) * d);
  res = min(res, solve((x + 1) / 2) + a + d);
  // 3
  res = min(res, solve(x / 3) + min(b, mul(2 * (x / 3), d)) + (x % 3) * d);
  res = min(res, solve(x / 3 + 1) + b + (3 - (x % 3)) * d);
  // 5
  res = min(res, solve(x / 5) + min(c, mul(4 * (x / 5), d)) + (x % 5) * d);
  res = min(res, solve(x / 5 + 1) + c + (5 - (x % 5)) * d);

  return ht[x] = res;
}

