map<ull, ull> memo;

ull dfs(ull i) {
  if (memo.find(i) != end(memo)) {
    return memo[i];
  }
  if (i == 1) {
    return memo[i] = d;
  }
  ull ans = i * d;
  if (i >= 2) {
    if (i % 2 == 0) {
      ans = min(ans, dfs(i / 2) + a);
    } else {
      ans = min(ans, dfs((i + 1) / 2) + a + d);
      ans = min(ans, dfs((i - 1) / 2) + a + d);
    }
  }
  if (i >= 3) {
    if (i % 3 == 0) {
      ans = min(ans, dfs(i / 3) + b);
    } else if (i % 3 == 1) {
      ans = min(ans, dfs((i - 1) / 3) + b + d);
      ans = min(ans, dfs((i + 2) / 3) + b + 2 * d);
    } else {
      ans = min(ans, dfs((i - 2) / 3) + b + 2 * d);
      ans = min(ans, dfs((i + 1) / 3) + b + d);
    }
  }
  if (i >= 5) {
    if (i % 5 == 0) {
      ans = min(ans, dfs(i / 5) + c);
    } else if (i % 5 == 1) {
      ans = min(ans, dfs((i - 1) / 5) + c + d);
      ans = min(ans, dfs((i + 4) / 5) + c + 4 * d);
    } else if (i % 5 == 2) {
      ans = min(ans, dfs((i - 2) / 5) + c + 2 * d);
      ans = min(ans, dfs((i + 3) / 5) + c + 3 * d);
    } else if (i % 5 == 3) {
      ans = min(ans, dfs((i - 3) / 5) + c + 3 * d);
      ans = min(ans, dfs((i + 2) / 5) + c + 2 * d);
    } else {
      ans = min(ans, dfs((i - 4) / 5) + c + 4 * d);
      ans = min(ans, dfs((i + 1) / 5) + c + d);
    }
  }
  return memo[i] = ans;
}

