ll dfs(map<ll, ll>& memo, const ll& n, const ll& a, const ll& b, const ll& c, const ll& d) {
  if (n == 0) return 0;
  if (memo[n] != 0) return memo[n];

  ll ans = INFLL;
  if (n < ans / d) ans = n * d;  // n * d が桁あふれする場合があるのでガードしておく

  {
    ll mod = n % 2;
    chmin(ans, dfs(memo, (n+mod)/2, a, b, c, d) + a + mod * d);
    chmin(ans, dfs(memo, (n-mod)/2, a, b, c, d) + a + (2-mod) * d);
  }
  {
    ll mod = n % 3;
    chmin(ans, dfs(memo, (n-mod)/3, a, b, c, d) + b + mod * d);
    chmin(ans, dfs(memo, (n+3-mod)/3, a, b, c, d) + b + (3-mod) * d);
  }
  {
    ll mod = n % 5;
    chmin(ans, dfs(memo, (n-mod)/5, a, b, c, d) + c + mod * d);
    chmin(ans, dfs(memo, (n+5-mod)/5, a, b, c, d) + c + (5-mod) * d);
  }

  memo[n] = ans;
  return ans;
}


