    priority_queue<pll, vector<pll>, greater<pll>> pq;
    pq.push(pll(0, n));
    map<ll, ll> mp;
    mp[n] = 0;
    ll ans = INF;
    while (pq.size()) {
        pll temp = pq.top();
        pq.pop();
        ll x = temp.second, cost = temp.first;
        if (x <= (INF - cost) / d) {
            chmin(ans, cost + d * x);
        }
        for (int v: {2, 3, 5}) {
