                else ncost += c;
                if (mp.count(nx) and mp[nx] <= ncost) continue;
                mp[nx] = ncost;
                pq.push(pll(ncost, nx));
            }
            for (int j = 0; j < v; j++) {
                if ((x - j) % v != 0) continue;
