void dfs2(unsigned long long now, unsigned long long mon){
	if(mon >= ans){
		return;
	}

	if(now == 1){
		ans = min(ans, mon+D);
		return;
	}

	if(now == 0){
		ans = min(ans, mon);
		return;
	}

	ans = min(ans, D*now+mon);


	if((now%2)){
		dfs2((now+1)/2, mon+D+A);
		dfs2(now/2, mon+D+A);
	}
	else dfs2(now/2, mon+A);

	switch(now%3){
		case 0:{
			dfs2(now/3, mon+B);
			break;
		}
