using namespace std;

int main(){
    Init();
    ll t; cin >> t;
    while(t--){
        ll n, a, b, c, d, ans = 1e18;;
        cin >> n >> a >> b >> c >> d;

        // m倍する時のコスト
        vi cost(6);
        cost[2] = a, cost[3] = b, cost[5] = c;

        // que<v, num>; numの時のコスト
        priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>> que;
        // 最小値（メモ）
        map<ll, ll> mp;

        // ansより大きかったら狩る
        // 既に通っている場合は、その時のコストより小さくないと狩る
        // 上記を除いてqueに加える
        auto insert = [&](ll v, ll n){
            if(v < ans && (!mp.count(n) || v < mp[n])){
                que.emplace(v, n);
                mp[n] = v;
            }
        };

        // 初期状態
        que.emplace(0, n);
        while(que.size()){
            auto p = que.top(); que.pop();
            ll v = p.first, num = p.second;
            // 優先度付き（昇順）なので、ansを超えた時点でbreak
            if(v >= ans) break;
            // ある地点から全て-1（コストd）で行けるなら試す
            if(num <= 2e18/d) chmin(ans, v+num*d);
            // 2, 3, 5倍を試す
            for(auto &mul: {2, 3, 5}){
                ll r = num%mul;
                ll vt = v + r*d + cost[mul];
                insert(vt, num/mul);
                vt = v + (mul-r)*d + cost[mul];
                insert(vt, num/mul+1);
            }
        }
        cout << ans << endl;
    }
}

