using namespace std;

int answer(int number, vector<int> &actions) {
  int a = actions.at(0);
  int b = actions.at(1);
  int c = actions.at(2);
  int d = actions.at(3);

  vector<int> coins;
  if(number == 1){
    return d;
  }

  if(number%2==0){
    coins.push_back(a + answer(number/2,actions));
  } else{
    int re = 2- number % 2;
    int target = number + re;
    coins.push_back( d * re + a + answer(target/2,actions));
  }

  if(number%3==0){
    coins.push_back(b + answer(number/3,actions));
  } else {
    int re = 3 - number % 3;
    int target = number + re;
    coins.push_back( d * re + b + answer(target/3,actions));
  }

  if(number%5==0){
    coins.push_back(c + answer(number/5,actions));
  }else{
    int re = 5 - number % 5 ;
    int target = number + re;
    coins.push_back( d * re + c + answer(target/5,actions));
  }

  if(number%30 != 0){
    coins.push_back( d + answer(number-1,actions));
  }

  sort(coins.begin(), coins.end());

  return coins[0];
}

int main() {
  int t;
  cin >> t;

  for(int i=0; i<t; i++){
    int n;
    cin >> n;

    vector<int> actions(n);
    for(int j=0;j<4;j++){
      cin >> actions[j];
    }
    cout << answer(n, actions) << endl;;
  }

}

