const ll INF = 1e18;
ll go(ll n) {
    if (n == 0) return 0;
    if (mp.find(n) != mp.end()) return mp[n];
    ll best = INF;
    if (n < (INF + d - 1) / d) best = n * d;
    for (int c = 0; c < 3; c++) {
        for (int i = -p[c] + 1; i <= p[c] - 1; i++) {
            ll will = n + i;
            if (will % p[c] != 0) continue;
            if (will < 0) continue;
            will /= p[c];
            if (will >= n) continue;
            if (will != 0) {
                best = min(best, go(will) + abs(i) * d + a[c]);
            }
            else {
                best = min(best, abs(i) * d);
            }
        }
    }
    return mp[n] = best;
}
