const ll INF=1e18;
const ll MOD=1e9+7;

ll cost[4];
ll dv[3] = { 2, 3, 5 };
map<ll, ll> memo;

ll getCost(ll n)
{
    if (n == 0) return 0;
    if (n == 1) return cost[3];
    if (memo.count(n)) return memo[n];

    ll res = INF;
    if (n < res/cost[3]) res = n*cost[3];
    rep(i,3) {
        if (n % dv[i] == 0) {
            res = min(res, getCost(n/dv[i]) + cost[i]);
        } else {
            ll lo = n / dv[i] * dv[i];
            ll hi = lo + dv[i];

            res = min(res, getCost(lo/dv[i]) + cost[i] + (n-lo)*cost[3]);
            res = min(res, getCost(hi/dv[i]) + cost[i] + (hi-n)*cost[3]);
        }
    }
    memo[n] = res;
    return res;
}

int main(int, char**)
{
    int t;
    cin >> t;

    ll n;
    vector<ll> ans;
    rep(i,t) {
        cin >> n;
        rep(j,4) cin >> cost[j];
        ans.push_back(getCost(n));
        memo.clear();
    }
    for (ll a : ans) cout << a << endl;

    return 0;
}

