auto solve(ll n, ll a, ll b, ll c, ll d) {
	ll ans = 1e18;
	unordered_map<ll, ll> use;
	priority_queue<PAIR, V<PAIR>, std::greater<PAIR>> q;

	auto ad = [&](ll cst, ll x) {
		if (use.find(x) == use.end()) {
			q.emplace(cst, x);
			use.emplace(x, cst);
			return;
		}
		if (cst < use[x]) {
			q.emplace(cst, x);
			use[x] = cst;
		}
	};

	q.emplace(0, n);
	while (!q.empty()) {
		auto [cst, x] = q.top();
		q.pop();
		if (cst > use[x]) { continue; }
		if (x == 0) { chmin(ans, cst); continue; }
		if (1e18 / x > d - 10) { chmin(ans, cst + x * d); }
		//cout << x << " " << cst << endl;
		if (x & 1) {
			ad(cst + a + d, (x - 1) / 2);
			ad(cst + a + d, (x + 1) / 2);
		} else {
			ad(cst + a, x / 2);
		}

		ll d3 = x % 3;
		if (d3 > 1) {
			ll nd3 = 3 - d3;
			ad(cst + b + nd3 * d, (x + nd3) / 3);
		} else {
			ad(cst + b + d3 * d, (x - d3) / 3);
		}

		ll d5 = x % 5;
		if (d5 > 2) {
			ll nd5 = 5 - d5;
			ad(cst + c + nd5 * d, (x + nd5) / 5);
		} else {
			ad(cst + c + d5 * d, (x - d5) / 5);
		}
	}
	return ans;
}

