const ll INF = 1e18;
const int m[] = {2, 3, 5};

ll n, d;
ll c[3];
map<ll, ll> mp;

ll myMin(ll x, ll d, ll f){
	return (x > (ldb)f / d ? f : x * d);
}

inline ll solve(ll x){
	if(mp.find(x) != mp.end())
		return mp[x];
	if(!x)
		return 0;
	ll &ret = mp[x], nx1, nx2, res1, res2;
	ret = myMin(x, d, INF);
	FOR(i, 0, 3){
		for(nx1 = x, res1 = 0; nx1 % m[i]; ++nx1, res1 += d);
		for(nx2 = x, res2 = 0; nx2 % m[i]; --nx2, res2 += d);
		if(res1 <= res2){
			ret = min(ret, solve(nx1 / m[i]) + res1 + c[i]);
		}
		if(res1 >= res2){
			ret = min(ret, solve(nx2 / m[i]) + res2 + c[i]);
		}
	}
	return ret;
}

