long long solve(long long x)
{
	if(!x)
		return 0;
	if(x==1)
		return d;
	if(mp.count(x))
		return mp[x];
	long long l2=x/2*2,r2=(x+1)/2*2,l3=x/3*3,r3=(x+2)/3*3,l5=x/5*5,r5=(x+4)/5*5,res=1e18;
	if(x<res/d)
		res=x*d;
	res=min(res,llabs(l2-x)*d+a+solve(l2/2));
    res=min(res,llabs(r2-x)*d+a+solve(r2/2));
    res=min(res,llabs(l3-x)*d+b+solve(l3/3));
    res=min(res,llabs(r3-x)*d+b+solve(r3/3));
    res=min(res,llabs(l5-x)*d+c+solve(l5/5));
    res=min(res,llabs(r5-x)*d+c+solve(r5/5));
    mp[x]=res;
    return res;
}
