map<lint,lint> memo;

lint dfs(lint n){
	if(n==1) return d;

	if(memo.count(n)>0) return memo[n];

	lint res=INF;
	if(1.0*d*n<1e10) res=d*n;

	for(int x:{2,3,5}){
		lint next=n/x;
		if(1<=next && next<n) res=min(res,a[x]+d*(n-next*x)+dfs(next));
		next=(n+x-1)/x;
		if(1<=next && next<n) res=min(res,a[x]+d*(next*x-n)+dfs(next));
	}
	return memo[n]=res;
}

