ll gao(ll n){
	if(n==0)return 0;
	if(n==1)return d;
	ll u=inf;
	if(n<inf/d)u=n*d;
	if(m.find(n)!=m.end())
		return m[n];
	ll x;
	for(ll i=0;i<3;i++){
		if(i==0)x=a;
		if(i==1)x=b;
		if(i==2)x=c;
		if(n%v[i]==0)
			u=min(u,x+gao(n/v[i]));
