map<long long, __int128> memo;
vector<long long> k{
  2,3,5
};

__int128 dfs(const vector<long long>& w, long long n){
  if(memo.count(n)) return memo[n];
  __int128 res = (__int128)n * w[3];

  for(int i=0; i<3; i++){
    __int128 tmp = dfs(w, n/k[i]) + w[i] + n%k[i] * w[3];
    if(res > tmp) res = tmp;
    tmp = dfs(w, (n+k[i]-1)/k[i]) + w[i] + (k[i]-(n%k[i]))%k[i] * w[3];
    if(res > tmp) res = tmp;
  }
  return memo[n] = res;
}

