ll solve(ll N){
  if(N==0)return 0;
  if(mp[N])return mp[N];
  ll K,x,res=inf;
  K=N>>1;
  if(~N&1){
    x=solve(K);
    chmin(res,x+D*K);
    chmin(res,x+A);
  }else{
    x=solve(K);
    chmin(res,x+D*(N-K));
    chmin(res,x+A+D);
    ++K;
    x=solve(K);
    chmin(res,x+D*(N-K));
    chmin(res,x+A+D);
  }
  K=N/3;
  if(3*K==N){
    x=solve(K);
    chmin(res,x+min(2*D*K,B));
  }else{
    x=solve(K);
    chmin(res,x+D*(N-K));
    chmin(res,x+B+(N-K*3)*D);
    ++K;
    x=solve(K);
    chmin(res,x+D*(N-K));
    chmin(res,x+B+(K*3-N)*D);
  }
  K=N/5;
  if(5*K==N){
    x=solve(K);
    chmin(res,x+min(4*D*K,C));
