ll A, B, C, D;
ll INF = 1e18;

unordered_map<ll, ll> mp;

ll go(ll n) {
  if (n == 0)
    return 0;
  if (n == 1)
    return D;
  ll &res = mp[n];
  if (res == 0)
    res = INF;
  else
    return res;

  if (n % 2 == 0)
    res = min(res, go(n / 2) + A);
  else
    res = min(res, min(go((n - 1) / 2) + D + A, go((n + 1) / 2) + D + A));

  if (n % 3 <= 1)
    res = min(res, go(n / 3) + D * (n % 3) + B);
  else
    res = min(res, go(n / 3 + 1) + D + B);

  if (n % 5 <= 2)
    res = min(res, go(n / 5) + D * (n % 5) + C);
  else
    res = min(res, go(n / 5 + 1) + D * (5 - n % 5) + C);

  if (res / D >= n)
    res = min(res, n * D);

  debug("n = %lld  res %lld\n", n, res);
  return res;
}

