constexpr int MOD = 1e9 + 7;
constexpr long long LINF = 1e18;
constexpr double EPS = 1e-10;
constexpr double PI = M_PI;

ll rec(ll n, ll a, ll b, ll c, ll d, map<ll, ll> &mp) {
    if (n == 0) return 0;
    if (n == 1) return d;
    if (mp.count(n)) return mp[n];

    ll res = LINF;
    if (n < 1e9) chmin(res, n*d);
    chmin(res, a + n%2 * d + rec(n/2, a, b, c, d, mp));
    if (n != 2) chmin(res, a + (2 - n%2) * d + rec(n/2+1, a, b, c, d, mp));
    chmin(res, b + n%3 * d + rec(n/3, a, b, c, d, mp));
    chmin(res, b + (3 - n%3) * d + rec(n/3+1, a, b, c, d, mp));
    chmin(res, c + n%5 * d + rec(n/5, a, b, c, d, mp));
    chmin(res, c + (5 - n%5) * d + rec(n/5+1, a, b, c, d, mp));

    return mp[n] = res;
}

