map<ll,ll> m;

ll dfs(ll value, ll a, ll b, ll c, ll d, ll cnt1){
  if(m[value]!=0)
    return m[value];
  if(value==0)
    return 0;

  ll res=LLINF;
  if(value%5==0){
    ll x=dfs(value/5,a,b,c,d,0);
    if(value/5*4<LLMAX/d)
      res=min(res,x+value/5*4*d);
    res=min(res,x+c);
  }
  if(value%3==0){
    ll x=dfs(value/3,a,b,c,d,0);
    if(value/3*2<LLMAX/d)
      res=min(res,x+value/3*2*d);
    res=min(res,x+b);
  }
  if(value%2==0){
    ll x=dfs(value/2,a,b,c,d,0);
    if(value/2<LLMAX/d)
      res=min(res,x+value/2*d);
    res=min(res,x+a);
  }
  if(cnt1<5)
    res=min(res,dfs(value-1,a,b,c,d,cnt1+1)+d);
  if(cnt1<5 && value>2)
    res=min(res,dfs(value+1,a,b,c,d,cnt1+1)+d);

  if(value<LLMAX/d)
    res=min(res,value*d);

  m[value]=res;
  return res;
}

