    queue<int> que;
    que.push(N);
    mp[N]=0;
    while(que.size()>0){
      if(N==1){
        break;
      }
      int x=que.front();
      que.pop();
      for(int i=x-1;i<=x+1;i++){
        int cost=0;
        if(i%2==0 && i>=1){
          cost=min((i/2)*D+nature(i-x)*D+mp[x],nature(i-x)*D+A+mp[x]);
          if(cost<0){
            cost=nature(i-x)*D+A+mp[x];
          }
          if(cost<mp[i/2] || mp[i/2]==0){
            mp[i/2]=cost;
            if(i/2>1){
              que.push(i/2);
            }
          }
        }
      }
      //3で割る場合
      for(int i=x-2;i<=x+2;i++){
        int cost=0;
        if(i%3==0 && i>=1){
          cost=min((i-i/3)*D+nature(i-x)*D+mp[x],nature(i-x)*D+B+mp[x]);
          if(cost<0){
            cost=nature(i-x)*D+B+mp[x];
          }
