            mp[i/3]=cost;
            if(i/3>1){
              que.push(i/3);
            }
          }
        }
      }
      //5で割る場合
      for(int i=x-4;i<=x+4;i++){
        int cost=0;
        if(i%5==0 && i>=1){
          cost=min((i-i/5)*D+nature(i-x)*D+mp[x],nature(i-x)*D+C+mp[x]);
          if(cost<0){
            cost=nature(i-x)*D+C+mp[x];
          }
          if(cost<mp[i/5] || mp[i/5]==0){
            mp[i/5]=cost;
            if(i/5>1){
              que.push(i/5);
            }
          }
        }
      }
    }
    cout<<mp[1]+D<<endl;
  }
}

