ll dfs(ll current) {
	if (current == 0) return 0;
	if (current == 1) return d;
	if (costs.count(current)) {
		return costs[current];
	}
	ll minCosts = 1e18;
	if (current < minCosts / d) {
		minCosts = d * current;
	}
	{
		ll div = current / 5;
		ll m = current - div * 5;
		auto a1 = dfs(div) + c + d * (m);
		minCosts = min(minCosts, a1);
		if (m) {
			a1 = dfs(div+1) + c + d * (- m + 5);
			minCosts = min(minCosts, a1);
		}
	}
	{
		ll div = current / 3;
		ll m = current - div * 3;
		auto a1 = dfs(div) + b + d * (m);
		minCosts = min(minCosts, a1);
		if (m) {
			a1 = dfs(div+1) + b + d * (-m + 3);
			minCosts = min(minCosts, a1);
		}
	}
	{
		ll div = current / 2;
		ll m = current - div * 2;
		auto a1 = dfs(div) + a + d * (m);
		minCosts = min(minCosts, a1);
		if (m) {
			a1 = dfs(div+1) + a + d;
			minCosts = min(minCosts, a1);
		}
	}
	costs[current] = minCosts;
	return minCosts;
}


