    return 0;
  if (n == 1)
    return d;
  if (memo.count(n))
    return memo[n];

  ll l2 = (n / 2) * 2;
  ll r2 = ((n + 1) / 2) * 2;
  ll l3 = (n / 3) * 3;
  ll r3 = ((n + 2) / 3) * 3;
