void solve() {
    ll N, A, B, C, D;
    cin >> N >> A >> B >> C >> D;

    min_queue<ll2> pq; // cost, number reached
    pq.push({0, N});

    unordered_map<ll,ll> visited;
    ll ans = 1e18;

    while(pq.top().se != 0 || pq.top().fi >= ans) {
        // cout << pq.top() << endl;
        ll cost = pq.top().fi;
        ll n = pq.top().se;
        pq.pop();

        if (visited.find(n) == visited.end() || visited[n] > cost)
            visited[n] = cost;
        else
            continue;

        if (N < ans/D) ans = min(ans, N*D); // to avoid overflow check N*D < ans which is our upper bound from the statement!

        if (n % 2 == 0) pq.push({cost+A, n/2});
        else {
            pq.push({cost+A+D, (n+1)/2});
            pq.push({cost+A+D, (n-1)/2});
        }
        if (n % 3 == 0) pq.push({cost+B, n/3});
        else {
            if (n % 3 == 1) pq.push({cost+B+D, (n-1)/3});
            else pq.push({cost+B+D, (n+1)/3});
        }
        if (n % 5 == 0) pq.push({cost+C, n/5});
        else {
            int r = n % 5;
            if (r <= 2) pq.push({cost+C+D*r, (n-r)/5});
            else pq.push({cost+C+D*(5-r), (n+5-r)/5});
        }
    }

    cout << min(ans, pq.top().fi) << "\n";
}

