#include <bits/stdc++.h>
using namespace std;

int64_t A, B, C, D;
map<int64_t, int64_t> memo;

int64_t f(int64_t x)
{
    if (x == 0)
        return 0;
    if (x == 1)
        return D;

    if (memo.count(x))
    {
        return memo.at(x);
    }

    int64_t res = (x < INT64_MAX / D) ? x * D : INT64_MAX;
    res = min(res, f(x / 2) + A + D * (x - (x / 2) * 2));
    if (x % 2 != 0)
    {
        res = min(res, f(x / 2 + 1) + A + D * ((x / 2 + 1) * 2 - x));
    }
    res = min(res, f(x / 3) + B + D * (x - (x / 3) * 3));
    if (x % 3 != 0)
    {
        res = min(res, f(x / 3 + 1) + B + D * ((x / 3 + 1) * 3 - x));
    }
    res = min(res, f(x / 5) + C + D * (x - (x / 5) * 5));
    if (x % 5 != 0)
    {
        res = min(res, f(x / 5 + 1) + C + D * ((x / 5 + 1) * 5 - x));
    }
    memo[x] = res;
    return res;
}

int main()
{
    int T;
    cin >> T;

    for (int t = 0; t < T; t++)
    {
        int64_t N;
        cin >> N >> A >> B >> C >> D;
        memo = map<int64_t, int64_t>();
        cout << f(N) << endl;
    }
}

