ll A, B, C, D;
map<ll, ll> memo;

ll rec(const ll N) {
  if (N == 0) return 0;
  if (N == 1) return D;
  if (memo.count(N) > 0) return memo[N];
  ll res = 1LL << 61;

  if (D < res / N)
    chmin(res, N * D);

  ll multis[] = {2, 3, 5};
  ll coins[] = {A, B, C};
  REP(i, 3) {
    ll multi = multis[i];
    ll coin = coins[i];
    ll U = (N + multi - 1) / multi * multi;
    ll L = (N / multi) * multi;
    chmin(res, abs(U-N) * D + coin + rec(U/multi));
    chmin(res, abs(L-N) * D + coin + rec(L/multi));
  }
  return memo[N] = res;
}

