map<LLONG, LLONG> num2MinCostMap;
LLONG N, A, B, C, D;

LLONG Digit(LLONG n)
{
    LLONG ret = 0;
    while (n)
    {
        n /= 10;
        ++ret;
    }
    return ret;
}

LLONG DFS(const LLONG n)
{
    if (num2MinCostMap.count(n)) return num2MinCostMap[n];
    vector<LLONG> vs(7);
    vs[6] = Digit(n) * Digit(D) > 18 ? 1145141919810364364LL : n * D;
    LLONG x = n / 2, y = n / 3, z = n / 5;
    vs[0] = DFS(x) + (n - x * 2) * D + A;
    vs[1] = DFS(x + 1) + ((x + 1) * 2 - n) * D + A;
    vs[2] = DFS(y) + (n - y * 3) * D + B;
    vs[3] = DFS(y + 1) + ((y + 1) * 3 - n) * D + B;
    vs[4] = DFS(z) + (n - z * 5) * D + C;
    vs[5] = DFS(z + 1) + ((z + 1) * 5 - n) * D + C;
    sort(vs.begin(), vs.end());
    return num2MinCostMap[n] = vs[0];
}

