      upd(res, calc(cur/5) + c + d * abs(i));
      // break;
    }
  }
  for (int i = -5; i <= min(4LL, v); ++i) {    
    long long cur = v - i;
    if ((cur % 3) == 0 &&  cur / 3 < v) {
      upd(res, calc(cur/3) + b + d * abs(i));
      // break;
    }
  }
  for (int i = -5; i <= min(4LL, v); ++i) {
    long long cur = v - i;
    if ((cur % 2) == 0 && cur / 2 < v) {
      upd(res, calc(cur/2) + a + d * abs(i));
      // break;
    }
  }
