using namespace std;

const int maxN = 1 << 18;
const long long INF = 1000000000000ll;

template <class T1, class T2> inline void remin(T1& a, T2 b)	{   a = min(a, (T1)b);  }

unordered_map <long long, long long> M;
long long cost[6], d;

long long go(long long n)
{
	auto it = M.find(n);
	if (it != M.end())
		return it->sd;

	long long ret = INF;

	FOR(i, 0, 5) for (int j : {2, 3, 5}) if (i < j)
	{
		long long dx = cost[j] + d*i;

		long long u = n - i;
		if (u % j == 0)
			remin(ret, go(u/j) + dx);
		u = n + i;
		if (u % j == 0)
			remin(ret, go(u/j) + dx);
	}

	if (n < 1000000000)
		remin(ret, d*n);

	return M[n] = ret;
}

void solve()
{
	long long n;
	scanf ("%lld%lld%lld%lld%lld", &n, cost+2, cost+3, cost+5, &d);
	M.clear();
	FOR(i, 1, 6)
		M[-i] = INF;
	M[0] = 0;
	M[1] = d;
	printf("%lld\n", go(n));	
}

int main()
{
	int t = 1;
	scanf ("%d", &t);
	while (t--)
		solve();
	return 0;
}

