LL finds(LL num)
{
	if (M[num]) return M[num];
	LL res=INF;
	if (log10(num)+log10(D)<=18) res=num*D;
	if (num>=2) res=min(res,calc(num,2,A)); 
	if (num>=3) res=min(res,calc(num,3,B)); 
	if (num>=5) res=min(res,calc(num,5,C));
	return M[num]=res;
}
LL calc(LL num,int k,int cost)
{
	LL L=num/k*k,R=L+k,res=finds(L/k)+abs(num-L)*D+cost;
	if (L!=k) res=min(res,finds(R/k)+abs(num-R)*D+cost);
	return res;
}
