ll res(ll x){
    if(x==0)return 0;
    if(x==1)return d;
    ll mod=1;
    ll k=0;
    ll res=INF;
    while (mod<=x*2){
        __int128 parta=(__int128)d*(__int128)(x/mod);
        ll partb=d*(__builtin_popcount(x%mod));
        ll partc=(k)*a;
        ll partd=d*(k+1-__builtin_popcount(x%mod));
        ll parte=(k)*a;
        // if (mod==4){
        //     cerr<<(ll)parta<<' '<<d*(__builtin_popcount(x%mod))<<' '<<(ll)partc<<'\n';
        // }
        if(parta<=INF){
            res=min(res,(ll)parta+partb+partc);
            res=min(res,(ll)parta+partd+parte);
        }

        mod*=2;
        ++k;
    }
    return res;
}

void ask(int B, int C){
    vi ord;
    for(int x=0;x<C;++x)ord.pb(5);
    for(int x=0;x<B;++x)ord.pb(3);
