        // cerr<<cost<<' '<<t<<' '<<t%ct<<'\n';
        if(ct==3)cost+=b;
        else cost+=c;
        if(ct==3){
            if(t%3!=0)cost+=d;
            if(t%3==2)++t;
            else if(t%3==1) --t;
        }else if(ct==5){
            if(t%5==1){
                t--;
                cost+=d;
            }else if(t%5==2){
                --t;--t;cost+=d;cost+=d;
            }else if(t%5==3){
                ++t;++t;cost+=d;cost+=d;
            }else if(t%5==4){
                ++t;cost+=d;
            }
        }
        t/=ct;
    }
    // cerr<<t<<' '<<res(t)<<'\n';
    ans=min(ans, cost+res(t));
}

