int myChe(map<long long,long long> &checked, pair<long long, long long> tmp, long long &minC){
  	  int flag = 1;
      long long n,cost,thisC;
      tie(n,cost) = tmp;
      if(minC <= cost) flag = 0;
	  if(checked.count(n)){
        thisC = checked.at(n);
        if(thisC <= cost) flag = 0;
        else checked[n] = cost;
      }
      else{
        checked[n] = cost;
      }
  	  if(n==1){
        minC = min(minC,cost);
        flag = 0;
      }
      else if(n==0) flag = 0;
  	  return flag;
}

void myTmp(map<long long,long long> &checked, long long &minC,
           pair<long long, long long> tmp, 
           queue<pair<long long, long long>> &que, 
           int p, long long costA, long long costD){
  long long n,cost;
  pair<long long, long long> tmp2;
  tie(n,cost) = tmp;
  if(n%p == 0){
    tmp2 = make_pair(n/p, cost + costA);
    if(myChe(checked,tmp2,minC)) que.push(tmp2);
  }
  else{
    tmp2 = make_pair(n/p, cost + costA + costD*(n%p));
    if(myChe(checked,tmp2,minC))que.push(tmp2);
    tmp2 = make_pair(n/p+1, cost + costA + costD*(p - n%p));
    if(myChe(checked,tmp2,minC))que.push(tmp2);
  }
}
