    if(n <= 2 * 1e9) chmin(ret, n * d);
    if(n % 2 == 0) chmin(ret, f(n / 2) + a);
    else { 
        chmin(ret, f((n + 1) / 2) + d + a);
        chmin(ret, f((n - 1) / 2) + d + a);
