    if(n % 3 == 2) {
        chmin(ret, f((n + 1) / 3) + d + b);
        chmin(ret, f((n - 2) / 3) + 2 * d + b);
    }
    if(n % 5 == 0) chmin(ret, f(n / 5) + c);
    if(n % 5 == 1) {
        chmin(ret, f((n + 4) / 5) + 4 * d + c);
        chmin(ret, f((n - 1) / 5) + d + c);
