        chmin(ret, f((n + 2) / 5) + 2 * d + c);
        chmin(ret, f((n - 3) / 5) + 3 * d + c);
    }
    if(n % 5 == 4) {
        chmin(ret, f((n + 1) / 5) + d + c);
