const long long inf = (long long) 1e18 + 10;

map<long long, long long> dist;

long long A, B, C, D;

long long go(long long n) {
  if (dist.count(n)) return dist[n];
  long long cur = inf / D > n ? n * D : inf;
  dist[n] = cur;
  for (int t : {2, 3, 5}) {
    long long m = n % t, prev = n - m, next = prev + t;
    long long p = (t == 2 ? A : (t == 3 ? B : C));
    cur = min(cur, go(prev / t) + m * D + p);
    cur = min(cur, go(next / t) + (t - m) * D + p);
  }
  return dist[n] = cur;
}

