    dist[2] = min(dist[1] + A, dist[1] + D);
    dist[3] = min(dist[1] + B, dist[2] + D);
    dist[4] = min(dist[2] + A, dist[3] + D);
    dist[5] = min(dist[1] + C, dist[4] + D);
    cout << go(N) << '\n';
  }
  return 0;
}

