const long long int INF = 1001001001001001001;

long long int A, B, C, D;

map<long long int, long long int> dp;
map<long long int, bool> flg;
long long int f(long long int N) {
  if (flg[N]) return dp[N];
  if (N == 0) return 0;
  if (N == 1) return D;

  long long int res = INF;
  if (N < INF / D) res = min(res, N * D);

  if (N % 2 == 0) {
    res = min(res, f(N/2) + A);
  } else {
    res = min(res, f((N-1)/2) + D + A);
    res = min(res, f((N+1)/2) + D + A);
  }

  if (N % 3 == 0) {
    res = min(res, f(N/3) + B);
  } else {
    int m = N % 3;
    res = min(res, f((N-m)/3) + m*D + B);
    res = min(res, f((N-m+3)/3) + (3-m)*D + B);
  }

  if (N % 5 == 0) {
    res = min(res, f(N/5) + C);
  } else {
    int m = N % 5;
    res = min(res, f((N-m)/5) + m*D + C);
    res = min(res, f((N-m+5)/5) + (5-m)*D + C);
  }

  flg[N] = true;
  return dp[N] = res;
}

