      res=min(res,x+c);
  }
  if(value%3==0){
    ll x=dfs(value/3,a,b,c,d,0);
    if(value/3*2<=LLMAX/d){
      if(x<=LLMAX-value/3*2*d)
        res=min(res,x+value/3*2*d);
    }
    if(x<=LLMAX-b)
      res=min(res,x+b);
  }
  if(value%2==0){
    ll x=dfs(value/2,a,b,c,d,0);
    if(value/2<=LLMAX/d){
      if(x<=LLMAX-value/2*d)
        res=min(res,x+value/2*d);
    }
    if(x<=LLMAX-a)
      res=min(res,x+a);
  }
  if(cnt1<=5){
    ll x=dfs(value-1,a,b,c,d,cnt1+1);
    if(x<=LLMAX-d)
      res=min(res,x+d);
  }
  if(cnt1<=5 && value>2){
    ll x=dfs(value+1,a,b,c,d,cnt1+1);
    if(x<=LLMAX-d)
      res=min(res,x+d);
  }

  if(value<=LLMAX/d)
    res=min(res,value*d);

  m[value]=res;
  return res;
}

