LL N, A, B, C, D;
int ddig;
LL res;

int Dig(LL num) {
    int dig = 0;
    while(num > 0) {
        num /= 10;
        ++dig;
    }

    return dig;
}

void dfs(LL n, LL cost) {
    if(n == 1) {
        res = min(res, cost + D);
        return;
    }
    if(res <= cost) return;

    while(n % 5 == 0) {
        n /= 5;
        cost += C;
    }
    while(n % 3 == 0) {
        n /= 3;
        cost += B;
    }
    while(n % 2 == 0) {
        n /= 2;
        cost += A;
    }

    if(n - (n % 5) >= 5) dfs((n - n % 5) / 5, cost + C + D * (n % 5));
    dfs((n + (5 - n % 5)) / 5, cost + C + D * (5 - n % 5));

    if(n - (n % 3) >= 3) dfs((n - n % 3) / 3, cost + B + D * (n % 3));
    dfs((n + (3 - n % 3)) / 3, cost + B + D * (3 - n % 3));

    if(n - (n % 2) >= 2) dfs((n - n % 2) / 2, cost + A + D * (n % 2));
    dfs((n + (2 - n % 2)) / 2, cost + A + D * (2 - n % 2));

    if(Dig(n) + ddig < 18) res = min(res, cost + n * D);

    return;
}

