map<lint, lint> mp;
lint A,B,C,D;

lint rec(lint n){
    if(n == 0) return 0;
    if(n == 1) return D;
    if(mp[n] != 0) return mp[n]; // 計算済みならもうやらない(メモ化再帰)

    lint ans = n*D; // -1 だけで全部片付けるとき
    if(ans<0) ans = INF; // オーバーフローした場合はどうせダメなのでINFにしておく（やばそう）

    lint p[3] = {2,3,5};
    lint q[3] = {A,B,C};
    rep(i,3){ // 2,3,5それぞれに対して
        lint tmp = q[i] + D*(n%p[i]) + rec(n/p[i]); //割り切れる時は割る, 割り切れない時は余りを引いて割る
        if(n%p[i]) tmp = min(tmp, q[i] + D*(p[i]-n%p[i]) + rec(n/p[i]+1)); //割り切れない時は (除数-余り) を足して割るのも試す
        ans = min(ans, tmp);
    }

    mp[n] = ans; // 結果を記録しておく
    return ans;
}

