ll dp(ll x) {
  if (done[x]) return memo[x];
  if (x == 0) return 0;
  if (x == 1) return d;

  ll res = INFll;
  if (ld(res)/d - 1 >= x) res = d*x;
  chmin(res, dp(x/2) + (x%2)*d + a);
