ll d(ll n) {
  if (!n)
    return 0;
  else if (m[n])
    return m[n];
  ll ret = min({
      A + n % 2 * D + d(n / 2),
      A + (2 - n % 2) % 2 * D + d((n + 1) / 2),
      B + n % 3 * D + d(n / 3),
      B + (3 - n % 3) % 3 * D + d((n + 2) / 3),
      C + n % 5 * D + d(n / 5),
      C + (5 - n % 5) % 5 * D + d((n + 4) / 5)
    });
  if ((double)D * n < 1e18) ret = min(D * n, ret);
  return m[n] = ret;
}

