ll solve(ll x) {
	if (mem.count(x)) return mem[x];
	mem[x] = INF;
	if (x < (ll)3e9) mem[x] = x * D;
	for (ll y = x - 2; y <= x + 2; y++) {
		if (y <= 0) continue;
		ll cur = D * abs(x - y);
		if (cur + A < mem[x] && y % 2 == 0) mem[x] = min(mem[x], cur + A + solve(y / 2));
		if (cur + B < mem[x] && y % 3 == 0) mem[x] = min(mem[x], cur + B + solve(y / 3));
		if (cur + C < mem[x] && y % 5 == 0) mem[x] = min(mem[x], cur + C + solve(y / 5));
	}
	return mem[x];
}

