void solve(){
  ll n,a,b,c,d;
  std::cin>>n>>a>>b>>c>>d;

  constexpr ll INF=1e18;

  std::map<ll,ll> memo;
  auto dp=[&](auto f,ll num)->ll{
    if(num==0)return 0;
    if(memo[num]!=0)return memo[num];

    ll val=INF;
    ll arr[3]={2,3,5};
    ll cost[3]={a,b,c};
    rep(i,0,3){
      ll down=num/arr[i];
      ll up=(num+arr[i]-1)/arr[i];
      if(down!=num)chmin(val,f(f,down)+d*std::abs(num-down*arr[i]) + (down>0 ? cost[i]:0));
      if(up!=num)chmin(val,f(f,up)+d*std::abs(num-up*arr[i]) + (up>0?cost[i]:0));
    }

    if(d<=val/num)chmin(val,d*num);

    return memo[num]=val;
  };

  dp(dp,n);

  std::cout<<dp(dp,n)<<"\n";

  for(const auto& [key,val]:memo)debug(key,val);
}

