ll cost(ll x,ll a,ll b,ll c,ll d,int ctr){
    if(x==1) return d;
    if(memo.count(x)) return memo[x];
    ll cand=INF;
    if(x%2ll==0) chmin(cand,a+cost(x/2,a,b,c,d,1));
    else {
        chmin(cand,d+a+cost(x/2,a,b,c,d,1));
        chmin(cand,d+a+cost((x+1)/2,a,b,c,d,1));
    }
    if(x==2||ctr==1) return cand;
    if(x%3ll==0) chmin(cand,b+cost(x/3,a,b,c,d,2));
    else if(x%3ll==1){
        chmin(cand,d+b+cost(x/3,a,b,c,d,2));
        chmin(cand,d+d+b+cost((x+2)/3,a,b,c,d,2));
    }
    else{
        chmin(cand,d+d+b+cost(x/3,a,b,c,d,2));
        chmin(cand,d+b+cost((x+1)/3,a,b,c,d,2));
    }
    if(x<5||ctr==2) return cand;
    if(x%5ll==0) chmin(cand,c+cost(x/5,a,b,c,d,3));
    else if(x%5ll==1){
        chmin(cand,d+c+cost(x/5,a,b,c,d,3));
        chmin(cand,d*4+c+cost((x+4)/5,a,b,c,d,3));
    }
    else if(x%5ll==2){
        chmin(cand,d+d+c+cost(x/5,a,b,c,d,3));
        chmin(cand,d+d+d+c+cost((x+3)/5,a,b,c,d,3));
    }
    else if(x%5ll==3){
        chmin(cand,d+d+d+c+cost(x/5,a,b,c,d,3));
        chmin(cand,d+d+c+cost((x+2)/5,a,b,c,d,3));
    }
    else{
        chmin(cand,d+c+cost((x+1)/5,a,b,c,d,3));
        chmin(cand,d*4+c+cost(x/5,a,b,c,d,3));
    }
    memo[x]=cand;
    return cand;
}
