	if (n % 3 == 0) solve1(n/3,now+b); else solve1(n/3,now+d*(n%3)+b),solve1(n/3+1,now+d*(3-n%3)+b);
	if (n % 5 == 0) solve1(n/5,now+c); else solve1(n/5,now+d*(n%5)+c),solve1(n/5+1,now+d*(5-n%5)+c);
