        // cost = min(cost,costs[i]+D*(up-n)+solve(n/arr[i]+1));

        ll g = n/arr[i];
		ll up = n - g*arr[i];
		cost = min(cost,D*up + costs[i]+solve(n/arr[i]));
		ll d = (g+1)*arr[i]-n;
		cost = min(cost,D*d + costs[i]+solve(n/arr[i]+1));
	}
}

return dp[n] = cost;
}

