void solve() {
    LL N, A, B, C, D;
    cin >> N >> A >> B >> C >> D;
    unordered_map<LL, LL> dist;
    auto cmp = [](const pair<LL, LL>& x, const pair<LL, LL>& y) {
        return x.second > y.second;
    };
    priority_queue<pair<LL, LL>, vector<pair<LL, LL>>, decltype(cmp)> Q(cmp);
    auto insertQ = [&](LL n, LL d) {
        if(not dist.count(n) or dist[n] > d) {
            dist[n] = d;
            Q.emplace(n, d);
        }
    };
    insertQ(N, 0);
    while(Q.size()) {
        auto t = Q.top();
        Q.pop();
        LL n = t.first;
        LL d = t.second;
        if(n == 0) {
            cout << d << "\n";
            return;
        } else if(n == 1) {
            cout << (d + D) << "\n";
            return;
        }
        if(double(n) * double(D) <= 1e18) {
            insertQ(0, d + n * D);
        }
        if(n % 2 == 0) {
            insertQ(n / 2, d + A);
        } else {
            insertQ(n / 2, d + A + D);
            insertQ(n / 2 + 1, d + A + D);
        }
        if(n % 3 <= 1) {
            insertQ(n / 3, d + B + (n % 3) * D);
        } else {
            insertQ(n / 3 + 1, d + B + D);
        }
        if(n % 5 <= 2) {
            insertQ(n / 5, d + C + (n % 5) * D);
        } else {
            insertQ(n / 5 + 1, d + C + (5 - (n % 5)) * D);
        }
    }
}

