long long int subsolve(long long int n){
    if(n <= 1) return n ? d : 0;
    if(const auto itr = dp.find(n); itr != dp.end()) return itr -> second;
    long long int res = INT64_MAX;
    if(n < INT64_MAX / d) chmin(res, n * d);
    chmin(res, solver(n, 2, a));
    chmin(res, solver(n, 3, b));
    chmin(res, solver(n, 5, c));
    return dp[n] = res;
}

long long int solver(const long long int n, const int div, const int x){
    const long long int p = n / div, q = n % div;
    if(!q) return subsolve(p) + x;
    const long long int koho1 = subsolve(p) + x + q * d;
    const long long int koho2 = subsolve(p + 1) + x + (div - q) * d;
    return (koho1 < koho2) ? koho1 : koho2;
}

