const ll inf=4e18;
map<ll,ll>f;
ll dfs(ll x){
	if(!x)return 0;
	if(f[x])return f[x];
	ll res=x>inf/d?inf:x*d;
	for(register int i=0;i<3;i++){
		ll y=x/dv[i];
		res=min(res,dfs(y)+w[i]+(x-y*dv[i])*d);
		y=(x+dv[i]-1)/dv[i];
		res=min(res,dfs(y)+w[i]+(y*dv[i]-x)*d);
	}
	return f[x]=res;
}
