const int N = 1e7;
int mem[N];

map<int, int> big;
int dp(int n) {
	if (n == 0) return 0;
	if (n < N) {
		if (mem[n] != -1) return mem[n];
	} else if (big.count(n)) return big[n];
	int rez = 1e18;
	if (n <= 1e18 / cost[3])
		rez = n * cost[3];
	for (int i = 0; i < 3; i++) {
		{
			int sub = n / nums[i];
			rez = min(rez, dp(sub) + (n % nums[i]) * cost[3] + cost[i]);
		}
		if (n % nums[i] != 0) {
			int sub = n / nums[i] + 1;
			if (sub < n) {
				rez = min(rez, dp(sub) + (nums[i] - (n % nums[i])) * cost[3] + cost[i]);
			}
		}
	}
	if (n < N) {
		mem[n] = rez;
	} else {
		big[n] = rez;
	}
	return rez;
}

void solve() {
	int n;
	cost.assign(4, 0);
	memset(mem, -1, sizeof mem);
	big.clear();
	scan n, cost;
	print dp(n);
