  chmin( ret, rec( n/5 )+C+(n%5)*D );
  chmin( ret, rec( (n+4)/5 )+C+(5-(n%5))*D );

  if( n < ret/D )
    chmin( ret, n*D );

  return memo[n] = ret;
}

