    if(n==0) return dp[n]=0;
    dp[n]=LLONG_MAX;
    if(n<=LLONG_MAX/d) dp[n]=n*d;
    for(auto x:xs) {
        ll nn=n/x*x;
        ll tmp;
        if(nn>0) {
            tmp=abs(n-nn)*d+vs[x]+dp_cal(nn/x);
            mini(dp[n],tmp);
        }
        if(nn!=n) {
            nn+=x;
            tmp=abs(n-nn)*d+vs[x]+dp_cal(nn/x);
            mini(dp[n],tmp);
        }
    }
    return dp[n];
}

