map<LLONG, LLONG> num2MinCostMap;
LLONG costs[3];
LLONG ks[3];
LLONG N, D;

const LLONG Digit(LLONG n)
{
    LLONG ret = 0;
    while (n)
    {
        n /= 10;
        ++ret;
    }
    return ret;
}

const LLONG DFS(const LLONG n)
{
    if (num2MinCostMap.count(n)) return num2MinCostMap[n];
    LLONG minCost = Digit(n) * Digit(D) > 18 ? 1145141919810364364LL : n * D;
    for (int i = 0; i < 3; ++i)
    {
        const LLONG k = ks[i];
        const LLONG lower = n / k;
        const LLONG upper = lower + 1;
        minCost = min(minCost,
            min(DFS(lower) + costs[i] + (n - lower * k) * D,
                DFS(upper) + costs[i] + (upper * k - n) * D));
    }
    return num2MinCostMap[n] = minCost;
}

void Solve()
{
    cin >> N >> costs[0] >> costs[1] >> costs[2] >> D;
    num2MinCostMap.clear();
    num2MinCostMap[0] = 0;
    num2MinCostMap[1] = D;
    num2MinCostMap[2] = min(D * 2, D + costs[0]);
    ks[0] = 2, ks[1] = 3, ks[2] = 5;
    cout << DFS(N) << endl;
}

