				//cout << "cexacttmp:" << cexacttmp << endl;
			}
			else {
				long long cup = (k + (5 - cm)) / 5;
				long long cdown = (k - cm) / 5;
				long long cuptmp, cdowntmp;
				if ((k - cup) < (tc.at(i).at(3) + tc.at(i).at(4) * (5 - cm)) / tc.at(i).at(4))cuptmp = dp[k] + (k - cup) * tc.at(i).at(4);
				else cuptmp = dp[k] + tc.at(i).at(3) + tc.at(i).at(4) * (5 - cm);
				if (dp.count(cup))dp.at(cup) = min(dp.at(cup), cuptmp);
				else dp[cup] = cuptmp;
				q.push(cup);
				if ((k - cdown) < (tc.at(i).at(3) + tc.at(i).at(4) * cm) / tc.at(i).at(4))cdowntmp = dp[k] + (k - cdown) * tc.at(i).at(4);
				else cdowntmp = dp[k] + tc.at(i).at(3) + tc.at(i).at(4) * cm;
				if (dp.count(cdown))dp.at(cdown) = min(dp.at(cdown), cdowntmp);
				else dp[cdown] = cdowntmp;
				q.push(cdown);
				//cout << "cuptmp:" << cuptmp << endl;
				//cout << "cdowntmp:" << cdowntmp << endl;
			}
			discovered.insert(k);
			q.pop();
		}
		cout << dp.at(1)+tc.at(i).at(4) << endl;
	}
}

