ll n, p[4], cn;
map<ll, ll> dp;
vector<int> divs = {2, 3, 5};

string to_str (ll x)
{
  string res;
  while (x)
  {
    res += (x % 10) + '0';
    x /= 10;
  }
  reverse(ALL(res));
  return res;
}

ll go (ll cn)
{
  if (!cn) return 0;
  if (cn == 1) return p[3];
  if (dp.count(cn)) return dp[cn];
  ll res = cn * p[3];
  FOR(i, 0, 3)
  {
    if (!(cn % divs[i])) res = min(res, p[i] + go(cn / divs[i]));
    else
    {
      ll md = cn % divs[i];
      ll imd = divs[i] - md;
      res = min({res, md * p[3] + p[i] + go((cn - md) / divs[i]), imd * p[3] + p[i] + go((cn + imd) / divs[i])});
    }
  }
  return dp[cn] = res;
}


void solve ()
{
  dp.clear();
  long long int N, P[4];
  R(N);
  FOR(i, 0, 4) R(P[i]);
  n = N;
  FOR(i, 0, 4) p[i] = P[i];
  cout << to_str(go(n)) << endl;
}

int main ()
{
  init_io();
  int t = 1;
  R(t);
  while (t--) solve();
  return 0;
}

