#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MAX = 1e7 + 10;
const ll INF = 9e18;

int T;
ll N, A, B, C, D;
ll f[MAX], n = 1e7;
map<ll, ll> mp;

ll dp(ll x) {
    if (x <= n) return f[x];
    if (mp.count(x)) return mp[x];
    ll res = INF;
    if (res / D > N) res = N * D;
    res = min(res, (x % 2) * D + A + dp(x / 2));
    res = min(res, (2 - x % 2) * D + A + dp((x + 1) / 2));

    res = min(res, (x % 3) * D + B + dp(x / 3));
    res = min(res, (3 - x % 3) * D + B + dp((x + 2) / 3 + 1));

    res = min(res, (x % 5) * D + C + dp(x / 5));
    res = min(res, (5 - x % 5) * D + C + dp((x + 4) / 5 + 1));


    return mp[x] = res;
}

int main() {
#ifdef ACM_LOCAL
    freopen("input.in", "r", stdin);
    freopen("output.out", "w", stdout);
#endif
    cin >> T;
    while (T--) {
        mp.clear();
        cin >> N >> A >> B >> C >> D;
        memset(f, 0x3f, sizeof(f)); f[0] = 0;
        for (int i = 1; i <= n; i++) {
            f[i] = min(f[i], f[i - 1] + D);
            if (i % 2 == 0) f[i] = min(f[i], f[i / 2] + A);
            if (i % 3 == 0) f[i] = min(f[i], f[i / 3] + B);
            if (i % 5 == 0) f[i] = min(f[i], f[i / 5] + C);
        }
        cout << dp(N) << endl;
    }

    return 0;
}

