#define MAX(a, b) (((a) < (b)) ? (b) : (a))

std::map<ll,ll> dp;
std::set<ll> pq;

ll const inf = 1000000000000000000;

void update(ll pos, ll val) {
  pq.insert(pos);
  if(dp.find(pos) == dp.end())
    dp[pos] = val;
  else
    dp[pos] = std::min(dp[pos], val);
}

void solve() {
  dp.clear();
  pq.clear();

  ll n, a, b, c, d;
  std::cin >> n >> a >> b >> c >> d;
  ll result = inf;
  dp[n] = 0; 
  pq.insert(n);

  while(0 < pq.size()) {
    std::set<ll>::iterator it = pq.end();
    it--;
    ll node = *it;
    pq.erase(it);
    if(d <= inf / node)
      result = std::min(result, dp[node] + d * node);

    if(node < 2)
      break;

    int rest = node % 2;

    update((node - rest) / 2, dp[node] + rest * d + a);
    update((node + (2 - rest) % 2) / 2, dp[node] + (2 - rest) % 2 * d + a);

    rest = node % 3;
    update((node - rest) / 3, dp[node] + rest * d + b);
    update((node + (3 - rest) % 3) / 3, dp[node] + (3 - rest) % 3 * d + b);

    rest = node % 5;
    update((node - rest) / 5, dp[node] + rest * d + c);
    update((node + (5 - rest) % 5) / 5, dp[node] + (5 - rest) % 5 * d + c);

  }
  std::cout << result << '\n';
}

int main() {
  int t;
