map<ll, ll> memo;
ll a; VL cost(6);

ll dfs(ll n) {
	if (memo.count(n)) {
		return memo[n];
	} else if (n == 0) {
		return memo[n] = 0;
	} else if (n == 1) {
		return memo[n] = a;
	}
	ll res = inf_ll;
	for (ll d : {2, 3, 5}) {
		for (ll m : {n / d * d, Ceil2(n, d)}) {
			ll c = abs(n - m) * a + cost[d];
			ll A = abs(n - m / d);
			if (a < Ceil(c, A)) {
				chmin(c, A * a);
			}
			chmin(res, dfs(m / d) + c);
		}
	}
	return memo[n] = res;
}

void solve(ll n) {
	out(dfs(n));
}

int main() {
	for (int t = in; t--;) {
		ll n = in;
		in(cost[2], cost[3], cost[5]);
		in(a);
		memo.clear();
		solve(n);
	}
}

