long long int CalcMinCost(long long int& num, long long int& A, long long int& B, 
                            long long int& C, long long int& D, vector<long long int>& record_cost) {
    long long int min_cost = 0;

    if (num < 10000 && record_cost[num] != 0) {
        return record_cost[num];
    }

    long long int reminder_5 = num % 5;
    long long int divide_5_plus = num / 5;
    long long int divide_5_minus = num / 5 + 1;

    long long int min_cost_5 = 0;
    if (divide_5_plus == 0 || divide_5_plus < (C / (4 * D) + 1)) {
        min_cost_5 = D * num;
    } else {
        min_cost_5 = D * reminder_5 + C + CalcMinCost(divide_5_plus, A, B, C, D, record_cost);
    }

    if (divide_5_plus != 0 && reminder_5 != 0) {
        long long int min_cost_5_minus = 0;
        if (divide_5_minus + 1 < (C / (4 * D) + 1)) {
            min_cost_5_minus = D * num;
        } else {
            min_cost_5_minus = D * (5 - reminder_5) + C + CalcMinCost(divide_5_minus, A, B, C, D, record_cost);
        }
        min_cost_5 = min(min_cost_5, min_cost_5_minus);
    }

    min_cost = min_cost_5;

    long long int reminder_3 = num % 3;
    long long int divide_3_plus = num / 3;
    long long int divide_3_minus = num / 3 + 1;

    long long int min_cost_3 = 0;
    if (divide_3_plus == 0 || divide_3_plus < (B / (2 * D) + 1)) {
        min_cost_3 = D * num;
    } else {
        min_cost_3 = D * reminder_3 + B + CalcMinCost(divide_3_plus, A, B, C, D, record_cost);
    }

    if (divide_3_plus != 0 && reminder_3 != 0) {
        long long int min_cost_3_minus = 0;
        if (divide_3_minus + 1 < (C / (2 * D) + 1)) {
            min_cost_3_minus = D * num;
        } else {
            min_cost_3_minus = D * (3 - reminder_3) + B + CalcMinCost(divide_3_minus, A, B, C, D, record_cost);
        }
        min_cost_3 = min(min_cost_3, min_cost_3_minus);
    }

    min_cost = min(min_cost, min_cost_3);

    long long int reminder_2 = num % 2;
    long long int divide_2_plus = num / 2;
    long long int divide_2_minus = num / 2 + 1;

    long long int min_cost_2 = 0;
    if (divide_2_plus == 0 || divide_2_plus < (A / D + 1)) {
        min_cost_2 = D * num;
    } else {
        min_cost_2 = D * reminder_2 + A + CalcMinCost(divide_2_plus, A, B, C, D, record_cost);
    }

    if (divide_2_plus != 0 && reminder_2 != 0) {
        long long int min_cost_2_minus = 0;
        if (divide_2_minus + 1 < (A / D + 1)) {
            min_cost_2_minus = D * num;
        } else {
            min_cost_2_minus = D * (2 - reminder_2) + B + CalcMinCost(divide_2_minus, A, B, C, D, record_cost);
        }
        min_cost_2 = min(min_cost_2, min_cost_2_minus);
    }

    min_cost = min(min_cost, min_cost_2);

    if (num < 10000) {
        record_cost[num] = min_cost;
    }

    return min_cost;
}

int main() {
    int T;
    cin >> T;

    for (int i = 0; i < T; ++i) {
        long long int N, A, B, C, D;
        cin >> N >> A >> B >> C >> D;

        vector<long long int> record_cost(10000);

        record_cost[1] = D;
        record_cost[2] = min(2 * D, D + A);
        record_cost[3] = min(3 * D, min(2 * D + A, D + B));

        cout << CalcMinCost(N, A, B, C, D, record_cost) << endl;
    }
}

