// Commonly used functions
inline i64 gcd(i64 a, i64 b) { // Use __gcd(a, b) instead for int
	i64 r;
	while (b) {
		r = a % b; a = b; b = r;
	}
	return a;
}

inline i64 lcm(i64 a, i64 b) {
	return (a / gcd(a, b) * b);
}

inline i64 fpow(i64 a, i64 b, i64 m = mod) {
	i64 r = 1;
	for (; b > 0; b >>= 1) {
		if (b & 1) r = r * a % m;
		a = a * a % m;
	}
	return r;
}

inline void addmod(int &a, int val, int m = mod) {
	if ((a = a + val) >= m) a -= m;
}

inline void submod(int &a, int val, int m = mod) {
	if ((a = a + val) < 0) a += m;
}

inline int mult(int a, int b, int m = mod) {
	return (i64) a * b % m;
}

inline int inv(int a, int m = mod) {
	return fpow(a, m - 2, m);
}

inline bool isPrime(i64 x) {
	if (x <= 3) return (x >= 2);
	if (x % 2 == 0 || x % 3 == 0) return false;
	for (i64 i = 5; i * i <= x; i += 6) {
		if (x % i == 0 || x % (i + 2) == 0) return false;
	}
	return true;
}

