void solve() {
	i64 a, b, c, d, n;
	cin >> n >> a >> b >> c >> d;
	vector<pair<int, i64> > ops;
	ops.eb(2, a); ops.eb(3, b); ops.eb(5, c);

	map<i64, i64> mp;
	mp[0] = 0;
	mp[1] = d;

	function<i64(i64)> dfs = [&](i64 x) {
		if (mp.find(x) != mp.end()) return mp[x];
		i64 res = ool;
		if ((lld) d * (lld) x < res) res = d * x;
		trav(p, ops) {
			int num = p.fi;
			i64 cost = p.se;
			res = min(res, dfs(x / num) + cost + d * (x % num));
			if (x % num != 0) {
				res = min(res, dfs(x / num + 1) + cost + d * (num - x % num));
			}
		}
		return mp[x] = res;
	};

	cout << dfs(n) << '\n';
}

