ll a, b, c, d;

map<ll, ll> ans;

ll solve(ll n)
{
    if (ans.find(n)!=ans.end()) return ans[n];
    if (n==0)
    {
        return 0;
    }
    if (n==1)
    {
        return d;
    }
    ll minn = 1e18;
    if (d<=minn/n) minn = min(minn, d*n);
    if (n%2==0) minn = min(minn, solve(n/2) + a);
    else
    {
        minn = min(minn, d*(n%2) + a + solve(n/2));
        minn = min(minn, d*(2 - n%2) + a + solve(1 + n/2));
    }

    if (n%3==0) minn = min(minn, solve(n/3) + b);
    else
    {
        minn = min(minn, d*(n%3) + b + solve(n/3));
        minn = min(minn, d*(3 - n%3) + b + solve(1 + n/3));
    }

    if (n%5==0) minn = min(minn, solve(n/5) + c);
    else
    {
        minn = min(minn, d*(n%5) + c + solve(n/5));
        minn = min(minn, d*(5 - n%5) + c + solve(1 + n/5));
    }

    ans[n] = minn;
    return minn;

}

void solve()
{
    ans.clear();
    ll n;
    cin>>n>>a>>b>>c>>d;
    cout<<solve(n)<<endl;
}

