ll gcd(ll n, ll m)
{
	ll tmp;
	while (m != 0)
	{
		tmp = n % m;
		n = m;
		m = tmp;
	}
	return n;
}

ll lcm(ll n, ll m)
{
	return abs(n) / gcd(n, m) * abs(m); //gl=xy
}

using namespace std;
//using namespace atcoder;
map<ll,ll>mp;
ll n,A,B,C,D;

ll rec(ll num){
	if(num==0)return 0LL;
	if(num==1)return D;
	if(mp.find(num)!=mp.end())return mp[num];

	ll res;
	if(log10(num)+log10(D)>log10(INF))res=INF;
	else res=num*D;
	if(num%2==0){
		chmin(res,rec(num/2)+A);
	}
	else{
		chmin(res,min(rec(num/2),rec(num/2+1))+A+D);
	}
	if(num%3==0){
		chmin(res,rec(num/3)+B);
	}
	else{
		chmin(res,min(rec(num/3)+B+D*(num%3),rec(num/3+1)+B+D*(3-num%3)));
	}
	if(num%5==0){
		chmin(res,rec(num/5)+C);
	}
	else{
		chmin(res,min(rec(num/5)+C+D*(num%5),rec(num/5+1)+C+D*(5-num%5)));
	}
	return mp[num]=res;
}


