int factorization(int64_t n, int a){
    int m=0;
    while(n%a==0){
        n /= a;
        m++;
    }
    return m;
}

int main(){
    int T;
    cin >> T;
    int64_t n, a, b, c, d, minimum;

    for(int t=0;t<T;t++){
        cin >> n >> a >> b >> c >> d;
        if(n==1){
            cout << d << endl;
            continue;
        }
        int64_t nn, aa, bb, cc, count, N;
        count = 0;
        for(int64_t i=-pow(10,5);i<pow(10,5);i++){
            nn = n + i;

            if(nn<0 || (n%2!=0 && n%3!=0 && n%5!=0)){
                continue;
            }

            aa = factorization(nn,a);
            bb = factorization(nn,b);
            cc = factorization(nn,c);

            N = aa*a + bb*b + cc*c + (abs(i)+1)*d;

            if(count == 0){
                minimum = N;
            }else{
                minimum = min(N,minimum);
            }
        }
        cout << minimum << endl;
    }

    return 0;
}

