using namespace std;
typedef unsigned long long ull;
ull a, b, c, d;
map<ull, ull> dp;

ull solve(ull n) {
	if (dp.count(n)) return dp[n];
	ull ret = d*n;
	ret = min(ret, solve(n/2) + min(a+d*(n%2), d*(n-n/2)));
	if (n % 2) ret = min(ret, solve(n/2+1) + min(a+d, d*(n-n/2-1)));

	ret = min(ret, solve(n/3) + min(b+d*(n%3), d*(n-n/3)));
	if (n % 3) ret = min(ret, solve(n/3+1) + min(b+d*(3-n%3), d*(n-n/3-1)));

	ret = min(ret, solve(n/5) + min(c+d*(n%5), d*(n-n/5)));
	if (n % 5) ret = min(ret, solve(n/5+1) + min(c+d*(5-n%5), d*(n-n/5-1)));

	return dp[n] = ret;
}

