map<ll,ll> mp;
ll a,b,c,d;

ll dfs(ll x){
    if(x==0) return 0;
    if(x==1) return d;
    if(mp.count(x)) return mp[x];
    if(x<=LINF/d) mp[x]=x*d;
    else mp[x]=LINF;

    // chmin
    for(ll i=-4; i<=4; i++){
