const int64_t INF = 5e18;

int32_t a, b, c, d;
std::map< int64_t, int64_t > dp;

int64_t calc_dp(int64_t x) {
	if(x == 1) {
		return d;
	}
	else if(dp.count(x) != 0) {
		return dp[x];
	}

	dp[x] = INF;

	if(x < INF / d) {
		dp[x] = x * d;	
	}

	std::vector< int32_t > mults = { 2, 3, 5 };
	std::vector< int32_t > costs = { a, b, c };

	for(int32_t i = 0; i < 3; i++) {
		int32_t mult = mults[i];
		int32_t cost = costs[i];

		if(x % mult == 0) {
			dp[x] = std::min(dp[x], calc_dp(x / mult) + cost);
		}
		else {
			int64_t down = x / mult * mult;
			dp[x] = std::min(dp[x], calc_dp(down / mult) + cost + (x - down) * d);
			int64_t up = down + mult;
			dp[x] = std::min(dp[x], calc_dp(up / mult) + cost + (up - x) * d);
		}
	}

	return dp[x];
}

