	else res=min(res,solve(x/3+1)+b+(x1+3-x)*d);
	if(x%2==0)res=min(res,solve(x/2)+a);
	else
	{
		res=min(res,solve(x/2)+a+d);
		res=min(res,solve(x/2+1)+a+d);
	}
	return dp[x]=res;
}
