ll a, b, c, d, n;

Pll f(ll prev_cost, ll prev_n,  ll base, bool increase) {
    ll next_n, cost;
    if(increase) {
        next_n = (prev_n + base - 1) / base;
        cost = prev_cost + ((base - prev_n % base) % base) * d;
    } else {
        next_n = prev_n / base;
        cost = prev_cost + prev_n % base * d;
    }
    if(next_n) cost += ((base==2)?a:((base==3)?b:c));
    return { cost, next_n };
}

void solve() {
