class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    ll N, A, B, C, D;
    bool input() {
        is >> N >> A>> B >> C >> D;
        return !!is;
    }

    ll dfs(ll x){
        if(x == 0) return 0;
        ll ans = INFLL;
        ll d5 = x%5;
        ll d3 = x%3;
        ll d2 = x%2;

        UPMIN(ans, dfs((x - d5)/5) + C + D*d5);
        UPMIN(ans, dfs2(x));
        return ans;
    }

    ll dfs2(ll x){
        if(x == 0) return 0;
        ll ans = INFLL;
        ll d3 = x%3;
        UPMIN(ans, dfs2((x - d3)/3) + B + D*d3);
        UPMIN(ans, dfs3(x));

        return ans;
    }

    ll dfs3(ll x){
        if(x == 0) return 0;
        ll ans = INFLL;
        if(x < INFLL/D)  ans = x*D;
        ll d2 = x%2;
        UPMIN(ans, dfs3((x - d2)/2) + A + D*d2);

        return ans;
    }


    void run();
};

