const int INF = 3e18 + 239;

map<int, int> mem;

int rec(int x, int a, int b, int c, int d) {
	// cerr << x << ' ' << cur << endl;
	if (mem.count(x)) return mem[x];
	if (x == 0) {
		return 0;
	}
	if (x == 1) {
		return d;
	}
	int cur = INF;
	{
		int f = (x / 5) * 5;
		for (int to = f; to <= f + 5; to += 5) {
			cur = min(cur, d * abs(x - to) + c + rec(to / 5, a, b, c, d));
		}
	}
	{
		int f = (x / 3) * 3;
		for (int to = f; to <= f + 3; to += 3) {
			cur = min(cur, d * abs(x - to) + b + rec(to / 3, a, b, c, d));
		}
		// rec(x / 3, a, b, c, d, cur + abs(x - f * 3) * d, ans);
		// rec(x / 3 + 1, a, b, c, d, cur + abs(x - (f + 1) * 3) * d, ans);
	}
	{
		if (x % 2 == 0) {
			cur = min(cur, a + rec(x / 2, a, b, c, d));
		} else {
			cur = min(cur, d + a + rec(x / 2, a, b, c, d));
			cur = min(cur, d + a + rec(x / 2 + 1, a, b, c, d));
		}
	}
	if (d < INF / x) {
		cur = min(cur, x * d);
	}
	mem[x] = cur;
	return mem[x];
}

