#define pll pair<LL,LL>
priority_queue<pll >Q;
LL n,A,B,C,D,ans;
inline void rw(LL x,LL w){if(!F.count(x))F[x]=INF;if(F[x]>w)F[x]=w,Q.push(mp(-w,x));}
inline void dfs5(LL x,LL now,bool ok=false){
	while(x%5==0){
		if(ok) rw(x,now);
		x/=5,now+=C,ok=true;
	}
	if(ok) rw(x,now);
}
inline void dfs3(LL x,LL now,bool ok=false){
	while(x%3==0) dfs5(x,now,ok),x/=3,now+=B,ok=true;
	dfs5(x,now,ok);
}
inline void dfs2(LL x,LL now,bool ok=false){
	while(!(x&1)) dfs3(x,now),x>>=1,now+=A,ok=true;
	dfs3(x,now,ok);
}
inline LL solve(){
	F.clear(),vis.clear(); while(!Q.empty()) Q.pop(); ans=INF;
	n=read(),A=read(),B=read(),C=read(),D=read(),F[n]=0,Q.push(mp(0,n));
	// debug(ans)el;
	while(!Q.empty()){
		LL x=Q.top().second; Q.pop(); if(vis[x]) continue; vis[x]=true;
		if(INF/x>=D) ans=min(ans,x*D+F[x]);
		// debug(x)sp,debug(F[x])sp,debug(x*D+F[x])sp,debug(ans)el;
		if(x==n) dfs2(x,F[x]);
		if(x-1>0) dfs2(x-1,F[x]+D);
		if(x-2>0) dfs3(x-2,F[x]+D+D);
		if(x-3>0) dfs5(x-3,F[x]+D+D+D);
		if(x-4>0) dfs5(x-4,F[x]+D+D+D+D);
		dfs2(x+1,F[x]+D);
		dfs3(x+2,F[x]+D+D);
		dfs5(x+3,F[x]+D+D+D);
		dfs5(x+4,F[x]+D+D+D+D);
	}
	return ans;
}
