      ans = min(ans, Solve(now / 3) + B + abs(i) * D);
      ll Lim = (INF - Solve(now / 3)) / D;
      ll deg = abs(now / 3 - num);
      if (deg <= Lim){
        ans = min(ans, Solve(now / 3) + deg * D);
      }
