using namespace std;

int T;
unsigned long N;
unsigned int A, B, C, D;

unsigned long calcu(unsigned long n) {
  if(n == 1) return D;
  if(n == 0) return 0;
  int rest2 = n % 2;
  int rest3 = n % 3;
  int rest5 = n % 5;

  int next = 2;
  int minCost = A + (D * rest2);

  int temp = (rest3 == 0) ? B : (B + D);
  if(minCost > temp) {
    minCost = temp;
    next = 3;
  }

  if(rest5 == 0) temp = C;
  else if(rest5 == 1 || rest5 == 4) temp = C + D;
  else temp = C + (D * 2);
  if(minCost > temp) {
    minCost = temp;
    next = 5;
  }
  //cout << "next : " << next << endl;
  unsigned long restCost = 0;
  if(next == 2) {
    if(rest2 == 0) {
      restCost = calcu(n / 2);
    } else {
      unsigned long cost2p = calcu((n + 1) / 2);
      unsigned long cost2m = calcu((n - 1) / 2);
      restCost = ((cost2p > cost2m) ? cost2m : cost2p);
    }
  } else if(next == 3) {
    if(rest3 == 0) {
      restCost = calcu(n / 3);
    } else if(rest3 < 2) {
      restCost = calcu((n - 1) / 3);
    } else {
      restCost = calcu((n + 1) / 3);
    }
  } else {
    if(rest5 == 0) {
      restCost = calcu(n / 5);
    } else if(rest5 < 3) {
      restCost = calcu((n - rest5) / 5);
    } else {
      restCost = calcu((n + 5 - rest5) / 5);
    }
  }
  return minCost + restCost;
}

int main() {
  cin >> T;
  for (int i = 0; i < T; i++) {
    cin >> N >> A >> B >> C >> D;
    cout << calcu(N) << endl;
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
ull a, b, c, d;
map<ull, ull> dp;

ull solve(ull n) {
	if (dp.count(n)) return dp[n];
	if (n <= 0) return 0;
	if (n == 1) return d;
	ull ret = d*n;
	ret = min(ret, solve(n/2) + min(a+d*(n%2), d*(n-n/2)));
	if (n % 2) ret = min(ret, solve(n/2+1) + min(a+d, d*(n-n/2-1)));

	ret = min(ret, solve(n/3) + min(b+d*(n%3), d*(n-n/3)));
	if (n % 3) ret = min(ret, solve(n/3+1) + min(b+d*(3-n%3), d*(n-n/3-1)));

	ret = min(ret, solve(n/5) + min(c+d*(n%5), d*(n-n/5)));
	if (n % 5) ret = min(ret, solve(n/5+1) + min(c+d*(5-n%5), d*(n-n/5-1)));

	return dp[n] = ret;
}

int main()
{
	int T; scanf("%d", &T);
	while (T--) {
		dp.clear();
		ull n; scanf("%llu%llu%llu%llu%llu", &n, &a, &b, &c, &d);
		printf("%llu\n", solve(n));
	}
	return 0;
}

