S M<ll, ll> cache;

ll solve(ll n, ll a, ll b, ll c, ll d)
{
    //debug_printf("solve n=%lld\n", n);
    //sleep(0.1);

    if (!n) return 0LL;
    if (cache.find(n) != cache.end()) return cache[n];

    ll ret = LONG_MAX;

    ll base = n * d;
    if (base / d == n && base > 0LL) ret = min(ret, base);

    ll nn, step;

    nn = n / 2LL;
    step = abs(nn * 2LL - n);
    ret = min(ret, solve(nn, a, b, c, d) + step * d + a);

    if (n % 2LL && n != 1LL) {
        nn++;
        step = abs(nn * 2LL - n);
        ret = min(ret, solve(nn, a, b, c, d) + step * d + a);
    }

    nn = n / 3LL;
    step = abs(nn * 3LL - n);
    ret = min(ret, solve(nn, a, b, c, d) + step * d + b);

    if (n % 3LL && n != 1LL) {
        nn++;
        step = abs(nn * 3LL - n);
        ret = min(ret, solve(nn, a, b, c, d) + step * d + b);
    }

    nn = n / 5LL;
    step = abs(nn * 5LL - n);
    ret = min(ret, solve(nn, a, b, c, d) + step * d + c);

    if (n % 5LL && n != 1LL) {
        nn++;
        step = abs(nn * 5LL - n);
        ret = min(ret, solve(nn, a, b, c, d) + step * d + c);
    }

    return cache[n] = ret;
}

void solve()
{
    ll n; llin(n);
    ll a; llin(a);
    ll b; llin(b);
    ll c; llin(c);
    ll d; llin(d);

    debug_printf("----------- start n=%lld\n", n);

    cache.clear();
    cout << solve(n, a, b, c, d) << endl;
}

void _main()
{
    ll t; llin(t);
    rep (i, t) solve();
}

