using namespace std;

typedef long long lint;

lint n, a, b, c, d;

const lint MAX = (1e18) + (1e9);

priority_queue <pair<lint, lint>, vector <pair<lint, lint>>, greater<pair<lint, lint>>> q;

unordered_map <lint, bool> viz;
unordered_map <lint, lint> dp;

lint cost[10];

void cmp(lint nr, lint c, lint cat)
{
    if(dp[nr / cat] == 0 || dp[nr / cat] > c + cost[cat])
    {
        dp[nr / cat] = c + cost[cat];
        q.push({dp[nr / cat], nr / cat});
    }
}

void solve()
{
    cost[2] = a;
    cost[3] = b;
    cost[5] = c;

    q.push({0, n});
    dp[n] = 0;

    while(viz[0] == 0)
    {
        lint cr = q.top().second;
        lint x = q.top().first;
        q.pop();
        if(viz[cr] == 0)
        {
           // cout << " suntem " << cr << " " << x << "\n";

            viz[cr] = 1;

            if(cr % 2 == 0 && (dp[cr / 2] == 0 || dp[cr / 2] > x + a))
            {
                dp[cr / 2] = x + a;
                q.push({dp[cr / 2], cr / 2});
            }

            if(cr % 3 == 0 && (dp[cr / 3] == 0 || dp[cr / 3] > x + b))
            {
                dp[cr / 3] = x + b;
                q.push({dp[cr / 3], cr / 3});
            }

            if(cr % 5 == 0 && (dp[cr / 5] == 0 || dp[cr / 5] > x + c))
            {
                dp[cr / 5] = x + c;
                q.push({dp[cr / 5], cr / 5});
            }

            if(abs(cr - 1) <= MAX / d)
                cmp(1, x + abs(cr - 1) * d, 1);

            if(cr <= MAX / d)
                cmp(0, x + cr * d, 1);

            int r = cr % 2;
            lint nou = cr - r;

            if(nou != cr && abs(cr - nou) <= MAX / d)
                cmp(nou, x + abs(cr - nou) * d, 2);

            if(abs(cr - (nou + 2)) <= MAX / d)
                cmp(nou + 2, x + abs(cr - (nou + 2)) * d, 2);

            if(nou >= 2)
                if(abs(cr - (nou - 2)) <= MAX / d)
                    cmp(nou - 2, x + abs(cr - (nou - 2)) * d, 2);


            r = cr % 3;
            nou = cr - r;

            if(nou != cr && abs(cr - nou) <= MAX / d)
                cmp(nou, x + abs(cr - nou) * d, 3);
            if(abs(cr - (nou + 3)) <= MAX / d)
                cmp(nou + 3, x + abs(cr - (nou + 3)) * d, 3);

            if(nou >= 3)
                if(abs(cr - (nou - 3)) <= MAX / d)
                    cmp(nou - 3, x + abs(cr - (nou - 3)) * d, 3);


            r = cr % 5;
            nou = cr - r;

            if(nou != cr && abs(cr - nou) <= MAX / d)
                cmp(nou, x + abs(cr - nou) * d, 5);
            if(abs(cr - (nou + 5)) <= MAX / d)
                cmp(nou + 5, x + abs(cr - (nou + 5)) * d, 5);

            if(nou >= 5)
                if(abs(cr - (nou - 5)) <= MAX / d)
                    cmp(nou - 5, x + abs(cr - (nou - 5)) * d, 5);

        }
    }

    cout << dp[0] << "\n";
}

int main()
{
    int qq;
    cin >> qq;
    while(qq > 0)
    {
        qq --;

        dp.clear();
        viz.clear();
        while(q.size() > 0)
            q.pop();

        cin >> n >> a >> b >> c >> d;

        solve();
    }
    return 0;
}

