	priq<lint> q;
	q.push(n);
	while(!q.empty())
	{
		lint x = q.top();
		q.pop();

		lint b2 = x / 2, a2 = div2(x, 2);
		lint b3 = x / 3, a3 = div2(x, 3);
		lint b5 = x / 5, a5 = div2(x, 5);

		if (!exist(m, b2))
		{
			m.insert({ b2, inf });
			q.push(b2);
		}
		if (!exist(m, b3))
		{
			m.insert({ b3, inf });
			q.push(b3);
		}
		if (!exist(m, b5))
		{
			m.insert({ b5, inf });
			q.push(b5);
		}
		if (!exist(m, a2))
		{
			m.insert({ a2, inf });
			q.push(a2);
		}
		if (!exist(m, a3))
		{
			m.insert({ a3, inf });
			q.push(a3);
		}
		if (!exist(m, a5))
		{
			m.insert({ a5, inf });
			q.push(a5);
		}

		m[b2] = mmin(m[b2], m[x] + d * (x - b2 * 2) + a);
