template<class T>
T &remin(T &x, const T &y)
{
	return x = min(x, y);
}

template<class T>
using minheap = priority_queue<T, vector<T>, greater<T>>;


const int bnd = 300;


ll Dijkstra(unordered_map<ll, ll> &dp, const ll n, const int a, const int b, const int c, const int d)
{
	if (n >= bnd)
		return numeric_limits<ll>::max() / 100;
	if (n == 0)
		return 0;

	if (!dp.count(n))
	{
		minheap<pair<ll, ll>> pq;
		pq.emplace(0, 0);

		while (!pq.empty())
		{
			ll val, num;
			tie(val, num) = pq.top();
			pq.pop();

			if (num < bnd && !dp.count(num))
			{
				dp[num] = val;

				pq.emplace(val + a, num * 2);
				pq.emplace(val + b, num * 3);
				pq.emplace(val + c, num * 5);
				pq.emplace(val + d, num + 1);
				if (num % 2 == 0)
					pq.emplace(val + a, num / 2);
				if (num % 3 == 0)
					pq.emplace(val + b, num / 3);
				if (num % 5 == 0)
					pq.emplace(val + c, num / 5);
				if (num > 0)
					pq.emplace(val + d, num - 1);
			}
		}
	}

	return dp.at(n);
}


ll foo(unordered_map<ll, ll> &dp, const ll n, const int a, const int b, const int c, const int d)
{
	if (n < 300)
		return Dijkstra(dp, n, a, b, c, d);

	if (!dp.count(n))
	{
		ll ans = min(numeric_limits<ll>::max() / d, n) * d;

		for (ll i = max(0ll, n - 5); i <= n + 5; i++)
		{
			if (i % 2 == 0)
				remin(ans, foo(dp, i / 2, a, b, c, d) + d * abs(i - n) + a);
			if (i % 3 == 0)
				remin(ans, foo(dp, i / 3, a, b, c, d) + d * abs(i - n) + b);
			if (i % 5 == 0)
				remin(ans, foo(dp, i / 5, a, b, c, d) + d * abs(i - n) + c);
		}

		dp[n] = ans;
	}

	return dp.at(n);
}


