		{
			que.push(pll(cost - b, num / 3));
		}

		if (mod5 != 0)
		{
			que.push(pll(cost - d * mod5 - c, num / 5));
			que.push(pll(cost - d * (5 - mod5) - c, num / 5 + 1));
		}
		else
		{
			que.push(pll(cost - c, num / 5));
		}
	}

	cout << ans << endl;
}

