  set<ll> N_tmp_st;
  while(que.size()){
    pair<ll, ll> now = que.top(); que.pop();
    ll cost_tmp = -now.first;
    ll N_tmp = now.second;
    if(N_tmp_st.find(N_tmp)!=N_tmp_st.end()) continue;
    N_tmp_st.emplace(N_tmp);
    //debug_print(N_tmp, cost_tmp);

    if(cost_tmp<0) exit(0);

    if(N_tmp==1) return cost_tmp+D;
    if(N_tmp==0) return cost_tmp;

    {
      ll amari = N_tmp%2;
      if(amari==0){
        ll tmp_cost = min((N_tmp/2)*D, A);
        if(N_tmp/2>A/D){
          tmp_cost = A;
        }
        que.push(make_pair(-cost_tmp-tmp_cost, N_tmp/2));
      }else{
        ll N_tmp_tmp1 = N_tmp+1;
        ll tmp_cost1 = min((N_tmp_tmp1/2)*D, A)+D;
        if(N_tmp_tmp1/2>A/D){
          tmp_cost1 = A+D;
        }
        que.push(make_pair(-cost_tmp-tmp_cost1, N_tmp_tmp1/2));

        ll N_tmp_tmp2 = N_tmp-1;
        if(N_tmp_tmp2<0) continue;
        ll tmp_cost2 = min((N_tmp_tmp2/2)*D, A)+D;
        if(N_tmp_tmp2/2>A/D){
          tmp_cost2 = A+D;
        }
        que.push(make_pair(-cost_tmp-tmp_cost2, N_tmp_tmp2/2));
      }
    }

    {
      ll amari = N_tmp%3;
      if(amari==0){
        ll tmp_cost = min((N_tmp/3*2)*D, B);
        if(N_tmp/3>B/D){
          tmp_cost = B;
        }
        que.push(make_pair(-cost_tmp-tmp_cost, N_tmp/3));
      }else{
        ll N_tmp_tmp1 = N_tmp+(3-amari);
        ll tmp_cost1 = min((N_tmp_tmp1/3*2)*D, B)+D*(3-amari);
        if(N_tmp_tmp1/3>B/D){
          tmp_cost1 = B+D*(3-amari);
        }
        que.push(make_pair(-cost_tmp-tmp_cost1, N_tmp_tmp1/3));

        ll N_tmp_tmp2 = N_tmp-amari;
        if(N_tmp_tmp2<0) continue;
        ll tmp_cost2 = min((N_tmp_tmp2/3*2)*D, B)+D*amari;
        if(N_tmp_tmp2/3>B/D){
          tmp_cost2 = B+D*amari;
        }
        que.push(make_pair(-cost_tmp-tmp_cost2, N_tmp_tmp2/3));
      }
    }

    {
      ll amari = N_tmp%5;
      if(amari==0){
        ll tmp_cost = min((N_tmp/5*4)*D, C);
        if(N_tmp/5>C/D){
          tmp_cost = C;
        }
        que.push(make_pair(-cost_tmp-tmp_cost, N_tmp/5));
      }else{
        ll N_tmp_tmp1 = N_tmp+(5-amari);
        ll tmp_cost1 = min((N_tmp_tmp1/5*4)*D, C)+D*(5-amari);
        if(N_tmp_tmp1/5>C/D){
          tmp_cost1 = C+D*(5-amari);
        }
        que.push(make_pair(-cost_tmp-tmp_cost1, N_tmp_tmp1/5));

        ll N_tmp_tmp2 = N_tmp-amari;
        if(N_tmp_tmp2<0) continue;
        ll tmp_cost2 = min((N_tmp_tmp2/5*4)*D, C)+D*amari;
        if(N_tmp_tmp2/5>C/D){
          tmp_cost2 = C+D*amari;
        }
        que.push(make_pair(-cost_tmp-tmp_cost2, N_tmp_tmp2/5));
      }
    }

    /*
    if(N_tmp%2==0){
