void body() {
    auto T = read<i64>();
    auto NABCDs = read<i64, i64, i64, i64, i64>(T);
    EACH (NABCD, NABCDs) {
        OrderedMap<i64, i64> cost;
        auto N = std::get<0>(NABCD);
        auto A = std::get<1>(NABCD);
        auto B = std::get<2>(NABCD);
        auto C = std::get<3>(NABCD);
        auto D = std::get<4>(NABCD);

        auto _cost_to_0 = [&](i64 x, auto f) -> i64 {
            auto _cost = [&](i64 d, i64 X) -> i64 {
                if (x / d == 0) {
                    return std::numeric_limits<i64>::max();
                }
                if (x == 2 && d == 2) {
                    return f(x / d, f) + std::abs(d * (x / d) - x) * D + X;
                }
                return std::min(
                    f(x / d, f) + std::abs(d * (x / d) - x) * D + X,
                    f(x / d + 1, f) + std::abs(d * (x / d + 1) - x) * D + X
                );
            };
            if (cost.find(x) != cost.end()) {
                return cost[x];
            }
            auto tmp = D * x;
            if (tmp <= 0) {
                // オーバーフローの恐れあり
                tmp = std::numeric_limits<i64>::max();
            }
            auto c = std::min(std::min<i64>(_cost(2, A), _cost(3, B)), std::min(_cost(5, C), tmp));
            cost[x] = c;
            return c;
        };
        cout << _cost_to_0(N, _cost_to_0) << endl;
    }
}

