  ans = min(ans, dfs(z) + min(d * y + b, dis(z, x)));
  if (y != 0) {
    z += 1;
    ans = min(ans, dfs(z) + min(d * (3 - y) + b, dis(z, x)));
  }

  y = x % 5;
  z = (x - y) / 5;
  ans = min(ans, dfs(z) + min(d * y + c, dis(z, x)));
  if (y != 0) {
    z += 1;
    ans = min(ans, dfs(z) + min(d * (5 - y) + c, dis(z, x)));
  }

  mp[x] = ans;
  return ans;
}

