      xnu = (x+2)/3;
      xnucost = dp[x] + B + D*((3 - x%3)%3);
      if (!dp.count(xnu) || xnucost < dp[xnu]) dp[xnu] = xnucost, q.push(xnu);
      xnu = x/5;
      xnucost = dp[x] + C + D*(x%5);
      if (!dp.count(xnu) || xnucost < dp[xnu]) dp[xnu] = xnucost, q.push(xnu);
      xnu = (x+4)/5;
      xnucost = dp[x] + C + D*((5 - x%5)%5);
      if (!dp.count(xnu) || xnucost < dp[xnu]) dp[xnu] = xnucost, q.push(xnu);
