using namespace std;
using ll = long long int;
using vec = vector<int>;
using P = pair<ll,ll>;
const ll INF = 1e18+7;

ll n;
ll a, b, c, d;

struct edge {
  ll to, cost;
  edge(ll to, ll cost) : to(to), cost(cost){}
};

ll dijkstra() {
  priority_queue<P, vector<P>, greater<P> > que;
  map<ll, ll> mem;
  mem[n] = 0;
  que.emplace(0, n);

  while (true) {
    P p = que.top(); que.pop();
    if (p.second == 1) {
      return p.first;
    }
    ll v = p.second;
    if (mem[v] < p.first) continue;

    vector<edge> g;
    switch (v % 2) {
      case 0: g.emplace_back(v/2, v/2 <= a/d ? v/2*d : a); break;
      case 1:
        g.emplace_back(v/2, v-v/2 <= (a+d)/d ? (v-v/2)*d : a+d);
        g.emplace_back(v/2+1, v-v/2-1 <= (a+d)/d ? (v-v/2-1)*d : a+d);
        break;
    }
    switch (v % 3) {
      case 0: g.emplace_back(v/3, v-v/3 <= b/d ? (v-v/3)*d : b); break;
      case 1:
        g.emplace_back(v/3, v-v/3 <= (b+d)/d ? (v-v/3)*d : b+d);
        g.emplace_back(v/3+1, v-v/3-1 <= (b+2*d)/d ? (v-v/3-1)*d : b+2*d);
        break;
      case 2:
        g.emplace_back(v/3, v-v/3 <= (b+2*d)/d ? (v-v/3)*d : b+2*d);
        g.emplace_back(v/3+1, v-v/3-1 <= (b+d)/d ? (v-v/3-1)*d : b+d);
        break;
    }
    switch (v % 5) {
      case 0: g.emplace_back(v/5, v-v/5 <= c/d ? (v-v/5)*d : c); break;
      case 1:
        g.emplace_back(v/5, v-v/5 <= (c+d)/d ? (v-v/5)*d : c+d);
        g.emplace_back(v/5+1, v-v/5-1 <= (c+2*d)/d ? (v-v/5-1)*d : c+2*d);
        break;
      case 2:
        g.emplace_back(v/5, v-v/5 <= (c+2*d)/d ? (v-v/5)*d : c+2*d);
        g.emplace_back(v/5+1, v-v/5-1 <= (c+3*d)/d ? (v-v/5-1)*d : c+3*d);
        break;
      case 3:
        g.emplace_back(v/5, v-v/5 <= (c+3*d)/d ? (v-v/5)*d : c+3*d);
        g.emplace_back(v/5+1, v-v/5-1 <= (c+2*d)/d ? (v-v/5-1)*d : c+2*d);
        break;
      case 4:
        g.emplace_back(v/5, v-v/5 <= (c+2*d)/d ? (v-v/5)*d : c+2*d);
        g.emplace_back(v/5+1, v-v/5-1 <= (c+d)/d ? (v-v/5-1)*d : c+d);
        break;
    }

    for (edge e : g) {
      if (e.to != n && mem[e.to] == 0) mem[e.to] = INF;
      if (mem[e.to] > mem[v] + e.cost) {
        mem[e.to] = mem[v] + e.cost;
        que.emplace(mem[e.to], e.to);
      }
    }
  }
}

