struct Comparator {
	bool operator()(const std::pair<long long int, long long int>& a, const std::pair<long long int, long long int>& b) const {
		return a.second > b.second;
	}
};
long long int by_two(const long long int n, const long long int a, const long long int d) {
	return n == 1 ? d : by_two(n >> 1, a, d) + a + (n & 1) * d;
}
int main() {
	std::cin.tie(nullptr); std::cin.sync_with_stdio(false);
	int test_case; std::cin >> test_case;
	for (auto t = 0; t < test_case; ++t) {
		long long int n, a, b, c, d; std::cin >> n >> a >> b >> c >> d;
		std::priority_queue<std::pair<long long int, long long int>, std::vector<std::pair<long long int, long long int>>, Comparator> queue;
		const long long int max = by_two(n, a, d);
		std::vector<long long int> costs{ a, b, c };
		std::vector<int> multipier{ 2, 3, 5 };
		queue.emplace(n, 0);
		std::unordered_map<long long int, long long int> min_cost; min_cost[n] = 0;
		min_cost[0] = (max / d <= n) ? std::min(max, n * d) : max;
		while (!queue.empty()) {
			const auto top = queue.top(); queue.pop();
			//std::cout << top.first << ", " << top.second << '\n';
			if (top.first == 0) break;
			if (min_cost[top.first] != top.second) continue;
			if (top.second / d + top.first <= min_cost[0] / d + 1) {
				if (min_cost[0] > top.first * d + top.second) {
					min_cost[0] = top.first * d + top.second;
					queue.emplace(0, top.first * d + top.second);
				}
			}
			for (auto i = 0; i < costs.size(); ++i) {
				const auto m = multipier[i];
				const auto cost = costs[i];
				for (const auto next : { top.first / m, top.first / m + 1 }) {
					const auto diff = d * std::abs(top.first - next * m) + top.second;
					if (next == 0 && diff < min_cost[0]) {
						min_cost[next] = diff;
						queue.emplace(next, diff);
					}
					if (cost + diff < min_cost[0] && (min_cost.find(next) == min_cost.end() || min_cost.find(next)->second > cost + diff)) {
						min_cost[next] = cost + diff;
						queue.emplace(next, cost + diff);
					}
				}
			}
		}
		std::cout << min_cost[0] << '\n';
	}
}

