ll dfs(ll v) {
	if (v == 0) return 0;
	if (v == 1) return D;

	if (cache.count(v)) return cache[v];

	ll res = ((double)v*D > 1e18?(ll)1e18:v*D);

	res = min(res, dfs(v/2)+(v&1?D:0)+A);
	res = min(res, dfs((v+1)/2)+(v&1?D:0)+A);

	if (v%3 <= 1) {
		res = min(res, dfs(v/3)+v%3*D+B);
