ll f(ll N) {
    if (N == 0) return 0;
    if (N == 1) return d;
    if (memo.count(N)) return memo[N];
    ll l2 = (N/2)*2;
    ll r2 = ((N+1)/2)*2;
    ll l3 = (N/3)*3;
    ll r3 = ((N+2)/3)*3;
    ll l5 = (N/5)*5;
    ll r5 = ((N+4)/5)*5;

    ll res = 1e18;
    if (N < res/d) res = N*d;
    res = min(res, llabs(l2-N)*d + a + f(l2/2));
    res = min(res, llabs(r2-N)*d + a + f(r2/2));

    res = min(res, llabs(l3-N)*d + b + f(l3/3));
    res = min(res, llabs(r3-N)*d + b + f(r3/3));

    res = min(res, llabs(l5-N)*d + c + f(l5/5));
    res = min(res, llabs(r5-N)*d + c + f(r5/5));

    memo[N] = res;

    return res;
}
