#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MAX = 1e7 + 10;
const ll INF = 9e18;

int T;
ll N, A, B, C, D;
ll f[MAX], n = 1e7;
map<ll, ll> mp;

ll calc(ll x) {
    if (x < 0) return INF;
    return x;
}

ll dp(ll x) {
    if (x <= n) return f[x];
    if (mp.count(x)) return mp[x];
    ll res = INF;
    ll t = x % 2;
    res = min(res, min(dp(x / 2) + min(A + t * D, calc((x - x / 2) * D)), dp(x / 2 + 1) + min(A + (2 - t) * D, calc((x - x / 2 - 1) * D))));
    t = x % 3;
    res = min(res, min(dp(x / 3) + min(B + t * D, calc((x - x / 3) * D)), dp(x / 3 + 1) + min(B + (3 - t) * D, calc((x - x / 3 - 1) * D))));
    if (x % 5 == 0) res = min(res, C + dp(x / 5));
    t = x % 5;
    res = min(res, min(dp(x / 5) + min(C + t * D, calc((x - x / 5) * D)), dp(x / 5 + 1) + min(C + (5 - t) * D, calc((x - x / 5 - 1) * D))));
    return mp[x] = res;
}

int main() {
#ifdef ACM_LOCAL
    freopen("input.in", "r", stdin);
    freopen("output.out", "w", stdout);
#endif
    cin >> T;
    while (T--) {
        cin >> N >> A >> B >> C >> D;
        memset(f, 0x3f, sizeof(f)); f[0] = 0;
        for (int i = 1; i <= n; i++) {
            f[i] = min(f[i], f[i - 1] + D);
            if (i % 2 == 0) f[i] = min(f[i], f[i / 2] + A);
            if (i % 3 == 0) f[i] = min(f[i], f[i / 3] + B);
            if (i % 5 == 0) f[i] = min(f[i], f[i / 5] + C);
        }
        cout << dp(N) << endl;
    }

    return 0;
}

