vector<lll> c(4), d;
map<ll, lll> dp;

ll dfs(ll n){

	if(n == 0) return 0;
	if(dp[n]) return dp[n];

	dp[n] = n*c[3];
	for(ll i=0; i<3; i++){
		ll k = 0;
		while((n-k)%d[i]) k++;
		dp[n] = min(dp[n], dfs((n-k)/d[i])+k*c[3]+c[i]);
		k = 0;
		while((n+k)%d[i]) k++;
		dp[n] = min(dp[n], dfs((n+k)/d[i])+k*c[3]+c[i]);
	}

	return dp[n];
}

