const int INF = 1LL << 60; //10e18+10e17ちょっとくらい
const int MOD = 1000000007;
const int MAX_N = 200100;

int N, A, B, C, D;
map<int, int> memo;
int solve(int num)
{
    if (num == 0)
        return 0;
    if (num == 1)
        return D;
    if (memo.count(num))
    {
        return memo[num];
    }

    int cost = INF;
    int add;

    if (cost / D > N)
        cost = D * N;

    if (num % 2 == 0)
    {
        add = min(num / 2 * D, A);
        if (add <= 0)
            add = A;
        cost = min(cost, solve(num / 2) + add);
    }
    else
    {
        int tmp = num;
        while (true)
        {
            tmp++;
            if (tmp % 2 == 0)
            {
                add = min(abs(num - tmp / 2) * D, A + D * abs(num - tmp));
                if (add <= 0)
                    add = A + D * abs(num - tmp);
                cost = min(cost, solve(tmp / 2) + add);
                break;
            }
        }
        tmp = num;
        while (true)
        {
            tmp--;
            if (tmp % 2 == 0)
            {
                add = min(abs(num - tmp / 2) * D, A + D * abs(num - tmp));
                if (add <= 0)
                    add = A + D * abs(num - tmp);
                cost = min(cost, solve(tmp / 2) + add);
                break;
            }
        }
    }

    if (num % 3 == 0)
    {
        add = min(num / 3 * 2 * D, B);
        if (add <= 0)
            add = B;
        cost = min(cost, solve(num / 3) + add);
    }
    else
    {
        int tmp = num;
        while (true)
        {
            tmp++;
            if (tmp % 3 == 0)
            {
                add = min(abs(num - tmp / 3) * D, B + D * abs(num - tmp));
                if (add <= 0)
                    add = B + D * abs(num - tmp);
                cost = min(cost, solve(tmp / 3) + add);
                break;
            }
        }
        tmp = num;
        while (true)
        {
            tmp--;
            if (tmp % 3 == 0)
            {
                add = min(abs(num - tmp / 3) * D, B + D * abs(num - tmp));
                if (add <= 0)
                    add = B + D * abs(num - tmp);
                cost = min(cost, solve(tmp / 3) + add);
                break;
            }
        }
    }

    if (num % 5 == 0)
    {
        add = min(num / 5 * 4 * D, C);
        if (add <= 0)
            add = C;
        cost = min(cost, solve(num / 5) + add);
    }
    else
    {
        int tmp = num;
        while (true)
        {
            tmp++;
            if (tmp % 5 == 0)
            {
                add = min(abs(num - tmp / 5) * D, C + D * abs(num - tmp));
                if (add <= 0)
                    add = C + D * abs(num - tmp);
                cost = min(cost, solve(tmp / 5) + add);
                break;
            }
        }
        tmp = num;
        while (true)
        {
            tmp--;
            if (tmp % 5 == 0)
            {
                add = min(abs(num - tmp / 5) * D, C + D * abs(num - tmp));
                if (add <= 0)
                    add = C + D * abs(num - tmp);
                cost = min(cost, solve(tmp / 5) + add);
                break;
            }
        }
    }
    memo[num] = cost;
    return cost;
}

