ll checker(ll x){
  ll cnt=0;
  while(x>0){
    x/=10;
    cnt++;
  }

  return cnt;
}

ll dfs(ll value, ll a, ll b, ll c, ll d, ll cnt1){
  if(m[value]!=0)
    return m[value];
  if(value==0)
    return 0;

  ll res=LLINF;
  if(value%5==0)
    res=min(res,dfs(value/5,a,b,c,d,0)+c);
  if(value%3==0)
    res=min(res,dfs(value/3,a,b,c,d,0)+b);
  if(value%2==0)
    res=min(res,dfs(value/2,a,b,c,d,0)+a);
  if(cnt1<5)
    res=min(res,dfs(value-1,a,b,c,d,cnt1+1)+d);
  if(cnt1<5 && value>2)
    res=min(res,dfs(value+1,a,b,c,d,cnt1+1)+d);

  if(checker(value)+checker(d)<19)
    res=min(res,value*d);

  m[value]=res;
  return res;
}

