LL n, a, b, c, d;
unordered_map<LL, LL> dp;

LL dfs(LL n){
	if (n==0) return 0;
	if (dp[n]) return dp[n];
	LL res = INF;
	if (res/d >= n) res = d * n;
	LL x = n%2, y = n%3, z = n%5;
	res = min(res, min(x*d + dfs((n-x)/2), (2-x)*d + dfs((n-x)/2+1)) + a);
	res = min(res, min(y*d + dfs((n-y)/3), (3-y)*d + dfs((n-y)/3+1)) + b);
	res = min(res, min(z*d + dfs((n-z)/5), (5-z)*d + dfs((n-z)/5+1)) + c);
	//cout<<n<<" "<<res<<endl;
	return dp[n] = res;
}

