typedef pair<LL, LL> pi; 

struct value {
	LL v = -1;
};

map<LL, value> dp;

LL a, b, c, d, n;
value call(LL num) {
	if(dp[num].v != -1) {
		return dp[num];
	}

	if(num == 0) {
		value val;
		val.v = 0;
		dp[num] = val;
		return dp[num];
	}

	LL all_d = d * num;
	if(all_d < 0) all_d = INFL;

	LL ans = INFL;
	ans = min(ans, all_d);
	if(num % 2 == 0) {
		ans = min(ans, call(num/2).v + a);
	} else {
		LL rem = num % 2;
		ans = min(ans, call(num/2).v + d*rem + a);
		if(num != 1) {
			rem = 2-rem;
			ans = min(ans, call((num+rem)/2).v + d*rem + a); 
		}
	}

	if(num % 3 == 0) {
		ans = min(ans, call(num/3).v + b);
	} else {
		LL rem = num % 3;
		ans = min(ans, call(num/3).v + d*rem + b);
		if(num != 1) {
			rem = 3-rem;
			ans = min(ans, call((num+rem)/3).v + d*rem + b); 
		}
	}

	if(num % 5 == 0) {
		ans = min(ans, call(num/5).v + c);
	} else {
		LL rem = num % 5;
		ans = min(ans, call(num/5).v + d*rem+c);
		if(num != 1) {
			rem = 5-rem;
			ans = min(ans, call((num+rem)/5).v + d*rem+c); 
		}
	}

	value ansv;
	ansv.v = ans;
	dp[num] = ansv;
	return dp[num];
}

