int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int tt;
    cin >> tt;
    while (tt--) {
        ll n, a, b, c, d;
        cin >> n >> a >> b >> c >> d;
        map<ll, ll> mp;
        mp[1] = d;
        function<ll(ll)> solve = [&](ll x) {
            if (x == 0) {
                return 0LL;
            }
            if (mp[x] != 0LL) {
                return mp[x];
            }
            ll res = 9e18;
            if (x < 1e9) {
                res = x * d;
            }
            if (x % 2 == 0) {
                res = min(res, solve(x / 2) + a);
            } else {
                res = min(res, solve(x / 2) + a + d);
                res = min(res, solve(x / 2 + 1) + a + d);
            }
            if (x % 3 == 0) {
                res = min(res, solve(x / 3) + b);
            } else if (x % 3 == 1) {
                res = min(res, solve(x / 3) + b + d);
                res = min(res, solve(x / 3 + 1) + b + d + d);
            } else {
                res = min(res, solve(x / 3) + b + d + d);
                res = min(res, solve(x / 3 + 1) + b + d);
            }
            ll q = x % 5;
            res = min(res, solve(x / 5) + c + d * q);
            res = min(res, solve(x / 5 + 1) + c + d * (5 - q));
            return mp[x] = res;
        };
        cout << solve(n) << '\n';
    }
    return 0;
}

