ll N, A, B, C, D;
ll dfs(ll x, map<ll, ll> &mp) {
    if (mp.find(x) != mp.end())
        return mp[x];

    ll mi = LLONG_MAX;
    auto func = [&](ll y, ll div, ll cost) -> void {
        ll tmp = y / div, mo = y % div, res;
        res = dfs(tmp, mp);
        mi = min(mi, res + cost + mo * D);
        if ((mi - res) / D >= y - tmp)
            mi = res + (y - tmp) * D;
        if (mo) {
            res = dfs(tmp + 1, mp);
            mi = min(mi, res + cost + (div - mo) * D);
            if ((mi - res) / D >= y - tmp - 1)
                mi = res + (y - tmp - 1) * D;
        }
    };

    func(x, 2, A);
    func(x, 3, B);
    func(x, 5, C);
    return mp[x] = mi;
}

