    vpll ks = {{2ll, a}, {3ll, b}, {5ll, c}};
    const ll inf = 1e18;
    function<ll(ll i)> comp = [&](ll i)->ll {
        if(!(i)) return 0;
        if (i == 1)
            return d;
        else if (dp.find(i) != dp.end())
            return dp[i];
        else {
            dp[i] = (i < inf / d) ? i * d : inf;
            for (auto [k, v] : ks) {
                ll lo = (i / k), hi = (i / k) + !!(i % k);
                ll clo = d * (i - k * lo) + v, chi = d * (k * hi - i) + v;
                ckmin(dp[i], clo + comp(lo), chi + comp(hi));
            }
            return dp[i];
        }
    };
    cout << comp(n) << "\n";
}
