int64_t Ceil(int64_t a, int64_t b) { return (a + b - 1) / b; }
int64_t Floor(int64_t a, int64_t b) { return a / b; }

int64_t Rec(int64_t now);

bool IsProductOverflow(long a, long b) {
  if (a == 0 || b == 0) return false;
  long prod = a * b;

  return (prod / b != a);
}

// void Update(int64_t& ret, int64_t now, int64_t m, int64_t cost) {
