//   if (!IsProductOverflow(D, now)) ChMin(ret, D * now);
// }
void Update(int64_t& ret, int64_t now, int64_t m, int64_t cost) {
  int64_t c  = Ceil(now, m) * m;
  int64_t f  = Floor(now, m) * m;
  int64_t rc = Rec(c / m);
  int64_t rf = Rec(f / m);
  ChMin(ret, rc + cost + D * (c - now));
  if (!IsProductOverflow(D, (c - c / m)))
    ChMin(ret, rc + D * (c - c / m) + D * (c - now));
  ChMin(ret, rf + cost + D * (now - f));
  if (!IsProductOverflow(D, (f - f / m)))
    ChMin(ret, rf + D * (f - f / m) + D * (now - f));
  if (!IsProductOverflow(D, now)) ChMin(ret, D * now);
}

map<int64_t, int64_t> memo;

int64_t Rec(int64_t now) {
  if (now == 0) return 0;
  if (now == 1) {
    return D;
  }
  {
    auto it = memo.find(now);
    if (it != memo.end()) {
      return it->second;
    }
  }

  int64_t ret = numeric_limits<int64_t>::max();
  Update(ret, now, 2, A);
  Update(ret, now, 3, B);
  Update(ret, now, 5, C);
  if (!IsProductOverflow(D, now)) ChMin(ret, D * now);
  //{
  //  int64_t c = Ceil(now, 2) * 2;
  //  int64_t f = Floor(now, 2) * 2;
