template <typename T> inline void read(T &AKNOI) {
	T x = 0, flag = 1;
	char ch = getchar();
	while (!isdigit(ch)) {
		if (ch == '-') flag = -1;
		ch = getchar();
	}
	while (isdigit(ch)) {
		x = x * 10 + ch - '0';
		ch = getchar();
	}
	AKNOI = flag * x;
}

template <typename T> inline void cmin(T &x, T y) {
	if (x > y) x = y;
}

const int pr[4] = {0, 2, 3, 5};
LL cost[4], D;
map<LL, LL> mp;

LL Calc(LL x) {
	if (!x) return 0;
	if (mp.count(x)) return mp[x];
	mp[x] = INF;
	if (mp[x] / x >= D) mp[x] = x * D;
	for (int i = 1; i <= 3; ++i) {
		if (x % pr[i]) {
			cmin(mp[x], Calc(x / pr[i]) + cost[i] + D * (x % pr[i]));
			cmin(mp[x], Calc(x / pr[i] + 1) + cost[i] + D * (pr[i] - x % pr[i]));
		} else {
			cmin(mp[x], Calc(x / pr[i]) + cost[i]);
		}
	}
	return mp[x];
}

void solve() {
	LL n; read(n);
	read(cost[1]); read(cost[2]); read(cost[3]); read(D);
	mp.clear();
	printf("%lld\n", Calc(n));
}

