    if(n==0){
        return 0;
    }
    if(n==1){
        return d;
    }
    if(m.find(n)==m.end()){
        if(n%2==0){
            ret = min(ret,dp(n/2)+a);
        }else{
            ret=min(ret,dp(n/2)+a+(n-(n/2)*2)*d);
            ret=min(ret,dp((n+1)/2) + a + (  ((n+1)/2)*2 -  n  )*d);
        }
        if(n%3==0){
            ret = min(ret,dp(n/3)+b);
        }else{
            ret=min(ret,dp(n/3)+b+(n-(n/3)*3)*d);
            ret=min(ret,dp((n+2)/3) + b + (  ((n+2)/3)*3 -  n  )*d);
        }
        if(n%3==0){
            ret = min(ret,dp(n/3)+b);
        }else{
            ret=min(ret,dp(n/3)+b+(n-(n/3)*3)*d);
            ret=min(ret,dp((n+2)/3) + b + (  ((n+2)/3)*3 -  n  )*d);
        }
        if(n%5==0){
            ret = min(ret,dp(n/5)+c);
