#define rup(x, y) (((x)+(y)-1)/(y))
using namespace std;
using ll = long long;
using P = pair<int,int>;
constexpr ll LINF = 4e18;

int a, b, c, d;
map<ll, ll> mp;
map<int, int> cost;

ll calc(ll s, ll g, int p) {
    ll k = abs(g * p - s);
    boost::multiprecision::cpp_int a = 1, b = 1;
    a *= k; a*= cost[1]; a += cost[p];
    b *= abs(s - g); b *= cost[1];
    return (ll)min(a, b);
}

ll f(ll n) {
    if (mp.find(n) != mp.end())
        return mp[n];
    if (n == 1)
        return mp[1] = cost[1];

    vector<int> v = {2, 3, 5};
    ll ret = LINF;
    for (auto p : v) {
        ll l = n / p, r = rup(n, p);
        if (l == 0)
            ret = min(ret, calc(n, r, p) + f(r));
        else
            ret = min(ret, min(calc(n, l, p) + f(l), calc(n, r, p) + f(r)));
    }
    mp[n] = ret;
    return ret;
}

