int main()
{
	int T;
	cin >> T;
	vector<long long> N( T );
	vector<long long> A( T );
	vector<long long> B( T );
	vector<long long> C( T );
	vector<long long> D( T );
	for( int i = 0; i < T; i++ ) {
		cin >> N[i] >> A[i] >> B[i] >> C[i] >> D[i];
	}

	typedef pair<long long, long long> P;
	for( int i = 0; i < T; i++ ) {
		priority_queue<P, vector<P>, greater<P>> que;
		map<long long, long long> mp;

		auto push = [&]( long long cost, long long loc )
		{
			if( mp.count( loc ) && cost >= mp[loc] ) return;
			que.push( P( cost, loc ) );
			mp[loc] = cost;
		};

		long long ans = INT64_MAX;
		push( 0, N[i] );
		while( !que.empty() ) {
			long long cost, loc;
			tie( cost, loc ) = que.top();
			que.pop();
			if( cost > ans ) break;
			if( loc == 0 ) ans = min( ans, cost );
			else if( loc == 1 ) {
				if( cost + D[i] >= 0 ) push( cost + D[i], 0 );
			}
			else {
				if( loc % 2 == 0 ) {
					if( cost + A[i] >= 0 ) push( cost + A[i], loc / 2 );
				}
				else {
					if( cost + A[i] + D[i] >= 0 ) push( cost + A[i] + D[i], (loc - 1) / 2 );
				}
				if( loc % 3 == 0 ) {
					if( cost + B[i] >= 0 ) push( cost + B[i], loc / 3 );
				}
				else {
					int m = loc % 3;
					if( m < 3 - m ) {
						if( cost + B[i] + D[i] * m >= 0 ) push( cost + B[i] + D[i] * m, (loc - m) / 3 );
					}
					else {
						if( cost + B[i] + D[i] * (3 - m) >= 0 && loc + (3 - m) >= 0 ) push( cost + B[i] + D[i] * (3 - m), (loc + (3 - m)) / 3 );
					}
				}
				if( loc % 5 == 0 ) {
					if( cost + C[i] >= 0 ) push( cost + C[i], loc / 5 );
				}
				else {
					int m = loc % 5;
					if( m < 5 - m ) {
						if( cost + C[i] + D[i] * m >= 0 ) push( cost + C[i] + D[i] * m, (loc - m) / 5 );
					}
					else {
						if( cost + C[i] + D[i] * (5 - m) >= 0 ) push( cost + C[i] + D[i] * (5 - m), (loc + (5 - m)) / 5 );
					}
				}
				if( cost + loc * D[i] >= 0 ) push( cost + loc * D[i], 0 );
			}
		}
		cout << ans << endl;
	}
}

