void dijkstra(ll src)
{
	pqueue<ii,vii,greater<ii>> q;
	dist[src]=0;
	dist[0]=INF;
	q.push({dist[src],src});

	while(!q.empty()){
		ll u=q.top().S; q.pop();
		if(DEBUG) cout<<"u="<<u<<" dist="<<dist[u]<<'\n';
		forn(i,0,3){
			ll v=u/dv[i];
			ll inc=abs(u-v*dv[i])*d+cost[i];
			if(logl(u)+logl(d)<=logl(ll(1e11)) && inc>abs(u-v)*d) inc=abs(u-v)*d;
			if(DEBUG) cout<<"v="<<v<<" dv="<<dv[i]<<" p="<<dv[i]*v<<'\n';
			if(dist.find(v)!=dist.end() && dist[v]<=dist[u]+inc) continue;

			dist[v]=dist[u]+inc;
			if(DEBUG) cout<<"dist["<<v<<"]="<<dist[v]<<'\n';
			if(v>0) q.push({dist[v],v});
		}

		forn(i,0,3){
			ll v=(u+dv[i]-1)/dv[i];
			ll inc=abs(u-v*dv[i])*d+cost[i];
			if(logl(u)+logl(d)<=logl(ll(1e11)) && inc>abs(u-v)*d) inc=abs(u-v)*d;
			if(DEBUG) cout<<"v="<<v<<" dv="<<dv[i]<<" p="<<dv[i]*v<<'\n';
			if(dist.find(v)!=dist.end() && dist[v]<=dist[u]+inc) continue;

			dist[v]=dist[u]+inc;
			if(DEBUG) cout<<"dist["<<v<<"]="<<dist[v]<<'\n';
			if(v>0) q.push({dist[v],v});
		}
	}
}

