int t;
ll N, A, B, C, D;
map<ll, ll> memo;

ll solve(ll val)
{
    if(val==0) return 0;
    if(val==1) return D;
    if (memo.count(val)) return memo[val];

    ll l2 = (val/2)*2;
    ll r2 = ((val+1)/2)*2;
    ll l3 = (val/3)*3;
    ll r3 = ((val+2)/3)*3;
    ll l5 = (val/5)*5;
    ll r5 = ((val+4)/5)*5;

    ll res = 1e18;
    if (val < res/D) res = val*D;
    res = min(res, llabs(l2-val)*D + A + solve(l2/2));
    res = min(res, llabs(r2-val)*D + A + solve(r2/2));

    res = min(res, llabs(l3-val)*D + B + solve(l3/3));
    res = min(res, llabs(r3-val)*D + B + solve(r3/3));

    res = min(res, llabs(l5-val)*D + C + solve(l5/5));
    res = min(res, llabs(r5-val)*D + C + solve(r5/5));

    memo[val] = res;
    return res;
}

