map<ll, ll> dp;

ll dfs(ll now){
    if(now == 0) return dp[0] = 0;
    if(now == 1) return dp[1] = d;
    if(dp.count(now)) return dp[now];
    ll res = LINF;
    if((LINF)/d > now) res = now*d;
    vector<ll> v = {a,b,c};
    rep(i,3){
        int next = vector<int>{2,3,5}[i];
        if(now % next == 0){
            res = min(res,dfs(now/next)+v[i]);
        }
        else{
            ll l = now/next*next, r = l+next;
            res = min(res,dfs(l/next)+v[i]+(now-l)*d);
            res = min(res,dfs(r/next)+v[i]+(r-now)*d);
        }
    }
    return dp[now] = res;

}

