#define RFOR(i,a,b) for (int i=(a);i>=(b);--i)
using ll=long long;

ll N; int A, B, C, D; 
map<ll,ll> res;
ll dp(ll x) {
    if (x == 0) return 0;
    if (res.count(x)) return res[x];
    res[x] = 1e18;
    if (x <= 1e9) res[x] = min(res[x], (ll)x*D);
    res[x] = min(res[x], min(dp(x/2)+A+(ll)(x%2)*D, dp((x+1)/2)+A+(ll)(2-x%2)*D));
    res[x] = min(res[x], min(dp(x/3)+B+(ll)(x%3)*D, dp((x+2)/3)+B+(ll)(3-x%3)*D));
    res[x] = min(res[x], min(dp(x/5)+C+(ll)(x%5)*D, dp((x+4)/5)+C+(ll)(5-x%5)*D));
    return res[x];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int T; cin >> T;
    while (T--) {
        cin >> N >> A >> B >> C >> D;
        res.clear();
        cout << dp(N) << '\n';
    }
}

