void solve(){
    LL(n,a,b,c,d);
    unordered_map<ll,ll>cost;
    cost[n]=0;
    priority_queue<ll>q;
    q.push(n);
    cost[0]=LINF;
    while(q.size()){
        ll x=q.top();
        q.pop();
        if(x<=LINF/d)chmin(cost[0],cost[x]+x*d);
        auto update=[&](ll y,ll c){
            cost.try_emplace(y,LINF);
            if(chmin(cost[y],cost[x]+c))q.push(y);
            return 0;
        };
        update(x/2,a+x%2*d);
        update((x+1)/2,a+(2-x%2)*d);
        update(x/3,b+x%3*d);
        update((x+2)/3,b+(3-x%3)*d);
        update(x/5,c+x%5*d);
        update((x+4)/5,c+(5-x%5)*d);
    }
    out(cost[0]);
}
