const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll t;
ll n, a, b, c, d;
vl ns, as, bs, cs, ds;

ll dfs(ll val, ll a, ll b, ll c, ll d, map<ll, ll>& memo){
    if (val == 0) return 0;
    else if (val == 1) return d;
    else if (memo[val] != 0) return memo[val];

    ll m2 = val % 2;
    ll m3 = val % 3;
    ll m5 = val % 5;
    ll cnt21 = m2 * d + a, cnt22 = (2 - m2) * d + a;
    ll cnt31 = m3 * d + b, cnt32 = (3 - m3) * d + b;
    ll cnt51 = m5 * d + c, cnt52 = (5 - m5) * d + c;
    ll cnt0 = INF;
    if (val < MOD * 100 / d) cnt0 = val * d;

    if (val - m2 > 0 && cnt21 < MOD * 100) cnt21 += dfs((val - m2) / 2, a, b, c, d, memo);
    if (val - m3 > 0 && cnt31 < MOD * 100) cnt31 += dfs((val - m3) / 3, a, b, c, d, memo);
    if (val - m5 > 0 && cnt51 < MOD * 100) cnt51 += dfs((val - m5) / 5, a, b, c, d, memo);

    if (val + (2 - m2) != 4 && cnt22 < MOD * 100) cnt22 += dfs((val + (2 - m2)) / 2, a, b, c, d, memo);
    else cnt22 = MOD * 200;

    if (cnt32 < MOD * 100) cnt32 += dfs((val + (3 - m3)) / 3, a, b, c, d, memo);
    else cnt32 = MOD * 200;

    if (cnt52 < MOD * 100) cnt52 += dfs((val + (5 - m5)) / 5, a, b, c, d, memo);
    else cnt52 = MOD * 200;

    return memo[val] = min({cnt0, cnt21, cnt22, cnt31, cnt32, cnt51, cnt52});
    // return memo[val] = min({cnt0, cnt21, cnt31, cnt51});
}

