      for (int k = 0; i + j*1.585 + k*2.322 < 180; k++) {
        int ca = i;
        int cb = j;
        int cc = k;
        int cd = 0;
        long long nn = n;
        while (cc) {
          switch (nn % 5) {
            case 0:
              cc--;
              nn = nn / 5;
              break;
            case 1: case 2:
              cd += nn % 5;
              nn -= nn % 5;
              break;
            case 3: case 4:
              cd += 5 - nn % 5;
              nn += 5 - nn % 5;
              break;
          }
        }
        while (cb) {
          switch (nn % 3) {
            case 0:
              cb--;
              nn = nn / 3;
              break;
            case 1:
              cd++;
              nn--;
              break;
            case 2:
              cd++;
              nn++;
              break;
          }
        }
        while (ca) {
          switch (nn % 2) {
            case 0:
              ca--;
              nn = nn / 2;
              break;
            case 1:
              cd++;
              nn--;
              break;
          }
        }
        if (nn > 1e9) {
          continue;
        }
        cd += nn;
        long long res = 1ll * i * a + 1ll * j * b + 1ll * k * c + 1ll * cd * d;
        if (res < ans) {
          ans = res;
        }
      }
    }
  }
  printf("%lld\n", ans);
}

