const int MAX = (int)1e2;

struct Solver {
  int64_t a, b, c, d;
  map<int64_t, int64_t> memo, best;

  void uin(int idx, int64_t val) {
    if (!memo.count(idx)) memo[idx] = val;
    memo[idx] = min(memo[idx], val);
  }

  Solver() {
    int64_t n; cin >> n >> a >> b >> c >> d;
    memo[0] = 0;
    memo[1] = d;
    for (int it = 0; it < MAX; ++it) {
      for (int i = 1; i <= MAX; ++i) {
        uin(i + 1, memo[i] + d);
        uin(i - 1, memo[i] + d);
        uin(i * 2, memo[i] + a);
        uin(i * 3, memo[i] + b);
        uin(i * 5, memo[i] + c);
      }
    }

    for (int i = 0; i <= 20; ++i) {
      best[i] = memo[i];
    }

    cout << Cost(n) << '\n';
  }

  int64_t Get(int64_t n, int k, int64_t cost) { 
    if (n % k == 0) {
      return Cost(n / k) + cost;
    }
    if (n % k < k - n % k) {
      return Cost(n / k) + cost + (n % k) * d;
    } else {
      return Cost(n / k + 1) + cost + (k - (n % k)) * d;
    }
  }

  int64_t Cost(int64_t n) {
    if (best.count(n)) {
      return best[n];
    }

    int64_t ret = n * d;
    if (n * d / d != n) ret = 1e18;

    ret = min(ret, Get(n, 2, a));
    ret = min(ret, Get(n, 3, b));
    ret = min(ret, Get(n, 5, c));

    return best[n] = ret;
  }
};

