  long long rmaxdif=MAX;
  long long temp;
  long long ri=0,rj=0,rk=0,li=0,lj=0,lk=0;
  for(long long i=0;i<61;i++){
    if(pow(2,i)>N+MAX) break;
    for(long long j=0;j<39;j++){
      if(pow(2,i)*pow(3,j)>N+MAX) break;   
      for(long long k=0;k<27;k++){
        temp=pow(2,i)*pow(3,j)*pow(5,k);
        //cout<<temp<<endl;
        if(temp>N+MAX) break; 
        if(temp>=N && temp-N<rmaxdif){
          rmaxdif=temp-N;
          ri=i;
          rj=j;
          rk=k;
        }
        if(temp<=N && N-temp<lmaxdif){
          lmaxdif=N-temp;
          li=i;
          lj=j;
          lk=k;
        }
      }
    }
  }
  long long ans=min(A*ri+B*rj+C*rk+D*rmaxdif,A*li+B*lj+C*lk+D*lmaxdif);
