ll f(ll s, uom<ll,ll>&dp)
  {
    if(s==0LL) return 0LL;
    if(s==1LL) return d;  

    if(dp.count(s)) return dp[s];

    // so we can reach 0 or 1 ,

    // Case- we can reach 1 or 0 , we can reach 1 from 2*i,3*i,4*i
    // so we start in the reverse direction, we can reach 1 or 0
    // from floor(s/2) or ceil(s/2) and similarly for 3 and 5

    ll op1 = (s/2LL)*(2LL) ; // gives req s to reach floor of s/2
    // the position it gives has to be reached by inc or dec of 1

    ll op2 = ((s+1LL)/2LL)*(2LL);

    // for ceil we do add 1 because if s was divisible by 2
    // floor and ceil would be same
    // if it is 11 floor is 5 reachable from 10 
    // to reach ceil value , we jump from (n+1)/2
    // beacuse by adding 1 a non divisible no
    // becomes divisible by 2

    // similarly we add 2 for 3 and 4 for 5

    ll op3 = (s/3LL)*(3LL);
    ll op4 = ((s+2LL)/3LL)*(3LL);
    ll op5 = (s/5LL)*(5LL);
    ll op6 = ((s+4LL)/5LL)*(5LL);

    ll ans = 1e18;

  // if i travel with eac
