        }
    }

    // x*2-y
    y = 2 - (v % 2);
    x = (v + y) / 2;
    if (x < v) {
        if (A > (x - 2 * y) * D) {
            if ((x - y) * D < ans)
                ans = min(ans, (x - y) * D + dfs(x));
