    // x*5+y
    y = v % 5;
    x = (v - y) / 5;
    if (x < v) {
        if (C > 4 * x * D) {
            if ((4 * x + y) * D < ans)
                ans = min(ans, (4 * x + y) * D + dfs(x));
        } else {
            if (C + y * D < ans)
                ans = min(ans, C + y * D + dfs(x));
        }
    }

    // x*5-y
    y = 5 - (v % 5);
