void solve() {
	ll n, a, b, c, d;cin >> n >> a >> b >> c >> d;
	__int128_t ans = (__int128_t)n * (__int128_t)d;
	queue<P> pq;
	map<__int128_t, __int128_t> mp;
	pq.push(MP(n, 0));
	while(!pq.empty()){
		auto now = pq.front();pq.pop();
		if(ans < now.SE)continue;
		ans = min(ans, now.SE + now.FI * d);

		__int128_t tmp = (now.FI % 2) * d;
		__int128_t nxt = now.FI / 2;
		if(mp.find(nxt) == mp.end() || now.SE + tmp + a < mp[nxt]){
			pq.push(MP(now.FI / 2, now.SE + tmp + a));
			mp[nxt] = now.SE + tmp + a;
		}

		tmp = (now.FI % 3) * d;
		nxt = now.FI / 3;
		if(mp.find(nxt) == mp.end() || now.SE + tmp + b < mp[nxt]){
			pq.push(MP(now.FI / 3, now.SE + tmp + b));
			mp[nxt] = now.SE + tmp + b;
		}

		tmp = (now.FI % 5) * d;
		nxt = now.FI / 5;
		if(mp.find(nxt) == mp.end() || now.SE + tmp + c < mp[nxt]){
			pq.push(MP(now.FI / 5, now.SE + tmp + c));
			mp[nxt] = now.SE + tmp + c;
		}

		tmp = (2 - now.FI % 2) * d;
		nxt = now.FI / 2 + 1;
		if(mp.find(nxt) == mp.end() || now.SE + tmp + a < mp[nxt]){
			pq.push(MP(now.FI / 2, now.SE + tmp + a));
			mp[nxt] = now.SE + tmp + a;
		}

		tmp = (3 - now.FI % 3) * d;
		nxt = now.FI / 3 + 1;
		if(mp.find(nxt) == mp.end() || now.SE + tmp + b < mp[nxt]){
			pq.push(MP(now.FI / 3, now.SE + tmp + b));
			mp[nxt] = now.SE + tmp + b;
		}

		tmp = (5 - now.FI % 5) * d;
		nxt = now.FI / 5 + 1;
		if(mp.find(nxt) == mp.end() || now.SE + tmp + c < mp[nxt]){
			pq.push(MP(now.FI / 5, now.SE + tmp + c));
			mp[nxt] = now.SE + tmp + c;
		}
	}

	cout << (ll)ans << endl;
}

