const ll INF = 2e18;

map<ll, ll> memo;

ll A, B, C, D;

ll solve(ll N) {
    if (memo.count(N)) return memo[N];

    if (N == 1) {
        memo[N] = D;
        return memo[N];
    }
    if (N == 0) {
        memo[N] = 0;
        return memo[N];
    }

    ll up_2   = solve( ceil((double)N/2)) + abs( ceil((double)N/2) * 2 - N) * D + A;
    ll down_2 = solve(floor((double)N/2)) + abs(floor((double)N/2) * 2 - N) * D + A;
    ll up_3   = solve( ceil((double)N/3)) + abs( ceil((double)N/3) * 3 - N) * D + B;
    ll down_3 = solve(floor((double)N/3)) + abs(floor((double)N/3) * 3 - N) * D + B;
    ll up_5   = solve( ceil((double)N/5)) + abs( ceil((double)N/5) * 5 - N) * D + C;
    ll down_5 = solve(floor((double)N/5)) + abs(floor((double)N/5) * 5 - N) * D + C;

    ll min_n = INF;
    if (N < INF / D) min_n = min(min_n, N * D);
    min_n = min(min_n, up_2);
    min_n = min(min_n, up_3);
    min_n = min(min_n, up_5);
    min_n = min(min_n, down_2);
    min_n = min(min_n, down_3);
    min_n = min(min_n, down_5);

    memo[N] = min_n;
    return memo[N];
}

