map<ll, ll> dp;
ll n, a, b, c, d;

ll f(ll n) {
    if (dp.count(n)) return dp[n];
    dp[n] = n * d;
    if (1e18 / n < d) dp[n] = 1e18;
    return dp[n] = min({
        dp[n],
        a + f(n / 2) + d * (n % 2),
        b + f(n / 3) + d * (n % 3),
        c + f(n / 5) + d * (n % 5),
        a + f((n + 1) / 2) + d * (2 - n % 2),
        b + f((n + 2) / 3) + d * (3 - n % 3),
        c + f((n + 4) / 5) + d * (5 - n % 5)
    });
}

