typedef long long ll;

priority_queue<pair<ll,ll>> q;

int main() {
	int t;
	cin >> t;
	while (t--) {
		ll n, a, b, c, d;
		cin >> n >> a >> b >> c >> d;
		while (q.size()) q.pop();
		q.push({0,n});
		ll p = 1e18;
		while (q.size()) {
			auto u = q.top();
			while (q.size() && q.top() == u) q.pop();
			if (-u.first >= p) continue;
			if (1e18/u.second >= d) q.push({u.first-d*u.second,0LL});
			for (int i = -4; i <= 4; i++) {
				ll f = -u.first+abs(i)*d;
				ll x = u.second+i;
				if (x < 0) continue;
				if (x == 0) {
					p = min(p,f);
					continue;
				}
				if (abs(i) < 2 && x%2 == 0) q.push({-f-a,x/2});
				if (abs(i) < 3 && x%3 == 0) q.push({-f-b,x/3});
				if (x%5 == 0) q.push({-f-c,x/5});
			}
		}
		cout << p << "\n";
	}
}

