using namespace std;

i128 compute(i64 n, map<i64,i128>& memo, i64 a, i64 b, i64 c, i64 d) {

	if(n == 1) {
		return d;
	}
	if(memo.count(n) > 0) {
		return memo[n];
	}
	i128 x = (i128)n * d;
	memo[n] = x;

	i64 next3 = n / 3 * 3;
	i64 next5 = n / 5 * 5;

	if(n - next3 > (next3 + 3) - n) {
		next3 += 3;
	}
	if(n - next5 > (next5 + 5) - n) {
		next5 += 5;
	}

	if(n % 2 == 0) {
		i128 y = compute(n / 2, memo, a, b, c, d) + a;
		x = min(x, y);
	} else {
		i128 y1 = compute((n - 1) / 2, memo, a, b, c, d) + a + d;
		i128 y2 = compute((n + 1) / 2, memo, a, b, c, d) + a + d;
		x = min(x, min(y1, y2));
	}

	i128 y3 = compute(next3 / 3, memo, a, b, c, d) + d * abs(next3 - n) + b;
	i128 y5 = compute(next5 / 5, memo, a, b, c, d) + d * abs(next5 - n) + c;
	x = min(x, min(y3, y5));

	return memo[n] = x;
}

