#define LL unsigned long long int
const LL INF = (1LL<<60);
const int INF_INT = 2147483647-1e6-1;
const LL mod = 1000000007ll;
const int mod_int = 1000000007;

LL T;
LL N[10],A[10],B[10],C[10],D[10];

LL ans[10];

unordered_map<LL,LL> cost;
int i=0;
LL dfs(LL num){
	//out << num << endl;
	if(num==1LU) return 0LU;
	if(num==2LU) return min(D[i],A[i]);
	if(cost[num]>0LU){
		//cout << "costret=" << num << endl;
		return cost[num];
	}

	LL ret = (INF/D[i]<num)?INF:D[i]*(num-1LU);

	if(num%2LU==0LU){
		LL divided = dfs(num/2LU);
		ret = min(ret,divided+A[i]);
		ret = min(ret,divided+D[i]*num/2LU);
	}else{
		LL divided_ceil = dfs((num+1LU)/2LU);
		ret = min(ret,divided_ceil+A[i]+D[i]);
		ret = min(ret,divided_ceil+((num+1LU)/2LU+1LU)*D[i]);
		LL divided_floor = dfs((num-1LU)/2LU);
		ret = min(ret,divided_floor+A[i]+D[i]);
		ret = min(ret,divided_floor+((num-1LU)/2LU+1LU)*D[i]);
	}

	if(num%3LU==0LU){
		LL divided = dfs(num/3LU);
		ret = min(ret,divided+B[i]);
		ret = min(ret,divided+D[i]*num*2LU/3LU);
	}else{
		LL upper = num-num%3LU+3LU;
		LL upper_diff = upper - num;
		LL divided_ceil = dfs(upper/3LU);
		ret = min(ret,divided_ceil+B[i]+D[i]*(upper_diff));
		ret = min(ret,divided_ceil+D[i]*(upper_diff + upper*2LU/3LU));

		LL lower = num-num%3LU;
		LL lower_diff = num - lower;
		LL divided_floor = dfs(lower/3LU);
		ret = min(ret,divided_floor+B[i]+D[i]*(lower_diff));
		ret = min(ret,divided_floor+D[i]*(lower_diff + lower*2LU/3LU));
	}

	if(num>=5LU){
		if(num%5LU==0LU){
			LL divided = dfs(num/5LU);
			ret = min(ret,divided+C[i]);
			ret = min(ret,divided+D[i]*num*4LU/5LU);
		}else{
			LL upper = num-num%5LU+5LU;
			LL upper_diff = upper - num;
			LL divided_ceil = dfs(upper/5LU);
			ret = min(ret,divided_ceil+C[i]+D[i]*(upper_diff));
			ret = min(ret,divided_ceil+D[i]*(upper_diff + upper*4LU/5LU));

			LL lower = num-num%5LU;
			LL lower_diff = num - lower;
			LL divided_floor = dfs(lower/5LU);
			ret = min(ret,divided_floor+C[i]+D[i]*(lower_diff));
			ret = min(ret,divided_floor+D[i]*(lower_diff + lower*4LU/5LU));
		}
	}

	cost[num] = ret;
	//cout << "cost[" << num << "]:" << cost[num] << endl;

	return ret;
}

void solve(){
	for(i=0;i<T;i++){
		ans[i] = dfs(N[i])+D[i];
		cost.clear();
	}
}

