ll A, B, C, D;
map<ll, ll> dp;
vector<ll> coin, cost;

ll solve(ll n) {
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return D;
    }
    if (dp.find(n) != dp.end()) {
        return dp[n];
    }
    ll tmpCost = INF;
    if (D < INF / n) {
        tmpCost = min(tmpCost, D * n);
    }
    for (int i = 0; i < 3; i++) {
        if (n % coin[i]) {
            ll div = n / coin[i];
            ll addKoro = (n % coin[i]) * D;
            ll subKoro = (((div + 1) * coin[i]) - n) * D;
//            cout << n << ": " << addKoro << " " << div << " coin: " << coin[i] << endl;
//            cout << n << ": " << subKoro << " " << div + 1 << endl << endl;
            tmpCost = min(tmpCost, solve(n / coin[i]) + cost[i] + addKoro);
            tmpCost = min(tmpCost, solve(div + 1) + cost[i] + subKoro);
        } else {
            tmpCost = min(tmpCost, solve(n / coin[i]) + cost[i]);
        }
    }
    return dp[n] = tmpCost;
}

