ll A, B, C, D;
map<ll, ll> memo;

ll Solve(ll N) {
	if (N == 0) { return 0; }
	if (memo.count(N)) { return memo[N]; }
	ll ans = 1e18;
	if (N < 3e9) { ans = N * D; }
	for (int p = -1; p <= 1; ++p) {
		ll x = N + p;
		if (x < 0 || x % 2 != 0) { continue; }
		ll y = x / 2;
		if (y < N) {
			chmin(ans, abs(p) * D + A + Solve(y));
		}
	}

	for (int p = -2; p <= 2; ++p) {
		ll x = N + p;
		if (x < 0 || x % 3 != 0) { continue; }
		ll y = x / 3;
		if (y < N) {
			chmin(ans, abs(p) * D + B + Solve(y));
		}
	}

	for (int p = -4; p <= 4; ++p) {
		ll x = N + p;
		if (x < 0 || x % 5 != 0) { continue; }
		ll y = x / 5;
		if (y < N) {
			chmin(ans, abs(p) * D + C + Solve(y));
		}
	}
    memo[N]=ans;
	return memo[N];
}


int main() {
