ll a, b, c, d;
const ll inf = 1LL<<60;
map<ll, ll> mp;

ll rec(ll now) {
    if (now == 0) return 0;
    if (mp.count(now)) {
        return mp[now];
    }
    ll res = inf;
    if (now < inf / d) chmin(res, now * d);
    for (int x : vector<int>{2, 3, 5}) {
        ll cost;
        if (x == 2) cost = a;
        else if (x == 3) cost = b;
        else cost = c;
        ll k = now % x;
        if (k * d <= (x-k) * d) chmin(res, rec((now-k)/x) + d*k + cost);
        else chmin(res, rec((now+(x-k))/ x) + (x-k)*d + cost);
    }
    return mp[now] = res;
}

void solve() {
    ll n;
    cin >> n >> a >> b >> c >> d;
    cout << rec(n) << endl;
    mp.clear();
}

