std::vector<int> results;
unsigned long long int N;
int T, i, coins, start;
unsigned long int A, B, C, D;

int calc(unsigned long long int n, int num_coins)
{
    if(n == N)
        return num_coins;

    else if(n > N+1)
        return -1;

    else
    {
        int min_coins = -1, res;

        if(n > N)
            return calc(n-1, num_coins+D);

        else if(n == 0)
            return calc(n+1, num_coins+D);

        else
        {
            res = calc(n*2, num_coins+A);
            if(res != -1)
                if(min_coins == -1)
                    min_coins = res;

            res = calc(n*3, num_coins+B);
            if(res != -1)
                if(min_coins == -1 || min_coins > res)
                    min_coins = res;

            res = calc(n*5, num_coins+C);
            if(res != -1)
                if(min_coins == -1 || min_coins > res)
                    min_coins = res;

            res = calc(n+1, num_coins+D);
            if(res != -1)
                if(min_coins == -1 || min_coins > res)
                    min_coins = res;
        }

        return min_coins;
    }
}

