const int64_t INF = 1LL << 62;

void solve()
{
  int64_t n, a, b, c, d;
  cin >> n >> a >> b >> c >> d;
  vector<pair<int, int64_t>> vp;
  vp.emplace_back(2, a);
  vp.emplace_back(3, b);
  vp.emplace_back(5, c);
  map<int64_t, int64_t> mp;
  mp[0] = 0;
  mp[1] = d;
  function<int64_t(int64_t)> dfs = [&](int64_t x) {
    if (mp.find(x) != mp.end())
    {
      return mp[x];
    }
    int64_t ret = INF, tmp = d * x;
    if (!__builtin_smulll_overflow(d, x, &tmp))
    {
      ret = d * x;
    }
    for (auto &p : vp)
    {
      int64_t num, cost;
      tie(num, cost) = p;
      ret = min(ret, dfs(x / num) + cost + d * (x % num));
      if (x % num != 0)
      {
        ret = min(ret, dfs(x / num + 1) + cost + d * (num - x % num));
      }
    }
    return mp[x] = ret;
  };
  cout << dfs(n) << endl;
}

