ll A,B,C,D;
ll solve(ll N){
  if(N==0)return 0;
  if(N==1)return D;
  priority_queue<pll,vector<pll>,greater<pll>> q;
  set<ll> visited;
  q.push(pll(0,N));
  while(!q.empty()){
    auto cur=q.top();q.pop();
    ll cost=cur.first,num=cur.second;
    if(visited.count(num))continue;
    visited.insert(num);
    if(num==0)return cost;
    if(num==1)return cost+D;
    auto push=[&](pll x){
      if(visited.count(x.second)==0){
        q.push(x);
      }
    };
    if(num/5*4<=C/D&&num/3*2<=B/D&&num/2<=A/D)push(pll(cost+num*D,0));
    push(pll(cost+A+num%2*D,num/2));
    if(num%2)push(pll(cost+A+D,num/2+1));
    push(pll(cost+B+num%3*D,num/3));
    if(num%3)push(pll(cost+B+D,num/3+1));
    push(pll(cost+C+num%5*D,num/5));
    if(num%5)push(pll(cost+C+D,num/5+1));
  }
}
