const long long inf = 4000000000000000000;

long long a, b, c, d;

map<long long, long long> dp;

long long dfs(long long n) {
	if(n <= 1) {
		return n * d;
	}

	if(n == 2) {
		return min(d * 2, a + d);
	}

	if(dp.count(n)) {
		return dp[n];
	}

	long long ret = inf;
	if(inf / d >= n) {
		ret = min(ret, n * d);
	}

	int x;

	if(n > 2) {
		x = n % 2;
		ret = min(ret, dfs(n / 2) + a + d * x);
		ret = min(ret, dfs(n / 2 + 1) + a + d * (2 - x));
	}

	if(n > 3) {
		x = n % 3;
		ret = min(ret, dfs(n / 3) + b + d * x);
		ret = min(ret, dfs(n / 3 + 1) + b + d * (3 - x));
	}

	if(n > 5) {
		x = n % 5;
		ret = min(ret, dfs(n / 5) + c + d * x);
		ret = min(ret, dfs(n / 5 + 1) + c + d * (5 - x));
	}

	return dp[n] = ret;
}

