long long calc(long long N, long long A, long long B, long long C, long long D, map<long long, long long>& Memo) {
	if (N == 0ll) return 0ll;
	if (N == 1ll) return D;
	if (Memo.find(N) != Memo.end()) return Memo[N];
	vector<long long>next = { N / 2ll, (N + 1ll) / 2ll, N / 3ll, (N + 2ll) / 3ll, N / 5ll, (N + 4ll) / 5ll };
	vector<long long>P = { 2ll,2ll,3ll,3ll,5ll,5ll };
	vector<long long>Q = { A,A,B,B,C,C };
	vector<long long>Ans(6);
	for (int i = 0; i < 6; i++) {
		Ans[i] = D * abs(N - next[i] * P[i]) + Q[i] + calc(next[i], A, B, C, D, Memo);
		if (i == 0) Memo[N] = Ans[i];
		Memo[N] = min(Memo[N], Ans[i]);
	}
	if (log(Memo[N]) >= log(N)+log(D)) Memo[N] = min(Memo[N], D * N);
	return Memo[N];
}

