const int N = 5e4 + 500;
const int MOD = 1e9 + 7;
const int INF = 0x3f3f3f3f;

unordered_map < ll, ll > dp;
ll A, B, C, D;

ll f(ll x){
	if(!x) return 0;
	if(dp[x]) return dp[x];
	ll ret = (ll)INF * INF;
	if(x < 1e9) ret = D * x;
	ret = min(ret, f(x / 2LL) + A + D * (x % 2LL));
	ret = min(ret, f(x / 3LL) + B + D * (x % 3LL));
	ret = min(ret, f(x / 5LL) + C + D * (x % 5LL));
	if(x / 2LL + 1LL != x)
		ret = min(ret, f(x / 2LL + 1LL) + A + D * (2LL - x % 2LL));
	if(x / 3LL + 1LL != x)
		ret = min(ret, f(x / 3LL + 1LL) + B + D * (3LL - x % 3LL));
	if(x / 5LL + 1LL != x)
		ret = min(ret, f(x / 5LL + 1LL) + C + D * (5LL - x % 5LL));
	return dp[x] = ret;
}


