map<ll, ll> memo;
ll A, B, C, D, N;

ll f(ll goal) {

    if (memo.count(goal)) return memo[goal];
    if (goal == 0) return 0;
    if (goal == 1) return D;

    ll best = D * goal;
    if (D < INF / goal) {
        best = min(best, D * goal);
    }

    for (int i = 0; i < 3; i++) {
        auto mul = vector<ll>{ 2, 3, 5 }[i];
        auto cost = vector<ll> { A, B, C }[i];
        if (goal % mul == 0) {
            best = min(best, cost + f(goal / mul));
        }
        else {
            ll down = goal / mul * mul;
            ll v1 = cost + f(goal / mul) + (goal - down) * D;
            ll up = down + mul;
            ll v2 = cost + f(goal / mul + 1) + (up - goal) * D;
            best = min(best, v1);
            best = min(best, v2);
        }
    }
    return memo[goal] = best;
}


