int T;
vector<unsigned long> N;
vector<unsigned int> A, B, C, D;

long calcu(unsigned long N, int num) {
	int d2 = 0;
	int d3 = 0;
	int d5 = 0;
	unsigned long tempN = N;
	while ((tempN % 2) == 0) {
		d2++;
		tempN /= 2;
	}
	while ((tempN % 3) == 0) {
		d3++;
		tempN /= 3;
	}
	while ((tempN % 5) == 0) {
		d5++;
		tempN /= 5;
	}
	return (A[num] * d2) + (B[num] * d3) + (C[num] * d5) + D[num];
}

int main() {
	cin >> T;
	for (int i = 0; i < T; i++) {
		unsigned long n;
		unsigned int a, b, c, d;
		cin >> n >> a >> b >> c >> d;
		N.push_back(n);
		A.push_back(a);
		B.push_back(b);
		C.push_back(c);
		D.push_back(d);
	}
	for (int i = 0; i < T; i++) {
		// Nを因数分解
		unsigned long ans = 1;
		vector<int> x(100);
		unsigned long num = N[i];
		for (unsigned long i = 2; i <= N[i]; i++) {
			while (num % i == 0) {
				x.at(i)++;
				num /= i;
			}
		}
		for (unsigned long i = 2; i <= N[i]; i++) {
			ans *= x.at(i) + 1;
		}
		if (ans == 1) {
			// 素数+1だった場合
			long res1 = calcu(N[i] + 1, i) + D[i];
			// 素数-1だった場合
			long res2 = calcu(N[i] - 1, i) + D[i];
			if (res1 < res2) {
				cout << res1 << endl;
			} else {
				cout << res2 << endl;
			}
		} else {
			cout << calcu(N[i], i) << endl;
		}
	}
	return 0;
}

