typedef long long Int;

Int A, B, C, D;
map<Int,Int> m;


Int llmin(Int A, Int B) {
    if (A < B) return A;
    else return B;
}

Int solve(Int N) {
    if (N == 0) return 0;
    if (N == 1) return D;
    if (m.count(N)) return m[N];

    Int l2 = (N/2)*2;
    Int r2 = ((N+1)/2)*2;

    Int l3 = (N/3)*3;
    Int r3 = ((N+1)/3)*3;

    Int l5 = (N/5)*5;
    Int r5 = ((N+1)/5)*5;

    Int res = 1e18;
    if (N < res/D) res = N * D;

    res = llmin(res, llabs(l2-N)*D + A + solve(l2/2));
    res = llmin(res, llabs(r2-N)*D + A + solve(r2/2));

    res = llmin(res, llabs(l3-N)*D + B + solve(l3/2));
    res = llmin(res, llabs(r3-N)*D + B + solve(r3/2));

    res = llmin(res, llabs(l5-N)*D + C + solve(l5/2));
    res = llmin(res, llabs(r5-N)*D + C + solve(r5/2));

    m[N] = res;

    return res;
}

int main() {
    int T; cin >> T;

    for (int t = 0; t < T; t++) {
        m.clear();
        Int N; cin >> N;
        cin >> A >> B >> C >> D;

        cout << solve(N) << "\n";
