//const ll MOD = 1e9+7;
//const ll MOD = 998244353;
//const ll MAX = 3e5+1;
const ll INF = (ll) 1e18;
//const ld PI = acos(-1);

ll calc(ll n, ll a, ll b, ll c, ll d, ll curr, unordered_map<ll, ll>& cache) {
    if (cache.find(n) != cache.end()) return curr + cache.at(n);
    ll ans;
    if (abs(n) < 1e9) ans = curr + abs(n) * d;
    else ans = INF;

    if (n % 2 == 0) {
        ll ca = calc(n / 2LL, a, b, c, d, curr+a, cache);
        ans = min(ans, ca);
    }
    if (n % 3 == 0) {
        ll ca = calc(n / 3LL, a, b, c, d, curr+b, cache);
        ans = min(ans, ca);
    }
    if (n % 5 == 0) {
        ll ca = calc(n / 5LL, a, b, c, d, curr+c, cache);
        ans = min(ans, ca);
    }
    if (n % 2LL != 0 && n % 3LL != 0 && n % 5LL != 0) {
        ll ca = calc(n-1, a, b, c, d, curr+d, cache);
        ans = min(ans, ca);
        ca = calc(n+1, a, b, c, d, curr+d, cache);
        ans = min(ans, ca);
    }
    //out(n << ' ' << ans - curr);
    //out(n << ' ' << ans << ' ' << curr);
    cache.insert(make_pair(n, ans-curr));
    return ans;
}

