        ll N, A, B, C, D;
        in(N); in(A); in(B); in(C); in(D);
        unordered_map<ll, ll> cache;
        cache.clear();
        cache[-1] = D;
        cache[0] = 0;
        cache[1] = D;
        ll ans = calc(N, A, B, C, D, 0, cache);
        out(ans);
    }

    return 0;
}

