ll a, b, c, d;

map<ll, ll> m;

ll floor(ll a, ll b) {
    return a / b;
}
ll ceil(ll a, ll b) {
    return (a + b - 1) / b;
}

ll solve(ll x) {
    if (x == 0) return 0;
    if (x == 1) return d;
    if (m.count(x)) return m[x];

    ll l2 = floor(x, 2) * 2;
    ll r2 =  ceil(x, 2) * 2;
    ll l3 = floor(x, 3) * 3;
    ll r3 =  ceil(x, 3) * 3;
    ll l5 = floor(x, 5) * 5;
    ll r5 =  ceil(x, 5) * 5;

    ll res = 1e18;
    if (x < res / d) res = x * d;
    chmin(res, abs(l2 - x) * d + a + solve(l2 / 2));
    chmin(res, abs(r2 - x) * d + a + solve(r2 / 2));
    chmin(res, abs(l3 - x) * d + b + solve(l3 / 3));
    chmin(res, abs(r3 - x) * d + b + solve(r3 / 3));
    chmin(res, abs(l5 - x) * d + c + solve(l5 / 5));
    chmin(res, abs(r5 - x) * d + c + solve(r5 / 5));

    m[x] = res;
    return res;
}

