template <typename Tu>
static inline constexpr bool is_multiplication_safe(Tu a, Tu b)
{
    return !a || b <= std::numeric_limits<Tu>::max() / a;
}

ll d[3];
map<ll, ll> m;
ll N, A, B, C, D;
ll ans;

ll dfs(ll val){
	if(m.find(val) != m.end()){
		return m[val];
	}
	if(val == 1) return 0;
	ll res = LLINF;
	if(is_multiplication_safe(D, (val-1))) res = D * (val - 1);
	rep(i, 3){
		ll res2 = 0;
		ll tmp = val - val % d[i];
		res2 += (val % d[i]) * D;
		if(tmp == 0){
			res = min(res, res2 - D);
			continue;
		}
		res2 += dfs(tmp / d[i]);
		if(i == 0) res2 += A;
		else if(i == 1) res2 += B;
		else if(i == 2) res2 += C;
		res = min(res, res2);
	}
	return m[val] = res;
}
