namespace hashcode {
template <class... Ts> ll hash_args(ll h, Ts const &... ts) {
  using swallow = std::initializer_list<int>;
  auto f = [](auto const &a) {
    using T = std::remove_const_t<std::remove_reference_t<decltype(a)>>;
    return std::hash<T>{}(a);
  };
  (void)swallow{(void(h = ((h << 19) - h) ^ f(ts)), 0)...};
  return h ^ (h >> 32);
}
