ll dp(ll n, ll p){
	if(n == 0) return 0;
    if(m[n] != 0) return m[n];
    ll ans = INF;
    for(ll i = n-5; i <= n+5; i++){
    	if(i < 0) continue;
    	ll diff = abs(i-n);
    	if(i == 0){
    		ans = min(ans , diff*d);
    		continue;
		}
		if(i == p) continue; 
		if(i%2 == 0){
			if(i/2 == n) continue;
			ll kt = i/2;
			ll h = a;
			if(amt(kt)) h = (kt)*d; 
			ans = min(ans , ((diff*d) + min( a , h  ) ) + dp(i/2 , n));
		}
		if(i%3 == 0){
			if(i/3 == n) continue;
			ll kt = 2*(i/3);
			ll h = b;
			if(amt(kt)) h = (kt)*d; 
			ans = min(ans , ((diff*d) + min( b ,h)  ) + dp(i/3 , n) );
		}
		if(i%5 == 0){
			if(i/5 == n) continue;
			ll kt = 4*(i/5);
			ll h = c;
			if(amt(kt)) h = (kt)*d; 
			ans = min(ans , ((diff*d) + min( c , h ) )  + dp(i/5 , n));
		}
	} 
