#define HASH 100003

typedef struct List {
	struct List* next;
	unsigned long long v;
} list;

typedef struct {
	unsigned long long key, id;
} data;

typedef struct {
	data obj[1000000];
	int size;
} min_heap;

void push(data x, min_heap* h)
{
	int i = h->size;
	data tmp;
	h->obj[(h->size)++] = x;
	while (1) {
		if (i == 0) break;
		else if (h->obj[i].key < h->obj[(i-1)/2].key) {
			tmp = h->obj[(i-1)/2];
			h->obj[(i-1)/2] = h->obj[i];
			h->obj[i] = tmp;
			i = (i - 1) / 2;
		} else break;
	}
}

data pop(min_heap* h)
{
	int i = 0, j;
	data output = h->obj[0], tmp;
	h->obj[0] = h->obj[--(h->size)];
	while (1) {
		if (i * 2 + 1 >= h->size) break;
		else if (i * 2 + 2 >= h->size) j = i * 2 + 1;
		else if (h->obj[i*2+1].key < h->obj[i*2+2].key) j = i * 2 + 1;
		else j = i * 2 + 2;
		if (h->obj[j].key < h->obj[i].key) {
			tmp = h->obj[j];
			h->obj[j] = h->obj[i];
			h->obj[i] = tmp;
			i = j;
		} else break;
	}
	return output;
}

int main()
{
	int i, j, k, T;
	unsigned long long N, A, B, C, D, tmp, cost;
	const unsigned long long sup = 0xffffffffffffffff;
	list *p, *hash[HASH], e[1000000];
	data d;
	min_heap h;
	scanf("%d", &T);
	for (i = 1; i <= T; i++) {
		scanf("%llu %llu %llu %llu %llu", &N, &A, &B, &C, &D);

		for (j = 0, k = 0; j < HASH; j++) hash[j] = NULL;
		h.size = 0;
		d.key = 0;
		d.id = N;
		push(d, &h);

		while (h.obj[0].id > 0) {
			d = pop(&h);
			j = d.id % HASH;
			for (p = hash[j]; p != NULL; p = p->next) if (p->v == d.id) break;
			if (p != NULL) continue;

			e[k].v = d.id;
			e[k].next = hash[j];
			hash[j] = &(e[k++]);
			tmp = d.id;
			cost = d.key;

			if (tmp <= (sup - cost) / D) {
				d.id = 0;
				d.key = cost + D * tmp;
				push(d, &h);
			}

			for (j = 0; j <= 1; j++) {
				if ((tmp + j) % 2 == 0) {
					d.id = (tmp + j) / 2;
					d.key = cost + A + D * j;
					push(d, &h);
					if (tmp > j && j != 0) {
						d.id = (tmp - j) / 2;
						push(d, &h);
					}
				}
			}

			for (j = 0; j <= 2; j++) {
				if ((tmp + j) % 3 == 0) {
					d.id = (tmp + j) / 3;
					d.key = cost + B + D * j;
					push(d, &h);
