			for (j = 0; j <= 4; j++) {
				if ((tmp + j) % 5 == 0) {
					d.id = (tmp + j) / 5;
					d.key = cost + C + D * j;
					push(d, &h);
				}
				if (tmp > j && j != 0 && (tmp - j) % 5 == 0) {
					d.id = (tmp - j) / 5;
					d.key = cost + C + D * j;
					push(d, &h);
				}
			}
