ll func(ll n){
	if(!n)return 0;
	if(n==1)return d;
	if(mp[n])return mp[n];
	ll ans=LLONG_MAX;
	if(n<(7*1e18)/d)ans=min(ans,n*d);
	if(n%2==0)ans=min(ans,a+func(n/2));
	else{
		ll k=n/2;
		k*=2;
		ans=min(ans,abs(n-k)*d+a+func(k/2));
		k+=2;
		ans=min(ans,abs(n-k)*d+a+func(k/2));
	}
	if(n%3==0)ans=min(ans,b+func(n/3));
	else{
		ll k=n/3;
		k*=3;
		ans=min(ans,abs(n-k)*d+b+func(k/3));
		k+=3;
		ans=min(ans,abs(n-k)*d+b+func(k/3));
	}
	if(n%5==0)ans=min(ans,c+func(n/5));
	else{
		ll k=n/5;
