typedef long long ll;
const ll INF=9e18;
int T,cnt;
ll n,a,b,c,d;
map<ll,ll> M;
ll solve(ll x) {
	if (M[x]) return M[x];
	if (!x) return M[x]=0;
	M[x]=INF;
	if (x<INF/d) M[x]=x*d;
	if (x%2==0) M[x]=min(M[x],solve(x/2)+a);
	else M[x]=min(M[x],min(solve(x/2),solve(x/2+1))+a+d);
	ll y;
	if (x%3==0) M[x]=min(M[x],solve(x/3)+b);
	else {
		y=x/3;
		M[x]=min(M[x],min(solve(y)+(x%3)*d,solve(y+1)+(3-x%3)*d)+b);
	}
	if (x%5==0) M[x]=min(M[x],solve(x/5)+c);
	else {
		y=x/5;
		M[x]=min(M[x],min(solve(y)+(x%5)*d,solve(y+1)+(5-x%5)*d)+c);
	}
	cnt++;
	return M[x];
}
