fun solve() {
    val t = nextLong().toInt()
    val ansList = longList()

    repeat(t) {
        val n = nextLong()
        val a = nextLong()
        val b = nextLong()
        val c = nextLong()
        val d = nextLong()
        val coin = longArrayOf(2, 3, 5)
        val price = longArrayOf(a, b, c)
        val memo = map<Long, Long>()
        memo[0] = 0L

        fun dfs(m: Long): Long {
            memo[m].also { if(it != null) return it }
            var ans = INF
            if(ans / d > m) ans = d * m
            for (i in 0..2) {
                val co = coin[i]
                val pr = price[i]
                val s = m / co
                val t = m % co
                ans = min(ans, dfs(s) + pr + t * d)
                if(t == 0L) continue
                if(s + 1 >= m) continue
                ans = min(ans, dfs(s + 1) + pr + (co - t) * d)
            }
            memo[m] = ans
            return ans
        }

        ansList.add(dfs(n))

    }

    println(ansList.joinToString("\n"))

}



