			val dy = intArrayOf(0, 0, -1, 1)

			var n = `in`.nextLong()
			var a = LongArray(3, {`in`.nextLong()})
			var b = longArrayOf(2, 3, 5)
			var d = `in`.nextLong()

			var f = TreeMap<Long, Long>()
			f[0] = 0
			fun solve(n: Long): Long
			{
				if (f.contains(n)) return f[n]!!
				var ret = INF
				for (i in 0..2)
				{
					for (x in arrayOf(n/b[i], n/b[i]+1))
						if (x < n)
						{
							ret = Math.min(ret, solve(x)+a[i]+Math.abs(n-x*b[i])*d)
							if (x*(b[i]-1) <= a[i]/d) ret = Math.min(ret, solve(x)+x*(b[i]-1)*d+Math.abs(n-x*b[i])*d)
						}
				}
				f[n] = ret
				return ret
			}

			var res = solve(n)
			out.println(res)
		}

	}

	internal class InputReader(stream: InputStream) {
		var reader: BufferedReader
		var tokenizer: StringTokenizer? = null

		init {
			reader = BufferedReader(InputStreamReader(stream), 32768)
			tokenizer = null
		}

		operator fun next(): String {
			while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
				try {
					tokenizer = StringTokenizer(reader.readLine())
				} catch (e: IOException) {
					throw RuntimeException(e)
				}

			}
			return tokenizer!!.nextToken()
		}

		fun nextInt(): Int {
			return Integer.parseInt(next())
		}

		fun nextLong(): Long {
		    return next().toLong()
		}

	}
