data class Task(val n: Long, val a: BigInteger, val b: BigInteger, val c: BigInteger, val d: BigInteger) {
    val solutions = mutableMapOf<Long, BigInteger>()

    var pre = false
    fun solve(n: Long): BigInteger {
        if (!pre) {
            pre = true
            solutions[1L] = d
            solutions[2L] = listOf(solutions[1]!! + d, solutions[1]!! + a).min()!!
            solutions[3L] = listOf(3 * d, solutions[2]!! + d, solutions[1]!! + c).min()!!
            solutions[4L] = listOf(4 * d, solutions[2]!! + a, solutions[3]!! + d).min()!!
            solutions[5L] = listOf(5 * d, solutions[4]!! + d, solutions[3]!! + 2 * d, solutions[3]!! + a + d).min()!!
        }


        if (solutions.containsKey(n)) return solutions[n]!!

        if (n == 0L) return BigInteger.ZERO

        val variants = mutableListOf<BigInteger>()
        variants.add(n.big * d)
        for (i in -1..1) if ((n + i) > 0 && (n + i) % 2 == 0L) {
            variants.add(abs(i) * d + solve((n + i) / 2) + a)
        }

        for (i in -2..2) if ((n + i) > 0 && (n + i) % 3 == 0L) {
            variants.add(abs(i) * d + solve((n + i) / 3) + b)
        }

        for (i in -5..5) if ((n + i) > 0 && (n + i) % 5 == 0L) {
            variants.add(abs(i) * d + solve((n + i) / 5) + c)
        }


        val ans = variants.min()!!

        solutions[n] = ans
        return ans
    }


}

