import java.lang.Exception
import kotlin.math.abs

fun solve(): Long {
    val input = readLine()!!.split(" ").map(String::toLong)
    val N = input[0];
    val A = input[1];
    val B = input[2];
    val C = input[3];
    val D = input[4];

    var minCost = Long.MAX_VALUE

    if (N == 1L) {
        return D
    }

    outeri@for(i in 0 until 100) {
        var pow2 = 1
        if (i==0) {
            pow2 = 1;
        } else if (i==1) {
            pow2 = 2;
        } else {
            pow2 = 2;
            for (z in 0 until i-1) {
                try {
                    pow2 = Math.multiplyExact(pow2, 2)
                } catch (e: Exception) {
                    break@outeri
                }
            }
        }

        outerj@for(j in 0 until 100) {
            var pow3 = 1
            if (j==0) {
                pow3 = 1;
            } else if (j==1) {
                pow3 = 3;
            } else {
                pow3 = 3;
                for (z in 0 until j-1) {
                    try {
                        pow3 = Math.multiplyExact(pow3, 3)
                    } catch (e: Exception) {
                        break@outerj
                    }
                }
            }

            outerk@for(k in 0 until 100) {
                var pow5 = 1
                if (k==0) {
                    pow5 = 1;
                } else if (k==1) {
                    pow5 = 5;
                } else {
                    for (z in 0 until k-1) {
                        pow5 = 5;
                        try {
                            pow5 = Math.multiplyExact(pow5, 5)
                        } catch (e: Exception) {
                            break@outerk
                        }
                    }
                }
                try {
                    var ci = i;
                    var cj = j;
                    var ck = k;

                    val t = Math.multiplyExact(Math.multiplyExact(pow2,pow3), pow5)
                    var l = abs(N-t)

                    // Dを足すコストのほうが低かったらこうかん？

                    val iA = Math.multiplyExact(ci.toLong(),A)
                    val jB = Math.multiplyExact(cj.toLong(),B)
                    val kC = Math.multiplyExact(ck.toLong(),C)
                    val lD = Math.multiplyExact(l, D)

                    val cost = Math.addExact(iA, Math.addExact(jB, Math.addExact(kC, lD)))


                    if (cost < minCost) {
                        minCost = cost
                    }
                } catch (e: Exception) {
                    break@outerk
                }
            }
        }
    }

    return minCost + D;
}


