			val INF = 4000000000000000000L
			val dx = intArrayOf(-1, 1, 0, 0)
			val dy = intArrayOf(0, 0, -1, 1)

			var n = `in`.nextLong()
			var a = LongArray(3, {`in`.nextLong()})
			var b = longArrayOf(2, 3, 5)
			var d = `in`.nextLong()

