// Global

fun solve() {
    val list = longList()

    repeat(nextLong().toInt()) {
        val n = nextLong()
        val a = nextLong()
        val b = nextLong()
        val c = nextLong()
        val d = nextLong()
        val price = longArrayOf(a, b, c)
        val coin = longArrayOf(2, 3, 5)
        val memo = map<Long, Long>()
        memo[0L] = 0L


        fun func(m: Long): Long {
            memo[m].also { if (it != null) return it }
            var ans = INF
            if(ans / d > m) ans = m * d
            for (i in 0..2) {
                val c = coin[i]
                val p = price[i]
                val s = m / c
                val t = m % c
                ans = min(ans, func(s) + p + t * d)
                if(t == 0L) continue
                if(s + 1 >= m) continue
                ans = min(ans, func(s + 1) + p + (c - t) * d)
            }
            memo[m] = ans
            return ans
        }

        list.add(func(n))
    }

    println(list.joinToString("\n"))
}



