fun main(){
    val t = readLine()!!.toInt()
    repeat(t){
        val (n, a, b, c, d) = readLine()!!.split(" ").map(String::toLong)
        var ans = Long.MAX_VALUE / 10

        fun search(now: Long, coin: Long){
            if(ans < coin){
                return
            }
            if(now == 0L){
                ans = min(ans, coin)
            }else if(now == 1L){
                ans = min(ans, coin + d)
            }else{
                val array = arrayOf(Pair(2, a), Pair(3, b), Pair(5, c))
                array.forEach {
                    if(now % it.first == 0L){
                        search(now / it.first, coin + it.second)
                    }else{
                        val remainder = now % it.first
                        search(now + it.first - remainder, coin + d * (it.first - remainder))
                        search(now - remainder, coin + d * remainder)
                    }
                }
            }
        }
        search(n, 0L)
        println(ans)
    }
}

import java.util.*
import kotlin.math.min

fun main() {

    val coins = arrayOf(2L,3L,5L) //61, 39, 27

    val sc = Scanner(System.`in`)
    val t = sc.nextInt()

    repeat(t) {
        val n = sc.nextLong()
        val costs = LongArray(3)
        costs[0] = sc.nextLong()
        costs[1] = sc.nextLong()
        costs[2] = sc.nextLong()

        val d = sc.nextLong()
        val cache = HashMap<Long,Long>()

        fun bestCost(v:Long, c:Int, p : Long, r:Long): Long {
            if(p == 0L)
                return r * d
            val remainder = r * d
            val cost = costs[c] + remainder
            val diff = v - p
            val costD = diff * d
            if(costD <= 0)
                return cost
            return min(costD, cost)
        }

        fun solve(remain:Long): Long {
            if(remain == 0L)
                return 0L
            if(remain == 1L)
                 return d
            if(cache.contains(remain)) {
                return cache[remain]!!
            }
            var best = Long.MAX_VALUE
            for(i in coins.indices) {
                val c = coins[i]
                val p = remain / c
                val r = remain % c
                val up = p + 1L
                val ur = c - r
                best = min(best, bestCost(remain, i, p, r) + solve(p))
                if(ur == c) {
                    continue
                }
                best = min(best, bestCost(up * remain, i, up, ur) + solve(up))
            }
            cache[remain] = best
            return best
        }
        println(solve(n))


    }


}

