                    if (d * 4 / 5 > MAX / i) {
                        res += c;
                    } else {
                        res += Math.min(d * (i / 5) * 4, c);
                    }

                    tmpMinRes = Math.min(tmpMinRes, res);
                }

                if (tmpMinRes != 1e18 + 7) {
                    long diff = Math.abs(i - n);
                    long curMinRes = diff * d;
                    tmpMinRes += curMinRes;
                    minRes = Math.min(minRes, tmpMinRes);
                }

            }

            memoMap.put(n, minRes);
            return minRes;
        }

