  static void t(long num, long coin) {

    if (num <= 0 || N * 5 <= num)
      return;

    if (cCoin.containsKey(num) && cCoin.get(num) < coin)
      return;

    cCoin.put(num, coin);

    if (N == num)
      cheapest = Math.min(cheapest, coin);

    else {
      t(num * 2, coin + A);
      t(num * 3, coin + B);
      t(num * 5, coin + C);
      t(num + 1, coin + D);
      t(num - 1, coin + D);
    }

  }

}

