class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    //Scanner sc = new Scanner("1 900000000000000000 332423423 454353412 934923490 987654321");
    int T = sc.nextInt();
    for (int i = 0; i < T; i++) {
      long N = sc.nextLong();
      int A = sc.nextInt();
      int B = sc.nextInt();
      int C = sc.nextInt();
      int D = sc.nextInt();
