	private static long calc(Map<Long, Long> num, long n, Abcd abcd, Map<Long, Boolean> numB) {
		if (num.containsKey(n)) {
			return num.get(n);
		}
		boolean isbeishu = false;
		long n1 = MAX;
		long n2 = MAX;
		long n3 = MAX;
		long n4 = MAX;
		long n5 = MAX;
		if (n % 5 == 0) {
			numB.put(n/5, true);
			long temp = calc(num, n/5, abcd, numB);
			if (isMax(temp)) {
				n3 = MAX;
			} else {
				n3 = temp + abcd.c;
			}
		}
		if (n % 3 == 0) {
			numB.put(n/3, true);
			long temp = calc(num, n/3, abcd, numB);
			if (isMax(temp)) {
				n4 = MAX;
			} else {
				n4 = temp + abcd.b;
			}
		}
		if (n % 2 == 0) {
			numB.put(n/2, true);
			long temp = calc(num, n/2, abcd, numB);
			if (isMax(temp)) {
				n5 = MAX;
			} else {
				n5 = temp + abcd.a;
			}
		}
		if (n <= abcd.n + 5 & n >= abcd.n) {
			long temp = calc(num, n + 1, abcd, numB);
			if (isMax(temp)) {
				n1 = MAX;
			} else {
				n1 = temp + abcd.d;
			}
		} else {
			if (numB.containsKey(n) && numB.get(n)) {
				long temp = calc(num, n + 1, abcd, numB);
				if (isMax(temp)) {
					n1 = MAX;
				} else {
					n1 = temp + abcd.d;
				}
			}
		}
		if (n >= abcd.n - 5 & n <= abcd.n) {
			long temp = calc(num, n - 1, abcd, numB);
			if (isMax(temp)) {
				n2 = MAX;
			} else {
				n2 = temp + abcd.d;
			}
		} else {
			if (numB.containsKey(n) && numB.get(n)) {
				long temp = calc(num, n - 1, abcd, numB);
				if (isMax(temp)) {
					n2 = MAX;
				} else {
					n2 = temp + abcd.d;
				}
			}
		}


		long min = Math.min(Math.min(Math.min(n1, n2), Math.min(n3, n4)), n5);
		num.put(n, min);
		return min;

	}

	private static boolean isMax(long num) {
		return num == MAX;
	}



