        boolean ret=false;
        if(num>=0) {
            if (!map.containsKey(num)) {
                map.put(num, cost);
                ret = true;
            } else {
                if (map.get(num) > cost) {
                    map.put(num, cost);
                    ret = true;
                }
            }
        }
        return ret;
    }
