        }else{
            if(map.get(num)>cost){
                map.put(num,cost);
            }
        }
    }
    boolean isEmpty(){
        return map.isEmpty();
    }
}

import java.util.HashMap;
import java.util.Scanner;

public class Solution {

    long convert(long N, int A, int B, int C, int D) {
        long i = 1;
        HashMap<Long, Long> map = new HashMap<>();
        map.put(i, (long) D);
        long bound = N + 5;
        for (i = 1; i <= bound; i++) {
            if (2 * i <= bound) {
                if (map.containsKey(2 * i)) {
                    if (map.get(i) + A < map.get(2 * i)) {
                        map.put(2 * i, Math.min(map.get(i) + A, map.get(2 * i)));
                    }
                } else {
                    map.put(2 * i, map.get(i) + A);
                }
            }

            if (3 * i <= bound) {
                if (map.containsKey(3 * i)) {
                    if (map.get(i) + B < map.get(3 * i)) {
                        map.put(3 * i, Math.min(map.get(i) + B, map.get(3 * i)));
                    }
                } else {
                    map.put(3 * i, map.get(i) + B);
                }
            }

            if (5 * i <= bound) {
                if (map.containsKey(5 * i)) {
                    if (map.get(i) + C < map.get(5 * i)) {
                        map.put(5 * i, Math.min(map.get(i) + C, map.get(5 * i)));
                    }
                } else {
                    map.put(5 * i, map.get(i) + C);
                }
            }


            if (i + 1 <= bound) {
                if (map.containsKey(i + 1)) {
                    if (map.get(i) + D < map.get(i + 1)) {
                        map.put(i + 1, Math.min(map.get(i) + D, map.get(i + 1)));
                    }
                } else {
                    map.put(i + 1, map.get(i) + D);
                }
            }

            if (i - 1 <= bound && i - 1 >= 0) {
                if (map.containsKey(i - 1)) {
                    if (map.get(i) + D < map.get(i - 1)) {
                        map.put(i - 1, Math.min(map.get(i) + D, map.get(i - 1)));
                    }
                } else {
                    map.put(i - 1, map.get(i) + D);
                }
            }
        }
        return map.get(N);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = scanner.nextInt();
        for (int t = 0; t < T; t++) {
            long N = scanner.nextLong();
            int A = scanner.nextInt();
            int B = scanner.nextInt();
            int C = scanner.nextInt();
            int D = scanner.nextInt();
            Solution solution = new Solution();
            System.out.println(solution.convert(N, A, B, C, D));
        }
    }

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.lang.reflect.Array;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

	static long A, B, C, D;

	static int MAX = 100000000;
	static long[] memo = new long[MAX];

	static long calc(long val, int number) {
		if (val < MAX && memo[(int)val] != -1) return memo[(int)val];
		if (val == 0) return memo[0] = 0;
		boolean two = false, three = false, five = false;
		if (val >= MAX) {
			if (number == 2) two = true;
			else if (number == 3) three = true;
			else five = true;
		} else {
			two = three = five = true;
		}
		long ret = Long.MAX_VALUE;
		if (Long.MAX_VALUE / val > D) {
			ret = Math.min(ret, D * val);
		}
		for (long i = Math.max(0, val - 1); i <= val + 1; i++) {
			if (two && i % 2 == 0 && i / 2 < val) {
				ret = Math.min(ret, D * Math.abs(i - val) + A + calc(i / 2, number));
			}
			if (three && i % 3 == 0) {
				ret = Math.min(ret, D * Math.abs(i - val) + B + calc(i / 3, number));
			}
		}
		for (long i = Math.max(0, val - 2); i <= val + 2; i++) {
			if (five && i % 5 == 0) {
				ret = Math.min(ret, D * Math.abs(i - val) + C + calc(i / 5, number));
			}
		}
		if (val < MAX) {
			memo[(int)val] = ret;
		}
		return ret;
	}

	public static void main(String[] args) throws IOException {
		MyScanner sc = new MyScanner();
		PrintWriter out = new PrintWriter(System.out);
		int T = sc.nextInt();
		for (int caze = 0; caze < T; caze++) {
			Arrays.fill(memo, -1);
			long N = sc.nextLong();
			A = sc.nextLong();
			B = sc.nextLong();
			C = sc.nextLong();
			D = sc.nextLong();

			long min = Math.min(calc(N, 2), calc(N, 3));
			min = Math.min(min, calc(N, 5));
			out.println(min);
		}

		out.flush();
	}

	static class MyScanner {
		private BufferedReader br;
		private StringTokenizer tokenizer;

		public MyScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}
	}
}

