class MyMap{
    HashMap<Long,Long> map=new HashMap<>();
    public boolean put(long num,long cost){
        boolean ret=false;
        if(num>=0) {
            if (!map.containsKey(num)) {
                map.put(num, cost);
                ret = true;
            } else {
                if (map.get(num) > cost) {
                    map.put(num, cost);
                    ret = true;
                }
            }
        }
        return ret;
    }
    public long out(){
        if (map.containsKey(0L)){
            return map.get(0L);
        }else {
            return 0;
        }
    }
}

class NextNums{
    HashMap<Long,Long> map=new HashMap<>();
    void put(long num,long cost){
        if (!map.containsKey(num)){
            map.put(num,cost);
        }else{
            if(map.get(num)>cost){
                map.put(num,cost);
            }
        }
    }
    boolean isEmpty(){
        return map.isEmpty();
    }
}

