	static long dfs(long x) {
		if(x == 0) return 0;
		if(x == 1) return d;
		if(map.containsKey(x)) return map.get(x);
		long min = linf;
		for(int i=0;i<3;i++) {
			long v = k[i];
			long low = x / v * v;
			long high = (x + v - 1) / v * v;
			long lowCost = (x-low) * d + dfs(low / v) + min(a[i], low <= 2000000000?low/v * (v-1) * d : linf);
			long highCost = (high-x) * d + dfs(high / v) + min(a[i], high <= 2000000000?high / v * (v - 1) * d : linf);
			min = min(min, lowCost, highCost);
		}
		map.put(x, min);
		return min;
	}

