        	sc[3] = scan.nextInt();
        	sc[4] = scan.nextInt();

        	sum = sum++;
        	piece = sc[4];

        	if(sc[0] > sum * 5){
            	sum = sum * 5;
            	piece = piece + sc[3];
        	}
        	else if(sc[0] > sum * 3){
            	sum = sum * 3;
            	piece = piece + sc[2];
        	}
        	else if(sc[0] > sum * 2){
            	sum = sum * 2;
            	piece = piece + sc[1];
        	}
