public class Main implements Runnable{

	@SuppressWarnings("static-method")
	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * AtCoder Grand Contest 044 A問題
		 * 考察メモ
		 * 基本的に、2倍や3倍や5倍を優先すべき
		 * ある値を2倍や3倍や5倍していくことで、誤差どの範囲に収められるか考えられる
		 * 2倍、3倍、5倍を使う回数を決め打った時、Dが何回要るかって分かるかな？
		 * これは2進数、3進数、5進数を考えれば行けそう
		 * まず、簡単のために2倍だけ考える
		 * するとΣ[i=0, x] A_i * 2^i = Nとして、コスト合計はAx+DΣA_i
		 * つまりNを2進数表記した時の答え(ただしA_xだけ上位桁全部)
		 * 同様に2進数と3進数を組み合わせる時は6進数表記での答え
		 * ここで、2進数と3進数を偏らせた方が得なパターンがあるか考える
		 * 12は(0+1)*2*2*3が最適だと嬉しいだけど……
		 * 14は(0+1)*2*2*3+(0+1)*2が最適、これはつまり1→2→6→7→14が嬉しいパターンがありそう
		 * えー、どう表せばいいんだ？
		 * dp[i][j]: iを表すために必要なコインの最小数
		 * これでDijkstraしてみる？枝刈りはできるけど
		 *
		 * ……逆から考えれば良いのか
		 * 例えば最初にNを9枚引いて、次に5で割るような操作はありえない
		 * だってNを4枚引いて5で割って1枚引く方が必ず得
		 * 従って、各値について高々±4して約数で割って、ってやると答えが出る
		 *
		 */
		int T = io.nextInt();
		while(T --> 0) {
			long N = io.nextLong();
			int A = io.nextInt(), B = io.nextInt(), C = io.nextInt(), D = io.nextInt();
			PriorityQueue<Pair> pq = new PriorityQueue<>((l, r) -> Long.compare(l.cost, r.cost));
			pq.add(new Pair(N, 0));
			HashSet<Long> set = new HashSet<>();
			while(!pq.isEmpty()) {
				Pair tmp = pq.poll();
				if (!set.add(tmp.num)) continue; // BFS順みたいなもの
				//io.debugln(tmp);
				if (tmp.num == 0) { // 最初に来れたものが勿論最小
					io.println(tmp.cost);
					break;
				}
				if (tmp.num <= 2_000_000_001L) pq.add(new Pair(0, tmp.cost + tmp.num * D)); // 全部D
				for (long i = Math.max(0, tmp.num - 4);i < tmp.num + 5;++ i) { // もし全部Dを使わないなら、早めに割るのが得
					long cost = tmp.cost + Math.abs(tmp.num - i) * D;
					if (i % 2 == 0) pq.add(new Pair(i / 2, cost + A));
					if (i % 3 == 0) pq.add(new Pair(i / 3, cost + B));
					if (i % 5 == 0) pq.add(new Pair(i / 5, cost + C));
				}
			}
		}

	}

	class Pair {
		long num, cost;
		Pair(long n, long c) {
			num = n;
			cost = c;
		}
		@Override
		public String toString() {
			return "{" + num + "," + cost + "}";
		}
	}

