/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        A_PayToWin solver = new A_PayToWin();
        solver.solve(1, in, out);
        out.close();
    }

    static class A_PayToWin {
        Map<Long, Long> cache = new HashMap<>();

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            final int[] muls = {2, 3, 5};

            int numTests = in.nextInt();
            for (int test = 0; test < numTests; test++) {
                long n = in.nextLong();
                Op[] ops = new Op[3];
                for (int i = 0; i < 3; i++) {
                    ops[i] = new Op(muls[i], in.nextInt());
                }
                long u = in.nextInt();
                cache.clear();
                out.println(calc(n, u, ops));
            }
        }

        private long calc(long n, long u, Op[] ops) {
            if (n == 0) {
                return 0;
            }
            if (cache.containsKey(n)) {
                return cache.get(n);
            }
            long res = Long.MAX_VALUE;
            if (res / n > u) {
                res = n * u;
            }
            for (Op op : ops) {
                long down = n % op.mul;
                long up = op.mul - down;
                if ((n - down) / op.mul < n) {
                    res = Math.min(res, down * u + op.cost + calc((n - down) / op.mul, u, ops));
                }
                if ((n + up) / op.mul < n) {
                    res = Math.min(res, up * u + op.cost + calc((n + up) / op.mul, u, ops));
                }
            }
            cache.put(n, res);
            return res;
        }

        class Op {
            int mul;
            long cost;

            public Op(int mul, int cost) {
                this.mul = mul;
                this.cost = cost;
            }

        }

    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }
}

import java.util.*;

public class Main {
    Scanner in = new Scanner(System.in);

    void handle(long[] curr, long m, long cost, long d, PriorityQueue<long[]> q, Map<Long, Long> visited) {
        long c = curr[0] + cost + d * (curr[1] % m);
        if (!visited.containsKey(curr[1]/m) || visited.get(curr[1]/m) > c) {
            q.add(new long[]{c, curr[1]/m});
            visited.put(curr[1]/m, c);
        }

        c = curr[0] + cost + d * (m-curr[1] % m);
        if (!visited.containsKey(curr[1] / m + 1) || visited.get(curr[1] / m + 1) > c) {
            q.add(new long[]{c, curr[1] / m + 1});
            visited.put(curr[1] / m + 1, c);
        }
    }

    long solve() {
        long n = in.nextLong(), a = in.nextLong(), b = in.nextLong(), c = in.nextLong(), d = in.nextLong();
        PriorityQueue<long[]> q = new PriorityQueue<>(Comparator.comparingLong(x -> x[0]));
        q.add(new long[]{0, n});
        long ret = -1;
        Map<Long, Long> visited = new HashMap<>();
        while (!q.isEmpty()) {
            long[] curr = q.poll();
            if (curr[1] == 0) {
                ret = curr[0];
                break;
            }

            handle(curr, 2, a, d, q, visited);
            handle(curr, 3, b, d, q, visited);
            handle(curr, 5, c, d, q, visited);

            if (curr[1] == 1) {
                if (!visited.containsKey(0) || visited.get(0) < curr[0] + d) {
                    visited.put(0L, curr[0] + d);
                    q.add(new long[]{curr[0] + d, 0});
                }
            }
        }

        return Math.min(ret, d * n);
    }

    void run() {
        int T = in.nextInt();
        while (T-- > 0) {
            System.out.println(solve());
        }
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

