import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        for(int i=0; i<t; i++) {
            solve(sc);
        }
    }
    static void solve(Scanner sc) {
        long n = sc.nextLong();
        long a = sc.nextInt();
        long b = sc.nextInt();
        long c = sc.nextInt();
        long d = sc.nextInt();

        Set<Long> visited = new HashSet<>();
        PriorityQueue<Node> q = new PriorityQueue<>();
        q.offer(new Node(n, 0));
        long md = Long.MAX_VALUE / d;
        while(!q.isEmpty()) {
            Node node = q.poll();
            long num = node.n;
            if(visited.contains(num)) {
                continue;
            }
            visited.add(num);
            if(node.n == 1) {
                System.out.println(node.d + d);
                return;
            }
            if(num%2 == 0) {
                if(!visited.contains(num/2)) {
                    q.offer(new Node(num/2, node.d + Math.min(a, d * Math.min(md,num/2))));
                }
            } else {
                if(!visited.contains((num-1)/2)) {
                    q.offer(new Node((num-1)/2, node.d + d + Math.min(a, d *  Math.min(md,(num-1)/2))));
                }
                if(!visited.contains((num+1)/2)) {
                    q.offer(new Node((num+1)/2, node.d + Math.min(a + d, d * Math.min(md, (num - (num-1)/2)))));
                }
            }
            if(num%3 == 0) {
                if(!visited.contains(num/3)) {
                    q.offer(new Node(num/3, node.d + Math.min(b, d * Math.min(md, num/3 * 2))));
                }
            } else {
                int r = (int)(num % 3);
                int p = 3 - r;
                if(!visited.contains((num-r)/3)) {
                    q.offer(new Node((num-r)/3, node.d + Math.min(d * r + b, Math.min(md, (num-(num-r)/3)) * d)));
                }
                if(!visited.contains((num+p)/3)) {
                    q.offer(new Node((num+p)/3, node.d + Math.min(d * p + b, Math.min(md, (num-(num+p)/3)) * d)));
                }
            }
            if(num%5 == 0) {
                if(!visited.contains(num/5)) {
                    q.offer(new Node(num/5, node.d + Math.min(c, d * Math.min(md, (num - num/5)))));
                }
            } else {
                int r = (int)(num % 5);
                int p = 5 - r;
                if(!visited.contains((num-r)/5)) {
                    q.offer(new Node((num-r)/5, node.d + Math.min(d * r + c, Math.min(md, (num-(num-r)/5)) * d)));
                }
                if(!visited.contains((num+p)/5)) {
                    q.offer(new Node((num+p)/5, node.d + Math.min(d * p + c, Math.min(md, (num-(num+p)/5)) * d)));
                }
            }
        }

    }

    static class Node implements Comparable<Node>{
        long n;
        long d;
        Node(long n, long d) {
            this.n = n;
            this.d = d;
        }
        @Override
        public int compareTo(Node node) {
            return Long.compare(d, node.d);
        }
    }

}

import java.util.*;

public class Main {

    private static int A;
    private static int B;
    private static int C;
    private static int D;

    private static long min;
    private static Map<Long,Long> memo;

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        StringBuilder ans = new StringBuilder();
        int T = sc.nextInt();
        while (T-- > 0) {
            long N = sc.nextLong();
            A = sc.nextInt();
            B = sc.nextInt();
            C = sc.nextInt();
            D = sc.nextInt();

            min = Long.MAX_VALUE;
            memo = new HashMap<>();
            dfs(N, 0);
            ans.append(min).append('\n');
        }

        System.out.print(ans);
    }


    private static void dfs(long n, long cost) {

        Long cached = memo.get(n);
        if (cached != null && cost >= cached) {
            return;
        }

        memo.put(n,cost);

        if (n == 0) {
            min = Math.min(min,cost);
            return;
        }

        if (n == 1) {
            min = Math.min(min,cost+D);
            return;
        }

        int[] div = new int[] {2,3,5};
        int[] divCost = new int[] {A,B,C};

        for (int i = 0; i < 3; i ++) {
            if (n%div[i] == 0) {
                divDfs(n, n/div[i], divCost[i], cost);
            } else {
                divDfs(n-n%div[i], n/div[i], divCost[i], cost+D*(n%div[i]));
                divDfs(n+(div[i]-n%div[i]), (n+div[i])/div[i], divCost[i], cost+D*(div[i]-n%div[i]));
            }
        }
    }

    private static void divDfs(long src, long dst, int divCost, long cost) {
        long diffCost;
        if (src-dst >= 1_000_000_000) {
            diffCost = divCost;
        } else {
            diffCost = Math.min((src-dst)*D,divCost);
        }
        dfs(dst, cost+diffCost);
    }
}

