  public void a(){
    if (x*2 <= n){
		calcA();
     } else if (x*2-n < n-x){
         calcA();
         for (int i = 0 ; i < x-n ; i++ ){
            calcD('-');
         }
     } else {
         for (int i = 0 ; i < n-x ; i++ ){
            calcD('+');
         }
     }
  }
  public void b(){
    if (x*3 < n) {
          calcB();
    } else {
      if (n-x < Math.abs(n-x*2) && n-x < x*3-n){
          for (int i = 0 ; i < n-x ; i++){
            calcD('+');
          }
      } else if (x*3-n < Math.abs(n-x*2)) {
           calcB();
        for (int i = 0 ; i < x-n ; i++){
           calcD('-');
        }
      } else {
        a();
      }//if文
    }
  }
  public void c(){
