          calcC();
    } else {
      if (n-x < Math.abs(n-x*3) && n-x < Math.abs(n-x*2) && n-x < x*5-n){
          for (int i = 0 ; i < n-x ; i++){
            calcD('+');
          }
         } else if (x*5-n < Math.abs(n-x*3) && x*5-n < Math.abs(n-x*2)) {
           calcB();
        for (int i = 0 ; i < x-n ; i++){
           calcD('-');
        }
      } else if (Math.abs(n-x*3) < Math.abs(n-x*2)) {
        b();
      } else {
        a();
      }
    }
