import java.util.function.LongUnaryOperator;

public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long mod = 1000000007;
    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final int[] da = {-1, 0, 1, 0, -1, 1, 1, -1, -1};

    long a, b, c, d;
    void solve() {
        int t = in.nextInt();
        for (int i = 0; i < t; i++) {
            long n = in.nextLong();
            a = in.nextLong();
            b = in.nextLong();
            c = in.nextLong();
            d = in.nextLong();
            memo = new HashMap<>();
            out.println(f(n));
        }
    }

    Map<Long, Long> memo;

    long f(long n) {
        if (memo.containsKey(n)) {
            return memo.get(n);
        }
        long res = inf;
        if (n > n / 2) {
            res = Math.min(res, f(n / 2) + n % 2 * d + a);
        }
        if (n > n / 3) {
            res = Math.min(res, f(n / 3) + n % 3 * d + b);
        }
        if (n > n / 5) {
            res = Math.min(res, f(n / 5) + n % 5 * d + c);
        }
        if (n != (n + 1) / 2) {
            res = Math.min(res, f((n + 1) / 2) + (2 - n % 2) * d + a);
        }
        if (n != (n + 2) / 3) {
            res = Math.min(res, f((n + 2) / 3) + (3 - n % 3) * d + b);
        }
        if (n != (n + 4) / 5) {
            res = Math.min(res, f((n + 4) / 5) + (5 - n % 5) * d + c);
        }
        if (n == 0 || res / n >= d) {
            res = Math.min(res, n * d);
        }
        memo.put(n, res);
        return res;
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

