public class Main {
    public static void main(String[] args){
        try{
            long[] list = {0,0,0};
            long[] arg = {0,0,0,0};
            long n = 0,bigger=0,poss1=0,poss2=0;
            BufferedReader br1 = new BufferedReader(new InputStreamReader(System.in));
            String temp = br1.readLine();
            long t = Integer.parseInt(temp);
            for(int i=0;i<t;i++){

                String[] temp1 = br1.readLine().split(" ");
                n = Integer.parseInt(temp1[0]);
                arg[0] = Integer.parseInt(temp1[1]);
                arg[1] = Integer.parseInt(temp1[2]);
                arg[2] = Integer.parseInt(temp1[3]);
                arg[3] = Integer.parseInt(temp1[4]);
            }
            if(n%2==0 || n%3==0 || n%5==0){
                System.out.println(core(n,list,arg));
            }
            else{
                bigger = n;
                while( bigger%2!=0 &&  bigger%3!=0 &&  bigger%5!=0)
                bigger+=1;
                poss1 = core(n,list,arg);
                bigger = n;
                while( bigger%2!=0 &&  bigger%3!=0 &&  bigger%5!=0)
                bigger-=1;
                poss2 = core(n, list, arg);
                System.out.println(Math.min(poss1,poss2));

            }
        }catch (IOException e){
            e.printStackTrace();
        }

    }

    public static long[] cal(long n,long[] list){
        list[0] = 0;
        list[1] = 0;
        list[2] = 0;
        while(n%2!=0){
            list[0]++;
            n/=2;
        }
        while(n%3!=0){
            list[1]++;
            n/=3;
        }
        while(n%5!=0){
            list[2]++;
            n/=5;
        }
        return list;
    }

    public  static long core(long n,long[] list,long[] arg){
        cal(n,list);
        long result1 = list[0] * arg[0] + list[1] * arg[1] + list[2] * arg[2] + arg[3];
        if(result1/n>arg[3]){
            return n*arg[3];
        }
        else{
            return result1;
        }
    }
}

import java.util.HashMap;
import java.util.Scanner;

class Solution {

    long convert(long N, int A, int B, int C, int D) {
        long i = 1;
        long val = D;
        HashMap<Long, Long> map = new HashMap<>();
        map.put(i, (long) D);
        long bound = N + 5;
        for (i = 1; i <= bound; i++) {
            if (2 * i <= bound) {
                if (map.containsKey(2 * i)) {
                    if (map.get(i) + A < map.get(2 * i)) {
                        map.put(2 * i, Math.min(map.get(i) + A, map.get(2 * i)));
                    }
                } else {
                    map.put(2 * i, map.get(i) + A);
                }
            }

            if (3 * i <= bound) {
                if (map.containsKey(3 * i)) {
                    if (map.get(i) + B < map.get(3 * i)) {
                        map.put(3 * i, Math.min(map.get(i) + B, map.get(3 * i)));
                    }
                } else {
                    map.put(3 * i, map.get(i) + B);
                }
            }

            if (5 * i <= bound) {
                if (map.containsKey(5 * i)) {
                    if (map.get(i) + C < map.get(5 * i)) {
                        map.put(5 * i, Math.min(map.get(i) + C, map.get(5 * i)));
                    }
                } else {
                    map.put(5 * i, map.get(i) + C);
                }
            }


            if (i + 1 <= bound) {
                if (map.containsKey(i + 1)) {
                    if (map.get(i) + D < map.get(i + 1)) {
                        map.put(i + 1, Math.min(map.get(i) + D, map.get(i + 1)));
                    }
                } else {
                    map.put(i + 1, map.get(i) + D);
                }
            }

            if (i - 1 <= bound && i - 1 >= 0) {
                if (map.containsKey(i - 1)) {
                    if (map.get(i) + D < map.get(i - 1)) {
                        map.put(i - 1, Math.min(map.get(i) + D, map.get(i - 1)));
                    }
                } else {
                    map.put(i - 1, map.get(i) + D);
                }
            }
        }
        return map.get(N);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = scanner.nextInt();
        for (int t = 0; t < T; t++) {
            long N = scanner.nextLong();
            int A = scanner.nextInt();
            int B = scanner.nextInt();
            int C = scanner.nextInt();
            int D = scanner.nextInt();
            Solution solution = new Solution();
            System.out.println(solution.convert(N, A, B, C, D));
        }
    }

}

