public class Main {

    static class Task {

        private long a;
        private long b;
        private long c;
        private long d;
        private Map<Long, Long> memoMap;
        private static final long MAX = (long) 1e18;

        private long dp(long n) {
            if (n == 1) {
                return 0;
            }

//            System.out.println(n);

            if (memoMap.containsKey(n)) {
                return memoMap.get(n);
            }

            long minRes = Long.MAX_VALUE;
            long left = Math.max(1, n - 5);
            long right = n + 1;
            for (long i = left; i <= right; i++) {
                long tmpMinRes = Long.MAX_VALUE;
                if (i == 1) {
                    tmpMinRes =  Math.abs(i - n) * d;
                    minRes = Math.min(minRes, tmpMinRes);
                    continue;
                }

                if (i % 2 == 0) {
                    long res = dp(i / 2);
                    if (d / 2 > MAX / i) {
                        res += a;
                    } else {
                        res += Math.min(d * (i / 2), a);
                    }
                    tmpMinRes = Math.min(tmpMinRes, res);
                }

                if (i % 3 == 0) {
                    long res = dp(i / 3);
                    if (d * 2 / 3 > MAX / i) {
                        res += b;
                    } else {
                        res += Math.min(d * (i / 3) * 2, b);
                    }
                    tmpMinRes = Math.min(tmpMinRes, res);
                }

                if (i % 5 == 0) {
                    long res = dp(i / 5);
                    if (d * 4 / 5 > MAX / i) {
                        res += c;
                    } else {
                        res += Math.min(d * (i / 5) * 4, c);
                    }

                    tmpMinRes = Math.min(tmpMinRes, res);
                }

                if (tmpMinRes != Long.MAX_VALUE) {
                    long diff = Math.abs(i - n);
                    long curMinRes = diff * d;
                    if (n % 2 == 0 && n / 2 == diff) {
                        curMinRes = Math.min(curMinRes, a);
                    }

                    if (n % 3 == 0 && n * 2 / 3 == diff ) {
                        curMinRes = Math.min(curMinRes, b);
                    }

                    if (n % 5 == 0 && n * 4 / 5 == diff) {
                        curMinRes = Math.min(curMinRes, c);
                    }

                    tmpMinRes += curMinRes;
                    minRes = Math.min(minRes, tmpMinRes);
                }

            }

            memoMap.put(n, minRes);
            return minRes;
        }

