    long d;
    long[] cost = new long[3];
    int[] divs = new int[]{2, 3, 5};

    Map<Long, Long> cache;

    long get(long n) {
        if (cache.containsKey(n)) {
            return cache.get(n);
        }
        if (n == 1) {
            return d;
        }
        long res = Long.MAX_VALUE;
        for (int it = 0; it < divs.length; it++) {
            int div = divs[it];
            for (long next = n - div + 1; next < n + div; next++) {
                if (next > 1 && next % div == 0) {
                    long curRes = Math.abs(next - n) * d + get(next / div) + cost[it];
                    res = Math.min(res, curRes);
                }
            }
        }
        cache.put(n, res);
        return res;
    }

    void solve() {
        int tc = in.nextInt();
        for (int t = 0; t < tc; t++) {
            long n = in.nextLong();
            cost[0] = in.nextLong();
            cost[1] = in.nextLong();
            cost[2] = in.nextLong();
            d = in.nextLong();
            cache = new HashMap<>();
            out.println(get(n));
        }
    }

