public class Main {

    static class Task {

        private long a;
        private long b;
        private long c;
        private long d;
        private Map<Long, Long> memoMap;

        private long dp(long n) {
            if (n == 1) {
                return 0;
            }

//            System.out.println(n);

            if (memoMap.containsKey(n)) {
                return memoMap.get(n);
            }

            long minRes = Long.MAX_VALUE;
            long left = Math.max(1, n - 5);
            long right = n + 1;
            for (long i = left; i <= right; i++) {
                long tmpMinRes = Long.MAX_VALUE;
                if (i == 1) {
                    tmpMinRes =  Math.abs(i - n) * d;
                    minRes = Math.min(minRes, tmpMinRes);
                    continue;
                }

                if (i % 2 == 0) {
                    long res = dp(i / 2) + Math.min(d * i / 2, a);
                    if (res >= 0) {
                        tmpMinRes = Math.min(tmpMinRes, res);
                    }
                }

                if (i % 3 == 0) {
                    long res = dp(i / 3) + Math.min(d * i * 2 / 3, b);
                    if (res >= 0) {
                        tmpMinRes = Math.min(tmpMinRes, res);
                    }
                }

                if (i % 5 == 0) {
                    long res = dp(i / 5) + Math.min(d * i * 4 / 5, c);
                    if (res >= 0) {
                        tmpMinRes = Math.min(tmpMinRes, res);
                    }
                }

                if (tmpMinRes != Long.MAX_VALUE) {
                    tmpMinRes += Math.abs(i - n) * d;
                    minRes = Math.min(minRes, tmpMinRes);
                }

            }

            memoMap.put(n, minRes);
            return minRes;
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int t = in.nextInt();
            while ((t--) > 0) {
                long n = in.nextLong();
                a = in.nextLong();
                b = in.nextLong();
                c = in.nextLong();
                d = in.nextLong();

                memoMap = new HashMap<>();
                long ans = dp(n) + d;
                out.println(ans);
            }
        }
    }

