public class Main {

    static class Task {

        private long a;
        private long b;
        private long c;
        private long d;
        private Map<Long, Long> memoMap;
        private static final long MAX = (long) 1e18;

        private long dp(long n) {
            if (n == 1) {
                return 0;
            }

//            System.out.println(n);

            if (memoMap.containsKey(n)) {
                return memoMap.get(n);
            }

            long minRes = Long.MAX_VALUE;
            long left = Math.max(1, n - 5);
            long right = n + 1;
            for (long i = left; i <= right; i++) {
                long tmpMinRes = Long.MAX_VALUE;
                if (i == 1) {
                    tmpMinRes =  Math.abs(i - n) * d;
                    minRes = Math.min(minRes, tmpMinRes);
                    continue;
                }

                if (i % 2 == 0) {
                    long res = dp(i / 2);
                    if (d / 2 > MAX / i) {
                        res += a;
                    } else {
                        res += Math.min(d * (i / 2), a);
                    }
                    tmpMinRes = Math.min(tmpMinRes, res);
                }

                if (i % 3 == 0) {
                    long res = dp(i / 3);
                    if (d * 2 / 3 > MAX / i) {
                        res += b;
                    } else {
                        res += Math.min(d * (i / 3) * 2, b);
                    }
                    tmpMinRes = Math.min(tmpMinRes, res);
                }

                if (i % 5 == 0) {
                    long res = dp(i / 5);
                    if (d * 4 / 5 > MAX / i) {
                        res += c;
                    } else {
                        res += Math.min(d * (i / 5) * 4, c);
                    }

                    tmpMinRes = Math.min(tmpMinRes, res);
                }

                if (tmpMinRes != Long.MAX_VALUE) {
                    tmpMinRes += Math.abs(i - n) * d;
                    minRes = Math.min(minRes, tmpMinRes);
                }

            }

            memoMap.put(n, minRes);
            return minRes;
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            Scanner scanner = new Scanner(System.in);
            int t = scanner.nextInt();
//            System.out.println(1000000000000000000L * 909090);
//            System.out.println(1000000000000000000L * 66666);
//            System.out.println(1000000000000000000L * 77777);
//            System.out.println(Long.MAX_VALUE);
            while ((t--) > 0) {
                long n = scanner.nextLong();
                a = scanner.nextLong();
                b = scanner.nextLong();
                c = scanner.nextLong();
                d = scanner.nextLong();

                memoMap = new HashMap<>();
                long ans = dp(n) + d;
                out.println(ans);
            }
        }
    }

