import java.util.HashMap;
import java.util.Scanner;

public class Main {

    long convert(long N, int A, int B, int C, int D) {
        long i = 1;
        HashMap<Long, Long> map = new HashMap<>();
        map.put(i, (long) D);
        long bound = N + 5;
        for (i = 1; i <= bound; i++) {
            if (2 * i <= bound) {
                if (map.containsKey(2 * i)) {
                    if (map.get(i) + A < map.get(2 * i)) {
                        map.put(2 * i, Math.min(map.get(i) + A, map.get(2 * i)));
                    }
                } else {
                    map.put(2 * i, map.get(i) + A);
                }
            }

            if (3 * i <= bound) {
                if (map.containsKey(3 * i)) {
                    if (map.get(i) + B < map.get(3 * i)) {
                        map.put(3 * i, Math.min(map.get(i) + B, map.get(3 * i)));
                    }
                } else {
                    map.put(3 * i, map.get(i) + B);
                }
            }

            if (5 * i <= bound) {
                if (map.containsKey(5 * i)) {
                    if (map.get(i) + C < map.get(5 * i)) {
                        map.put(5 * i, Math.min(map.get(i) + C, map.get(5 * i)));
                    }
                } else {
                    map.put(5 * i, map.get(i) + C);
                }
            }


            if (i + 1 <= bound) {
                if (map.containsKey(i + 1)) {
                    if (map.get(i) + D < map.get(i + 1)) {
                        map.put(i + 1, Math.min(map.get(i) + D, map.get(i + 1)));
                    }
                } else {
                    map.put(i + 1, map.get(i) + D);
                }
            }

            if (i - 1 <= bound && i - 1 >= 0) {
                if (map.containsKey(i - 1)) {
                    if (map.get(i) + D < map.get(i - 1)) {
                        map.put(i - 1, Math.min(map.get(i) + D, map.get(i - 1)));
                    }
                } else {
                    map.put(i - 1, map.get(i) + D);
                }
            }
        }
        return map.get(N);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = scanner.nextInt();
        for (int t = 0; t < T; t++) {
            long N = scanner.nextLong();
            int A = scanner.nextInt();
            int B = scanner.nextInt();
            int C = scanner.nextInt();
            int D = scanner.nextInt();
            Main main = new Main();
            System.out.println(main.convert(N, A, B, C, D));
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
	static long rec(long N , long A , long B , long C , long D , Map<Long, Long> memo){
		if(memo.containsKey(N)){
			return memo.get(N);
		}
		if(N == 0){
			return 0;
		}
		if(N == 1){
			return D;
		}
		long r5 = N / 5;
		long diff = N - r5 * 5;
		long ret = rec(r5 , A , B , C , D , memo) + D * diff + C;
		if(diff != 0){
			diff = (r5 + 1) * 5 - N;
			ret = Math.min(rec(r5 + 1 , A , B , C , D , memo) + D * diff + C , ret);
		}
		long r3 = N / 3;
		diff = N - r3 * 3;
		ret = Math.min(ret, rec(r3 , A , B , C , D , memo) + D * diff + B);
		if(diff != 0){
			diff = (r3 + 1) * 3 - N;
			ret = Math.min(ret, rec(r3 + 1 , A , B , C , D , memo) + D * diff + B);
		}
		long r2 = N / 2;
		diff = N - r2 * 2;
		ret = Math.min(ret, rec(r2 , A , B , C , D , memo) + D * diff + A);
		if(diff != 0){
			diff = (r2 + 1) * 2 - N;
			ret = Math.min(ret, rec(r2 + 1 , A , B , C , D , memo) + D * diff + A);
		}
		if(N < ret / D){
			ret = Math.min(ret, N * D);			
		}
		memo.put(N, ret);
		return ret;
	}
	static long solve(long N , long A , long B , long C , long D){
		Map<Long, Long> memo = new HashMap<Long, Long>();		
		return rec(N , A , B , C , D , memo);
	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int T = sc.nextInt();
		for(int cn = 1 ; cn <= T ; ++cn){
			long N = sc.nextLong();
			long A = sc.nextLong();
			long B = sc.nextLong();
			long C = sc.nextLong();
			long D = sc.nextLong();
			long ret = solve(N , A , B , C , D);
			System.out.println(ret);
		}
	}
}

