public final class Main {

    public static void main(String[] args) {
        final Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        final int t = in.nextInt();
        for (int i = 0; i < t; i++) {
            final long n = in.nextLong();
            final int a = in.nextInt();
            final int b = in.nextInt();
            final int c = in.nextInt();
            final int d = in.nextInt();
            in.nextLine();
            System.out.println(dfs(n, a, b, c, d));
        }
    }

    private static long dfs(long n, int a, int b, int c, int d) {
        final Set<Long> seen = new HashSet<>();
        final PriorityQueue<long[]> q = new PriorityQueue<>(Comparator.comparingLong(l -> l[1]));
        q.offer(new long[] { n, 0 });
        while (!q.isEmpty()) {
            final long[] curr = q.remove();
//            System.out.println(Arrays.toString(curr));
            if (curr[0] == 0) {
                return curr[1];
            }
            if (!seen.add(curr[0])) {
                continue;
            }
            q.offer(new long[] { curr[0] / 5, curr[1] + c + (d * (curr[0] % 5)) });
            q.offer(new long[] { (curr[0] / 5) + 1, curr[1] + c + (d * (5 - (curr[0] % 5))) });
            q.offer(new long[] { curr[0] / 3, curr[1] + b + (d * (curr[0] % 3)) });
            q.offer(new long[] { (curr[0] / 3) + 1, curr[1] + b + (d * (3 - (curr[0] % 3))) });
            q.offer(new long[] { curr[0] / 2, curr[1] + a + (d * (curr[0] % 2)) });
            q.offer(new long[] { (curr[0] / 2) + 1, curr[1] + a + (d * (2 - (curr[0] % 2))) });
            if (curr[0] <= Math.floorDiv(Long.MAX_VALUE, d) && curr[1] + curr[0] * d > 0) {
                q.offer(new long[] { 0, curr[1] + curr[0] * d });
            }
        }
        return -1;
    }
}

import java.util.*;

public class Main {
    static int m2;
    static int m3;
    static int m5;
    static int a1;
    static HashMap<Long, Long> map = new HashMap<>();
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		int t = sc.nextInt();
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < t; i++) {
		    long n = sc.nextLong();
		    m2 = sc.nextInt();
		    m3 = sc.nextInt();
		    m5 = sc.nextInt();
		    a1 = sc.nextInt();
		    map.clear();
		    map.put(0L, 0L);
		    map.put(1L, (long)a1);
		    sb.append(dfw(n)).append("\n");
		}
		System.out.print(sb);
	}

	static long dfw(long x) {
	    if (map.containsKey(x)) {
	        return map.get(x);
	    }
	    long min;
	    if (x <= Long.MAX_VALUE / a1) {
	        min = x * a1;
	    } else {
	        min = Long.MAX_VALUE;
	    }
	    if (x % 2 == 0) {
	        min = Math.min(min, dfw(x / 2) + m2);
	    } else {
	        min = Math.min(min, dfw((x + 1) / 2) + a1 + m2);
	        min = Math.min(min, dfw((x - 1) / 2) + a1 + m2);
	    }
	    if (x % 3 == 0) {
	        min = Math.min(min, dfw(x / 3) + m3);
	    } else {
	        long mod = x % 3;
	        if (x > 3) {
	            min = Math.min(min, dfw((x - mod) / 3) + a1 * mod + m3);
	        }
	        min = Math.min(min, dfw((x + (3 - mod)) / 3) + a1 * (3 - mod) + m3);
	    }
	    if (x % 5 == 0) {
	        min = Math.min(min, dfw(x / 5) + m5);
	    } else {
	        long mod = x % 5;
	        if (x > 5) {
	            min = Math.min(min, dfw((x - mod) / 5) + a1 * mod + m5);
	        }
	        min = Math.min(min, dfw((x + (5 - mod)) / 5) + a1 * (5 - mod) + m5);
	    }
	    map.put(x, min);
	    return min;
	}
}

