  private static long dfs(long n) {
    if(cache.containsKey(n))
      return cache.get(n);
    if(n == 0) return 0;
    if(n == 1) return d;

    long res = Long.MAX_VALUE;
    if (n < res/d) res = n * d;

    long l2 = (n/2)*2;
    long r2 = ((n+1)/2)*2;
    long l3 = (n/3)*3;
    long r3 = ((n+2)/3)*3;
    long l5 = (n/5)*5;
    long r5 = ((n+4)/5)*5;

    res = Math.min(res, a + (n - l2) * d + dfs(l2/2));
    res = Math.min(res, a + (r2 - n) * d + dfs(r2/2));
    res = Math.min(res, b + (n - l3) * d + dfs(l3/3));
    res = Math.min(res, b + (r3 - n) * d + dfs(r3/3));
    res = Math.min(res, c + (n - l5) * d + dfs(l5/5));
    res = Math.min(res, c + (r5 - n) * d + dfs(r5/5));
    cache.put(n, res);
    return res;
  }

