    public static void main (String[] args) throws Exception {

        String s = "5\n" +
                "11 1 2 4 8\n" +
                "11 1 2 2 8\n" +
                "32 10 8 5 4\n" +
                "29384293847243 454353412 332423423 934923490 1\n" +
