import java.util.*;

public class Main {

    private static long A;
    private static long B;
    private static long C;
    private static long D;

    private static long min;
    private static Map<Long,Long> memo;

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        StringBuilder ans = new StringBuilder();
        int T = sc.nextInt();
        while (T-- > 0) {
            long N = sc.nextLong();
            A = sc.nextInt();
            B = sc.nextInt();
            C = sc.nextInt();
            D = sc.nextInt();

            min = Long.MAX_VALUE;
            memo = new HashMap<>();
            dfs(N, 0);
            ans.append(min).append('\n');
        }

        System.out.print(ans);
    }


    private static void dfs(long n, long cost) {

        if (n == 1) {
            min = Math.min(min,cost+D);
            return;
        }

        Long cached = memo.get(n);
        if (cached != null && cost >= cached) {
            return;
        }

        memo.put(n,cost);

        dfs((n-(n%2))/2, cost+A+D*(n%2));
        dfs((n+(n%2))/2, cost+A+D*(n%2));
        dfs((n-(n%3))/3, cost+B+D*(n%3));
        dfs((n+3-(n%3))/3, cost+B+D*(3-(n%3)));
        dfs((n-(n%5))/5, cost+C+D*(n%5));
        dfs((n+5-(n%5))/5, cost+C+D*(5-(n%5)));
    }
}

import java.util.*;

public class Main {

    private static int A;
    private static int B;
    private static int C;
    private static int D;

    private static long min;
    private static Map<Long,Long> memo;

    private static int[] div = new int[] {2,3,5};
    private static int[] divCost;

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        StringBuilder ans = new StringBuilder();
        int T = sc.nextInt();
        while (T-- > 0) {
            long N = sc.nextLong();
            A = sc.nextInt();
            B = sc.nextInt();
            C = sc.nextInt();
            D = sc.nextInt();

            divCost  = new int[] {A,B,C};

            min = Long.MAX_VALUE;
            memo = new HashMap<>();
            dfs(N, 0);
            ans.append(min).append('\n');
        }

        System.out.print(ans);
    }


    private static void dfs(long n, long cost) {

        Long cached = memo.get(n);
        if (cached != null && cost >= cached) {
            return;
        }

        memo.put(n,cost);

        if (n == 0) {
            min = Math.min(min,cost);
            return;
        }

        if (n == 1) {
            min = Math.min(min,cost+D);
            return;
        }


        for (int i = 0; i < 3; i ++) {
            if (n < div[i]) {
                dfs(0, cost+n*D);
            } else if (n%div[i] == 0) {
                divDfs(n, n/div[i], divCost[i], cost);
            } else {
                Long ccc = memo.get(n-n%div[i]);
                if (ccc == null || cost+D*(n%div[i]) < ccc) {
                    memo.put(n-n%div[i],cost+D*(n%div[i]));
                    divDfs(n-n%div[i], n/div[i], divCost[i], cost+D*(n%div[i]));
                }
                Long ddd = memo.get(n+(div[i]-n%div[i]));
                if (ddd == null || cost+D*(div[i]-n%div[i]) < ddd) {
                    memo.put(n+(div[i]-n%div[i]),cost+D*(div[i]-n%div[i]));
                    divDfs(n+(div[i]-n%div[i]), (n+div[i])/div[i], divCost[i], cost+D*(div[i]-n%div[i]));
                }
            }
        }
    }

    private static void divDfs(long src, long dst, int divCost, long cost) {
        long diffCost;
        if (src-dst >= 1_000_000_000) {
            diffCost = divCost;
        } else {
            diffCost = Math.min((src-dst)*D,divCost);
        }
        dfs(dst, cost+diffCost);
    }
}

package AGC44;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		int T = Integer.parseInt(sc.next());

		long[][] ca = new long[T][5];
		long[] ans = new long[T];
		for(int i = 0;i < T;i++) {
			 ca[i][0] = Long.parseLong(sc.next());
			 ca[i][1] = Long.parseLong(sc.next());
			 ca[i][2] = Long.parseLong(sc.next());
			 ca[i][3] = Long.parseLong(sc.next());
			 ca[i][4] = Long.parseLong(sc.next());

			 ans[i] = calc(ca[i]);
		}

		for(long a : ans) {
			System.out.println(a);
		}
	}

	public static long calc(long[] a) {
			 long total = 0;
			 long zan = 0;

			 long[] bb = new long[5];

			 while(zan != a[0]) {
				 if(zan == 0) {
					 zan++;
					 total += a[4];
				 }

				 bb[0] = Math.abs(a[0]-(zan * 2));
				 bb[1] = Math.abs(a[0]-(zan * 3));
				 bb[2] = Math.abs(a[0]-(zan * 5));
				 bb[3] = Math.abs(a[0]-(++zan ));
				 bb[4] = Math.abs(a[0]-(--zan ));

				 long min =Long.MAX_VALUE;
				 int ii = 0;
				 for(int i = 0; i < bb.length;i++) {
					 if(min >= bb[i]) {
						 min = bb[i];
						ii = i;
					 }
				 }
				 switch(ii) {
				 case 0:
					 zan = zan * 2;
					 total += a[1];
					 break;
				 case 1:
					 zan = zan * 3;
					 total += a[2];
					 break;
				 case 2:
					 zan = zan * 5;
					 total += a[3];
					 break;
				 case 3:
					 zan++;
					 total += a[4];
					 break;
				 case 4:
					 zan--;
					 total += a[4];
					 break;
				 }

			 }
		return total;

	}

}

