	public class Program
	{
		static void Main()
		{
			var cin = new Scanner();
			int t = cin.Int();
			var sb = new StringBuilder();
			for (int i = 0; i < t; i++) {
				long n = cin.Long();
				long a = cin.Long();
				long b = cin.Long();
				long c = cin.Long();
				long d = cin.Long();

				var map = new HashMap<long, long>(x => long.MaxValue);
				map[n] = 0;
				var q = new PriorityQueue<PriorityPair<long, long>>(true);
				q.Enqueue(new PriorityPair<long, long>(0, n));
				while (q.Count > 0) {
					var cur = q.Dequeue();
					if (map[cur.Item] < cur.Priority || cur.Item < 0) {
						continue;
					}

					BigInteger temp = (BigInteger)cur.Item * d + cur.Priority;
					if (temp <= long.MaxValue) {
						map[0] = Math.Min(map[0], (long)temp);
					}

					void func(long m, long cost)
					{
						long div = cur.Item % m;
						long numB = (cur.Item - div) / m;
						long numU = (cur.Item + (m - div)) / m;
						long coinB = cur.Priority + div * d + cost;
						long coinU = cur.Priority + (m - div) * d + cost;
						if (map[numB] > coinB) {
							map[numB] = coinB;
							q.Enqueue(new PriorityPair<long, long>(coinB, numB));
						}

						if (map[numU] > coinU) {
							map[numU] = coinU;
							q.Enqueue(new PriorityPair<long, long>(coinU, numU));
						}
					}

					func(2, a);
					func(3, b);
					func(5, c);
				}

				long ans = map[0];
				sb.AppendLine(ans.ToString());
			}

			Console.Write(sb.ToString());
		}
	}

	public struct PriorityPair<T, U> : IComparable<PriorityPair<T, U>>
			where T : IComparable<T>
	{
		public T Priority { get; set; }
		public U Item { get; set; }

		public PriorityPair(T priority, U item)
		{
			Priority = priority;
			Item = item;
		}

		public int CompareTo(PriorityPair<T, U> target)
			=> Priority.CompareTo(target.Priority);

		public override string ToString()
			=> $"{Priority} {Item}";
	}

	public class PriorityQueue<T> where T : IComparable<T>
	{
		private readonly int reverseFactor_;
		private T[] heap_;

		public T Top => heap_[0];
		public int Count { get; private set; } = 0;

		public PriorityQueue(bool reverses = false)
			: this(1024, reverses) { }

		public PriorityQueue(
			int capacity,
			bool reverses = false)
		{
			heap_ = new T[capacity > 0 ? capacity : 1];
			reverseFactor_ = reverses ? -1 : 1;
		}

		public void Enqueue(T item)
		{
			if (heap_.Length == Count) {
				Extend(heap_.Length * 2);
			}

			heap_[Count] = item;
			++Count;

			int c = Count - 1;
			while (c > 0) {
				int p = (c - 1) >> 1;
				if (Compare(heap_[p], item) < 0) {
					heap_[c] = heap_[p];
					c = p;
				} else {
					break;
				}
			}

			heap_[c] = item;
		}

		public T Dequeue()
		{
			T ret = heap_[0];
			int n = Count - 1;

			var item = heap_[n];
			int p = 0;
			int c = (p << 1) + 1;
			while (c < n) {
				if (c != n - 1 && Compare(heap_[c + 1], heap_[c]) > 0) {
					++c;
				}

				if (Compare(item, heap_[c]) < 0) {
					heap_[p] = heap_[c];
					p = c;
					c = (p << 1) + 1;
				} else {
					break;
				}
			}

			heap_[p] = item;
			Count--;

			return ret;
		}

		public void Clear() => Count = 0;

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private int Compare(T x, T y)
			=> x.CompareTo(y) * reverseFactor_;

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private void Extend(int newSize)
		{
			var newHeap = new T[newSize];
			heap_.CopyTo(newHeap, 0);
			heap_ = newHeap;
		}
	}


	public class HashMap<TKey, TValue> : Dictionary<TKey, TValue>
