            for (var i = 0; i < t; i++)
            {
                var nabcd = Console.ReadLine().Trim().Split(' ').Select(long.Parse).ToArray();
                var n = nabcd[0];
                var a = nabcd[1];
                var b = nabcd[2];
                var c = nabcd[3];
                var d = nabcd[4];
                Console.WriteLine(Dfs(0, 0, n, a, b, c, d));
            }
        }

        static long Dfs(long coins, long current, long n, long a, long b, long c, long d)
        {
            if (current > n) return coins + (current - n) * d;
            if (current == n) return coins;
            if (current == 0)
            {
                current++;
                coins += d;
            }

            var resA = Dfs(coins + a, current * 2, n, a, b, c, d);
            var resB = Dfs(coins + b, current * 3, n, a, b, c, d);
            var resC = Dfs(coins + c, current * 5, n, a, b, c, d);
            var resD = Dfs(coins + d, current + 1, n, a, b, c, d);
            // Console.WriteLine($"{resA}, {resB}, {resC}, {resD}");
            var tmp = Math.Min(Math.Min(resA, resB), Math.Min(resC, resD));
            // Console.WriteLine(tmp);
            return tmp;
        }
    }
}

using System;
