            //if(ac == 2 && bc == 1) {
            //    var zzzz = 0;
            //}
            return ret;
        };

        minmin = long.MaxValue;
        mins = new Dictionary<long, long>();
        search(0, n, a, b, c, d);
        for(int i=-100; i<=100; i++) {
            search(d * Math.Abs(i), n+i, a, b, c, d);
        }

        return minmin;
    }

    static long minmin;
    static Dictionary<long, long> mins;

    static void search(long co, long n, long a, long b, long c, long d) {
        if(n == 1) {
            co += n * d;
            minmin = Math.Min(minmin, co);
            //Debug.WriteLine($"{co}");
            return;
        }

        if(minmin <= co) {
            return;
        }

        if(n.ToString().Length + (long)d.ToString().Length < 19)
        minmin = Math.Min(minmin, co + n * d);

        if (mins.ContainsKey(n) && mins[n] <= co) {
            return;
        }

        if(!mins.ContainsKey(n) || mins[n] > co) {
            mins[n] = co;
        }

        if (n / 2 != 0) {
            search(co + a + d * (n % 2), n / 2, a, b, c, d);
        }
        if (n / 3 != 0) {
            search(co + b + d * (n % 3), n / 3, a, b, c, d);
        }
        if (n / 5 != 0) {
            search(co + c + d * (n % 5), n / 5, a, b, c, d);
        }

        n++;
        co += d;
        if (n / 2 != 0) {
            search(co + a + d * (n % 2), n / 2, a, b, c, d);
        }
        if (n / 3 != 0) {
            search(co + b + d * (n % 3), n / 3, a, b, c, d);
        }
        if (n / 5 != 0) {
            search(co + c + d * (n % 5), n / 5, a, b, c, d);
        }

        n-=2;
        if (n / 2 != 0) {
            search(co + a + d * (n % 2), n / 2, a, b, c, d);
        }
        if (n / 3 != 0) {
            search(co + b + d * (n % 3), n / 3, a, b, c, d);
        }
        if (n / 5 != 0) {
            search(co + c + d * (n % 5), n / 5, a, b, c, d);
        }
    }

