using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Numerics;

static class Program
{
    class Solver
    {
        long A;
        long B;
        long C;
        long D;
        Dictionary<long, BigInteger> memo = new Dictionary<long, BigInteger>();
        public Solver(long A, long B, long C, long D)
        {
            this.A = A;
            this.B = B;
            this.C = C;
            this.D = D;
        }
        public BigInteger Solve(long N)
        {
            if (N == 0) { return 0; }
            if (N == 1) { return D; }
            if (!memo.ContainsKey(N))
            {
                var ans = new List<BigInteger> { BigInteger.Multiply(N, D) };
                long i = N % 2;
                long j = N % 3;
                long k = N % 5;
                memo[N] = ans[0];
                if (i == 0)
                {
                    ans.Add(Solve(N / 2) + A);
                }
                else
                {
                    ans.Add(Solve((N - i) / 2) + A + D * i);
                    ans.Add(Solve((N + (2 - i)) / 2) + A + D * (2 - i));
                }
                if (j == 0)
                {
                    ans.Add(Solve(N / 3) + B);
                }
                else
                {
                    ans.Add(Solve((N - j) / 3) + B + D * j);
                    ans.Add(Solve((N + (3 - j)) / 3) + B + D * (3 - j));
                }
                if (k == 0)
                {
                    ans.Add(Solve(N / 5) + C);
                }
                else
                {
                    ans.Add(Solve((N - k) / 5) + C + D * k);
                    ans.Add(Solve((N + (5 - k)) / 5) + C + D * (5 - k));
                }
                memo[N] = ans.Min();
            }
            return memo[N];
        }
    }

    static void Main(string[] args)
    {
        int T = int.Parse(Console.ReadLine());
        for (int i = 0; i < T; ++i)
        {
            var V = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
            Console.WriteLine(new Solver(V[1], V[2], V[3], V[4]).Solve(V[0]));
        }
    }
