class GFG
{
    static long a = 0, b = 0, c = 0, d = 0;
    static long
        target = 0;
    static Dictionary<string, long> dic = new Dictionary<string, long>();
    public static void Main()
    {
        var t = int.Parse(Console.ReadLine());
        while (t > 0)
        {
            t--;
            var input = Console.ReadLine().Split(' ');

            target = int.Parse(input[0]);
            a = int.Parse(input[1]);
            b = int.Parse(input[2]);
            c = int.Parse(input[3]);
            d = int.Parse(input[4]);
            var ans = PlayToWin(target);
            Console.Write(ans);
            Console.WriteLine();
        }

    }

    public static long PlayToWin(long x)
    {
        if (x == 1)
            return 1;
        if (x == 0)
            return 0;
        string key = x.ToString();
        if (dic.ContainsKey(key))
            return dic[key];
        long c2 = ((x + 1) / 2) * 2;
        long f2 = (x / 2) * 2;
        long c3 = ((x + 2) / 3) * 3;
        long f3 = (x / 3) * 3;
        long c5 = ((x + 4) / 5) * 5;
        long f5 = (x / 5) * 5;

        long ret = (x < 1000000000000000000 / d) ? x * d : 1000000000000000000;

        var ans1 = (c2 - x) * d + a + PlayToWin(c2 / 2);
        var ans2 = (x - f2) * d + a + PlayToWin(f2 / 2);
        var ans3 = (c3 - x) * d + b + PlayToWin(c3 / 3);
        var ans4 = (x - f3) * d + b + PlayToWin(f3 / 3);
        var ans5 = (c5 - x) * d + c + PlayToWin(c5 / 5);
        var ans6 = (x - f5) * d + c + PlayToWin(f5 / 5);

        dic.Add(key, Math.Min(Math.Min(Math.Min(Math.Min(Math.Min(Math.Min(ret, ans1), ans2), ans3), ans4), ans5), ans6));
        return dic[key];
    }

}

