class Program {
    static void Main (string[] args) {
        var inp = Console.ReadLine().Split(' ');
        int T = int.Parse(inp[0]);

        for(int i = 0;i < T;i++) {
            var inp2 = Console.ReadLine().Split(' ');
            long N = long.Parse(inp2[0]);
            int A = int.Parse(inp2[1]); //2x
            int B = int.Parse(inp2[2]); //3x
            int C = int.Parse(inp2[3]); //5x
            int D = int.Parse(inp2[4]); //+1-1

            long coin = D;
            List<long> prime = PrimeFactors(N);
            r(prime,ref coin,A,B,C,D);

            Console.WriteLine("{0}",coin);
        }
    }

    public static void r (List<long> _prime,ref long _coin,int A,int B,int C,int D) {
        for(int i = 0;i < _prime.Count;i++) {
            switch(_prime[i]) {
                case 2:
                _coin += A;
                break;

                case 3:
                _coin += B;
                break;

                case 5:
                _coin += C;
                break;

                default:
                _coin += D;
                r(PrimeFactors(_prime[i] - 1),ref _coin,A,B,C,D);
                break;
            }
        }
    }

    public static List<long> PrimeFactors (long n) {
        long i = 2;
        long tmp = n;
        List<long> tmpList = new List<long>();

        while(i * i <= n) {
            if(tmp % i == 0) {
                tmp /= i;
                tmpList.Add(i);
            } else {
                i++;
            }
        }

        if(tmp != 1) tmpList.Add(tmp);

        return tmpList;
    }
}

