public class Hello
{
    public static long a, b, c, d;
    public static Dictionary<long, long> dic;
    public static void Main()
    {
        var t = int.Parse(Console.ReadLine().Trim());
        while (t > 0)
        {
            string[] line = Console.ReadLine().Trim().Split(' ');
            var n = long.Parse(line[0]);
            a = long.Parse(line[1]);
            b = long.Parse(line[2]);
            c = long.Parse(line[3]);
            d = long.Parse(line[4]);
            dic = new Dictionary<long, long>();
            var ans = getAns(n);
            Console.WriteLine(ans);
            t--;
        }
    }
    static long getAns(long n)
    {
        if (n == 0) return 0;
        if (n == 1) return d;
        if (dic.ContainsKey(n)) return dic[n];
        var L2 = n / 2;
        var r2 = (n + 1) / 2;
        var L3 = n / 3;
        var r3 = (n + 2) / 3;
        var L5 = n / 5;
        var r5 = (n + 4) / 5;
        var res = long.MaxValue;
        if (n < res / d) res = n * d;
        res = Min(res, Abs(L2 * 2 - n) * d + a + getAns(L2));
        res = Min(res, Abs(r2 * 2 - n) * d + a + getAns(r2));
        res = Min(res, Abs(L3 * 3 - n) * d + b + getAns(L3));
        res = Min(res, Abs(r3 * 3 - n) * d + b + getAns(r3));
        res = Min(res, Abs(L5 * 5 - n) * d + c + getAns(L5));
        res = Min(res, Abs(r5 * 5 - n) * d + c + getAns(r5));
        dic[n] = res;
        return res;
    }
}

