class Solver
{
    long A, B, C, D;
    Dictionary<long, long> memo;
    public void Solve(Scanner sc)
    {
        var T = sc.Int;
        while (T-- > 0)
        {
            long N;
            sc.Make(out N, out A, out B, out C, out D);
            memo = new Dictionary<long, long>();
            memo[0] = 0;
            memo[1] = D;
            Console.WriteLine(dp(N));
        }
    }
    long dp(long N)
    {
        if (memo.ContainsKey(N)) return memo[N];

        var rt = long.MaxValue/3;
        if ((double)N * D < long.MaxValue/3)
        {
            chmin(ref rt, N * D);
        }
        chmin(ref rt, dp(N / 2) + A + (N % 2) * D);
        chmin(ref rt, dp((N + 1) / 2) + A + (N % 2) * D);
        chmin(ref rt, dp(N / 3) + B + (N % 3) % 3 * D);
        chmin(ref rt, dp((N + 2) / 3) + B + (3 - N % 3) % 3 * D);
        chmin(ref rt, dp(N / 5) + C + (N % 5) * D);
        chmin(ref rt, dp((N + 4) / 5) + C + (5 - N % 5) % 5 * D);
        return memo[N] = rt;
    }
}

