            if (current == n) return coins;
            if (current == 0)
            {
                current++;
                coins += d;
            }

            var resA = Dfs(coins + a, current * 2, n, a, b, c, d);
            var resB = Dfs(coins + b, current * 3, n, a, b, c, d);
            var resC = Dfs(coins + c, current * 5, n, a, b, c, d);
            var resD = coins + Math.Abs(current - n) * d;
            Console.WriteLine($"{resA}, {resB}, {resC}, {resD}");
            var tmp = Math.Min(Math.Min(resA, resB), Math.Min(resC, resD));
            return tmp;
        }
    }
