namespace AtCoder2 {
	class Program {
		static void Main(string[] args) {

	var inputArray = retreiveLongArray();
			var inputCount = 1;

			// 不正な入力は処理しない
			if (inputArray.Length != inputCount) {
				Console.WriteLine("invalid input");
				return;
			}
			long T = inputArray[0];
			var ans = new List<long>();
			for (int i = 0; i < T; i++) {
				var s = Solve();
				ans.Add(s);
			}
			foreach (var item in ans) {
				Console.WriteLine(item);
			}
		}

		/// <summary>
		/// 1つのテストケースについて説く
		/// </summary>
		private static long Solve() {
			var input = retreiveLongArray();
			long N = input[0];
			two = input[1];
			three = input[2];
			five = input[3];
			plusOne = input[4];

			var minCost = long.MaxValue;
			_memoDic = new Dictionary<long, long>();
			//メモ付きDFSで解く
			minCost = DFS(N);
			return minCost;

		}

		private static long DFS(long n) {

			if (n == 1) {
				return plusOne;
			}
			if (n==0) {
				return 0;
			}

			if (_memoDic.ContainsKey(n)) {
				return _memoDic[n];
			}

			var cost2 = subDFS(n, two,2);
			var cost3 = subDFS(n, three, 3);
			var cost5 = subDFS(n, five, 5);

			var cost = Math.Min(Math.Min(cost2, cost3),cost5);
			_memoDic.Add(n, cost);
			return cost;

		}

		private static long subDFS(long n, long shoricost,long divide) {

			checked {
				//divideで割る場合
				var amari = n % divide;
				if (amari == 0) {
					var normal = DFS(n / divide) + shoricost;
					var Jimichi = long.MaxValue;
					if (n-n/divide < shoricost / plusOne + 1) {//オーバーフロー対策である程度まともな時しか計算しない
						Jimichi = DFS(n / divide) + (n - n / divide) * plusOne;
					}
					return Math.Min(normal, Jimichi);

				}
				else {
					var Normal =  shoricost + plusOne * amari;

					var costfloor = subDFS(n - amari,shoricost,divide) + plusOne * amari; 

					var costsail = subDFS(n + divide - amari, shoricost, divide) + plusOne * (divide - amari);

					return Math.Min(costfloor, costsail);
				}
			}

		}

		//計算用メモ
		private static Dictionary<long, long> _memoDic;
		//必要コイン
		private static long two;
		private static long three ;
		private static long five ;
		private static long plusOne ;

		/// <summary>
		/// スペースで区切られた文字列配列の入力を受け取る
		/// </summary>
		/// <returns></returns>
		private static string[] retreiveStringArray() {
			var inputArray = Console.ReadLine().Split(' ');
			return inputArray;
		}

		/// <summary>
		/// スペースで区切られた整数配列の入力を受け取る
		/// </summary>
		/// <returns></returns>
		private static long[] retreiveLongArray() {
			var inputArray = Console.ReadLine().Split(' ');
			var longArray = inputArray.Select(s => long.Parse(s));
			return longArray.ToArray();
		}
	}
