class Solver
{
    public Dictionary<ulong, ulong> dic = new Dictionary<ulong, ulong>();
    public ulong Solve(ulong n)
    {
        if (dic.TryGetValue(n, out var res)) return res;
        if (n == 0) return 0;

        res = d * n;
        var n5 = n / 5;
        var np5 = n / 5 + 1;
        var r5 = n % 5;
        var n3 = n / 3;
        var np3 = n / 3 + 1;
        var r3 = n % 3;
        var n2 = n / 2;
        var np2 = n / 2 + 1;
        var r2 = n % 2;

        if (r5 * d + c < (n - n5) * d)
            res.UpdateMin(r5 * d + c + Solve(n5));
        if (r5 != 0 && (5 - r5) * d + c < (n - np5) * d)
            res.UpdateMin((5 - r5) * d + c + Solve(np5));

        if (r3 * d + b < (n - n3) * d)
            res.UpdateMin(r3 * d + b + Solve(n3));
        if (r3 != 0 && (3 - r3) * d + b < (n - np3) * d)
            res.UpdateMin((3 - r3) * d + b + Solve(np3));

        if (r2 * d + a < (n - n2) * d)
            res.UpdateMin(r2 * d + a + Solve(n2));
        if (r2 != 0 && (2 - r2) * d + a < (n - np2) * d)
            res.UpdateMin((2 - r2) * d + a + Solve(np2));

        return dic[n] = res;
    }
    ulong a;
    ulong b;
    ulong c;
    ulong d;
    public Solver(ulong a, ulong b, ulong c, ulong d)
    {
        this.a = a;
        this.b = b;
        this.c = c;
        this.d = d;
        dic[0] = 0;dic[1] = d;
    }
}

