                memo = new Dictionary<long, long>();

                long ans = DFS(N);
                Console.WriteLine(ans);
            }

        }

        static long A;
        static long B;
        static long C;
        static long D;
        static Dictionary<long, long> memo;
        static long DFS(long N)
        {
            if (N == 1) return D;
            if (N == 0) return 0;
            if (memo.ContainsKey(N)) return memo[N];

            long cand = long.MaxValue;
            if (N % 2 == 0) cand = Math.Min(cand, DFS(N / 2) + A);
            else if (N % 2 == 1)
            {
                cand = Math.Min(cand, DFS((N + 1) / 2) + D + A);
                cand = Math.Min(cand, DFS((N - 1) / 2) + D + A);
            }

            if (N % 3 == 0) cand = Math.Min(cand, DFS(N / 3) + B);
            else
            {
                long k = N % 3;
                cand = Math.Min(cand, DFS((N - k) / 3) + k * D + B);
                cand = Math.Min(cand, DFS((N + 3 - k) / 3) + (3 - k) * D + B);
            }

            if (N % 5 == 0) cand = Math.Min(cand, DFS(N / 5) + C);
            else
            {
                long k = N % 5;
                cand = Math.Min(cand, DFS((N - k) / 5) + k * D + C);
                cand = Math.Min(cand, DFS((N + 5 - k) / 5) + (5 - k) * D + C);
            }
            if (N <= 1000000000) cand = Math.Min(cand, N * D);

            memo.Add(N, cand);
            return cand;
        }
    }


