    static void Solve()
    {
        var T = sc.ReadInt();
        for (int i = 0; i < T; i++)
        {
            var N = sc.ReadLong();
            var A = sc.ReadLong();
            var B = sc.ReadLong();
            var C = sc.ReadLong();
            var D = sc.ReadLong();
            var memo = new HashMap<long, long>();
            long F(long n)
            {
                if (n < 0) return long.MaxValue / 10;
                if (n == 0) return 0;
                if (n == 1) return D;
                if (memo[n] > 0) return memo[n];
                var res = long.MaxValue;
                {
                    var rem = n % 2;
                    var nn = n - rem;
                    res = Math.Min(res, F(nn / 2) + A + D * rem);
                    if (rem > 0)
                    {
                        rem = 2 - rem;
                        nn = n + rem;
                        res = Math.Min(res, F(nn / 2) + A + D * rem);
                    }
                }
                {
                    var rem = n % 3;
                    var nn = n - rem;
                    res = Math.Min(res, F(nn / 3) + B + D * rem);
                    if (rem > 0)
                    {
                        rem = 3 - rem;
                        nn = n + rem;
                        res = Math.Min(res, F(nn / 3) + B + D * rem);
                    }
                }
                {
                    var rem = n % 5;
                    var nn = n - rem;
                    res = Math.Min(res, F(nn / 5) + C + D * rem);
                    if (rem > 0)
                    {
                        rem = 5 - rem;
                        nn = n + rem;
                        res = Math.Min(res, F(nn / 5) + C + D * rem);
                    }
                }
                memo[n] = res;
                return res;
            }
            var ans = F(N);
            Console.WriteLine(ans);
        }
    }
