                    {

                        buf = Math.Abs(Ard - num) * D + A + Solve(Ard / 2);
                        if (buf < minimum) minimum = buf;
                        if (Ard != Aru)
                        {
                            buf = Math.Abs(Aru - num) * D + A + Solve(Aru / 2);
                            if (buf < minimum) minimum = buf;
                        }

                        buf = Math.Abs(Brd - num) * D + B + Solve(Brd / 3);
                        if (buf < minimum) minimum = buf;
                        if (Brd != Bru)
                        {
                            buf = Math.Abs(Bru - num) * D + B + Solve(Bru / 3);
                            if (buf < minimum) minimum = buf;
                        }

                        buf = Math.Abs(Crd - num) * D + C + Solve(Crd / 5);
                        if (buf < minimum) minimum = buf;
                        if (Crd != Cru)
                        {
                            buf = Math.Abs(Cru - num) * D + C + Solve(Cru / 5);
                            if (buf < minimum) minimum = buf;
                        }

                        memo.Add(num, minimum);

                        return minimum;

                    }
                }

            }

            foreach (var data in ans)
                Console.WriteLine(data);
        }

    }

}

