public class Solver
{
	private long[] K = new long[] { 2, 3, 5 };

	public void Solve()
	{
		long T = GetLong();
		WriteLine(string.Join("\n", Range(0, T).Select(_ => solve())));
	}

	private long solve()
	{
		long N = GetLong();
		var ABC = GetLongs(3);
		var D = GetLong();
		return rec(ABC, D, N, new Dictionary<long, long>());
	}

	private long rec(long[] ABC, long D, long x, Dictionary<long, long> dp)
	{
		if(dp.ContainsKey(x))
			return dp[x];

		long min = long.MaxValue / 2;
		try
		{
			chmin(ref min, checked(D * x));
		}
		catch
		{
		}

		for(long i = 0; i < 3; i++)
		{
			long floor = x / K[i];
			if(floor > 0)
			{
				long dpFloor = rec(ABC, D, floor, dp);
				chmin(ref min, dpFloor + ABC[i] + D * Abs(x - K[i] * floor));
			}

			long ceil = (x + K[i] - 1) / K[i];
			if(ceil > 1)
			{
				long dpCeil = rec(ABC, D, ceil, dp);
				chmin(ref min, dpCeil + ABC[i] + D * Abs(x - K[i] * ceil));
			}
		}
		return (dp[x] = min);		
	}
}

