public class Factorial
{
    public long[] Fact;
    public long[] invFact;
    long _mod;
    public Factorial(long N, long mod = 1000000007)
    {
        Fact = new long[N + 1];
        invFact = new long[N + 1];
        _mod = mod;
        Fact[0] = 1;
        Fact[1] = 1;
        for (long i = 2; i <= N; ++i)
        {
            Fact[i] = Fact[i - 1] * i % _mod;
            Fact[i] %= _mod;
        }
        invFact[N] = Power(Fact[N], _mod - 2, _mod);
        for (long i = N; i > 0; --i)
        {
            invFact[i - 1] = invFact[i] * i % _mod;
            invFact[i - 1] %= _mod;
        }
    }
    public long Comb(long n, long r)
    {
        if (n < 0 || r < 0 || n < r) return 0;
        return Fact[n] * invFact[r] % _mod * invFact[n - r] % _mod;
    }
}












public static class NumberTheory
{
    public static Dictionary<long, int> PrimeFactorization(long N)
    {
        var ret = new Dictionary<long, int>();
        for (long i = 2; i * i <= N; ++i)
        {
            int cnt = 0;
            while (N % i == 0)
            {
                cnt++;
                N /= i;
            }
            if (cnt != 0) ret[i] = cnt;
        }
        if (N >= 2) ret[N] = 1;
        return ret;
    }
    public static Dictionary<int, int> FactoricalPF(int N)
    {
        var ret = new Dictionary<int, int>();
        for (int i = 2; i <= N; ++i)
        {
            int ni = i;
            for (int j = 2; j * j <= ni; ++j)
            {
                int cnt = 0;
                while (ni % j == 0)
                {
                    ++cnt;
                    ni /= j;
                }
                if (cnt == 0) continue;
                if (ret.ContainsKey(j))
                    ret[j] += cnt;
                else ret[j] = cnt;
            }
            if (ni >= 2)
            {
                if (ret.ContainsKey(ni))
                    ret[ni] += 1;
                else ret[ni] = 1;
            }
        }
        return ret;
    }
    public static List<long> DivisorEnumrate(long N)
    {
        var ret = new List<long>();
        for (long i = 1; i * i <= N; ++i)
        {
            if (N % i == 0)
            {
                ret.Add(i);
                ret.Add(N / i);
            }
        }
        return ret;
    }
    public static List<int> seive(int n)
    {
        var ret = new List<int>();
        bool[] isPrime = new bool[n + 1];
        for (int i = 1; i <= n; ++i) isPrime[i] = true;
        isPrime[1] = false;
        for (int i = 1; i <= n; ++i)
        {
            int j = i;
            if (isPrime[i]) ret.Add(i);
            else continue;
            while (j <= n)
            {
                j += i;
                if (j > n) continue;
                isPrime[j] = false;
            }
        }
        return ret;
    }
    public static bool isPrime(long n)
    {
        for (int i = 2; i * i <= n; ++i)
        {
            if (n % i == 0) return false;
        }
        return true;
    }
}
