            N = r[0];A = r[1];B = r[2];C = r[3];D = r[4];
            Dic = new Dictionary<long, long>();
            Dic[N] = 0;
            DFS(N, 0);
            Console.WriteLine(Dic[1] + D);
        }
    }

    static void DFS(long n,long m)
    {

        Dic[n] = Min(Dic[n], m);
        if (n <= 1) return;
        if (Dic[n] != m) return;

        long p = n % 2;
        if (Point(n / 2) > m + A + D * p)
            DFS(n / 2, Min(m + A + D * p,m + f(n-n/2,D)));
        if (p > 0)
        {
            long min = Min(m + A + D * (2 - p), m + f(n - n / 2 - 1, D));
            if ( Point(n / 2 + 1) > min)
                DFS(n / 2 + 1, min);
        }

         p = n % 3;
        if (Point(n / 3) > m + B + D * p)
            DFS(n / 3, Min(m + B + D * p,m + f(n-n/3,D)));
        if (p > 0)
        {
            long min = Min(m + B + D * (3 - p), m + f(n - n / 3 - 1, D));
                if(p>0&&Point(n/3+1)> min)
                    DFS(n / 3 + 1, min);
        }


        if (n < 5) return;
        p = n % 5;
        if (Point(n / 5) > m + C + D * p)
            DFS(n / 5, Min(m + C + D * p,m + f(n-n/5,D)));
        if (p > 0)
        {
            long min = Min(m + C + D * (5 - p), m + f(n - n / 5 - 1, D));
                if (p > 0 && Point(n / 5 + 1) >min)
                    DFS(n / 5 + 1,min);
        }

    }
    static long Point(long num)
    {
        if (!Dic.ContainsKey(num)) Dic[num] = long.MaxValue/2;
        return Dic[num];
    }
    static long f(long a,long b)
    {
        if( Log10(a)+Log10(b)+2>= 19)
        {
            return long.MaxValue/2;
        }
        return a * b;
    }
}

