            for (int i = 0; i < T; i++)
            {
                memo = new Dictionary<long, long>();
                var vals2 = Console.ReadLine().Split(' ')
                .Select(x => long.Parse(x)).ToList();
                N = vals2[0];
                A = vals2[1];
                B = vals2[2];
                C = vals2[3];
                D = vals2[4];
                var ans = serch(N);
                Console.WriteLine(ans);


            }



            Console.Out.Flush();

        }
        static long serch(long num)
        {
            checked
            {
                if (num == 900000000000000000)
                {

                }
                long ans;
                long gval;
                if (memo.TryGetValue(num, out gval))
                {
                    return gval;
                }
                if (num == 1)
                {
                    memo[num] = D;
                    return D;

                }
                if (num == 0)
                {
                    return 0;
                }
                ans = serch(num / 2) + A + D * (num % 2);

                if (num > 2)
                    ans = Math.Min(serch(num / 2 + 1) + A + D * (2-num % 2), ans);

                ans = Math.Min(serch(num / 3) + B + D * (num % 3), ans);
                ans = Math.Min(serch(num / 3 + 1) + B + D * (3 - num % 3), ans);
                ans = Math.Min(serch(num / 5) + C + D * (num % 5), ans);
                ans = Math.Min(serch(num / 5 + 1) + C + D * (5 - num % 5), ans);
                if (long.MaxValue / num > D)
                {
                    ans = Math.Min(ans, D * num);
                }

                memo[num] = ans;


                return ans;
            }
        }



    }

