                    if (!map.TryGetValue(nn, out o) || o > nc)
                    {
                        map[nn] = nc;
                        pq.Enqueue(new Pair(nn, nc));
                    }
                }

                {
                    long nn = pop.N / 3 + 1;
                    long nc = pop.Coin + Math.Min(d * (3 - m) + b, Mul(d, pop.N - nn));
                    if (!map.TryGetValue(nn, out o) || o > nc)
                    {
                        map[nn] = nc;
                        pq.Enqueue(new Pair(nn, nc));
                    }
                }
            }

            // 2
            {
