                }

                {
                    long nn = pop.N / 2 + 1;
                    long nc = pop.Coin + Math.Min(d * (2 - m) + a, Mul(d, pop.N - nn));
                    if (!map.TryGetValue(nn, out o) || o > nc)
                    {
                        map[nn] = nc;
                        pq.Enqueue(new Pair(nn, nc));
                    }
                }
            }
        }

        return "-1";
    }



    public static void Main(string[] args) => new Program().Solve();
}

