function exec(N, A, B, C, D) {
  // console.log(N, A, B, C, D)

  // 
  let queue = [
    {
      c: 0n,
      n: N,
      // debug
      d: 0
    }
  ]
  let visited = {
  }
  let min = Number.MAX_SAFE_INTEGER

  while(queue.length > 0) {
    const q = queue.shift()
    // console.log(q.d, q, 'remain:', queue.length, 'min:', min)
    // console.log(queue)

    // // debug
    // if (q.d > 2) break

    visited[q.n] = q.c
    // クリア判定
    if (0n === q.n) {
      // console.log('found:', q)
      if (min > q.c) {
        min = q.c
        continue
      }
    }

    // 終了判定
    if (min <= q.c) {
      // console.log('finish')
      continue
    }

    //A
    if (q.n % 2n === 0n) {
      const n = q.n / 2n
      const cD = q.c + A
      const cA = q.c + D * (q.n - n)
      if (!visited[n] || visited[n] > cD || visited[n] > cA) {
        if (cD < cA) {
          visited[n] = cD
          queue.push({
            c: cD,
            n: n,
            d: q.d+1
          })
        } else {
          visited[n] = cA
          queue.push({
            c: cA,
            n: n,
            d: q.d+1
          })
        }
      }
    } else {
      {
        const n =(q.n+1n) / 2n
        const cD = q.c + A + D
        const cA = q.c + D * (q.n - n)
        if (!visited[n] || visited[n] > cD || visited[n] > cA) {
          if (cD < cA) {
            visited[n] = cD
            queue.push({
              c: cD,
              n: n,
              d: q.d+1
            })
          } else {
            visited[n] = cA
