class TestCase
  def initialize(a, b, c, d)
    @a, @b, @c, @d = a, b, c, d
    @memo = {0 => 0, 1 => d}              # 初期値
  end

  def go(n)
    return @memo[n] if @memo.key? n
    ad, bd, cd = n/2, n/3, n/5
    ai, bi, ci = (n+1)/2, (n+2)/3, (n+4)/5
    # `n-bd*3` は `n%3` と同じ意味
    # `bi*3-n` は `(3-n%3)%3` と同じ意味
    @memo[n] ||= [
      @d * n,                             # ずっとD
      @a + @d * (n&1) + go(ad),           # Dで2の倍数に減らしてA
      @b + @d * (n-bd*3) + go(bd),        # Dで3の倍数に減らしてB
      @c + @d * (n-cd*5) + go(cd),        # Dで5の倍数に減らしてC
      @a + @d * (n&1) + go(ai),           # Dで2の倍数に増やしてA
      @b + @d * (bi*3-n) + go(bi),        # Dで2の倍数に増やしてB
      @c + @d * (ci*5-n) + go(ci)         # Dで2の倍数に増やしてC
      ].min
  end
end

gets.to_i.times do
  n, a, b, c, d = gets.chomp.split(" ").map(&:to_i)
  t = TestCase.new(a, b, c, d)
  puts t.go(n)
end

