func solve(n int) int {
	if n == 0 {
		return 0
	}
	if n == 1 {
		return d
	}
	// out(n)
	if dp[n] != 0 {
		return dp[n]
	}
	// out(n)
	var r, x int
	r = n % 5
	x = n - r
	ret := solve(x/5) + c + d*r
	if x != n && x != 0 {
		x += 5
		ret = min(ret, solve(x/5)+c+(5-r)*d)
	}

	r = n % 3
	x = n - r
	ret = min(ret, solve(x/3)+b+d*r)
	if x != n && x != 0 {
		x += 3
		ret = min(ret, solve(x/3)+b+(3-r)*d)
	}
	r = n % 2
	x = n - r
	ret = min(ret, solve(x/2)+a+d*r)
	if x != n && x != 0 {
		x += 2
		ret = min(ret, solve(x/2)+a+(2-r)*d)
	}

	if n*d/d == n {
		ret = min(ret, n*d)
	}
	dp[n] = ret
	return ret
}

