const Inf = math.MaxInt64

func solve(n, a, b, c, d int) int {
	q := Heap{}
	now := State{n, 0}
	q.push(now)
	visited := make(map[int]bool)

	ans := Inf
	for len(q) > 0 {
		now = q.pop()
		if now.number <= (Inf-now.cost)/d {
			// Infを超えない範囲だったら number * d を加算したやつを暫定最小値として計算する
			ans = Min(ans, now.cost+now.number*d)
		}
		if now.cost >= ans {
			return ans
		}
		if visited[now.number] {
			continue
		}
		visited[now.number] = true
		{ // c *5
			l := now.number / 5 * 5
			r := l + 5
			q.push(State{
				number: l / 5,
				cost:   now.cost + c + (now.number-l)*d,
			})
			q.push(State{
				number: r / 5,
				cost:   now.cost + c + (r-now.number)*d,
			})
		}
		{ // b *3
			l := now.number / 3 * 3
			r := l + 3
			q.push(State{
				number: l / 3,
				cost:   now.cost + b + (now.number-l)*d,
			})
			q.push(State{
				number: r / 3,
				cost:   now.cost + b + (r-now.number)*d,
			})
		}
		{ // a *2
			l := now.number / 2 * 2
			r := l + 2
			q.push(State{
				number: l / 2,
				cost:   now.cost + a + (now.number-l)*d,
			})
			q.push(State{
				number: r / 2,
				cost:   now.cost + a + (r-now.number)*d,
			})
		}
	}
	return ans
}

func Min(xs ...int) int {
	min := xs[0]
	for _, x := range xs[1:] {
		if min > x {
			min = x
		}
	}
	return min
}

type State struct {
	number int
	cost   int
}

type HeapElement = State
type Heap []HeapElement

func (h Heap) Less(i, j int) bool    { return h[i].cost < h[j].cost }
func (h Heap) Len() int              { return len(h) }
func (h Heap) Swap(i, j int)         { h[i], h[j] = h[j], h[i] }
func (h *Heap) Push(x interface{})   { *h = append(*h, x.(HeapElement)) }
func (h *Heap) Pop() (x interface{}) { *h, x = (*h)[:len(*h)-1], (*h)[len(*h)-1]; return }
func (h *Heap) push(v HeapElement)   { heap.Push(h, v) }
func (h *Heap) pop() HeapElement     { return heap.Pop(h).(HeapElement) }

