	t := intScanner()
	for i := 0; i < t; i++ {
		n := intScanner()
		a, b, c, d = intScanner(), intScanner(), intScanner(), intScanner()
		m = make(map[int]int)
		m[0], m[1] = 0, d
		solve(n)
		fmt.Println(m[n])
	}
}
func solve(x int) {
	p := make([]int, 7)
	p[0] = q(x/2) + a + x%2*d
	p[1] = q((x+1)/2) + a + ((x+1)/2*2-x)*d
	p[2] = q(x/3) + b + x%3*d
	p[3] = q((x+2)/3) + b + ((x+2)/3*3-x)*d
	p[4] = q(x/5) + c + x%5*d
	p[5] = q((x+4)/5) + c + ((x+4)/5*5-x)*d
	p[6] = overflow(x * d)
	m[x] = min(p)
}
func q(x int) int {
	if _, ok := m[x]; !ok {
		solve(x)
	}
	return m[x]
}
func overflow(x int) int {
	if x*d/d == x {
		return x
	} else {
		return mod * mod
	}
}

