var DEBUG = true

func main() {
	defer Flush()

	T := readi()
	for t := 0; t < T; t++ {
		N := readi()
		A := readi()
		B := readi()
		C := readi()
		D := readi()
		println(solve(N, A, B, C, D))
		Flush()
	}
}

func solve(N, A, B, C, D int) int {
	dp := make(map[int]int)

	dp[0] = 0
	dp[1] = D

	dc := []int{A, B, C}
	var dfs func(N int) int
	dfs = func(N int) int {
		//dbg("N", N)
		v, ok := dp[N]
		if ok {
			return v
		}

		res := math.MaxInt64
		for i, d := range []int{2, 3, 5} {
			E := dc[i]
			if m := N % d; m == 0 {
				//dbg(N, "=>", N/d)
				res = min(res, E+dfs(N/d))
			} else {
				r := d - m
				//dbg(N, "=>", (N-m)/d)
				res = min(res, D*m+E+dfs((N-m)/d))
				//dbg(N, "=>", (N+d-m)/d)
				res = min(res, D*r+E+dfs((N+r)/d))
			}
			dN := N - N/d
			// dN*D < E
			// dN*D < (E+D-1)
			if dN < (E+D-1)/D {
				res = min(res, dN*D+dfs(N/d))
			}
		}
		dp[N] = res
		return res
	}
	ans := dfs(N)
	return ans
}

