// cur->0にかかる最小コストを計算
// memo[cur]に最小コストを格納する
func dfs(cur int) {
	if _, ok := memo[cur]; ok {
		return
	}

	if cur == 1 {
		// memo[cur] = d
		return
	}

	if cur == 0 {
		// memo[0] = 0
		return
	}

	dfs(cur / 2)
	dfs(Kiriage(cur, 2))
	dfs(cur / 3)
	dfs(Kiriage(cur, 3))
	dfs(cur / 5)
	dfs(Kiriage(cur, 5))

	res := INF_INT64
	if cur < res/d {
		res = cur * d
	}

	ChMin(&res, memo[cur/2]+a+(cur-2*(cur/2))*d)
	ChMin(&res, memo[cur/3]+b+(cur-3*(cur/3))*d)
	ChMin(&res, memo[cur/5]+c+(cur-5*(cur/5))*d)

	tmp := Kiriage(cur, 2)
	ChMin(&res, memo[tmp]+a+(2*tmp-cur)*d)
	tmp = Kiriage(cur, 3)
	ChMin(&res, memo[tmp]+b+(3*tmp-cur)*d)
	tmp = Kiriage(cur, 5)
	ChMin(&res, memo[tmp]+c+(5*tmp-cur)*d)

	memo[cur] = res
}

// Kiriage returns Ceil(a/b)
// a >= 0, b > 0
func Kiriage(a, b int) int {
	return (a + (b - 1)) / b
}

// ChMin accepts a pointer of integer and a target value.
// If target value is SMALLER than the first argument,
//	then the first argument will be updated by the second argument.
func ChMin(updatedValue *int, target int) bool {
	if *updatedValue > target {
		*updatedValue = target
		return true
	}
	return false
}

