}

func main() {
	scanner.Split(bufio.ScanWords)

	// 試行数
	t := scanNumberToken()
	for ; t > 0; t-- {

		// 目標数
		n := scanNumberToken()
		//支払い枚数 a:2倍、 b:3倍、c:5倍
		a, b, c, d := scanNumberToken(), scanNumberToken(), scanNumberToken(), scanNumberToken()

		var target int = 1     // おそらく最初に必ずdをやるので +1
		var totalCoins int = d // 最初は0から増やすのでdの経費はかかる
		for n != target {
			planA := (target * 2) / a
			planB := (target * 3) / b
			planC := (target * 5) / c
			plans := []int{planA, planB, planC}
			sort.Ints(plans)
			fmt.Println(target, totalCoins)
			time.Sleep(1 * time.Second)

			// 目標数と現状の差
			remain := int(math.Abs(float64(n - target)))
			remainA := int(math.Abs(float64(n - target*2)))
			remainB := int(math.Abs(float64(n - target*3)))
			remainC := int(math.Abs(float64(n - target*5)))
			remains := []int{remainA, remainB, remainC}
			sort.Ints(remains)

			if remains[0] == remainC && plans[len(plans)-1] == planC {
				totalCoins += c
				target *= 5
				continue
			}
			if remains[0] == remainB && plans[len(plans)-1] == planB {
				totalCoins += b
				target *= 3
				continue
			}
			if remains[0] == remainA && plans[len(plans)-1] == planA {
				totalCoins += a
				target *= 2
				continue
			}

			totalCoins += d * remain
			target = n
		}
		fmt.Println(totalCoins)
	}
}

