func solve(x int) {
	p := make([]int, 6)
	p[0] = q(x/2) + smaller(a+x%2*d, overflow((x-x/2)*d))
	p[1] = q((x+1)/2) + smaller(a+((x+1)/2*2-x)*d, overflow((x-(x+1)/2)*d))
	p[2] = q(x/3) + smaller(b+x%3*d, overflow((x-x/3)*d))
	p[3] = q((x+2)/3) + smaller(b+((x+2)/3*3-x)*d, overflow((x-(x+2)/3)*d))
	p[4] = q(x/5) + smaller(c+x%5*d, overflow((x-x/5)*d))
	p[5] = q((x+4)/5) + smaller(c+((x+4)/5*5-x)*d, overflow((x-(x+4)/5)*d))
	m[x] = min(p)
}
