var memo map[int]int

var A, B, C, D int

func solve(N int) int {
	if N == 0 {
		return 0
	}
	if N == 1 {
		return D
	}
	if v, ok := memo[N]; ok {
		// log.Println(N, v, ok)
		return v
	}
	l2 := (N / 2) * 2
	r2 := ((N + 1) / 2) * 2
	l3 := (N / 3) * 3
	r3 := ((N + 2) / 3) * 3
	l5 := (N / 5) * 5
	r5 := ((N + 4) / 5) * 5
	res := int(1e18)
	if N < res/D {
		res = N * D
	}
	res = min(res, abs(l2-N)*D+A+solve(l2/2))
	res = min(res, abs(r2-N)*D+A+solve(r2/2))
	res = min(res, abs(l3-N)*D+B+solve(l3/3))
	res = min(res, abs(r3-N)*D+B+solve(r3/3))
	res = min(res, abs(l5-N)*D+C+solve(l5/5))
	res = min(res, abs(r5-N)*D+C+solve(r5/5))
	memo[N] = res
	return res
}

