func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	t := getNextInt(scanner)
	for tt := 0; tt < t; tt++ {
		n := getNextInt64(scanner)
		a := getNextInt64(scanner)
		b := getNextInt64(scanner)
		c := getNextInt64(scanner)
		d := getNextInt64(scanner)
		cc := &coins{}
		heap.Init(cc)
		heap.Push(cc, newCoin(n, 0))
		costs := map[int64]int64{2: a, 3: b, 5: c}
		var ans int64
		ans = math.MaxInt64
		memo := map[int64]int64{}
		for cc.Len() > 0 {
			p := heap.Pop(cc).(coin)
			if memo[p.n] > 0 {
				continue
			}
			memo[p.n] = p.cost
			if p.cost > ans {
				continue
			}
			if p.n == 0 {
				ans = p.cost
				continue
			}
			if p.n > n+5 {
				continue
			}
			for _, div := range [3]int64{2, 3, 5} {
				if p.n%div == 0 {
					heap.Push(cc, newCoin(p.n/div, p.cost+costs[div]))
					continue
				}
				if p.n < div {
					heap.Push(cc, newCoin(0, p.cost+d*p.n))
					continue
				}
				heap.Push(cc, newCoin(p.n/div, p.cost+costs[div]+d*(p.n%div)))
				heap.Push(cc, newCoin(p.n/div+1, p.cost+costs[div]+d*(div-p.n%div)))
				if (math.MaxInt64-p.cost)/d > p.n {
					heap.Push(cc, newCoin(0, p.cost+d*p.n))
				}

			}
		}
		fmt.Fprintln(writer, ans)
	}
}

func newCoin(n, cost int64) coin {
	return coin{
		n:    n,
		cost: cost,
	}
}

type coin struct {
	n, cost int64
}

type coins []coin

func (h coins) Len() int { return len(h) }
func (h coins) Less(i, j int) bool {
	return h[i].cost < h[j].cost
}
func (h coins) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *coins) Push(x interface{}) {
	*h = append(*h, x.(coin))
}
func (h *coins) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

