func foo(m map[int]int, n, a, b, c, d int) int {
	if n == 0 {return 0}
	if n == 1 {return d}
	if m[n] > 0 {return m[n]}

	res := n * d
	f2 := n / 2
	c2 := (n + 1) / 2
	f3 := n / 3
	c3 := (n + 2) / 3
	f5 := n / 5
	c5 := (n + 4) / 5

	res = min(res, (n - f2 * 2) * d + a + foo(m, f2, a, b, c, d))
	res = min(res, (c2 * 2 - n) * d + a + foo(m, c2, a, b, c, d))

	res = min(res, (n - f3 * 3) * d + b + foo(m, f3, a, b, c, d))
	res = min(res, (c3 * 3 - n) * d + b + foo(m, c3, a, b, c, d))

	res = min(res, (n - f5 * 5) * d + c + foo(m, f5, a, b, c, d))
	res = min(res, (c5 * 5 - n) * d + c + foo(m, c5, a, b, c, d))

	m[n] = res
	return res
}

