            if (n !in memo) {
                auto res = n * D;
                res = min(res, solve(n / BigInt(2)) + A + (n % BigInt(2)) * D);
                res = min(res, solve(n / BigInt(3)) + B + (n % BigInt(3)) * D);
                res = min(res, solve(n / BigInt(5)) + C + (n % BigInt(5)) * D);
                memo[n] = res;
            }
            return memo[n];
        }
        writeln(solve(N));
    }
}

