enum long INF = long.max/5;

long A, B, C, D;
long[long] memo;

long f(long N) {
  if (N == 0) return 0;
  if (N == 1) return D;
  if (N in memo) return memo[N];

  long res = INF;
  if (N < INF/D) res.ch!min(N*D);

  res.ch!min(D*abs(N - N.floor(2)*2) + A + f(N.floor(2)));
  res.ch!min(D*abs(N - N.ceil(2) *2) + A + f(N.ceil(2) ));
  res.ch!min(D*abs(N - N.floor(3)*3) + B + f(N.floor(3)));
  res.ch!min(D*abs(N - N.ceil(3) *3) + B + f(N.ceil(3) ));
  res.ch!min(D*abs(N - N.floor(5)*5) + C + f(N.floor(5)));
  res.ch!min(D*abs(N - N.ceil(5) *5) + C + f(N.ceil(5) ));

  return memo[N] = res;
}

