def minCost(n):
	if n == 1:
		return d
	if n == 2:
		return min(d + a, 2 * d)
	if n == 3:
		return min(d + b, 3 * d)
	if n == 5:
		return min(d + c, 5 * d)
	if n in pw:
		return pw[n]
	else:
		ns = dict()
		ns[n - (n % 2)] = 1
		ns[n + (2 - (n % 2))] = 1
		ns[n - (n % 3)] = 1
		ns[n + (3 - (n % 3))] = 1
		ns[n - (n % 5)] = 1
		ns[n + (5 - (n % 5))] = 1
		_min = n * d
		for key in ns:
			if key > 0:
				if key % 2 == 0:
					_min = min(_min, a + int(minCost(key // 2)) + d * abs(n - key))
				if key % 3 == 0:
					_min = min(_min, b + int(minCost(key // 3)) + d * abs(n - key))
				if key % 5 == 0:
					_min = min(_min, c + int(minCost(key // 5)) + d * abs(n - key))
		pw[n] = _min
		return pw[n]

