import copy


def prime_factorize(n, a, b, c, d, ans, tmp_dict={1: 0, 2: 0, 3: 0, 5: 0}):
    tmp = copy.copy(tmp_dict)
    if n == 1:
        tmp[1] += 1
        ans.append(tmp[2] * a + tmp[3] * b + tmp[5] * c + tmp[1] * d)
        return
    if n % 2 != 0:
        tmp[1] += 1
        return (
            prime_factorize(n - 1, a, b, c, d, ans, tmp),
            prime_factorize(n + 1, a, b, c, d, ans, tmp),
        )
    while n % 2 == 0:
        if a <= n * d:
            tmp[2] += 1
        else:
            tmp[1] += n - n // 2
        n //= 2
    while n % 3 == 0:
        if b <= n * d:
            tmp[3] += 1
        else:
            tmp[1] += n - n // 3
        n //= 3
    while n % 5 == 0:
        if c <= n * d:
            tmp[5] += 1
        else:
            tmp[1] += n - n // 5
        n //= 5
    return prime_factorize(n, a, b, c, d, ans, tmp)


