min_coin = 0
def search(N, n, c, A, B, C, D):
    global min_coin
    if c > min_coin:
        return N*D
    if n > N*2:
        return N*D
    if n <= 0:
        return N*D
    if c > N*D:
        return N*D
    if N == n:
        min_coin = c
        return c
    AA = search(N, n*2, c+A, A, B, C, D)
    BB = search(N, n*3, c+B, A, B, C, D)
    CC = search(N, n*5, c+C, A, B, C, D)
    DD = search(N, n+1, c+D, A, B, C, D)
    DDD = search(N, n-1, c+D, A, B, C, D)
    return min(AA, BB, CC, DD, DDD)

