def get(target,cost_one,cost_two,cost_three,cost_five):
  dp = [float("inf") for _ in range(5*target)]
  def recurse(num,cost):
    if num ==  target:
      return cost;
    if num == 0:
      return recurse(1,cost_one);
    if dp[num] != float("inf"):
      return dp[num];
    else:
      minima = float("inf")
      if num < target:
        minima = min(minima,recurse(num+1,cost + cost_one),recurse(num*2,cost + cost_two),recurse(num*3,cost + cost_three),recurse(num*5,cost+ cost_five))
      else:
        minima = recurse(target,cost  + (num - target)*cost_one)
    dp[num] = minima;
    return minima;
  return recurse(0,0)
