def gen_dp(a, b, c, d):
    @lru_cache(maxsize=None)
    def dp(n):

        if n == 0:
            return 0
        elif n == 1:
            return d
        else:
            return min(
                d * n,
                d * abs(n - (n // 5 * 5)) + c + dp(n // 5),
                d * abs(n - ((n + 4) // 5 * 5)) + c + dp((n + 4) // 5),
                d * abs(n - (n // 3 * 3)) + b + dp(n // 3),
                d * abs(n - ((n + 2) // 3 * 3)) + b + dp((n + 2) // 3),
                d * abs(n - (n // 2 * 2)) + a + dp(n // 2),
                d * abs(n - ((n + 1) // 2 * 2)) + a + dp((n + 1) // 2),
            )

    return dp


