    arr = []
    temp = n
    for i in [2, 3, 5]:
        if temp % i == 0:
            cnt = 0
            while temp % i == 0:
                cnt += 1
                temp //= i
            arr.append(cnt)
        else:
            arr.append(0)
    return arr

