    def dfs(n):  # n -> 0 になるまでのコスト
        if n == 0:
            return 0
        if n == 1:
            return D

        cost = n * D

        for div, c in zip((2, 3, 5), (A, B, C)):
            m = n % div
            if m == 0:
                cost = min(cost, dfs(n // div) + c)
            else:
                cost = min(cost, dfs(math.floor(n / div)) + c + D * m)
                cost = min(cost, dfs(math.ceil(n / div)) + c + D * (div - m))

        return cost

    return dfs(N)


