    v = n
    total = 2**a * 3**b * 5**c
    if total > v:
        return (total-v)*D + a*A + b*B + c*C + cost
    if v==1:
        return a*A + b*B + c*C + cost
    while True:
        if a==0 and b==0 and c==0:
            return D*(v-1)+cost

        if a>0 and v%2==0:
            cost += A
            v = v//2
            a -= 1
        elif b>0 and v%3==0:
            cost += B
            v = v//3
            b -= 1
        elif c>0 and v%5==0:
            cost += C
            v = v//5
            c -= 1
        else:
            best = 10**30
            if c>0:
                if v%5<=2:
                    m = _sub(v//5,A,B,C,D,a,b,c-1, cost=cost+D*(v%5)+C)
                    best = min(m, best)
                else:
                    m = _sub(v//5+1,A,B,C,D,a,b,c-1, cost=cost+D*(5-(v%5))+C)
