            return 0
        if n == 1:
            return d
        ans = n * d
        if n % 2 == 0:
            ans = min(ans, F(n//2) + a)
        if n % 2 == 1:
            up = F((n + 1) // 2) + a + d
            down = F((n - 1) // 2) + a + d
            ans = min(ans, up, down)
        if n % 3 == 0:
            ans = min(ans, F(n // 3) + b)
        if n % 3 == 1:
            up = F((n + 2) // 3) + b + d + d
            down = F((n - 1) // 3) + b + d
            ans = min(ans, up, down)
        if n % 3 == 2:
            up = F((n + 1) // 3) + b + d
            down = F((n - 2) // 3) + b + d + d
            ans = min(ans, up, down)
        if n % 5 == 0:
            ans = min(ans, F(n // 5) + c)
        if n % 5 == 1:
            up = F((n + 4) // 5) + c + d + d + d + d
            down = F((n - 1) // 5) + c + d
            ans = min(ans, up, down)
        if n % 5 == 2:
            up = F((n + 3) // 5) + c + d + d + d
            down = F((n - 2) // 5) + c + d + d
            ans = min(ans, up, down)
        if n % 5 == 3:
            up = F((n + 2) // 5) + c + d + d
            down = F((n - 3) // 5) + c + d + d + d
            ans = min(ans, up, down)
        if n % 5 == 4:
            up = F((n + 1) // 5) + c + d
            down = F((n - 4) // 5) + c + d + d + d + d
            ans = min(ans, up, down)
        return ans

