def f(N):
    if N == 1:
        return D

    if N in CACHE:
        return CACHE[N]

    x = None
    if N%2 == 0:
        x = f(N//2) + A
    else:
        N2 = N//2
        x = min(f(N2+1), f(N2)) + A + D

    N3 = N%3
    if N3 == 0:
        x = min(x, f(N//3)+B)
    elif N3 == 1:
        x = min(x, f(N//3)+B+D)
    else:
        x = min(x, f(N//3+1)+B+D)

    if N >= 4:
        N5 = N%5
        if N5 == 0:
            x = min(x, f(N//5)+C)
        elif N5 <= 2:
            x = min(x, f(N//5)+C+D*N5)
        else:
            x = min(x, f(N//5+1)+C+D*(5-N5))

    if D <= x/N:
        x = min(x, D*N)

    CACHE[N] = x
    return x


