def select_abcd(v, r, N, A, B, C, D, min_v):
  if r == N:
    return v
  if r > N:
    return min(v + D * (r - N), min_v)
  if v == 0:
    return select_abcd(v + D, r + 1, N, A, B, C, D, min_v)
  else:
    tmp = (N - r) * D
    if min_v > v + D:
      if tmp < A + abs(r * 2 - N) * D and tmp < B + abs(r * 3 - N) * D and tmp < C + abs(r * 5 - N) * D:
        return min(min_v, v + tmp)
      if A > D and B > D and C > D:
        min_v = min(min_v, select_abcd(v + D, r + 1, N, A, B, C, D, min_v))
    if min_v > v + A and tmp > A + abs(r * 2 - N) * D:
      min_v = min(min_v, select_abcd(v + A, r * 2, N, A, B, C, D, min_v))
    if A + A + abs(r * 4 - N) * D > B + abs(r * 3 - N) * D and min_v > v + B and tmp > B + abs(r * 3 - N) * D:
      min_v = min(min_v, select_abcd(v + B, r * 3, N, A, B, C, D, min_v))
    if A + B + abs(r * 6 - N) * D > C + abs(r * 5 - N) * D and min_v > v + C and tmp > C + abs(r * 5 - N) * D:
      min_v = min(min_v, select_abcd(v + C, r * 5, N, A, B, C, D, min_v))
    return min_v


