def solve(problem):
    N, A, B, C, D = problem[0], problem[1], problem[2], problem[3], problem[4]
    dp = [[0 for n in range(2*N+1)] for r in range(max(A,B,C,D))]
    dp[-1][0] = 1
    nowcoin = 0
    lbound = 0
    ubound = 2

    while dp[-1][N] == 0:
        nowcoin += 1
        newline = list(dp[-1])
        if newline[lbound] == 1:
            lbound += 1
        print(lbound)

        for n in range(lbound,min(ubound,2*N+1)):
            if newline[n] == 0:
                if n%2 == 0:
                    if dp[-A][int(n/2)] == 1:
                        newline[n] = 1
                        ubound = max(n*5, ubound)
            if newline[n] == 0:
                if n%3 == 0:
                    if dp[-B][int(n/3)] == 1:
                        newline[n] = 1
                        ubound = max(n*5, ubound)
            if newline[n] == 0:
                if n%5 == 0:
                    if dp[-C][int(n/5)] == 1:
                        newline[n] = 1
                        ubound = max(n*5, ubound)
            if newline[n] == 0:
                if n+1 <= 2*N:
                    if dp[-D][int(n+1)] == 1:
                        newline[n] = 1
                        ubound = max(n*5, ubound)
            if newline[n] == 0:
                if n-1 >= 0:
                    if dp[-D][int(n-1)] == 1:
                        newline[n] = 1
                        ubound = max(n*5, ubound)
        dp.pop(0)
