def search(n, a, b, c, d, k, result):
    if(k == 0):
        return result
    elif(k == 1):
        return result + d
    elif(k == 2):
        return min(result +2*d, result + a +d)
    else:
        if(k % 2 == 0):
            m1 = 0
        else:
            m1 = 1
        m2 = m1
        if(k % 3 == 0):
            m3 = 0
            m4 = 0
        else:
            m3 = 3 - (k%3)
            m4 = 3 - m3
        if(k % 5 == 0):
            m5 = 0
            m6 = 0
        else:
            m5 = 5 - (k%5)
            m6 = 5 - m5
        return min(search(n, a, b, c, d, (k + m1)/2, result + d * m1 + a),
                    search(n, a, b, c, d, (k - m2)/2, result + d * m2 + a),
                    search(n, a, b, c, d, (k + m3)/3, result + d * m3 + b),
                    search(n, a, b, c, d, (k - m4)/3, result + d * m4 + b),
                    search(n, a, b, c, d, (k + m5)/5, result + d * m5 + c),
                    search(n, a, b, c, d, (k - m6)/5, result + d * m6 + c))

