def solve(N, A, B, C, D, memo):
    if N in memo:
        return memo[N]
    ans = D * N
    if N <= 1:
        memo[N] = ans
        return ans
    divs = [(2, A), (3, B), (5, C)]
    for divider, divcost in divs:
        delta = N % divider
        if delta:
            ans = min(ans, solve(N // divider, A, B, C, D, memo) +
                      divcost + D * delta)
            ans = min(ans, solve(N // divider + 1, A, B, C, D, memo) +
                      divcost + D * (divider - delta))
        else:
            ans = min(ans, solve(N // divider, A, B, C, D, memo) + divcost)
    memo[N] = ans
    return ans


