import functools
def solve(N, A, B, C, D):
    @functools.lru_cache(None)
    def dp(N):
        if N<=0:
            return float('inf')
        if N == 1:
            return 0
        ans = (N-1)*D
        # BY TWO
        mod_2 = N % 2
        if not mod_2:
            ans = min(ans, dp(N//2)+A)
        else:
            ans =min(ans, dp((N+(2-mod_2))//2)+(A+D*(2-mod_2)))
            ans = min(dp((N-mod_2)//2)+(A+D*mod_2), ans)
        mod_3 = N % 3
        if not mod_3:
            ans = min(ans, dp(N//3)+B)
        else:
            ans =min(ans, dp((N+(3-mod_3))//3)+(B+D*(3-mod_3)))
            ans = min(dp((N-mod_3)//3)+(B+D*mod_3), ans)
        mod_5 = N % 5
        if not mod_5:
            ans = min(ans, dp(N//5)+C)
        else:
            ans =min(ans, dp((N+(5-mod_5))//5)+(C+D*(5-mod_5)))
            ans = min(dp((N-mod_5)//5)+(C+D*mod_5), ans)
        return ans

    return dp(N)+D
