import math
def closest(div, goal):
  div1 = goal - goal % div
  div2 = goal + (div - goal % div)
  if div1 == div2:
   return div1, div1+div, div1-div
  else:
    return div1, div2, div2
def process(closest, multi, highCP):
  close = closest/multi
  log = math.log(highCP, close)
  if log % 1 ==0:
    return math.log(highCP, close)
  else:
    return False
