import heapq


def solve():
  N, A, B, C, D = map(int, input().split())
  min_cost = 1e+18
  seen_value = set()
  queue = []
  heapq.heappush(queue, (0, N))

  while True:
    if len(queue) == 0:
      print(min_cost)
      return

    c, n = heapq.heappop(queue)

    if n in seen_value:
      continue

    seen_value.add(n)

    if n < 1e+9:
      min_cost = min(c + D * n, min_cost)

    if n < 2:
      continue

    m2 = n % 2

    if m2 == 0:
      heapq.heappush(queue, (c + A, n // 2))
    else:
      heapq.heappush(queue, (c + A + D, (n - 1) // 2))

    if n < 3:
      continue

    m3 = n % 3

    if m3 == 0:
      heapq.heappush(queue, (c + B, n // 3))
    elif m3 == 1:
      heapq.heappush(queue, (c + B + D * 1, (n - 1) // 3))
    else:
      heapq.heappush(queue, (c + B + D * 2, (n - 2) // 3))

    if n < 5:
      continue

    m5 = n % 5

    if m5 == 0:
      heapq.heappush(queue, (c + C, n // 5))
    elif m5 == 1:
      heapq.heappush(queue, (c + C + D * 1, (n - 1) // 5))
    elif m5 == 2:
      heapq.heappush(queue, (c + C + D * 2, (n - 2) // 5))
    elif m5 == 3:
      heapq.heappush(queue, (c + C + D * 3, (n - 3) // 5))
    else:
      heapq.heappush(queue, (c + C + D * 4, (n - 4) // 5))


