class Cost_Table:
    def __init__(self, table=None):
        self.table = table if (table is not None) else {}
    def update(self, num, cost):
        if num in self.table:
            if cost < self.table[num]:
                self.table[num] = cost
                return True
            else:
                return False
        else:
            self.table[num] = cost
            return True
    def get_cost(self, num):
        return self.table[num]

