def dfs(N, A, B, C, D, memo):
    if (N in memo):
        return memo[N]

    if (N == 0):
        return 0

    if (N == 1):
        return D

    ans = N * D
    if (N % 2 == 0):
        ans = min(ans, dfs(N // 2, A, B, C, D, memo) + A)
    else:
        rem = N % 2
        ans = min(ans, dfs((N - rem) // 2, A, B, C, D, memo) + A + rem * D)
        ans = min(ans, dfs((N + 2 - rem) // 2, A, B, C, D, memo) + A + (2 - rem) * D)

    if (N % 3 == 0):
        ans = min(ans, dfs(N // 3, A, B, C, D, memo) + B)
    else:
        rem = N % 3
        ans = min(ans, dfs((N - rem) // 3, A, B, C, D, memo) + B + rem * D)
        ans = min(ans, dfs((N + 3 - rem) // 3, A, B, C, D, memo) + B + (3 - rem) * D)

    if (N % 5 == 0):
        ans = min(ans, dfs(N // 5, A, B, C, D, memo) + C)
    else:
