    else:
        memo[n] = min(dp((n+1)//2),dp((n-1)//2))+A+D
    if n%3==0:
        memo[n] = min(memo[n],dp(n//3)+B)
    elif n%3==1:
        memo[n] = min(memo[n],dp((n-1)//3)+B+D,dp((n+2)//3)+B+2*D)
    elif n%3==2:
        memo[n] = min(memo[n],dp((n+1)//3)+B+D,dp((n-2)//3)+B+2*D)
    if n%5==0:
        memo[n] = min(memo[n],dp(n//5)+C)
    elif n%5==1:
        memo[n] = min(memo[n],dp((n-1)//5)+C+D,dp((n+4)//5)+C+4*D)
    elif n%5==2:
        memo[n] = min(memo[n],dp((n-2)//5)+C+2*D,dp((n+3)//5)+C+3*D)
    elif n%5==3:
        memo[n] = min(memo[n],dp((n+2)//5)+C+2*D,dp((n-3)//5)+C+3*D)
    elif n%5==4:
        memo[n] = min(memo[n],dp((n+1)//5)+C+D,dp((n-4)//5)+C+4*D)
