def get_simple_price(n, p, d, m):
    price = 0
    while n != 0:
        mod = n % m
        if mod != 0:
            price += mod * d
            n -= mod
        if n != 0:
            price += p
            n //= m
    return price


def discover(n, a, b, c, d):
    # make limit
    limit = min(
        get_simple_price(n, a, d, 2),
        get_simple_price(n, b, d, 3),
        get_simple_price(n, c, d, 5),
        n * d,
    )
    memo = {}

    queue = deque([(n, 0)])
    while len(queue) > 0:
        t, p = queue.pop()
        if t == 0:
            if p < limit:
                limit = p
            continue
        if t == 1:
            queue.append((0, p + d))
            continue
        if t in memo:
            if p < memo[t]:
                memo[t] = p
            else:
                continue
        else:
            memo[t] = p

        queue.append((0, p + t * d))
        mod = t % 2
        queue.append((t // 2, p + a + d * mod))
        if mod != 0:
            queue.append((t // 2 + 1, p + a + d * (2 - mod)))
        mod = t % 3
        queue.append((t // 3, p + b + d * mod))
        if mod != 0:
            queue.append((t // 3 + 1, p + b + d * (3 - mod)))
        mod = t % 5
        queue.append((t // 5, p + c + d * mod))
        if mod != 0:
            queue.append((t // 5 + 1, p + c + d * (5 - mod)))

    return limit


