import math, collections, heapq
T = int(input())


def solve(N, A, B, C, D):
    dp = collections.defaultdict(lambda: float('inf'))
    dp[0] = 0
    dp[1] = D

    def calc(x):
        if x in dp:
            return dp[x]
        cand = []
        q, r = divmod(x, 2)
        if r == 1:
            cand += [calc(x // 2) + min(A + D, D * (x - x // 2))]
            cand += [calc(x // 2 + 1) + min(A + D, D * (x - x // 2 - 1))]
        else:
            cand += [calc(x // 2) + min(A, D * (x - x // 2))]
        q, r = divmod(x, 3)
        if r < 2:
            cand += [calc(x // 3) + min(B + D * r, D * (x - x // 3))]
        else:
            cand += [calc(x // 3 + 1) + min(B + D, D * (x - x // 3 - 1))]
        q, r = divmod(x, 5)
        if r < 3:
            cand += [calc(x // 5) + min(C + D * r, D * (x - x // 5))]
        else:
            cand += [
                calc(x // 5 + 1) + min(C + D * (5 - r), D * (x - x // 5 - 1))
            ]
        dp[x] = min(cand)
        return dp[x]

    print(calc(N))


