    ans = D * N
    for i in range(61):
        for j in range(39):
            for k in range(27):
                multi_num = (2 ** i) * (3 ** j) * (5 ** k)
                if multi_num > 2 * N:
                    break

                bef_D_num, af_D_num = divmod(N,  multi_num)
                if N % multi_num > multi_num // 2:
                    bef_D_num += 1
                    af_D_num = multi_num - af_D_num
                temp_ans = D * (bef_D_num + af_D_num) + A * i + B * j + C * k
                ans = min(ans, temp_ans)
    return ans

