        return memo[n]

    res = setting[1]*n
    for k in [2,3,5]:
        if n%k == 0:
            res = min(res, execute(n//k, memo, setting) + setting[k])
        else:            
            down = (n//k)*k
            res = min(res, execute(down//k, memo, setting) + setting[k] + (n-down)*setting[1])
            up = (n//k)*k+k
            res = min(res, execute(up//k, memo, setting) + setting[k] + (up-n)*setting[1])

    memo[n] = res
