import numpy as np
import heapq
heap = []

def put(num):
    heapq.heappush(heap, -num)

def pop():
    return heapq.heappop(heap)*(-1)

def empty():
    return (len(heap) == 0)

def register(num, cost):
    if num in d:
        if cost > d[num]:
            return False
    d[num] = cost
    return True

def register_multi(nums, costs):
    res = []
    for num, cost in zip(nums, costs):
        if register(num, cost):
            res += [num]
    return res

