def get(target,cost_one,cost_two,cost_three,cost_five):
  dp = [float("inf") for _ in range(target+1000)]
  if target ==1:
    return cost_one
  if target == 0:
    return 0
  dp[1] = cost_one
  dp[2] = min(dp[1]*2,dp[1] + cost_two,dp[1] + cost_three + cost_one,dp[1] + cost_five + 3*cost_one)
  for i in range(3,target + 101):
    minima = float("inf")
    minima = min(minima, dp[1]*i)
    if i%2 == 0:
      minima = min(minima,dp[i//2] + cost_two)
    if i%3 == 0:
      minima = min(minima,dp[i//3] + cost_three)
    if i%5 == 0:
      minima = min(minima,dp[i//5] + cost_five)
    dp[i] = min(minima,dp[i-1] + cost_one)
  for j in range(target+1,target+101):
    dp[target] = min(dp[target],dp[j] + (j-target)*cost_one)
  return dp[target]
