    if len(queue) == 0:
      print(min_cost)
      return

    c, n = heapq.heappop(queue)

    if n >= min_value:
      continue

    if n == 0:
      print(c)
      return

    min_value = n

    if n < 1e+9:
      min_cost = min(c + D * n, min_cost)

