def nasu(N, n):
  if N in DP:
    return n + DP[N]
  if N == 0:
    return n
  if N == 1:
    return n + D
  ans = n + D * N
  a = N % 2
  if a == 0:
    ans = min(ans, nasu(N // 2, n + A))
  else:
    if a > 1:
      ans = min(ans, nasu((N - 1) // 2, n + D + A))
    ans = min(ans, nasu((N + 1) // 2, n + D + A))
  b = N % 3
  if b == 0:
    ans = min(ans, nasu(N // 3, n + B))
  else:
    if N > 2:
      ans = min(ans, nasu((N - b) // 3, n + (b * D) + B)) 
    ans = min(ans, nasu((N + (3 - b)) // 3, n + ((3 - b) * D) + B)) 
  c = N % 5
  if c == 0:
    ans = min(ans, nasu(N // 5, n + C))
  else:
    if N > 4:
      ans = min(ans, nasu((N - c) // 5, n + (c * D) + C))
    ans = min(ans, nasu((N + (5 - c)) // 5, n + ((5 - c) * D) + C)) 

  DP[N] = ans - n
  return ans

