def g(x,p,K,A,B,C,D):
    u=ceil(x/p)
    return f(u,A,B,C,D)+K+abs(x-u*p)*D

def h(x,p,K,A,B,C,D):
    u=floor(x/p)
    return f(u,A,B,C,D)+K+abs(x-u*p)*D

