class PriorityQueue:
    def __init__(self, heap=None):
        '''
        heap ... list
        '''
        self.heap = heap or []
        heapify(self.heap)

    def push(self, item):
        heappush(self.heap, item)

    def pop(self):
        return heappop(self.heap)

    def pushpop(self, item):
        return heappushpop(self.heap, item)

    def __call__(self):
        return self.heap

    def __len__(self):
        return len(self.heap)


def solve(N,A,B,C,D):
    pq = PriorityQueue()
    visited = dict()

    best = 2 ** 63
    pq.push((0, N))

    while len(pq) > 0:
        cost, now = pq.pop()
        if now < 0:
            continue
        if now in visited and visited[now] <= cost:
            continue
        visited[now] = cost

        # debug("cost %lld, now %lld, [%d]\n", cost, now, last);
        if now == 0:
            best = min(best, cost)

        for d in range(-4, 5):
            x = now + d
            c = cost + D*abs(d)
            if x == 0:
                best = min(best, c)
            if x % 5 == 0:
                minc = min(C, D*(x - x//5))
                pq.push((c+minc, x//5))

        for d in range(-2, 3):
            x = now + d
            c = cost + D*abs(d)
            if x == 0:
                best = min(best, c)
            if x % 3 == 0:
                minc = min(B, D*(x - x//3))
                pq.push((c+minc, x//3))

        for d in range(-1, 2):
            x = now + d
            c = cost + D*abs(d)
            if x == 0:
                best = min(best, c)
            if x % 2 == 0:
                minc = min(A, D*(x - x//2))
                pq.push((c+minc, x//2))

    return best

