    ops = ((2, a), (3, b), (5, c))
    dp = {0:0, 1:d, 2:d + min(a, d)}

    def helper(n):
        if n in dp:
            return dp[n]

        m = min(op[1] + min(helper(n//op[0]) + (n-n//op[0]*op[0])*d, 
                helper(-(-n//op[0])) + ((-(-n//op[0]))*op[0]-n)*d) for op in ops)
        m = min(n*d, m)
        dp[n] = m
        return m

    return helper(n)


