    if n % 2 == 1:
        cand.append(dp((n-1) // 2) + A + D)
        cand.append(dp((n+1) // 2) + A + D)
    if n % 3 == 0:
        cand.append(dp(n // 3) + B)
    if n % 3 == 1:
        cand.append(dp((n-1) // 3) + B + D)
        cand.append(dp((n+2) // 3) + B + 2 * D)
    if n % 3 == 2:
        cand.append(dp((n+1) // 3) + B + D)
        if n - 2 != 0:
            cand.append(dp((n-2) // 3) + B + 2 * D)
    if n % 5 == 0:
        cand.append(dp(n // 5) + C)
    if n % 5 == 1:
        cand.append(dp((n-1) // 5) + C + D)
        cand.append(dp((n+4) // 5) + C + 4 * D)
    if n % 5 == 2:
        if n - 2 != 0:
            cand.append(dp((n-2) // 5) + C + 2 * D)
        cand.append(dp((n+3) // 5) + C + 3 * D)
    if n % 5 == 3:
        if n - 3 != 0:
            cand.append(dp((n-3) // 5) + C + 3 * D)
        cand.append(dp((n+2) // 5) + C + 2 * D)
    if n % 5 == 4:
        cand.append(dp((n+1) // 5) + C + D)
        if n - 4 != 0:
            cand.append(dp((n-4) // 5) + C + 4 * D)
    cand.append(D * n)
