            # 3で割り算
            ret = min(ret, f(q) + B)
        elif r == 1:
            # -1して3で割り算
            ret = min(ret, f(q) + B + D)
        else:
            # +1して3で割り算
            ret = min(ret, f(q+1) + B + D)

        q, r = divmod(N, 5)
        if r == 0:
            # 5で割り算
            ret = min(ret, f(q) + C)
        elif r == 1:
            # -1して5で割り算
            ret = min(ret, f(q) + C + D)
        elif r == 2:
            # -2して5で割り算
