def dp(n,A,B,C,D):
    global can3,can2,can5 
    if n>=30:
        return n//30*dp(30,A,B,C,D) + dp(n%30,A,B,C,D)
    if n==0:
        return 0
    if n==1:
        return D
    if n%5==0:
        can5 = dp(n//5,A,B,C,D) + C
    if n%3==0:
        can3 = dp(n//3,A,B,C,D) + B
    if n%2==0:
        can2 = dp(n//2,A,B,C,D) + A     
    return min(can5,can3,can2,dp(n-1,A,B,C,D)+D,dp(n+1,A,B,C,D)+D)

