use proconio::marker::{Bytes, Chars};

#[derive(Copy, Clone, Eq, PartialEq, Debug)]
struct State {
    cost: i64,
    n: i64,
    min_div: i64,
}

impl Ord for State {
    fn cmp(&self, other: &State) -> Ordering {
        other.cost.cmp(&self.cost).then(other.n.cmp(&self.n)) // BinaryHeapはmax-heapなので、costは逆方向に比較する
    }
}
impl PartialOrd for State {
    fn partial_cmp(&self, other: &State) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn f(n: i64, a: i64, b: i64, c: i64, d: i64) -> i64 {
    let mut q: BinaryHeap<State> = BinaryHeap::new();
    q.push(State {
        n: n,
        cost: 0,
        min_div: 2,
    });
    let mut min_cost = 1000000000i64 * 1000;
    let mut last_n = 0;
    let mut last_cost = 0;

    while let Some(State { n, cost, min_div }) = q.pop() {
        if n == 0 {
            min_cost = cost;
            break;
        }
        if n < 0 {
            continue;
        }
        if n == last_n && cost==last_cost {
            continue;
        }
        last_n = n;
        last_cost = cost;

        //println!("{} {} {}", n, cost, min_div);
        {
            let tmp = cost as i128 + n as i128 * d as i128;
            if tmp < min_cost as i128 {
                min_cost = tmp as i64;
                q.push(State {
                    n: 0,
                    cost: tmp as i64,
                    min_div: 6,
                });   
            }
        }

        let mut ff = |n, cost, div| {
            if n % div == 0 {
                q.push(State {
                    n: n / div,
                    cost: cost + if div==2 {a} else if div==3 {b} else {c},
                    min_div: div,
                })
            }
        };

        if min_div <= 2 {
            ff(n, cost, 2);
        }
        if min_div <= 3 {
            ff(n, cost, 3);
        }
        ff(n, cost, 5);

        ff(n + 1, cost + d, 2);
        ff(n - 1, cost + d, 2);
        ff(n + 1, cost + d, 3);
        ff(n - 1, cost + d, 3);
        ff(n + 1, cost + d, 5);
        ff(n - 1, cost + d, 5);

        ff(n + 2, cost + d * 2, 3);
        ff(n - 2, cost + d * 2, 3);
        ff(n + 2, cost + d * 2, 5);
        ff(n - 2, cost + d * 2, 5);

        ff(n + 3, cost + d * 3, 5);
        ff(n - 3, cost + d * 3, 5);

        ff(n + 4, cost + d * 4, 5);
        ff(n - 4, cost + d * 4, 5);
    }
    //while let Some(s) = q.pop() {
    //    println!("{:?}", s);
    //}
    return min_cost;
}

