fn solve(n: i128, a: i128, b: i128, c: i128, d: i128, mem: &mut HashMap<i128, i128>) -> i128 {
    if mem.contains_key(&n) {
        return mem[&n];
    }

    let mut res = n * d;
    res = min(
        res,
        solve((n + 4) / 5, a, b, c, d, mem) + c + (5 - (n % 5)) * d,
    );
    res = min(
        res,
        solve((n + 2) / 3, a, b, c, d, mem) + b + (3 - (n % 3)) * d,
    );
    res = min(
        res,
        solve((n + 1) / 2, a, b, c, d, mem) + a + (2 - (n % 2)) * d,
    );
    if n >= 5 {
        res = min(res, solve(n / 5, a, b, c, d, mem) + c + (n % 5) * d);
    }
    if n >= 3 {
        res = min(res, solve(n / 3, a, b, c, d, mem) + b + (n % 3) * d);
    }
    if n >= 2 {
        res = min(res, solve(n / 2, a, b, c, d, mem) + a + (n % 2) * d);
    }
    mem.insert(n, res);
    mem[&n]
}

