    for &(n, a, b, c, d) in &q {
        let mut ans = std::usize::MAX;
        let mut memo = HashMap::new();
        memo.insert(n, 0usize);
        let mut heap = std::collections::BinaryHeap::new();
        heap.push(Reverse((0usize, n)));
        while let Some(Reverse((x, m))) = heap.pop() {
            if memo.get(&m).map(|&z| z < x).unwrap_or(false) {
                continue;
            }
            ans = std::cmp::min(ans, x.saturating_add(d.saturating_mul(m)));
            for &(k, e) in &[(2, a), (3, b), (5, c)] {
                for &l in &[m / k, m / k + 1] {
                    let y = x.saturating_add(abssub(m, l * k).saturating_mul(d).saturating_add(e));
                    let z = memo.entry(l).or_insert(std::usize::MAX);
                    if *z > y {
                        *z = y;
                        heap.push(Reverse((y, l)));
                    }
                }
            }
        }
        println!("{}", ans);
    }
}

