struct Memoized {
    memo: std::collections::BTreeMap<usize, usize>,
}

impl Memoized {
    fn func(&mut self, x: usize, a: usize, b: usize, c: usize, d: usize) -> usize {
        if let Some(&memo) = self.memo.get(&x) {
            return memo;
        }

        if x <= 1 {
            return d * x;
        }

        let &ans = [
            x.saturating_mul(d),
            self.func(x / 2, a, b, c, d) + x % 2 * d + a,
            self.func((x + 1) / 2, a, b, c, d) + (2 - x % 2) % 2 * d + a,
            self.func(x / 3, a, b, c, d) + x % 3 * d + b,
            self.func((x + 2) / 3, a, b, c, d) + (3 - x % 3) % 3 * d + b,
            self.func(x / 5, a, b, c, d) + x % 5 * d + c,
            self.func((x + 4) / 5, a, b, c, d) + (5 - x % 5) % 5 * d + c,
        ]
        .iter()
        .min()
        .unwrap();
        self.memo.insert(x, ans);
        ans
    }

    fn new() -> Self {
        Self {
            memo: std::collections::BTreeMap::new(),
        }
    }
}

