struct DefaultMap<S, T> {
    data: std::collections::HashMap<S, T>,
    default: T,
}
impl<S: Eq + std::hash::Hash, T> DefaultMap<S, T> {
    fn new(default: T) -> DefaultMap<S, T> {
        DefaultMap {
            data: std::collections::HashMap::new(),
            default: default,
        }
    }
    fn keys(&self) -> std::collections::hash_map::Keys<S, T> {
        self.data.keys()
    }
    fn iter(&self) -> std::collections::hash_map::Iter<S, T> {
        self.data.iter()
    }
    fn len(&self) -> usize {
        self.data.len()
    }
}
impl<S: Eq + std::hash::Hash, T> std::ops::Index<S> for DefaultMap<S, T> {
    type Output = T;
    fn index(&self, key: S) -> &Self::Output {
        if let Some(val) = self.data.get(&key) {
            val
        } else {
            &self.default
        }
    }
}
impl<S: Eq + std::hash::Hash + Clone, T: Clone> std::ops::IndexMut<S> for DefaultMap<S, T> {
    fn index_mut(&mut self, key: S) -> &mut Self::Output {
        self.data.entry(key.clone()).or_insert(self.default.clone());
        self.data.get_mut(&key).unwrap()
    }
}

fn solve(
    n: u128,
    a: u128,
    b: u128,
    c: u128,
    d: u128,
    mut memo: &mut DefaultMap<u128, Option<u128>>,
) -> u128 {
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return d;
    }
    if let Some(ans) = memo[n] {
        return ans;
    }
    let mut ans = n * d;
    ans = min!(
        ans,
        (n - (n / 2) * 2) * d + a + solve(n / 2, a, b, c, d, &mut memo)
    );
    ans = min!(
        ans,
        ((n + 1) / 2 * 2 - n) * d + a + solve((n + 1) / 2, a, b, c, d, &mut memo)
    );
    ans = min!(
        ans,
        (n - (n / 3) * 3) * d + b + solve(n / 3, a, b, c, d, &mut memo)
    );
    ans = min!(
        ans,
        ((n + 2) / 3 * 3 - n) * d + b + solve((n + 2) / 3, a, b, c, d, &mut memo)
    );
    ans = min!(
        ans,
        (n - (n / 5) * 5) * d + c + solve(n / 3, a, b, c, d, &mut memo)
    );
    ans = min!(
        ans,
        ((n + 4) / 5 * 5 - n) * d + c + solve((n + 4) / 5, a, b, c, d, &mut memo)
    );
    memo[n] = Some(ans);
    ans
}

