fn dfs(i: u128, a: u128, b: u128, c: u128, d:u128, memo: &mut HashMap<u128, u128>) -> u128 {
    if i == 1 {
        return d;
    }
    if i == 0 {
        return 0;
    }
    if memo.contains_key(&i) {
        return *memo.get(&i).unwrap();
    }

    let mut min_count = INF;
    if i % 2 == 0 {
        let tmp: u128;
        if a / d <= i / 2 {
            tmp = dfs(i / 2, a, b, c, d, memo) + min(a, i / 2 * d);
        } else {
            tmp = dfs(i / 2, a, b, c, d, memo) + a;
        }
        min_count = min(tmp, min_count);
    } else {
        let tmp = dfs((i + 1) / 2, a, b, c, d, memo) + min(a, (i + 1) / 2 * d) + d;
        min_count = min(tmp, min_count);
        let tmp = dfs((i - 1) / 2, a, b, c, d, memo) + min(a, (i - 1) / 2 * d) + d;
        min_count = min(tmp, min_count);
    }

    if i % 3 == 0 {
        let tmp = dfs(i / 3, a, b, c, d, memo) + min(b, 2 * i / 3 * d);
        min_count = min(tmp, min_count);
    } else if i % 3 == 1 {
        let tmp = dfs((i - 1) / 3, a, b, c, d, memo) + min(b, 2 * (i - 1) / 3 * d) + d;
        min_count = min(tmp, min_count);
        let tmp = dfs((i + 2) / 3, a, b, c, d, memo) + min(b, 2 * (i + 2) / 3 * d) + d * 2;
        min_count = min(tmp, min_count);
    } else {
        let tmp = dfs((i - 2) / 3, a, b, c, d, memo) + min(b, 2 * (i - 2) / 3 * d) + d * 2;
        min_count = min(tmp, min_count);
        let tmp = dfs((i + 1) / 3, a, b, c, d, memo) + min(b, 2 * (i + 1) / 3 * d) + d;
        min_count = min(tmp, min_count);
    }

    if i % 5 == 0 {
        let tmp = dfs(i / 5, a, b, c, d, memo) + min(c, 4 * i / 5 * d);
        min_count = min(tmp, min_count);
    } else if i % 5 == 1 {
        let tmp = dfs((i - 1) / 5, a, b, c, d, memo) + min(c, 4 * (i - 1) / 5 * d) + d;
        min_count = min(tmp, min_count);
        let tmp = dfs((i + 4) / 5, a, b, c, d, memo) + min(c, 4 * (i + 4) / 5 * d) + d * 4;
        min_count = min(tmp, min_count);
    } else if i % 5 == 2 {
        let tmp = dfs((i - 2) / 5, a, b, c, d, memo) + min(c, 4 * (i - 2) / 5 * d) + d * 2;
        min_count = min(tmp, min_count);
        let tmp = dfs((i + 3) / 5, a, b, c, d, memo) + min(c, 4 * (i + 3) / 5 * d) + d * 3;
        min_count = min(tmp, min_count);
    } else if i % 5 == 3 {
        let tmp = dfs((i - 3) / 5, a, b, c, d, memo) + min(c, 4 * (i - 3) / 5 * d) + d * 3;
        min_count = min(tmp, min_count);
        let tmp = dfs((i + 2) / 5, a, b, c, d, memo) + min(c, 4 * (i + 2) / 5 * d) + d * 2;
        min_count = min(tmp, min_count);
    } else {
        let tmp = dfs((i - 4) / 5, a, b, c, d, memo) + min(c, 4 * (i - 4) / 5 * d) + d * 4;
        min_count = min(tmp, min_count);
        let tmp = dfs((i + 1) / 5, a, b, c, d, memo) + min(c, 4 * (i + 1) / 5 * d) + d;
        min_count = min(tmp, min_count);
    }
    memo.insert(i, min_count);

    min_count
}

