fn solve(n: i64, a: i64, b: i64, c: i64, d: i64) -> i64 {
    let mut dist = BTreeMap::new();
    dist.insert(n, 0);
    let mut heap = BinaryHeap::new();
    heap.push((Reverse(0), n));

    while let Some((Reverse(cost), x)) = heap.pop() {
        let mut candidates = vec![];

        let x1 = (x + 1) / 2 * 2;
        let next_cost = (x - x1).abs() * d + a;
        let next_x = (x + 1) / 2;
        candidates.push((next_x, next_cost));

        let x2 = x / 2 * 2;
        let next_cost = (x - x2).abs() * d + a;
        let next_x = x / 2;
        candidates.push((next_x, next_cost));

        let x1 = (x + 2) / 3 * 3;
        let next_cost = (x - x1).abs() * d + b;
        let next_x = x1 / 3;
        candidates.push((next_x, next_cost));

        let x1 = x / 3 * 3;
        let next_cost = (x - x1).abs() * d + b;
        let next_x = x1 / 3;
        candidates.push((next_x, next_cost));

        let x1 = (x + 4) / 5 * 5;
        let next_cost = (x - x1).abs() * d + c;
        let next_x = x1 / 5;
        candidates.push((next_x, next_cost));

        let x1 = x / 5 * 5;
        let next_cost = (x - x1).abs() * d + c;
        let next_x = x1 / 5;
        candidates.push((next_x, next_cost));
        for (next_x, next_cost) in candidates.into_iter() {
            if next_x == 0 {
                continue;
            }

            let cur = dist.entry(next_x).or_insert(INF);
            if *cur > next_cost + cost {
                *cur = next_cost + cost;
                heap.push((Reverse(next_cost + cost), next_x));
            }
        }

        if x < INF / d {
            let cur = dist.entry(0).or_insert(INF);
            if *cur > x * d + cost {
                *cur = x * d + cost;
            }
        }
    }

    dist[&0]
}

