fn dfs(dp: &mut HashMap<i64, i64>, x: i64, a: i64, b: i64, c: i64, d: i64) -> i64 {
    if dp.contains_key(&x) {
        dp[&x]
    } else {
        let mut res = x.saturating_mul(d);
        res = min(res, dfs(dp, x / 2, a, b, c, d) + a + x % 2 * d);
        if x % 2 != 0 {
            res = min(res, dfs(dp, x / 2 + 1, a, b, c, d) + a + d);
        }
        res = min(res, dfs(dp, x / 3, a, b, c, d) + b + x % 3 * d);
        if x % 3 != 0 {
            res = min(res, dfs(dp, x / 3 + 1, a, b, c, d) + b + (3 - x % 3) * d);
        }
        res = min(res, dfs(dp, x / 5, a, b, c, d) + c + x % 5 * d);
        if x % 5 != 0 {
            res = min(res, dfs(dp, x / 5 + 1, a, b, c, d) + c + (5 - x % 5) * d);
        }
        dp.insert(x, res);
        res
    }
}

