                let y = (x / 5) * 5;
                res = min(res, self.solve(y / 5) + self.c + (x - y) * self.d);
                res = min(res, self.solve(y / 5 + 1) + self.c + (y + 5 - x) * self.d);
            }
            self.memo.insert(x, res);
            res
        }
    }
}

