#[allow(unused_macros)]
macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

#[allow(unused_macros)]
macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: ty),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, t: usize);
    for _ in 0..t {
        parse!(it, n: usize, a: usize, b: usize, c: usize, d: usize);
        let mut q = std::collections::VecDeque::new();
        q.push_back((n, 0));
        let mut ret = std::usize::MAX;
        let mut seen = std::collections::HashMap::new();
        seen.insert(n, 0);
        if n == 1 {
            ret = d;
        }
        while let Some((x, s)) = q.pop_front() {
            let (p, flag0) = d.overflowing_mul(x);
            let (p, flag1) = p.overflowing_add(s);
            if !(flag0 || flag1) {
                ret = min(ret, p);
            };
            if x == 1 || x == 0 {
                if x == 0 {
                    ret = min(ret, s);
                }
                continue;
            }

            let y = match x % 2 {
                0 => (x / 2, s + a),
                1 => ((x - 1) / 2, s + a + d),
                _ => unreachable!(),
            };
            if let Some(v) = seen.get(&y.0) {
                if *v > y.1 {
                    seen.insert(y.0, y.1);
                    q.push_back(y);
                }
            } else {
                seen.insert(y.0, y.1);
                q.push_back(y);
            }

            if x % 2 == 1 {
                let y = ((x + 1) / 2, s + a + d);
                if let Some(v) = seen.get(&y.0) {
                    if *v > y.1 {
                        seen.insert(y.0, y.1);
                        q.push_back(y);
                    }
                } else {
                    seen.insert(y.0, y.1);
                    q.push_back(y);
                }
            }

            let y = match x % 3 {
                0 => (x / 3, s + b),
                1 => ((x - 1) / 3, s + b + d),
                2 => ((x + 1) / 3, s + b + d),
                _ => unreachable!(),
            };
            if let Some(v) = seen.get(&y.0) {
                if *v > y.1 {
                    seen.insert(y.0, y.1);
                    q.push_back(y);
                }
            } else {
                seen.insert(y.0, y.1);
                q.push_back(y);
            }
            let y = match x % 5 {
                0 => (x / 5, s + c),
                1 => ((x - 1) / 5, s + c + d),
                2 => ((x - 2) / 5, s + c + 2 * d),
                3 => ((x + 2) / 5, s + c + 2 * d),
                4 => ((x + 1) / 5, s + c + d),
                _ => unreachable!(),
            };
            if let Some(v) = seen.get(&y.0) {
                if *v > y.1 {
                    seen.insert(y.0, y.1);
                    q.push_back(y);
                }
            } else {
                seen.insert(y.0, y.1);
                q.push_back(y);
            }
        }
        println!("{}", ret);
    }
}

