use std::collections::HashMap;
struct global {
    memo: std::collections::HashMap<u64, u64>,
}

impl global {
    fn solve(&mut self, n: u64, a: u64, b: u64, c: u64, d: u64) -> u64 {
        if let Some(&v) = self.memo.get(&n) {
            return v;
        }

        if n <= 1 {
            return d * n;
        }

        let &ans = [
            n.saturating_mul(d),
            self.solve(n / 2, a, b, c, d) + n % 2 * d + a,
            self.solve((n + 1) / 2, a, b, c, d) + (2 - n % 2) % 2 * d + a,
            self.solve(n / 3, a, b, c, d) + n % 3 * d + b,
            self.solve((n + 2) / 3, a, b, c, d) + (3 - n % 3) % 3 * d + b,
            self.solve(n / 5, a, b, c, d) + n % 5 * d + c,
            self.solve((n + 4) / 5, a, b, c, d) + (5 - n % 5) % 5 * d + c,
        ]
        .iter()
        .min()
        .unwrap();
        self.memo.insert(n, ans);
        return ans;
    }
}

