fn solve() {
    let stdin = io::stdin();
    let mut kin = KInput::new(stdin.lock());
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    macro_rules! output { ($($args:expr),+) => { write!(&mut out, $($args),+).unwrap(); }; }
    macro_rules! outputln {
        ($($args:expr),+) => { output!($($args),+); outputln!(); };
        () => { output!("\n"); if cfg!(debug_assertions) { out.flush().unwrap(); } }
    }

    let t: usize = kin.input();
    for _ in 0..t {
        let (n, a, b, c, d): (i64, i64, i64, i64, i64) = kin.input();
        let mut memo = BTreeMap::new();
        outputln!("{}", f(n, a, b, c, d, &mut memo));
        kdbg!(memo.len());
    }
}

fn f(n: i64, a: i64, b: i64, c: i64, d: i64, memo: &mut BTreeMap<i64, i64>) -> i64 {
    if n == 0 {
        return 0;
    }
    if let Some(&v) = memo.get(&n) {
        return v;
    }
    let mut v = n.saturating_mul(d);
    v = v.min(a + d * (n % 2) + f(n / 2, a, b, c, d, memo));
    if n > 2 {
        v = v.min(a + d * (2 - n % 2) + f((n + 2 - 1) / 2, a, b, c, d, memo));
    }
    v = v.min(b + d * (n % 3) + f(n / 3, a, b, c, d, memo));
    if n > 3 {
        v = v.min(b + d * (3 - n % 3) + f((n + 3 - 1) / 3, a, b, c, d, memo));
    }
    v = v.min(c + d * (n % 5) + f(n / 5, a, b, c, d, memo));
    if n > 5 {
        v = v.min(c + d * (5 - n % 5) + f((n + 5 - 1) / 5, a, b, c, d, memo));
    }
    memo.insert(n, v);
    v
}

