use std::collections::VecDeque;
use std::io::{self, Write};
use std::str::FromStr;

struct Scanner {
    stdin: io::Stdin,
    buffer: VecDeque<String>,
}
impl Scanner {
    fn new() -> Self {
        Scanner {
            stdin: io::stdin(),
            buffer: VecDeque::new(),
        }
    }
    fn cin<T: FromStr>(&mut self) -> T {
        while self.buffer.is_empty() {
            let mut line = String::new();
            let _ = self.stdin.read_line(&mut line);
            for w in line.split_whitespace() {
                self.buffer.push_back(String::from(w));
            }
        }
        self.buffer.pop_front().unwrap().parse::<T>().ok().unwrap()
    }
    fn chars(&mut self) -> Vec<char> {
        self.cin::<String>().chars().collect()
    }
    fn vec<T: FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.cin()).collect()
    }
}

use std::cmp::min;
use std::collections::HashMap;
use std::io::*;

fn rec(x: u128, a: u128, b: u128, c: u128, d: u128, map: &mut HashMap<u128, u128>) -> u128 {
    if let Some(val) = map.get(&x) {
        return *val;
    } else {
        let mut res = x * d;
        res = min(res, rec(x / 2, a, b, c, d, map) + a + x % 2 * d);
        if x % 2 != 0 {
            res = min(res, rec(x / 2 + 1, a, b, c, d, map) + a + (2 - x % 2) * d);
        }
        res = min(res, rec(x / 3, a, b, c, d, map) + b + x % 3 * d);
        if x % 3 != 0 {
            res = min(res, rec(x / 3 + 1, a, b, c, d, map) + b + (3 - x % 3) * d);
        }
        res = min(res, rec(x / 5, a, b, c, d, map) + c + x % 5 * d);
        if x % 5 != 0 {
            res = min(res, rec(x / 5 + 1, a, b, c, d, map) + c + (5 - x % 5) * d);
        }
        map.insert(x, res);
        res
    }
}

fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let t: usize = itr.next().unwrap().parse().unwrap();
    let mut out = Vec::new();
    for _ in 0..t {
        let n: u128 = itr.next().unwrap().parse().unwrap();
        let a: u128 = itr.next().unwrap().parse().unwrap();
        let b: u128 = itr.next().unwrap().parse().unwrap();
        let c: u128 = itr.next().unwrap().parse().unwrap();
        let d: u128 = itr.next().unwrap().parse().unwrap();

        let mut map = HashMap::new();
        map.insert(0, 0);
        map.insert(1, d);
        writeln!(out, "{}", rec(n, a, b, c, d, &mut map)).ok();
    }
    stdout().write_all(&out).unwrap();
}

