use std::collections::HashMap;

struct Node {
    v: u64,
    cost: u64
}

fn solve(n: u64, one_cost: u64, costs: &[u64]) -> u64 {
    let mut queue = min_heap_by_key(|node: &Node| node.cost);
    let mut ds = HashMap::new();
    queue.push(Node { v: n, cost: 0 });
    ds.insert(n, 0);
    loop {
        let node = queue.pop().unwrap();
        if node.v == 0 {
            return node.cost;
        }
        if *ds.get(&node.v).unwrap() > node.cost {
            continue;
        }
        //dbg!((node.v, node.cost));
        let mut nexts = Vec::new();
        if let Some(cost) = node.v.checked_mul(one_cost) {
            nexts.push(Node { v: 0, cost: node.cost + cost });
        }
        if node.v >= 2 {
            if node.v % 2 == 0 {
                nexts.push(Node { v: node.v/2, cost: node.cost + costs[0] });
            } else {
                nexts.push(Node { v: node.v/2, cost: node.cost + one_cost + costs[0] });
                nexts.push(Node { v: node.v/2+1, cost: node.cost + one_cost + costs[0] });
            }
        }
        if node.v >= 3 {
            let rem = node.v % 3;
            if rem < 3-rem {
                nexts.push(Node { v: node.v/3, cost: node.cost + one_cost*rem + costs[1] });
            } else {
                nexts.push(Node { v: node.v/3+1, cost: node.cost + one_cost*(3-rem) + costs[1] });
            }
        }
        if node.v >= 5 {
            let rem = node.v % 5;
            if rem < 5-rem {
                nexts.push(Node { v: node.v/5, cost: node.cost + one_cost*rem + costs[2] });
            } else {
                nexts.push(Node { v: node.v/5+1, cost: node.cost + one_cost*(5-rem) + costs[2] });
            }
        }
        for next in nexts {
            if ds.get(&next.v).map_or(false, |&cost| cost <= next.cost ) {
                continue;
            }
            ds.insert(next.v, next.cost);
            queue.push(next);
        }
        //dbg!(&ds);
    }
}

fn main() {
    read!();
    for (n, mut costs) in read_lines::<(u64, Vec<u64>)>() {
        let one_cost = costs.pop().unwrap();
        println!("{}", solve(n, one_cost, &costs));
    }
}

