struct G {
    n: i64,
    a: i64,
    b: i64,
    c: i64,
    d: i64,
}
fn solve(n: i64, a: i64, b: i64, c: i64, d: i64) -> i64 {
    if n == 0 {
        return 0;
    }
    let mut ret = INF;
    if n % 3 == 0 {
        ret = min(ret, solve(n / 3, a, b, c, d) + b);
    } else if n % 5 == 0 {
        ret = min(ret, solve(n / 5, a, b, c, d) + c);
    } else if n % 2 == 0 {
        ret = min(ret, solve(n / 2, a, b, c, d) + a);
    } else {
        ret = min(n * d, solve(n - 1, a, b, c, d) + d);
    }
    ret
}
