const INF: i64 = 4e18 as i64;

fn solve(n: i64, a: i64, b: i64, c: i64, d: i64, memo: &mut HashMap<i64, i64>) -> i64 {
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return d;
    }
    if memo.contains_key(&n) {
        return *memo.get(&n).unwrap();
    }
    let mut best = ifv!(n >= INF / d, INF, n * d);
    best = min(best, solve(n/2, a, b, c, d, memo) + a + d * (n % 2));
    best = min(best, solve((n+1)/2, a, b, c, d, memo) + a + d * (n % 2));
    best = min(best, solve(n/3, a, b, c, d, memo) + b + d * (n % 3));
    best = min(best, solve((n+2)/3, a, b, c, d, memo) + b + d * ((3 - n % 3) % 3));
    best = min(best, solve(n/5, a, b, c, d, memo) + c + d * (n % 5));
    best = min(best, solve((n+4)/5, a, b, c, d, memo) + c + d * ((5 - n % 5) % 5));
    memo.insert(n, best);
    best
}

fn main() {
    input! {
        n: usize,
        testcases: [(i64, i64, i64, i64, i64); n]
    };
    for (n, a, b, c, d) in testcases {
        println!("{}", solve(n, a, b, c, d, &mut HashMap::new()));
    }
}

