use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};

use proconio::input;

fn solve(target: i64, a: u128, b: u128, c: u128, d: u128) {
    let mut heap = BinaryHeap::new();
    let mut best = HashMap::new();
    heap.push((Reverse(0), target));
    best.insert(target, 0);

    fn push(
        heap: &mut BinaryHeap<(Reverse<u128>, i64)>,
        best: &mut HashMap<i64, u128>,
        m: i64,
        cost: u128,
    ) {
        let now_best = best.entry(m).or_insert(std::u128::MAX);
        if cost < *now_best {
            *now_best = cost;
            heap.push((Reverse(cost), m));
        }
    }

    while let Some((Reverse(cost), n)) = heap.pop() {
        if n == 0 {
            println!("{}", cost);
            return;
        }
        if n < 0 {
            continue;
        }
        if n % 2 == 0 {
            let m = n / 2;
            let cost = cost + a.min(m as u128 * d);
            push(&mut heap, &mut best, m, cost);
        } else {
            push(&mut heap, &mut best, n - 1, cost + d);
            push(&mut heap, &mut best, n + 1, cost + d);
        }
        if n % 3 == 0 {
            let m = n / 3;
            let cost = cost + b.min((m * 2) as u128 * d);
            push(&mut heap, &mut best, m, cost);
        } else if n % 3 == 1 {
            push(&mut heap, &mut best, n - 1, cost + d);
            push(&mut heap, &mut best, n + 2, cost + d * 2);
        } else {
            push(&mut heap, &mut best, n - 2, cost + d * 2);
            push(&mut heap, &mut best, n + 1, cost + d);
        }
        if n % 5 == 0 {
            let m = n / 5;
            let cost = cost + c.min((m * 4) as u128 * d);
            push(&mut heap, &mut best, m, cost);
        } else if n % 5 == 1 {
            push(&mut heap, &mut best, n - 1, cost + d);
            push(&mut heap, &mut best, n + 4, cost + d * 4);
        } else if n % 5 == 2 {
            push(&mut heap, &mut best, n - 2, cost + d * 2);
            push(&mut heap, &mut best, n + 3, cost + d * 3);
        } else if n % 5 == 3 {
            push(&mut heap, &mut best, n - 3, cost + d * 3);
            push(&mut heap, &mut best, n + 2, cost + d * 2);
        } else {
            push(&mut heap, &mut best, n - 4, cost + d * 4);
            push(&mut heap, &mut best, n + 1, cost + d);
        }
    }
}

fn main() {
    input! {
        t: u64,
        cases: [(i64, u128, u128, u128, u128); t],
    };

    for case in cases {
        solve(case.0, case.1, case.2, case.3, case.4);
    }
}

