fn solve(n: u64, a: u64, b: u64, c: u64, d: u64) {
    let mut mem: HashMap<u64, u64> = HashMap::new();

    let mut q: BinaryHeap<Reverse<(u64, u64)>> = BinaryHeap::new();
    q.push(Reverse((n, 0)));

    while let Some(Reverse((k, v))) = q.pop() {
        let &bef = mem.get(&k).unwrap_or(&std::u64::MAX);
        if bef <= v {
            continue;
        }
        mem.insert(k, v);

        if k == 0 {
            continue;
        }

        //A
        if k % 2 == 0 {
            if a / d < k / 2 {
                q.push(Reverse((k / 2, v + a)));
            } else {
                q.push(Reverse((k / 2, v + k / 2 * d)));
            }
        } else {
            let plus = 2 - (k % 2);
            let plus_diff = (k + plus) / 2;
            if a / d < plus_diff {
                q.push(Reverse((k + plus - plus_diff, v + d * plus + a)));
            } else {
                q.push(Reverse((
                    k + plus - plus_diff,
                    v + d * plus + d * plus_diff,
                )));
            }

            let minus = k % 2;
            let minus_diff = (k - minus) / 2;
            if a / d < minus_diff {
                q.push(Reverse((k - minus - minus_diff, v + d * minus + a)));
            } else {
                q.push(Reverse((
                    k - minus - minus_diff,
                    v + d * minus + d * minus_diff,
                )));
            }
        }

        //B
        if k % 3 == 0 {
            if b / d < k * 2 / 3 {
                q.push(Reverse((k / 3, v + b)));
            } else {
                q.push(Reverse((k / 3, v + k * 2 / 3 * d)));
            }
        } else {
            let plus = 3 - (k % 3);
            let plus_diff = (k + plus) / 3 * 2;
            if b / d < plus_diff {
                q.push(Reverse((k + plus - plus_diff, v + d * plus + b)));
            } else {
                q.push(Reverse((
                    k + plus - plus_diff,
                    v + d * plus + d * plus_diff,
                )));
            }

            let minus = k % 3;
            let minus_diff = (k - minus) / 3 * 2;
            if b / d < minus_diff {
                q.push(Reverse((k - minus - minus_diff, v + d * minus + b)));
            } else {
                q.push(Reverse((
                    k - minus - minus_diff,
                    v + d * minus + d * minus_diff,
                )));
            }
        }

        //C
        if k % 5 == 0 {
            if c / d < k * 4 / 5 {
                q.push(Reverse((k / 5, v + c)));
            } else {
                q.push(Reverse((k / 5, v + k * 4 / 5 * d)));
            }
        } else {
            let plus = 5 - (k % 5);
            let plus_diff = (k + plus) / 5 * 4;
            if c / d < plus_diff {
                q.push(Reverse((k + plus - plus_diff, v + d * plus + c)));
            } else {
                q.push(Reverse((
                    k + plus - plus_diff,
                    v + d * plus + d * plus_diff,
                )));
            }

            let minus = k % 5;
            let minus_diff = (k - minus) / 5 * 4;
            if c / d < minus_diff {
                q.push(Reverse((k - minus - minus_diff, v + d * minus + c)));
            } else {
                q.push(Reverse((
                    k - minus - minus_diff,
                    v + d * minus + d * minus_diff,
                )));
            }
        }
    }

    println!("{}", mem.get(&0).unwrap());
}

