macro_rules !min {($a :expr $(,) *) =>{{$a } } ;($a :expr ,$b :expr $(,) *) =>{{std ::cmp ::min ($a ,$b ) } } ;($a :expr ,$($rest :expr ) ,+$(,) *) =>{{std ::cmp ::min ($a ,min !($($rest ) ,+) ) } } ;}

fn f(
   x: usize,
   a: usize,
   b: usize,
   c: usize,
   d: usize,
   m: &mut std::collections::BTreeMap<usize, usize>,
) -> usize {
   if let Some(&y) = m.get(&x) {
      y
   } else {
      let two = match x % 2 {
         0 => f(x / 2, a, b, c, d, m),
         _ => d + min(f(x / 2, a, b, c, d, m), f(x / 2 + 1, a, b, c, d, m)),
      } + a;
      let three = match x % 3 {
         0 => b + f(x / 3, a, b, c, d, m),
         i => min(
            i * d + f(x / 3, a, b, c, d, m) + if x / 3 == 0 { 0 } else { b },
            (3 - i) * d + f(x / 3 + 1, a, b, c, d, m) + b,
         ),
      };
      let five = match x % 5 {
         0 => c + f(x / 5, a, b, c, d, m),
         i => min(
            i * d + f(x / 5, a, b, c, d, m) + if x / 5 == 0 { 0 } else { c },
            (5 - i) * d + f(x / 5 + 1, a, b, c, d, m) + c,
         ),
      };
      let mut y = min!{two, three, five};
      if x <= y/d {
         y = min(y, d*x);
      }
      m.insert(x, y);
      y
   }
}

