fn dfs(r: usize, a: usize, b: usize, c: usize, d: usize, m: &mut HashMap<usize, usize>) -> usize {
    let mut res = if let Some(t) = r.checked_mul(d){ t } else { usize::MAX };
    if r == 0 { return 0; }
    if r == 1 { return d; }
    if m.contains_key(&r) {
        return *m.get(&r).unwrap();
    }
    res = min(res, dfs(r / 2, a, b, c, d, m) + a + d * (r % 2));
    res = min(res, dfs((r + 1) / 2, a, b, c, d, m) + a + d * (r % 2));
    res = min(res, dfs(r / 3, a, b, c, d, m) + b + d * (r % 3));
    res = min(res, dfs((r + 2) / 3, a, b, c, d, m) + b + d * (3 - r % 3));
    res = min(res, dfs(r / 5, a, b, c, d, m) + c + d * (r % 5));
    res = min(res, dfs((r + 4) / 5, a, b, c, d, m) + c + d * (5 - r % 5));
    m.insert(r, res);
    res
}

