use std::collections::{BinaryHeap,BTreeMap};
use std::cmp::Reverse;
fn main() {
    proconio::input! {
        t: usize,
        nabcd: [(i64,i64,i64,i64,i64);t],
    }
    for (n,a,b,c,d) in nabcd {
        let mut e = BTreeMap::new();
        let mut q = BinaryHeap::new();
        q.push((Reverse(0),n));
        while let Some((Reverse(s),i))=q.pop() {
            if e.contains_key(&i) {continue;}
            e.insert(i, s);
            if i==0 {
                break;
            }
            for (k,v) in &[(2,a),(3,b),(5,c)] {
                let r=i%k;
                let c=r*d+v;
                let j=i/k;
                if c>=d.saturating_mul(i-j) {
                    q.push((Reverse(s+i*d),0));
                }
                else {
                    if !e.contains_key(&j) {
                        q.push((Reverse(s+c),j));
                    }
                    if r>0 {
                        let c=(k-r)*d+v;
                        let j=j+1;
                        if c<d.saturating_mul(i-j) && !e.contains_key(&j) {
                            q.push((Reverse(s+c),j));
                        }
                    }
                }
            }
        }
        println!("{}",e.get(&0).unwrap_or(&-1));
    }
}

fn dfs(
    n: usize,
    a: usize,
    b: usize,
    c: usize,
    d: usize,
    x: usize,
    memo: &mut HashMap<usize, usize>,
) -> usize {
    let mut res = std::usize::MAX;
    if n == 0 {
        return min(res, x);
    } else if n == 1 {
        return min(res, x + d);
    }

    for &p in [(2, a), (3, b), (5, c)].iter().rev() {
        if n >= p.0 {
            let flor = n / p.0;
            res = min(
                dfs(flor, a, b, c, d, x + p.1 + (n - flor * p.0) * d, memo),
                res,
            );
            if n % p.0 != 0 {
                let ceil = n / p.0 + 1;
                res = min(
                    dfs(ceil, a, b, c, d, x + p.1 + (ceil * p.0 - n) * d, memo),
                    res,
                );
            }
        }
    }
    match memo.get_mut(&n) {
        Some(v) => {
            *v = min(res, *v);
        }
        None => {
            memo.insert(n, res);
        }
    };
    res
}

fn solve() {
    let t: usize = read();
    'outer: for i in 0..t {
        let n: usize = read();
        let (a, b): (usize, usize) = (read::<usize>(), read::<usize>());
        let (c, d): (usize, usize) = (read::<usize>(), read::<usize>());
        let mut memo: HashMap<usize, usize> = HashMap::new();
        let mut que = BinaryHeap::new();
        que.push((Reverse(0), Reverse(n)));

        while let Some((Reverse(cost), Reverse(n))) = que.pop() {
            if n == 0 {
                memo.insert(0, cost);
                break;
            } else if n == 1 {
                memo.insert(0, cost + d);
                break;
            }
            match memo.get_mut(&n) {
                Some(v) => {
                    if *v <= cost {
                        continue;
                    } else {
                        *v = cost;
                    }
                }
                None => {
                    memo.insert(n, cost);
                }
            };

            que.push((Reverse(cost.wrapping_add(n.wrapping_mul(d))), Reverse(0)));
            for &p in [(2, a), (3, b), (5, c)].iter().rev() {
                if n >= p.0 {
                    let flor = n / p.0;
                    que.push((Reverse(cost + p.1 + (n - flor * p.0) * d), Reverse(flor)));
                    if n % p.0 != 0 {
                        let ceil = n / p.0 + 1;
                        que.push((Reverse(cost + p.1 + (ceil * p.0 - n) * d), Reverse(ceil)));
                    }
                }
            }
        }
        println!("{}", memo.get(&0).expect("error"));
    }
}

