struct Scanner {
    buff: Vec<String>,
    pos: usize,
}

#[allow(dead_code)]
impl Scanner {
    pub fn new() -> Self {
        Scanner {
            buff: Vec::new(),
            pos: 0,
        }
    }

    pub fn next<T: FromStr>(&mut self) -> T {
        while self.buff.len() <= self.pos {
            self.pos = 0;
            self.buff = read_line().split_whitespace().map(|s| s.to_owned()).collect();
        }

        let result = self.buff[self.pos].parse::<T>();
        self.pos += 1;
        result.ok().unwrap()
    }

    pub fn next_line(&mut self) -> String {
        let result  = read_line().trim().to_owned();
        self.buff.clear();
        self.pos = 0;

        result
    }

    pub fn next_vec<T: FromStr>(&mut self) -> Vec<T> {
        self.buff.clear();
        self.pos = 0;
        read_line().trim().split_whitespace().map(|s| s.parse().ok().unwrap()).collect()
    }

    pub fn next_line_chars(&mut self) -> Vec<char> {
        let result  = read_line().trim().chars().collect();
        self.buff.clear();
        self.pos = 0;

        result
    }
}

fn func(n: u64, a: u64, b: u64, c: u64, d: u64, memo: &mut HashMap<u64, u64>) -> u64 {
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return d;
    }

    if let Some(&v) = memo.get(&n) {
        return v;
    }
    let n2 = n / 2 * 2;
    let n2u = (n+1) / 2 * 2;
    let n3 = n / 3 * 3;
    let n3u = (n+2) / 3 * 3;
    let n5 = n / 5 * 5;
    let n5u = (n+4) / 5 * 5;

    let mut ans = 1_000_000_000_000_000_010;
    if n < ans /d {
        ans = n * d;
    }
    ans = cmp::min(ans, (n - n2) * d + a + func(n2/2, a, b, c, d, memo));
    ans = cmp::min(ans, (n2u - n) * d + a + func(n2u/2, a, b, c, d, memo));
    ans = cmp::min(ans, (n - n3) * d + b + func(n3/3, a, b, c, d, memo));
    ans = cmp::min(ans, (n3u - n) * d + b + func(n3u/3, a, b, c, d, memo));
    ans = cmp::min(ans, (n - n5) * d + c + func(n5/5, a, b, c, d, memo));
    ans = cmp::min(ans, (n5u - n) * d + c + func(n5u/5, a, b, c, d, memo));

    memo.insert(n, ans);

    ans
}


