use itertools::Itertools as _;
use num::pow::{checked_pow, pow};
use proconio::input;
use std::cmp::min;
use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};
use std::i64;
struct Solver {
    cost_one: i64,
    rules: [(i64, i64); 3],
    memo: HashMap<i64, i64>,
}
impl Solver {
    fn new(a: i64, b: i64, c: i64, d: i64) -> Solver {
        Solver {
            cost_one: d,
            rules: [(2, a), (3, b), (5, c)],
            memo: HashMap::new(),
        }
    }
    fn solve(&mut self, n: i64) -> i64 {
        match n {
            0 => return 0,
            1 => return self.cost_one,
            _ => {}
        }
        if let Some(&v) = self.memo.get(&n) {
            return v;
        }
        let mut res = self.cost_one.checked_mul(n).unwrap_or(i64::MAX);
        let rules = self.rules;
        for (mul, cost) in &rules {
            let total = self.solve(n / mul) + cost + (n % mul) * self.cost_one;
            res = min(res, total);
            if n % mul != 0 {
                let total = self.solve(n / mul + 1) + cost + (mul - n % mul) * self.cost_one;
                res = min(res, total);
            }
        }
        self.memo.insert(n, res);
        res
    }
}
fn main() {
    input! { t : usize , }
    for _ in 0..t {
        input! { mut n : i64 , a : i64 , b : i64 , c : i64 , d : i64 , }
        println!("{}", Solver::new(a, b, c, d).solve(n));
    }
}

