use proconio::{input, fastout};
use proconio::marker::*;
use nalgebra::min;
use std::collections::HashMap;

fn dfs(r: usize, a: usize, b: usize, c: usize, d: usize, m: &mut HashMap<usize, usize>) -> usize {
    let mut res = if let Some(k) = r.checked_mul(d){ k } else { std::usize::MAX };
    if r == 0 { return 0; }
    if r == 1 { return d; }
    if m.contains_key(&r) {
        return *m.get(&r).unwrap();
    }
    res = min(res, dfs(r / 2, a, b, c, d, m) + a + d * (r % 2));
    res = min(res, dfs((r + 1) / 2, a, b, c, d, m) + a + d * (r % 2));
    res = min(res, dfs(r / 3, a, b, c, d, m) + b + d * (r % 3));
    res = min(res, dfs((r + 2) / 3, a, b, c, d, m) + b + d * (3 - r % 3));
    res = min(res, dfs(r / 5, a, b, c, d, m) + c + d * (r % 5));
    res = min(res, dfs((r + 4) / 5, a, b, c, d, m) + c + d * (5 - r % 5));
    m.insert(r, res);
    res
}

#[fastout]
fn main() {
    input! {
    t: usize,
    nabcds: [[usize; 5]; t]
    }
    for nabcd in nabcds {
        let mut m = HashMap::new();
        let (r, a, b, c, d) = (nabcd[0], nabcd[1], nabcd[2], nabcd[3], nabcd[4]);
        let ans = dfs(r, a, b, c, d, &mut m);
        println!("{}", ans);
    }
}

use std::cmp::{min, Ordering};
use std::collections::{BinaryHeap, HashSet};

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
    ($($r:tt)*) => {
        let mut s = {
            use std::io::Read;
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).unwrap();
            s
        };
        let mut iter = s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};

    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };

    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };

    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };

    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };

    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

#[derive(Debug, PartialEq, Eq)]
struct Query {
    cost: u64,
    num: u64,
}

impl Ord for Query {
    fn cmp(&self, other: &Self) -> Ordering {
        self.cost.cmp(&other.cost).reverse()
    }
}

impl PartialOrd for Query {
    fn partial_cmp(&self, other: &Query) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn solve(v: Vec<u64>) {
    let (n, a, b, c, d) = (v[0], v[1], v[2], v[3], v[4]);
    let threshold = (1e+20 as u64) / d;

    let mut queue = BinaryHeap::new();
    let mut seens = HashSet::new();

    queue.push(Query { cost: 0, num: n });

    while !queue.is_empty() {
        let q: Query = queue.pop().unwrap();

        if q.num == 0 {
            println!("{}", q.cost);
            return;
        }

        if seens.contains(&q.num) {
            continue;
        }

        seens.insert(q.num);

        if q.num < threshold {
            queue.push(Query {
                num: 0,
                cost: q.cost + q.num * d,
            });
        }

        for [k, v] in [[2, a], [3, b], [5, c]].iter() {
            if q.num < *k {
                break;
            }

            let m = q.num % *k;
            let n = q.num / *k;

            if m == 0 {
                queue.push(Query {
                    num: n,
                    cost: q.cost + *v,
                });
            } else {
                queue.push(Query {
                    num: n,
                    cost: q.cost + *v + (d * m),
                });
                queue.push(Query {
                    num: n + 1,
                    cost: q.cost + *v + (d * (*k - m)),
                });
            }
        }
    }

    panic!("aaa");
}

fn main() {
    input! { n: u64, vs: [[u64; 5]; n] }

    for v in vs {
        solve(v);
    }
}

