fn sat_pow(b: usize, mut n: usize) -> usize {
    let mut res = 1usize;
    let mut mul = b;
    while n > 0 {
        if n & 1 == 1 {
            res = res.saturating_mul(mul);
        }
        mul = mul.saturating_mul(mul);
        n >>= 1;
    }
    res
}

macro_rules ! min { ( $ x : expr ) => ( $ x ) ; ( $ x : expr , $ ( $ z : expr ) ,+ ) => { { std :: cmp :: min ( $ x , min ! ( $ ( $ z ) ,* ) ) } } }

fn main() {
    use core::cmp::Reverse;
    input! {
        t: usize,
    }
    for _ in 0..t {
        input! {
            n: usize,
            a: usize,
            b: usize,
            c: usize,
            d: usize,
        }

        let mut heap = BinaryHeap::new();
        heap.push((Reverse(0), n));
        let mut dist = BTreeMap::new();
        dist.insert(n, 0);
        let neighbors = vec![(2, a), (3, b), (5, c)];
        while let Some((Reverse(cost), val)) = heap.pop() {
            if val == 1 {
                println!("{}", cost + d);
                break;
            }
            for &(base, bcost) in &neighbors {
                if val % base == 0 {
                    let kd = dist.get(&(val / base)).cloned().unwrap_or(std::usize::MAX);
                    let nd = cost.saturating_add(min!(bcost, (val - val / base).saturating_mul(d)));
                    if kd > nd {
                        dist.insert(val / base, nd);
                        heap.push((Reverse(nd), val / base));
                    }
                } else {
                    let v1 = val / base * base;
                    let v2 = v1 + base;
                    let kd = dist.get(&(v1 / base)).cloned().unwrap_or(std::usize::MAX);
                    let nd = cost.saturating_add(
                        min!(bcost, (v1 - v1 / base).saturating_mul(d)) + (val - v1) * d,
                    );
                    if kd > nd {
                        dist.insert(v1 / base, nd);
                        heap.push((Reverse(nd), v1 / base));
                    }
                    let kd = dist.get(&(v2 / base)).cloned().unwrap_or(std::usize::MAX);
                    let nd = cost.saturating_add(
                        min!(bcost, (v2 - v2 / base).saturating_mul(d)) + (v2 - val) * d,
                    );
                    if kd > nd {
                        dist.insert(v2 / base, nd);
                        heap.push((Reverse(nd), v2 / base));
                    }
                }
            }
        }
    }
}

