fn rec(n: usize, abcd: (usize, usize, usize, usize), memo: &mut HashMap<usize, usize>) -> usize {
    let (a, b, c, d) = abcd;
    if n == 0 {
        return 0;
    } else if n == 1 {
        return d;
    }
    if let Some(&res) = memo.get(&n) {
        return res;
    }

    let mut res = Vec::new();
    res.push(rec(n/2, abcd, memo) + d*(n - n/2*2) + a);
    res.push(rec((n+1)/2, abcd, memo) + d*((n+1)/2*2 - n) + a);
    res.push(rec(n/3, abcd, memo) + d*(n - n/3*3) + b);
    res.push(rec((n+2)/3, abcd, memo) + d*((n+2)/3*3 - n) + b);
    res.push(rec(n/5, abcd, memo) + d*(n - n/5*5) + c);
    res.push(rec((n+4)/5, abcd, memo) + d*((n+4)/5*5 - n) + c);
    res.push(n.saturating_mul(d));
    let res = res.into_iter().min().unwrap();
    memo.insert(n, res);
    res
}

