};

use std::collections::HashMap;

fn func(a: u128, b: u128, c: u128, d: u128, k: u128, memo: &mut HashMap<u128, u128>) -> u128 {
   if memo.contains_key(&k) {
      return memo[&k];
   }

   if k == 0 {
      return 0;
   }
   if k == 1 {
      return d;
   }

   let mut cost = k * d;

   cost = std::cmp::min(
      cost,
      (k - (k / 5) * 5) * d + c + func(a, b, c, d, k / 5, memo),
   );
   cost = std::cmp::min(
      cost,
      (k - (k / 3) * 3) * d + b + func(a, b, c, d, k / 3, memo),
   );
   cost = std::cmp::min(
      cost,
      (k - (k / 2) * 2) * d + a + func(a, b, c, d, k / 2, memo),
   );

   cost = std::cmp::min(
      cost,
      (((k + 5 - 1) / 5) * 5 - k) * d + c + func(a, b, c, d, (k + 5 - 1) / 5, memo),
   );
   cost = std::cmp::min(
      cost,
      (((k + 3 - 1) / 3) * 3 - k) * d + b + func(a, b, c, d, (k + 3 - 1) / 3, memo),
   );
   cost = std::cmp::min(
      cost,
      (((k + 2 - 1) / 2) * 2 - k) * d + a + func(a, b, c, d, (k + 2 - 1) / 2, memo),
   );

   memo.insert(k, cost);

   return cost;
}

