        while let Some(Reverse((sum, now))) = heap.pop() {
            if sum > dp[&now] {
                continue;
            }
            if now < (1e+18 as i64) / d {
                let zero = dp.entry(0).or_insert(std::i64::MAX);
                *zero = std::cmp::min(*zero, sum + d * now);
            }
            if now > 1 {
                for &(div, cost) in divs.iter() {
                    let (next_floor, next_ceil) = (now / div, (now + div - 1) / div);
                    for &next in [next_ceil, next_floor].iter() {
                        let next_ref = dp.entry(next).or_insert(std::i64::MAX);
                        let next_cost = sum + cost + (now - next * div).abs() * d;
                        if next_cost < *next_ref {
                            *next_ref = next_cost;
                            heap.push(Reverse((next_cost, next)));
                        }
                    }
                }
            }
        }
        println!("{}", dp[&0]);
    }
}

