impl PartialOrd for Query {
    fn partial_cmp(&self, other: &Query) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn solve() {
    input! {n:u64, a:u64, b:u64, c:u64, d:u64};
    let mut queue = BinaryHeap::new();
    let mut seens = HashSet::new();
    let threshold = 1e+20 as u64 / d;

    queue.push(Query { num: n, cost: 0 });

    while !queue.is_empty() {
        let query = queue.pop().unwrap();

        if query.num == 0 {
            println!("{}", query.cost);
            return;
        }

        if seens.contains(&query.num) {
            continue;
        }

        seens.insert(query.num);

        if query.num <= threshold {
            queue.push(Query {
                num: 0,
                cost: query.cost + query.num * d,
            })
        }

        for [k, p] in [[2, a], [3, b], [5, c]].iter() {
            if query.num < *k {
                continue;
            }

            let dval = query.num / *k;
            let mval = query.num % *k;

            if mval == 0 {
                queue.push(Query {
                    num: dval,
                    cost: query.cost + p,
                });
            } else {
                queue.push(Query {
                    num: dval,
                    cost: query.cost + p + d * mval,
                });
                queue.push(Query {
                    num: dval + 1,
                    cost: query.cost + p + d * (*k - mval),
                });
            }
        }
    }

