    }

    for (n, a, b, c, d) in nabcd {
        let mut kouho = vec![n * d];
        for i in 0..=64 {
            for j in 0..=64 {
                for k in 0..=64 {
                    let pow_a = match 2i128.checked_pow(i) {
                        Some(x) => x,
                        None => break,
                    };

                    let pow_b = match 3i128.checked_pow(j) {
                        Some(x) => x,
                        None => break,
                    };

                    let pow_c = match 5i128.checked_pow(k) {
                        Some(x) => x,
                        None => break,
                    };

                    let sum = match pow_a
                        .checked_mul(pow_b)
                        .map(|x| x.checked_mul(pow_c))
                        .flatten()
                    {
                        Some(x) => x,
                        None => break,
                    };

                    if n <= sum && sum <= n * 5 {
                        let coins = a * i as i128 + b * j as i128 + c * k as i128 + d;
                        kouho.push(coins + (sum - n).abs() * d);
                        if sum % 2 == 0 {
                            kouho.push(coins - 1 + (n - (sum / 2)).abs() * d);
                        }
                        if sum % 3 == 0 {
                            kouho.push(coins - 1 + (n - (sum / 3)).abs() * d);
                        }
                        if sum % 4 == 0 {
                            kouho.push(coins - 1 + (n - (sum / 4)).abs() * d);
                        }
                        if sum % 5 == 0 {
                            kouho.push(coins - 1 + (n - (sum / 5)).abs() * d);
                        }
                    }
                }
            }
        }

        println!("{}", kouho.iter().min().unwrap());
