fn main() {
    input! {//
        t:usize,
        mut nabcd:[(i128,i128,i128,i128,i128);t]
    }
    for &(n, a, b, c, d) in nabcd.iter() {
        let mut g = G {
            n: n,
            a: a,
            b: b,
            c: c,
            d: d,
            dp: HashMap::new(),
        };
        println!("{}", g.solve(n));
    }
}
struct G {
    n: i128,
    a: i128,
    b: i128,
    c: i128,
    d: i128,
    dp: HashMap<i128, i128>,
}
impl G {
    fn solve(&mut self, n: i128) -> i128 {
        if n == 1 {
            return self.d;
        }
        if n == 0 {
            // return 0;
            return INF;
        }
        let dp = *self.dp.entry(n).or_insert(0);
        if dp > 0 {
            return dp;
        }
        let mut ret = n * self.d;
        ret = min(
            ret,
            self.solve(n / 2) + self.a + (n - (n / 2 * 2)) * (self.d),
        );
        ret = min(
            ret,
            self.solve((n + 1) / 2) + self.a + ((n + 1) / 2 * 2 - n) * (self.d),
        );
        ret = min(ret, self.solve(n / 3) + self.b + (n - (n / 3 * 3)) * self.d);
        ret = min(
            ret,
            self.solve((n + 2) / 3) + self.b + ((n + 2) / 3 * 3 - n) * self.d,
        );
        ret = min(ret, self.solve(n / 5) + self.c + (n - n / 5 * 5) * self.d);
        ret = min(
            ret,
            self.solve((n + 4) / 5) + self.c + ((n + 4) / 5 * 5 - n) * self.d,
        );
        *self.dp.entry(n).or_insert(0) = ret;
        ret
    }
}
