const MOD: u32 = 1_000_000_007;
const INF: i64 = std::i64::MAX/10;

fn solve() {
    let t = read!(usize);
    for i in 0..t {
        let (n,a,b,c,d) = read!(i64,i64,i64,i64,i64);
        let mut map: HashMap<i64,i64> = HashMap::new();
        let mut sum = 0;
        let ans = dfs(n,a,b,c,d,&mut map,&mut sum);
        println!("{}", ans);
    }
}

fn dfs(cur: i64, a: i64, b: i64, c: i64, d: i64, mut map: &mut HashMap<i64,i64>, mut s: &mut i64) -> i64{
    let val = *map.get(&cur).unwrap_or(&0);
    if val!=0 {
        return val;
    }
    if cur==1 {
        return d;
    }
    let mut sum = INF;
    if cur/2!=0 {
        sum = min(sum, a+dfs(cur/2,a,b,c,d,&mut map,&mut s) + d*(cur-cur/2*2));
    }
    if (cur+1)/2!=0 {
        sum = min(sum, a+dfs((cur+1)/2,a,b,c,d,&mut map,&mut s) + d*((cur+1)/2*2-cur));
    }
    if cur/3!=0{
        sum = min(sum, b+dfs(cur/3,a,b,c,d,&mut map,&mut s) + d*(cur-cur/3*3));
    }
    if (cur+2)/3!=0 {
        sum = min(sum, b+dfs((cur+2)/3,a,b,c,d,&mut map,&mut s) + d*((cur+2)/3*3-cur));
    }
    if cur/5!=0 {
        sum = min(sum, c+dfs(cur/5,a,b,c,d,&mut map,&mut s) + d*(cur-cur/5*5));
    }
    if (cur+4)/5!=0 {
        sum = min(sum, c+dfs((cur+4)/5,a,b,c,d,&mut map,&mut s) + d*((cur+4)/5*5-cur));
    }
    if d.to_string().len() + cur.to_string().len() < 15 {
        sum = min(sum, d*cur);
    }
    *map.entry(cur).or_insert(sum);
    *s += 1;
    sum
}

